// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":169,"question":"إذا صلَّى المُصلي صلاة المغرب ونسي التَّشهد الأخير فما حكمه؟","title":"حكم من نسي التشهد الآخير في الصلاة","answer":"الجواب: صلاة المغرب أو غيرها: إذا نسي التَّشهد الأخير من صلاة المغرب أو غيرها من الصَّلوات يعود إلى مجلسه ويأتي بالتَّشهد الأخير، ثم يسجد للسهو ويُسلِّم، أو يُسلِّم ثم يسجد للسهو، فإن شاء سجد للسهو قبل ذلك أو بعد ذلك، والأفضل بعد السَّلام؛ لأنه سلَّم عن نقصٍ، فإذا نسي التشهد الأخير وسلَّم يعود إلى الصلاة إذا كان الفصلُ ليس بطويلٍ، ما طال الفصل، ولو قام من مكانه، ولو خرج يرجع فيجلس ويأتي بالتشهد ثم يُسلِّم ثم يسجد للسهو، هذا هو الأفضل، وإن سجد قبل السلام فلا بأس.\nوالدليل على هذا أنَّ النبي ﷺ في بعض الصَّلوات سلَّم من ثلاثٍ وخرج، فأشار له الناسُ أنه بقيت عليه ركعةٌ، فرجع وأتمَّ الركعة وسلَّم وسجد للسهو عليه الصلاة والسلام.\nوفي حديث ذي اليدين -حديث أبي هريرة- أنه صلَّى الظهر أو العصر ركعتين وقام من مكانه إلى مكانٍ آخر، فنُبِّهَ أنه سلَّم من ثنتين، فعاد فكمَّل الصلاة وسلَّم ثم سجد للسهو، مع أنه قد قام من مكانه واستقبل غير جهة القبلة يحسب أنه أتمَّ صلاته، والنبي ﷺ ينسى كما ينسى غيرُه، يقول ﷺ: إنما أنا بشرٌ أنسى كما تنسون، فإذا نسيتُ فذكِّروني، هكذا قال عليه الصلاة والسلام.\nأما إذا طال الفصلُ يُعيد الصلاة من أولها، إذا طال الفصلُ عُرفًا؛ فإنه يُعيد الصلاة من أولها.","link":"https://binbaz.org.sa/fatwas/3707/حكم-من-نسي-التشهد-الاخير-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0164.mp3","categories":["التشهد والتسليم","سجود السهو"]},{"id":956,"question":"صلَّى الإمامُ وسها في الصلاة، ولكنه لم يسجد للسهو، وخرج الناسُ من الصلاة، فما الحكم جزاكم الله خيرًا؟","title":"ما الحكم لو سها الإمام وسلّم ولم يسجد للسهو؟","answer":"الجواب: الواجب عليه... أُمر بالسجود، الواجب عليه أن يسجد للسهو، فإذا تركه ساهيًا أو جاهلًا فلا شيء عليه...، لكن الواجب عليه أن يسجد، والواجب على المأمومين أن يُنبهونه: \"سبحان الله\"، إذا سلَّم يُسلِّمون ويُنَبِّهونه بالكلام: ترى ما سجدتَ، وعليك سهوٌ فاسجد، يُنبهونه، مثلما نبَّه الصحابةُ النبيَّ صلى الله عليه وسلم لما سلَّم من ثنتين، وسلَّم من ثلاثٍ، وزاد خامسةً، نبَّهوه بالكلام عليه الصلاة والسلام.\nفإذا سها بأن زاد ركعةً وسلَّم وجلس؛ يُنبهونه ولو بالكلام، يُسلِّمون ويُنَبِّهونه، وإن كفى: \"سبحان الله\" سبَّحوا به: \"سبحان الله\" قبل أن يُسلِّم، وإذا سلَّم سلَّموا ونبَّهوه بالكلام، وإذا ترك جاهلًا أو ناسيًا فالصلاة صحيحة.","link":"https://binbaz.org.sa/fatwas/21000/ما-الحكم-لو-سها-الامام-وسلم-ولم-يسجد-للسهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0797صلى الإمام وسهى في الصلاة ولكنه لم يسجد للسهو وخرج الناس من الصلاة فما الحكم؟ابن باز.mp3","categories":["سجود السهو"]},{"id":1012,"question":"صليتُ مع إمامٍ رباعيةً، وصلَّى بنا ثلاث ركعاتٍ، ولما سبَّحنا له لم يستجب، وأصرَّ على عمله، وبعد السلام أصرَّ قائلًا بأنه قد صلَّى أربع ركعات، وأما أنا فأنا متأكِّدٌ بأنه لم يُصلِّ سوى ثلاثٍ، فهل أكتفي بما صليتُ معه أم أُعيد الصلاة؟","title":"ما الحكم لو سها الإمام وأصَرَّ أنه مصيب؟","answer":"الجواب: إذا سلَّم الإمامُ عن نقص ركعةٍ في الرباعية أو غيرها وأنت تعلم أنه ناقصٌ تُنَبّه، تقول: سبحان الله، سبحان الله، وهو يعمل باجتهاده، يعمل بما عنده: إذا كان مُتيقِّنًا أنك غلطانٌ وأنه لم يَسْهُ فعلى ما يعتقد هو، فإذا كان يرى أنها غير زائدةٍ فعل، وإن كان يرى أنها غير ناقصةٍ فعل، وأنت عليك أن تعمل بما تعتقد: فإذا كنت تعتقد أنها ناقصةٌ تقوم إذا سلَّم وتأتي بركعةٍ، وإن طال الفصلُ تُعيد الصلاة كلها، وأما هو فصلاته صحيحة إذا كان يعتقد ذلك، وهكذا الذين معه صلاتهم صحيحة إذا وافقوه، أو ما عندهم علمٌ، ليس عندهم علمٌ بالزيادة ولا بالنقص، صلاتهم صحيحة تبعًا لإمامهم، أما أنت الذي تعتقد أنه ناقصٌ فإنَّك تقوم وتُكمل إذا سلَّم، فإن تركت ذلك وطال الفصلُ تُعيدها من أوَّلها كلها.","link":"https://binbaz.org.sa/fatwas/21064/ما-الحكم-لو-سها-الامام-واصر-انه-مصيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0860صليت مع أمام رباعية وصلى بنا ثلاث لما سبحنا له لم يستجب وبعد السلام أصرَّقائلاً بأنه صلى أربع؟.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":1167,"question":"تعلمون ما للصلاة من فضلٍ وأجرٍ ومكانةٍ، ولكن قد تطرأ عليها أمورٌ تنقص أجرها، وقد جعل الله تعالى ما يجبرها وهو سجود السَّهو، فآمل من فضيلتكم إعطاءنا تصورًا كاملًا عنه، هل هو قبل السلام أم بعده؟ وجزاكم الله خيرًا.","title":"متى يكون سجود السهو قبل السلام أو بعده؟","answer":"الجواب:\nسجود السَّهو مشروعٌ لما يقع من الإمام والمنفرد من السَّهو، وهو واجبٌ فيما يبطل عمده الصلاة، ويجوز قبل السلام وبعده، مَن سجد قبل السلام فلا بأس، ومَن سجد بعد السلام فلا بأس، الأمر فيه واسعٌ، ولكنه قبل السلام أفضل في جميع الأحوال، إلا في حالتين:\nإحداهما: إذا سلَّم عن نقص ركعةٍ أو أكثر، فإن الأفضل أن يسجد بعد السلام، كما فعل النبيُّ ﷺ في حديث ذي اليدين، وفي حديث عمران: لما سلَّم عن نقصٍ كمّل وسلَّم، ثم سجد للسهو سجدتين بعد السلام، هذا هو الأفضل.\nوالحال الثاني: إذا بنى على غالب ظنِّه، يعني: اشتبه عليه هل صلَّى ثلاثًا أم أربعًا؟ وغلب على ظنه أنها أربع، وكمّل، ولم يُنكر عليه ذلك من المأمومين؛ يسجد بعد السلام أفضل، وهكذا لو كان منفردًا وغلب على ظنه، وبنى على غالب ظنه، فإنَّ السجود بعد السلام أفضل؛ لحديث ابن مسعودٍ  في \"البخاري\": أن النبي عليه الصلاة والسلام قال: إذا شكَّ أحدُكم في صلاته فليتحرَّ الصواب، وليتم عليه، ثم ليُسلم، ثم يسجد سجدتين، فجعل السجودَ بعد السلام.\nأما في غير هاتين الحالتين فالسّجود قبل السلام أفضل، ومع ذلك لو سجد قبل السلام في الجميع أو بعد السلام في الجميع؛ فلا حرج، والحمد لله.","link":"https://binbaz.org.sa/fatwas/21216/متى-يكون-سجود-السهو-قبل-السلام-او-بعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1012متى يكون سجود السهو قبل السلام أم بعده؟.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":1546,"question":"تأخَّر المأمومُ عن قراءة الفاتحة؛ لكونه ساهيًا مثلًا، ثم ركع الإمام؟","title":"حكم مَن سَهَا عن الفاتحة حتى ركع الإمام","answer":"الجواب:\nيركع ولا شيء عليه، تسقط عنه بالسهو، وتسقط عنه بالجهل.\nس: أقصد: ثم رفع الإمام قبل أن يتم؟\nج: لا، يركع ولا يصبر، يركع ويقطعها.\nس: ولو قال: إنه يأتي بركعةٍ جديدةٍ؟\nج: لا، يقطعها ويركع مع الإمام.","link":"https://binbaz.org.sa/fatwas/21647/حكم-من-سها-عن-الفاتحة-حتى-ركع-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سهو الإمام في قراءة الفاتحة.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":1561,"question":"كبير السن الذي يقول: أصلي من الليل ما شاء الله، فأسهو كثيرًا؛ فأُسلم بعد ثلاث، بعد أربع، ما أدري كم صليتُ؟ فما حكم صلاتي؟","title":"حكم مَن يسهو كثيرًا فلا يعلم كم صلى","answer":"الجواب:\nيبني على اليقين، وإذا غلب على ظنه شيء يبني على غالب ظنه إن كَثُر معه هذا الشيء، ويسجد للسهو. فإن كان يغلب عليه ما عليه من الظن ولا عليه سجود سهو إذا غلب عليه.","link":"https://binbaz.org.sa/fatwas/21663/حكم-من-يسهو-كثيرا-فلا-يعلم-كم-صلى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من سها في صلاته فلم يعلم كم صلى.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":1579,"question":"إمام قام إلى الخامسة في الصلاة الرباعية، والمأمومون بعضهم شاكّ، وبعضهم مُتَيَقِّنٌ، فقاموا جميعًا معه؟","title":"حكم مَن قام مع الإمام لخامسة لشك أو جهل","answer":"الجواب:\nالذي شكَّ يقوم، والمتيقِّن يقول: سبحان الله، سبحان الله، يُنَبِّه ولا يقوم.\nس: وهل على المتعمد إعادة؟\nج: لا، ما عليه شيء ما دام جاهلًا، ما عليه شيء ما دام يجهل حكم الشرع.","link":"https://binbaz.org.sa/fatwas/21682/حكم-من-قام-مع-الامام-لخامسة-لشك-او-جهل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قام الإمام إلى خامسة في الرباعية فقام المأمومين بعده بعضهم شاكّ، وبعضهم متيقن.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":1673,"question":"مَن صلَّى خمس ركعات مع الإمام؟","title":"ما حكم مَن قام لركعة خامسة سها فيها الإمام؟","answer":"الجواب:\nإذا كان ما عنده خبرٌ يُتابع الإمامَ وليس عليه شيءٌ.\nس: ما يُعيد صلاته؟\nج: لا، ما يُعيد، ما دام أنه قد تابع الإمامَ فليس عليه شيءٌ، والإمام يسجد للسهو إن كان عنده شكٌّ، وإن لم يكن عنده شكٌّ فالعمدة على ما اعتقده.\nس: ومَن صلَّى معه عالمًا أنها خمس، ويدري أنه قام للخامسة؟\nج: هل هو جاهل؟\nس: لا، ما هو بجاهل، لكنه تابع.\nج: وَرَاه ما هو جاهل؟! ما يقوم إلا إنسان جاهل، وإلا ما هو بجاهل كان جلس ونبَّه وقال: سبحان الله، سبحان الله.\nس: يُعيد صلاتَه؟\nج: ما يمكن أن يكون عالمًا، إلا إنسان جَهِلَ أو سها، فالعالم لا يقوم، العالم يجلس حتى يُسلِّم الإمامُ فيُسلِّم معه، ويسجد للسهو معه.","link":"https://binbaz.org.sa/fatwas/21779/ما-حكم-من-قام-لركعة-خامسة-سها-فيها-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلى خمس ركعات مع الإمام.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":2009,"question":"يقول السائل: إمام أتى بالركعة الخامسة في صلاة الظهر فسبح المأمومون وأكمل الإمام الخامسة فاختلف المصلون، منهم: من تابع الإمام وأتى بالخامسة، ومنهم من جلس والمسبوق بركعة، ومنهم من أتى بركعة بعد سجود السهو والمسبوق بركعة، ومنهم من أتى بركعة بعد سجود السهو والتسليم، ومنهم من سلم مع الإمام بعد السجود، ولم ينكر أحد على الآخر، فما حكم صلاة كل واحد من هؤلاء؟","title":"ما يفعل المأموم لو زاد الإمام ركعة خامسة؟","answer":"الجواب:\nالواجب على المأمومين يتابعونه إذا قام إلا من عرف أنها زائدة فلا يتابع، من عرف أنها زائدة يُسَبِّح ولا يتابع، وإذا سلم سلم معه، ومن لم يعرف؛ لأنه قد يكون متأكدًا، هو قد يكون غلطانًا مَنْ سَبَّح، وقد يكون هو متأكدًا أنها ما هي خامسة، فالمأمومون يتابعونه إلا الذي عنده علم أنها خامسة لا يتابع، يجلس، فإذا سلم معه، هذا المشروع لهم، والمسبوق لا يَعَتَد بها، إذا سلم إمامه قام وقضى ما عليه إذا عرف أنها زائدة.\nس: والذي متأكد؟\nالشيخ: أما إذا لم يعرف أنها زائدة....\nس: يتابعه في سجود السهو اللي متأكد أنها هي الخامسة؟\nالشيخ: يجلس لا يقوم.\nس: ما يتابعه في سجود السهو؟\nالشيخ: يسجد معه للسهو، لكن لا يتابعه للقيام ويجلس معه للسهو؛ لأن السهو عام للجميع نقص على الجميع.","link":"https://binbaz.org.sa/fatwas/22125/ما-يفعل-الماموم-لو-زاد-الامام-ركعة-خامسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/زيادة ركعة خامسة وإكمال الإمام للصلاة.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":2053,"question":"سائلٌ يقول أنَّه كان يُصلِّي المغرب، وبعدما صلَّى ركعتين نسي الجلوس للتشهد الأوسط، ونهض وأتى بالركعة الثالثة، ثم تشهد، ثم صلَّى ركعةً رابعةً؟","title":"حكم مَن أتى برابعة لترك التشهد في المغرب","answer":"الجواب:\nهل كان ناسيًا؟\nس: يجهل الحكم.\nج: أتى بالرابعة عن ترك الجلوس؟\nس: نعم.\nج: ليس عليه شيء ما دام جاهلًا، لكن يُعَلَّم.\nس: وما حكمه إن لم يكن جاهلًا؟\nج: ما هو بقائم إلَّا جاهل.\nس: أقصد أنه إذا لم يكن جاهلًا وفعل هذا ناسيًا؟\nج: النَّاسي أشدّ وأشدّ.","link":"https://binbaz.org.sa/fatwas/22171/حكم-من-اتى-برابعة-لترك-التشهد-في-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من أتى بركعة رابعة لتركه التشهد الأوسط في المغرب.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":2144,"question":"إمام سجد للسهو بعد السلام، فماذا يلزم مَن فاتته ركعةٌ؟ هل يُسلّم مع الإمام ويسجد؟","title":"حكم المسبوق لو سجد الإمام للسهو بعد السلام","answer":"الجواب:\nلا، يُسلّم إذا قضى ما عليه ويسجد، فالمسبوق إذا قضى ما عليه يسجد للسّهو، إذا سلَّم مع الإمام سهوًا، أو سها فيما بينها، سواء سها مع إمامه، أو سها فيما انفرد به؛ يكون سجوده إذا قضى صلاته قبل أن يُسلِّم سجدتين.","link":"https://binbaz.org.sa/fatwas/22263/حكم-المسبوق-لو-سجد-الامام-للسهو-بعد-السلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إمام سجد للسهو بعد السلام فماذا يلزم من فاتته ركعة.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":2187,"question":"مأمومٌ أدرك الإمام في الركعة الثانية، فقام الإمام للخامسة دون أن يُنَبَّه، والمأموم شكّ، فعندما انتهى الإمامُ من الخامسة نُبِّه عليه، فسجد سجدتي السَّهو، فبينما هو يسجد قام المأمومُ ليقضي الركعة؟","title":"حكم مأموم فاتته ركعة وقام الإمام لخامسة","answer":"الجواب:\nيسجد للسهو بعد قضاء ما عليه، إذا لم يكن سجد مع الإمام.\nس: قبل السلام أم بعده؟\nج: يسجد قبل السلام، هذا هو الأفضل.","link":"https://binbaz.org.sa/fatwas/22310/حكم-ماموم-فاتته-ركعة-وقام-الامام-لخامسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم في قيام الإمام لخامسة والمأمومٌ أدرك الإمام في الركعة الثانية.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":2209,"question":"رجل كبَّر في صلاته منفردًا، ثم قرأ الفاتحة، وقرأ بعدها سورةً من كتاب الله  ولكنه نسي آيات منها، فقال: \"الله أكبر\" بيده ولسانه على أنه يريد الركوع، ثم تذكّر الآيات فاستمر واقفًا يُكْمِلها، فما حكم صلاته؟","title":"ما حكم مَن كَبَّر للركوع ثم رجع للقراءة؟","answer":"الجواب:\nما ركع بعد؟\nس: نعم، فالظهر ما حناه، لكنه كبَّر بيده ولسانه.\nج: الأقرب -والله أعلم- أنه ما عليه شيء؛ لأنَّه ما ركع بعد، فالركوع يكون بالفعل وليس بمجرد الكلام.\nس: إذن يُكبّر ثانيًا بعد انتهائه من الآيات؟\nج: نعم يُكبّر ويركع.\nس: ألا يسجد سجود السّهو إذا رفع يديه؟\nج: لا، رفع اليدين لا يُوجِب سجود السّهو؛ لأنه رفع بنية الركوع ثم لم يتم الركوع.","link":"https://binbaz.org.sa/fatwas/22332/ما-حكم-من-كبر-للركوع-ثم-رجع-للقراءة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/نسي الآيات فهمّ للركوع ثم تذكرها فما الحكم.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":2451,"question":"إنسان دخل صلاة رباعية وفاته ركعة والإمام جاء بخامسة؟","title":"فاتته ركعة مع الجماعة وزاد الإمام ركعة سهوًا، فهل يتابع الإمام ليتم ما فاته","answer":"الجواب:\nلا، لا يتابعه يجلس.\nس: أنا فاتتني ركعة صليت مثلًا ثلاث وفاتتني ركعة والإمام جاء بخامسة؟\nالشيخ: اجلس لا تتابعه، إذا سَلَّم تقوم تقضي الركعة اللي فاتت، لا تتابعه.","link":"https://binbaz.org.sa/fatwas/22580/فاتته-ركعة-مع-الجماعة-وزاد-الامام-ركعة-سهوا-فهل-يتابع-الامام-ليتم-ما-فاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دخل صلاة رباعية وفاته ركعة وزاد الإمام خامسة.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":3067,"question":"سجود السهو يجوز فيه الدعاء؟","title":"هل يجوز الدعاء في سجود السهو؟","answer":"الجواب: نعم، مثل سجود الصلاة يقول: سبحان ربي الأعلى، ويدعو فيه، طيب.","link":"https://binbaz.org.sa/fatwas/23227/هل-يجوز-الدعاء-في-سجود-السهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز الدعاء في سجود السهو.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":3072,"question":"أحد الإخوة يقول: إمام صلى بالناس وترك السجدة الأخيرة وسلّم ثم نبّهوه، ثم يقول: وكَبَر وسجد ثلاث سجدات وسلم، هل هذا فعل صحيح أو غير صحيح؟","title":"ما يفعل مَنْ نَسي السجدة الأخيرة بالصلاة؟","answer":"الجواب: لا، يسجد السجدة التي تركها ثم يسلم، ثم يسجد السهو سجدتين.\nالسؤال: أما يلزم أن يأتي بركعة ثانية؟\nالشيخ: ما يلزم، الصحيح ما يلزم، يسجد السجدة التي تركها، ثم يسلم ثم يسجد السجدتين، هذا هو الأفضل، ولو سجد للسهو ثم السجدة التي تركها، ثم سجد سجدة للسهو ثم سلم؛ هذا يصح؛ لأنها تأخيرها الأفضل فقط.\nالسؤال: هو الآن سجد ثلاث سجدات مع بعض... وسلم؟\nالشيخ: لا بأس، لا بد ّيتشهد بعد السجدة التي ضيّعها ثم سجدها، يأتي بالتشهد، ثم يسجد السهو قبل السلام أو بعده، وبعده أفضل.\nالسؤال: ما فعل هذا هو...؟\nالشيخ: يُعِيد الصلاة إنْ طال الفصل، وإنْ ما طال الفصل يتشهد ثم يسلّم ثم يسجد للسهو سجدتين.","link":"https://binbaz.org.sa/fatwas/23232/ما-يفعل-من-نسي-السجدة-الاخيرة-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ماذا يفعل من نسي السجدة الأخيرة في الصلاة.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":3074,"question":"الأَوْلى: سجدتا السهو تكون قبل السلام أم بعد السلام؟","title":"موضع سجود السهو قبل السلام وبعده","answer":"الجواب: يختلف، إنْ سلّم عن نقص يكون بعد السلام.\nالسؤال: يعني بعضهم يسجدوها قبل السلام؟\nالشيخ: يجزئ قبل السلام وبعد السلام.\nالسؤال: والأوْلى؟\nالشيخ: لكن إذا كان النقص يكون بعد السلام، إذا كان سلم عن ثلاث ركعات ثم نُبّه وتمّم يكون سجوده بعد السلام أو أشباه ذلك، يعني سها سهوًا سلّم فيه، هذا يكون سجوده بعد السلام.  أما إذا كان سهوٌ في داخل الصلاة يكون الأفضل قبل السلام، إن ترك التشهد الأول، مثل: شك هل هي ثلاث أو أربع ونبّهوه وكَمّل؛ يكون قبل السلام أفضل.","link":"https://binbaz.org.sa/fatwas/23234/موضع-سجود-السهو-قبل-السلام-وبعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سجود السهو قبل السلام أم بعده.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":3422,"question":"إذا طال الفصلُ، نَسِيَ السهو، وطال الفصل، هل يعيد الصلاة؟","title":"حكم مَنْ نَسِيَ سجود السهو وطال الفصل","answer":"الجواب: لا، يسجد للسهو، إذا ذكر السجود يسجد السجود.\nس: ولو طال الفصل؟\nالشيخ: ولو طال الفصل.\nس: ولو بعد يوم.\nالشيخ: الصواب، ولو طال الفصل، بعض أهل العلم يرى أنه يسقط، ولكن الأفضل والأحوط أنه يسجد، ولو طال الفصل.\nس: إذا كان معه جماعة، إمام يصلي جماعة؟\nالشيخ: ينبّههم.\nس: يعني يسقط عن من ذهب، ولم يعلم...؟\nالشيخ: نعم، وإذا نبّههم، وسجد للسهو؛ يكون احتياطه أحسن.\nس: إذا طال الفصل ما يعيد الصلاة؟\nالشيخ: لا ما يعيد الصلاة، ما يعيدها من أجل سجود السهو، لا، قال بعض أهل العلم: يسقط السهو بطول الفصل، ولكن إذا سجد للسهو ولو طال الفصل: هذا أحوط؛ لأن الرسول أمر بسجود السهو عليه الصلاة والسلام.\nس: لو كان نسي التشهد الأول ثم بعد يومين تذكر؟\nالشيخ: الأمر سهل إن شاء الله.\nس: يسجد أحسن؟\nالشيخ: إن سجد فلا بأس، إن سجد للسهو فظاهر الحديث النبي ﷺ لما نسى التشهد الأول سجد سجود السهو قبل أن يسلم عليه الصلاة والسلام.\nس: تذكرون يسجد للسهو ولو طال الفصل؟\nالشيخ: هذا هو الأفضل، والأحوط، بعض أهل العلم يرى أنه يسقط إذا طال الفصل.\nس: لكن لو أحدث، قول بعض أهل العلم: إذا أحدث، أو خرج من المسجد، أو طال الفصل؛ سقط؟\nالشيخ: هذا اجتهاد من أهل العلم.\nس: لو أحدث هل يقال: تطهرْ، ثم اسجدْ؟\nالشيخ: هذا هو الأفضل، هذا هو الأحوط؛ لأنه سجدتان باقيتان عليه.\nس: يعني هذا الحدث هذا ما يضر؟\nالشيخ: هذا أحوط.\nس: ما يسقط الحدث؟\nالشيخ: من باب الاحتياط.\nس: يعني ترون سجود السهو ما يسقط...؟\nالشيخ: من باب الاحتياط، ومن قال بسجوده هو قول قوي، من قال بالسجود بطول الفصل فهو قول قوي، لكن كَوْن النبي ﷺ أمر بالسجود وسكت يدل على أن الأولى أن يسجد للسهو متى ذكر.","link":"https://binbaz.org.sa/fatwas/23596/حكم-من-نسي-سجود-السهو-وطال-الفصل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل متفرقة في سجود السهو.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":3426,"question":"إذا سلّم الإمام عن نقص: المأموم هل يسلم معه، وهو متيقن أنه يسلّم عن نقص؟","title":"ما يفعل المأموم لو سلّم الإمام عن نقص؟","answer":"الجواب: لا، لا يسلّم، ينّبه يقول: سبحان الله، سبحان الله.\nس: إذا لم ينتبه الإمام ماذا عليه، هل يتبرع شخص ويكلمه؟\nالشيخ: لا، يَعْرِف، إذا قال الناس: سبحان الله؛ عَرَف.","link":"https://binbaz.org.sa/fatwas/23600/ما-يفعل-الماموم-لو-سلم-الامام-عن-نقص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تنبيه الإمام على النقص في الصلاة.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":3556,"question":"إذا صلى الإمام الظهر ركعتين ثم ذُكِّر... وخشي أن العامة تلبِّس عليه فقال لهم: سأصلي ركعتين وسأسجد مرتين؛ حتى ما يُلَبِّس عليهم؟","title":"حكم إمام سها وخشي التلبيس على المصلين","answer":"الجواب: يصلي ما بقي ولا يحتاج، يكفي ما فعله النبي ﷺ، يقوم ويصلي ما بقي، والحمد لله، ولا يقول شيئًا.","link":"https://binbaz.org.sa/fatwas/23738/حكم-امام-سها-وخشي-التلبيس-على-المصلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في تنبيه الإمام للمأمومين.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":4178,"question":"سائل يقول: رجل جاء والإمام قد صلى ركعة من المغرب، فصلى معه ركعة، فلما صلى الإمام الركعة الثانية سهى، فسلم من ثنتين، فقام هذا الرجل المسبوق ليأتي بما سُبق به، ثم ذُكّر الإمام فقام ليأتي بما سهى فيه، فماذا يشرع لمن فارق الإمام أن يفعل؟","title":"حكم مسبوقٍ فارق الإمام ثم عاد الإمام لسهو","answer":"الجواب: يعود مع الإمام يكمل مع الإمام، ثم يقضي بعد سلام الإمام، يعود مع الإمام يكمل الثانية ثم يقضي الثالثة، إلا أن يكون قد فارق فقد أدى ما عليه.","link":"https://binbaz.org.sa/fatwas/24435/حكم-مسبوق-فارق-الامام-ثم-عاد-الامام-لسهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ماذا يشرع لمن فارق الإمام في حال سهى الإمام.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":4568,"question":"سجود السهو قبل السلام أو بعد السلام؟","title":"متى يكون سجود السهو قبل السلام أو بعده؟","answer":"الجواب: الأفضل قبل السلام في جميع الصور إلا ما ثبت عن النبي عليه الصلاة والسلام ..... مثلما سلَّم عن نقص ركعةٍ أو أكثر يكون بعد السلام أفضل، وهكذا إذا بنى على غالب ظنِّه كما في حديث ابن مسعود: إذا بنى على غالب ظنِّه وتحرَّى الصواب يُسلِّم ثم يسجد للسهو بعد السلام.  يعني في حالتين: إحداهما: إذا سلَّم عن ..... أو أكثر، يكون الأفضل بعد السلام. والحالة الثانية: إذا بنى على غالب ظنِّه كما في حديث ابن مسعودٍ... إذا تحرى الصواب فيُتم عليه، ثم يُسلِّم، ثم يسجد سجدتين ...","link":"https://binbaz.org.sa/fatwas/24851/متى-يكون-سجود-السهو-قبل-السلام-او-بعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يكون سجود السهو قبل السلام أو بعده.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":4569,"question":"المسبوق إذا سلَّم مع إمامه ساهيًا ما يكون بعد السلام أيضًا؟","title":"ما حكم المسبوق إذا سلَّم مع إمامه ساهيًا؟","answer":"الجواب: يسجد للسهو بعد السلام أفضل، وإن سجد قبل السلام أجزأه؛ لأنه سلَّم عن نقصٍ.","link":"https://binbaz.org.sa/fatwas/24852/ما-حكم-المسبوق-اذا-سلم-مع-امامه-ساهيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ماذا يجب على المسبوق إذا سلَّم مع إمامه ساهيًا.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":4604,"question":"السجود قبل السلام أو بعده؟","title":"متى يكون سجود السهو قبل السلام ومتى بعده؟","answer":"الجواب: أفضلية، الأفضل إذا سلَّم عن نقصٍ أن يكون بعد السلام، وهكذا لو بنى على غلبة ظنِّه فبعد السلام، وما سوى ذلك فهو قبل السلام، ولو سجد بعد السلام لما أفضليته قبل السلام، أو سجد قبل السلام لما أفضليته بعد السلام؛ صحَّ ذلك ولا حرج؛ لأن الأحاديث الصحيحة تدل على هذا، فالجمع بينها هو هذا الأفضلية، فلو سجد قبل السلام في النَّقص أجزأت، لو أخَّر في التشهد الأول، أخَّره وسجد بعد السلام فلا حرج، إنما هي للأفضلية، الأفضلية أن يُراعي ما فعله النبيُّ ﷺ.\nس: ويُكبِّر؟\nج: يُكبِّر نعم، يُكبر عند السجود وعند الرفع، هكذا جاء في حديث أبي هريرة وحديث عمران.","link":"https://binbaz.org.sa/fatwas/24893/متى-يكون-سجود-السهو-قبل-السلام-ومتى-بعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يكون سجود السهو قبل السلام أو بعده.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":4605,"question":"يُكبِّر للركعة الفائتة إذا سلَّم عن ثلاثٍ من أربعٍ وأتى بالركعة يُكبِّر لها؟","title":"إذا سلَّم عن ثلاثٍ ثم أتى بالفائتة هل يُكبِّر لها؟","answer":"الجواب: ما له أصل، قد كبَّر حين قام من السجدة الثانية، يقف بنية الصلاة ويكمل، ويقف معه بنية الصلاة.","link":"https://binbaz.org.sa/fatwas/24894/اذا-سلم-عن-ثلاث-ثم-اتى-بالفاىتة-هل-يكبر-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا سلَّم عن ثلاثٍ من أربعٍ وأتى بالركعة فهل يُكبِّر للركعة الفائتة.mp3","categories":["سجود السهو","التكبير والاستفتاح"]},{"id":4772,"question":"يا شيخ متى يكون السجود قبل السلام، ومتى يكون بعد السلام؟","title":"متى يكون سجود السهو قبل السلام ومتى يكون بعده؟","answer":"السجود قبل السلام إلا في حالتين، هذا الأفضل:  حالة: إذا سلم عن نقص ركعة أو أكثر فيكمل ويسجد للسهو بعد السلام،. والحال الثانية: إذا بنى على غالب ظنه؛ تمم الصلاة وسلم ثم سجد للسهو. والبقية قبل السلام، هذا هو الأفضل.","link":"https://binbaz.org.sa/fatwas/25135/متى-يكون-سجود-السهو-قبل-السلام-ومتى-يكون-بعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يكون سجود السهو قبل السلام ومتى يكون بعده.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":4947,"question":"تفصيل أحوال سجود السهو على الوجوب؟","title":"هل تفصيل السجود قبل أو بعد السلام واجب؟","answer":"الجواب: على الأفضلية، ولو سجد قبل السلام، أو بعد السلام؛ أجزأ فيها كلها، والحمد لله. \nإنْ سجد قبل السلام، أو بعد السلام، في جميع الصور؛ أجزأ، والحمد لله.","link":"https://binbaz.org.sa/fatwas/27484/هل-تفصيل-السجود-قبل-او-بعد-السلام-واجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تفصيل السجود قبل أو بعد السلام واجب؟.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":4949,"question":"في رواية في أبي داود أنه أمر بلالًا فأقام الصلاة ثم صلى ما نقص؟","title":"هل تُقام الصلاة مجددًا لصلاة ما نقص سهوًا؟","answer":"الجواب: المشهور عنه ﷺ في الصحيحين أنه كَبّر مِن غير إقامة؟\nالطالب: ولو صحت هذه الرواية تكون شاذة؟\nالشيخ: محل نظر، والأقرب، والله أعلم، أنها ما هي بصحيحة، وأنها شاذة من بعض الرواة.","link":"https://binbaz.org.sa/fatwas/27487/هل-تقام-الصلاة-مجددا-لصلاة-ما-نقص-سهوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تُقام الصلاة مجددًا لصلاة ما نقص سهوًا؟.mp3","categories":["سجود السهو"]},{"id":5193,"question":"يقول: إذا صلَّى المُصلي صلاة المغرب ونسي التَّشهد الأخير فما حكمه؟","title":"ما حكم مَن صلَّى ونسي التَّشهد الأخير؟","answer":"الجواب: صلاة المغرب أو غيرها: إذا نسي التَّشهد الأخير من صلاة المغرب أو غيرها من الصَّلوات يعود إلى مجلسه ويأتي بالتَّشهد الأخير، ثم يسجد للسهو ويُسلِّم، أو يُسلِّم ثم يسجد للسهو، فإن شاء سجد للسهو قبل ذلك أو بعد ذلك، والأفضل بعد السَّلام؛ لأنه سلَّم عن نقصٍ، فإذا نسي التشهد الأخير وسلَّم يعود إلى الصلاة إذا كان الفصلُ ليس بطويلٍ، ما طال الفصل، ولو قام من مكانه، ولو خرج يرجع فيجلس ويأتي بالتشهد ثم يُسلِّم ثم يسجد للسهو، هذا هو الأفضل، وإن سجد قبل السلام فلا بأس. والدليل على هذا أنَّ النبي ﷺ في بعض الصَّلوات سلَّم من ثلاثٍ وخرج، فأشار له الناسُ أنه بقيت عليه ركعةٌ، فرجع وأتمَّ الركعة وسلَّم وسجد للسهو عليه الصلاة والسلام. وفي حديث ذي اليدين -حديث أبي هريرة- أنه صلَّى الظهر أو العصر ركعتين وقام من مكانه إلى مكانٍ آخر، فنُبِّهَ أنه سلَّم من ثنتين، فعاد فكمَّل الصلاة وسلَّم ثم سجد للسهو، مع أنه قد قام من مكانه واستقبل غير جهة القبلة يحسب أنه أتمَّ صلاته، والنبي ﷺ ينسى كما ينسى غيرُه، يقول ﷺ: إنما أنا بشرٌ أنسى كما تنسون، فإذا نسيتُ فذكِّروني، هكذا قال عليه الصلاة والسلام. أما إذا طال الفصلُ يُعيد الصلاة من أولها، إذا طال الفصلُ عُرفًا فإنه يُعيد الصلاة من أولها.","link":"https://binbaz.org.sa/fatwas/30135/ما-حكم-من-صلى-ونسي-التشهد-الاخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 164.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":5321,"question":"هل في السنة الراتبة سجود سهو؟","title":"ما حكم سجود السهو في السنة الراتبة؟","answer":"الجواب: السجود يكون في النفل والفرض، سجود السهو يكون في الفرض والنفل، إذا سها في النافلة سهوًا يوجب السهو مثل الفريضة، لو شك هل سجد سجدتين أو واحدة سجد الثانية وسجد السهو، ولو قام يصلي ثنتين فشك هل أتى بالثانية أو ما أتى بالثانية يأتي بالثانية ويسجد للسهو.[1]","link":"https://binbaz.org.sa/fatwas/30984/ما-حكم-سجود-السهو-في-السنة-الراتبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 041.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":5786,"question":"صلينا جماعة في مسجد، فقام الإمام للركعة الخامسة، فقال له المأمومون: سبحان الله، فجلس، ثم سلم دون السجود للسهو، فخرج المصلون على ذلك؟","title":"حكم من سها في الصلاة ولم يسجد للسهو","answer":"الجواب: هذا غلط، إذا قام الإنسان إلى الخامسة في الظهر، أو في العصر، أو في العشاء، ثم نُبه على أنها زائدة، ثم رجع، فإنه يلزمه أن يسجد للسهو قبل أن يسلم؛ لأن النبي -عليه الصلاة والسلام- كان إذا زاد على الصلاة، أو نقص؛ سجد سجدتين. وذكر العلماء أنه إذا أتى بفعل يبطل الصلاة؛ وجب عليه سجود السهو، ولا شك أن قيامه للخامسة عامدًا يبطل الصلاة، فإذا فعله ساهيًا؛ وجب عليه الرجوع، والجلوس، وقراءة التحيات، ثم سجود السهو قبل أن يسلم، وإن أخر فسجد بعد السلام؛ فلا بأس. أما ترك السجود فلا، لكن لعله تركه ساهيًا بعد ولم ينبه، ولكن الواجب عليه أن يسجد للسهو في مثل هذا، وهكذا في المغرب إذا قام إلى رابعة، أو في الفجر إذا قام إلى ثالثة، ثم نبه، أو تذكر، ورجع عليه سجود السهو أيضًا؛ جبرًا لصلاته. السؤال: لو أنه جلس في الثالثة مكان الرابعة، ثم نبه؟ الجواب:  يسجد للسهو؛ لأنه إذا جلس للثالثة فقد عزم على ترك ركعة، فإذا نبه سجد، النبي ﷺ قال للذي شك في صلاته: أثلاثًا، أم أربعًا، فليجعلها ثلاثًا، ثم يكمل صلاته، ثم يسجد للسهو، فإن كان صلى خمسًا شفعتا له صلاته، وإن كان صلى أربعا كان ترغيمًا للشيطان. السؤال: ولو نُبه بعد خروجه من المسجد؟ الجواب: يعود، ويسجد بالحاضرين.","link":"https://binbaz.org.sa/fatwas/1115/حكم-من-سها-في-الصلاة-ولم-يسجد-للسهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_122.mp3","categories":["سجود السهو"]},{"id":5790,"question":"واحد صلى مأمومًا، ولكن ما شعر بنفسه إلا والإمام سلم، فسلم، بس يقول: ما يدري هل قرأ التشهد، أم لا؟","title":"من شك في عدم قراءة التشهد وهو مأموم","answer":"الجواب:  هذا الشك بعدما سلم، وإلا شك قبل. السؤال: يقول: ما فهمت نفسي إلا وأنا مسلم مع الإمام، لكن ما أدري هل قرأت التشهد، أم لا؟ الجواب: شكه بعد السلام يعني. السؤال: يقول: ما شعرت بنفسي إلا وأنا أسلم مع الإمام؟ الجواب: إذا شك بعد السلام ما عليه شيء، الأصل أنه قرأه.","link":"https://binbaz.org.sa/fatwas/1117/من-شك-في-عدم-قراءة-التشهد-وهو-ماموم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_124.mp3","categories":["سجود السهو"]},{"id":6198,"question":"صليت إمامًا، وعند الجلوس للتشهد الأول؛ نهضت للركعة الثالثة، ولم أجلس للتشهد الأول، ولكن سبح عليّ المأمومون، وذلك قبل أن أستوي قائمًا، ورجعت، وجلست للتشهد، فهل عليّ في هذا سجود للسهود؟","title":"حكم من سها عن التشهد ورجع قبل أن يستتم قائمًا","answer":"الجواب: نعم إذا قام الإنسان إلى الثالثة، ونُبه قبل أن يستتم قائمًا؛ يرجع، وعليه سجود السهو، أما حديث: فليجلس، ولا سهو عليه فهو ضعيف لا يحتج به، لكن إذا قام، وحصل له صورة القيام؛ فإنه قد فعل ما يبطل عمده الصلاة، فوجب عليه سجود السهو، إذا انتهى من صلاته، ولم يبق إلا السلام؛ سجد سجدتين قبل أن يسلم.","link":"https://binbaz.org.sa/fatwas/1667/حكم-من-سها-عن-التشهد-ورجع-قبل-ان-يستتم-قاىما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_546.mp3","categories":["سجود السهو"]},{"id":6202,"question":"صليت إمامًا، وعند الجلوس للتشهد الأول؛ نهضت للركعة الثالثة، ولم أجلس للتشهد الأول، ولكن سبح عليّ المأمومون، وذلك قبل أن أستوي قائمًا، ورجعت، وجلست للتشهد، فهل عليّ في هذا سجود للسهود؟","title":"حكم من سها عن التشهد ورجع قبل أن يستتم قائمًا","answer":"الجواب: نعم إذا قام الإنسان إلى الثالثة، ونُبه قبل أن يستتم قائمًا؛ يرجع، وعليه سجود السهو، أما حديث: فليجلس، ولا سهو عليه فهو ضعيف لا يحتج به، لكن إذا قام، وحصل له صورة القيام؛ فإنه قد فعل ما يبطل عمده الصلاة، فوجب عليه سجود السهو، إذا انتهى من صلاته، ولم يبق إلا السلام؛ سجد سجدتين قبل أن يسلم.","link":"https://binbaz.org.sa/fatwas/1667/حكم-من-سها-عن-التشهد-ورجع-قبل-ان-يستتم-قاىما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_546.mp3","categories":["سجود السهو"]},{"id":6207,"question":"صليت إمامًا في صلاة الظهر، وفي الركعة الرابعة حدث عندي شك هل أتيت بالرابعة، أم لا؟ ونهضت لأجل أن آتي بالرابعة، وسبح المأمومون، وطبعًا جلست للتشهد، فهل عليّ سجود للسهود، ومتى أسجد؟","title":"حكم القيام إلى الخامسة سهوًا في صلاة رباعية","answer":"الجواب: إذا شك في الرابعة هل هي الرابعة، أو الثالثة، فقام ليأتي بالرابعة، فنبه؛ فإنه يجلس، ويتشهد، ويكمل، ثم يسجد للسهو قبل أن يسلم؛ لأنه حينئذ بنى حين قام، أراد البناء على اليقين، والرسول أمر من بنى على اليقين أن يسجد للسهو قبل أن يسلم، السنة أن يسجد قبل أن يسلم. أما الذي نقص ركعة، أو نقص ركعتين مثلًا فهذا الأفضل له أن يكون سجوده بعد السلام، يكمل صلاته إذا نُبه، ثم بعد ما يقرأ التحيات، والدعاء؛ يسلم، ثم بعد ذلك يسجد للسهو سجدتين، كما فعل النبي ﷺ في قصة ذي اليدين لما سلم عن ركعتين، وحديث عمران بن حصين لما سلم عن ثلاث، كمل صلاته وسلم منها، ثم سجد للسهو بعد ذلك.","link":"https://binbaz.org.sa/fatwas/1669/حكم-القيام-الى-الخامسة-سهوا-في-صلاة-رباعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_547.mp3","categories":["سجود السهو"]},{"id":6631,"question":"رجل صلى، ونسي الركوع في إحدى الركعات، ولكنه تذكره حين سجد، فماذا عليه؟","title":"حكم من نسي الركوع ثم تذكره وهو ساجد","answer":"الجواب: عليه أن يرجع فيركع، ثم يسجد سجدتين، ويسجد للسهو بعد ذلك، عليه أن يعود واقفًا، يكبر راكعًا، ثم يرفع، ثم يسجد سجدتين، ثم يتم ... فإن كان ما ذكر إلا الركعة الثانية؛ قامت الثانية مقامها، وبطلت الأولى، وهي التي ترك .. إذا كان ما ذكر إلا في الثانية. أما إن كان ذكر في السجود؛ فإنه عليه أن يرجع، فيقوم، ويكبر راكعًا، ثم يرفع، ثم يسجد إلى آخره، ويكمل صلاته، وعليه سجود السهو بعد ذلك قبل أن يسلم سجدتين، قبل أن يسلم. السؤال: ولو نسي المأموم؟ الجواب: المأموم، يعود، يركع، ويلحق إمامه.","link":"https://binbaz.org.sa/fatwas/2466/حكم-من-نسي-الركوع-ثم-تذكره-وهو-ساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_993.mp3","categories":["سجود السهو","الركوع والسجود"]},{"id":6645,"question":"رجل صلى، ونسي الركوع في إحدى الركعات، ولكنه تذكره حين سجد، فماذا عليه؟","title":"حكم من نسي الركوع ثم تذكره وهو ساجد","answer":"الجواب: عليه أن يرجع فيركع، ثم يسجد سجدتين، ويسجد للسهو بعد ذلك، عليه أن يعود واقفًا، يكبر راكعًا، ثم يرفع، ثم يسجد سجدتين، ثم يتم ... فإن كان ما ذكر إلا الركعة الثانية؛ قامت الثانية مقامها، وبطلت الأولى، وهي التي ترك .. إذا كان ما ذكر إلا في الثانية. أما إن كان ذكر في السجود؛ فإنه عليه أن يرجع، فيقوم، ويكبر راكعًا، ثم يرفع، ثم يسجد إلى آخره، ويكمل صلاته، وعليه سجود السهو بعد ذلك قبل أن يسلم سجدتين، قبل أن يسلم. السؤال: ولو نسي المأموم؟ الجواب: المأموم، يعود، يركع، ويلحق إمامه.","link":"https://binbaz.org.sa/fatwas/2466/حكم-من-نسي-الركوع-ثم-تذكره-وهو-ساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_993.mp3","categories":["سجود السهو","الركوع والسجود"]},{"id":6768,"question":"إذا زاد الإمام في الصلاة، ولم ينهه أحد، ولكن شخصًا واحدًا سبّح، فلم يلتفت إليه الإمام، ولم يسجد سجود السهو، فماذا يفعل الإمام، والمأموم؟","title":"حكم الإمام إذا زاد في الصلاة ولم ينبهه إلا واحد","answer":"الجواب: إذا زاد الإمام في الصلاة، ولم ينبهه أحد، أو نبهه واحد، ولم يرجع إليه -يعتقد أنه مصيب- أو نبهه أكثر، ويعتقد أنه مصيب؛ فلا شيء، صلاته صحيحة، وصلاتهم صحيحة، والذي يعلم أنه زائد، لا يقوم معه إذا قام إلى خامسة، في الظهر، أو في العصر، أو في العشاء، أو إلى رابعة في المغرب، أو إلى ثالثة في الفجر، أو الجمعة وهو يعلم أنه زائد، الذي يعلم أنه زائد لا يقوم، يجلس ينبهه وهو جالس، فإن رجع الإمام، وإلا انتظره، وسلم معه، والإمام ما يجوز له أن يرجع إذا كان يعتقد أنه مصيب، وأن الذي نبهه غلطان، لا يرجع.  أما إذا كان عنده تردد، ولكن نبهه واحد، ما نبهه إلا واحد؛ ما يلزمه الرجوع لواحد، يمضي؛ لأن سكوت الباقين دليل على أنه مصيب، فإذا نبهه اثنان، أو أكثر؛ رجع. السؤال: إذا غلط الإمام في شيء من صلاته، فسبح بعض المأمومين، فقام ليأتي بما ترك، فسبح آخرون، وأصبح في حيرة من أمره، فماذا يقول للمأموم، وماذا يفعل الإمام؟ الجواب: ينبه على حسب حاله إذا كان ركوعًا يقال: يَا أَيُّهَا الَّذِينَ آمَنُوا ارْكَعُوا [الحج:77] وإن كان سجودًا: وَاسْجُدْ وَاقْتَرِبْ [العلق:19] واسجدوا يأتي بشيء فَاسْجُدُوا لِلَّهِ وَاعْبُدُوا [النجم:62] ينبهه بشيء يفهم منه، وإن كان قيامًا يقول: وَقُومُوا لِلَّهِ قَانِتِينَ [البقرة:238] يعني ينبهه بآية تناسب المقام؛ حتى ينتبه الإمام.","link":"https://binbaz.org.sa/fatwas/2629/حكم-الامام-اذا-زاد-في-الصلاة-ولم-ينبهه-الا-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1125.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":6994,"question":"ما رأيكم في قول الألباني في كتابه \"كيفية صلاة النبي ﷺ\" أن وضع اليمنى على اليسرى على الصدر بعد الركوع بدعة؟ وما رأيكم في قوله: بتقديم اليدين على الركبتين عند السجود؟","title":"حكم وضع اليد اليمنى على اليسرى بعد الركوع","answer":"الجواب:\n\nهذا قد نبهناه عليه، قوله: إن وضع اليدين بعد الركوع بدعة، هذا غلط، ونبهناه عليه، وكتبنا في هذا في الصحف منذ مدة، ووضحنا أن وضع اليدين على الصدر قبل الركوع، أو بعد الركوع سنة، وقوله في صفة صلاة النبي أنه بدعة غلط منه -عفا الله عنا وعنه- ولعله يراجع ذلك؛ لأنه رجل جيد، وطيب، وطالب علم، وله نشاط كبير في الحديث -جزاه الله خيرًا- ولكن له أخطاء، وأغلاط مثل غيره، أنا، وهو، وغيرنا، كل له أغلاط، لكن هذا غلط منه -على كل حال- غلط وضع اليدين بعد الركوع، وهو قائم سنة، مثل وضعها قبل الركوع، سواء سواء.\n\nيقول وائل بن حجر : رأيت النبي ﷺ إذا كان قائمًا في الصلاة يضع يده اليمنى على كفه اليسرى، والرسغ، والساعد، هكذا السنة.\n\nوأما عند السجود: فاختلف العلماء، منهم من يرى وضع اليدين قبل، ومنهم من يرى وضع الركبتين.\n\nوالأرجح: وضع الركبتين قبل حتى لا يشبه البعير في وضع يديه؛ لأن البعير يبدأ بيديه، فالسنة أن تبدأ برجليك، لا بيديك؛ خلافًا للبعير، كما ثبت عن النبي ﷺ أنه كان إذا سجد وضع ركبتيه قبل يديه -عليه الصلاة، والسلام-.","link":"https://binbaz.org.sa/fatwas/2913/حكم-وضع-اليد-اليمنى-على-اليسرى-بعد-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1361.mp3","categories":["سجود السهو","الركوع والسجود"]},{"id":7034,"question":"إذا ترك الإمام التشهد الأول سهوًا، ثم ترك أيضًا سجود السهو، فماذا يفعل؟","title":"حكم نسيان الإمام التشهد الأول وسجود السهو","answer":"الجواب:\n\nإن ذكر بعد السلام يسجد للسهو، وإن طال الفصل؛ سقط عند جمع من أهل العلم، وإن قضاه في بيته؛ فلا بأس؛ أحسن، وأكمل.","link":"https://binbaz.org.sa/fatwas/3006/حكم-نسيان-الامام-التشهد-الاول-وسجود-السهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1414.mp3","categories":["سجود السهو"]},{"id":7037,"question":"إمام صلى صلاة العصر، وأثناء الركعة الأخيرة سجد سجدة واحدة فقط، وجلس للتشهد الأخير، وسلم، وبعد ذلك نبه من المصلين أنه لم يسجد إلا سجدة واحدة، ولم يسجد الثانية إلا الركعة الأخيرة، ثم قام وصلى بهم ركعة كاملة، وجلس للتشهد، ثم سلم، وسجد سجود السهو، هل هذه الصفة هي الصواب؟","title":"حكم من نسي السجدة الثانية من الركعة الأخيرة","answer":"الجواب:\n\nنعم هذا هو المشروع، إذا ترك السجدة، وسلم، ثم ذكر، أو نبه؛ يقوم يأتي بركعة، ثم يكمل، ثم يسلم، ثم يسجد سجدة للسهو بعد السلام أفضل.\n\nالسؤال: وإن سجد قبل السلام؟\n\nالجواب: أجزأ أجزأ، لكن الأفضل بعد السلام، إذا سلم عن نقص.\n\nالسؤال: ولو أتي بالسجدة...؟\n\nالجواب: لا، ما تجزئ نعم؛ لأنه قد سلم.\n\nالسؤال: لكن يا شيخ هو ما نقص، يعني نقول: إنه الآن صلى الظهر، وقعد في الثالثة، وقالوا له: سبحان الله، هل هو يسلم يا شيخ بعد ال...؟\n\nالجواب: لا، إذا قالوا: سبحان الله، وقام؛ يكون سجوده قبل السلام، إنما هذه إذا سلم، ثم نبهوه.","link":"https://binbaz.org.sa/fatwas/3002/حكم-من-نسي-السجدة-الثانية-من-الركعة-الاخيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1410.mp3","categories":["سجود السهو"]},{"id":7189,"question":"صلينا وراء إمام صلى الظهر ثلاث ركعات، وذكرناه بالتسبيح ولم يقم، ثم سجد سجود السهو، وسجد معه بعض المصلين، والبعض لم يسجدوا، بل قاموا وأتوا بالركعة الرابعة، وسلموا؟","title":"عدم استجابة الإمام لتسبيح المأمومين حال سهوه","answer":"الجواب:\n\nعلى من عرف أنه ناقص أن يسبح، وأن ينبه، فإن قام؛ وإلا يقومون ويكملون، أما هو يعمل باجتهاده، إذا كان يعلم أنه مصيب؛ يجلس، ويسلم.\n\nوأما إذا كان ما عنده ضبط يلزمه أن ينصاع للمسبحين به المنبهين، ويقوم ويأتي بالرابعة، ولهذا لما نبه النبيﷺ في إحدى صلاتي العشي أنه سلم من ثنتين؛ قام لما استثبت منهم، قام وأتم الصلاة، وهكذا في الحديث الثاني حديث عمران لما نبه أنه صلى ثلاثًا؛ قام وأتى بالرابعة -عليه الصلاة والسلام-. \n\nفالواجب على الإمام أنه ينصاع للمأمومين إذا سبحوا له، ويعمل بتنبيههم، إن كان ناقصًا؛ كمل، وإن كان زائدًا؛ رجع إلا إذا كان يعلم أنه مصيب هو، وأنه يتقين هذا، وأنهم مخطئون؛ فيعمل بيقينه.","link":"https://binbaz.org.sa/fatwas/3233/عدم-استجابة-الامام-لتسبيح-المامومين-حال-سهوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1575.mp3","categories":["سجود السهو","صلاة الجماعة"]},{"id":7493,"question":"هذه أيضاً رسالة موجهة لكم شخصياً، يقول مرسلها المقدم الطالب عبد الوهاب عمر المريح في معهد الجوف العلمي، يقول: سماحة الشيخ عبد العزيز بن عبد الله بن باز الرئيس العام لإدارة البحوث العلمية والإفتاء والدعوة والإرشاد الموقر، أرجو من سماحتكم الإجابة على الأسئلة بواسطة برنامج نور على الدرب، وهي: أولاً: لماذا التزم الفقهاء عدم متابعة الإمام في الركعة الزائدة، بينما الحديث المرفوع يثبت متابعة الإمام وعدم الاختلاف عليه في السهو، ومن بين ذلك ما رواه الإمامان في الصحيحين عن أبي هريرة ما يثبت متابعة الإمام في السهو حتى في الركعة الزائدة، وذلك عند قوله ﷺ: إنما جعل الإمام ليؤتم به، فإن كبر فكبروا إلى آخره، والحديث الثاني: لا تختلفوا على إمامكم نرجو من سماحتكم الإفادة عما استفسرناه تماماً؟","title":"سبب ترك متابعة الإمام في الركعة الزائدة","answer":"الجواب: قد تقرر بالنص والإجماع أن الصلوات معروفة العدد، ليس فيها زيادة ولا نقص، الظهر أربع في حق المقيم غير المسافر، والعصر كذلك، والعشاء كذلك، والمغرب ثلاث، والفجر اثنتان، والجمعة اثنتان، فهي صلاة معروفة العدد، فإذا زاد الإمام ركعة فهو إما ساهي وإما عامد، ولا يتصور أن إنسان يزيدها عمداً إلا إنساناً لا يعرف الأحكام ولا يدري ما هو فيه، وإنما الواقع أن يكون سهواً، فإذا زاد ركعة سهواً نبه، فإن انتبه ورجع وجلس فالحمد لله، وإن لم ينتبه وأصر على الزيادة، فإن الواجب على من علم الزيادة ألا يتابعه؛ لأن هذه متابعة في الخطأ، ونحن مأمورون ألا نتابع الأئمة في الخطأ، إنما الطاعة في المعروف، فالإمام نقتدي به لكن في المعروف لا في الخطأ، فالزيادة التي يزيدها الإمام سهواً تعتبر خطأ وزيادة في الصلاة الشرعية، فمن عرفها وعلم أنها خطأ لا يتابعه بل يجلس، ولا يتابعه في الخامسة في الظهر والعصر والعشاء، ولا في الرابعة في المغرب، ولا في الثالثة في الفجر والجمعة، بل يجلس.\nأما من لم يعرف أنها زائدة فإنه يتابعه عملاً بالحديث الذي ذكره السائل: إنما جعل الإمام ليؤتم به فلا تختلفوا عليه، فإذا ركع فاركعوا.. الحديث، هذا يتابعه الجاهل، الذي ما درى عن الزيادة يتابعه؛ لأن الأصل وجوب المتابعة، أما الذي عرف أنها زيادة فقد عرف أنها خطأ، فلا يتابعه في الخطأ، بل يجلس ولا يتابعه في الخطأ، ولا أعلم في هذا خلافاً بين أهل العلم وأن من عرف أن الإمام زاد ركعة فإنه ينبهه بقوله: سبحان الله! سبحان الله! فإن أجاب الإمام ورجع إلى الصواب وإلا وجب على من علم أنها زائدة أن ينتظر، وجب عليه أن يجلس ولا يتابعه في الخطأ، هذا هو المعروف عند أهل العلم، وهو الموافق للأدلة الشرعية: «إنما الطاعة في المعروف» فليس هناك أحد يطاع في المعاصي أبداً، ولا في الأخطاء، فإذا عرفت أنه قد أخطأ لا تتابعه في الخطأ.\nأما الإمام الذي أصر ولم يرجع فهو بين أمرين:\nإن كان يعتقد صحة ما فعل وأنه المصيب، وأن الذين نبهوه أخطئوا فقد أصاب وأحسن ولا بأس عليه، إذا كان يعتقد أنه مصيب، فيكمل صلاته على نيته وعلى اعتقاده، وصلاته صحيحة، والذين اعتقدوا أنه زائد صلاتهم صحيحة أيضاً، ولا حرج على الجميع، كل مأخوذ باعتقاده وما علم أنه الصحيح في نفسه.\nأما إن كان هو ليس عنده ضبط، ولكنه أصر من دون ضبط فقد غلط، ولا يجوز له ذلك؛ لأنه أصر على الخطأ، فيكون زيادته هذه الزيادة، وهو قد نبهه اثنان فأكثر من المأمومين على أنها خطأ وليس عنده ضبط، يكون خطأ، فيكون عمله غير صحيح، وتكون الزيادة هذه مبطلة لصلاته؛ لأنه تعمد زيادة ركعة غير مشروعة، فيكون زاد في الصلاة عمداً ما ليس منها، فتبطل الصلاة بذلك، وأما الذين انفردوا عنه وجلسوا لاعتقادهم أنها زائدة صلاتهم صحيحة، يكملون صلاتهم ويقرءون التحيات ويكملون صلاتهم ويسلمون، أما هو إذا كان ما عنده بصيرة ولكنه أصر على الخطأ ولم يطاوع من نبهه من الجماعة إذا كانوا اثنين فأكثر، فإن صلاته غير صحيحة هو، وعليه أن يعيدها من أولها لكونه استمر في الباطل والخطأ على غير هدى، وأما إذا كان مصيباً؛ يعتقد أنه مصيب وأن الذين نبهوه أخطئوا، فهذا مثل ما تقدم صلاته صحيحة، وهو مسئول عن اعتقاده ولا حرج عليه. نعم.\nالمقدم: لكن نبقى في السلام يا شيخ، يسلمون وهو لم يسلم؟\nالشيخ: إذا كان استمر ولم يرجع، فالأفضل لهم ينتظرونه، هذا الأفضل، وإن سلموا أجزأ، صحت؛ لأنهم معذورون بالانفراد؛ لكن إذا انتظروه يكون أحسن؛ لأنه قد يكون معذوراً، قد يكون يعتقد صواب نفسه فيكون معذوراً، فإذا انتظروه وسلموا معه يكون أحسن. نعم.","link":"https://binbaz.org.sa/fatwas/4454/سبب-ترك-متابعة-الامام-في-الركعة-الزاىدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_006/00604.mp3","categories":["سجود السهو","صلاة الجماعة"]},{"id":7495,"question":"أيضاً السؤال الأخير يقول: هل تارك صلاة الفجر وحالق اللحية يقدم للإمامة بالمسلمين في الصلوات؟","title":"حكم الصلاة خلف العصاة","answer":"الجواب: الذي لا يصلي الفجر في الجماعة عاصي، والذي يحلق لحيته عاصي، وهكذا المدخن وشارب السكر كلهم عصاة، فلا ينبغي أن يكونوا أئمة للمسلمين، ينبغي لولاة الأمور ألا يجعلوهم أئمة، لكن لو بلي بهم إنسان وصلى خلفهم صحت صلاته، لو بلي بهم إنسان وصلى خلفهم صحت صلاته، كما صلى ابن عمر وغيره من الصحابة خلف الحجاج بن يوسف ، وهو من أظلم الناس؛ سفاك للدماء؛ لأنه مسلم وإنما لديه معاصي.\nفالحاصل: أن المعصية لا تمنع الإمامة، ولكن يكون صاحبها ناقصاً في الإمامة، يحسن الصلاة خلف غيره، ويجب إبداله إذا كانت معصيته ظاهرة، يجب إبداله، على ولاة الأمور الذين لهم الشأن في الإمامة وفي النصب والعزل، عليهم أن يعزلوه وأن يلتمسوا الشخص السليم من هذه المعاصي، حسب الإمكان، لكن إن كان يترك الفجر بالكلية، لا يصلي بالكلية، هذا كافر، لا يكون إماماً نعوذ بالله، إذا كان لا يصليها بالكلية هذا كافر، لكن الظاهر: أن مراد السائل لا يصليها في الجماعة، تكاسل عنها، فهذا عاصي، وقد قال ابن مسعود : لقد رأيتنا وما يتخلف عنها إلا منافق معلوم النفاق يعني: في الجماعة.\nفالحاصل: أنه إذا ترك الجماعة؛ الفجر أو الظهر أو العصر، هذه معصية، إذا تركها من دون عذر هذه معصية، ومن كان معروفاً بهذا الشيء لا ينبغي أن يكون إماماً، بل ينبغي أن يعزل وأن يتخذ إمام أصلح منه وأنفع للمسلمين، وأبعد عن المحرمات؛ لكن مثل ما تقدم إذا بلي الإنسان بمثل هذه الأمور فإن صلاته صحيحة ولا يصلي وحده، يصلي مع الناس، ابتلي بالصلاة مع إمام يحلق، مع إمام يدخن، مع إمام قد يتكاسل عن بعض الصلوات في الجماعة فإنه يصلي خلفه، والصلاة في الجماعة مطلوبة، وهذا العاصي مضرته على نفسه، وعلى الناصحين أن يوجهوه ويرشدوه ويحذروه من مغبة هذا العمل السيئ، والله جل وعلا لطيف بعباده ، قد يوفق للتوبة بسبب نصيحة إخوانه، وقد يرتدع فيرجع إلى الصواب بسبب النصيحة والتوجيه. نعم.","link":"https://binbaz.org.sa/fatwas/4456/حكم-الصلاة-خلف-العصاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_006/00606.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7507,"question":"هذه الرسالة من المستمع من المدينة المنورة: محمد عمران، يقول: ما حكم صلاة الرجال خلف النساء أو بجانبهن في الجهة الأخرى؟","title":"حكم صلاة الرجال خلف النساء أو بجانبهن","answer":"الجواب: المشروع أن يكون الرجال أمام النساء، وأن يكون النساء خلف الرجال في المساجد وأينما صلوا، يكون النساء خلف الرجال، هذا هو المشروع، وهذا هو الواجب، لكن لو دعت ضرورة في مثل أيام الحج مواسم الحج في المسجد النبوي وفي المسجد الحرام، قد يقعن النساء عن يمين المصلين، أو عن يسارهم، أو أمامهم، فلا يضر صلاة الرجال، صلاة الرجال صحيحة، ولو كان النساء أمامهم أو عن يمينهم أو عن شمائلهم لا يضره ذلك، أما السنة والمشروع والواجب أن يكن خلف المصلين، هذه السنة. نعم.","link":"https://binbaz.org.sa/fatwas/4468/حكم-صلاة-الرجال-خلف-النساء-او-بجانبهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_008/00806.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7512,"question":"هذا سؤال من المستمع من الرياض: محمد عمران الغشام يقول: إن فيه بعض المأمومين يذهبون إلى مساعدة الإمام في تسوية الصفوف للصلاة، كأن يقول: تقدم يا فلان، وتأخر يا فلان، ورصوا الصفوف، فما حكم تسوية الصفوف من قبل المأمومين؟ أثابكم الله.","title":"حكم مساعدة بعض المأمومين للإمام في تسوية الصفوف","answer":"الجواب: لا حرج في ذلك، هذا من التعاون على البر والتقوى، الرسول ﷺ أمر برص الصفوف وتسويتها وقال: إن تسويتها من إقامة الصلاة فإذا ساعد بعض المأمومين الإمام فيمن حولهم يلاحظونهم ويأمرونهم بالاستواء والتراص، فهذا كله خير، وهذا من باب التعاون على البر والتقوى ولا نعلم به بأساً.","link":"https://binbaz.org.sa/fatwas/4476/حكم-مساعدة-بعض-المامومين-للامام-في-تسوية-الصفوف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_008/00812.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7552,"question":"هذه الرسالة من ناجي مصلح عبد الله من دولة البحرين، منطقة أمن المحرق، يقول في رسالته: إلى حضرة الأفاضل المشتركين في تقديم برنامج نور على الدرب في إذاعة الرياض، تحية الإسلام وبعد: نشكركم على برنامجكم والرد على أسئلة المستمعين، يقول: ما حكم من صلى الفرض منفرداً ثم أقيمت جماعة، هل يعيد الصلاة مع الجماعة، وإذا أعاد الصلاة مع الجماعة هل ينويها قضاءً أو نفل، أو يعيد الفرض نفسه الذي صلاه قبل الجماعة؟","title":"حكم إعادة صلاة الفرض جماعة لمن صلاها منفرداً","answer":"الجواب: يشرع لمن صلى فرداً ثم جاءت جماعة أن يصلي معهم، اغتناماً لفضل الجماعة، وتكون صلاته معهم نافلة، والأولى هي فرضه، هذا هو الصواب، ومما يدل على هذا قوله عليه الصلاة والسلام لـأبي ذر لما ذكر الأمراء الذين يؤخرون الصلاة عن وقتها قال: صل الصلاة لوقتها، فإن أدركتها معهم فصل معهم، فإنها لك نافلة، ولما دخل رجل قد صلى الناس قال عليه الصلاة والسلام: ألا رجل يتصدق على هذا فيصلي معه.\nفالحاصل: أنه إذا صلى الفرض فرداً ثم جاءت جماعة شرع له أن يصلي معهم حتى يدرك فضل الجماعة، وإن كان صلى قبل الناس يحسب أنهم قد صلوا ثم جاء الناس وجاء الإمام، فيشرع له أن يصلي معهم، وتكون فرضه الأولى، والثاني نافلة. نعم.\nالمقدم: لو كان في الأولى منفرداً؟\nالشيخ: سواء كان منفرداً أو في جماعة، إذا صلى الأولى فرضه منفرداً أو في جماعة ثم حضر جماعة أخرى فصلاته معهم نفل لا فرض؛ لأن هذا قوله ﷺ لما قيل له في منى في حجة الوداع عن شخصين أنهم لم يصليان، دعاهما، فقال: ما منعكما أن تصليا معنا؟ قالا: قد صلينا في رحالنا، قال عليه الصلاة والسلام: إذا صليتما في رحالكما ثم أدركتما الإمام ولم يصل فصليا معه، فإنها لكما نافلة ، فأمرهما أن يصليا مع الإمام إذا حضرا وهو في الصلاة، وأخبر أنها نافلة لهما، وأن صلاة الفريضة هي التي تقدمت. نعم.","link":"https://binbaz.org.sa/fatwas/4539/حكم-اعادة-صلاة-الفرض-جماعة-لمن-صلاها-منفردا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_013/01303.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7553,"question":"أيضاً يقول: هل يجوز الانتقال من جماعة في المسجد إلى جماعة أخرى، وأي الصلاة تكن هي صلاة الواجبة عليه، وأيها تكون السنة؟","title":"تعدد الجماعات في المسجد في وقت واحد","answer":"الجواب: إذا صلى مع جماعة فلا وجه لانتقاله إلى جماعة أخرى، إذا أحرم مع الجماعة ثم جاءت جماعة أخرى فإنه يكمل مع الجماعة التي أحرم فيها، ولا نرى وجهاً لانتقاله إلى الجماعة الأخرى ما دام يصلي مع جماعة، أحرم مع جماعة يصلي معهم ثم جاءت جماعة أخرى تصلي، فإنه لا ينتقل إليها بل عليها أن تصلي مع الناس، فهذه الجماعة الأخيرة تصلي مع الجماعة الأولى ولا تنفرد؛ لأن هذا اختلاف لا وجه له، وبدعة في الشرع، كونه تصلي جماعتان في المسجد أو ثلاث، هذا لا وجه له، بل الواجب أنهم إذا جاءوا والإمام الأول لم يصل صلوا معه، إذا لم يكن به مانع، أما إذا كان الإمام الأول فيه مانع، كونه مثلاً كافراً لا تصح الصلاة خلفه، هذا له وجه شرعي، لكن إذا كان الإمام ممن تصح الصلاة خلفه فإنها لا تعدد الجماعة بل يصلون جميعاً، ولا يتعدد في المسجد جماعات يعني في وقت واحد، لكن إذا صلى الجماعة الأولى وجاء ناس ما صلوا فإنهم يصلون جماعة، قول بعض السلف إنهم يصلون فراداً قول ضعيف ليس بصواب، فالصواب أنهم إذا جاءوا وقد صلى الناس يصلون جماعة لا فرادى، حرصاً على فضل الجماعة، وعملاً بالأحاديث العامة، ومن ذلك ما يروى عنه ﷺ أنه قال: صلاة الرجل مع الرجل أزكى من صلاته وحده، وصلاته مع الرجلان أزكى من صلاته مع الرجل، وما كان أكثر فهو أحب إلى الله.\nفالجماعة مطلوبة، فإذا فاته الصلاة مع الجماعة الرسمية التي هي الجماعة الأساسية في المسجد، ثم أدرك جماعة يصلون صلى معهم جماعة ولا يصلي وحده. نعم.","link":"https://binbaz.org.sa/fatwas/4540/تعدد-الجماعات-في-المسجد-في-وقت-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_013/01304.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7557,"question":"هذه مجموعة أسئلة وردتنا من مستمع للبرنامج، ولكنه لم يذكر اسمه، يقول في رسالته هذه: إذا جئت إلى المسجد فوجدت الإمام جالسًا للتشهد الأول، فهل أكبر ثم أجلس، أم أنتظر حتى يقوم؟","title":"متابعة المسبوق لإمامه","answer":"الجواب: الأفضل أن يكبر وهو واقف تكبيرة الإحرام ثم يجلس؛ لما جاء في عدة أحاديث فيها الأمر بأن يفعل المسبوق ما يفعله إمامه، وأنه لا ينتظر بل إذا أتى الإمام والإمام على حال فإنه يفعل كما يفعل الإمام؛ فإذا أتاه وهو ساجد سجد، وإذا أتاه وهو راكع ركع، وإذا أتاه وهو جالس جلس، هذا هو السنة، يقف فيكبر وهو واقف تكبيرته الأولى؛ تكبيرة الإحرام، ثم ينحط جالسًا.  المقدم: أيضًا سؤاله الآخر قريب من الأول وأنتم أجبتم عليه، يقول: إذا جئت إلى المسجد فوجدت الإمام ساجد أو سيسجد، فهل أكبر ثم أسجد معه، أم أنتظر حتى يقوم. هذا أجبتم عنه؟ الجواب: يكبر التكبيرة الأولى ثم ينحط ساجداً. نعم.","link":"https://binbaz.org.sa/fatwas/4561/متابعة-المسبوق-لامامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_014/01402.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7558,"question":"يقول في سؤاله الثالث: إذا صلى رجل وأمه أو أحد محارمه في غرفة واحدة منفردين وليسوا جماعة، فهل يجب أن يتقدم الرجل وتتأخر المرأة؟ علماً بأنهما منفردين. نريد الإجابة مصحوبة بالدليل إذا أمكن، وفقكم الله؟","title":"اصطفاف النساء خلف الرجال في الصلاة","answer":"الجواب: إذا أراد أن يصلي بالمرأة فإنها تكون خلفه لا تكون في الصف، ولو كان زوجاً وزوجة، أو مع أمه، أو أخته، أو بنته، المشروع أنها تقف خلفه؛ ولهذا لما صلى النبي ﷺ بـأم سليم كانت أم سليم خلفهم، صلى بـأنس عن يمينه وأم سليم خلفهم أم أنس ، وهكذا لما صلى بـأنس والحسن بن ضمرة صارا خلفه صفاً وصارت أم سليم خلفهما ولم تصف معهما ولا مع النبي ﷺ، فالسنة في موقف النساء خلف الرجال، ولو كانت أم الإمام أو زوجة الإمام لا تصف معه، بل تكون خلفه، هذه السنة، ولا يلزم ذلك أن يصلي جماعة، لو صلى وحده وهي وحدها فلا بأس، لكن إذا أراد أن تصلي معه في التهجد في الليل، أو الفريضة، مثلاً مريض ما يستطيع يخرج للمسجد، أو فاتته الفريضة في المسجد فصلت معه الفريضة لا بأس، أو التهجد لا بأس، يصلي بها لكن تكون خلفه لا معه. نعم.","link":"https://binbaz.org.sa/fatwas/4562/اصطفاف-النساء-خلف-الرجال-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_014/01403.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7584,"question":"يقول في رسالته فائز: هل يجوز أن يتقدم إمام بمأمومين وهو لا يجيد قراءة الفاتحة وبعض سور الصلاة جيداً، ويوجد فيهم من هو أحسن منه في القراءة؟","title":"حكم إمامة من لا يجيد القراءة","answer":"الجواب: قد ثبت عن رسول الله عليه الصلاة والسلام أنه قال: يؤم القوم أقرؤهم لكتاب الله، فإن كانوا في القراءة سواء فأعلمهم بالسنة، فإن كانوا في السنة سواء فأقدمهم هجرة، فإن كانوا في الهجرة سواء فأقدمهم سلماً يعني إسلاماً، وفي لفظ آخر: فأكبرهم سناً، فالسنة في مثل هذا أن يتقدم من هو أقرأ وأفضل على من دونه، فإذا تقدم المفضول صحت الصلاة وأجزأت إذا كان يقيم الفاتحة ويقيم الصلاة فلا بأس لكنه خالف السنة، فالأفضل والأولى أن يقدموا من هو أفضل منه ومن هو أقرأ منه إذا تفاوتوا تفاوتاً بيناً، فالسنة أن يقدم الأقرأ ثم من ذكر بعده، هذا هو السنة، ولا يقدم المفضول مع وجود الأفضل، هذا هو الأفضل إلا أن يكون إمام الحي إماماً راتب فلا بأس، أو السلطان فلا بأس. \nوالحاصل: أنه إذا كان يقيم الفاتحة ويجيدها ولا يلحن فيها لحناً يحيل المعنى فصلاته صحيحة، إذا كان يقيم الصلاة ولا ينقرها نقراً ولا يأتي فيها بما يبطلها فلا بأس، ولكن كونه يقدم في الصلاة من هو أولى حسب ما قاله النبي ﷺ، هذا هو الذي ينبغي للمسلمين أن يقدموا من قدمه الرسول ﷺ، وأن يؤخروا من أخره عليه الصلاة والسلام، هذا هو الذي ينبغي في هذه المسائل. نعم.","link":"https://binbaz.org.sa/fatwas/4637/حكم-امامة-من-لا-يجيد-القراءة ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_019/01902.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7609,"question":"السؤال الثاني عند عبد الوهاب عمر المريح من الجوف يقول: هل الصلاة مع الجماعة شرط لصحة الصلاة أم لا، نرجو ذكر الدليل إن أمكن ذلك وفقكم الله؟","title":"هل الصلاة مع الجماعة شرط لصحة الصلاة؟","answer":"الجواب: اختلف العلماء في هذه المسألة، فقال قوم: إن أداء الصلاة في جماعة شرط، وأن من صلى وحده بدون عذر بطلت صلاته. \nوقال آخرون: بل واجبة، تجب الصلاة في الجماعة، ويجب السعي إليها وأن تؤدى في المساجد، وهذا أعدل الأقوال. \nوقال قوم: أنها فرض كفاية، إذا قام بها من يكفي صار أداؤها جماعة في حق الباقين سنة.\nوقال آخرون: سنة. \nولكن الصواب من هذه الأقوال وأعدلها وأصحها قول من قال: إنها واجبة.. إن أداء الصلاة في الجماعة واجبة، وفي المساجد بالذات يجب أن تؤدى في المساجد مع المسلمين، لقول النبي صلى الله عليه وسلم: «من سمع النداء فلم يأت فلا صلاة له إلا من عذر قيل لـابن عباس: ما هو العذر؟ قال: خوف أو مرض»، خرجه ابن ماجة والحاكم وجماعة بإسناد جيد، قال الحافظ في البلوغ: على شرط مسلم ، وفي صحيح مسلم عن أبي هريرة : أن رجل أعمى قال: يا رسول الله! إنه ليس لي قائد يلائمني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له النبي ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب، فهذا أعمى ليس له قائد يلائمه، ومع هذا يقول له النبي ﷺ: أجب ولم يجد له رخصة، وفي رواية خارج مسلم قال: لا أجد لك رخصة فصرح ﷺ أن الأعمى الذي ليس له قائد يلائمه ليس له رخصة في ترك الصلاة في الجماعة في المساجد، وثبت في الصحيحين عنه ﷺ أنه هم أن يحرق على من تخلف عن صلاة الجماعة بيوتهم وقال: لقد هممت أن آمر بالصلاة فتقام، ثم آمر من يصلي بالناس، ثم أنطلق برجال معهم حزم من حطب إلى قوم -وفي لفظ: إلى رجال- لا يشهدون الصلاة، فأحرق عليهم بيوتهم فلولا أنهم فعلوا منكراً لما هم بتحريق بيوتهم، لأنه لا يهم إلا بالحق عليه الصلاة والسلام، فلو أنهم أتوا جريمة توجب هذه العقوبة لما هم بأن يتخلف عن الصلاة، ويستخلف من يصلي بالناس ثم يذهب إليهم في وقت الصلاة حتى لا يتعذر ويقول: قد صلينا، أو كذا وكذا، يأتي في وقت الصلاة حتى تكون الحجة قائمة، ويروى عنه عليه السلام أنه قال: لولا ما في البيوت من النساء والذرية لحرقتها عليهم.\nفهذا كله يدل على وجوب أداء الصلاة في جماعة، أما الشرط لا، ليس بشرط على الصحيح؛ لأنها لو كانت شرطاً لأمر الناس بالإعادة وقال: من صلى في بيته فليعد، ومن صلى في غير جماعة فليعد، فلما لم يأمر النبي بالإعادة عليه الصلاة والسلام، وإنما توعدهم وأمرهم بالحضور دل على الوجوب؛ لأن الأصل دوام الوجوب، وأصل الوعيد الدلالة على وجوب ما توعد عليه، فهذا هو الحق أنها تجب الصلاة في الجماعة في المساجد في بيوت الله، لا في بيته، بل يصلي مع الجماعة في مساجد الله، هذا هو الواجب وهذا هو الحق، والله المستعان. نعم. \nومن المصائب العظيمة تساهل كثير من الناس اليوم بالصلاة وهي عمود الإسلام، وهي أول شيء يحاسب عنه يوم القيامة، هذه الصلاة، وقد صح عنه عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح، وقال عليه الصلاة والسلام: رأس الأمر الإسلام، وعموده الصلاة، وذروة سنامه الجهاد في سبيل الله فالواجب على جميع المسلمين العناية بهذا الأمر، على النساء والرجال، فيجب على النساء المحافظة عليها في الأوقات وأن تؤدى بطمأنينة وإخلاص لله، وإقبال عليها، مع الطمأنينة الكاملة في ركوعها وسجودها وقراءتها، وفي الجلسة بين السجدتين، وفي الوقفة بعد الركوع، كل هذا يجب أن يعتنى به، وأن يكون المصلي مطمئناً سواء كان رجل أو امرأة، فهذا أمر عظيم، فيجب على الرجال والنساء العناية بهذا الأمر، وعلى الرجال أداؤها في الجماعة في مساجد الله مع إخوانه المسلمين، كما فعل الرسول ﷺ وكما فعل أصحابه رضي الله عنهم، وتنفيذاً لأمره عليه الصلاة والسلام وطاعة له ﷺ. \nومن المعلوم أن الصلاة داخل البيت فيه تشبه بالمنافقين، وفيه عصيان للرسول صلى الله عليه وسلم، وهو وسيلة إلى تركها، متى تساهل بها وصلاها في البيت فقد يغفل عنها وقد يؤخرها كثيراً، وقد يتركها بالكلية، إذ لو كانت لها أهمية لما صلاها في البيت، وقال عبد الله بن مسعود : لقد رأيتنا وما يتخلف عنها إلا منافق معلوم النفاق -يعني الصلاة في الجماعة- ولقد كان الرجل يؤتى به يهادى بين الرجلين حتى يقام في الصف، يعني: من حرص الصحابة رضي الله عنهم وأرضاهم على الصلاة في الجماعة، كان الرجل يؤتى به.. يهادى بين الرجلين -يعضدون له- حتى يقام في الصف، فهذا يدل على عناية الصحابة بالصلاة وأنها تهمهم كثيراً. \nومن المصائب أيضاً تساهل كثير من الناس بصلاة الفجر خاصة، فإنها يتساهل بها الأكثر من غيرها، مع أنهم في بيوتهم، لكن بأسباب السهر الكثير يتخلفون عن صلاة الفجر في الجماعة في المساجد، وربما أخروها إلى بعد طلوع الشمس إلى أن يذهبوا إلى أعمالهم، وهذه من المصائب العظيمة ومن المنكر العظيم. \nفيجب على المسلم أن يحذر ذلك، وأن لا يسهر سهراً يضره ويسبب تخلفه عن الصلاة في الجماعة في المساجد، ولو كان سهره في أعمال مباحة أو مستحبة كقراءة القرآن أو التهجد بالليل أو ما أشبه ذلك، لا يجوز له أن يسهر سهراً يجعله يتخلف عن صلاة الفجر في الجماعة ويتثاقل عنها، فكيف إذا كان سهره في معاصي الله، في استماع الأغاني وآلات الملاهي.","link":"https://binbaz.org.sa/fatwas/4662/هل-الصلاة-مع-الجماعة-شرط-لصحة-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_022/02203.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7610,"question":"هذا السؤال الأخير من عبد الوهاب بن عمر المريح شاركه فيه عمر سراج المفرح القرطبي من المغرب الشقيق ومحمد نايف عوض من الرياض، يقول فيه: هل تصح الصلاة خلف شارب الدخان إذا لم يوجد من يقرأ القرآن إلا هو، وكثيراً ما نرى بعض الناس يتدافعون ويقول: صل أنت، إلا صل أنت، أنا أشرب الدخان، نرجو الإفادة في ذلك وفقكم الله؟","title":"حكم الصلاة خلف الفاسق","answer":"الجواب: ينبغي أن يقدم في الإمامة أصلح الموجودين وأقرؤهم، ينبغي أن يقدم أصلحهم وأقرؤهم لقول النبي ﷺ: يؤم القوم أقرؤهم لكتاب الله، فإن كانوا في القراءة سواء فأعلمهم بالسنة، فإن كانوا في السنة سواء فأقدمهم هجرة، فإن كانوا في الهجرة سواء فأقدمهم سلماً -وفي رواية: فأكبرهم سناً فالواجب هو أن يعنى بهذا الأمر فيقدم الأفضل فالأفضل، فإن تقدم بعض العصاة كشارب الدخان، أو العاق لوالديه أو من يتهم بغير ذلك، صحت الصلاة، الصلاة تصح خلف الفاسق.. خلف العاصي على الصحيح من أقوال العلماء، ولا تصح خلف الكافر، من عرف كفره لا تصح الصلاة خلفه، أما العاصي فإنها تصح الصلاة خلفه سواء كان شارب دخان، أو عاصياً بشيء آخر كالعاق لوالديه، قاطع الرحم، من يتعاطى الربا ولا يستحله.. إلى غير ذلك، فالعصاة في أصح أقوال العلماء تصح الصلاة خلفهم، فقد صلى ابن عمر خلف الحجاج بن يوسف وكان من أفسق الناس ومن السفاكين للدماء، وصلى كثير من الصحابة خلف بعض الأمراء الفسقة، فدل ذلك على أن الصلاة صحيحة خلف الفاسق، ولكن إذا تيسر المستقيم العدل فهو الأولى وهو الذي يجب أن يقدم، وعلى المسئولين عن الإمامة أن يقدموا الأفضل فالأفضل، وأن لا يقدموا الفسقة حسب الإمكان، حسب القدرة، وإذا اجتمع قوم في مكان وقت الصلاة قدموا أفضلهم قدموا أحسنهم، وجاهدوا في ذلك، هذا هو الذي ينبغي لهم عملاً بالسنة وتعظيماً لها. نعم.","link":"https://binbaz.org.sa/fatwas/4663/حكم-الصلاة-خلف-الفاسق ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_022/02204.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7620,"question":"سؤاله الثاني يقول: صليت مع جماعة، ولكن الركعة الأولى قد فاتت علي، ولما سلم الإمام سلمت معه، ثم افتكرت أنه باقي علي ركعة قبل أن أكلم أحداً، فهل أعيد الصلاة أم أكمل الصلاة التي بدأتها مع الإمام؟","title":"حكم نسيان ركعة أو أكثر وتذكّرها بعد الصلاة","answer":"الجواب: إذا فات الإنسان بعض الركعات ثم سلم مع الإمام ناسياً؛ فإن عليه أن يقوم فيكمل، ولا يعيد الصلاة بل يكمل ما فاته ركعة أو أكثر، ثم يسجد للسهو قبل السلام أو بعد السلام، وبعد السلام هي أفضل لكونه سلم عن نقص، وتكفيه الصلاة وتجزئه والحمد لله، إذا سلم عن نقص ركعة فأكثر مع إمامه ناسياً وهو مسبوق، فإنه إذا انتبه يقوم فيأتي بالركعة التي فاتته أو الركعتين ويسجد للسهو بعد السلام، يكمل ثم يسلم ثم يسجد سجدتين للسهو بعد السلام، وإن سجدهما قبل السلام فلا بأس، هذا إذا كان ذكر قريباً، أما إن طال الفصل وتأخر ذكره لتسليمه مع إمامه فإنه يعيدها كلها، مثلاً سلم ونسي حتى طال الفصل، سلم من الظهر حتى ما ذكر إلا العصر أو في الليل، يقضيها كلها، يعيدها كلها، أما إذا ذكر في الحال في مجلسه أو بعد قيامه بقليل خطوات أو ما أشبه ذلك، هذا يكفيه إعادة الركعة؛ يعني قضاء الركعة، لأنه صلى الله عليه وسلم سلم من بعض الصلوات صلاة العصر أو الظهر، وقام ومشى ودخل بعض حجر نسائه، فنبهه ذو اليدين ، فرجع وكمل الصلاة ولم يعدها، فالذي يفعل مثل فعله صلى الله عليه وسلم ليس عليه إعادة، بل يأتي بما فاته فقط، يعني يأتي بالركعة التي فاتته أو الثنتين فإذا سلم سجد للسهو كما فعله النبي عليه الصلاة والسلام، أما إذا أطال الفصل كثيراً يعني مثلاً: ذهب عليه وقت، مثلما فاته في الظهر ولم يذكر إلا في العصر، أو ما فاته في العصر فما ذكره إلا في المغرب أو في العشاء، مثل هذا يعيدها كلها، يعني يعيدها من أولها، لأنه طال الفصل. نعم.","link":"https://binbaz.org.sa/fatwas/4673/حكم-نسيان-ركعة-او-اكثر-وتذكرها-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_024/02403.mp3","categories":["سجود السهو"]},{"id":7633,"question":"هذه الرسالة وردت من الرياض حمد محمد الرياض يقول: كنا خلف إمام تقدم بنا ليصلي، إلا أنه ارتبك في قراءة القرآن فهرب من أمامنا، هل يتقدم منا أحد أم نقطع الصلاة ونبدأها من جديد وبإمام جديد؟","title":"حكم صلاة المأمومين إذا طرأ على إمامهم ما يفسد صلاته","answer":"الجواب: الصواب أن لهم الخيار، الصواب في هذا أن لهم الخيار، إذا انفتل الإمام أو أصابه الحدث -يعني: سبقه الحدث- فهم بالخيار، إن شاءوا قدموا واحداً منهم إن كان ما قدم أحد هو، إن شاءوا قدموا أحداً وصلى بهم وبنى على الصلاة، وإن شاءوا بدءوها من أولها واستأنفوها من أولها، هم بالخيار، ولكن الأولى والأفضل أن يقدموا واحداً يكمل بهم، وأحد القريبين من الإمام يقدم ويكمل بهم الصلاة والحمد لله، هذا هو الأرجح، ولا حرج في ذلك إن شاء الله. \nالمقدم: يعني ولو كان الإمام هارباً هروب؟\nالشيخ: ولو، قد طعن عمر رضي الله عنه فاستخلف عبد الرحمن ، وصلى بهم بقية الصلاة، عبد الرحمن بن عوف . نعم.\nالمقدم: أحسنتم.","link":"https://binbaz.org.sa/fatwas/4687/حكم-صلاة-المامومين-اذا-طرا-على-امامهم-ما-يفسد-صلاته ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_025/02509.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7638,"question":"هذه الرسالة من الدكتور أحمد محمد طه طبيب بمستشفى الأمراض الصدرية بالطائف، يقول في رسالته: هناك مسجد بالمستشفى للصلاة ولكبر المستشفى ووسعها فإنه في أوقات الصلاة تتجمع فئة قليلة وتكون من بينها إمام للصلاة ويتركون المسجد، وهناك كذلك فئة غير كثيرة تصلي بالمسجد، ونحن الأطباء كنا نتجمع وراء طبيب مصري يصلي بنا في سيب من أسياب المستشفى، وبعد مدة اكتشفت ما اكتشف الأطباء أن هذا الطبيب الإمام رجل ينقل الفتنة ويتكلم في حق الناس، وينقل النميمة، فهل لي أن أستمر بالصلاة وراءه أو أن أذهب للمسجد، وبالفعل انتقلت للمسجد، وهل ملزم بإعادة الصلاة التي صليتها وراءه، أرجو الإفادة؟","title":"حكم الصلاة خلف النمام","answer":"الجواب: الواجب على من في المستشفى لمن يستطيع الصلاة في المسجد أن يصلي في المسجد الذي بقرب المستشفى سواءً كان طبيباً أو ممرضاً أو عائداً أو مريضاً يستطيع الحضور في المسجد، الواجب عليهم أن يصلوا في المسجد؛ لأن الله جل وعلا شرع عمارة المساجد لتقام فيها الصلاة كما قال سبحانه: فِي بُيُوتٍ أَذِنَ اللَّهُ أَنْ تُرْفَعَ وَيُذْكَرَ فِيهَا اسْمُهُ [النور:36]. \nفالحاصل أن الواجب على من في المستشفى الذي يقدر على الوصول إلى المسجد أن يصلي في المسجد، وفي الحديث عنه ﷺ أنه قال: من سمع النداء فلم يأت فلا صلاة له إلا من عذر خرجه ابن ماجة والدارقطني وغيرهما بإسناد جيد، وكذلك سأله أعمى قال: يا رسول الله! ليس لي قائد يلائمني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له النبي ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب فالنبي ﷺ قال له: أجب ولم يأذن له أن يصلي في بيته مع أنه كفيف وليس له قائد يلائمه، وفي رواية له: بعيد الدار فدل ذلك على وجوب أداء الصلوات في المساجد، ولا فرق بين أهل المستشفى وغيرهم، والذين يصلون في بعض المستشفى قد خالفوا السنة وتركوا الواجب. \nأما الصلاة خلف الطبيب الذي ينقل النميمة ويحصل منه بعض الأذى، هذا صلاته... صحيحة، الصلاة خلف العاصي صحيحة، ولكن ينبغي ألا يؤم الناس إلا خيارهم، يلتمس الأخيار في الإمامة، فينبغي أن يختار للإمامة أفضل الناس أقرؤهم، ثم أعلمهم بالسنة.. إلى آخره كما جاء في الحديث عنه عليه الصلاة والسلام أنه قال: يؤم القوم أقرؤهم لكتاب الله، فإن كانوا في القراءة سواء فأعلمهم بالسنة، فإن كانوا في السنة سواء فأقدمهم هجرة، فإن كانوا في الهجرة سواء فأقدمهم سلماً يعني إسلاماً. \nفالحاصل أنه يختار للإمامة الأحسن والأفضل فالأفضل، ولا يؤم الناس من هو معروف بالنميمة أو غيرها من الفسق، بل مثل هذا يجب على المسئولين أن يبدلوه وألا يقروه بل يلتمس غيره من هو أفضل منه إذا تيسر ذلك، ولو صلى خلفه الناس صحت الصلاة؛ لأنه إن صحت صلاته في نفسه صحت الصلاة خلفه، لكن ينبغي ألا يقر في الإمامة إلا من هو معروف بالعدالة والاستقامة، وأما الكافر فلا تصح الصلاة خلفه، من حكم بكفره لا تصح الصلاة خلفه، وإنما هذا في شأن الفاسق العاصي الذي ليس بكافر، وإذا لم يتيسر له إمام أصلح منه صلى خلفه، ولو صلى خلفه أيضاً لحاجة إلى ذلك أو لبعد مساجد أخرى أو ما أشبهه فلا بأس، المقصود الصلاة خلفه صحيحة، ولكن إذا تيسر من هو أولى منه وأفضل منه فليصلى خلف من هو أفضل وأحسن خروجاً من خلاف العلماء القائلين بعدم الصحة.. بعدم صحة الصلاة خلف الفاسق، وقد صلى ابن عمر رضي الله تعالى عنهما خلف الحجاج في الحج، وكان الحجاج من أفسق الناس ومن أظلمهم. نعم.","link":"https://binbaz.org.sa/fatwas/4692/حكم-الصلاة-خلف-النمام ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_026/02605.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7672,"question":"المقدم: هذه رسالة من المرسل سليم محمد الزهراني يقول في رسالته: السلام عليكم ورحمة الله وبركاته، ولفضيلة المشايخ الذين يعطون من وقتهم في سبيل إرشاد المواطنين والرد على استفساراتهم، وإلى سماحة الشيخ عبد العزيز بن باز أرجو الإجابة على هذه الأسئلة: إذا دخل رجل وأنا في صلاة نفل، واعتقد ذلك الرجل أنني أصلي الفرض، فاتخذني إماماً ليصلي معي الفرض، فما الحكم في هذا، هل أدفعه قبل البدء معي مع العلم أنه قيل لي: أنه يجب أن تفرق بين الفرض والنفل بأن ترفع صوتك في التكبيرات بالنسبة للفرض بخلاف النفل، فما رأي سماحتكم في ذلك؟","title":"حكم إمامة المتنفل بالمفترض","answer":"الجواب: قد دلت السنة عن رسول الله عليه الصلاة والسلام بأنه لا حرج في أن يكون المأموم مفترضاً والإمام متنفلاً، فإذا كنت أيها السائل تصلي نفلاً فجاء رجل وصف معك ليصلي فريضته فلا بأس ولا حرج على الصحيح، وإن كان بعض أهل العلم يرى أنه لا يصلي المتنفل إمام المفترض، لكنه قول ضعيف قول مرجوح في الدليل، والصواب: أنه لا حرج في ذلك، فإذا دخل معك فلا بأس أن تؤمه وهو يصلي فرضاً وأنت تصلي نفلاً، لا حرج في ذلك، وليس لما قلته أصل أن من أنه يرفع الصوت في تكبير الفرض ويخفض في النفل لا أصل لهذا فيما أعلم، بل التكبير فيهما سواء، يكبر في صلاته الفريضة والنافلة سواء لا نعلم في هذا شيء، إلا الإمام فإنه يكبر ويرفع صوته لأنه ينبه الناس ويبلغ الناس، أما المأموم وهو منفرد فصوته في الفريضة أو النافلة سواء لا نعلم في هذا سنة تفرق بينهما. نعم.","link":"https://binbaz.org.sa/fatwas/4871/حكم-امامة-المتنفل-بالمفترض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_039/03905.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7673,"question":"السؤل: سؤاله الثاني يقول: لي زميل ساكن معي وأعلم أنه يصلي ولكن ليس في المسجد، وهو أعلم مني في أمور الدين، وأنا أصلي في المسجد فهل علي شيء تجاه هذا أو يلحقني شيء من إثم في بقائي معه؟","title":"هل أهجر صديقي لتركه صلاة الجماعة؟","answer":"الجواب: عليك أن تنصحه في الله، وأن تعلمه أن الصلاة في الجماعة واجبة، وأنها من أهم من فرائض الصلاة، وقد صح عن النبي عليه الصلاة والسلام أنه قال: من سمع النداء فلم يأت فلا صلاة له إلا من عذر، وجاءه ﷺ رجل أعمى فقال: يا رسول الله! ليس لي قائد يلائمني إلى المسجد فهل من رخصة أن أصلي في بيتي؟ فقال له النبي صلى الله عليه وسلم: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب، فهذا الرجل الأعمى ما رخص له النبي ﷺ أن يصلي في بيته، مع أنه أعمى، وليس له قائد، وفي رواية أنه شاسع الدار-بعيد الدار- ومع هذا أمره النبي ﷺ بصلاة الجماعة.\nفيجب على المسلمين جميعاً من الرجال أن يصلوا في الجماعة، أن يصلوا في المساجد، كما فعل النبي ﷺ وأصحابه كانوا يصلون في المسجد عليه الصلاة والسلام ورضي الله عنهم، وأمر بالصلاة في المساجد، وأخبر أن من سمع النداء فلم يأت فلا صلاة له إلا من عذر كالمرض ونحوه، فعليك أن تنصح هذا، وأن تخوفه من الله عز وجل، وأن تقول له: يا أخي! اتق الله، صل في جماعة، ولا تدع صلاة الجماعة، فإن أصر على ترك الجماعة ولم يصل مع الناس، فإنه يستحق الهجر، يستحق أن تهجره وتدع صحبته؛ لئلا يعاديك فتتأخر عن الجماعة؛ لأن المعاصي مثل الجرب، أصحابها قد يعدون، يعدون الناس، وقد يسببون مرضاً انتقال مرضهم إلى غيرهم، فالذي يتظاهر بالمعصية ولا تنفع فيه النصيحة يستحق أن يهجر، ولا يتخذ جليساً ولا صاحباً، ولا تجاب له دعوة إلى وليمة ونحوها، حتى يعلم بشاعة ما فعل، وأنه جدير بأن يهجره إخوانه المستقيمون إذا أظهر المعصية ولم يبال بالناس، كالذي يتظاهر بترك الصلاة في الجماعة في المساجد، أو يتظاهر بشرب الخمر، أو يتظاهر بحلق اللحى ولا يبال ولا يقبل النصيحة، أو يتظاهر بعقوق والديه وعدم برهما، أو يتظاهر بإسبال الثياب وجرها ولا يقبل النصيحة، أو يتجاهر بالتدخين، والتدخين من أقبح الأمراض وهو شر كبير، فالواجب على من يتعاطاه التوبة إلى الله منه، كما أن السكر حرام ومنكر وكبيرة، فالتدخين فيه من الشر العظيم والبلاء الكبير ما فيه، فيجب ترك هذه المعاصي والحذر منها، ولا مانع بل يشرع هجر أهلها إذا لم يستقيموا ولم يدعوا ما هم عليه، إلا إذا كان الهجر قد يزيد في الشر، وقد يجرهم إلى شر، فينبغي تركه، وأن يعتاض عنه بالنصيحة الدائمة، والتوجيه الدائم لهؤلاء حتى يهديهم الله هم وأشباههم.","link":"https://binbaz.org.sa/fatwas/4872/هل-اهجر-صديقي-لتركه-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_039/03906.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7706,"question":"هذه رسالة وردتنا من يحيى بن أحمد الجابري من نجران يقول: إلى الرياض الإذاعة برنامج نور على الدرب، السلام عليكم ورحمة الله وبركاته وبعد: هل يجوز السحب من الصف الأول وما بعد كمل؟ وهل علي إثم إذا سحبني أحد ولم أنسحب، والرسول ﷺ يقول: لو يعلم الناس ما في النداء والصف الأول ثم لم يجدوا إلا أن يستهموا عليه لاستهموا؟ نرجو تبيين الخلاف في ذلك، وإعطائنا الرأي الراجح، وشكراً لكم؟","title":"حكم سحب رجل من الصف لمن لم يجد شخصاً آخر","answer":"الجواب: لا ينبغي السحب من الصف الأول ولا غيره، بل الذي يأتي يلتمس فرجة فيدخل فيها، فإن لم يجد صبر حتى يأتي أحد فيصف معه، وإن تقدم مع الإمام وصلى عن يمين الإمام فلا بأس، أما أنه يسحب من الصف الأول أو من الثاني أو .. لا، أما حديث: ألا دخلت معهم أو اجتررت رجلاً فهو حديث ضعيف لا يجوز التعويل عليه، ولأن السحب تصرف في الناس بغير حق. \nفالحاصل أنه لا ينبغي السحب، ولا يلزم المسحوب أن ينسحب، بل إذا أحب أن يبقى في صفه فيبقى في صفه، وليس لأحد أن يسحبه من صفه. \nثم السحب من الصف يسبب خللاً في الصف وفرجة في الصف، والنبي ﷺ أمر بسد الخلل ورص الصفوف، فالذي يدخل لا ينبغي له أن يسحب أحداً، بل يلتمس، إن وجد فرجة دخل فيها وسد الصف، فإن لم يجد تقدم مع الإمام فصف عن يمين الإمام، فإن لم يتيسر ذلك فالمشروع له الصبر حتى يأتي أحد فيصفا جميعاً، فإن فرغت الصلاة ولم يأت أحد صلى وحده بعد ذلك، والحمد لله ولا حرج عليه؛ لأن النبي عليه السلام قال: لا صلاة لمنفرد خلف الصف فلا يجوز له أن يصلي وحده خلف الصف، ولكن يصبر حتى يجد من يقف معه، وقد ذهب بعض أهل العلم أنه إذا ما وجد أحد يسوغ له أن يصلي وحده، ولكنه قول ضعيف مخالف لظاهر الأحاديث الصحيحة، فلا وجه للتعويل عليه، ولكن المؤمن يصبر لعله يجد أحداً يصف معه، فإن وجد فرجة دخل فيها، وإن تيسر له الوقوف مع الإمام وقف مع الإمام عن يمينه، هذا هو المشروع فيما نعلم. نعم.\nالمقدم: أحسنتم وأثابكم الله.","link":"https://binbaz.org.sa/fatwas/4905/حكم-سحب-رجل-من-الصف-لمن-لم-يجد-شخصا-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_029/02908.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7768,"question":"يقول: نمت قبل الظهر، فلما استيقظت وجدت أناساً في المسجد يصلون الظهر، وفكرت أنهم يصلون العصر، فدخلت معهم بنية العصر، فهل أصلي بعد انقضاء الصلاة ظهراً أم لا؟ ومتى أصليها وفقكم الله؟","title":"حكم من أدرك الجماعة ولم يكن قد صلى الفريضة السابقة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذا السائل في جوابه تفصيل: إن كان حين صلى معهم العصر ظن أنه قد صلى الظهر، وهو في اعتقاده أنه قد صلى الظهر، وظنهم يصلون العصر لأنه في اعتقاده قد صلى الظهر؛ أجزأته صلاة العصر، وعليه أن يصلي الظهر بعد ذلك؛ لأنه صلى العصر ظاناً أنه قد صلى الظهر، فتكون صلاته صحيحة.\nأما إذا كان تعمد صلاة العصر، وهو يعلم أنه عليه الظهر، فإنها لا تجزؤه، فعليه أن يعيد العصر بعدما يصلي الظهر، يصلي الظهر أولاً، ثم يصلي العصر؛ لأن الله رتب هذه بعد هذه، فالواجب أن تؤدى كما فرضها الله، فيصلي الظهر أولاً ثم يصلي العصر؛ لكن إذا صلى العصر الإنسان ناسياً يحسب أنه ليس عليه ظهر، ثم بان أن عليه الظهر بعدما صلى العصر أجزأته. نعم.","link":"https://binbaz.org.sa/fatwas/4981/حكم-من-ادرك-الجماعة-ولم-يكن-قد-صلى-الفريضة-السابقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_046/04604.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7774,"question":"في سؤاله الثاني يقول: ما هو سجود السهو ومتى يتعين وكيف أداؤه، وهل هو قبل السلام أو بعده، وكيف أعمل إذا كنت لا أدري أنا سجدت سجدتين أو سجدة أو قرأت التحيات قبل الصلاة على النبي ﷺ أو لا؟ وأغلب هذه الأحوال ظنون؟","title":"ما حكم سجود السهو ومواضعه؟","answer":"الجواب: سجود السهو لما يبطل عمده واجب، إذا فعل شيئاً أو ترك شيئاً -سهواً- يبطل عمده الصلاة وجب عليه سجود السهو؛ لأنه مكمل للصلاة، والنبي أمر بسجود السهو عليه الصلاة والسلام، تكميلاً للصلاة، فإذا مثلاً ترك تسبيحة الركوع والسجود ناسياً، وجب عليه سجود السهو على الصحيح من أقوال العلماء؛ لأن الصحيح أن هذه التسبيحات واجبة، أقلها مرة.. أقلها تسبيحة واحدة، كذلك إذا ترك التشهد الأول ناسياً وجب عليه سجود السهو في الأصح من أقوال العلماء، كما فعله النبي عليه الصلاة والسلام.\nكذلك إذا مثلاً نسي الركوع وسجد، ثم عاد وأتى بالركوع، فإنه يكمل صلاته ويسجد للسهو، كذلك إذا نسي ركعة فسلم أو ركعتين فسلم، ثم تنبه أو نبه، فإنه يكمل صلاته ويسجد للسهو أيضاً وهذا واجب، والضابط: أن كل شيء يبطل عمده الصلاة، إذا فعله ساهياً وجب عليه سجود السهو، وهو مخير، إن شاء فعله قبل السلام، وإن شاء فعله بعد السلام، سجود السهو إذا كمل التشهد والدعاء شرع له سجود السهو قبل أن يسلم، وإن أخره بعد السلام جاز ذلك، لكن الأفضل في غالب أنواع السهو أن يكون قبل السلام، الأفضل أن يكون قبل السلام، فإن سلم عن نقص ركعتين فأكثر، فإن سلم عن ثلاث في الظهر أو العصر أو العشاء أو سلم عن ثنتين في المغرب أو عن واحدة في الفجر أو في الجمعة، ثم نبه فإنه يقوم ويكمل الصلاة، ويجعل سجوده بعد السلام، كما فعله النبي ﷺ هذا هو الأفضل، إذا سلم عن نقص ..... فأكثر، ثم نبه أو تنبه وكمل صلاته، فإن سجوده يكون بعد السلام، يسلم ثم يسجد السهو سجدتين ثم يسلم مرة أخرى هذا هو الأفضل، فيما إذا كان سهوه بتسليم عن النقص، فالأفضل أن يكون بعد السلام، أما أنواع السهو الأخرى فإنه يكون قبل السلام الأصل مثل ترك التشهد الأول، ترك تسبيحة الركوع أو السجود، زاد ركعة في الصلاة ثم نبه فجلس، فإنه يكمل الصلاة ثم يسجد السهو قبل أن يسلم، وإن سجد بعد السلام فلا بأس.\nكذلك مما يكون بعد السلام إذا غلب على ظنه، إذا عمل بغالب الظن، مثل غلب على ظنه أنه كمل الصلاة، شك في ثلاث أو أربع، وغلب على ظنه أنها أربع ، فبنى على هذا وكمل الصلاة على أنها أربع، فإنه يسلم ثم يسجد للسهو بعد ذلك ثم يسلم، لأنه بنى على غالب ظنه، كذلك إذا شك هل سجد واحدة أو سجدتين يجعلها سجدة ويأتي بالسجدة الثانية، ويسجد السهو قبل السلام، مثل أن سجد سجدة، وشك هل هي الأولى أو الثانية؛ فإنه يجعلها الأولى ويأتي بالسجدة الثانية حتى يتيقن صلاته، ثم إذا كمل الصلاة يسجد السهو سجدتين، هذا هو المشروع، وإن أخر سجود السهو بعد السلام فلا حرج في ذلك، لكن في حالين الأفضل بعد السلام: إحدى الحالين إذا سلم عن نقص ركعة أو أكثر ثم نبه وتنبه، يكمل صلاته ويسجد للسهو بعد السلام، الحالة الثانية: إذا بنى على غالب ظنه، لا على اليقين، بل بنى على غالب الظن، فيجوز له على الصحيح، فإذا بنى على غالب ظنه، فإنه يكمل الصلاة ويسلم، ثم يسجد للسهو ثم يسلم، وما عدا هذا فالسجود فيه قبل السلام، هذا هو الأفضل، على ظاهر السنة.","link":"https://binbaz.org.sa/fatwas/4986/ما-حكم-سجود-السهو-ومواضعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_047/04703.mp3","categories":["سجود السهو"]},{"id":7836,"question":"يسأل أخونا ويقول: هل تجوز إمامة الشخص المعوق؟","title":"حكم إمامة المعوق","answer":"الجواب: التعويق فيه تفصيل إن كان التعويق يمنعه من الركوع والسجود فلا، فلا تجوز إمامته، يستعمل شخص صالح سليم، أما لو كان إماماً راتباً فأصابه عارض، مثل ما فعل النبي ﷺ يصلي جالساً ولا حرج في ذلك إذا كان هو الإمام الراتب هو الإمام الحي، أما إنسان ليس بإمام راتب فلا يقدم يصلي بهم وهو معوق يصلي قاعداً أو لا يركع أو لا يسجد، بل يلتمس إنسان صالح يستطيع الركوع والسجود ونحو ذلك.\nأما إذا كان المعوق لا يمنعه ذلك فيه عوق مرض في رجله في يده لكن لا يمنعه من الصلاة قائماً وراكعاً وساجداً فهذا لا بأس لا يضره هذا ولا حرج في ذلك. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/5227/حكم-امامة-المعوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_052/05208.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7865,"question":"أحمد بن محمد بن اليحيى أيضاً يقول في رسالته هذه: إذا سها الإمام في صلاة التراويح وقام بعد الركعة الثانية هل يرجع أم يكمل إلى الركعة الرابعة؟","title":"حكم من سها في الركعة الثانية وقام إلى الثالثة","answer":"الجواب: يرجع، إذا قام في التراويح قد نوى ثنتين فقام إلى الثالثة ينبه وعليه أن يرجع، كما لو قام في الثالثة في الفجر؛ لأن النبي عليه السلام قال: صلاة الليل مثنى مثنى فإذا قد نوى ثنتين كما هو العادة في التراويح وهو السنة، فإذا قام إلى الثالثة ينبه أو تنبه هو يرجع، ولو كان في أثناء القراءة ولو بعد الركوع يرجع ويجلس ويقرأ التحيات يكملها والصلاة على النبي ﷺ والدعاء ثم يسلم، ثم يقوم للتسليمة التي بعدها، كما لو فعل هذا في الفجر أو في الجمعة يرجع.","link":"https://binbaz.org.sa/fatwas/5318/حكم-من-سها-في-الركعة-الثانية-وقام-الى-الثالثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_056/05604.mp3","categories":["سجود السهو"]},{"id":7871,"question":"أيضاً يقول: صلاة الفرد لا تجوز ولكن إذا دخل المصلي ووجد الإمام راكعاً هل يجر من وسط الصف أو من يمينه أو يركع وحده على احتمال دخول آخر معه ولو بعد الركعة؟","title":"ماذا يفعل من جاء لصلاة الجماعة ولم يجد موضعًا؟","answer":"الجواب: الذي ينبغي أن لا يعجل، إذا جاء والإمام راكع يلتمس المكان المناسب فرجة يدخل فيها في طرف الصف حتى يكمل الصف ولا يعجل ولو فاتته الركعة، النبي عليه الصلاة والسلام قال: ما أدركتم فصلوا وما فاتكم فأتموا ونهى عن العجلة.\nفالداخل لا يعجل ولا يصف وحده بل يلتمس الفرجة أو يصف في طرف الصف فإن لم يجد تقدم وصف عن يمين الإمام ولا يصلي وحده، الرسول ﷺ قال: لا صلاة لمنفرد خلف الصف، ولما رأى رجل يصلي خلف الصف وحده أمره أن يعيد الصلاة.\nفالحاصل: أنه لا يجذب أحداً لأن هذا تصرف الناس بغير حق؛ ولأن هذا يفتح فرجة في الصف، إذا جره فتح فرجة في الصف والمطلوب سد الخلل وسد الفرج وعدم إيجاد فرج في الصفوف، ولكن ينتظر لعله يأتي أحد إذا كان الصف قد كمل وليس هناك محل مع الإمام ينتظر، وإلا فليتقدم فيصلي مع الإمام عن يمينه أو يقارب بين أفراد الصف حتى يجد فرجة فيدخل فيها ولا يصلي وحده. نعم.","link":"https://binbaz.org.sa/fatwas/5322/ماذا-يفعل-من-جاء-لصلاة-الجماعة-ولم-يجد-موضعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_056/05609.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7884,"question":"أيضاً يقول: رجل لا يصلي في المسجد علماً بأنه جار المسجد وهو رجل متدين ويصلي في المنزل مع أولاده، وحجة هذا الرجل أن الناس الذين يصلون في المسجد قلوبهم فيها حسد وبغض أو غيض، فما حكم ذلك وفقكم الله؟","title":"حكم ترك الجماعة في المسجد","answer":"الجواب: هذا الرجل قد أتى منكراً؛ لأن الصلاة في البيت لا تجوز، والواجب على المؤمن أن يصلي مع الناس في المساجد في الجماعة، قال النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر هذا وعيد شديد، وقال عليه الصلاة والسلام لرجل أعمى سأله: قال: يا رسول الله! هل لي من رخصة أن أصلي في بيتي؟ فقال له النبي ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب أخرجه مسلم في الصحيح، فإذا كان أعمى ليس له قائد يلائمه يقال له: (أجب) وينهى عن الصلاة في البيت، فكيف بالصحيح القادر؟! وقد هم ﷺ أن يحرق على المتخلفين بيوتهم، ويروى عنه عليه السلام أنه قال: لولا ما فيي البيوت من النساء والذرية لحرقتها عليهم.\nفالخلاصة: أن هذا لا يجوز له أن يصلي في البيت بل عليه أن يصلي مع الجماعة ولو كان في الجماعة من زعم أن فيهم حسداً أو كذا لا يمنع هذا أن يحضر معهم وأن يصلي معهم، وإذا علم إنساناً فيه شر ينصحه ويوجهه إلى الخير، أما أن يتخلف عن الجماعة فهذا لا يجوز، بل الواجب عليه أن يحضر الجماعة، وقد قال ابن مسعود رضي الله عنه في الحديث الصحيح: لقد رأيتنا وما يتخلف عنها -يعني: الصلاة في الجماعة- إلا منافق معلوم النفاق، هذا نوع من النفاق، التخلف عن صلاة الجماعة من غير عذر نوع من النفاق كما قال عبد الله بن مسعود ، فينبغي أن ينصح هذا ويوجه إلى الخير وأن يحذر من عمله السيئ وتخلفه في البيت عن صلاة الجماعة، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/5354/حكم-ترك-الجماعة-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_059/05902.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7963,"question":"أيضاً يقول: هل يجوز للمتيمم أن يصلي إمام لعدم من يصلي إمام غيره، هل ذلك يجوز أم لا؟","title":"حكم إمامة المتيمم بالمتوضئ","answer":"الجواب: يجوز أن يصلي المتيمم بالمتوضئين، إذا تيمم لعذر شرعي عن الحدث الأصغر أو الأكبر جاز أن يؤم الذين تطهروا بالماء لا حرج في ذلك ولا بأس، ولو وجد من يصلح الإمامة، إذا كان صالحاً للإمامة وأمهم فلا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/5484/حكم-امامة-المتيمم-بالمتوضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_069/06905.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7995,"question":"يقول: إذا أدرك المصلي الإمام في الركعة الثانية أو الثالثة فأي الركعات يأتي بها بعد السلام؟","title":"ما يفعله من أدرك الإمام في الركعة الثانية أو الثالثة","answer":"الجواب: إذا أدرك الإمام في أثناء الصلاة فالذي يدركه هو أول صلاته على الراجح، وما يقضيه هو آخرها، الذي يقضي هو آخرها، والذي يدرك مع الإمام هو أولها، حتى لا تتنافى الصلاة ولا تختلف، فإذا صلى.. أدرك الإمام وقد صلى ركعتين، فالركعتان اللتان أدرك هما أول صلاته، واللتان يقضيهما من الظهر أو العصر أو العشاء هما آخر صلاته، وهكذا الفجر وهكذا المغرب، ما أدركه مع الإمام هو أولها، يقرأ فيه الفاتحة وما تيسر معها، وما يقضيه هو آخرها، هذا هو الأرجح، نعم؛ لقول النبي ﷺ: إذا أتيتم الصلاة فأتوها وأنتم تمشون وعليكم السكينة والوقار، فما أدركتم فصلوا وما فاتكم فأتموا وفي اللفظ الآخر: فاقضوا، معنى اقضوا أتموا يعني، القضاء بمعنى التمام، هذا هو الحجة في هذا الباب؛ ولأن هذا هو الذي يليق بالصلاة ويتناسب معها، أن ما أدرك هو أولها وما يقضيه هو آخرها. نعم.\nالمقدم: أيضاً يقول: إذا أدرك المصلي الإمام .. هو فعلاً أتى بالسؤال وهو الإجابة التي .. يقول: إذا أدرك المصلي الإمام في الركعة الثانية أو الثالثة فأي الركعات يأتي بها بعد السلام، هل هي تلك الركعات الأولى التي فاتته -وهذا أجبتم عليه-.\nالشيخ: أجبنا. نعم.\nالمقدم: يقول: وهل الصورة واحدة في جميع الفرائض، أي: هل من فاتته الركعة الأولى أو الثانية كمن فاتته الثالثة التي يجلس فيها ويقرأ بالتشهد؟\nالشيخ: نعم، الطريق واحد نعم.\nالمقدم: يقول: إن هذا التبس عليه كثيراً وهو يريد أن يقف على الحقيقة في ذلك؟\nالشيخ: هذا هو الصواب. نعم.","link":"https://binbaz.org.sa/fatwas/5564/ما-يفعله-من-ادرك-الامام-في-الركعة-الثانية-او-الثالثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_074/07406.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":7997,"question":"من عيسى بن علي الموسى الرياض يقول: السلام عليكم ورحمة الله وبركاته وبعد: سماحة الشيخ عبد العزيز بن عبد الله بن باز! تحية إكرام لكم.وبعد:أريد أن أعرض سؤالي هذا وهو يتعلق بالصلاة، أنا دخلت والإمام راكع في الهواء، ثم كبرت تكبيرة الإحرام والإمام راكع، فرفع قبل أن أركع معه، هل أدركت الصلاة أم لا وفقكم الله؟","title":"بماذا تدرك الركعة","answer":"الجواب: إذا دخل الإنسان والإمام راكع ثم كبر تكبيرة الإحرام ثم رفع الإمام قبل أن يهوي للركوع، قبل أن يستوي راكعاً، فإنه قد فاتته الركعة لا يدركها، إنما يدركها إذا استوى راكعاً قبل أن يرفع، يعني: إذا انحدر راكعاً قبل أن يرفع إمامه يكون أدركها ولو ما سبح إلا بعد ذلك، أما إذا كبر للإحرام ثم رفع الإمام قبل أن يستوي راكعاً فإنه يعتبر غير مدرك لهذه الركعة بل يقضيها. نعم.\nالمقدم: لكن في هذه الحالة ألم يدخل في الصلاة مع ... ؟\nالشيخ: دخل في الصلاة لكن ما ركع، فاته الركوع، فاته الركوع. نعم.","link":"https://binbaz.org.sa/fatwas/5566/بماذا-تدرك-الركعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_074/07408.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8050,"question":"يقول: أتأخر في الصباح من صلاة الصبح، وأصليها فائت؛ وذلك بسبب النهوض من النوم متأخراً، وأنا لست متعمداً، ولا أحس بنفسي إلا والوقت فائت ما حكم ذلك؟","title":"ضرورة اتخاذ الأسباب المعينة على أداء الصلاة في جماعة","answer":"الجواب: الواجب على المؤمن أن يتخذ الأسباب، التي تعينه على أداء الصلاة في الوقت، وليس له التساهل حتى يفوت الوقت، الواجب عليك أيها السائل! أن تضع الساعة تنبهك وقت الصلاة، إذا لم يكن عندك منبه من زوجة جيدة أو غيرها، تضع ساعة حتى تستعين بها على الوقت، أما التساهل في هذا فلا يجوز، وأنت آثم بهذا التساهل. نعم.\nالمقدم: أحسنتم أثابكم الله!","link":"https://binbaz.org.sa/fatwas/5847/ضرورة-اتخاذ-الاسباب-المعينة-على-اداء-الصلاة-في-جماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_081/08113.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8053,"question":"يقول السائل علاء الدين يوسف إبراهيم من المديمر بالسودان: السلام عليكم ورحمة الله وبركاته، وبعد: تحياتي لك مقدم البرنامج وإلى برنامجنا، بل مدرسة الملايين نور على الدرب، وإنني لجد معجب به، وأقترح عليكم أن تزيدوا من زمن البرنامج، وأرجو أن تطرحوا سؤالي هذا على أصحاب الفضيلة المشايخ: إني كنت أصلي في الشفع، بعد الركعة الثانية نهضت واقفاً سهواً، علماً بأنني لم أجلس، فأتممت أربع ركعات، ثم سجدت سهو قبل السلام، هل كان هذا صحيح، أم كان علي أن أعيدها أرشدوني إلى الصواب وفقكم الله؟","title":"حكم من ترك التشهد الأوسط سهواً","answer":"الجواب: هذا الذي فعلته أيها السائل هو الموافق للسنة، فقد ثبت عن النبي ﷺ: أنه في إحدى صلاتي العشي الظهر أو العصر، قام إلى الثالثة ولم يجلس في التشهد الأول، بل قام إلى الثالثة، وقام الناس معه، فلما فرغ من الصلاة وانتظر الناس تسليمه، كبر وسجد سجدتين للسهو ثم سلم، بدلاً من الجلسة التي تركها وهي جلسة التشهد الأول، هذا هو المشروع إذا قام الإنسان ساهياً من التشهد الأول، ولم يجلس في الظهر، أو في العصر، أو في المغرب، أو في العشاء، فإنه لا يرجع بل يستمر إذا قام واستتم قائم يستمر، هذا هو الأفضل له لا يرجع، يستمر في صلاته، فإذا فرغ من صلاته وحصل وقت التسليم، كبر وسجد سجدتين مثل سجوده في الصلاة سواءً بسواء، ثم يسلم بعد ذلك، ويقول في سجود السهو مثل ما يقول في سجود الصلاة: سبحان ربي الأعلى، سبحان ربي الأعلى، سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، ويدعو بما أحب من الدعوات الطيبة ثم يسلم، والمقصود أن سجود الصلاة، سجود السهو، سجود التلاوة، سجود الشكر يقال فيها مثل ما يقال في سجود الصلاة، من التسبيح والدعاء، هذا هو المشروع. نعم.","link":"https://binbaz.org.sa/fatwas/5854/حكم-من-ترك-التشهد-الاوسط-سهوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_082/08208.mp3","categories":["سجود السهو"]},{"id":8122,"question":"سؤاله الثالث سؤال الأخ الذي رمز لنفسه بـ (م) فقط، يقول: أحياناً يغيب الإمام ويتقدم بنا رجال لا يعرفون القراءة، وإنما هم يحفظون بعض السور، وأنا متأكد أنني أقرؤهم، حيث أنني أحفظ عدداً من الأجزاء يقارب ستة، ولكنني أخجل من التقدم وأرتعش، فهل على المصلين أو علي ذنب إذا تقدم بنا رجل، وفي المأمومين من هو أقرأ منه؟","title":"حكم إمامة غير الأقرأ مع وجود الأقرأ","answer":"الجواب: لا حرج إن شاء الله ليس فيه شيء، لكن ينبغي للمأمومين أن ينظروا ويتأملوا إذا عرفوا واحداً هو أقرؤهم يقدمونه، أما لو تقدم واحد وصلى بهم وقراءته مستقيمة في الفاتحة فلا يضر ذلك، لكن من حيث السنة ينظرون ويتأملون، فإذا عرفوا أن واحداً من الموجودين هو أقرؤهم قدموه، إذا كان عدلاً طيباً مستور الحال، وأما إذا تقدم من لا يحسن الفاتحة ولا يجيد قراءتها، بل يلحن بها لحناً يحيل المعنى، فإنه يعلم إن اعتدل وإلا يعزل عن الصلاة، ويتقدم من يجيد القراءة حتى يصلي بالناس، وأما كونك أنت تحرج لا حرج عليك إذا لم تقدم، ولاسيما إذا كان تصيبك رعشة واضطراب فلا يتقدم، يتقدم غيرك من الذين عندهم الثبات، وعندهم الاعتدال والسلامة. نعم.","link":"https://binbaz.org.sa/fatwas/5923/حكم-امامة-غير-الاقرا-مع-وجود-الاقرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_087/08709.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8136,"question":"أيضاً من الرياض وردتنا رسالة من راشد مرشد أحمد، يقول فيها: صلينا مع إمام في أحد الأيام، فنسي الإمام وقرأ الفاتحة في الركعة الثالثة، وهي يسر فيها كما تعلمون، وسبح المأمون لكن الإمام لم يسجد للسهو، ما حكم التسبيح؟ وما حكم عدم سجود الإمام؟","title":"حكم سجود السهو على من جهر في الصلاة السرية","answer":"الجواب: السنة السر في الثالثة والرابعة، في العشاء، والثالثة المغرب، سنة، كونه يسر في الثالثة في المغرب والثالثة والرابعة في العشاء هذا سنة، فلو جهر لا يضر، لو جهر لا يضر؛ لأن النبي كان يسمعهم الآية أحياناً في السرية عليه الصلاة والسلام، فالأفضل للإمام أنه لا يجهر، بل يسر كما فعل النبي صلى الله عليه وسلم، فلو جهر ونبهه المأموم فلا بأس، إذا نبهه المأموم حتى يأخذ بالسنة وينتبه للسنة هذا لا بأس، ولا يلزمه السجود؛ لأن الجهر والإخفات سنتان، والسجود إنما يلزم فيما إذا فعل ما يبطل عمده الصلاة، فإذا كان عمده يبطل الصلاة وجب فيه سجود السهو، كما لو زاد سجدة، أو زاد ركوع، أو زاد قياماً، هذا ينبه وإذا تعمد يبطل الصلاة، وإذا كان ما تعمد يسجد السهو، أما الجهر في الثالثة في المغرب والثالثة والرابعة في العشاء فهذا لا يوجب سجود السهو، ولكن تنبيهه حسن، كون المأموم ينبهه حتى ينتبه لهذه السنة. هذا مشروع، وإن سجد للسهو فهذا حسن، ولكن لا يلزمه؛ لأن الجهر ليس بمحرم.\nالمقدم: وفي هذه الحالة يقولون مثلاً: سبحان الله.\nالشيخ: سبحان الله نعم حتى ينتبه للسنة.","link":"https://binbaz.org.sa/fatwas/5936/حكم-سجود-السهو-على-من-جهر-في-الصلاة-السرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_088/08807.mp3","categories":["سجود السهو"]},{"id":8148,"question":"أيضاً هذا سؤال وردنا من أحد السادة المستمعين (ن. م. ق) من الرياض يقول: كثير من الناس ينامون طوال أيام رمضان في النهار حتى تفوتهم كثير من أوقات الصلاة مع الجماعة، فما موقف الإسلام من هؤلاء الصوام؟","title":"نصيحة لمن ينام عن صلاة الجماعة في نهار رمضان","answer":"الجواب: هؤلاء قد فرطوا وتساهلوا، والواجب عليهم أن يهتموا بالصلاة، فالصلاة أعظم من الصوم، الصلاة هي الركن الأول من أركان الإسلام بعد الشهادتين، هي أعظم الأركان وأهمها بعد الشهادتين، وهي عمود الإسلام، وهي أعظم وأكبر شأناً من الصوم، فالواجب أن يهتم بها وأن يحرص المؤمن على أدائها في وقتها في الجماعة حرصاً تاماً، وإذا نام في النهار أو في الليل فينبغي أن يكون عنده موقظ من أهله ينبهونه أو الساعة يركبها على وقت الصلاة، حتى إذا نبهته يقوم، ولا يجوز له التفريط إذا كان عنده والده أو والد أو زوجة جيدة توقظه فالحمد لله، وإلا وجب أن يشتري ساعة ويجعلها عند رأسه، يركبها على وقت الصلاة في الليل والنهار، ولا يجوز له التساهل في هذا، ينام حتى يضيع صلاة الظهر أو صلاة العصر، هذا لا يجوز، ثم إنه لا يجوز أن يضيع صلاة الفجر بسبب التساهل والنوم، لا. بل يجب عليه أن يهتم بهذا الأمر وأن يصلي مع الناس في الأوقات أوقات الصلاة، وأن يعمل ما يعينه على ذلك من منبهين من أهله أو ساعة عند رأسه. نعم.","link":"https://binbaz.org.sa/fatwas/5950/نصيحة-لمن-ينام-عن-صلاة-الجماعة-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_090/09002.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8157,"question":"نبدأ أولاً برسالة سعد سعود الهاشل من الظهران حيث يقول: إذا حضر شخص لصلاة العشاء ووجد الجماعة يصلون فأحرم معهم بالصلاة، فتبين أنهم في التراويح، فما حكم صلاته هذه؟","title":"جواز صلاة المفترض خلف المتنفل","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: إذا أحرم الإنسان مع الناس في ليالي رمضان يظنهم في الفريضة ثم ظهر أنهم في التراويح؛ فإنه يصلي معهم يستمر، فإن سلم الإمام في التراويح يقوم ويكمل صلاته ولا بأس؛ لأنه على الصحيح يجوز أن يصلي المفترض خلف المتنفل، وقد صلى معاذ  بأصحابه العشاء وهو متنفل وهم فارضون، كان يصلي مع النبي ﷺ العشاء فرضه ثم يأتي ويصلي بأصحابه العشاء وهو متنفل وهم مفترضون، والنبي ﷺ صلى بأصحابه صلاة الخوف الصلاة الأولى فرضاً وصلى بالطائفة الثانية وهو متنفل عليه الصلاة والسلام وهم مفترضون فلا حرج، فإذا وجدهم يصلون التراويح صلى معهم بنية فرضه، ثم إذا سلم الإمام قام وكمل صلاته والحمد لله. نعم، هذا هو الصواب. نعم.","link":"https://binbaz.org.sa/fatwas/5949/جواز-صلاة-المفترض-خلف-المتنفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_090/09001.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8180,"question":"أيهما الصحيح أن أصلي خلف إمام يحلق لحيته أم خلف إمام يشرب الدخان ولماذا، أفيدونا أفادكم الله؟","title":"حكم الصلاة خلف حليق اللحية أو المدخن، وأيهما أولى؟","answer":"الجواب: إذا تيسر لك أن لا تصلي خلف هذا ولا خلف هذا فهو أولى لا تصل خلف المدخن ولا خلف الحليق، إذا تيسر لك إمام آخر في مسجد آخر لأن هذا أسلم لصلاتك وأسلم لدينك، ولكن الحليق إثمه أظهر لأنها معصية ظاهرة والمدخن قد تختفي معصيته قد يكون هناك أسباب تخفيها من التنظف والتطيب حتى لا يظهر عليه ريح الدخان، أما اللحية فهي معصية ظاهرة ومجاهرة بما حرم الله عز وجل فإثمه أكثر وأكبر وشره أعظم وإن كان كلاهما محرماً هذا وهذا؛ التدخين محرم وفيه مضار كثيرة ولكن صاحبه قد يختفي به، أما حلق اللحية فلا حيلة في الاختفاء فيها لأنها معصية ظاهرة وتشبه بالمشركين وبالنساء فيجب الحذر من هذا ومن هذا جميعاً.\nوالواجب على المسئولين عن المساجد أن لا يولوا من كان بهذه الصفة وأن يختاروا للإمامة أهل الاستقامة الذين لا يتظاهرون بالمعصية وذلك بإعفاء اللحية وبالبعد عن التدخين وهكذا غير هذا من المعاصي الظاهرة. نعم.\nنسأل الله للجميع الهداية والتوفيق. نعم.\nالمقدم: الواقع الإمام -الشيخ عبد العزيز - كثيراً ما تنصحون بأن يكون الإمام على ما هو كذا وكذا من الصفات وكثير من إخواننا أصبحوا يشتكون من هذا الموضوع فيقولون: أصبح يؤمنا أناس كانوا معروفين بأنهم من القبوريين وآخرون يشكون من أئمة يعرفون أنهم من فرقة كذا وكذا من تلك الفرق التي اختلفت في الأسماء والصفات كـالأشاعرة مثلاً وهلم جراً، يشرحون كثيراً من هذه الأمور كلمة حول هذا لو تكرمتم سماحة الشيخ؟\nالشيخ: الواجب على وزارة الحج والأوقاف والمسئولين فيها أن يخافوا الله عز وجل وأن يحذروا التساهل في هذا الأمر وأن يبذلوا قصارى جهدهم في اختيار الأئمة وأن لا يولى إلا المعروف بالعقيدة الصحيحة السلفية وأن لا يولى إلا من هو بالمظهر الشرعي قد أعفى لحيته وترك الإسبال حتى يكونوا أبرءوا الذمة هذا هو الواجب عليهم الواجب على ولاة الأمور ومنهم وزارة الحج والأوقاف والمسئولون فيها الواجب عليهم أن يتحروا في الأئمة وهكذا المؤذنون ولكن الإمام أعظم فيجب عليهم أن يتحروا في أن لا يولوا إلا من هو صالح للإمامة في عقيدته وفي مظهره الشرعي والعقيدة أهم وأعظم فالواجب على المسئولين في الأوقاف أن يعنوا بهذا الأمر وأن يتقوا الله وأن يتعاونوا مع المحاكم ومع الرئاسة العامة للبحوث العلمية والإفتاء ومع الهيئة ومع كل من يظنون فيه الخير أن يختار لهم الإمام وأن يعينهم وأن يدلهم ويرشدهم على الأئمة؛ والواجب على أهل العلم أن يستجيبوا الواجب على أهل العلم من المدرسين والقضاة أن يستجيبوا للإمامة حتى يسدوا هذا الفراغ العظيم الذي أحوج الأوقاف إلى أن تستورد من لا يرضى في دينه ولا في خلقه، الواجب على القضاة وعلى العلماء أن يشاركوا في الإمامة وأن يحتسبوا الأجر وأن يصبروا حتى يسدوا فراغاً عظيماً في هذه المسألة.\nوهنا عزم من الدولة بإيجاد معاهد للأئمة والخطباء وهذا متى تحقق إن شاء الله سد هذه الثغرة وسد هذا الفراغ وقد تمت الموافقة على افتتاح معهد للأئمة والخطباء في الرياض ونرجو أن يفتتح مثله في المدينة ومكة وهكذا في المدن الأخرى كالقصيم والحايل وأبها ونحو ذلك حتى يسد هذا الفراغ الضرورة داعية إلى هذا الأمر فنسأل الله أن يوفق الدولة للبدار بهذا الأمر وهذا المعهد سيكون من طريق جامعة الإمام محمد بن سعود وهي أهل لهذا الأمر.\nفنسأل الله أن يسهل افتتاحه في هذا العام وقد تمت ..... ..... فيما بلغني ولم يبق إلا شيء يسير ..... نرجو أن يتم في هذه الأيام حتى يفتح إن شاء الله هذه الأيام ثم يفتح بعده إن شاء معاهد أخرى في مكة المكرمة والمدينة المنورة وغيرهما من المدن التي ينبغي أن يفتح فيها هذا المعهد، والحاجة ماسة بل الضرورة ماسة إلى هذا الأمر وهذا لا يعفي العلماء من المدرسين وغيرهم ولا يعفي القضاة من الاستجابة بل عليهم فيما أعتقد أن يستجيبوا وأن يؤموا في المساجد المحتاجة وأن يحتسبوا الأجر حتى يوجد من يقوم مقامهم ويسد عنهم هذا الفراغ.\nنسأل الله للجميع التوفيق والهداية.\nالمقدم: الواقع هذه بشارة -سماحة الشيخ- وإذا تكرمتم أرجو من سماحة الشيخ المتابعة أيضاً حول هذا الموضوع لعل الله سبحانه وتعالى أن يحقق على أيديكم هذا الأمل الكبير الذي ينتظره المسلمون.\nالشيخ: إن شاء الله أنا متابع لهذا ونسأل الله أن يحقق ذلك في هذا العام وفيما بعده.","link":"https://binbaz.org.sa/fatwas/5987/حكم-الصلاة-خلف-حليق-اللحية-او-المدخن-وايهما-اولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_105/10508.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8209,"question":"سؤاله الثاني: إذا قام الإمام بعد إتمام الصلاة وقبل السلام، وهمَّ بأن يأتي بركعة زيادة عن الصلاة، واستدرك المأمومون بذلك وأرادوا التنبيه عن سهوه، بقول: سبحان الله، ولكنه مع ذلك أصر على الوقوف للزيادة، فما حكم ذلك، وماذا يعمل المأمومون بعده أفيدونا أفادكم الله؟","title":"زيادة الإمام في الصلاة بعد تنبيه المصلين له","answer":"الواجب على المأمومين التنبيه؛ لأن النبي ﷺ قال: من نابه شيء في صلاته فليسبح الرجال، ولتصفق النساء، والواجب على الإمام إذا نبهوه أن يرجع، إلا إذا كان يعتقد أنه مصيب وأنهم مخطئون فإنه يعمل بصواب نفسه باعتقاده ويستمر حتى يكمل الصلاة باعتقاده، والذين نبهوه إن كانوا متيقنين أنه غلطان وأنه مخطئ لا يقومون معه، يجلسون، يقرءون التحيات ويصلون على النبي ﷺ ويدعون، وينتظرونه حتى يسلموا معه؛ لأنه معذور وهم معذورون، هم معذورون باعتقادهم أنه مخطئ، وهو معذور باعتقاده أنه مصيب وأنهم مخطئون، فكل منهما معذور في اجتهاده وتيقنه بزعمه صواب نفسه، فإذا سلم سلموا معه. أما إن كان ما عنده يقين، فالواجب عليه أن يرجع إذا كان من نبهه اثنان فأكثر، عليه أن يرجع إذا كان ليس عنده يقين وإنما ظن، فإنه يرجع كما رجع النبي ﷺ لقول ذي اليدين لما نبهه وسأل الناس وصوبوا ذا اليدين رجع النبي ﷺ وأتم صلاته، ولم يعمل بقول ذي اليدين؛ لأنه واحد، فالواحد لا يلزم الرجوع إليه إلا إذا اعتقد الإمام أنه مصيب رجع، أما إذا كان المنبه اثنين فإنه يرجع لقولهما، ويبني على قولهما ويدع ظنه، هكذا الواجب. وأما المأمومون فإنهم لا يتابعونه في الخطأ، لا في الزيادة ولا في النقص، إن كان فيه زيادة فيجلسون، حتى يسلم ويسلموا معه، وإن كان فيه نقص ولم يمتثل وجلس في الثالثة من الظهر مثلاً أو العشاء أو العصر، أو جلس في الثانية[1] من الفجر أو الجمعة ولم يطعهم فإنهم يقومون يكملون، يكملون صلاتهم ويتمونها ويخالفونه؛ لأنه أخطأ باعتقادهم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6018/زيادة-الامام-في-الصلاة-بعد-تنبيه-المصلين-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_095/09504.mp3","categories":["سجود السهو","صلاة الجماعة"]},{"id":8262,"question":"إذا توفر مجموعة من النساء في مكان واحد فهل تجب عليهن صلاة الجماعة؟ وهل هناك إثم إذا صلت كل واحدة بمفردها ولم يصلين جماعة؟","title":"مشروعية صلاة الجماعة للنساء","answer":"الجواب: لا حرج في ذلك، ولا تجب عليهن الجماعة، الجماعة من اختصاص الرجال، وجوبها في حق الرجال، أما المرأة فليس عليها جماعة، لكن لو صلين جماعة فلا حرج، لو صلين جماعة أو صلت بهن إحداهن ولا سيما من لها بصيرة وعلم حتى تعلمهن وحتى ترشدهن هذا طيب هذا مستحب، قد روي عن أم سلمة و عائشة أنهما صلتا ببعض النساء.\nفالحاصل أنه إذا وجد فيهن امرأة قارئة معلمة تفيدهن وصلت بهن هذا طيب ومشروع للتعليم تعرف كيف تصلي المرأة؟ كيف تركع؟ كيف تطمئن؟ كيف تخشع في صلاتها؟ وتكون إمامتهن بينهن في وسطهن لا تقدم بل تكون في وسطهن، وتجهر بالقراءة في المغرب والعشاء والفجر كالرجل، حتى يستفدن منها، وإذا رأت منهن شيء من الخلل علمتهن وتعظهن وتذكرهن إذا كان عندها علم فهذا شيء مطلوب، لكن لو لم يصلين جماعة فلا حرج ولو كن موجودات في بيت واحد، إذا صلت كل واحدة وحدها فلا حرج.","link":"https://binbaz.org.sa/fatwas/6072/مشروعية-صلاة-الجماعة-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_098/09812.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8287,"question":"أخونا له سؤال آخر يتعلق بصلاة التراويح سماحة الشيخ يقول: نرجو بيان الحكم؛ إذا صلى الإمام بنا في التراويح ثلاث ركعات وسلم على اعتبار أنها ركعتين، هل هناك سجود للسهو في السنة، أو لا؟","title":"حكم سجود السهو لمن سها في النافلة","answer":"الجواب: نعم فيه السجود، إذا نوى ركعتين كالعادة يعني: السنة صلاة الليل مثنى مثنى، فإذا قام إلى ثالثة ينبه يقال: سبحان الله، سبحان الله، وعليه أن يرجع ويكمل قراءة التحيات والصلاة على النبي ﷺ والدعاء، ثم يسجد للسهو ثم يسلم، فإن مضى ولم يجلس نبهوه حتى يجلس ولو بعد الثالثة، فيجلس ويقرأ التحيات وما بعدها من الصلاة على النبي ﷺ والدعاء، ثم يسجد للسهو، كما أنه مشروع في الفريضة مشروع في النافلة. نعم.","link":"https://binbaz.org.sa/fatwas/6097/حكم-سجود-السهو-لمن-سها-في-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_107/10703.mp3","categories":["سجود السهو"]},{"id":8305,"question":"هذه رسالة من السائل: موسى سراج علي ، مقيم في المملكة العربية السعودية، يقول في رسالته: نحن نعلم أن من أدرك الجماعة في الركوع أو من أدرك المصلين في الركوع فقد أدرك الركعة، ولكن بعض الناس يقولون: لا صلاة لمن لا فاتحة له. أرجو توضيح هذا الإشكال؟","title":"حكم من أدرك الإمام وهو راكع","answer":"الجواب: هذه مسألة خلاف بين أهل العلم، هل تدرك الركعة بالركوع أم لابد من القراءة مع الإمام؟ هذا موضوع فيه خلاف بين أهل العلم، والصواب: أنه متى أدرك الركعة -يعني: الركوع- فقد أدرك الركعة، هذا هو الذي عليه جمهور أهل العلم من الأئمة الأربعة وغيرهم، وهو الذي دل عليه حديث أبي بكرة الثقفي  الذي رواه البخاري في الصحيح: أن أبا بكرة جاء والنبي راكع عليه الصلاة والسلام فركع ثم دخل في الصف ثم كمل صلاته، فلما سلم النبي ﷺ سأل عنه فأخبر، فقال: زادك الله حرصاً ولا تعد ولم يأمره بقضاء الركعة؛ ولهذا الصواب من قولي العلماء: أن من أدرك الركوع أدرك الركعة وأجزأته ولا يؤمر بالإعادة، أما قوله ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب فهذا في حق من أدرك القيام وأمكنه القيام، أما من عجز فهو معذور، هذا الذي عليه أهل التحقيق وجمهور أهل العلم، فالذي فاته القيام معذور، فيصلي الركوع مع الإمام وبقية الصلاة ويجزئه ذلك هذا هو الصواب. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6129/حكم-من-ادرك-الامام-وهو-راكع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_201/20111.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8311,"question":"من رأس تنورة رحيمة رسالة باعثها أخونا عثمان محمد أحمد ، أخونا: ما حكم السلام قبل الإمام في حالة السهو، هل صلاته صحيحة، أم لا؟","title":"حكم سلام المأموم قبل إمامه سهواً","answer":"الجواب: إذا سلم المأموم قبل الإمام سهواً فإنه يرجع إلى نية الصلاة، ثم يسلم بعد إمامه ولا شيء عليه، صلاته صحيحة، إذا سلم قبل إمامه سهواً ثم انتبه فإنه يعود إلى نية الصلاة ثم يسلم بعد إمامه ولا شيء عليه، إلا أن يكون مسبوقاً، فإن كان مسبوقاً بركعة أو أكثر فإنه يسجد للسهو بعدما يقضي ما عليه، إذا قضى ما عليه من الركعات سجد للسهو عن سلامه سهواً قبل إمامه. نعم.","link":"https://binbaz.org.sa/fatwas/6115/حكم-سلام-الماموم-قبل-امامه-سهوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_108/10806.mp3","categories":["سجود السهو"]},{"id":8324,"question":"هذه رسالة من المرسل (عبد الكريم . س. م) من القصيم يقول: أنا أسكن حياً بعيداً عن البلاد بحوالي خمسة كيلو مترات، في أوقات النهار والمغرب والعشاء أصلي مع جماعة المسجد ولله الحمد، ولكن في صلاة الفجر أصلي منفرداً، فهل يحق لي ذلك؟","title":"حكم الصلاة في البيت لمن بعد عليه المسجد","answer":"الجواب: نعم؛ لأن خمسة كيلو بعيد لا يسمع النداء، فله أن يصلي وحده؛ لأن المسافة بعيدة، أما لو كان بقربه مسجد يسمع به النداء وجب عليه السعي؛ لقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر فإذا كان في هذا المكان البعيد الذي لا يسمع فيه النداء فإنه لا يلزمه الحضور، فإن تجشم المشقة وصبر ولاسيما إذا كان صاحب سيارة فهذا خير له وله فضل عظيم. نعم.\nالمقدم: أحسنتم، جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6141/حكم-الصلاة-في-البيت-لمن-بعد-عليه-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_202/20206.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8369,"question":"إذا رفع الإمام من السجود، وشرع في فاتحة الكتاب، بقي من المصلين جالساً حتى ينتهي الإمام من الفاتحة، أو قبلها بقليل، من الممكن أن يكون مريضاً أو متعمداً، ما الحكم في ذلك؟","title":"تأخر المأموم عن متابعة الإمام أثناء القراءة","answer":"الجواب: إن كان مريضاً يشق عليه القيام، ويستعين بهذا على بقية القيام، فلا حرج في ذلك، أما إن كان يتعمد ويتكاسل، فلا يجوز، الواجب عليه القيام والمسارعة إلى القيام مع إمامه، إلا إذا كان أراد جلسة الاستراحة، وهي جلسة خفيفة قليلة، فلا بأس بذلك، يجلس قليلاً كما يجلس بين السجدتين، ثم ينهض ولا يطيل، أما أن يطيل حتى يقارب الإمام الفاتحة، أو نصف الفاتحة فهذا لا ينبغي، بل الواجب البدار والمسارعة مع الإمام؛ لأن الرسول عليه السلام قال: إنما جعل الإمام ليؤتم به، فلا تختلفوا عليه. فالواجب على المأموم أن يسارع وأن يقوم مع الإمام، إلا من عذرٍ شرعي، كالمرض أو نية جلسة الاستراحة، وهي: جلسة خفيفة، لا بأس بها، بل هي مستحبة في أصح قولي العلماء، فإن جلس بهذه النية فلتكن خفيفة، ثم ينهض. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6218/تاخر-الماموم-عن-متابعة-الامام-اثناء-القراءة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_114/11409.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8439,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين من تشاد يقول: أنا السائل شعيب آدم من تشاد مدينة مندو، أتقدم لكم بسؤالين راجياً منكم الإجابة وفقكم الله، السؤال الأول: إذا كان حضرت مع الإمام في صلاة العشاء، وكان ذلك في الركعتين الأخيرتين وهن سراً، فماذا أفعل في الركعتين اللتين فاتتا، هل أقرأ فيهما سراً أم جهراً؟","title":"أول الصلاة بالنسبة للمسبوق","answer":"الجواب: الصواب أن ما أدركه المأموم مع الإمام فهو أول صلاته، وما يقضيه هو آخرها، هذا هو الصواب، وهو الأصح من قولي العلماء؛ لقوله ﷺ: إذا أتيتم الصلاة فأتوها وعليكم السكينة، فما أدركتم فصلوا، وما فاتكم فأتموا، وفي اللفظ الآخر: فاقضوا  يعني اقضوا بمعنى: أتموا، فالقضاء هنا بمعنى التمام جمعاً بين الروايتين؛ ولأن رواية التمام أكثر، ومعناها أظهر، وهذا معنى قوله تعالى: فَإِذَا قَضَيْتُمُ الصَّلاةَ فَاذْكُرُوا اللَّهَ [النساء:103] يعني: أتممتموها: فَإِذَا قَضَيْتُمْ مَنَاسِكَكُمْ فَاذْكُرُوا اللَّهَ [البقرة:200] يعني: أتممتم، فإذا أدرك ركعتين من العشاء مثلاً، أو أدرك ركعتين من المغرب؛ فإنه يقضي الباقي على حسب الحال: فإن كان المغرب قضى الثانية بالجهر والثالثة بغير الجهر، وإن كان العشاء فإنه يقضيهما سراً من دون جهر ويكتفى بالفاتحة فقط؛ لأنهما آخر صلاته، والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/6323/اول-الصلاة-بالنسبة-للمسبوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_120/12004.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8440,"question":"إذا حضرت بقرية وكان إمامها من أهل الصوفية، ولا يقبض يديه في الصلاة، ولا يدلي بركبتيه قبل يديه إلى السجود، فهل تجوز صلاتي خلفه أم لا؟","title":"حكم الصلاة خلف من ينتسب للصوفية؟","answer":"الجواب: إذا كان موحداً معروفاً بالتوحيد، ليس مشركاً؛ وإنما عنده شيء من الجهل أو التصوف، ولكنه موحد مسلم يعبد الله وحده، ولا يعبد المشايخ ويدعوهم من دون الله كالشيخ عبد القادر أو غيره، بل يعبد الله وحده، فمجرد كونه لا يضم يديه لا يمنع، هذا أمر مسنون ضم اليدين، وجعل اليمنى على اليسرى على الصدر هذا مستحب، فمن أرخاهما وأرسلهما فلا حرج عليه وصلاته صحيحة، وبهذا قال جماعة من أهل العلم، وهو المعروف في مذهب مالك رحمه الله عند أصحابه، لكن الصواب والمشروع أنه يضم، هذا هو الأفضل، وهذا هو السنة يضم اليمنى إلى اليسرى، ويجعلهما على صدره، ويجعل اليمنى فوق كف اليسرى والرسغ والساعد هذا هو الأفضل، وهذا هو المحفوظ عن النبي ﷺ، رواه أبو داود والنسائي وآخرون عن النبي ﷺ من حديث وائل بن حجر ، وهكذا جاء له شاهد عند أحمد رحمه الله في مسنده من حديث قبيصة بن هلب عن أبيه: أن النبي ﷺ كان يضع يديه على صدره، فالمقصود من هذا هو الأفضل، لكن من أرسل فلا حرج صلاته صحيحة، وهكذا إذا قدم ركبتيه قبل يديه هذا هو الأفضل، وقال آخرون: يقدم يديه قبل ركبتيه؛ لما ورد في ذلك من حديث أبي هريرة ، والأمر في هذا واسع، فلا يضر الصلاة قدم ركبتيه أو قدم يديه، الأمر كله واسع، والصلاة صحيحة، لكن الأفضل أن يقدم ركبتيه ثم يديه هذا هو الأفضل، وهذا هو المعتمد، يقدم ركبتيه ثم يديه ثم جبهته وأنفه، هذا هو الأفضل، وهذا هو المعتمد من حيث الدليل، وإن قدم يديه ثم ركبتيه فلا حرج في ذلك، والصلاة صحيحة والحمد لله، ولا مانع من الصلاة خلف من يفعل ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/6324/حكم-الصلاة-خلف-من-ينتسب-للصوفية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_120/12005.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8489,"question":"أختنا تسأل عن صلاة الجماعة بالنسبة للمرأة في المدارس أو في غيرها وترجو التوجيه؟","title":"حكم صلاة الجماعة للمرأة","answer":"الجواب: صلاة الجماعة على النساء غير واجبة، لكنها إذا تيسرت أفضل حتى يتعلم بعضهن من بعض وحتى يستفيد بعضهن من بعض، وقد جاء عن أم سلمة وعائشة رضي الله عنهما أنهما أمتا بعض النساء، فذلك يدل على أن هذا أمر معلوم عندهن في العهد الأول والقرن الأول، ومعلوم ما في هذا من الفضائل والمصالح فإن وجود امرأة ذات علم وبصيرة تؤم النساء يستفيد منها النساء كثيراً، يتعلمن كيف يصلين كيف يركعن كيف يسجدن إلى غير ذلك، فصلاتهن جماعة خلف إمامة صالحة ذات بصيرة وعلم هذا لا شك فيه أنه ينفع الجميع.\nوهي تقف وسطهن، لا أمامهن بل تقف وسطهن وتجهر في الجهرية كالمغرب والعشاء والفجر.\nفالحاصل أنه مستحب إذا تيسر، وليس بواجب، إنما تجب الجماعة على الرجال في بيوت الله  حيث قدروا على ذلك، وأما النساء فصلاتهن منفردات جائزة، وإذا تيسرت الجماعة لهن فيما بينهن فهو حسن ولا سيما إذا وجدت امرأة لديها علم وبصيرة حتى تصلي بهن وتعلمهن الصلاة الشرعية التي أرشد إليها النبي ﷺ قولاً وفعلاً.\nوقد قال عليه الصلاة والسلام: صلوا كما رأيتموني أصلي وهذا يعم النساء والرجال جميعاً فعلى جميع المصلين أن يصلوا كما صلى النبي صلى الله عليه وسلم، والمرأة الفاهمة العالمة تعلم أخواتها في الله وبناتها وغيرهن الصلاة الشرعية، وإذا صلت بهن كان ذلك أكمل في التعليم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6548/حكم-صلاة-الجماعة-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_126/12603.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8493,"question":"أحد الإخوة من الخفجي ناصر عديم الدوسري أخونا يقول: شخص دخل المسجد بعد انتهاء صلاة الجماعة -صلاة العصر- وقام يصلي منفرداً، وأثناء صلاته دخل شخص آخر هل يتصل معه بالصلاة وهل تعتبر صلاتهم صلاة جماعة؟","title":"حكم من صلى منفرداً ثم دخل معه آخر","answer":"الجواب: نعم هذا هو الأفضل إذا قام يصلي وجاء آخر فالأفضل أن يصف معه عن يمينه، فإن كان الداخل اثنين صفا خلفه حتى تحصل لهم فضيلة الجماعة، وقد ثبت عنه ﷺ أنه رأى رجلاً بعد الصلاة قد دخل وفاتته الصلاة، فقال عليه الصلاة والسلام: من يتصدق على هذا فيصلي معه.\nفالسنة أن يقوم بعض الإخوان وبعض الحاضرين فيصلي مع الداخل حتى تكون له جماعة، لكن إن كان واحداً صف عن يمينه وإن كان أكثر من واحد صاروا خلفه، هذا هو السنة وهذا هو المشروع وفي هذا فضل عظيم؛ لأن الرجل يحصل له فضل الجماعة بقيام إخوانه معه، ولو واحداً. نعم.\nالمقدم: بارك الله فيكم، إذاً من قال: إن صلاة الجماعة مع الإمام الراتب فقط قول مخطئ؟\nالشيخ: لا، غلط ليس له أصل لكن الواجب البدار بصلاة الجماعة والصلاة مع الإمام وعدم التأخر، لكن متى قدر أنه تأخر لعلة من العلل ثم صادف من يصلي معه يرجى له أجر الجماعة لعموم الأدلة. نعم.","link":"https://binbaz.org.sa/fatwas/6552/حكم-من-صلى-منفردا-ثم-دخل-معه-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_126/12607.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8508,"question":"والرسالة الأولى في حلقة هذه الليلة مقدمة من السائل (ح. ص. الأحمدي) من المدينة المنورة الحرة الغربية، يقول في رسالته التي تشتمل على عدة أسئلة: لقد صلى بنا يوماً من الأيام إمام المسجد صلاة العصر خمس ركعات، فنبهناه ولكنه لم يرجع، فهل يجوز لنا متابعته أم الجلوس ثم السلام معه؟ وهل على من تابعه عالماً بأنه صلى خمساً إعادة أم لا، أفيدونا بارك الله فيكم؟","title":"حكم متابعة المأمومين للإمام إذا زاد أو نقص في الصلاة","answer":"الجواب:","link":"https://binbaz.org.sa/fatwas/6596/حكم-متابعة-المامومين-للامام-اذا-زاد-او-نقص-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_204/20401.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8522,"question":"هذه رسالة وردتنا من أحد الإخوة لم يذكر اسماً ولا عنواناً، يقول في رسالته: عندنا زاوية نصلي فيها الصلوات الخمس؛ لأن فيها أذان، ولكن لا تقام فيها صلاة الجمعة، فما حكم صلاتنا فيها؟","title":"حكم الصلاة في المساجد الصغيرة التي لا يصلى فيها الجمعة","answer":"الجواب: إذا كانت الزاوية بمثابة المسجد ولكنها زاوية صغيرة يعني: مسجد صغير، فيصلى فيها إذا كان ما هناك مسجد يغني عنها، فإن كان هناك مسجد يغني عنها كبير يصلى مع الجماعة في المسجد الكبير الذي فيه الإمام وفيه المؤذن، وإذا كانت الحارة ليس فيها إلا هذه الزاوية المسجد الصغير صلوا فيها جماعة، وأذنوا فيها وأقاموا، وعين لها إمام إذا تيسر لها إمام، وإلا صلى بهم من حضر من أهل الاستقامة الذين يصلحون للإمامة، يصلي بهم خيرهم وأفضلهم إذا كان ليس لها إمام راتب، ويؤذن فيها من تيسر منهم إذا لم يكن لها مؤذن راتب.\nفالحاصل أن الزاوية بمثابة المسجد الصغير، يسمون المساجد الصغيرة يسمونها زوايا في كثير من البلدان، فهذه الزوايا التي هي المساجد الصغيرة يصلى فيها عند الحاجة إليها، وإذا كانت الحارة والحي فيه مساجد أكبر وأوسع فيصلى مع الكثرة وتهجر هذه الزوايا، إذا كان هناك مساجد كبيرة تغني عنها، أما إذا دعت الحاجة إليها يصلى فيها والحمد لله. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6604/حكم-الصلاة-في-المساجد-الصغيرة-التي-لا-يصلى-فيها-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_204/20408.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8529,"question":"هذه رسالة وردتنا من أحد الإخوة لم يذكر اسماً ولا عنواناً، يقول في رسالته: عندنا زاوية نصلي فيها الصلوات الخمس؛ لأن فيها أذان، ولكن لا تقام فيها صلاة الجمعة، فما حكم صلاتنا فيها؟","title":"حكم الصلاة في المساجد الصغيرة التي لا يصلى فيها الجمعة","answer":"الجواب: إذا كانت الزاوية بمثابة المسجد ولكنها زاوية صغيرة يعني: مسجد صغير، فيصلى فيها إذا كان ما هناك مسجد يغني عنها، فإن كان هناك مسجد يغني عنها كبير يصلى مع الجماعة في المسجد الكبير الذي فيه الإمام وفيه المؤذن، وإذا كانت الحارة ليس فيها إلا هذه الزاوية المسجد الصغير صلوا فيها جماعة، وأذنوا فيها وأقاموا، وعين لها إمام إذا تيسر لها إمام، وإلا صلى بهم من حضر من أهل الاستقامة الذين يصلحون للإمامة، يصلي بهم خيرهم وأفضلهم إذا كان ليس لها إمام راتب، ويؤذن فيها من تيسر منهم إذا لم يكن لها مؤذن راتب.\nفالحاصل أن الزاوية بمثابة المسجد الصغير، يسمون المساجد الصغيرة يسمونها زوايا في كثير من البلدان، فهذه الزوايا التي هي المساجد الصغيرة يصلى فيها عند الحاجة إليها، وإذا كانت الحارة والحي فيه مساجد أكبر وأوسع فيصلى مع الكثرة وتهجر هذه الزوايا، إذا كان هناك مساجد كبيرة تغني عنها، أما إذا دعت الحاجة إليها يصلى فيها والحمد لله. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6604/حكم-الصلاة-في-المساجد-الصغيرة-التي-لا-يصلى-فيها-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_204/20408.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8532,"question":"ما الحكم إذا سها المصلي عن سجدة في صلاته، سواءً علم وهو في الصلاة أم لم يعلم إلا بعدها؟","title":"حكم من ترك سجدة في صلاته سهواً","answer":"الجواب: إذا نسي سجدة بطلت الركعة التي ترك منها السجدة وقامت الثانية مقامها، فمتى ذكر يأتي بركعة بدل الركعة التي ترك منها السجدة، وسجد للسهو إذا كان إماماً، أما إذا كان مأموماً فإنه يقضي بعد تسليم إمامه يقوم يأتي بركعة بدل الركعة التي ترك منها السجود، ويكفيه ... وتصح صلاته إن شاء الله بذلك؛ لأنه فاتته ركعة في المعنى بسبب السجدة التي تركها، أما إن كان إمام أو منفرد فإنه يأتي بركعة بدل الركعة التي ترك السجدة منها ويسجد للسهو بعد ذلك، أما المأموم الذي نسي السجدة ولم يفطن لها إلا بعدما مضت الركعة بعدما قام إلى الركعة الثانية وشرع في القراءة فإنه إذا سلم إمامه يأتي بركعة بدل الركعة التي ترك منها السجود، فإن ذكرها حين قيامه رجع وسجدها وتمت صلاته من غير حاجة إلى زيادة ركعة إذا تذكرها في الحال حين قيامه إلى الركعة التي بعدها، أو بعد قيامه قبل الشروع في القراءة فإنه يرجع ويأتي بالسجدة وتجزئه ركعته، لكن لو نسي واستمر النسيان فإنه يأتي بركعة بعد ذلك، والأقرب والله أعلم إنه يسجد للسهو؛ لأنه صار كالمسبوق إذا قضى الركعة التي عليه يسجد للسهو سجدتين لأنه صار في هذا حكمه حكم المسبوق. نعم.\nالمقدم: جزاكم الله خير، وإذا لم يعلم إلا بعد الصلاة مثلاً يعيد الصلاة؟\nالشيخ: لا. يأتي بركعة إذا كان الوقت قصير قريب يأتي بركعة فقط ويسجد للسهو، أما إذا كان طال الفصل.. عرفاً بأن نسي ولم يذكر إلا في اليوم الثاني أو الثالث أو بعد طول الفصل، المقصود: إذا طال الفصل يعيد الصلاة كلها، يأتي بها كلها، يقضي الصلاة كلها. نعم.\nالمقدم: جزاكم الله خير، وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6619/حكم-من-ترك-سجدة-في-صلاته-سهوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_205/20510.mp3","categories":["سجود السهو"]},{"id":8533,"question":"وهذه رسالة وردتنا من مستمع ذيلها بتوقيع طالب عالم، يقول في أول رسالته: إذا وجدت الإمام قد سلم ولا يزال بعض المأمومين ممن فاته بعض الركعات مع الإمام يقضي، فهل يجوز لي أن أصلي خلفه مؤتماً به لجماعة ثانية أم لا؟","title":"الائتمام بالمسبوق","answer":"الجواب: الأمر في هذا واسع، إن صليت وحدك فهو أحوط وأولى خروجاً من خلاف العلماء، وإن كان معك جماعة فالأولى والأفضل أن تصلوا جميعاً ولا تصلوا مع المسبوق، وإن صليت مع المسبوق وجعلته إماماً لك فلا حرج في ذلك على الصحيح، والصلاة صحيحة إن شاء الله، لكن الأفضل والأولى لك أن تصلي وحدك؛ لأن كثيراً من أهل العلم لا يرى صحة إمامة المسبوق الذي قام ليقضي ما عليه، فإن صليت معه فلا حرج، كما لو دخلت مع إنسان يصلي وحده وجعلته إماماً لك وصليت معه فإنه لا حرج في ذلك، والجماعة مطلوبة. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6614/الاىتمام-بالمسبوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_205/20505.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8536,"question":"يقول أيضاً: إذا قمت لإكمال ما فاتني من الصلاة مع الإمام في صلاة جهرية كالفجر مثلاً، فهل أجهر بالقراءة أم أسر بها؟","title":"حكم الجهر للمسبوق في الصلاة الجهرية","answer":"الجواب: الأفضل الجهر؛ لأن الصلاة الجهرية السنة فيها الجهر، لكنه جهر لا يؤذي من حوله من المصلين والمهللين، فيكون جهر خفيف لا يتأذى به من حوله من المصلين. نعم.","link":"https://binbaz.org.sa/fatwas/6615/حكم-الجهر-للمسبوق-في-الصلاة-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_205/20506.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8537,"question":"وأولى رسائل هذه الحلقة وردتنا من المستمع (ع. م. م) من الرياض، يقول فيها: إذا سهوت في الصلاة ولم أسجد سجود السهو، وسلمت ونسيت سجود السهو، فماذا يجب علي أن أفعل؟","title":"حكم من سها في الصلاة ولم يسجد للسهو","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد أبان النبي ﷺ الحكم فيما يتعلق بالسهو، وذكر عليه الصلاة والسلام أنواعاً من ذلك قولاً وفعلاً عليه الصلاة والسلام، فمن ذلك: ما رواه أبو سعيد الخدري رضي الله عنه، عن النبي ﷺ أنه قال: إذا شك أحدكم في صلاته فلم يدر كم صلى ثلاثاً أم أربعا فليطرح الشك وليبن على ما استيقن، ثم يسجد سجدتين، فإن كان صلى خمساً شفعن له صلاته، وإن كان صلى تماماً كانتا ترغيماً للشيطان خرجه مسلم في صحيحه، فإذا شك الإنسان هو صلى ثنتين أم ثلاث يجعلها ثنتين يبني على الأقل وهو اليقين، وإن شك أنها ثلاث أو أربع جعلها ثلاثاً ثم كمل، ثم بعد هذا يسجد للسهو سجدتين قبل أن يسلم، وهكذا لو سها عن قول: (سبحان ربي العظيم) في الركوع، أو عن (سبحان ربي الأعلى) في السجود أو عن قول (رب اغفر لي) بين السجدتين، أو سها عن قول (ربنا ولك الحمد) عند ارتفاعه من الركوع، أو سها الإمام أو المنفرد عن قول (سمع الله لمن حمده) كل هؤلاء يشرع لهم بل يجب عليهم سجود السهو، سجدتان قبل أن يسلم، وهكذا لو سلم من ثلاث في الظهر أو العصر أو العشاء، أو سلم من ثنتين في المغرب مثلاً، أو سلم من واحدة في الفجر أو الجمعة ناسياً فإنه يسجد للسهو، لكن في هذه الحالة إذا سلم عن نقص ركعة أو أكثر فإنه يكون سجوده بعد السلام أفضل؛ لفعل النبي ﷺ، فإنه سلم مرة من ركعتين فنبه وكمل صلاته ثم سلم ثم سجد للسهو سجدتين، ومرة سلم من ثلاث عليه الصلاة والسلام فنبه فكمل صلاته ثم سلم، ثم سجد سجدتين للسهو ثم سلم.\nهذا هو المشروع للمؤمن والمؤمنة في السهو، فإذا نسي السجود فصلاته صحيحة، إذا نسي سجود السهو فصلاته صحيحة، لكن متى ذكر سجد سجدتي السهو سواء في المسجد أو في بيته، وقال بعض أهل العلم: إذا طال الفصل سقطت، ولكن الأحوط والأولى أنه متى ذكرها ولو طال الفصل سجد سجدتين بنية السهو، سواء في المسجد أو في بيته. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6610/حكم-من-سها-في-الصلاة-ولم-يسجد-للسهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_205/20501.mp3","categories":["سجود السهو"]},{"id":8539,"question":"يقول أيضاً: إذا قمت لإكمال ما فاتني من الصلاة مع الإمام في صلاة جهرية كالفجر مثلاً، فهل أجهر بالقراءة أم أسر بها؟","title":"حكم الجهر للمسبوق في الصلاة الجهرية","answer":"الجواب: الأفضل الجهر؛ لأن الصلاة الجهرية السنة فيها الجهر، لكنه جهر لا يؤذي من حوله من المصلين والمهللين، فيكون جهر خفيف لا يتأذى به من حوله من المصلين. نعم.","link":"https://binbaz.org.sa/fatwas/6615/حكم-الجهر-للمسبوق-في-الصلاة-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_205/20506.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8540,"question":"وأولى رسائل هذه الحلقة وردتنا من المستمع (ع. م. م) من الرياض، يقول فيها: إذا سهوت في الصلاة ولم أسجد سجود السهو، وسلمت ونسيت سجود السهو، فماذا يجب علي أن أفعل؟","title":"حكم من سها في الصلاة ولم يسجد للسهو","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد أبان النبي ﷺ الحكم فيما يتعلق بالسهو، وذكر عليه الصلاة والسلام أنواعاً من ذلك قولاً وفعلاً عليه الصلاة والسلام، فمن ذلك: ما رواه أبو سعيد الخدري رضي الله عنه، عن النبي ﷺ أنه قال: إذا شك أحدكم في صلاته فلم يدر كم صلى ثلاثاً أم أربعا فليطرح الشك وليبن على ما استيقن، ثم يسجد سجدتين، فإن كان صلى خمساً شفعن له صلاته، وإن كان صلى تماماً كانتا ترغيماً للشيطان خرجه مسلم في صحيحه، فإذا شك الإنسان هو صلى ثنتين أم ثلاث يجعلها ثنتين يبني على الأقل وهو اليقين، وإن شك أنها ثلاث أو أربع جعلها ثلاثاً ثم كمل، ثم بعد هذا يسجد للسهو سجدتين قبل أن يسلم، وهكذا لو سها عن قول: (سبحان ربي العظيم) في الركوع، أو عن (سبحان ربي الأعلى) في السجود أو عن قول (رب اغفر لي) بين السجدتين، أو سها عن قول (ربنا ولك الحمد) عند ارتفاعه من الركوع، أو سها الإمام أو المنفرد عن قول (سمع الله لمن حمده) كل هؤلاء يشرع لهم بل يجب عليهم سجود السهو، سجدتان قبل أن يسلم، وهكذا لو سلم من ثلاث في الظهر أو العصر أو العشاء، أو سلم من ثنتين في المغرب مثلاً، أو سلم من واحدة في الفجر أو الجمعة ناسياً فإنه يسجد للسهو، لكن في هذه الحالة إذا سلم عن نقص ركعة أو أكثر فإنه يكون سجوده بعد السلام أفضل؛ لفعل النبي ﷺ، فإنه سلم مرة من ركعتين فنبه وكمل صلاته ثم سلم ثم سجد للسهو سجدتين، ومرة سلم من ثلاث عليه الصلاة والسلام فنبه فكمل صلاته ثم سلم، ثم سجد سجدتين للسهو ثم سلم.\nهذا هو المشروع للمؤمن والمؤمنة في السهو، فإذا نسي السجود فصلاته صحيحة، إذا نسي سجود السهو فصلاته صحيحة، لكن متى ذكر سجد سجدتي السهو سواء في المسجد أو في بيته، وقال بعض أهل العلم: إذا طال الفصل سقطت، ولكن الأحوط والأولى أنه متى ذكرها ولو طال الفصل سجد سجدتين بنية السهو، سواء في المسجد أو في بيته. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6610/حكم-من-سها-في-الصلاة-ولم-يسجد-للسهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_205/20501.mp3","categories":["سجود السهو"]},{"id":8543,"question":"يقول أيضاً: إذا سلم بعض المأمومين تسليمة واحدة عن اليمين قبل الإمام سهواً، فهل تبطل صلاته؟","title":"حكم من سلم قبل الإمام سهواً","answer":"الجواب: لا تبطل صلاته، لكنه يسلم بعده.\nالمقدم: ثانية؟\nالشيخ: يسلم بعده ثانياً. نعم.\nالمقدم: طيب جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6616/حكم-من-سلم-قبل-الامام-سهوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_205/20507.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8544,"question":"له سؤال آخر في هذه الرسالة يقول فيه: يغلبني النعاس أحياناً في صلاة الصبح فلا أعلم ما قلت ولا ما فعلت كالقراءة والتحيات، ولكنه ليس بالنوم العميق الذي يخشى من نقض الوضوء معه فماذا أفعل، أفيدوني بارك الله فيكم؟","title":"حكم غلبة النعاس في صلاة الصبح","answer":"الجواب: مادام شعورك معك وتعقل الصلاة وأنك تتابع الإمام فصلاتك صحيحة، فالأصل أنك أديت ما يفعله الإمام، هذا هو الأصل وهو الظاهر من عملك مع الإمام حتى تعلم خلاف ذلك، إذا علمت أنك لم تقرأ التحيات مع الإمام تأتي بها ثم تسلم، وإن كنت علمت أنك تركت الفاتحة من ركعة من الركعات فالأمر في هذا واسع؛ لأن الإمام يتحمله عنك عند سهوك، وعند جهلك، وعند عدم علمك بما وقع منك، يتحمل الإمام عنك ذلك إن شاء الله. نعم.\nالمقدم: جزاكم الله خير. وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6611/حكم-غلبة-النعاس-في-صلاة-الصبح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_205/20502.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8560,"question":"هذه رسالة وردتنا من أخ جزائري يعمل بفرنسا رمز لاسمه بـ (س. ع) يقول في رسالته: لدينا إمام مسجد كبير في الغرب الجزائري وقعت له حادثة سيارة كان يقودها بنفسه ومعه اثنان من الرجال، وكان يريد أن يسبق سيارة أمامه فدخل في تلك السيارة من الخلف، ومات الرجلان اللذان معه، وأما هو فقد نجا؛ لأنه من جهة اليسار، وبقي إماماً بعد هذه الحادثة، فهل ينطبق عليه قول الله : وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا [النساء:93] إلى آخر الآية، أم أنه قتله هنا خطأ، وهل تجوز الصلاة خلفه؟","title":"حكم إمامة رجل قتل رجلين خطأ","answer":"الجواب: ما دام لم يتعمد قتل نفسه ولا قتل من معه، وإنما أراد أن يسبقها فدخل تحتها فلا يكون متعمداً بهذا، ويكون من باب القتل الخطأ، وعليه الدية والكفارة، ولا مانع من الصلاة خلفه؛ لأنه لم يتعمد القتل، مع أن الصحيح أن العاصي تصح الصلاة خلفه، لو تعمد القتل فهو عاصي، وأتى كبيرة عظيمة، ولكن لا يكون كافراً إذا لم يستحل ذلك، ومن صلى خلف الفاسق صلاته صحيحة على الصحيح، فإذا صلى خلف القاتل أو خلف العاق لوالديه، أو خلف من زنى، أو ما أشبه ذلك فإن الصلاة صحيحة، ولكن ينبغي أن لا يقدموا إذا كانوا معروفين بالمعاصي، ينبغي أن لا يقدم أحد منهم، بل يقدم من هو معروف بالعدالة والاستقامة، لكن لو صلى بعض الناس خلف من هو معروف بالفسق صحت صلاته على الصحيح، فقد صلى ابن عمر خلف الحجاج بن يوسف الثقفي أمير العراق وهو من أظلم الناس وأفسقهم ومع هذا صلى ابن عمر خلفه، فالمقصود: أن الصلاة خلف الفاسق والظالم صحيحة، ولكن ينبغي أن لا يقدم للإمامة مع القدرة، بل يلتمس الرجل العدل الذي يؤم الناس عنده القدرة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6644/حكم-امامة-رجل-قتل-رجلين-خطا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_207/20705.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8603,"question":"الصلاة في البيت لكي لا يرى من لا يحب؟","title":"حكم صلاة الرجل في بيته","answer":"الجواب: هذا ليس بعذر، بل يجب عليه أن يصلي في المساجد مع المسلمين وإن رأى من لا يحب، الأمر في هذا واسع، وإذا.. ويش يضره، عليه أن يجيب الله ورسوله وعليه أن يفعل ما أمره الله به ورسوله، وإن رأى بعض الناس الذي لا يحبهم، الرسول عليه السلام يقول: من سمع النداء فلم يأت فلا صلاة له إلا من عذر أخرجه ابن ماجة والدارقطني والحاكم وجماعة بإسناد جيد على شرط مسلم ، وقال عليه الصلاة والسلام لما سأله ابن أم مكتوم ، قال: يا رسول الله! ليس لي قائد يلائمني للمسجد، فهل لي من رخصة أنن أصلي في بيتي؟ فقال ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب رواه مسلم في الصحيح.\nفهذا أعمى ليس له قائد يلائمه، ويقال له: (أجب) وفي اللفظ الآخر يقول ﷺ: لا أجد لك رخصة فإذا كان الأعمى لا يوجد له رخصة ليس له قائد يلائمه، فكيف بحال الرجل الصحيح السليم المعافى البصير، الأمر في حقه أعظم.\nوفي الصحيحين عن النبي ﷺ أنه قال: لقد هممت أن آمر بالصلاة فتقام، ثم آمر رجلاً فيؤم الناس، ثم أنطلق برجال معهم حزم منن حطب إلى رجال لا يشهدون الصلاة فأحرق عليهم بيوتهم وهذا يدل على عظم الأمر، وفي مسند أحمد قال: لولا ما في البيوتت من النساء والذرية لحرقتها عليهم.\nفالحاصل: أن الأدلة واضحة قائمة على وجوب الصلاة في الجماعة في المساجد وليس لمن تأخر عنها لئلا يرى بعض الناس الذين لا يحبهم ليس له عذر في ذلك، بل عليه أن يتقي الله ويراقب الله ويصلي مع المسلمين، ولو رأى من لا يحب. نعم.\nالمقدم: الله المستعان.","link":"https://binbaz.org.sa/fatwas/6734/حكم-صلاة-الرجل-في-بيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_129/12908.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8611,"question":"هذه رسالة وردتنا من السائل (م. ع) من القصيم بريدة، يقول فيها: سمعت فتوى بأن الصلاة تصح وتجوز خلف شارب الدخان وحالق لحيته، ولكنها لا تصح ولا تجوز خلف المسبل، فوجدت حرجاً في نفسي إذا دخلت مكاناً فيه شخص مسبل فإنني لا أصلي خلفه حتى وإن كان في المسجد، ولا أصف وراءه ولا بجانبه، واستدل من أفتاني على هذا بأن هناك حديثاً يقول فيه الرسول ﷺ: إن الله لا يقبل صلاة مسبل أفيدونا أفادكم الله؟","title":"حكم الصلاة خلف العاصي","answer":"الجواب: الصواب الذي عليه المحققون من أهل العلم: أن العاصي تصح الصلاة خلفه كما تصح صلاته في نفسه، سواء كان العاصي شارب دخان، أو شارب خمر، أو مرابياً، أو عاقاً، أو مسبلاً أو غير ذلك، ولكن ينبغي للمؤمن أن يختار الإمام الصالح، إذا كان عنده مساجد يختار الإمام الصالح ويصلي خلف الإمام الصالح، فإن الصلاة خلفه أكمل وأتم، وأما صلاته خلف العاصي فهي صحيحة ولكن ينبغي أن لا يقر العاصي، ينبغي أن يسعى في إزالته إذا لم يقبل النصيحة، أولاً ينصح يوجه إلى الخير وينصح، فإن هداه الله فالحمد لله، وإلا فينبغي الاتصال بمن له الأمر حتى يزال وحتى يعين من هو خير منه، أما الصلاة فصحيحة ولو خلف المسبل على الصحيح، فإن ما جاء من الوعيد في حق المسبل لا يمنع صحة صلاته ولا يمنع صحة الصلاة خلفه، هو على كل حال لا يجوز له الإسبال لا في الصلاة ولا في خارجها، ولكن الصلاة خلفه صحيحة، وصلاته صحيحة لكنه آثم. نعم.\nالمقدم: وهذا الحديث الذي سمعناه؟\nالشيخ: نعم، هذا الحديث جاء، رواه أبو داود وغيره ولا بأس به، ولكنه من باب الوعيد. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6740/حكم-الصلاة-خلف-العاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_210/21006.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8614,"question":"هذه رسالة وردتنا من السائل (م. ع) من القصيم بريدة، يقول فيها: سمعت فتوى بأن الصلاة تصح وتجوز خلف شارب الدخان وحالق لحيته، ولكنها لا تصح ولا تجوز خلف المسبل، فوجدت حرجاً في نفسي إذا دخلت مكاناً فيه شخص مسبل فإنني لا أصلي خلفه حتى وإن كان في المسجد، ولا أصف وراءه ولا بجانبه، واستدل من أفتاني على هذا بأن هناك حديثاً يقول فيه الرسول ﷺ: إن الله لا يقبل صلاة مسبل أفيدونا أفادكم الله؟","title":"حكم الصلاة خلف العاصي","answer":"الجواب: الصواب الذي عليه المحققون من أهل العلم: أن العاصي تصح الصلاة خلفه كما تصح صلاته في نفسه، سواء كان العاصي شارب دخان، أو شارب خمر، أو مرابياً، أو عاقاً، أو مسبلاً أو غير ذلك، ولكن ينبغي للمؤمن أن يختار الإمام الصالح، إذا كان عنده مساجد يختار الإمام الصالح ويصلي خلف الإمام الصالح، فإن الصلاة خلفه أكمل وأتم، وأما صلاته خلف العاصي فهي صحيحة ولكن ينبغي أن لا يقر العاصي، ينبغي أن يسعى في إزالته إذا لم يقبل النصيحة، أولاً ينصح يوجه إلى الخير وينصح، فإن هداه الله فالحمد لله، وإلا فينبغي الاتصال بمن له الأمر حتى يزال وحتى يعين من هو خير منه، أما الصلاة فصحيحة ولو خلف المسبل على الصحيح، فإن ما جاء من الوعيد في حق المسبل لا يمنع صحة صلاته ولا يمنع صحة الصلاة خلفه، هو على كل حال لا يجوز له الإسبال لا في الصلاة ولا في خارجها، ولكن الصلاة خلفه صحيحة، وصلاته صحيحة لكنه آثم. نعم.\nالمقدم: وهذا الحديث الذي سمعناه؟\nالشيخ: نعم، هذا الحديث جاء، رواه أبو داود وغيره ولا بأس به، ولكنه من باب الوعيد. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6740/حكم-الصلاة-خلف-العاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_210/21006.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8695,"question":"يسأل أخونا عن إمام يصلي بالناس وليس على رأسه غطاء؟","title":"حكم من صلى بالناس وهو حاسر الرأس","answer":"الجواب: لا حرج في ذلك؛ لأن الرأس ليس من العورة، إنما السنة أن يصلي بالإزار والرداء، لقول النبي ﷺ: لا يصلي أحدكم في الثوب الواحد ليس على عاتقه منه شيء، فإذا صلى مكشوف الرأس فلا حرج في ذلك، لكن إذا أخذ زينته واستكمل الزينة يكون أفضل، لقول الله سبحانه: يَا بَنِي آدَمَ خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ [الأعراف:31] فإذا استكمل الزينة التي اعتادها في بلاده مع جماعته وكان من عادتهم أنهم يسترون الرءوس فهذا أفضل، أما إذا كان في بلاده ليس من عادتهم هذا بل من عادتهم كشف الرءوس فلا بأس أن يصلي مكشوف الرأس. نعم.","link":"https://binbaz.org.sa/fatwas/6842/حكم-من-صلى-بالناس-وهو-حاسر-الراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_131/13102.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8708,"question":"بالنسبة للإمام إذا كان يسقط عليه بعض الأحرف نظراً للتغة في لسانه ما رأيكم في هذا؟","title":"حكم إمامة الإمام الألتغ","answer":"الجواب: إذا كانت الفاتحة سليمة ولا يضيع منها شيء فلا بأس؛ لأن قراءة غيرها ليس بواجب بل مستحب وإنما الواجب قراءة الفاتحة فهو الركن، فإذا كانت الفاتحة سليمة يؤديها كما ينبغي فصلاته صحيحة ولا بأس بإمامته، وإن كان لا يستطيع ذلك فلا يكون إماماً يصلي مع الناس مأموماً. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6855/حكم-امامة-الامام-الالتغ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_132/13204.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8754,"question":"السؤال الأخير في رسالة الأخ (م. ق. ل) من جيزان يقول: هناك مسجد له إمام وهناك رجل في بعض الأحيان يصلي ويؤم الناس بدون إذن الإمام الراتب، فهل صلاته صحيحة؟","title":"حكم إمامة الناس في الصلاة دون إذن الإمام الراتب","answer":"الجواب: إذا كان الإمام قد يتأخر عن الموعد المعتاد وتقدم بعض المأمومين وصلى بالناس لا حرج صلاته صحيحة وصلاتهم صحيحة، لأن الرسول ﷺ لما تأخر صلى عبد الرحمن بن عوف ولم ينكر عليه النبي ﷺ، بل أقره على ذلك وصلى معه ما بقي من الصلاة، فقد ثبت عنه ﷺ: أنه كان في غزوة تبوك في صلاة الفجر تخلف لقضاء حاجته، فلما حضر وقت الصلاة وتأخر النبي ﷺ أقيمت الصلاة، وصلى بالناس عبد الرحمن بن عوف الزهري أحد العشرة المشهود لهم بالجنة، فجاء النبي ﷺ وقد صلى عبد الرحمن ركعة، فأراد أن يتأخر فأشار له النبي ﷺفكمل الصلاة وصلى معه النبي ﷺ الركعة التي بقيت، فلما سلم عبد الرحمن قام النبي ﷺ ومعه المغيرة بن شعبة فقضيا ما عليهما.\nفدل ذلك على أن الإمام إذا تأخر فإن الجماعة لا يعطلون قد يقدمون من شاءوا من أهل الخير، فيصلي بهم؛ حتى لا يتعطل الناس وهذا هو الحق، أما كون بعض الناس يتسرع ويقيم قبل أن يأتي وقت الصلاة فهذا غلط لا يجوز هذا، وليس لأحد أن يتقدم على الإمام الراتب قبل مجيء الوقت المعتاد. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6911/حكم-امامة-الناس-في-الصلاة-دون-اذن-الامام-الراتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_217/21708.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8805,"question":"السؤال السادس سماحة الشيخ من الأخ سعد موسى السويرق الصلاحي من الحجرة بلاد زهران يقول فيه: إذا أقيمت الصلاة ولم أقرأ مع المصلين سورة الفاتحة ولكن أدركت الركوع، وسمعت من الكثير من الناس أنه إذا لم تقرأ الفاتحة يلزمني أن لا أسلم مع الإمام ويلزمني إكمال الركعة التي لم أدرك فيها قراءة الفاتحة مع الإمام والمصلين، أفيدونا جزاكم الله خيراً؟","title":"كيفية إدراك الركعة من الصلاة","answer":"الجواب: الصواب في هذه المسألة أن المسلم إذا أدرك الإمام وهو راكع فإنه يركع معه وتجزئه الركعة، ولا يلزمه قضاؤها هذا هو الصواب، وهو الذي عليه جمهور أهل العلم، الأئمة الأربعة أبو حنيفة ومالك والشافعي وأحمد وجمهور أهل العلم كلهم يرون أن الركعة مجزئة. وأن صلاته صحيحة كاملة وليس عليه قضاء الركعة، والحجة في ذلك ما ثبت في صحيح البخاري رحمه الله عن أبي بكرة الثقفي رضي الله عنه أنه أتى النبي ﷺ وهو راكع فركع دون الصف ثم دخل في الصف، فلما سلم النبي ﷺ سأل عن ذلك فأخبر أبو بكرة أنه هو الفاعل، فقال النبي ﷺ: زادك الله حرصاً ولا تعد ولم يأمره بقضاء الركعة ولكن نهاه أن يعود عن الركوع دون الصف، وأمره أن يصبر حتى يصل الصف ثم يركع في الصف، فهذا هو الواجب أن المؤمن لا يعجل، فإذا جاء والإمام راكع لا يعجل حتى يصل الصف ثم يركع مع الناس، وتجزئه الركعة ويكون معذوراً في عدم قراءة الفاتحة؛ لأنه ما أدرك القيام، ومعلوم أن قراءة الفاتحة أمر مطلوب من المأموم وغيره، بل فرض كما قال النبي ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتابولكن هذا الذي أدرك الركوع معذور ؛ لأنه فاته القيام فصار معذوراً، هذا هو الصواب.\nوهكذا لو نسي القراءة وهو مع الإمام نسي القراءة المأموم، أو جهل حكمها يحسب أنها لا تلزمه، فإن صلاته صحيحة ومجزئة ولا يلزمه قضاء شيء.\nأما من علم حكم الله فإنه يقرأ الفاتحة ما دام أدرك القيام يقرؤها مع الإمام في سكوت الإمام، فإذا لم يسكت الإمام قرأها سراً في نفسه ثم أنصت، لقوله ﷺ: لعلكم تقرءون خلف الإمام؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب، فإنه لا صلاة لمن لم يقرأ بها هذا عموم يستثنى منه من أدرك الركوع لحديث أبي بكرة .\nوالقاعدة الشرعية: أن العام يخصص بالخاص، السنة العامة تخصص بالسنة الخاصة، وهكذا الآيات القرآنية العامة تخص بالآيات المخصصة وتخص بالسنة أيضاً، فحديث أبي بكرة يخصص عموم قوله ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب وبهذا يتضح للسائل أن الركعة مجزئة وأنه ليس عليه القضاء، هذا هو الصواب والذي عليه جمهور أهل العلم، وقد ذهب بعض أهل العلم أن عليه قضاء الركعة ولكنه قول مرجوح لما عرفت من الأدلة والله ولي التوفيق.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/6961/كيفية-ادراك-الركعة-من-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_222/22208.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":8860,"question":"رسالة وصلت إلى البرنامج من سوريا وباعثها أحد الإخوة من هناك يقول: (أ.ع.هـ) أخونا يقول: ما حكم من صلى بالناس جماعة وفيه جرح؟","title":"حكم صلاة الإمام بالمأمومين إذا كان فيه جرح","answer":"","link":"https://binbaz.org.sa/fatwas/7015/حكم-صلاة-الامام-بالمامومين-اذا-كان-فيه-جرح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_137/13703.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9010,"question":"رسالة وصلت إلى البرنامج من الأردن وباعثها أخونا محمد محمد عبد اللطيف من محافظة الشرقية، أخونا يقول: إننا مجموعة من العمال نصلي في السكن بينما المسجد يبعد عنا ما يقرب من كيلو متر فقط، هل صلاتنا صحيحة أم لا؟","title":"حكم ترك صلاة الجماعة بسبب بُعد المسجد","answer":"الجواب: الصلاة صحيحة لكنكم قصرتم في ترك الجماعة، والواجب عليكم أداؤها في الجماعة في بيوت الله ، كما قال الله سبحانه: فِي بُيُوتٍ أَذِنَ اللَّهُ أَنْ تُرْفَعَ وَيُذْكَرَ فِيهَا اسْمُهُ [النور:36]، وقال النبي عليه الصلاة والسلام في الحديث الصحيح: من سمع النداء فلم يأت فلا صلاة له إلا من عذر.\nفالواجب عليكم أن تبادروا إلى أدائها في الجماعة في بيوت الله، أما ما مضى فالصلاة صحيحة وعليكم التوبة والاستغفار، إذا كنتم تسمعون النداء لو كانت الأصوات هادئة سمعتم النداء العادي من المأذنة.\nولكن بكل حال فينبغي لكم أن تسارعوا إلى أدائها في الجماعة والحذر من التساهل في أدائها في السكن، والغالب أن الكيلو يسمع النداء إذا كانت الأصوات هادئة والمؤذن ذو صوت جيد، فالغالب أنه يسمع صوته من هذه المسافة، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/7168/حكم-ترك-صلاة-الجماعة-بسبب-بعد-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14703.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9065,"question":"اتسع الوقت شيخ عبدالعزيز لهذا السؤال من أخينا إسماعيل ناصر الهياف من حائل يسأل ويقول: بعض الناس يقولون: إن من يتحرك ثلاث حركات في الصلاة بطلت صلاته، هل هذا صحيح؟","title":"الحركة المبطلة للصلاة","answer":"الجواب: ليس بصحيح هذا قول بعض أهل العلم لكن ليس بصحيح، وإنما الذي يبطل الصلاة الحركة الكثيرة المتوالية عرفًا إذا كثرت الحركة وتوالت فهذا هو الذي يبطلها عند أهل العلم، كأن يعبث في ثيابه أو شعره عبثًا كثيرًا متواليًا أو بأخذ شيء وطرحه شيء متوالي كثير ليس له حد محدود بل يعتبر كثيرًا في العرف، هذا هو اللي يبطل الصلاة.\nفالواجب على المؤمن أن يطمئن في صلاته والمؤمنة كذلك، وأن يجتهد في ترك العبث والحركة إلا الشيء اليسير فيعفى عنه، وقد ثبت عنه ﷺ: أنه كان يصلي وهو حامل أمامة بنت زينب ابنة بنته، فإذا سجد وضعها وإذا قام حملها وثبت عنه ﷺ: أنه في صلاة الكسوف لما عرضت عليه الجنة تقدم خطوات ولما عرضت عليه النار تأخر خطوات، وثبت عنه أنه فتح الباب لـعائشة، هذا وأمثاله لا يضر، الشيء القليل الذي يعتبر قليلًا لا يضر في الصلاة، ولكن الشيء الكثير هو الذي يجتنب، وهكذا القليل إذا لم يكن له حاجة.\nيحرص المؤمن على السكون والهدوء في الصلاة وهكذا المؤمنة حتى يكملها، هذا هو المشروع للمؤمن والمؤمنة جميعًا، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7224/الحركة-المبطلة-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_178/17809.mp3","categories":["سجود السهو","مبطلات الصلاة"]},{"id":9082,"question":"بعض المأمومين يتابعون الإمام في المصحف أثناء قراءته؟","title":"حكم متابعة المأموم للإمام بالمصحف","answer":"الجواب: هذا سألني عنه غير واحد، والذي يظهر لي أنه لا ينبغي هذا وأن الأولى الإقبال على الصلاة والخشوع ووضع اليدين على الصدر اليمنى على اليسرى، على كف اليسرى ورسغها وساعدها متدبراً لما يقرأه الإمام ومنصتاً هكذا، الله يقول سبحانه: وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا [الأعراف:204]، والنبي ﷺ يقول: إذا قرأ الإمام فأنصتوا، فالسنة أن ينصت ولا يشتغل بشيء لا بالمصحف ولا بغيره، بل يضع يمينه على شماله على صدره خاشعاً مطمئناًَ منصتاً متدبراً متعقلاً لما يقرأه الإمام، هذا هو الأفضل والأولى، وأما الاستماع له بالمصحف فأقل أحواله الكراهة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7237/حكم-متابعة-الماموم-للامام-بالمصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_149/14913.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9095,"question":"هذه رسالة وصلت إلى البرنامج من الأخ المستمع: شريف خليفة أحمد سوداني مقيم بالرياض، الرسالة تحتوي على العديد من الأسئلة، يقول في سؤاله الأول: هل من الممكن أن أصلي جماعة أنا وأولادي وأيضاً مع زوجتي؟ أفيدونا أفادكم الله.","title":"حكم الصلاة بالأولاد والأهل جماعة في البيت","answer":"الجواب: نعم، لا بأس أن تصلي جماعة مع أولادك وزوجتك في النوافل، مثل صلاة الليل بعض الأحيان، مثل صلاة الضحى بعض الأحيان، لا بصفة راتبة ولكن بعض الأحيان، كما فعله النبي ﷺ في بيت أنس ، فصلى بـأنس واليتيم خلفه وأم سليم خلفهم، وصلى في بيت عتبان صلاة الضحى جماعة لما زاره عليه الصلاة والسلام لا بأس بهذا، وهكذا لو فاتت الفريضة.. فاتتك صلاة الفريضة في المسجد لأنك شغلت عن ذلك، بمرض أو غيره، ورجعت إلى البيت لا بأس أن تصلي بأولادك وأهلك الجماعة، ولكن ليس لك أن تتأخر عن الجماعة لا يجوز لك أن تتأخر عن الجماعة، بل يجب عليك أنت وأولادك يجب عليكم جميعاً أن تخرجوا إلى المساجد وأن تصلوا مع الناس، لقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر.\nوقد ثبت في الصحيحين أنه صلى الله عليه وسلم هم أن يحرق على المتخلفين عن الصلاة في الجماعة بيوتهم، وروي عنه عليه السلام أنه قال: لولا ما في البيوت من النساء والذرية لحرقتها عليهم فهذا يدل على أن تخلفهم أمر ممنوع، وأنهم يستحقون أن يحرق عليهم بيوتهم بسبب تخلفهم عن هذا الواجب، وجاءه رجل أعمى عليه الصلاة والسلام يقول له: يا رسول الله، إنه ليس لي قائد يلائمني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له عليه الصلاة والسلام: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب وفي لفظ قال له: لا أجد لك رخصة فإذا كان أعمى، ليس له قائد يلائمه ليس له رخصة فكيف بحال غيره.\nفالمقصود أن الواجب على كل مسلم أن يصلي في المساجد مع الناس، هو وأولاده ومن تحت يده من أيتام أو خدام يصلون في المساجد مع المسلمين، وليس له أن يصلي في بيته، لكن لو شغل عن هذا بمرض ... مريض صلى مع زوجته لا بأس، أو مع أولاده الصغار ليس عليهم جماعة لا بأس، أو أناس مرضى صلوا معه جماعة لا بأس، أما الأقوياء فيلزمهم أن يصلوا في المساجد، وليس لهم التخلف إلا بعذر شرعي كالمرض. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7261/حكم-الصلاة-بالاولاد-والاهل-جماعة-في-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_227/22706.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9111,"question":"من صحت صلاته لنفسه صحت لغيره، هل ولو كان يقر البدع؟","title":"حكم إمامة المبتدع","answer":"الجواب: نعم، إذا كانت بدعة لا تكفره البدعة لا تكفره بدعة تعتبر معصية لا تعتبر كفرًا أكبر فيصلى خلفه، أما إذا كانت بدعته تكفره كالذي يعبد الأموات ويستغيث بالأموات هذا يسمى بدعة وهو شرك أكبر فهذا لا يصلى خلفه، وهكذا إذا كانت بدعته تضمن كفرًا مثل بدعة أهل وحدة الوجود الذين يقولون: ليس هناك عابد ومعبود بل يرون عين الإله المعبود هو عين المخلوق، وهذا كفر أكبر نعوذ بالله.\nالحاصل أن البدع التي لا تكفر يصلى خلف صاحبها، وإذا هجر حتى يتوب حسن، هذا حسن كونه يهجر ويصلى خلف غيره حتى يتوب لعله يتوب هذا طيب، لكن لو صلى خلفه وهو ليس بكافر فإن الصلاة صحيحة كما يصلى خلف العاصي، هذا في أصح قولي العلماء رحمة الله عليهم، وقد صلى بعض الصحابة كـابن عمر  خلف الحجاج بن يوسف الثقفي الظالم وهو من أظلم الناس وأفسقهم، وصلى خلفه جم غفير من السلف الصالح في الحج فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/7269/حكم-امامة-المبتدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_179/17905.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9122,"question":"السؤال الثاني في رسالة الأخ (ن. م) من مدينة الرمادي يقول فيه: ما حكم من صلى مع إمام حلق لحيته، هل صلاة المأموم صحيحة أم لا، أفيدونا جزاكم الله خيراً؟","title":"حكم الصلاة خلف حالق اللحية","answer":"الجواب: اختلف العلماء رحمة الله عليهم في الصلاة خلف الإمام الفاسق للمعاصي، كالمرابي ومن عرف بشيء من المعاصي الكبيرة كالعقوق للوالدين، وقطيعة الرحم وشهادة الزور ونحو ذلك، هل تصح الصلاة خلفهم، على قولين لأهل العلم، والصواب: أنها تصح الصلاة خلفهم؛ لأن الرسول ﷺ قال في الأمراء: يصلون لكم فإن أحسنوا فلكم ولهم وإن أساءوا فلكم وعليهم ولم يأمرهم بإعادة الصلاة خلفهم وفيهم الفاسق وفيهم غيره.\nولأن الصحابة كـابن عمر صلى خلف الحجاج بن يوسف الثقفي أمير العراق وكان من أفسق الناس وأظلم الناس.\nفالصواب: أن الصلاة خلف الفاسق صحيحة أما خلف الكافر فلا، خلف الكافر المعروف بالكفر كالذي يسب الدين أو يتعلق بالأموات ويدعوهم من دون الله أو ما أشبه ذلك من أنواع الكفر هذا لا يصلى خلفه، وأما الفاسق وهو المسلم العاصي فهذا الصلاة خلفه صحيحة، وحالق اللحية من هؤلاء من الفسقة، إذا أصر على ذلك ولم يتب فهو من الفسقة يعني: من العصاة فالصلاة خلفه صحيحة، ولكن ينبغي أن لا يتخذ إماماً، ينبغي للمسئولين أن يلتمسوا إماماً أصلح منه مع القدرة، حتى لا يؤم الناس إلا خيارهم، نسأل الله للمسلمين العافية والسلامة. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7280/حكم-الصلاة-خلف-حالق-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_228/22805.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9125,"question":"هذه رسالة وصلت إلى البرنامج من المستمع (أ. أ. ع) من العراق يقول في بدايتها: بسم الله الرحمن الرحيم، السلام عليكم ورحمة الله وبركاته، تحية إلى برنامجكم الموقر وبعد، سؤالي الأول: إذا صلى شخص واكتشف بعد الصلاة أن شيئاً قد نزل منه، فهل عليه إعادة للصلاة أم لا أفيدونا أفادكم الله؟","title":"حكم من اكتشف نزول شيء منه بعد الصلاة","answer":"الجواب: إذا صلى الإنسان ثم اكتشف بعد الصلاة أنه خرج منه بول أو مذي ففيه تفصيل: إن تيقن أن هذا خرج في الصلاة فعليه الإعادة، عليه أن يتوضأ، يستنجي من البول أو من المذي ويغسل ذكره وأنثييه من المذي ويعيد الوضوء الشرعي ويعيد الصلاة، أما إن كان عنده شك لا يدري هل هذا خرج في الصلاة أو بعد الصلاة فليس عليه إعادة، إذا كان عنده شك في هذا البول الذي رأى أثره أو المذي هل كان في الصلاة أو كان خروجه بعد الصلاة فلا إعادة عليه.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7290/حكم-من-اكتشف-نزول-شيء-منه-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_229/22904.mp3","categories":["سجود السهو","مبطلات الصلاة"]},{"id":9127,"question":"السؤال الثاني في رسالة الأخ خالد علي من جمهورية السودان يقول فيه: هل يجوز لي أن أصلي في بيتي أم ماذا أفعل، أفيدونا أفادكم الله؟","title":"حكم الصلاة في البيت","answer":"الجواب: عليك أن تصلي في المساجد مع إخوانك المسلمين إذا كان فيها إمام يرضى دينه، فإذا كان ليس فيها إمام فصل مع بعض إخوانك الطيبين في بيتك أو في أحد بيوتهم، إلا أن يوجد مسجد طيب تتمكنون من الصلاة فيه بإمام صالح فهذا واجب عليكم أن تلتمسوا مسجداً فيه إمام صالح أو يمكن أن يؤمكم فيه بعضكم حتى تصلوا فيه صلاة الجماعة وتقيموا فيه شعيرة الله جل وعلا بالأذان والإقامة، أما إذا كان الأئمة الذين حولكم كلهم مشركون، كلهم يدعون الأموات ويستغيثون بالأموات وينذرون للأموات، فهؤلاء لا يصلى خلفهم، بل تصلي في بيتك أو تصلي مع إخوانك في أحد بيوتهم جماعة إذا أمكن ذلك حتى يوجد مسجد تستطيعون فيه إقامة الصلاة خلف إمام صالح. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7296/حكم-الصلاة-في-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_229/22908.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9182,"question":"من الإمارات العربية المتحدة هذه رسالة بعثها أحد الإخوة المستمعين يقول: أحمد جليدان أخونا يسأل مجموعة من الأسئلة في سؤاله الأول يقول: إذا سهوت في صلاة نافلة مثل تحية المسجد أو بعض الرواتب أو في القيام -أي التراويح- في رمضان هل أسجد سجدتين للسهو أم لا يلزم ذلك؛ لأنها نافلة؟","title":"حكم سجود السهو في صلاة النافلة","answer":"الجواب: حكم النافلة كالفريضة، فإذا سها المسلم في النافلة سهوًا يقتضي سجود السهو فإنه يفعل ذلك في النافلة، فلو مثلًا نسي سجدة من السجدات وقام فإنه يرجع ويأتي بالسجدة، ثم يسجد للسهو قبل أن يسلم ثم يسلم، وهكذا لو سلم ناسيًا التحيات ثم ذكر فإنه يعود ويأتي بالتحيات ثم يسجد للسهو ويسلم، أو يسلم ويسجد سجدتي السهو بعد السلام، كل ذلك جائز؛ لأن حكمها حكم الفريضة في هذا الباب. نعم.","link":"https://binbaz.org.sa/fatwas/7342/حكم-سجود-السهو-في-صلاة-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_180/18006.mp3","categories":["سجود السهو"]},{"id":9184,"question":"هل صلاة الجماعة واجبة أم سنة؟ وما هو تفسير قوله تعالى أعوذ بالله من الشيطان الرجيم: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43] وكثير من الناس يتساهلون في صلاة الجماعة وهم يسمعون النداء وقريبين من المسجد، ما الحكم في هذا، وهل تقبل صلاة من يسمع النداء ولم يذهب إلى المسجد؟","title":"صلاة الجماعة فريضة ويجب أداؤها في المساجد","answer":"الجواب: صلاة الجماعة فريضة، والواجب على من سمع النداء أن يجيب المؤذن وليس له أن يصلي وحده ولا في البيت ولو جماعة في البيت ليس لهم ذلك، بل الواجب أن يصلوا مع المسلمين في المساجد في بيوت الله عز وجل، كما قال النبي الكريم عليه الصلاة والسلام: من سمع النداء فلم يأت فلا صلاة له إلا من عذر وسأله عليه الصلاة والسلام رجل أعمى فقال: يا رسول الله! ليس لي قائد يلائمني إلى المسجد فهل من رخصة أن أصلي في بيتي؟ فقال عليه الصلاة والسلام: هل تسمع النداء بالصلاة؟ قال:نعم. قال: فأجب خرجه مسلم في صحيحه، وفي الرواية الأخرى: لا أجد لك رخصة.\nوثبت في الصحيحين أنه عليه الصلاة والسلام أنه هم أن يحرق على المتخلفين بيوتهم، فدل ذلك على أن أداءها في المساجد مع المسلمين أمر مفترض وليس له أن يصلي وحده ولا في بيته بل عليه أن يشارك إخوانه المسلمين ويجيب المنادي، ومن ترك ذلك فقد أشبه المنافقين في هذا العمل، وقد اختلف العلماء رحمة الله عليهم هل تصح صلاته؟ على قولين:\nفالأكثرون على أنها تصح مع الإثم.\nوقال بعض أهل العلم: إنها لا تصح، كونه يصلي وحده ويدع الجماعة، فالواجب على المؤمن أن يحذر التخلف وأن يصلي مع إخوانه المسلمين، وأن يبتعد عن مشابهة المنافقين، والله المستعان. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7344/صلاة-الجماعة-فريضة-ويجب-اداوها-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_180/18008.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9203,"question":"شخص دخل في الصلاة والناس جلوس في التشهد الأخير وجلس معهم، وبعد تسليم الإمام أكمل الصلاة، هل يحصل على أجر الجماعة، وإذا لم يحصل على أجر الجماعة فما هو أجره على ذلك؟","title":"حكم المأموم إذا أدرك الجماعة وهم في التشهد الأخير","answer":"الجواب: النبي ﷺ قال: إذا أتيتم الصلاة فلا تأتوها وأنتم تسعون وأتوها وعليكم السكينة، فما أدركتم فصلوا وما فاتكم فأتموا، فالمشروع له إذا جاء وهم في الجلوس في التشهد الأخير أن يدخل معهم ويجلس معهم مكبراً، يكبر وهو واقف تكبيرة الإحرام ثم يجلس ويقرأ التحيات معهم، فإذا سلم إمامه قام وقضى صلاته كملها، أما هل يحصل له فضل الجماعة فهذا فيه التفصيل:\nإن كان معذوراً بأن تأخر لعذر شرعي كقضاء الحاجة التي نزلت به فذهب يتوضأ، أو شغله شاغل لا حيلة فيه فله أجر الجماعة؛ لأن المشغول والمعذور بالعذر الشرعي حكمه حكم من حضر، لقوله ﷺ: إذا مرض العبد أو سافر كتب الله ما كان يعمل وهو صحيح مقيم، ولقوله ﷺ في غزوة تبوك: إن في المدينة أقواماً ما سرتم مسيراً ولا قطعتم وادياً إلا وهم معكم، وفي اللفظ الآخر: إلا شركوكم في الأجر، قالوا: يا رسول الله! وهم في المدينة؟ قال: وهم في المدينة، حبسهم العذر، وفي لفظ: حبسهم المرض، فدل ذلك على أن من حبسه عذر شرعي يكون له أجر من عمل العمل على الوجه الشرعي.\nأما إن كان تأخر عن تساهل فإنه لا يحصل له فضل الجماعة، وقد قال عليه الصلاة والسلام: من أدرك ركعة من الصلاة فقد أدرك الصلاة، من أدرك ركعة أدرك فضل الجماعة، وإن لم يدرك الركعة لم يدرك فضل الجماعة إذا كان عن تساهل وعدم عذر شرعي، والله المستعان.","link":"https://binbaz.org.sa/fatwas/7363/حكم-الماموم-اذا-ادرك-الجماعة-وهم-في-التشهد-الاخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_151/15109.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9257,"question":"الرسالة التالية وصلت إلى البرنامج من الرياض وباعثتها إحدى الأخوات المستمعات تقول: (ن. ح. ص) أختنا تقول: حجيت الفريضة مع والدي وعمري عشرون عاماً، وفي أثناء الطواف أو السعي تقام الصلاة وأصلي مع الإمام وأنا لا أعلم هل الوقت هو وقت الظهر أو العصر؛ لأني كنت مرتبكة من الخوف وكثرة الحجاج.ثانياً: طفت طواف الوداع وأنا على غير طهر وأعلم أن التي على تلك الحالة لا يسقط عنها طواف الوداع","title":"حكم من صلى خلف إمام بنية مترددة بين صلاتين","answer":"الجواب: أما الصلاة التي صليتيها مع الإمام وأنت لا تعرفين ما هي هل هي الظهر أو العصر فعليك أن تعيدي الصلاتين صلاة الظهر وصلاة العصر التي لم تتحققي من فعلها ذلك اليوم بالنية عن ذلك اليوم، تعيدين الصلاة عن ذلك اليوم صلاة الظهر وصلاة العصر، وأما طوف الوداع الذي طفتيه وأنت على غير طهارة فعليك دم؛ لأنك ما طفت في الحقيقة، الطواف بغير وضوء غير شرعي ولا يجزي، فعليك ذبيحة تذبح في مكة للفقراء توكلين شخصاً ثقة من أهل مكة أو من المتوجهين إليها للعمرة أو للحج حتى يذبحها عنك بالنية عن طوف الوادع والحمد لله.\nأما ما يتعلق بالمدينة فليس عليه شيء؛ لأنك أخطأت ولكن ليس عليك قضاء شيء، فإن صليت دخلت المسجد النبوي وأنت على غير طهارة فليس عليك شيء، لكن إن كنت صليت بغير طهارة صلاة الفريضة فعليك أن تعيديها، أما مجرد دخولك المسجد من دون طهارة فليس عليك عنه شيء. نعم.\nالمقدم: بارك الله فيكم، هذا الاستحياء الذي يذكره كثير من أخواتنا المستمعات لعل لسماحة الشيخ توجيه بخصوصه؟\nالشيخ: نعم، لا يجوز الحياء في مثل هذا، هذا الحياء ليس بعذر، والله لا يستحيي من الحق سبحانه وتعالى، فإذا كانت المرأة وقت الطواف أو وقت الصلاة على غير طهور تقول: أنا على غير طهور كالرجل تذهب إلى زمزم إلى محل آخر تتوضأ للصلاة ولا تصلي بغير طهارة ولا تطوف بغير طهارة هذا ليس فيه حياء كل الناس يحدثون؛ المرأة والرجل، كل واحد يقع منه الحدث الرجل والمرأة والصغير والكبير حتى الأنبياء إذا أحدثوا توضئوا وهم أشرف الناس.\nفالحاصل أن هذا ليس فيه حياء، ولما سألت أم سليم النبي ﷺ عن الاحتلام قالت: يا رسول الله! إن الله لا يستحي من الحق فهل علىى المرأة من غسل إذا هي احتلمت؟ فقال النبي ﷺ: نعم، إذا هي رأت الماء والله يقول: وَاللَّهُ لا يَسْتَحْيِي مِنََ الْحَقِّ [الأحزاب:53].\nفالمقصود: أن الواجب على المؤمن أن يقول الحق ولا يستحيي، وهكذا المؤمنة عليها أن تقول الحق ولا تستحيي في هذا سواء كان في مسألة الوضوء أو غسل الجنابة أو غير ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7420/حكم-من-صلى-خلف-امام-بنية-مترددة-بين-صلاتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_153/15306.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9265,"question":"هنا رسالة وصلت إلى البرنامج من الأخ علي بن سليمان من مكة - المعابدة، أخونا عرضنا بعض أسئلته في حلقة مضت وفي هذه الحلقة يسأل ويقول: إذا صلى المرء الصلاة الرباعية ولم يسجد في إحدى ركعاتها إلا سجدة واحدة فهل يجزيه سجود السهو أو يأتي بركعة ثم يسجد للسهو بعدها؟","title":"الواجب على من نسي سجوداً في صلاته","answer":"الجواب: إذا أسقط المصلي سجدة ساهياً فإنه يأتي بها في الحال فإن لم يذكر إلا بعد ذلك بعدما قام وشرع في القراءة فإنه يكمل صلاته ويأتي بزيادة ركعة، يضيف ركعة أخرى كاملة بدل الركعة التي ترك سجودها، ثم يسجد للسهو قبل أن يسلم ويسلم، وأما إن ذكر في الحال حين رفعه من السجود فإنه يسجد، يعود ويسجد الثانية، ويسجد للسهو بعد ذلك إذا كان قد قام، أما إذا كان قبل أن يقوم يسجد الثانية ولا سهو عليه. نعم.\nالمقدم: إذا سجد للسهو ثم جلس للسلام إلا أنه قرأ التحيات وربما انتصفها أو انتهى منها، فكيف يفعل هل يسجد لها سهواً أو يسلم؟\nالشيخ: إذا قرأ التشهد بعد سجوده للسهو لا يضره، ما يضر. نعم.","link":"https://binbaz.org.sa/fatwas/7428/الواجب-على-من-نسي-سجودا-في-صلاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_154/15403.mp3","categories":["سجود السهو"]},{"id":9342,"question":"يسأل أيضاً ويقول: لنا إمام راتب في مسجد قريتنا لكنه يترك بعض سنن الصلاة عمداً، فمثلاً يرفض قبض يديه، ويرفض التسليمة، فيخرج من الصلاة بالسلام عليكم فقط، وقد نصحه بعض الإخوة أكثر من مرة لكنه رفض وقال: أنا مالكي المذهب لا يجوز لي القبض ولا يجوز لي السلام عليكم ورحمة الله يميناً وشمالاً، أفيدونا هل الصلاة خلفه جائزة أم لا؟","title":"حكم الصلاة خلف إمام لديه عدة أخطاء وجهل","answer":"الجواب: هذا على كل حال يجب أن ينصح ويسأل أهل العلم، والمذاهب غير ملزمة لأهلها، التقليد غير جائز بل يجب على المؤمن وعلى طالب العلم أن يأخذ بالحق، ولا يحتج بمذهب مالك أو الحنبلي أو الشافعي أو الحنفي هذا غلط كبير في حق طالب العلم، بل يجب على طالب العلم أن يتحرى الأدلة، وأن يتحرى الصواب حتى يأخذ به، وقد ثبت عن رسول الله ﷺ أنه قبض، وثبت عنه ﷺ أنه كان يسلم تسليمتين، فكيف يجوز لمسلم أن يخالف الرسول ﷺ لقول مالك، هذا لا يجوز أن يقوله عاقل مسلم، مالك واحد من العلماء لا يجوز أن يؤخذ قوله إذا خالف قول الرسول ﷺ، وهكذا قول الشافعي أو أبي حنيفة أو أحمد أو الثوري أو الأوزاعي أو غيرهم، هؤلاء أئمة علماء رضي الله عنهم ورحمهم، لكن أقوالهم تعرض على الكتاب والسنة، فإن وافقت أخذت لأنها وافقت الحق، وإن خالفت فالواجب أخذ الحق والعمل به مع من قاله، فإذا كان مذهب الشافعي وافق الحق وأنت مالكي، عليك أن تأخذ بقول الشافعي لأنه وافق الحق، وهكذا مذهب أحمد وهكذا أبي حنيفة ، إذا وافق الحق تأخذ به، وتخالف قول مالك ؛ لأن مالك رحمه الله يدعو إلى هذا فيقول: ما منا إلا راد ومردود عليه إلا صاحب هذا القبر.\nوهكذا بقية الأئمة كلهم يقولون: يجب على المسلم أن يقبل الحق وأن يأخذ به، وأن لا يقلدهم فيما خالف الحق، هذا الإمام قد غلط وجهل فعليه أن يراجع الحق ويراجع كلام أهل العلم، وعليه أن ينصاع للنصاحين، فيسلم تسليمتين، وهذا لازم وكذلك يشرع له القبض، فيضع اليمنى على كفه اليسرى على صدره، أما ما نقله ابن القاسم عن مالك من الإرسال فهذا حمله بعض أهل العلم على أنه بسبب ما أصاب يديه، وعجز عن ضمهما، أو كان قد بدا له شيء فغلط، وكل إمام له غلطات وله أخطاء، والسنة هي المعصومة التي جاء بها الرسول ﷺ، فالواجب الأخذ بها متى ثبتت، لقول الله : فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59]، ولقوله سبحانه: فَلا وَرَبِّكَ لا يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لا يَجِدُوا فِي أَنفُسِهِمْ حَرَجًا مِمَّا قَضَيْتَ وَيُسَلِّمُوا تَسْلِيمًا [النساء:65].\nفنصيحتي لهذا الإمام أن يتقي الله وأن يرجع إلى الصواب، وصلاته معه صحيحة؛ لأنه متأول وهو مقلد وجاهل في هذه المسألة، لكن إن استقام ورجع إلى الصواب وإلا فاسعوا في عزله وإبعاده لخطئه الكبير، فلا يصلح للإمامة وهو بهذا الرأي، وبهذا التقليد الأعمى، والله المستعان.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7509/حكم-الصلاة-خلف-امام-لديه-عدة-اخطاء-وجهل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_238/23806.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9407,"question":"أخونا أيضًا يقول: يلحظ على المصلين أن الواحد يبعد عن الثاني بما يعادل طول قدم، ويرجو التوجيه والنصيحة جزاكم الله خيرًا؟","title":"ترك الفرج بين الصفوف في الصلاة","answer":"الجواب: الواجب على المسلمين في الصفوف التراص والتقارب ولا يجوز ترك الفرج؛ لقول النبي ﷺ: تراصوا كان يأمرهم عند الدخول في الصلاة أن يتراصوا، وأن يسدوا الفرج، فوجب على المسلمين الامتثال وأن يسدوا الفرج وأن يتراصوا، فيلزق قدمه بقدم جاره ويتقاربون جميعًا حتى لا يكون بينهم فرج، وبعض الناس قد يؤذي جيرانه يتوسع يلصق أقدامه بأقدام إخوانه لكن يحصل بذلك بعض الأذى.\nفالسنة أن يستقيم في وقوفه وأن يجذب أخاه إليه من هنا وهنا حتى يتراصوا، وحتى لا يؤذيهم بشيء، يستقيم ويجر أخاه إليه من هنا ومن هنا حتى يسدوا الفرجة ولا يفسح ويمد رجليه من هنا ومن هنا من أجل لصق قدمه بقدمهم، لا؛ بل يعلمهم السنة بأن يستقيم في وقفته ويجر هذا الذي عن يمينه وعن شماله حتى يسدوا الفرجة برفق وحكمة حتى لا يكون هناك شقاق ونزاع، وحتى تحصل السنة التي دعا إليها النبي عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/7571/ترك-الفرج-بين-الصفوف-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_189/18903.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9421,"question":"إذا دخلت المسجد وقد فاتتني الصلاة ووجدت أولادًا صغارًا يصلون في جماعة وإمامهم عمره عشر سنوات تقريبًا، هل أصلي معهم؟","title":"هل يجوز الصلاة خلف إمام عمره عشر سنوات؟","answer":"الجواب: نعم، صل معهم، يجوز أن يكون الإمام ابن عشر سنين أو أقل أو أكثر، فقد ثبت أن عمرو بن سلمة الصحابي الجليل صلى بأصحابه وهو ابن سبع سنين؛ لأنه كان أكثرهم قرآنًا، فلا بأس أن يكون الإمام دون البلوغ كابن عشر وابن ثمان وابن إحدى عشرة ونحو ذلك.\nوليس من شرط الإمامة التكليف، المهم أن يكون يحسن الصلاة، ويحسن القراءة، فإذا وجدت إمامًا دون التكليف يصلي بالناس صل معهم، ولا تقل هذا صغير، فقد ثبت في صحيح البخاري عن عمرو بن سلمة  أنه ذكر عن النبي ﷺ أنه قال: إذا حضرت الصلاة فليؤذن لكم أحدكم، وليؤمكم أكثركم قرآنًا، قال: فنظروا -نظر قومه- فلم يجدوا أحدًا أكثر مني قرآنًا، فقدموني وأنا ابن ست أو سبع سنين فالرواية تحمل على أنه كان ابن سبع؛ لأن الرسول عليه الصلاة والسلام قال: مروا أبناءكم بالصلاة لسبع واضربوهم عليها لعشر فأقل سن تكون فيه الإمامة وأن يؤمر فيه بالصلاة والوضوء هو السبع فما فوق، وهذا الحديث الصحيح حجة في ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7586/هل-يجوز-الصلاة-خلف-امام-عمره-عشر-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_190/19007.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9547,"question":"يقول السائل أيضاً: إن والدي كبير ولا يذهب لصلاة الجمعة، ويقول: إنه مريض عندما سألته عن ذلك بمرض هو عبارة عن بخر في الفم ورائحة كريهة، وقال: إنه لا يريد أن يؤذي الناس بهذه الرائحة، فهل يجوز فعله هذا؟","title":"حكم ترك صلاة الجمعة والجماعة لصاحب الرائحة المؤذية","answer":"الجواب: نعم، هذا عذر شرعي، إذا كان به بخر شديد الرائحة الكريهة ولم يتيسر له ما يزيله فهو عذر، كما أن البصل والكراث عذر، فالبخر قد يكون شديد الرائحة الكريهة قد يؤذي من حوله من يمينه وشماله، فإذا كان هذا البخر شديداً يؤذي من حوله ولم يجد له دواء ولا حيلة فهو معذور، أما إن وجد دواء أو وجد حيلة تزيله فعليه أن يفعل ذلك حتى لا يتأخر عن صلاة الجمعة والجماعة، ولكن متى عجز عن ذلك ولم يتيسر فهو معذور أشد من عذر صاحب البصل، لأن صاحب البصل يستطيع أن يدع البصل والكراث، فأما هذا فلا يستطيع إذا عجز عن الدواء، والبخر لا شك أنه يؤذي من حوله إذا كانت رائحته ظاهرة وهكذا ... الآباط إذا كان شديد ... ولم يستطع زواله بالصابون والدواء إذا كان يعالجه ولم يزل فهذا عذر أيضاً، أما إذا استطاع إزالته بالغسل والبخور والأدوية الأخرى التي تزيل أثره من الآباط، فالواجب عليه فعل ذلك حتى يصلي مع المسلمين، وهكذا صاحب الدخان يجب عليه أن يزيل أثر الدخان من فمه بكل ما يستطيع، وأن يكون قرب الصلاة لا يتحرى هذا حتى لا يؤذي من حوله، فإذا كان هناك بقية استعمل ما يزيل بقية الرائحة من الأدوية أو أشياء تمضغ أو غير ذلك مما يزيل رائحته حتى لا يؤذي أحداً، نعم. والدخان ... قبيح منكر يجب تركه، ولا تجوز التجارة فيه لا بيعاً وشراءً، لكن من بلي به فليتق الله وليستعن بالله على تركه وليحذر شره وبلاءه وما دام يتعاطاه فليحذر أن يأتي به المسجد وهو رائحته ظاهرة؛ بل يتعاطى ما يزيل الرائحة ويجتهد حتى يعافيه الله من شره وحتى يجد حيلة في تركه. نعم.\nالمقدم: بارك الله فيكم، الحقيقة يا سماحة الشيخ! أن كثيراً من الرجال يتساهلون في موضوع طيب الرائحة عند الصلاة، ومنهم من يعني يأتي وعليهم ملابس العمل أو ملابس مثل ما تفضلتم فيها رائحة كريهة فلا أدري يعني بماذا توجهون في هذا؟\nالشيخ: الواجب على المؤمن أن يحرص على طيب الرائحة، كان النبي صلى الله عليه وسلم يحب الطيب ويتعاطى الطيب عليه الصلاة والسلام، فإذا أمكنه أن يتعاطى ما يزيل الرائحة فليفعل، لكن في حال العمل قد لا يتمكن فليتق الله ما استطاع، أما إذا تمكن من إزالة الرائحة الكريهة من رائحة الدخان أو الآباط أو البخر فليتق الله وليعمل حتى لا يتأخر عن جمعة ولا عن جماعة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7707/حكم-ترك-صلاة-الجمعة-والجماعة-لصاحب-الراىحة-الموذية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_246/24606.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9565,"question":"يقول: إذا دخل المسجد شخص والصف كامل خلف الإمام ولم يتأخر معه أحد من الصف، هل يصلي منفرداً؟","title":"حكم صلاة الرجل منفرداً خلف الصف","answer":"الجواب: عليه أن يعتني بالمقام، فإن كثيراً من الناس إذا دخلوا والناس يصلون لا يعتني بالمقام، فلو اجتهد فهو في الغالب يجد فرجة يصلي فيها، فإن لم يجد صلى مع الإمام إن أمكن عن يمين الإمام ولا يصلي وحده خلف الصف ولا يجذب أحداً؛ لأن الرسول ﷺ قال: لا صلاة لمنفرد خلف الصف، ولم يرد في حديث صحيح ما يدل على شرعية الجذب، ولأن الجذب يفتح فرجة في الصف، والواجب سد الخلل وعدم إيجاد فرجة في الصف، فعلى الداخل أن ينتظر إن لم يجد فرجة، فإن وجد أحد يصلي معه فالحمد لله وإلا صلى وحده بعد السلام بعد سلام الإمام.\nوالغالب أنه متى اجتهد في مراصة الصف وتتبع خلل الصف فإنه في الغالب يجد فرجة ولو في نهاية الصف حتى يصلي في الصف، لكن لو فرضنا أنه لم يجد شيئاً ولم يتمكن من الإمام أن يصلي عن يمينه فإنه يبقى ينتظر حتى يصلي وحده بعد الإمام أو يأتي إنسان فيصلي معه في صف مستقل.\nوالحجة كما تقدم أن النبي ﷺ قال: لا صلاة لمنفرد خلف الصف، وثبت عنه عليه السلام: أنه رأى رجلاً يصلي خلف الصف وحده فأمره أن يعيد الصلاة فدل ذلك على أن الواحد لا يقف خلف الصف ولا خلف الإمام، بل إن كان الإمام ليس معه أحد وقف عن يمينه، وإن كان معه صفوف التمس فرجة في الصف، فإن وجد فالحمد لله، وإلا انتظر حتى يجد أو تقدم فصف عن يمين الإمام إذا أمكنه ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7735/حكم-صلاة-الرجل-منفردا-خلف-الصف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_247/24707.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9569,"question":"يقول: يوجد اثنان في صلاة العصر يصليان جماعة، فجاءهم فرد ثالث بعد دخولهما في الصلاة فتقدم الإمام لأنه لا يوجد مكان بالخلف حتى يرجع أحد المأمومين أو أحد الرجلين، فهل يجوز للإمام أن يتقدم خاصة أننا نعلم من الحديث أن رسول الله ﷺ وجه بأن يتأخر واحد من الشخصين ولا يتقدم الإمام؟","title":"كيفية تقدم الإمام في الصلاة إذا دخل ثالث","answer":"الجواب: إن كان الإمام في محل يمكنه أن يصلي فيه ويتأخران تأخرا، وإذا كان الإمام في محل لا يمكنهما التأخر فيه تقدم هو ولا حرج فلا بأس، المهم وجود السعة في المكان، فإن كانت السعة خلفه تأخر الذي معه مع الآخر وصليا خلفه، مثلما فعل النبي ﷺ فإنه كان يصلي فجاء جابر وجبار فصفا عن يمنيه وشماله فأخرهما وجعلهما خلفه، وهكذا قصته مع أنس واليتيم جعلهما خلفه، أما إذا كان قد صف على الجدار كلهم على الجدار اللي خلفهم والسعة أمامهم فإنه يتقدم هو يتقدم الإمام فيصلي بهم، هذا هو المشروع. نعم.\nالمقدم: بارك الله فيكم، وجزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7731/كيفية-تقدم-الامام-في-الصلاة-اذا-دخل-ثالث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_247/24703.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9578,"question":"أولى رسائل هذه الحلقة وردت من السائل عبد الله بن ناصر بن سيف من الدلم يقول فيها: إذا دخل المسجد عدة أشخاص ووجدوا شخصاً يصلي منفرداً ومضى بعض صلاته، هل يقتدون به إماماً لهم، أو يتقدم بهم واحد منهم؟ أفيدونا أفادكم الله.","title":"حكم أداء صلاة جماعة وفي المسجد رجل يصلي منفرداً","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن المشروع لهؤلاء الداخلين أن يصلوا جماعة، بل هذا هو الواجب عليهم، فإن رأوا من سبقهم أهلاً للإمامة وقدموه وصلوا خلفه فهو أفضل حتى يكون الجمع أكثر، وإن رأوه ليس بأهل لذلك فصلوا وحدهم واتخذوا إماماً منهم أصلح للإمامة من ذاك الأول الذي سبقهم فذلك أفضل وأولى. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7733/حكم-اداء-صلاة-جماعة-وفي-المسجد-رجل-يصلي-منفردا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_247/24705.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9599,"question":"يقول أيضاً: كنت ضيفاً على بعض الإخوة، فأدركت عندهم صلاة العصر، فسألتهم عن المسجد: هل هو قريب أم بعيد؟ فأجابوني: بأنه بعيد قليلاً، وقالوا: أحسن أن نصلي في المنزل جماعة، وأنا في إمكاني الذهاب للمسجد ولكنني خشيت أن يتفرق إخوتي، فمنهم من يذهب معي للمسجد ومنهم من يصلي وحده، لذلك صليت معهم في المنزل وقدموني فصليت بهم، ونسبةً لضيق الغرفة صلى واحد منهم على يميني،  هل صلاتنا صحيحة بهذه الصورة؟ وإذا كانت الإجابة بلا، هل أعيد الصلاة وحدها أم أعيد كل صلاة صليتها بعدها، أفيدوني أفادكم الله؟","title":"حكم الصلاة في البيت جماعة لبعد المسجد","answer":"الجواب: الصلاة والحال ما ذكر صحيحة، صلاتكم صحيحة والحمد لله، وإذا كان المسجد بعيداً لا يسمعون النداء فلا حرج في صلاتهم في محلهم، أما إذا كانوا يسمعون النداء بغير المكبر النداء العادي، عند هدوء الأصوات يسمعون النداء، وجب عليهم الذهاب إلى المسجد؛ لقول النبي ﷺ: من سمع النداء فلا صلاة له إلا من عذر.\nفالواجب على كل مسلم أن يجيب المنادي، وأن يذهب إلى المسجد ويصلي مع إخوانه إذا كان يسمع النداء بالمكبر أو بغير المكبر، لكن إذا كان لا يسمعه لو كان ...... بالصوت العادي لبعده لم يلزمه المشي إلى ذاك المسجد، ولكن إذا ذهب بالسيارة أو صبر على المشي يكون أفضل لما فيه من الخير العظيم، لكن لا يلزمه أن يجيب المؤذن إلا إذا كان في مكان يسمعه لو كان أذانه بغير مكبر؛ لأن المكبر يسمع من محل بعيد، والاعتبار بسماعه بدون مكبر عند هدوء الأصوات فمثل هذا يلزمه أن يذهب إذا كان يسمع في محل أو هدأت الأصوات، وإذا كان لا يسمع لم يلزمه لكن إذا سعى لذلك وصبر على المشقة كان أفضل وأحسن. نعم.\nالمقدم: بارك الله فيكم، يسأل ما هي نصائحكم لإخواننا المسلمين الذين يصلون في منازلهم وفي أماكن عملهم، رغم وجود المساجد بالقرب من هذه الأماكن والحمد لله؟\nالشيخ: ليس لهم ذلك كما تقدم في السؤال السابق، الواجب على من سمع النداء أن يذهب إلى المسجد وألا يصلي في بيته ولا في محل عمله ولا في مزرعته، الواجب عليه أن يتوجه إلى المسجد مع إخوانه؛ ثبت عن رسول الله عليه الصلاة والسلام أنه قال: من سمع النداء فلا صلاة له إلا من عذر، قيل لـابن عباس: ما العذر؟ قال: خوف أو مرض وفي الصحيح عن أبي هريرة : أن رجلاً أعمى قال: يا رسول الله! ليس لي قائد يلائمني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال عليه الصلاة والسلام: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب فهذا رجل أعمى أجابه النبي ﷺ بقوله: أجب، وفي لفظ قال: لا أجد لك رخصة فإذا كان الأعمى البعيد الدار، الذي ليس له قائد يلائمه يقال له: لا رخصة لك، ويقال له: أجب، فكيف بحال الأصحاء المبصرين الذين يسمعون النداء، فالواجب عليهم أن يجيبوا بكل حال، وأن يتوجهوا إلى المسجد بكل حال، وأن يصلوا مع إخوانهم، ومن تأخر فهذه مشابهة لأهل النفاق، يقول عبد الله بن مسعود  من سره أن يلقى الله غداً مسلماً فليحافظ على هؤلاء الصلوات الخمس حيث ينادى بهن، فإن الله شرع لنبيكم سنن الهدى، وإنهن من سنن الهدى، ولو أنكم صليتم في بيوتكم كما يصلي هذا المتخلف في بيته لتركتم سنة نبيكم، ولو تركتم سنة نبيكم لضللتم -وفي لفظ: لكفرتم- ولقد رأيتنا وما يتخلف عنها إلا منافق معلوم النفاق -وفي لفظ: أو مريض- فهذا عبد الله بن مسعود وهو من كبار الصحابة  يقول: أنه في عهد النبي ﷺ لا يتخلف عن الصلاة في الجماعة إلا منافق أو مريض، فهذا يدل على أن الواجب على المؤمن أن يسعى لها، وأن يحرص على أدائها في الجماعة، وأن يحذر طاعة الشيطان ومشابهة أهل النفاق، والله المستعان.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7780/حكم-الصلاة-في-البيت-جماعة-لبعد-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_249/24907.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9646,"question":"السؤال الثاني في رسالة الأخ (م. ر. عبد الرب ) من اليمن الديمقراطية يقول فيه: ما حكم من أدرك الإمام راكعًا هل أدرك الصلاة أم لا، لأن النبي ﷺ قال: لا تتم الصلاة بدون فاتحة الكتاب) أفيدونا أفادكم الله؟","title":"إدراك المأموم الركعة بإدراك الركوع","answer":"الجواب: الصحيح أنه إذا أدرك الركوع أدرك الركعة؛ لأن النبي ﷺ لما دخل أبو بكرة الثقفي وهو راكع ركع معه دون الصف ثم دخل في الصف، فقال له النبي ﷺ: زادك الله حرصًا ولا تعد ولم يأمره بقضاء الركعة، فدل ذلك على أنه معذور وهذا يخصص قوله ﷺ لا صلاة لمن لم يقرأ بفاتحة الكتاب هذا في حق الإمام والمنفرد، والمأموم القادر على الصحيح، أما المأموم العاجز الذي جاء وقد فاته قيامه والإمام راكع فإن الصحيح أنه يجزئه الركوع وتتم ركعته وهذا قول الأئمة الأربعة ... أبي حنيفة و مالك والشافعي وأحمد وجمهور أهل العلم، وذهب بعض أهل العلم إلى أنها لا تجزئ وأن عليه القضاء ولكن الصواب أنها تجزئه، هذا هو الأرجح وبهذا يكون معذورًا لأنه ما أدرك القيام، وهكذا لو نسي ولم يقرأها أو تركها تقليدًا لبعض العلماء القائلين بأنها لا تجب على المأموم فإن صلاته صحيحة. نعم.","link":"https://binbaz.org.sa/fatwas/7812/ادراك-الماموم-الركعة-بادراك-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19409.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9697,"question":"يقول أيضاً الأخ مجدي: هل يلزمني أن أفسخ العقد الذي بيني وبين صاحب المزرعة؛ بسبب عدم وجود مساجد عندي في هذا المكان، أم أعود مرة أخرى للعمل في هذا ولا حرج علي؟","title":"هل يلزم فسخ عقد العمل لعدم وجود مساجد في محل العمل؟","answer":"الجواب: لا يلزمك أن تفسخ العقد، ولك أن تبقى في المزرعة وهذا من رزق الحلال ما دمت في عمل طيب في كسب الحلال، احمد الله جل وعلا، وصل الصلاة في وقتها، وأذن وأقم واحفظ دينك وأبشر بالخير، ولو كنت وحدك والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7899/هل-يلزم-فسخ-عقد-العمل-لعدم-وجود-مساجد-في-محل-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_254/25408.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9733,"question":"سماحة الشيخ، السائلة (د. ع) من الأحساء تقول: من سها في صلاته وقام من الركعة الثانية قبل أن يتشهد ولم يذكر إلا وهو في الركعة الثالثة، هل يعود ويجلس للتشهد؟ وإذا ذكر قبل أن يعتدل قائماً، هل يعود ويتشهد؟ وفي كلا الحالتين هل يسجد للسهو؟","title":"حكم من نسي التشهد الأوسط","answer":"الجواب: إذا قام عن التشهد الأول وذكر في أثناء قيامه يرجع، يلزمه الرجوع ويتشهد ويسجد للسهو كما فعله النبي ﷺ فإنه قام من التشهد الأول ولم يرجع وسجد سجدتين للسهو قبل أن يسلم لا بأس.\nأما إذا شرع في القراءة ما ذكر إلا بعد الشروع في القراءة لا يرجع يستمر ويسجد للسهو والحمد لله قبل أن يسلم. نعم.","link":"https://binbaz.org.sa/fatwas/7889/حكم-من-نسي-التشهد-الاوسط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27222.mp3","categories":["سجود السهو"]},{"id":9753,"question":"أخيراً يقول: هل يجوز أن يصلي المفترض خلف المتنفل؟ وما دليل ذلك بارك الله فيكم؟","title":"حكم صلاة المفترض خلف المتنفل","answer":"الجواب: نعم يجوز أن يصلي المفترض خلف المتنفل؛ لأنه ثبت عن النبي ﷺ أنه صلى في بعض غزواته بجماعة من أصحابه ركعتين، وكانت هذه فرضه ثم صلى بآخرين ركعتين، فصارت نفلاً له عليه الصلاة والسلام، وثبت أن معاذاً كان يصلي مع النبي ﷺ العشاء ثم يرجع فيصلي بأصحابه صلاة العشاء، فهي له نفل، وهي لهم فرض ومع هذا أقره النبي ﷺ على ذلك، فدل ذلك على جواز صلاة المفترضين خلف المتنفلين. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7923/حكم-صلاة-المفترض-خلف-المتنفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25614.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9756,"question":"أخيراً يقول: هل يجوز أن يصلي المفترض خلف المتنفل؟ وما دليل ذلك بارك الله فيكم؟","title":"حكم صلاة المفترض خلف المتنفل","answer":"الجواب: نعم يجوز أن يصلي المفترض خلف المتنفل؛ لأنه ثبت عن النبي ﷺ أنه صلى في بعض غزواته بجماعة من أصحابه ركعتين، وكانت هذه فرضه ثم صلى بآخرين ركعتين، فصارت نفلاً له عليه الصلاة والسلام، وثبت أن معاذاً كان يصلي مع النبي ﷺ العشاء ثم يرجع فيصلي بأصحابه صلاة العشاء، فهي له نفل، وهي لهم فرض ومع هذا أقره النبي ﷺ على ذلك، فدل ذلك على جواز صلاة المفترضين خلف المتنفلين. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7923/حكم-صلاة-المفترض-خلف-المتنفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25614.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9765,"question":"من محافظة مطروح في جمهورية مصر العربية قرية النزيلة المستمع: محمد جبريل الملاح يسأل ويقول:إذا دخلت المسجد ووجدت المصلين في التشهد الأخير، وجلست معهم حتى التسليم، فهل يلزمني حينئذٍ أن أعود لأقيم الصلاة، علماً بأني لم أكبر تكبيرة الإحرام؟ جزاكم الله خيراً.","title":"حكم من أدرك الإمام في التشهد الأخير فجلس ولم يكبر","answer":"الجواب: إذا كنت لم تكبر جلست من دون تكبير، فلا صلاة لك، وعليك أن تكبر حين تبدأ الصلاة، لكن الأفضل لك، إذا جئت وهم في التشهد الأخير، عليك أن تكبر وأنت واقف تكبيرة الإحرام، ثم تجلس معهم، وتأتي بالتشهد، متابعة الإمام أفضل ثم إذا سلم الإمام قمت تؤدي صلاتك كاملة، لقول النبي ﷺ: إذا أتى أحدكم الصلاة فليمش وعليه السكينة والوقار، فما أدرك صلى، وما فاته أتمه، وفي اللفظ الآخر: فما أدركتم فصلوا وما فاتكم فأتموا، فالسنة لمن جاء والإمام جالس في التشهد الأخير أن يدخل معه في الصلاة، وأن يكبر تكبيرة الإحرام وهو واقف ثم يجلس، وإن كبر حين الجلوس فهذا لا بأس به، فيتشهد ثم إذا سلم الإمام قام، وصلى بقية صلاته، نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7932/حكم-من-ادرك-الامام-في-التشهد-الاخير-فجلس-ولم-يكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_257/25706.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9771,"question":"من محافظة مطروح في جمهورية مصر العربية قرية النزيلة المستمع: محمد جبريل الملاح يسأل ويقول:إذا دخلت المسجد ووجدت المصلين في التشهد الأخير، وجلست معهم حتى التسليم، فهل يلزمني حينئذٍ أن أعود لأقيم الصلاة، علماً بأني لم أكبر تكبيرة الإحرام؟ جزاكم الله خيراً.","title":"حكم من أدرك الإمام في التشهد الأخير فجلس ولم يكبر","answer":"الجواب: إذا كنت لم تكبر جلست من دون تكبير، فلا صلاة لك، وعليك أن تكبر حين تبدأ الصلاة، لكن الأفضل لك، إذا جئت وهم في التشهد الأخير، عليك أن تكبر وأنت واقف تكبيرة الإحرام، ثم تجلس معهم، وتأتي بالتشهد، متابعة الإمام أفضل ثم إذا سلم الإمام قمت تؤدي صلاتك كاملة، لقول النبي ﷺ: إذا أتى أحدكم الصلاة فليمش وعليه السكينة والوقار، فما أدرك صلى، وما فاته أتمه، وفي اللفظ الآخر: فما أدركتم فصلوا وما فاتكم فأتموا، فالسنة لمن جاء والإمام جالس في التشهد الأخير أن يدخل معه في الصلاة، وأن يكبر تكبيرة الإحرام وهو واقف ثم يجلس، وإن كبر حين الجلوس فهذا لا بأس به، فيتشهد ثم إذا سلم الإمام قام، وصلى بقية صلاته، نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7932/حكم-من-ادرك-الامام-في-التشهد-الاخير-فجلس-ولم-يكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_257/25706.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9782,"question":"هذه رسالة من (ح. م. ح) أخ مصري مقيم بالطائف، يقول في رسالته: أثناء إذاعة الصلاة على الهواء مباشرة في التلفاز، هل يجوز وأنا في بيتي أن أصلي خلف إمام المسجد التي تذاع منه الصلاة، أفيدونا أفادكم الله؟","title":"حكم الصلاة خلف التلفاز أو المذياع","answer":"الجواب: لا يصلى خلف التلفاز، الواجب عليك أن تصلي في الجماعة في المساجد التي حولك، وليس لك أن تصلي في بيتك؛ لأن النبي عليه السلام قال: من سمع النداء فلم يأت فلا صلاة له إلا من عذر.\nفالواجب على كل مكلف أن يصلي مع الجماعة في المساجد، إذا سمع النداء: حي على الصلاة حي على الفلاح.\nوقد ثبت عنه ﷺ أنه جاءه رجل أعمى فقال: يا رسول الله! ليس لي قائد يلائمني إلى المسجد فهل لي من رخصة أن أصلي في بيتي؟ فقال له النبي ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب فإذا كان الأعمى الذي ليس له من يقوده بصفة مناسبة أو بصفة دائمة، بل قد يتأخر عنه قائده ومع هذا يؤمر بالصلاة في الجماعة فكيف بغيره؟!\nفالحاصل: أن الواجب على المكلفين من الرجال أن يصلوا في مساجد الله في بيوت الله مع إخوانهم، لكن لو قدر أنه تأخر لمرض أو علة من العلل، ففاتته الصلاة لا يصلي خلف المذياع، ولا خلف التلفاز مما يذاع في التلفاز، بل يصلي وحده أو يصلي مع من عنده من أهل بيته، والنساء يقفن خلفه لا يقفن معه، المرأة فأكثر تقف خلفه وتصلي معه لا بأس.\nأما الصلاة.. مع الإمام الذي يسمعه في الإذاعة أو في التلفاز فلا، أو يراه في التلفاز فلا. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7949/حكم-الصلاة-خلف-التلفاز-او-المذياع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_259/25902.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9785,"question":"هذا السائل له سؤال آخر يقول فيه: دخلت المسجد وكانت صلاة المغرب قائمة وأنا لم أصل العصر بعد، فهل أصلي العصر بعد صلاة المغرب أم أصلي العصر أولاً ثم أصلي المغرب، أو أدخل مع الإمام وهو يصلي المغرب فأكمل رابعة وتكفيني عن العصر، أفيدوني أفادكم الله؟","title":"حكم من أتى المسجد وهم يصلون المغرب ولم يصل العصر","answer":"من كان عليه العصر وحضر وقت صلاة المغرب فإنه يصلي معهم المغرب ويكملها برابعة بنية العصر، ثم يصلي المغرب بعد ذلك، وهو معذور على الصحيح في هذه المسألة، وإنما زاد رابعة لأن العصر أربع، فإذا سلم الإمام قام وكمل كالمسبوق، وتجزئه، وليس له أن يقدم المغرب عليها لأن الترتيب واجب، كونه يرتب الصلوات يصلي العصر ثم المغرب ثم العشاء هذا أمر لازم، كما فرضها الله .\nولما فاتت النبي ﷺ الصلوات يوم الأحزاب حتى غابت الشمس بدأ بالعصر فصلاها، ثم صلى بعدها المغرب.\nوفي رواية: أنه فاتته الظهر والعصر والمغرب، فصلى الظهر ثم صلى العصر ثم صلى المغرب عليه الصلاة والسلام بعد ما غابت الشمس.\nوالمقصود: أنه يرتب فيصلي معهم المغرب بنية العصر، فإذا سلم الإمام قام فصلى الرابعة وأجزأته، ثم يصلي العشاء في وقتها، أما إن أمكنه أن يصلي العصر قبل ذلك بأن جاء قبل أن تقام الصلاة فليبدأ بالعصر فيصليها ثم يصلي معهم المغرب. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7951/حكم-من-اتى-المسجد-وهم-يصلون-المغرب-ولم-يصل-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_259/25904.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9813,"question":"يسأل أخيراً ويقول: إذا رأى الشخص إماماً في صلاته نقص أو ربما بطلت الصلاة، فهل يتركه ويفارقه ويصلي مع غيره أو يصلي وحده، مثلاً: كأن ينقص في أعضاء السجود أو في القراءة أو نحو ذلك؟","title":"حكم من علم من إمامه ما يوجب بطلان الصلاة","answer":"الجواب: إذا صلى الإنسان مع إنسان وظهر منه ما يبطل الصلاة فارقه وصلى مع جماعة أخرى إن وجدت وإلا صلى وحده، إذا تحقق وعلم أنه فعل ما يبطل الصلاة، أما إذا كان لا يتحقق ذلك فإنه يكمل الصلاة ويعلمه أو يرشده إلى ما قد يخل به من شيء لا يبطل الصلاة، أما أنه يقطع الصلاة ولم ير شيئاً واضحاً يبطل الصلاة فهذا لا يجوز له، بل يجب عليه أن يتمم الصلاة، لكن إن رأى خللاً لا يبطل الصلاة نبه عليه إذا استطاع ونصح وعلم أخاه ما ينفعه.\nأما إن رأى شيئاً واضحاً يبطل الصلاة بأن رأى عورته بادية أو تكلم كلاماً عمداً في الصلاة كالمستهزي أو كالضاحك الذي ليس بناسي، بل يظهر منه اللعب في الصلاة أو الضحك في الصلاة أو ما أشبه ذلك مما هو دليل على أنه متلاعب وأنه لا يصلي.\nالمقصود: متى ظهر منه أمر يبطل الصلاة قطعها وصلى مع غيره إن وجد أحداً وإلا صلى وحده، مع إنكار المنكر وتعليمه بعد ما يلزم من وجوب إنكار المنكر وتعليمه ما قد يخفى عليه إن كان جاهلاً. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7983/حكم-من-علم-من-امامه-ما-يوجب-بطلان-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_260/26004.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9821,"question":"يسأل أخيراً ويقول: إذا رأى الشخص إماماً في صلاته نقص أو ربما بطلت الصلاة، فهل يتركه ويفارقه ويصلي مع غيره أو يصلي وحده، مثلاً: كأن ينقص في أعضاء السجود أو في القراءة أو نحو ذلك؟","title":"حكم من علم من إمامه ما يوجب بطلان الصلاة","answer":"الجواب: إذا صلى الإنسان مع إنسان وظهر منه ما يبطل الصلاة فارقه وصلى مع جماعة أخرى إن وجدت وإلا صلى وحده، إذا تحقق وعلم أنه فعل ما يبطل الصلاة، أما إذا كان لا يتحقق ذلك فإنه يكمل الصلاة ويعلمه أو يرشده إلى ما قد يخل به من شيء لا يبطل الصلاة، أما أنه يقطع الصلاة ولم ير شيئاً واضحاً يبطل الصلاة فهذا لا يجوز له، بل يجب عليه أن يتمم الصلاة، لكن إن رأى خللاً لا يبطل الصلاة نبه عليه إذا استطاع ونصح وعلم أخاه ما ينفعه.\nأما إن رأى شيئاً واضحاً يبطل الصلاة بأن رأى عورته بادية أو تكلم كلاماً عمداً في الصلاة كالمستهزي أو كالضاحك الذي ليس بناسي، بل يظهر منه اللعب في الصلاة أو الضحك في الصلاة أو ما أشبه ذلك مما هو دليل على أنه متلاعب وأنه لا يصلي.\nالمقصود: متى ظهر منه أمر يبطل الصلاة قطعها وصلى مع غيره إن وجد أحداً وإلا صلى وحده، مع إنكار المنكر وتعليمه بعد ما يلزم من وجوب إنكار المنكر وتعليمه ما قد يخفى عليه إن كان جاهلاً. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7983/حكم-من-علم-من-امامه-ما-يوجب-بطلان-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_260/26004.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9827,"question":"وهذه رسالة وردت إلى البرنامج من هاشم عبد الرحيم محمد من معهد المشرف العلمي في السودان، يقول السائل في رسالته: ما حكم التبليغ خلف الإمام، بحيث يقول المؤذن بعد قول الإمام: الله أكبر، فيردد بعده بالرغم أن هناك مكبر صوت وأن المأمومين يسمعون تكبير الإمام؟","title":"حكم التبليغ خلف الإمام في الصلاة","answer":"الجواب: لا بأس بالتبليغ عن الإمام إذا دعت الحاجة إلى ذلك، إن كان المسجد كبيراً أو صوت الإمام ضعيفاً، أو لم يكن هناك مكبر أو ما أشبه ذلك، المقصود: إذا دعت الحاجة إلى التبليغ فلا حرج في ذلك ولو كان صوت الإمام يسمع، ولو كان هناك مكبر فإن المساجد قد تكون في بعض الأحيان كبيرة والناس فيها متباعدون، قد يخفى صوت الإمام على بعضهم فلا حرج في التبليغ، وقد كان الصديق  يبلغ عن النبي ﷺ لما صلى بالناس في مرض موته عليه الصلاة والسلام، كان صوته ضعيفاً فصار أبو بكر يبلغ الناس، يتأسى بالنبي ﷺ ثم هو يبلغ الناس، وهذا هو الأصل في التبليغ، إذا دعت الحاجة إلى التبليغ فإنه لا حرج في ذلك، وإذا أمر به ولي الأمر أو رآه إمام المسجد أو رآه أهل المسجد للمصلحة؛ لأن بعض الناس في أطراف المسجد قد لا يبلغهم صوت الإمام فلا حرج في هذا. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7985/حكم-التبليغ-خلف-الامام-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_260/26006.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9916,"question":"وأولى رسائل هذه الحلقة وردت إلينا من ضيف الله بن عبدالعزيز المطيري يقول في رسالته: إذا دخلت إلى صلاة المغرب والجماعة في التشهد الأخير، ودخلت معهم ثم سلم الإمام وقمت لأكمل الصلاة، فهل أصلي ركعة وأجلس للتشهد الأول أم أصلي ركعتين وأجلس للتشهد الأول وآتي بثالثة أفيدوني أفادكم الله؟","title":"كيفية صلاة من أدرك الإمام في التشهد الأخير من المغرب","answer":"الجواب: بسم الله الرحمن الرحيم، اللهم صل وسلم على رسول الله وعلى آله وأصحابه.\nأما بعد: فإن المصلي إذا دخل والإمام في الركعة الأخيرة في التشهد أو في السجود فإنه يدخل معه ويكمل الصلاة معه، ثم إذا سلم الإمام قام فأتى بركعتين ثم يجلس في التشهد الأول ثم يأتي بالثالثة، هذه هي الصفة الشرعية لأداء صلاة المغرب لمن فاتته الصلاة كلها، أما من فاتته واحدة فإنه بعدما يسلم الإمام يقوم فيأتي بواحدة تكون ثانية له، ويجلس ويأتي بالتشهد الأول ويصلي على النبي صلى الله عليه وسلم ثم يقوم للثالثة فيكمل صلاته، والله ولي التوفيق.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8085/كيفية-صلاة-من-ادرك-الامام-في-التشهد-الاخير-من-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_267/26701.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9918,"question":"وهذا محمد مبخوت الراشدي من سلطنة عمان من صلالة يقول في هذه الرسالة التي بعث بها إلى البرنامج: لقد حضرت لصلاة العصر ودخلت في الركعة الثالثة وبعد تسليم الإمام قمت لتكملة ما فاتني من الصلاة، وأثناء ذلك حضر مسلم وصلى خلفي وجعلني إماماً له، فهل يحق لي أن أكون إماماً له، وهل تحسب له صلاة الجماعة، أفيدونا أفادكم الله؟","title":"حكم إمامة المسبوق","answer":"الجواب: لا حرج في ذلك إن شاء الله على الصحيح يكون مأموماً وأنت إمام ويرجى أن يكون لكما فضل الجماعة، وإن صلى وحده وكملت وحدك فلعله أحوط؛ خروجاً من خلاف العلماء المانعين من ذلك. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8086/حكم-امامة-المسبوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_267/26702.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9920,"question":"وهذا محمد مبخوت الراشدي من سلطنة عمان من صلالة يقول في هذه الرسالة التي بعث بها إلى البرنامج: لقد حضرت لصلاة العصر ودخلت في الركعة الثالثة وبعد تسليم الإمام قمت لتكملة ما فاتني من الصلاة، وأثناء ذلك حضر مسلم وصلى خلفي وجعلني إماماً له، فهل يحق لي أن أكون إماماً له، وهل تحسب له صلاة الجماعة، أفيدونا أفادكم الله؟","title":"حكم إمامة المسبوق","answer":"الجواب: لا حرج في ذلك إن شاء الله على الصحيح يكون مأموماً وأنت إمام ويرجى أن يكون لكما فضل الجماعة، وإن صلى وحده وكملت وحدك فلعله أحوط؛ خروجاً من خلاف العلماء المانعين من ذلك. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8086/حكم-امامة-المسبوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_267/26702.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":9921,"question":"وهذه رسالة وردتنا من الأخ مطلق العنيزي من الخرج يقول فيها: إذا دخلت المسجد والجماعة المصلين قد أكملوا الصف ولا يوجد في الصف فرجة، فماذا أفعل؟ هل أجذب شخصاً من الصف السابق ليصف بجانبي، أم أصلي لوحدي، وتصدف أحياناً كثيرة أن الإمام يسلم ولم يأت أحد آخر يصلي معي أفيدوني أفادكم الله؟","title":"حكم من أتى المسجد ولم يجد فرجة في الصف","answer":"الجواب: الواجب على من دخل والإمام في الصلاة أن يلتمس فرجة فيدخل فيها، أو يلتمس أطراف الصفوف حتى يصف مع الناس، أما جذبه لغيره فلا، والحديث الوارد في ذلك: هلا دخلت معهم أو جررت رجلاً حديث ضعيف لا تقوم به الحجة ولأن جذب الرجل من الصف يفتح فيه فرجة والرسول ﷺ أمر بسد الخلل وسد الفرج، ولكن ينتظر حتى يجد مكاناً في الصف أو يأتي بعض الناس فيصف معه، أما أنه يصف وحده فلا؛ لأن الرسول عليه السلام قال: لا صلاة لمنفرد خلف الصف ولما رأى رجلاً يصلي خلف الصف وحده أمره أن يعيد الصلاة.\nلكن إن تيسر له أن يصف مع الإمام عن يمينه فلا بأس، والخلاصة أنه ينتظر إن لم يجد مكاناً فإنه ينتظر ولو فاتته الصلاة، فإذا سلم الإمام صلى وحده، وإن أتى معه أحد وصلى معه فالحمد لله، وإن وجد فرجة في الصف الأول أو في الثاني أو في أطراف الصفوف صف مع الناس، وإن تمكن من الدخول حتى يقف مع الإمام عن يمينه فعل ذلك، هذا هو المشروع وهذا هو الواجب.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8081/حكم-من-اتى-المسجد-ولم-يجد-فرجة-في-الصف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_268/26802.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10009,"question":"رسالة وصلت إلى البرنامج من المستمع: (ع. ح. ع) من مصر، وقد بعث بمجموعة من الأسئلة، يقول في أحدها: شخصان يعملان في متجر واحد، ويصليان معًا بإمامة أحدهما، ولكن المأموم يسلم بعد الإمام بثلاث دقائق تقريبًا، وعندما يسأله الإمام لماذا يفعل هكذا يرد عليه بأن صلاته سريعة، فهل يصح هذا؟","title":"حكم تأخر المأموم عن متابعة إمامه","answer":"الجواب: السنة للمؤمن أن يسلم بعد إمامه، وأن يفعل الأمور بعد إمامه متصلًا به لا يتأخر؛ لقوله ﷺ: إنما جعل الإمام ليؤتم فلا تختلفوا عليه، فإذا كبر فكبروا، وإذا ركع فاركعوا، وإذا قال: سمع الله لمن حمده، فقولوا: ربنا ولك الحمد.. إلى آخره.\nفالسنة أنه يتابع إمامه متصلًا، فإذا انقطع صوت الإمام مكبرًا كبر، وإذا استوى راكعًا ركع، وإذا استوى ساجدًا انقطع صوته سجد وهكذا، وإذا سلم سلم بعده، لكن إن كان الإمام يعجل قبل أن يأتي المأموم بالمشروع فلا بأس أن يتأخر بعده قليلًا؛ حتى يكمل المشروع من التعوذ بالله من عذاب جهنم ومن عذاب القبر ومن فتنة المحيا والممات ومن فتنة المسيح الدجال .\nوينبغي للإمام أن لا يعجل؛ حتى لا يلجئ المأمومين إلى ترك السنن أو إلى التأخر بعده، ينبغي له أن يتأنى ولا يعجل؛ حتى يتمكن المأمومون من فعل المشروعات مع الواجبات.\nثم أيضًا: ليس لهما أن يصليا في الدكان وحدهما، الواجب أن يصلوا في المساجد لا يصلوا في متجرهما، الواجب عليهما أن يخرجا إلى المسجد مع المسلمين، ولا يجوز لأحد أن يصلي في بيته ولا في دكانه، بل يجب أن يذهب إلى المصلى يغلق الدكان ويذهب إلى المصلى، حق الله مقدم. نعم.","link":"https://binbaz.org.sa/fatwas/8177/حكم-تاخر-الماموم-عن-متابعة-امامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_331/33113.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10024,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، تقول: إني أختكم في الإسلام أم يوسف من محافظة نينوى من الجمهورية العراقية، جئتكم برسالتي هذه راجية الجواب لأسئلتي ولكم جزيل الشكر، سؤالي الأول هو: هل يحق لي الصلاة جماعة مع أولادي وأجهر بالقراءة لأجل استفادتهم وحفظهم للآيات، علمًا أن أكبرهم يبلغ من العمر الحادية عشرة وأجمعهم وأحثهم على صلاة الجماعة دائمًا؟","title":"حكم إمامة المرأة بأبنائها","answer":"الجواب: المشروع للأولاد الذكور أن يصلوا مع الناس في المساجد، وإذا ما صلوا معهم وفاتتهم الصلاة وصليت أنت بالبنات وهم يصلون لأنفسهم وحدهم فلا بأس، أما أن تصلي أنت بالرجال لا ولو كانوا صغارًا، المرأة لا تؤم الرجال ولكن إذا صلوا وحدهم فاتتهم الصلاة فصلوا وحدهم يؤمهم واحد منهم، وتصلين أنت معهم والبنات معهم والإمام يكون واحدًا منهم إذا كان مميزًا ابن سبع سنين أو ثمان أو تسع وهو عاقل جيد يفهم فلا بأس يصلي بكم، وأنت تكوني مأمومة لا إمامة، لكن إذا أميت البنات أو الأخوات وكنت وسطهن فلا بأس بذلك، كان بعض نساء النبي عليه الصلاة والسلام يصلين بالنساء، فالحاصل أنك تكونين إمامة بالنساء خاصة لا بالذكور، وإذا صلى الذكور في البيت يصلي بهم واحد منهم وإذا صليت معهم أنت مأمومة فلا بأس، وليس لهم أن يصلوا في البيت بل عليهم أن يصلوا مع الرجال في المساجد، لكن لو قدر في بعض الأحيان أنهم فاتتهم وصلوا في البيت يصلون جماعة ويصلي بهم أحدهم أقرؤهم وأفضلهم يؤمهم. نعم.\nالمقدم: جزاكم الله خيرًا، إذا كان هذا الذي عمره إحدى عشرة سنة يصلح أن يكون إمامًا في البيت؟\nالشيخ: نعم يؤمهم لكن لا يجوز أن يصلوا في البيت عليهم أن يصلوا مع الناس في المساجد. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8193/حكم-امامة-المراة-بابناىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_332/33205.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10048,"question":"من سلّم من الصلاة ثم تذكر أنه نسي ركنًا من أركان الصلاة أو شك، هل يأتي بركعة أم يعيد الصلاة؟","title":"حكم من ترك ركنًا من أركان الصلاة","answer":"الجواب: إذا تيقن أنه ترك ركنًا يأتي بركعة ويسجد للسهو بعدما يسلّم يسجد للسهو، أما إذا كان شك فلا يلزمه شيء، الشك بعد الصلاة لا يعتبر ولا يؤثر، إذا سلّم وهو عن اعتقاد أنها تمت صلاته ثم جاءت شكوك بعد ذلك لا حرج عليه، بل هذه وساوس لا يلتفت إليها، أما إذا تيقن أنه ترك ركوعًا أو سجودًا فإنه يأتي بركعة، يأتي بركعة يكمل بها صلاته ثم يسجد للسهو بعد السلام، وإن سجد قبل السلام فلا بأس.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8236/حكم-من-ترك-ركنا-من-اركان-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30317.mp3","categories":["سجود السهو"]},{"id":10055,"question":"من سلّم من الصلاة ثم تذكر أنه نسي ركنًا من أركان الصلاة أو شك، هل يأتي بركعة أم يعيد الصلاة؟","title":"حكم من ترك ركنًا من أركان الصلاة","answer":"الجواب: إذا تيقن أنه ترك ركنًا يأتي بركعة ويسجد للسهو بعدما يسلّم يسجد للسهو، أما إذا كان شك فلا يلزمه شيء، الشك بعد الصلاة لا يعتبر ولا يؤثر، إذا سلّم وهو عن اعتقاد أنها تمت صلاته ثم جاءت شكوك بعد ذلك لا حرج عليه، بل هذه وساوس لا يلتفت إليها، أما إذا تيقن أنه ترك ركوعًا أو سجودًا فإنه يأتي بركعة، يأتي بركعة يكمل بها صلاته ثم يسجد للسهو بعد السلام، وإن سجد قبل السلام فلا بأس.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8236/حكم-من-ترك-ركنا-من-اركان-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30317.mp3","categories":["سجود السهو"]},{"id":10085,"question":"من خميس مشيط المستمع (م. ع) يسأل ويقول: أسهو كثيرًا وخاصة في عدد السجدات، هل يلزمني إعادة الصلاة أم سجود السهو يكفي، وإن كان يلزمني إعادة الصلاة فأنا لا أتذكر عددها، فكيف توجهونني؟","title":"من يسهو في عدد السجدات، هل يلزمه إعادة الصلاة؟","answer":"الجواب: ليس عليك إعادة الصلاة ولكن عليك أن تبني على اليقين، فإذا شككت هل سجدت واحدة أو ثنتين تجعلها واحدة ثم تأتي بالسجدة الثانية وتسجد للسهو بعد الفراغ من الصلاة قبل أن تسلم من أجل السهو في جميع الركعات، سواء في الركعة الأولى أو في الثانية أو في الثالثة من المغرب والرباعية أو في الرابعة من الرباعية، متى حصل الشك هل سجدت واحدة أو سجدتين فالأصل عدم الثانية، تبني على اليقين وتسجد للثانية، ثم عند الفراغ وقبل التسليم تسجد سجدتين للسهو. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8254/من-يسهو-في-عدد-السجدات-هل-يلزمه-اعادة-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_276/27613.mp3","categories":["سجود السهو"]},{"id":10088,"question":"إذا سهوت في موضعين في صلاة واحدة، كأن ينقصني سجدة وآتي بركعة زيادة، فهل يكفيني سجودي للسهو أم أن الصلاة تبطل؟","title":"الاكتفاء بسجدتي السهو وإن تعدد السهو","answer":"الجواب: يكفي سجود السهو ولو سها مرات، لو سها الإنسان مرات يكفي سجود السهو للجميع سجدتان للجميع والحمد لله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8257/الاكتفاء-بسجدتي-السهو-وان-تعدد-السهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_276/27616.mp3","categories":["سجود السهو"]},{"id":10089,"question":"إذا كنت قد دخلت في الصلاة الرباعية مع الإمام في الركعة الأولى، وعند التسليم شككت هل ينقصني ركعة أم لا فقمت وجئت بالركعة الخامسة والتي أظنها الرابعة بالنسبة لي، وبعد أن سلمت قال لي من كان بجواري إنني أتيت بخمس ركعات فسجدت للسهو، فهل فعلي هذا صحيح؟","title":"حكم من زاد في الصلاة عامداً أو ناسياً","answer":"","link":"https://binbaz.org.sa/fatwas/8258/حكم-من-زاد-في-الصلاة-عامدا-او-ناسيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_276/27617.mp3","categories":["سجود السهو"]},{"id":10095,"question":"هل سجود السهو واجب أم سنة؟","title":"هل سجود السهو واجب أم سنة؟","answer":"الجواب: سجود السهو واجب لأن الرسول ﷺ أمر بذلك إذا كان عن ترك واجب أو فعل محظور سهوًا وجب كما لو ترك التشهد الأول أو جلس في الرابعة فنبئ وقام ليكمل أو زاد ثالثة في الفجر أو رابعة في المغرب أو خامسة في العشاء أو نحوها، فإنه يسجد للسهو وجوبًا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8264/هل-سجود-السهو-واجب-ام-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_333/33308.mp3","categories":["سجود السهو"]},{"id":10106,"question":"في الركعة الثالثة أو الرابعة أكون قد انتهيت من قراءة الفاتحة والإمام لم يركع بعد، هل أعيد قراءة الفاتحة أم أقرأ سورة أخرى؟","title":"انتهى من قراءة الفاتحة والإمام لم يركع فماذا يفعل؟","answer":"الجواب: تقرأ ما تيسر أو تسكت ولا تعيد الفاتحة تقرأ ما تيسر آية أو آيتين أو تسكت حتى يكبر.\nالمقدم: جزاكم الله خيرًا.\nالمقدم: كذلك في التشهد إذا انتهيت من التشهد والإمام لم ينهض للإتيان بالثالثة؟\nالشيخ: تصلي على النبي ﷺ وتقف أو تعيد الصلاة على النبي ﷺ أو تعيد التحيات.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8276/انتهى-من-قراءة-الفاتحة-والامام-لم-يركع-فماذا-يفعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_333/333017.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10117,"question":"هل يجوز لي أن أصلي بالناس ووالدي موجود؟","title":"حكم إمامة الناس مع وجود الوالد","answer":"الجواب: نعم إذا كنت أقرأ تصلي بالناس ولو كان أبوك موجود، يقول النبي ﷺ: يؤم القوم أقرؤهم لكتاب الله، فإن كانوا في القراءة سواء فأعلمهم بالسنة، فإن كانوا في السنة سواء فأقدمهم هجرة، فإن كانوا في الهجرة سواء فأقدمهم سلمًا -يعني: إسلامًا، وفي اللفظ الآخر: فأكبرهم سنًا، فإذا كنت أعلم من أبيك فأنت تؤمهم، نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8290/حكم-امامة-الناس-مع-وجود-الوالد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_277/27708.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10126,"question":"أحد الإخوة المستمعين بعث برسالة يقول: المرسل البشير صافي النور محمد من تهامة عسير، يقول: ما حكم رجل صلى منفرداً خلف صفوف المأمومين، وما الذي يترتب عليه جزاكم الله خيراً؟","title":"تجب الإعادة لمن صلى وحده خلف الصف","answer":"الجواب: إذا صلى الإنسان منفرداً خلف الصف أو امرأة خلف صف النساء منفردة وجبت الإعادة، لقوله ﷺ: لا صلاة لمنفرد خلف الصف، ولما رأى رجل يصلي خلف الصف لوحده أمره ﷺ أن يعيد الصلاة. فهذا يدل على أن من صلى وحده خلف الصف يعيد؛ لقوله ﷺ: لا صلاة لمنفرد خلف الصف، لكن المرأة إذا كان ما معها نساء صلاتها صحيحة خلف الصف مستثناة، أما إذا كان معها نساء وتركت صف النساء وصلت خلفهن وحدها فإنها كالرجل في هذا تعيد الصلاة، أما إذا كانت خلف الرجال وليس معها أحد فإنه يجزؤها ذلك، لأن أم سليم صلت خلف النبي ﷺ وحدها خلف الرجال، أما الرجل لا، إذا صلى خلف الصفوف فإنه يقضي، لقوله ﷺ: لا صلاة لمنفرد خلف الصف، وفي حديث وابصة بن معبد أنه ﷺ رأى رجلاً يصلي خلف الصف وحده فأمره أن يعيد الصلاة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8308/تجب-الاعادة-لمن-صلى-وحده-خلف-الصف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_305/30513.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10134,"question":"يقول: هل يجوز أن يؤم رجل النساء؟","title":"حكم إمامة الرجل للنساء","answer":"الجواب: نعم، يجوز أن يؤم النساء في الصلاة وفي التراويح، النبي ﷺ زار أنس بن مالك وصلى خلفه أنس بن مالك ويتيم عندهم، صفاً خلفه وصفت أم سليم خلفهم، وكان النساء يصلين خلف الإمام في مسجد النبي ﷺ في حياته ﷺ وبعد وفاته صلى الله عليه وسلم، فلا بأس أن يصلي النساء خلف الإمام ولو كان وحده الإمام وكلهن نساء، لأن الخلوة بالثنتين فأكثر ما تحرم إنما تحرم الخلوة إذا كانت لواحدة، لقوله ﷺ: لا يخلون رجل بامرأة فإن الشيطان ثالثهما، فإذا كان معها نساء أو معها رجال ما تسمى خلوة، وقد مكث النبي ﷺ مع أنس واليتيم وأم سليم جميعاً صلى بهم عليه الصلاة والسلام، وهكذا في رمضان لو صلى بالنساء في التراويح في البيت صلى بهم رجل كفيف فلا حرج، أو بصير لكن يتغشين عنه ويحتجبن وإذا سلم لا يكشفن له بل يتحجبن يسترن الوجوه وغير الوجه عند إقباله عليهن وسلامه، هذا لا حرج فيه لأن المقصود هو عدم الخلوة وعدم النظر إلى العورات، فإذا كن مستورات عن البصير أو كان الإمام أعمى وليس هناك خلوة فلا حرج في ذلك، ولكن إذا كان أعمى يكون أسلم وأبعد عن الفتنة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8296/حكم-امامة-الرجل-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_305/30502.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10149,"question":"الأخت (و. ع) من الزلفي بعثت تسأل وتقول: صليت الظهر ولما ركعت الركعة الرابعة ورفعت من الركوع وأردت السجود عدت مرة أخرى وركعت، ثم تذكرت وسجدت، فهل علي إعادة للصلاة؟","title":"حكم من زاد ركوعاً في صلاته سهواً","answer":"الجواب: ليس عليك إعادة، عليك سجود السهو؛ لأنك زدت ركوعاً سهواً فعليك بعد الفراغ من التحيات والدعاء سجدتان للسهو تسجدين سجدتين مثل سجود الصلاة تقولين فيهما: سبحان ربي الأعلى، سبحان ربي الأعلى، وتجلسين بينهما مثلما تجلسين بين السجدتين تقولي: رب اغفر لي، رب اغفر لي بين السجدتين ثم تسلمين، هذا الذي عليك، وهكذا لو زدت سجوداً أو زدت ركعة خامسة في الظهر أو العشاء أو العصر أو رابعة في المغرب أو ثالثة في الفجر سهواً ثم تذكرت تسجدي للسهو. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8324/حكم-من-زاد-ركوعا-في-صلاته-سهوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_307/30705.mp3","categories":["سجود السهو"]},{"id":10172,"question":"يقول: إذا نسيت سجوداً في الركعة الأولى، ولم أذكر إلا عند الشروع في الركعة الثانية، فهل آتي بركعة أخرى قبل التشهد الأخير، أم بعده قبل السلام؟","title":"حكم من نسي سجوداً في الصلاة","answer":"الجواب: إذا ذكرت السجود قبل الشروع تأتي بالسجود، إذا سجدت سجدة واحدة ثم عرفت أنه.. تحسب أنك سجدت الثانية ثم انتبهت تسجد الثانية ولا تنهض، ولو نهضت ترجع تأتي بالسجود الثاني، سواء لو نبهك المأمومون أو انتبهت أنت بنفسك إن كنت إماماً أو مأموماً أو منفرداً ترجع تأتي بالسجود، لكن إذا كنت شرعت في القراءة تستمر في صلاتك تزيد ركعة بدل الركعة التي بطلت، تزيد ركعة أخرى بدل الركعة التي تركت سجودها كأنها معدومة، وتسجد للسهو إن كنت إماماً أو منفرداً، تسجد للسهو إن كنت إماماً أو منفرداً، أما إن كنت مأموماً فإنك إذا سلم إمامك، لا، تقوم وتأتي بركعة بدل الركعة اللي تركت منها السجود وتسلم وليس عليك سجود للسهو لأنك تبع الإمام من أول الصلاة، أما إن كنت...... مسبوقاً بركعة أو بركعتين فإنك تكمل وتسجد للسهو بعد التكميل، وأما إذا كنت مع الإمام من أول الصلاة ونسيت السجدة ما ذكرتها إلا وأنت مع الإمام قائم للقراءة فإنك تأتي بركعة بعد سلام إمامك وليس عليك سجود سهو لأنك دخلت معه من أولها فيتحمل عنك سجود السهو. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8345/حكم-من-نسي-سجودا-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_308/30806.mp3","categories":["سجود السهو"]},{"id":10184,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من تبوك، باعثتها إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (ش. ع. غ. ص) ، تقول أختنا: يوجد في بعض الأسواق مصلى للنساء وهو ملتصق بالمسجد في ذلك السوق، فهل يجب على النساء اللائي يصلين فيه أن يلتزمن بصلاة إمام المسجد أم يصلين لوحدهن، مع العلم أنهن يسمعن صوت الإمام؟ جزاكم الله خيرا.","title":"حكم ائتمام النساء بالإمام الذي لا يرينه ولا يرين المأمومين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفإن هؤلاء النسوة يصلين وحدهن، ولا يقتدين بالإمام إذا كن لا يرين الإمام ولا يرين المأمومين وإنما يسمعن الصوت، الصوت لا يكفي ما دمن خارج المسجد، ما دمن خارج المسجد يصلين وحدهن كل واحدة تصلي وحدها، أما إذا كن يرين الإمام أو المأمومين، أو كن في داخل المسجد فلا بأس فيكفي أن يقتدين بالإمام في هذه الحالة، أما إذا كن خارج المسجد فإنهن يصلين وحدهن إذا كن لا يرين الإمام ولا يرين المأمومين. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8354/حكم-اىتمام-النساء-بالامام-الذي-لا-يرينه-ولا-يرين-المامومين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_278/27801.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10188,"question":"تقول: إذا أخطأ الإنسان في قراءة القرآن أثناء الصلاة، فهل عليه سجود السهو؟","title":"حكم سجود السهو لمن أخطأ في القرآن في الصلاة","answer":"الجواب: الخطأ يختلف ويتنوع؛ فإن كان الخطأ مما يبطل عمدُه الصلاة، ولكن فعله ساهيًا فهذا يسجد للسهو، أما إذا كان لا يبطل عمدُه الصلاة كاللحن الذي يُعفى عنه فهذا لا يجب فيه سجود السهو، فلو قال: (الحمدَ لله رب العالمين) أو قال: (الحمد لله رب العالمين الرحمنَ الرحيم) أو (الرحمنُ الرحيم) هذا لا يبطل عمدُه الصلاة؛ لأن له وجهًا من الإعراب، وهكذا لو قال: (مالكُ يوم الدين) أو (مالكَ يوم الدين) هذا اللحن بالنصب أو الرفع لا يخل بالمعنى.  أما إذا سها فقرأ شيئًا يبطل عمدُه الصلاة سهوًا منه فإنه يسجد للسهو، كأن يقرأ: (صراط الذين أنعمتُ عليهم)، هذا ينسب النعمة إليه، هذا لحن عظيم يخل بالمعنى، فالمنعم هو الله وحده، صراطَ الذين أنعمتَ عليهم يعني: الرب عز وجل، هذا لحن شنيع إذا تعمده أبطل الصلاة، وإذا كان سهوًا يسجد للسهو، يعيد القراءة صراط الذين أنعمت عليهم ويسجد للسهو، وهكذا لو قال: (إياكِ نعبد وإياكِ نستعين) هذا لحن يحيل المعنى؛ لأنه خطاب للأنثى، والخطاب مع الله إياكَ نعبد ، فإذا تعمد هذا بطلت صلاته، وقد يكون بهذا مرتدًّا إذا عرف أنه يخاطب أنثى، أنه يتعمد يخاطب ربه خطاب الأنثى، فإنه يعتبر مستهزئًا كافرًا محتقراً لربه ، أما إذا سبق على لسانه سهوًا فإنه يسجد للسهو. نسأل الله السلامة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8361/حكم-سجود-السهو-لمن-اخطا-في-القران-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_309/30904.mp3","categories":["سجود السهو"]},{"id":10191,"question":"تقول: إذا أخطأ الإنسان في قراءة القرآن أثناء الصلاة، فهل عليه سجود السهو؟","title":"حكم سجود السهو لمن أخطأ في القرآن في الصلاة","answer":"الجواب: الخطأ يختلف ويتنوع؛ فإن كان الخطأ مما يبطل عمدُه الصلاة، ولكن فعله ساهيًا فهذا يسجد للسهو، أما إذا كان لا يبطل عمدُه الصلاة كاللحن الذي يُعفى عنه فهذا لا يجب فيه سجود السهو، فلو قال: (الحمدَ لله رب العالمين) أو قال: (الحمد لله رب العالمين الرحمنَ الرحيم) أو (الرحمنُ الرحيم) هذا لا يبطل عمدُه الصلاة؛ لأن له وجهًا من الإعراب، وهكذا لو قال: (مالكُ يوم الدين) أو (مالكَ يوم الدين) هذا اللحن بالنصب أو الرفع لا يخل بالمعنى.  أما إذا سها فقرأ شيئًا يبطل عمدُه الصلاة سهوًا منه فإنه يسجد للسهو، كأن يقرأ: (صراط الذين أنعمتُ عليهم)، هذا ينسب النعمة إليه، هذا لحن عظيم يخل بالمعنى، فالمنعم هو الله وحده، صراطَ الذين أنعمتَ عليهم يعني: الرب عز وجل، هذا لحن شنيع إذا تعمده أبطل الصلاة، وإذا كان سهوًا يسجد للسهو، يعيد القراءة صراط الذين أنعمت عليهم ويسجد للسهو، وهكذا لو قال: (إياكِ نعبد وإياكِ نستعين) هذا لحن يحيل المعنى؛ لأنه خطاب للأنثى، والخطاب مع الله إياكَ نعبد ، فإذا تعمد هذا بطلت صلاته، وقد يكون بهذا مرتدًّا إذا عرف أنه يخاطب أنثى، أنه يتعمد يخاطب ربه خطاب الأنثى، فإنه يعتبر مستهزئًا كافرًا محتقراً لربه ، أما إذا سبق على لسانه سهوًا فإنه يسجد للسهو. نسأل الله السلامة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8361/حكم-سجود-السهو-لمن-اخطا-في-القران-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_309/30904.mp3","categories":["سجود السهو"]},{"id":10200,"question":"تقول أختنا في سؤال آخر: هل إذا اجتمع النساء في وقت الصلاة في مسجد أو في مكان طاهر، فهل يجب عليهن أن يصلين جماعة، أم تصلي كل واحدة منهن لوحدها، وإذا صلين جماعة فما هي صفة الإمامة لهن، وهل تقرأ جهراً أم سرًا؟ وهل تكون صلاة الجماعة في هذه الحالة واجبة عليهن أم مستحبة لهن جزاكم الله خيرًا؟","title":"حكم صلاة الجماعة للنساء","answer":"الجواب: إذا اجتمع النساء في أي مكان لم تجب عليهن الجماعة، كل واحدة لها أن تصلي وحدها ولا حرج؛ لأن الجماعة من شأن الرجال، أما النساء فليس عليهن جماعة، لكن لو صلين جماعة وأمتهن إحداهن فلا بأس، فقد روي عن عائشة رضي الله عنها وأم سلمة أنهما أمتا في بعض الأحيان بعض النساء، فإذا صلت المرأة بجماعة من النساء في بيتها أو في أي مكان فلا حرج.\nوإذا صلت بالنساء تقف وسطهن تكون في وسطهن لا تتقدم مثل الرجل، تكون في وسط الصف الأول وترفع صوتها بالتكبير، وإذا كانت الصلاة جهرية كالمغرب والعشاء والفجر تجهر بالقراءة حتى تسمعهن وتفيدهن، وإذا كانت سرية كالرجل تسر بالقراءة، لكن ترفع صوتها بالتكبير، وبقول: سمع الله لمن حمده مثل الرجل حتى تسمع النساء وحتى يقتدين بها، وعليها الخشوع والطمأنينة وعدم العجلة حتى يتأسين بها، نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8355/حكم-صلاة-الجماعة-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_278/27802.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10247,"question":"المستمع سعد حسن مصري يعمل في المملكة بعث بسؤالين، يقول في الأول منهما: أعمل في المزرعة بالمنطقة الشرقية من المملكة وأعمل في المزرعة طوال الوقت، وأصلي الفروض داخل المزرعة، لكن إذا جاء يوم الجمعة واستأذنت كفيلي لا يسمح لي فكيف تنصحونني جزاكم الله خيرًا؟","title":"حكم صلاة العامل للمكتوبات في المزرعة","answer":"الجواب: إذا كنت قريبًا من المسجد تسمع النداء فعليك أن تصلي في المسجد، أما إذا كنت بعيدًا لا تسمع النداء فلا حرج أن تصلي في المرزعة، لقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر، قيل لـابن عباس: ما هو العذر؟ قال: خوف أو مرض. ولأنه ﷺ جاءه رجل أعمى فقال: يا رسول الله! ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي فيي بيتي؟ فقال له النبي ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب ، فهذا أعمى ليس له قائد، ومع هذا أمره النبي ﷺ أن يجيب على المؤذن، وأن يحضر إلى الجماعة.\nفهكذا العمال في المزارع، وفي التعمير، وفي غير ذلك يلزمهم أن يصلوا في الجماعة في المساجد، إذا كانوا قريبين من المساجد يسمعون النداء، وإلا صلوا في محلهم جماعة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8419/حكم-صلاة-العامل-للمكتوبات-في-المزرعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27905.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10254,"question":"رسالة من المستمع عبدالله عبدالله من الجمهورية العراقية بغداد بعث برسالة يقول فيها: بالقرب من دارنا يوجد مسجد كنا نصلي فيه الجماعة، وبعد مدة وجدنا أن إمام المسجد وشيخه يبتدع أمورًا لا أصل لها في الدين كالدروشة وغيرها، فهل يجوز الصلاة وراءه بماذا تفيدوننا وتنصحوننا جزاكم الله خيرًا؟","title":"حكم الصلاة خلف من يبتدع بدعة كالدروشة","answer":"الجواب: هذا شيء مبهم، فإن الدروشة ليس لها حد معروف، لابد من البيان، هذه الدروشة ما هي الدروشة هل هي بدعة معروفة؟ أو دعاء غير الله أو الاستغاثة بغير الله؟ أو ما هي الدروشة؟ لا يمكن الجواب عن هذا إلا ببيان الدروشة. نعم.\nالمقدم: إذًا: في انتظار رسالة الأخ عبد الله الثانية حتى يوضح هذا الموضوع؟\nالشيخ: نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8425/حكم-الصلاة-خلف-من-يبتدع-بدعة-كالدروشة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_336/33607.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10262,"question":"الأخ المستمع علي محمد فتحي غروي من جازان بعث برسالة يقول فيها: البعض من الناس يطيلون في قراءة الفاتحة فيركع الإمام وما زال المأموم واقفًا يقرأ الفاتحة، فعندما يرفع الإمام من الركوع يبدأ المأموم في الركوع، ولا يلحق الركعة مع الإمام، ما حكم صلاة مثل هؤلاء؟","title":"حكم التأخر عن متابعة الإمام في الصلاة","answer":"الجواب: لا يجوز هذا، الواجب على المأموم إذا ركع إمامه أن يركع، لقول النبي ﷺ: إذا ركع فاركعوا، وإذا قال: سمع الله لمن حمده فقولوا: ربنا ولك الحمد، وإذا سجد فاسجدوا فإذا ركع إمامه ركع وسقط عنه باقي الفاتحة، كما لو جاء والإمام راكع فإنه يركع معه وتسقط عنه الفاتحة، لحديث أبي بكرة في صحيح البخاري رحمه الله، أن أبا بكرة  الثقفي جاء والإمام راكع النبي راكع عليه الصلاة والسلام فركع دون الصف ثم دخل في الصف، فلما سلم النبي ﷺ، قال له: زادك الله حرصًا ولا تعد ولم يأمره بقضاء الصلاة.\nفدل ذلك على صحتها لأنه معذور لما فاته القيام سقطت عنه الفاتحة.\nوهكذا المأموم إذا ركع إمامه قبل أن يكملها ركع مع إمامه، وسقط عنه باقيها، وينبغي له أن يلاحظ ذلك حال قيامه حتى يقرأها قبل ركوع إمامه، يبدأ بقراءتها في أول الركعة حتى يقرأها قبل إمامه قبل أن يركع، ولا يتساهل. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8433/حكم-التاخر-عن-متابعة-الامام-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_337/33702.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10280,"question":"أيضاً يقول: فاتتني صلاة العشاء مع الجماعة في شهر رمضان، ودخلت المسجد والإمام يصلي التراويح، فدخلت معه على نية صلاة العشاء، ولما سلم الإمام وقفت للركعة الثالثة، وقد وقف الإمام للصلاة، فأكملت معه الركعتين التاليتين من صلاة التراويح، فأصبحت في حقي أربع ركعات، هل يجوز ذلك؟ وهل تعتبر حينئذٍ صلاتي صحيحة؟","title":"صلاة المفترض خلف المتنفل صحيحة","answer":"الجواب: كان الذي ينبغي لك لما سلم تقوم وتكمل صلاتك، إذا سلم من الثنتين تقوم أنت وتكمل صلاتك وحدك، كالذي يصلي مع إنسانٍ فاته بعضها، فيقوم بعد سلام إمامه يكمل، والصواب أن الصلاة صحيحة، وأن صلاة المفترض خلف المتنفل صحيحة، هذا هو الأرجح من قولي العلماء؛ أنه يجوز للمفترض أن يصلي خلف المتنفل، كما كان معاذ  يصلي بأصحابه العشاء، وهو قد صلاها مع النبي ﷺ، فيصلي بهم متنفلاً، وهم مفترضون.\nأما هذه الحالة التي سلم إمامك، ثم قمت وتابعته في الركعتين الأخريين، حتى كملت أربعاً، في صحتها نظر، والأقرب والله أعلم أنها صحيحة إن شاء الله، ليس عليك إعادة، هذا هو الأقرب إن شاء الله، ولكن في المستقبل إذا كان مثل هذا، فالأحوط لك إذا سلم أن تقضي وحدك ما بقي عليك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8449/صلاة-المفترض-خلف-المتنفل-صحيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_311/31105.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10281,"question":"من أحد الإخوة المستمعين هو جمال حمود المخادري من اليمن، سؤال يقول فيه: ما حكم من صلى بالناس جماعة، ثم سها فسجد ولم يركع، هل صلاته باطلة أم صحيحة؟","title":"حكم من صلى بالناس فسجد ولم يركع سهواً","answer":"الجواب: إذا نبهوه يرجع، يقوم ويأتي بالركوع، يقوم ينتصب قائماً ثم يكبر ويركع.\nوأما إذا كان ما نبهوه إلا بعد السلام يأتي بركعة، يقوم ويأتي بركعة كاملة، ثم يتشهد ويكمل ويصلي على النبي ويدعو، ثم يسجد سجدتين للسهو، ثم يسلم.\nأما إذا ما تذكر إلا بعدما طال الفصل؛ فإنه يعيد الصلاة كلها، ويخبر الذين معه أن يعيدوا الصلاة، الذين معه ولم يركعوا يعيدوها؛ لأن صلاتهم باطلة لما طال الفصل، أما إذا تنبه بعد السلام أو نبهه الجماعة، فإنه يقوم ويأتي بركعةٍ كاملة، وبعد الفراغ من التشهد والدعاء، يسجد سجدتين للسهو ثم يسلم. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8454/حكم-من-صلى-بالناس-فسجد-ولم-يركع-سهوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_311/31110.mp3","categories":["سجود السهو"]},{"id":10300,"question":"من المخواه المستمع (ع. ع. ج) بعث يسأل ويقول: هل يجوز لرجل لا يحفظ إلا الفاتحة أن يكون إماماً؟","title":"حكم إمامة من لا يحفظ إلا الفاتحة","answer":"الجواب: يجوز أن يكون إماماً، ولكن غيره أفضل منه، الذي يحفظ زيادة وعنده علم وعنده سور أخرى أفضل وأولى وإلا الفاتحة هي الركن تجزي وتصح الصلاة معها من الإمام والمنفرد والجماعة، لكن وجود إمام يحفظ زيادة على الفاتحة ويصلي بإخوانه أفضل وأولى إذا كان مستقيماً عدلاً، أما إذا لم يوجد من هو مستقيم إلا من يحفظ الفاتحة فقط صلى بالجماعة، ولكن بحمد الله ميسر له أن يقرأ زيادة ويتحفظ زيادة من الآيات والسور القصيرة إذا اجتهد يسر الله أمره، وإذا لم يقرأ إلا الفاتحة أجزأه ذلك والحمد لله، لكن يلتمسون من يكون عنده حفظ للزيادة على الفاتحة من أهل الخير؛ لأن ذلك أولى حتى يسمعهم ما تيسر من القرآن بعد الفاتحة اقتداءً بالنبي ﷺ وبأصحابه  وبعلماء المسلمين بعد ذلك، هكذا السنة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8469/حكم-امامة-من-لا-يحفظ-الا-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_312/31209.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10334,"question":"يسأل أخونا ويقول: ما هي الأعذار التي تجيز للمسلم التخلف عن حضور صلاة الجماعة في المسجد؟","title":"الأعذار المبيحة للتخلف عن صلاة الجماعة","answer":"الجواب: الأعذار ذكر العلماء منها عدة: منها المرض إذا كان مريض يشق عليه الخروج، ومنها الخوف إذا كان في بلاد فيها خوف لو خرج يخشى على نفسه، ومنها: حضور أحد الخبثين البول أو الغائط، كونه يتخلف لأجل قضاء حاجته، الحدث نزل به هذا ولم يتيسر له الخروج لأجل قضاء الحاجة وفاتته الجماعة فهو معذور، لكن ينبغي له أن يتحرى قبل ذلك بوقت حتى يتفرغ للجماعة، لكن لو حدث.. أراد الخروج فحدث به حادث البول أو الغائط فإنه مأمور بالتخلص منهما، لقول النبي ﷺ: لا صلاة بحضرة الطعام ولا وهو يدافع الأخبثان.\nومنها لو حضر الطعام بين يديه فإنه يبدأ به، لا يتخذه عادة يقدم الطعام حتى يتخلف عن الصلاة، لا، لكن لو قدم بين يديه في بيته أو عند بعض من استضافهم فإنه يبدأ بالطعام ولو فاتته الجماعة.\nهذه من الأعذار ومنها لو كان بعيد ما يسمع النداء.. المساجد بعيدة عنه، لا يسمع النداء هذا عذر أيضاً، أما إذا كان يسمع النداء فيلزمه أن يجيب من طريق الصوت العادي، أما من طريق المكبرات قد يسمع من بعيد ولا يلزمه لأنه بعيد، لكن إذا كان بالصوت العادي من غير مكبر يسمع عند خلو الأصوات يسمع عليه أن يجيب، لقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر أو كان في البلد فإنه يجيب؛ لأن البلد لو هدأت الأصوات لسمع، فهذا يجيب ويصلي مع الناس، ولا يتأخر. نعم.","link":"https://binbaz.org.sa/fatwas/8512/الاعذار-المبيحة-للتخلف-عن-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_315/31512.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10378,"question":"أيضاً يسأل عن عبارات لـابن القيم عليه رحمة الله فيقول : قال ابن القيم: التخفيف أمر نسبي يرجع فيه إلى ما فعله النبي ﷺ لا إلى شهوات المأمومين، ما المقصود بالأمر النسبي وما المقصود بشهوات المأمومين؟","title":"هدي النبي في التخفيف على المأمومين في الصلاة","answer":"الجواب: مثلما تقدم أنه يتأسى بالنبي ﷺ في التخفيف فيقرأ كما قرأ النبي ﷺ، ويركع كما ركع، ويسجد كما سجد، يكون متوسطًا لا مطيلًا ولا ناقرًا، بين النقر وبين الإطالة التي تشق على الناس، هذا هو التأسي بالنبي ﷺ، ولا يتأسى بالنقارين الذين يسرعون في الصلاة حتى لا يمكنون الناس من أداء المشروع، ولا يتأسى بالمطولين المنفرين ولكن بين ذلك، والأسوة هو النبي ﷺ؛ لأنه قال: صلوا كما رأيتموني أصلي، وقال الرب جل وعلا: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21]، فالتأسي بالنبي هذا هو التوسط. اللهم صل عليه ...\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8549/هدي-النبي-في-التخفيف-على-المامومين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_280/28003.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10402,"question":"رسالة وصلت إلى البرنامج من العراق وباعثها المستمع (ح. م. م) يقول في رسالته: هل تجوز الصلاة في البيت، علمًا بأن المسجد ليس ببعيد عن بيتي ولكني أذهب لصلوات الجمعة، وأصلي التراويح وأذهب بعض الأوقات، فهل صلاتي صحيحة؟","title":"حكم صلاة الفريضة في البيت","answer":"الجواب: لا يجوز للمسلم أن يصلي في البيت وهو قادر على المسجد وهو يسمع النداء، بل عليه أن يجيب ويصلي مع المسلمين، لقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر، قيل لابن عباس: ما هو العذر؟ قال: مرض أو خوف، وجاءه ﷺ رجل أعمى فقال: يا رسول الله! ليس لي قائد يلائمني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له -المصطفى عليه الصلاة والسلام-: هل تسمع النداء بالصلاة؟ قال: نعم. قال: فأجب وفي رواية قال: لا أجد لك رخصة فإذا كان رجل أعمى الذي ليس له قائد يلائمه ليس له رخصة فكيف بالصحيح البصير.\nالمقصود: أن الواجب على المسلمين من الرجال الصلاة في المساجد وعدم الصلاة في البيوت.\nواختلف العلماء هل تصح أو لا تصح، إذا صلى في البيت، فالأكثرون: على أنها تصح مع الإثم، وقال آخرون: لا تصح؛ لأن من شرطها أن تؤدى في الجماعة مع القدرة.\nفالواجب عليك يا أخي! أن تحرص على أدائها في الجماعة في بيوت الله عز وجل، وأن تحذر التساهل بذلك، وقد ثبت عنه ﷺ أنه هم أن يحرق على المتخلفين بيوتهم، وما ذاك إلا لشدة الجريمة، فاحمد الله يا أخي! على ما أ عطاك من العافية وبادر وسارع إلى أداء الصلاة في الجماعة ما دام المسجد قريبًا تسمع النداء، لو كان النداء بالصوت العالي لا بالمكبر فإنه يلزمك الحضور، أما بالمكبر فإن المكبر يسمع من بعيد، فإذا كان بعيدًا عنك يشق عليك الحضور وربما فاتت الصلاة إذا خرجت بعد الأذان ربما فاتت الصلاة لبعده فلا يلزمك، بل تصلي أنت وجيرانك في محل آخر حتى يبنى لكم مسجد، أما ما دمت تسمع النداء فالواجب عليك أن تذهب إليه، وإذا كان السماع بالمكبر واستطعت أن تذهب فهذا خير عظيم، وإن شق عليك ذلك جاز لك أن تصلي وحدك حتى يتيسر لك جماعة أو مسجد قريب؛ لأن الله يقول:فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] والنبي ﷺ يقول: من سمع النداء وأنت لا تسمع النداء لولا المكبر، أما إذا كان تسمعه لو كان هناك نداء بدون مكبر تسمعه لقربك فإنه يلزمك الصلاة مع إخوانك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8575/حكم-صلاة-الفريضة-في-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_340/34009.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10436,"question":"أيضاً يصف بعض الأئمة بقوله: يقع أكثرهم في اللحن الجلي: كإبدال حرف مكان حرف أو حركة مكان حركة، أو ترك المد الطبيعي أو المد الواجب، وعدم الإظهار في موضع الإظهار، وكذلك عدم الإدغام في موضعه، وقرأنا لأهل العلم أن من يقع في اللحن الجلي لا تنبغي الصلاة خلفه. افتونا رحمكم الله، هل نصلي خلف هؤلاء، أم يكون ذلك عذراً يبيح لنا الصلاة في بيوتنا حتى لو أديناها فرادى؟ وقد نصحنا لهم كثيراً، ولكن لا سامع منهم ولا مجيب؟","title":"حكم الصلاة خلف إمام يلحن لحناً جلياً","answer":"الجواب: اللحن قسمان أيها السائل وأيها المستمع، اللحن قسمان:\nلحن يحيل المعنى فهذا ينبه عليه الإمام حتى يعتدل في القراءة مثل أن يقرأ: صراط الذين أنعمت عليهم، أنعمت بضم التاء، أو أنعمت بكسر التاء، هذا غلط عظيم ينبه حتى يعدل القراءة، أو يقرأ إياك بكسر الكاف يخاطب المرأة، فيعدل ينبه حتى يعدل القراءة، أما اللحن اللي ما يحيل المعنى مثل إظهار في محل إخفاء أو في محل إدغام، أو إدغام في محل إظهار فهذا ما يضر ما يحيل المعنى، ولا يستوجب التخلف عن الصلاة، بل هذا من باب تحسين القراءة، كذلك المد المتصل والمد اللازم إن مد فهو أكمل للقراءة وإلا ما يضر ولا يخل بالمعنى.\nفينبغي لك أيها السائل أن لا تتشدد في الأمور وأن لا تغلو، فالتجويد في هذه المسائل من باب تحسين القراءة وليس من باب الإلزام، ولكن من باب التحسين للقراءة وتجويدها وتقويتها، وإذا قرأ قراءة عربية ليس فيها ما يغير المعنى فلا بأس، فإذا قال: الحمد لله رب العالمين ما يضر رب العالمين له معنى في الإعراب، يعني: هو رب العالمين مقطوع، أو قرأ: الحمد لله رب العالمين له معنى في العربية معناه: أعني رب العالمين منصوب بتقدير فعل محذوف، وإن كان القراءة المتبعة رب نعت لما قبلها: الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝ الرَّحْمَنِ الرَّحِيمِ [الفاتحة:2-3] هذه هي القراءة المعلومة والذي ينبغي للقارئ أن يلاحظها، لكن لو رفع أو نصب ما يضر ما يحيل المعنى، أو قال في قراءته: اهدنا الصراط المستقيم، الصراط المستقيم أو الصراط المستقيم ما يضر بالمعنى، أو أظهر في محل الإدغام أو أدغم في محل الإظهار أو أظهر في محل الإخفاء فلا يضر ذلك في المعنى ولا يخل بالمعنى.\nفلا ينبغي للمؤمن أن يشدد في هذه المسائل، ولكن يجتهد في وصية أخيه بأن يحسن القراءة ويجودها حتى تكون قراءة حسنة جيدة ماشية على الطرق المتبعة والقواعد المعمول بها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8611/حكم-الصلاة-خلف-امام-يلحن-لحنا-جليا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_318/31803.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10443,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين سمى نفسه في نهاية رسالته فقال: أخوكم في الله ابن مسعود ، أخونا له جمع من الأسئلة من بينها سؤال يقول: إذا شرع الإنسان في صلاة النافلة وأقيمت الصلاة المكتوبة وأثناء تأديته للنافلة، هل يتم صلاته، أم يقطعها بالدخول في الفريضة؟ وإذا قلتم بقطع النافلة فهل تصير ديناً عليه أن يؤديها بعد الفريضة أم لا، جزاكم الله خيراً؟","title":"حكم من شرع في صلاة نافلة ثم أقيمت صلاة الفريضة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفقد شرع الله جل وعلا للمسلم إذا سمع الإقامة أن يقطع الصلاة التي هو فيها ويشتغل بالفريضة، فقد ثبت عن رسول الله عليه الصلاة والسلام أنه قال: إذا أقيمت الصلاة فلا صلاة إلا المكتوبة خرجه مسلم في صحيحه، فإذا أقيمت الصلاة والمؤمن يصلي فإنه يقطعها سواءً تحية المسجد أو راتبة، يقطعها ويشتغل بالفريضة، وليس عليه قضاؤها بعد ذلك؛ لأنها نافلة لا يجب عليه قضاؤها والحمد لله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8609/حكم-من-شرع-في-صلاة-نافلة-ثم-اقيمت-صلاة-الفريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_318/31801.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10457,"question":"من المستمع (ف. ح) من الدمام رسالة ضمنها جمعاً من الأسئلة، في أحدها يقول: إذا أدركت صلاة الجماعة وهم في التشهد الأخير، فهل أكون بهذا قد أدركت فضل صلاة الجماعة، أم يجب علي انتظار بعض المصلين المتأخرين لنصلي جماعة ليتم لنا فضل صلاة الجماعة، أفيدونا جزاكم الله خيراً؟","title":"إدراك فضل الجماعة بإدراك التشهد الأخير","answer":"الجواب: يقول النبي ﷺ في الحديث الصحيح: لا تأتوا الصلاة وأنتم تسعون، وأتوها عليكم السكينة، فما أدركتم فصلوا، وما فاتكم فأتموا فقوله: فما أدركتم فصلوايعم من أدركها، من أدرك الإمام في التشهد، ولكن لا تدرك الجماعة إلا بركعة لقوله ﷺ: من أدرك ركعة من الصلاة فقد أدرك الصلاةفهي تدرك بركعة الجماعة، ولكن إذا كان معذور أحياناً يتأخر يكون له فضل الجماعة ولو ما أدركها بالكلية، إذا تأخر عن عذر شرعي كقضاء حاجة الإنسان، لما أراد الذهاب إلى المسجد، نزل به حاجة الإنسان من بول أو غائط فتأخر من أجل ذلك، أو غير ذلك من الأعذار الشرعية، فله فضل الجماعة، ولكن لا تدرك الجماعة بغير عذر بإدراك التشهد ولكن بركعة فأكثر، وإذا كانوا جماعة وصلوا وحدهم فلا بأس، وإن دخلوا مع الإمام في التشهد فلا بأس الأمر واسع، إن دخلوا معه لعموم قوله: فما أدركتم فصلوافلا بأس، وإن صلوا وحدهم؛ لأن الصلاة ما بقي منها إلا التشهد فلا حرج إن شاء الله. نعم.\nالمقدم: جزاكم الله خيراً، إنما فضيلة الجماعة لا بد بركعة؟\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/8627/ادراك-فضل-الجماعة-بادراك-التشهد-الاخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_319/31905.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10458,"question":"من لواء تعز في اليمن المستمع عبدالودود عبدالله ناجي مجاهد التميمي بعث برسالة ضمنها جمعاً من الأسئلة من بينها سؤال يقول: إذا اختلفت نية الإمام والمأموم فهل الصلاة صحيحة؟","title":"حكم الصلاة إذا اختلفت نية الإمام والمأموم","answer":"الجواب: الصواب أنها صحيحة، الصواب أنها صحيحة إذا كان الإمام مثلاً يصلي العصر وجاء إنسان ما صلى الظهر، وصلى خلفه بنية الظهر صحت على الصحيح، أو كان الإمام قد أدى الفريضة وصلى بالناس الآخرين النافلة وهي لهم فريضة كذلك، كما فعل معاذ كان يصلي مع النبي ﷺ فريضته ثم يأتي لقومه ويصلي بهم فريضتهم وهو متنفل، أو كان الإمام مفترض والمأمومون متنفلون لا حرج في ذلك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8633/حكم-الصلاة-اذا-اختلفت-نية-الامام-والماموم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_319/31911.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10459,"question":"من المستمع (ف. ح) من الدمام رسالة ضمنها جمعاً من الأسئلة، في أحدها يقول: إذا أدركت صلاة الجماعة وهم في التشهد الأخير، فهل أكون بهذا قد أدركت فضل صلاة الجماعة، أم يجب علي انتظار بعض المصلين المتأخرين لنصلي جماعة ليتم لنا فضل صلاة الجماعة، أفيدونا جزاكم الله خيراً؟","title":"إدراك فضل الجماعة بإدراك التشهد الأخير","answer":"الجواب: يقول النبي ﷺ في الحديث الصحيح: لا تأتوا الصلاة وأنتم تسعون، وأتوها عليكم السكينة، فما أدركتم فصلوا، وما فاتكم فأتموا فقوله: فما أدركتم فصلوايعم من أدركها، من أدرك الإمام في التشهد، ولكن لا تدرك الجماعة إلا بركعة لقوله ﷺ: من أدرك ركعة من الصلاة فقد أدرك الصلاةفهي تدرك بركعة الجماعة، ولكن إذا كان معذور أحياناً يتأخر يكون له فضل الجماعة ولو ما أدركها بالكلية، إذا تأخر عن عذر شرعي كقضاء حاجة الإنسان، لما أراد الذهاب إلى المسجد، نزل به حاجة الإنسان من بول أو غائط فتأخر من أجل ذلك، أو غير ذلك من الأعذار الشرعية، فله فضل الجماعة، ولكن لا تدرك الجماعة بغير عذر بإدراك التشهد ولكن بركعة فأكثر، وإذا كانوا جماعة وصلوا وحدهم فلا بأس، وإن دخلوا مع الإمام في التشهد فلا بأس الأمر واسع، إن دخلوا معه لعموم قوله: فما أدركتم فصلوافلا بأس، وإن صلوا وحدهم؛ لأن الصلاة ما بقي منها إلا التشهد فلا حرج إن شاء الله. نعم.\nالمقدم: جزاكم الله خيراً، إنما فضيلة الجماعة لا بد بركعة؟\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/8627/ادراك-فضل-الجماعة-بادراك-التشهد-الاخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_319/31905.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10460,"question":"من لواء تعز في اليمن المستمع عبدالودود عبدالله ناجي مجاهد التميمي بعث برسالة ضمنها جمعاً من الأسئلة من بينها سؤال يقول: إذا اختلفت نية الإمام والمأموم فهل الصلاة صحيحة؟","title":"حكم الصلاة إذا اختلفت نية الإمام والمأموم","answer":"الجواب: الصواب أنها صحيحة، الصواب أنها صحيحة إذا كان الإمام مثلاً يصلي العصر وجاء إنسان ما صلى الظهر، وصلى خلفه بنية الظهر صحت على الصحيح، أو كان الإمام قد أدى الفريضة وصلى بالناس الآخرين النافلة وهي لهم فريضة كذلك، كما فعل معاذ كان يصلي مع النبي ﷺ فريضته ثم يأتي لقومه ويصلي بهم فريضتهم وهو متنفل، أو كان الإمام مفترض والمأمومون متنفلون لا حرج في ذلك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8633/حكم-الصلاة-اذا-اختلفت-نية-الامام-والماموم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_319/31911.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10462,"question":"ما هي الأحكام التي يجب أن يقتدي بها المصلون خلف الإمام في صلاة الفجر والمغرب والعشاء، وهل يقرءون الفاتحة وسورة قصيرة عندما يقرأ الإمام، أم يكتفون بقراءة الإمام؟","title":"وجوب اقتداء المأموم بالإمام في الصلاة","answer":"الجواب: المأموم تابع لإمامه في جميع الصلوات، تابع الإمام؛ لأنه إنما جعل ليؤتم به، فلا يختلف عليه المأموم ولكن بعده، إذا كبر كبر، وإذا ركع ركع، وإذا رفع رفع وهكذا، وينصت لقراءته في الفجر والمغرب والعشاء، ينصت إذا قرأ الإمام، وعليه أن يقرأ الفاتحة فقط في الجهرية يقرؤها سراً وينصت بعد ذلك، لقوله ﷺ: لعلكم تقرءون خلف إمامكم؟ قلنا: نعم. قال: لا تفعلوا إلا بفاتحة الكتاب، فإنه لا صلاة لمن لم يقرأ بها وفي الأخيرتين من العشاء يقرأ الفاتحة فقط، وفي الأخيرة من المغرب كذلك الفاتحة فقط، أما في الظهر والعصر ويقرأ في الأولى والثانية الفاتحة وما تيسر معها الأولى والثانية في الظهر والعصر؛ لأنها سرية يقرأ فيها، نعم. وفي الأخيرة يقرأ الفاتحة فقط، الثالثة والرابعة في الظهر والعصر يقرأ الفاتحة، وإن قرأ مع الفاتحة زيادة في الثالثة والرابعة من الظهر فلا بأس، قد ورد في حديث أبي سعيد عند مسلم ما يدل على ذلك، فإنه  أخبر أنهم حزروا صلاة النبي ﷺ في الظهر والعصر قدر ثلاثين آية، قال: وفي الأخريين من الظهر قدر النصف، هذا يقتضي أنه كان يقرأ في الظهر زيادة على الفاتحة في الثالثة والرابعة، لكن لعل هذا بعض الأحيان؛ لأن أبا قتادة في الصحيحين أخبر أن النبي ﷺ كان لا يقرأ في الثالثة إلا فاتحة الكتاب والرابعة كذلك، في الظهر والعصر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8640/وجوب-اقتداء-الماموم-بالامام-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_320/32006.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10465,"question":"إذا اختلفت نية المأموم والإمام فهل الصلاة صحيحة؟","title":"صحة الصلاة إذا اختلفت نية الإمام والمأموم","answer":"الجواب: الصواب أنها صحيحة؛ لأن الرسول صلى الله عليه وسلم صلى في الخوف ببعض المسلمين ركعتين صلاة الخوف، ثم صلى بطائفة أخرى ركعتين، فصارت الأولى له فريضة والثانية له نافلة وهم لهم فريضة، وكان معاذ  يصلي مع النبي ﷺ في العشاء صلاة الفريضة، ثم يرجع فيصلي بقومه صلاة العشاء نافلة له وهي لهم فرض، فدل ذلك على أن لا حرج في اختلاف النية.\nوهكذا لو أن إنساناً جاء إلى مسجد فصلى العصر وهو لم يصل الظهر، فإنه يصلي معهم العصر بنية الظهر، ولا حرج عليه في أصح قولي العلماء، ثم يصلي العصر بعد ذلك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8635/صحة-الصلاة-اذا-اختلفت-نية-الامام-والماموم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_320/32001.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10527,"question":"يقول: صلينا مدة كبيرة وراء رجل يرابي، وبعدها تاب إلى الله تعالى، لكنه لم يرد المال الذي اكتسبه زيادة على أصحابه، ما هو توجيهكم في صلاتنا السابقة والآن، جزاكم الله خيرًا؟","title":"حكم الصلاة خلف المرابي قبل التوبة توبته وبعدها","answer":"الجواب: الصلاة صحيحة والحمد لله، والتوبة صحيحة من تاب تاب الله عليه إذا تاب توبة صادقة، وإذا كان حين رابى جاهل فله ما سلف، أما إن كان يعلم ويتساهل فيتصدق بما دخله من الربا، يعطيه للفقراء والمساكين؛ لأن الله يقول جل وعلا: وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا فَمَنْ جَاءَهُ مَوْعِظَةٌ مِنْ رَبِّهِ فَانتَهَى فَلَهُ مَا سَلَفَ وَأَمْرُهُ إِلَى اللَّهِ [البقرة:275]، فإذا كان حين جاءته الموعظة حين علم التحريم تاب إلى الله، فله ما سلف ولا يرد معاملته السابقة، أما إذا كان لا قد علم ولكن تساهل واستمر فإنما دخل عليه من الربا لا يجوز له، بل يجب عليه أن يصرفه في وجوه البر والخير، بالصدقة على الفقراء والمساكين، والمشاريع الخيرية، ولا يبقيه لنفسه. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8702/حكم-الصلاة-خلف-المرابي-قبل-التوبة-توبته-وبعدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_283/28316.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10533,"question":"السائلة سماحة الشيخ أيضاً لها سؤال آخر تذكر تقول: زوج أختي يصلي في البيت، ولا يصلي الصلوات في وقتها بل يقوم بجمعها ويصليها أثناء العودة من العمل، هذه الفقرة الأولى؟","title":"حكم من يجمع الصلوات في بيته ويترك الجماعة","answer":"الجواب: هذا منكر، لا يجوز هذا العمل لا بد أن يصلي مع الجماعة، ويصلي الصلاة في وقتها، وليس له تأخيرها عن وقتها، بل يجب أن يصلي الصلاة في وقتها ويجب أن يصليها في الجماعة أيضاً مع إخوانه المسلمين؛ لأن الله وقت مواقيت وقال جل وعلا: إِنَّ الصَّلاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَوْقُوتًا [النساء:103] يعني: مفروضاً في الأوقات، وقال سبحانه: أَقِمِ الصَّلاةَ لِدُلُوكِ الشَّمْسِ إِلَىى غَسَقِ اللَّيْلِ [الإسراء:78] الآية.\nلا بد أن تقام الصلاة في وقتها، وليس له أن يؤخرها عن وقتها، وعليه أن يؤديها في الجماعة؛ لقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر وقيل لـابن عباس : ما هو العذر؟ قال: خوف أو مرض، وجاءه رجل أعمى فقال: يا رسول الله! ليس لي قائد يقودني إلى المسجد فهل لي من رخصة أن أصلي في بيتي؟ فقال صلى الله عليه وسلم: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب فأمره أن يجيب مع أنه أعمى ليس له قائد، فكيف بحال البصير؟! الوجوب عليه أشد وأعظم.\nوتأخير الصلاة عن وقتها كفر أكبر عند جمع من أهل العلم؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة فإذا أخر الفجر حتى تطلع الشمس عمداً أو أخر العصر حتى تغرب الشمس عمداً، فهذا قد أخر الصلاة عن وقتها، فيكفر عند جمع من أهل العلم؛ لقوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه.\nفالواجب الحذر من التساهل بهذا الأمر، نسأل الله العافية والسلامة، نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/8708/حكم-من-يجمع-الصلوات-في-بيته-ويترك-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28405.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10585,"question":"إذا حصل من الإمام سهو، السجود له يحصل بعد السلام، فهل يسلم المأموم مع الإمام ثم إذا نهض من فاتته بعد الركعات من المأمومين، فهل يعود مرة أخرى مع الإمام؟","title":"حكم سجود المسبوق للسهو مع الإمام بعد السلام","answer":"الجواب: إن سجد الإمام والمسبوق لم ينهض سجد معه، أما إذا كان قبل السلام فيسجد معه على كل حال، وأما إذا كان بعد السلام فإن كان الإمام سجد حالاً قبل أن ينهض المأموم -المسبوق- فإنه يسجد معه، ثم بعدما يسلم الإمام يقوم المسبوق ويقضي ما عليه، أما إن كان المسبوق قد استتم قائماً، ثم سجد الإمام فليس عليه أن يعود، ولكن يكمل ما عليه ثم يسجد للسهو بعد قضائه ما عليه؛ لأنه معذور حين انفرد حين نوى الانفراد واستقل عن إمامه، ليقضي ما عليه، فيكون سجوده بعد نهاية ما عليه، أما لو أن الإمام بادر بالسجود من حين سلم قبل أن يقوم المأموم فإنه يسجد معه، والحمد لله ويكفيه ذلك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8755/حكم-سجود-المسبوق-للسهو-مع-الامام-بعد-السلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_324/32403.mp3","categories":["سجود السهو"]},{"id":10645,"question":"سماحة الشيخ! السائل أيضاً من عمان الأردن يقول: ما حكم السلام بعد الصلاة على من يصلي بجانب أخيه المسلم، وما حكم قول: (تقبل الله) بعد السلام أو قبله، وإذا أصر الشخص على قولها دائمًا فهل يجوز أن نرد التحية عليه بمثلما يقول، أي: تقبل الله منا ومنك، وما حكم قول ذلك بعد الخروج من المسجد كأن يقول: تقبل الله منا ومنكم، نرجو من سماحة الشيخ إجابة؟","title":"حكم المصافحة بعد الصلاة، وقول: (تقبل الله منا ومنكم)","answer":"الجواب: لا حرج في ذلك إذا قال لأخيه: تقبل الله منا ومنك بعد الصلاة، أو عند الخروج من المسجد، أو عند اللقاء، أو من صلاة الجنازة، أو من اتباع الجنائز، أو من صلاة الجمعة أو غير ذلك كل هذا خير إن شاء الله، لا حرج في ذلك، فالمسلم يدعو لأخيه بالقبول والمغفرة، وإذا دخل المسجد وصلى الركعتين أو أكثر ثم سلم من على يمينه وعلى شماله هذا هو السنة؛ لأن الرسول ﷺ شرع للأمة إذا تلاقوا أن يتصافحوا، وكانوا إذا لقوا النبي صافحوه عليه الصلاة والسلام، وكانوا إذا تلاقوا تصافحوا الصحابة ، والمصافحة سنة، فإذا لقي أخاه في الصف قبل الصلاة صافحه، أو بعد السلام بعدما صلى الركعتين، صافحه، أو بعد الفريضة إذا كان ما صافحه قبل ذلك، جاء والناس في الصلاة، فلما صلى الفريضة وهلل صافح أخاه كل هذا طيب، لا حرج في ذلك.\nأما كونه إذا سلم الفريضة بدأ يأخذ بيد اللي عن يمينه وشماله وهو قد سلم أو وهو يعرفهم وقد سلم عليهم؛ هذا ما له أصل، لكن إذا كان جاء وهم يصلون ودخل معهم في الصلاة ثم فرغ من الصلاة ومن الذكر صافحهم هذا طيب، نعم.\nالمقدم: جزاكم الله خيراً سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/8822/حكم-المصافحة-بعد-الصلاة-وقول-تقبل-الله-منا-ومنكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28507.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10659,"question":"رجل دخل المسجد والإمام راكع فكبر للركوع، وفي خلال نزوله للركوع كان الإمام يرفع من الركعة، هل يكون الرجل قد أدرك الركعة أم لا؟ وإذا كان لم يدركها فمتى تتحقق الركعة؟","title":"الحال التي يعتبر فيها المأموم مدركاً للركوع مع إمامه","answer":"الجواب: إن استوى راكعاً قبل أن يرفع إمامه فقد أدرك الركعة، إذا وصل إلى حد الركوع قبل أن يرفع إمامه فقد أدرك الركوع، أما عند الهوي رفع الإمام قبل أن يصل حد الركوع فيعتبر غير مدرك، ويقضي هذه الركعة التي لم يدرك فيها الإمام في حال الركوع، وهكذا لو شك يقضي هذه الركعة؛ لأنه لم يتحقق أنه أدرك هذا الركن مع إمامه، أما إذا علم أنه أدرك الركوع، يعني: وصل إلى حد الركوع مع إمامه فإنه يعتبرها، ولو كانت تسبيحه وطمأنينته بعد ذلك، يعني: ولو كان التسبيح والطمأنينة بعد رفع الإمام، ما دام وصل إلى حد الركوع والإمام لم يرفع.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8844/الحال-التي-يعتبر-فيها-الماموم-مدركا-للركوع-مع-امامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_329/32910.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10663,"question":"إذا فاتت المصلي الركعتان الأوليان من صلاة العشاء أو العصر أو الظهر، عندما يقوم لقضائها هل يصلي ركعة ثم يقرأ التشهد الأول ثم يصلي الركعة الأخرى، أم يصليهما بدون تشهد، وكذلك إذا فاتته ثلاث ركعات من الرباعية؟","title":"كيفية قضاء الركعات التي فاتته مع الإمام","answer":"الجواب: إذا فاته اثنتان من المغرب فإنه إذا قام يأتي بواحدة ثم يجلس يأتي بالتشهد الأول؛ لأن السنة في المغرب أن يجلس بعد الثنتين للتشهد الأول، فإذا قرأ واحدة ضمت إلى ما أدركه مع الإمام وصار الجميع ثنتين، فيجلس للتشهد الأول، ثم يقوم فيأتي بالثالثة منفردة يسر بها بالقراءة في المغرب، أما في العشاء فإذا فاته اثنتان فإنه يأتي بالثنتين متتابعتين؛ لأنه لا جلوس فيهما إلا في الأخيرة منهما، وهو الجلوس الأخير، كما هو معلوم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8840/كيفية-قضاء-الركعات-التي-فاتته-مع-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_329/32906.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10664,"question":"أولى قضايا هذه الحلقة قضية بعث بها المستمع مستور حامد عبدالله السواط، أخونا مستور عرضنا بعض أسئلته في حلقات مضت، وفي هذه الحلقة له جمع من الأسئلة فيسأل هذا السؤال ويقول: إذا جاء إنسان والإمام والمأمومون ما زالوا قائمين في الصلاة وكبر تكبيرة الإحرام، وعندما قرأ ثلاث آيات من سورة الفاتحة ركع الإمام، فهل يركع أم يكمل السورة، علماً بأنه إذا أكملها سوف يتأخر عن الإمام والمصلين في الركوع والسجود؟","title":"حكم ركوع الإمام قبل إتمام المسبوق للفاتحة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن الواجب على المأموم متى وصل إلى الإمام وهو في الصلاة الدخول معه في الصلاة، فإذا دخل معه في الصلاة وهو قائم قرأ، ويستحب له أن يستفتح ثم يتعوذ ثم يسمي ثم يقرأ الفاتحة، فإن أمكنه إكمالها فالحمد لله، وإن لم يمكنه ركع مع إمامه ولم يكملها، وإمامه يقوم مقامه في هذه الحالة ولا يلزمه الإكمال، كما لو جاء والإمام راكع فإنه يركع معه، وتجزئه الركعة على الصحيح، ويسقط عنه واجب القراءة لما فاته القيام، هذا هو الذي عليه جمهور الأئمة من الأئمة الأربعة وغيرهم؛ لحديث أبي بكرة الثقفي : أنه جاء إلى النبي ﷺ وهو راكع فركع دون الصف ثم دخل في الصف، فقال له النبي ﷺ بعدما سلم: زادك الله حرصاً ولا تعد المعنى لا تعد إلى الركوع دون الصف، ولم يأمره بقضاء الركعة، فدل ذلك على سقوط القراءة عنه؛ لأنه فات محلها، فهكذا الذي جاء والإمام واقف قبل أن يركع ولكن لم يمكنه أن يكمل الفاتحة، فإنه يركع معه؛ لقوله ﷺ: وإذا ركع فاركعوا فهو مأمور بمتابعة إمامه، أما إذا كان ما بقي منها إلا آية أو آيتان يمكنه أن يقرأهما فليقرأهما.\nالحاصل: أنه إذا أمكنه أن يكملها كملها وإلا ركع؛ لقوله ﷺ: وإذا ركع فاركعوا ويسقط عنه ما بقي من الفاتحة؛ لأنه مأمور بالمتابعة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8835/حكم-ركوع-الامام-قبل-اتمام-المسبوق-للفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_329/32901.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10671,"question":"إذا فاتت المصلي الركعتان الأوليان من صلاة العشاء أو العصر أو الظهر، عندما يقوم لقضائها هل يصلي ركعة ثم يقرأ التشهد الأول ثم يصلي الركعة الأخرى، أم يصليهما بدون تشهد، وكذلك إذا فاتته ثلاث ركعات من الرباعية؟","title":"كيفية قضاء الركعات التي فاتته مع الإمام","answer":"الجواب: إذا فاته اثنتان من المغرب فإنه إذا قام يأتي بواحدة ثم يجلس يأتي بالتشهد الأول؛ لأن السنة في المغرب أن يجلس بعد الثنتين للتشهد الأول، فإذا قرأ واحدة ضمت إلى ما أدركه مع الإمام وصار الجميع ثنتين، فيجلس للتشهد الأول، ثم يقوم فيأتي بالثالثة منفردة يسر بها بالقراءة في المغرب، أما في العشاء فإذا فاته اثنتان فإنه يأتي بالثنتين متتابعتين؛ لأنه لا جلوس فيهما إلا في الأخيرة منهما، وهو الجلوس الأخير، كما هو معلوم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8840/كيفية-قضاء-الركعات-التي-فاتته-مع-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_329/32906.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10672,"question":"أولى قضايا هذه الحلقة قضية بعث بها المستمع مستور حامد عبدالله السواط، أخونا مستور عرضنا بعض أسئلته في حلقات مضت، وفي هذه الحلقة له جمع من الأسئلة فيسأل هذا السؤال ويقول: إذا جاء إنسان والإمام والمأمومون ما زالوا قائمين في الصلاة وكبر تكبيرة الإحرام، وعندما قرأ ثلاث آيات من سورة الفاتحة ركع الإمام، فهل يركع أم يكمل السورة، علماً بأنه إذا أكملها سوف يتأخر عن الإمام والمصلين في الركوع والسجود؟","title":"حكم ركوع الإمام قبل إتمام المسبوق للفاتحة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن الواجب على المأموم متى وصل إلى الإمام وهو في الصلاة الدخول معه في الصلاة، فإذا دخل معه في الصلاة وهو قائم قرأ، ويستحب له أن يستفتح ثم يتعوذ ثم يسمي ثم يقرأ الفاتحة، فإن أمكنه إكمالها فالحمد لله، وإن لم يمكنه ركع مع إمامه ولم يكملها، وإمامه يقوم مقامه في هذه الحالة ولا يلزمه الإكمال، كما لو جاء والإمام راكع فإنه يركع معه، وتجزئه الركعة على الصحيح، ويسقط عنه واجب القراءة لما فاته القيام، هذا هو الذي عليه جمهور الأئمة من الأئمة الأربعة وغيرهم؛ لحديث أبي بكرة الثقفي : أنه جاء إلى النبي ﷺ وهو راكع فركع دون الصف ثم دخل في الصف، فقال له النبي ﷺ بعدما سلم: زادك الله حرصاً ولا تعد المعنى لا تعد إلى الركوع دون الصف، ولم يأمره بقضاء الركعة، فدل ذلك على سقوط القراءة عنه؛ لأنه فات محلها، فهكذا الذي جاء والإمام واقف قبل أن يركع ولكن لم يمكنه أن يكمل الفاتحة، فإنه يركع معه؛ لقوله ﷺ: وإذا ركع فاركعوا فهو مأمور بمتابعة إمامه، أما إذا كان ما بقي منها إلا آية أو آيتان يمكنه أن يقرأهما فليقرأهما.\nالحاصل: أنه إذا أمكنه أن يكملها كملها وإلا ركع؛ لقوله ﷺ: وإذا ركع فاركعوا ويسقط عنه ما بقي من الفاتحة؛ لأنه مأمور بالمتابعة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8835/حكم-ركوع-الامام-قبل-اتمام-المسبوق-للفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_329/32901.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10703,"question":"يقول أخونا في سؤال آخر: يوجد جماعة من المسلمين يجتمعون في بيت رجل عالم في بعض الأيام يذكرون الله تعالى، وعند أوقات الصلاة يقوم أحدهم يؤذن للصلاة في البيت ويصلون في البيت، مع أنه يوجد في القرية مسجد على مسيرة عشر دقائق بينه وبين البيت، فما حكم عملهم هذا؟","title":"حكم التخلف عن صلاة المسجد بحجة الانشغال بالذكر","answer":"الجواب: اجتماعهم في بعض الأحيان لقراءة القرآن والمذاكرة طيب، كان النبي ﷺ يذكر أصحابه ويجتمعون به ﷺ ويذكرهم ويعلمهم ويرشدهم، كان ابن مسعود  يذكر أصحابه كل خميس ويعلمهم، فلا بأس بالاجتماع في بعض الأوقات للتذكير والمدارسة، بليل أو نهار.\nأما تخلفهم عن الصلاة هذا لا يجوز يجب عليهم أن يصلوا في المساجد، وليس لأحد أن يصلي في البيت، إلا من عذر شرعي كالمرض.\nوفي الصحيحين أن النبي ﷺ أنه قال: لقد هممت أن آمر بالصلاة فتقام ثم آمر رجلاً فيؤم الناس، ثم أنطلق برجال معهم حزم من حطب إلى رجال لا يشهدون الصلاة فأحرق عليهم بيوتهم، فتوعدهم بتحريق البيوت على من تخلف عن الصلاة في جماعة، وقال أيضا عليه الصلاة والسلام: من سمع النداء فلم يأت فلا صلاة له إلا من عذر، قيل لـابن عباس: ما هو العذر؟ قال: خوف أو مرض.\nوهكذا الحديث الصحيح فيما رواه مسلم في الصحيح عن النبي ﷺ أنه قال: لما أتاه رجل أعمى وقال: يا رسول الله! ليس قائد يلائمني إلى المسجد فهل لي من رخصة أن أصلي في بيتي؟ فقال له عليه الصلاة والسلام: هل تسمع النداء بالصلاة؟ قال: نعم. قال: فأجب، وفي لفظ آخر: لا أجد لك رخصة، فهذا من ليس له قائد يلائمه ومع هذا يقال له: أجب، يعني: أجب الأذان.\nويقول عبد الله بن مسعود  فيما رواه مسلم في الصحيح: لقد رأيتنا وما يتخلف عنها إلا منافق معلوم النفاق أو مريض، فالتخلف عن الصلاة مع الجماعة منكر ومن خصال أهل النفاق.\nفالواجب على المؤمن أن يصلي الصلوات الخمس في جماعة، وأن يحافظ على ذلك وأن يحذر التخلف، فالتخلف فيه مشابهة لأهل النفاق. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/8884/حكم-التخلف-عن-صلاة-المسجد-بحجة-الانشغال-بالذكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_342/34207.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10787,"question":"نضع هذا الموضوع جانباً الآن وننتقل إلى رسالة أخرى من رسائل الإخوة المستمعين هو المستمع (ف. ل. ر) من المنطقة الوسطى في المملكة، أخونا عرضنا بعض أسئلة له في حلقة مضت وفي هذه الحلقة يسأل ويقول: إذا فاتتني صلاة الجماعة وأنا رجل بالغ فأردت أن أصلي فأتى أولاد في سن العاشرة والثانية عشرة والثالث عشرة والرابع عشرة والخامس عشرة، أي: من عشر إلى خمس عشرة سنة، فهل أتقدمهم أم يكون الجميع في صف واحد معي على اليمين، فقد قال أحد الرجال: إنه لا يتقدم إذا كان كل من معك في هذا العمر أو أقل؛ لأنهم لا يضبطون صلاتهم، أفتوني جزاكم الله خيراً؟","title":"موضع المأمومون من الإمام إذا كانوا لم يبلغوا الحلم","answer":"الجواب: إذا كان الواقع ما ذكره السائل فإنه يتقدم بهم، ويصلي بهم ويكونون خلفه صفاً أو أكثر، إذا كانوا أبناء سبع فأكثر، من سبع فأكثر، لقوله ﷺ: مروا أبناءكم بالصلاة لسبع فابن السبع مأمور بالصلاة ومميز، فإذا كانوا أبناء سبع فأكثر وهم اثنان فأكثر فإنهم يصفون خلف الإمام، وقد صلى النبي ﷺ بـأنس واليتيم فصارا خلفه عليه الصلاة والسلام.\nأما إذا كان الصبي واحداً فقط فإنه يصلي عن يمين الإمام، كالرجل الكبير يصلي عن يمينه، كما صلى ابن عباس عن يمين الإمام.. عن يمين النبي ﷺ في صلاة الليل، وكما صلى أنس عن يمينه لما زار ﷺ جدة أنس ، فالمقصود أنه إذا كان واحداً ولو كبيراً يكون عن يمين الإمام، أما إذا كان المأمومون اثنين فأكثر ولو لم يبلغوا الحلم فإنهم يصفون خلف الإمام إذا كانوا من أهل الصلاة، وهم أبناء سبع فأكثر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8967/موضع-المامومون-من-الامام-اذا-كانوا-لم-يبلغوا-الحلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_351/35104.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10845,"question":"نعود مع مطلع هذه الحلقة إلى رسالة المستمع (م. ع. ق) من مكة المكرمة، أخونا عرضنا سؤالًا له في حلقة مضت، وفي هذه الحلقة يسأل ويقول: صليت الظهر يومًا فشككت في الصلاة هل هي ثلاث أم أربع، ثم إني لم أصل الرابعة التي شككت فيها، وفي اليوم الثاني أعدت الصلاة كاملة، ما حكم ما فعلت؟","title":"حكم الشك في عدد ركعات الصلاة","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالذي فعلت هو الصواب؛ لأن الواجب عليك لما شككت أن تجعلها ثلاثًا، وأن تأتي برابعة، ثم تسجد للسهو قبل أن تسلم، هكذا أمر النبي ﷺ، قال -عليه الصلاة والسلام-: إذا صلى أحدكم وشك في صلاته فلم يدر كم صلى ثلاثًا، أم أربعًا فليطرح الشك وليبن على ما استيقن، ثم ليسجد سجدتين قبل أن يسلم، فإن كان صلى خمسًا شفعن له صلاته، وإن كان صلى تمامًا كانتا ترغيمًا للشيطان. فالمقصود: أن المؤمن إذا شك هل صل ثنتين، أو ثلاثًا يجعلها ثنتين، وإذا شك هل صلى ثلاثًا أم أربعًا؟ يعني: في الرباعية يجعلها ثلاثًا، وإذا كان في المغرب فشك هل صلى ثنتين أو ثلاثًا، يجعلها ثنتين، ويأتي بالثالثة، وإذا كان في الفجر، أو في الجمعة، وشك هل صلى واحدة، أو ثنتين يجعلها واحدة، ثم يكمل، ثم بعد النهاية يسجد سجدتين قبل أن يسلم، هذا هو الواجب على المؤمن إذا كان منفردًا أو إمامًا، فإذا لم يفعل واقتصر على الثلاث المشكوك فيها فإن صلاته تكون باطلة، وعليه أن يعيد ذلك، أما إن كان مأمومًا فإنه يتبع إمامه، المأموم يتبع إمامه، وليس له حكم الانفراد، بل يتبع إمامه، إذا شك يتابع إمامه. ولا ينبغي للمؤمن أن يتساهل في هذه الأمور، بل ينبغي له أن يعمل بالحق بالسنة، فإذا شك هل صلى ثنتين أو ثلاثًا يجعلها ثنتين وكمل، شك هل صلى ثلاثًا في الظهر، أو العصر، أو العشاء، أم صلى أربعًا يجعلها ثلاثًا ويكمل، ثم بعد ذلك في النهاية إذا كان إمامًا أو منفردًا يسجد للسهو، وهكذا لو شك هل سجد سجدة، أو سجدتين يجعلها سجدة، ويأتي بالسجدة الثانية، أو شك وهو واقف هل ركع أو ما ركع يركع، يعني: يبني على اليقين أنه ما ركع ويركع، ثم يسجد للسهو بعد النهاية إذا فرغ من صلاته، وانتهى من التحيات والدعاء، يسجد سجدتين للسهو قبل أن يسلم، نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ تسمحوا لي بإعادة السؤال؟ الشيخ: نعم. المقدم: يقول: صليت الظهر يومًا فشككت في الصلاة هل هي ثلاث أم أربع، ولم أصل الرابعة التي شككت فيها، وفي اليوم الثاني صليتها كلها بعد صلاة العصر، فما حكم ما فعلت؟ الشيخ: مثلما تقدم، إن كان شكه بعد الصلاة فليس عليه إعادة، إذا كان شك في ثلاث، أو أربع بعدما صلى هو صلى أربعًا على نيته أنها أربع... طرأ عليه الشك بعد الصلاة، وبعد السلام هذا فلا عمل عليه، الشك بعد الصلاة لا عمل عليه، والأصل: أنه صلاها أربعًا والحمد لله. أما إذا كان شكه في أثنائها هل صلى ثلاثًا أم أربعًا، تساهل واقتصر على الثلاث، ولم يكمل، ثم تنبه بعد ذلك، وقضاها بعد صلاة العصر، أو الظهر، أو الضحى فقضاؤه صحيح، وهذا الواجب عليه إن يقضيها؛ لأنه ما صلى صلاة تامة، سلم منها وهو شاك، فهذا عليه أن يقضي إذا كان لم يتمم في الحال لما تنبه ما تمم، أو كان الشك بعد الصلاة فلا عمل عليه، الشكوك بعد الفراغ من العبادة لا عمل عليها. فلو صلى على أنها تامة، ثم بعد هذا وقع عنده شكوك فليس عليه عمل، إنما العمل إذا كان الشك في داخلها، شك هل صلى ثلاثًا أم أربعًا قبل أن يسلم؟ فالواجب عليه أنه يجعلها ثلاثًا، ويكمل، يأتي برابعة، هذا في الظهر والعصر والعشاء، وفي المغرب شك ثنتين أو ثلاثًا، إذا شك هل صلى ثنتين أو ثلاثًا؟ يجعلها ثنتين، ثم يأتي بالثالثة، يكمل المغرب. وهكذا في الفجر والجمعة إذا شك هل صلى ثنتين، أو صلى واحدة؟ يجعلها واحدة، هذا المتيقن، ثم يأتي بالثانية ويكمل ويسجد للسهو قبل أن يسلم، فلو أنه ترك العمل بهذا ما بنى على اليقين تساهل واقتصر على الثالثة وسلم، أو الثنتين وسلم في المغرب، هذا يكون أخطأ وخالف السنة، فإن تنبه في الحال قام وأتى بركعة، فإن كان ما تنبه إلا بعد ما طال الفصل يقضيها كلها كما فعل، كما فعل هذا السائل. المقدم: إذًا أخونا حينما قضاها كاملة في اليوم الثاني لا حرج عليه؟ الشيخ: نعم؛ لأنه طال الفصل، حصل عليه. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9020/حكم-الشك-في-عدد-ركعات-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_356/35601.mp3","categories":["سجود السهو"]},{"id":10859,"question":"رسالة وصلت إلى البرنامج من المستمع صادف بن يؤيا هكذا كتبه اسمه من جيبوتي، بعث برسالة ضمنها مجموعة من الأسئلة، من بينها سؤال يقول: كنا نصلي في مسجد، فإذا بإمامه يأمر الناس بفعل ما حرم الله في كتابه، أو على لسان رسوله ﷺ فمثلًا في خطبة الجمعة أمرنا بأن نتبرك بقبور الصالحين، سواء كانوا أمواتًا، أم أحياء كما أمرنا في حالة السؤال أن نقول: بجاه فلان، هل يجوز أن نصلي خلف هذا الإمام، أم لا؟ ورسالتك جاءت في آخر البرنامج يا أخ صادف نرجو لك التوفيق.","title":"حكم الصلاة خلف إمام يحث على التبرك بالصالحين","answer":"الجواب:  لا يجوز الصلاة خلف هذا الذي يأمر بالتبرك بالصالحين بقبورهم، هذا جاهل بالحكم الشرعي، وجاهل بالتوحيد، أما كلمة (بجاه) هذه كلمة بدعة، لا تكون كفرًا، بدعة بجاه فلان، أو بحق فلان، لا تجوز لأن الرسول ﷺ لم يفعل ذلك، ولا أصحابه، وليس من التوسل الشرعي، بل الواجب ترك ذلك، فلا يجوز للمسلم أن يقول في دعائه بجاه محمد، أو بجاه فلان، أو بجاه الأولياء، أو بحق الأنبياء؛ لأن هذا لم يشرع، ولم يرد في أدعية النبي ﷺ ولا أدعية الصحابة -رضي الله عنهم وأرضاهم- أما كونه يأمر بالتبرك بقبور الصالحين، فهذا كلام مجمل، التبرك بقبور الصالحين يقتضي أنه يسألهم، أو يتبرك بترابهم، أو يتبرك بسؤالهم، أو الاستغاثة بهم، أو طلب ... هذا كلام شديد خطي، مثل هذا يدل على جهله، فينبغي أن يعزل، ولا يكون إمامًا، ينبغي أن يسعى لدى المسؤولين في إبدالهم بغيره، ولا يصلى خلفه إلا إذا علم وبين له الحق، وتاب من ذلك، فلا حرج -إن شاء الله- إذا استقام وتاب، فالتوبة تجب ما قبلها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9046/حكم-الصلاة-خلف-امام-يحث-على-التبرك-بالصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_357/35714.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10862,"question":"المستمع عوض الله الطيب سوداني الجنسية، مقيم في ليبيا يقول: عملي يتطلب وجودي به طول الوقت، والمسجد بعيد منه ...الشيخ: أعد أعد.السؤال مرة أخرى: يقول: عملي يتطلب وجودي به طوال الوقت، والمسجد بعيد منه بحيث لا أسمع الأذان، فما رأي الدين في صلاتي وحدي؟","title":"حكم صلاة الجماعة على من لم يسمع النداء","answer":"الجواب: إذا كنت لا تسمع الأذان مع هدوء الأصوات، ومع كون الوقت ليس فيه ما يمنع سماع الصوت؛ فإنك لا يلزمك الحضور، أما إذا كان عدم سماع الأذان من أجل وجود أصوات، أو رياح تمنع الصوت عن جهتك، أو ما أشبه ذلك، وإلا لو كانت الأصوات هادئة، والجو هادئ لسمعت فإنه يلزمك؛ لأن الرسول -عليه الصلاة والسلام- قال: من سمع النداء فلم يأت فلا صلاة له إلا من عذر، وإذا اجتهدت في ذلك، وتحريت الصلاة مع المسلمين، ولو كنت بعيدًا فهو خير لك، وأفضل لك، وأبعد لك عن الشبهة مع الأجر العظيم في أداء الصلاة في الجماعة، لكن لا يلزمك إلا إذا كنت تسمع النداء في الوقت الذي يسمع فيه النداء، ليس هناك موانع تمنع من صوت المؤذن. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9042/حكم-صلاة-الجماعة-على-من-لم-يسمع-النداء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_357/35710.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10878,"question":"إذا دخل المصلي المسجد لصلاة الفجر، ووجد الإمام في السجود بعد الركعة الثانية، فدخل معه، وقضى ما عليه بعد سلام الإمام، ولما انتهى من صلاته وجد جماعة أخرى، فهل يدخل معهم، وتكون الركعتان اللتان صلاهما سنة، أم لا يجوز؟ جزاكم الله خيرًا.","title":"حكم إعادة الفريضة جماعة بعد صلاتها منفرداً","answer":"الجواب:  صلاته أجزأته فريضته الحمد لله، وإذا صلى مع الناس الحاضرين صارت له نافلة، كما في حديث أبي ذر يقول ﷺ: إنه يكون عليكم أمراء يؤخرون الصلاة عن أوقاتها، فصل الصلاة لوقتها، فإن أدركتها معهم فصل فإنها لك نافلة، ولا تقل صليت فلا أصلي، فهي تكون نافلة مع الآخرين. وهكذا لما صلى في منى -عليه الصلاة والسلام- يوم حجة الوداع وسلم رأى رجلين لم يصليا معه، فدعا بهما، فجيء بهما إليه، فقال: ما منعكما أن تصليا معنا؟ قالا: قد صلينا في رحالنا -يعني: في مخيمنا- فقال: لا تفعلا، إذا صليتما في رحالكما، ثم أدركتما الإمام، ولم يصل فصليا معه، فإنها لكما نافلة فالمؤمن إذا صلى في مسجد من المساجد، أو في محل آخر، ثم أدرك جماعة يصلون، فصلى معهم كانت له نافلة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9056/حكم-اعادة-الفريضة-جماعة-بعد-صلاتها-منفردا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_359/35902.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10885,"question":"إذا دخل المصلي المسجد لصلاة الفجر، ووجد الإمام في السجود بعد الركعة الثانية، فدخل معه، وقضى ما عليه بعد سلام الإمام، ولما انتهى من صلاته وجد جماعة أخرى، فهل يدخل معهم، وتكون الركعتان اللتان صلاهما سنة، أم لا يجوز؟ جزاكم الله خيرًا.","title":"حكم إعادة الفريضة جماعة بعد صلاتها منفرداً","answer":"الجواب:  صلاته أجزأته فريضته الحمد لله، وإذا صلى مع الناس الحاضرين صارت له نافلة، كما في حديث أبي ذر يقول ﷺ: إنه يكون عليكم أمراء يؤخرون الصلاة عن أوقاتها، فصل الصلاة لوقتها، فإن أدركتها معهم فصل فإنها لك نافلة، ولا تقل صليت فلا أصلي، فهي تكون نافلة مع الآخرين. وهكذا لما صلى في منى -عليه الصلاة والسلام- يوم حجة الوداع وسلم رأى رجلين لم يصليا معه، فدعا بهما، فجيء بهما إليه، فقال: ما منعكما أن تصليا معنا؟ قالا: قد صلينا في رحالنا -يعني: في مخيمنا- فقال: لا تفعلا، إذا صليتما في رحالكما، ثم أدركتما الإمام، ولم يصل فصليا معه، فإنها لكما نافلة فالمؤمن إذا صلى في مسجد من المساجد، أو في محل آخر، ثم أدرك جماعة يصلون، فصلى معهم كانت له نافلة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9056/حكم-اعادة-الفريضة-جماعة-بعد-صلاتها-منفردا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_359/35902.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10887,"question":"تقول في سؤال آخر إذا أخطأ الإمام في قراءته، ولم يرد عليه أحد من الرجال، فهل يجوز لإحدى النساء الرد عليه؟","title":"حكم فتح المرأة على الإمام إذا نسي في القراءة","answer":"الجواب:  نعم، تنبيه تفتح عليه إن فتح عليه الرجال فالحمد لله، وإلا تفتح عليه، وصوتها ليس بعورة، إنما العورة التغنج والخضوع، هذا هو المنهي عنه، كما قال تعالى: يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32]، والخضوع: اللين والتكسر في الصوت، فيطمع الذي في قلبه مرض الشهوة. أما الصوت العادي لا بأس به، ولهذا قال: وَقُلْنَ قَوْلًا مَعْرُوفًا [الأحزاب:32]، يعني: قولًا ليس فيه فحش وعنف، وليس فيه تغنج ولا تكسر ولا خضوع، بل بين ذلك قولًا عاديًا، فتفتح عليه بكلام عادي، ليس فيه تكسر وخضوع، وليس فيه عنف وشدة، ولكن القول المعتاد، ولهذا قولًا معروفًا وقلن قولاً معروفاً يعني: قولًا معتادًا ليس فيه خضوع، وهكذا تأمر بالمعروف، تنهى عن المنكر، تدعو إلى الله، ترشد إليه ولو مع الرجال، تدعوهم إلى الله، تنكر عليهم المنكر بقول طيب، ليس فيه خضوع، وليس فيه عنف، كما تعلم أخاها وابنها وبناتها الحمد لله، تعلم الأطفال الصغار الذين دون السبع، تعلمهم، وترشدهم بالقرآن. المقصود: أنها تدعو إلى الله، وتعلم بصوت ليس فيه خضوع إذا كان المعلم ممن له شهوة، كالمراهق والرجل. المقصود: أنها لا تمتنع من قول الحق من أجل قول بعض الناس: إن صوتها عورة، لا ليس بعورة، فالصوت المجرد ليس بعورة، كان النساء يتكلمن مع النبي ﷺ ويسألنه، ومع الصحابة، ويخاطبهن، ويخاطبونه، ولم يقل: إن أصواتكن عورة، وقد حضر معهن ذات يوم جمعهن، وعلمهن، وأرشدهن، وأجاب عن أسئلتهن -عليه الصلاة والسلام- هذا أمر معروف، وإنما المنكر الخضوع الذي يسبب الفتنة بها، أو يظن بها السوء من أجله، أما القول العادي فلا بأس به. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9057/حكم-فتح-المراة-على-الامام-اذا-نسي-في-القراءة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_359/35903.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10889,"question":"السائل محمد محمود شاهين يقول: تخلف رجل عن صلاة الجماعة، أي حضر بعد سلام الإمام، فماذا يفعل؟ هل يلتحق بمن جاء متأخرًا، ويتم معه؟ أم ماذا يفعل؟","title":"حكم من دخل المسجد وقد فاتته الجماعة","answer":"الجواب:  نعم إذا فاتته الصلاة مع الجماعة إن وجد أحدًا صلى معه، وإلا صلى وحده، والحمد لله، وإن وجد جماعة -ولو واحدًا- صلوا جماعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9066/حكم-من-دخل-المسجد-وقد-فاتته-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28603.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10921,"question":"إذا كنت في صلاة وانتابني شك فبنيت على الأدنى، وبعد الفراغ من الصلاة كلمني أحد كان إلى جنبي، وقال لي: إن صلاتك زائدة، فماذا أفعل؟","title":"حكم من بنى في صلاته على الأدنى فأخبر بالزيادة فيها","answer":"الجواب:  لا يضرك؛ إذا بنيت على اليقين شككت: هل صليت ثلاثًا، أم أربعًا في الظهر مثلًا، وبنيت على اليقين، وكملت أربعًا باعتقادك، ثم لما سلمت قال لك بعض الناس: إنك زائد ما يضرك؛ لأنك عملت بالشرع، وهكذا الإمام إذا فعل ذلك واحتاط، ثم قال له بعض الناس بعد السلام: إنك زائد ما يضر، لكن الذي يعلم أن الإمام زائد ... لا يقوم معه، يجلس وينبهه يقول: سبحان الله! سبحان الله! فإن رجع فالحمد لله وإلا بقي حتى يسلم مع إمامه؛ لأن الإمام قد يعتقد أنه مصيب وأنهم مخطئون، ولا يجيبهم ويستمر ويكمل الزائدة، فهم يجلسون إذا كانوا معتقدين أنهم مصيبون يجلسون وينتظرون حتى يسلم بهم، أما من لا يعلم فإنه يتابع الإمام، الذي ما عنده بصيرة يتابع الإمام، ولو تابعه إنسان يعلم أنه زائد، ولكن يجهل الحكم يحسب أنه يلزمه يجهل الحكم الشرعي فلا يضره أيضًا ذلك.  فالحاصل أن الإنسان إذا بنى على اليقين في صلاته التي سها فيها، ثم نبه بعد ذلك أنه زاد لا يضره ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9099/حكم-من-بنى-في-صلاته-على-الادنى-فاخبر-بالزيادة-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_361/36109.mp3","categories":["سجود السهو"]},{"id":10925,"question":"إذا كنت في صلاة وانتابني شك فبنيت على الأدنى، وبعد الفراغ من الصلاة كلمني أحد كان إلى جنبي، وقال لي: إن صلاتك زائدة، فماذا أفعل؟","title":"حكم من بنى في صلاته على الأدنى فأخبر بالزيادة فيها","answer":"الجواب:  لا يضرك؛ إذا بنيت على اليقين شككت: هل صليت ثلاثًا، أم أربعًا في الظهر مثلًا، وبنيت على اليقين، وكملت أربعًا باعتقادك، ثم لما سلمت قال لك بعض الناس: إنك زائد ما يضرك؛ لأنك عملت بالشرع، وهكذا الإمام إذا فعل ذلك واحتاط، ثم قال له بعض الناس بعد السلام: إنك زائد ما يضر، لكن الذي يعلم أن الإمام زائد ... لا يقوم معه، يجلس وينبهه يقول: سبحان الله! سبحان الله! فإن رجع فالحمد لله وإلا بقي حتى يسلم مع إمامه؛ لأن الإمام قد يعتقد أنه مصيب وأنهم مخطئون، ولا يجيبهم ويستمر ويكمل الزائدة، فهم يجلسون إذا كانوا معتقدين أنهم مصيبون يجلسون وينتظرون حتى يسلم بهم، أما من لا يعلم فإنه يتابع الإمام، الذي ما عنده بصيرة يتابع الإمام، ولو تابعه إنسان يعلم أنه زائد، ولكن يجهل الحكم يحسب أنه يلزمه يجهل الحكم الشرعي فلا يضره أيضًا ذلك.  فالحاصل أن الإنسان إذا بنى على اليقين في صلاته التي سها فيها، ثم نبه بعد ذلك أنه زاد لا يضره ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9099/حكم-من-بنى-في-صلاته-على-الادنى-فاخبر-بالزيادة-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_361/36109.mp3","categories":["سجود السهو"]},{"id":10929,"question":"يسأل سؤال آخر ويقول: ما حكم صلاة المفترض خلف المتنفل؟","title":"هل صلاة المتنفل إماما لمفترضين جائزة؟","answer":"الجواب:  لا حرج في ذلك صلاته صحيحة، فلو أن إنسانًا متنفل، وأم الناس وهم مفترضون صحت صلاته وصلاتهم، وقد ثبت في الصحيحين: أن معاذًا  كان يصلي مع النبي ﷺ العشاء، ثم يذهب إلى قومه فيصلي بهم تلك الصلاة فهو متنفل وهم مفترضون، ولم ينكر عليه النبي ذلك -عليه الصلاة والسلام- ومثل هذا لا يخفى عليه -عليه الصلاة والسلام- كما ثبت عنه ﷺ: أنه صلى صلاة الخوف بطائفة ركعتين، ثم سلم، ثم صلى بآخرين ركعتين، فكانت الأولى فرضه، والثانية نفل له، وهي فرض للصحابة -رضي الله عنهم وأرضاهم- وبهذا يعلم أنه لا حرج في ذلك أن يكون الإمام متنفلًا والمأموم مفترضًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9112/هل-صلاة-المتنفل-اماما-لمفترضين-جاىزة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_362/36209.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10941,"question":"يقول في سؤال آخر: هل يمكن للرجل أن يصلي مع زوجته في البيت؟ وفي هذه الحالة أين تقف الزوجة؟ هل تقف عن يمينه، أو شماله، أو خلفه؟ نرجو الإفادة جزاكم الله خيرًا.","title":"مكان الزوجة مع زوجها في الصلاة مؤتمة به","answer":"الجواب:  أما الفريضة فيلزمه أن يصلي مع المسلمين في المسجد، وليس له أن يصلي في بيته، لا مع أهله، ولا مع غيرهم، يجب على المؤمن أن يصلي مع الناس في بيوت الله ؛ لقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر، قيل لـابن عباس: ما هو العذر؟ قال: مرض أو خوف؛ ولأنه -عليه الصلاة والسلام- سأله رجل أعمى قال: يا رسول الله! ليس لي قائد يلائمني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال -عليه الصلاة والسلام-: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب، فلم يرخص له أن يصلي في البيت مع أنه أعمى، وليس له قائد يلائمه. فالواجب على المسلمين من الرجال الصلاة في مساجد الله، في بيوت الله مع إخوانهم، ولا يجوز التخلف عنها، لكن لو صلى الإنسان مع امرأته نافلة كالتهجد بالليل، أو صلاة الضحى فلا بأس، وتكون خلفه، أما الرجل يكون عن يمينه الواحد، يكون عن يمينه، أما المرأة تكون خلفه، ولو أنها زوجته؛ لأن النبي ﷺ لما صلى في بيت أنس صلاة الضحى جعل أنسًا عن يمينه، وجعل المرأة خلفهم، وفي اللفظ الآخر: صلى بـأنس واليتيم وجعلهما خلفه، وجعل المرأة خلفهما وهي جدة أنس. فالمقصود أن المرأة وإن كانت زوجةً، أو أمًا، أو أختًا لا تصف مع الرجل، ولكن تكون خلفه، سواء كان إمامًا، أو مأمومًا، إن كان إمامًا، فهي خلفه، وإن كان صفوفًا صلت خلف الصفوف، هذا في النافلة. أما الفريضة فالواجب على الرجل أن يصلي مع الناس، لكن لو كان مريضًا، أو فاتته الصلاة في المسجد، وصلى في البيت، وصلت خلفه فلا بأس صلاة الفريضة؛ لأنه في هذه الحال معذور، إما لأنه مريض، أو لأنه قد فاتته الفريضة مع الرجال. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9118/مكان-الزوجة-مع-زوجها-في-الصلاة-موتمة-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_363/36302.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10949,"question":"رسالة من بريدة باعثها مستمع من هناك رمز إلى اسمه بالحروف (أ. ن. م) يقول: أفيد سماحتكم أنني وأحد الزملاء كنا راجعين من سفر مسافة قصر، فلما حان وقت صلاة المغرب، ونحن نسير طلبت من زميلي أن نؤخر صلاة المغرب ونجمعها مع صلاة العشاء، فلما وصلنا إلى الرياض سمعنا أذان العشاء، وأثناء سيرنا إلى المنزل طلب مني زميلي أن نتوقف لنصلي العشاء مع الجماعة في المسجد، ومن ثم نصلي المغرب إما في البيت أو في المسجد بعد صلاة العشاء، فرفضت ذلك وقلت: بل نصلي المغرب في المسجد أولًا، ثم نلحق بالجماعة في صلاة العشاء، وفعلًا صليت المغرب، ومن ثم لحقت بالجماعة بصلاة العشاء، أما هو فقد أصر على رأيه، وصلى العشاء أولًا، فلما انتهت الصلاة صلى المغرب، أينا الذي على صواب؟","title":"حكم تأدية صلاة العشاء مع الجماعة قبل أداء المغرب","answer":"الجواب:  الصواب معك؛ لأن الله أوجب الترتيب، فالواجب أن يبدأ بالمغرب، ثم بعد ذلك يدخل معهم في صلاة العشاء، فقد أصبت وهو عليه القضاء، عليه أن يعيد العشاء؛ فإنه صلاها قبل المغرب، والله أوجب أن تصلى العشاء بعد المغرب، فعليه أن يعيد العشاء؛ لأنه صلاها في غير وقتها، وقتها بعد المغرب، وأما أنت فقد أصبت، نسأل للجميع التوفيق، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9126/حكم-تادية-صلاة-العشاء-مع-الجماعة-قبل-اداء-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_363/36310.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":10951,"question":"يقول: أنا مقيم في المملكة، وأعمل راعيًا للإبل، وليس بجواري مدينة أو قرية، وأنا رجل مسلم أحب الصلاة، فماذا أفعل في هذا الأمر، والعمل لا يسمح لي؟ أرجو الإفادة جزاكم الله خيرًا.","title":"حكم صلاة من كان في البر بعيداً عن المساجد","answer":"الجواب: الحمد لله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، صل في مكانك مع إبلك، صل في مكانك الذي أنت فيه، ولا يلزمك أن تذهب إلى مساجد، ما عندك مساجد، ما عندك إلا الصحراء، صل في الأرض التي أنت فيها والحمد لله، ولا حرج عليك، فإذا قدمت البلد صل مع الناس في المساجد، وما دمت في البر ترعى الإبل، أو الغنم، أو البقر صل في مكانك والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9132/حكم-صلاة-من-كان-في-البر-بعيدا-عن-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_363/36316.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11013,"question":"بعد هذا ننتقل إلى المدينة المنورة عبر رسالة بعث بها المستمع: يحيى مالك، يقول: أثناء الصلاة يجيء أحد المصلين وحتى ينبه الإمام ليلحق على الركعة فإنه يقول: (إن الله مع الصابرين)، أو يحدث أصواتًا، فهل هذا جائز؟","title":"حكم قول: (إن الله مع الصابرين) حتى يتمهل الإمام فيدرك الركوع","answer":"الجواب:  لا أعرف لهذا أصلًا، بل يأتي فإن أمكنه ركع مع الإمام، وإلا قضى ما فاته، والحمد لله، ولا حاجة إلى أصوات، ولا حاجة إلى أن يقول: إن الله مع الصابرين، ليس عليه دليل، ولكن يمشي وعليه السكينة حتى يصل بالصف، فإذا أدرك الركوع فالحمد لله، وإلا سجد مع إمامه، وقضى ما فاته، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9193/حكم-قول-ان-الله-مع-الصابرين-حتى-يتمهل-الامام-فيدرك-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_366/36609.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11020,"question":"بعد هذا ننتقل إلى المدينة المنورة عبر رسالة بعث بها المستمع: يحيى مالك، يقول: أثناء الصلاة يجيء أحد المصلين وحتى ينبه الإمام ليلحق على الركعة فإنه يقول: (إن الله مع الصابرين)، أو يحدث أصواتًا، فهل هذا جائز؟","title":"حكم قول: (إن الله مع الصابرين) حتى يتمهل الإمام فيدرك الركوع","answer":"الجواب:  لا أعرف لهذا أصلًا، بل يأتي فإن أمكنه ركع مع الإمام، وإلا قضى ما فاته، والحمد لله، ولا حاجة إلى أصوات، ولا حاجة إلى أن يقول: إن الله مع الصابرين، ليس عليه دليل، ولكن يمشي وعليه السكينة حتى يصل بالصف، فإذا أدرك الركوع فالحمد لله، وإلا سجد مع إمامه، وقضى ما فاته، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9193/حكم-قول-ان-الله-مع-الصابرين-حتى-يتمهل-الامام-فيدرك-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_366/36609.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11129,"question":"يقول: هل الخطأ في بعض أركان الصلاة جهلًا يبطلها، فإن من الناس من يصلي عدد ركعات قصده أن يركع ويسجد حتى يغلب على ظنه أنه أكمل الصلاة، من غير أن يفهم أن الظهر أربع، والعصر والعشاء كذلك، فقد يواصل أربع ركعات بتشهد واحد، يوجد هذا حتى الآن في بعض البوادي، فما هو رأيكم؟","title":"حكم الزيادة أو النقص في الصلاة جهلاً","answer":"الجواب:  إذا كان عن جهل ترك التشهد الأول، أو زاد ركعة خامسة يحسب أنه يجوز، أو ناسيًا ما يضره ذلك صلاته صحيحة، لكن إذا كان ناسيًا يسجد للسهو، نعم. المقدم: جزاكم الله خيرًا، كونه يقول: إن هذا موجود في بعض البوادي لا بد لسماحة الشيخ من تعليق حول هذا؟ الشيخ: أنا ما أعلم هذا، وأستبعد أنه يوجد، أنه يجهل أن الظهر أربع والعصر أربع أستبعد، في المملكة العربية السعودية!! هذا لا ...... وإذا كان وجد فهذا صحيح، صلاته صحيحة لأنه ترك التشهد الأول مثلًا جاهلًا، أو زاد ركعة جاهلًا فصلاته صحيحة، ولكن يجب أن يتعلم، ويجب أن يعلم، إذا كنت تعلم ذلك أيها السائل! فعليك أن ترشده، وأن تعلمه إذا كان لا يعرف ولا تسكت. المقدم: جزاكم الله خيرًا، هل تنصحونه بتحديد المناطق تمامًا لعله يوجه إليهم من يرشدهم؟  الشيخ: نعم، نوصي السائل إذا كان يعلم ذلك أن يكتب لنا، أو لوزارة الشؤون الإسلامية حتى يبلغهم هذا المحل الذي فيه هذه الجهالة، هذا من التعاون على البر والتقوى، يكتب لنا، أو للدكتور عبد الله التركي وزير الشؤون الإسلامية، حتى يرسل لهم بعض الدعاة، نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9306/حكم-الزيادة-او-النقص-في-الصلاة-جهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_369/36906.mp3","categories":["سجود السهو"]},{"id":11173,"question":"هذا السائل نبيل محمد حرفوش بالرياض يقول: لقد حدث في صلاة العصر ذات يوم أن الإمام في سجود الركعة الرابعة الأخيرة أتى بسجدة واحدة ولم ينتبه أحد على أساس بأنه أتى بالسجدتين، وبعد الانتهاء من الصلاة قال أحد المصلين للإمام: ناقص سجدة، فأتى الإمام بسجدتي السهو فقط، ولم يأت بالسجدة الناقصة، السؤال يا سماحة الشيخ: هل صلاة العصر هذه ما زالت معلقة لكونها ناقصة سجدة وهي ركن من أركان الصلاة، أو تعتبر صحيحة جزاكم الله خيرًا؟","title":"هل تجزئ سجدتا السهو عن ركن في الصلاة؟","answer":"الجواب:  إذا كان الإمام تذكر أنه ترك السجدة يلزمه الإعادة، وهكذا من معه يعيدون؛ لأن سجود السهو لا يكفي عن السجدة، والواجب عليه أن يأتي بالسجدة ثم يأتي بالتشهد ثم يسلم ثم يسجد للسهو، وإن سجد قبل السلام فلا بأس، يسجد سجود السهو. وبعض أهل العلم يرى أنه يقوم ويأتي بركعة كاملة. لكن الصواب أنه يأتي بالسجدة ويكفي، يعود يأتي بسجدة، يجلس يقول: رب اغفر لي رب اغفر لي ثم يسجد، ثم بعد السجود يقرأ التشهد ثم يسلم، ويسجد للسهو بعد ذلك، وإن سجد قبل السلام للسهو فلا بأس. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9346/هل-تجزى-سجدتا-السهو-عن-ركن-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29020.mp3","categories":["الركوع والسجود","سجود السهو"]},{"id":11195,"question":"رسالة وصلت إلى البرنامج من القصيم باعثها مستمع رمز إلى اسمه بالحروف (أ.م) يقول: بعض أئمة المساجد يحصل منهم بعض الأخطاء، بمعنى: يقوم للركعة الثالثة قبل الجلوس للتشهد الأول، ولدى قيامه يتذكر ويجلس قبل تنبيه المأمومين له، وفي هذه الحالة لا يسجد للسهو، فهل يلزمه السجود للسهو أم لا؟","title":"حكم سجود السهو لمن نسي التشهد الأول ثم رجع","answer":"الجواب:  نعم إذا قام ناسيًا ثم تنبه وجلس يسجد للسهو، ويسجد الناس معه، وإذا ترك هذا جاهلًا فلا شيء عليه، صلاته صحيحة إن شاء الله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9366/حكم-سجود-السهو-لمن-نسي-التشهد-الاول-ثم-رجع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37211.mp3","categories":["سجود السهو"]},{"id":11236,"question":"هذا السائل الذي رمز لاسمه بـ (أ. أ. أ) المنطقة الشرقية، يقول: هل يشترط في الإمامة نية الإمامة في الصلاة؟","title":"هل يشترط النية في الإمامة، وحكم الائتمام بالمسبوق","answer":"الجواب:  نعم لابد من نية الإمامة. المقدم: نعم. وإذا دخل رجل فوجد رجلًا يصلي فهل يأتم به، وهل يشرع الائتمام بالمسبوق؟ الشيخ: لا حرج في ذلك، لا حرج في ذلك وإن صلى وحده فلا بأس، وإن ائتم بالمسبوق وجعله إمامًا له ليحصل فضل الجماعة فهذا حسن. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9407/هل-يشترط-النية-في-الامامة-وحكم-الاىتمام-بالمسبوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29117.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11258,"question":"بعد هذا رسالة وصلت إلى البرنامج من اليمن، وباعثها مستمع يقول: المرسل علي محمد يقول: كان لدي ضيوف فحان وقت صلاة العشاء، فقلت لهم: حان وقت الصلاة في المسجد فلم يستجيبوا إلي، فكررتها عليهم عدة مرات، لكنهم صلوا في البيت، فهل قمت بواجبي نحو أمرهم بالمعروف؟","title":"المسافر المقيم أكثر من 4 أيام يلزمه الصلاة في المسجد","answer":"الجواب: نعم، لكن إذا كانوا مسافرين فلهم أن يصلوا في البيت قصرًا، إذا كانوا مسافرين مروا بك مسافرين ليسوا مقيمين في البلد مدة تزيد على أربعة أيام، بل عزمهم السفر، إنما مروا ضيوفًا وهم اثنان فأكثر فلهم أن يصلوا قصرًا في البيت، وإن صلوا مع الناس صلوا أربعًا.  أما إذا كانوا ضيوفًا من أهل البلد، أو عزمهم الإقامة أكثر من أربعة أيام فعليهم الصلاة في المسجد مع الناس، والواجب عليهم السمع والطاعة وألا يخالفوك، بل يجب عليهم أن يخرجوا إلى المسجد ويصلوا مع الناس، وإذا أبوا فقد أديت ما عليك، وعليك أن تصلي مع الناس ثم ترجع إليهم، تخرج وتصلي مع الجماعة ثم ترجع، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9434/المسافر-المقيم-اكثر-من-4-ايام-يلزمه-الصلاة-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37407.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11278,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: (حسن . م) من السودان، يسأل ويقول: رجل صلى العصر بمنزله وذهب إلى السوق فوجد الناس يصلون العصر في الجامع، هل يصلي معهم مرة أخرى أم تكفي الأولى، أفيدونا جزاكم الله خيرًا.","title":"حكم إعادة الفريضة في المسجد جماعة لمن صلاها في بيته","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد فإن الواجب عليه أن يصلي مع الجماعة، وليس له أن يصلي في بيته، بل يجب أن يصلي مع الجماعة ويحذر صفات المنافقين، وقد قال النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر قيل لابن عباس : ما هو العذر؟ قال: خوف أو مرض، وجاءه ﷺ رجل أعمى فقال: يا رسول الله! ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له عليه الصلاة والسلام: هل تسمع النداء بالصلاة؟ قال: نعم. قال فأجب. هذا رجل أعمى ليس له قائد ومع هذا قال له النبي ﷺ أجب فكيف بغيره؟ ومن صلى في بيته ثم جاء مسجدًا يصلون شرع له أن يصلي معهم، وإلا صلاته مجزئة مع الإثم، مع كونه آثمًا حين ترك الجماعة بدون عذر، لكن إذا صلى معهم تكون نافلة كما أمر النبي بهذا عليه الصلاة والسلام، أمر من صلى الصلاة ثم حضر صلاة أخرى أن يصلي معهم فهي نافلة فإنها نافلة تكون له نافلة.  المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9450/حكم-اعادة-الفريضة-في-المسجد-جماعة-لمن-صلاها-في-بيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37501.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11280,"question":"يقول: أنا أحفظ القرآن وأصلي كثيرًا خلف أئمة يخطؤون في القراءة كثيرًا، وأخاف أن أرد عليهم إذا لم يفتح عليهم أحد، فأريد من سماحتكم أن تبينوا لي الطريقة الصحيحة في ذلك جزاكم الله خيرًا؟","title":"صفة الفتح على الإمام إن أخطأ أو نسي","answer":"الجواب:  عليك أن تفتح على من غلط، أن تفتح عليه وأنت في الصلاة، تقرأ الآية التي غلط فيها أو وقف عندها حتى يتنبه والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9461/صفة-الفتح-على-الامام-ان-اخطا-او-نسي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37512.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11284,"question":"يقول: أنا أحفظ القرآن وأصلي كثيرًا خلف أئمة يخطؤون في القراءة كثيرًا، وأخاف أن أرد عليهم إذا لم يفتح عليهم أحد، فأريد من سماحتكم أن تبينوا لي الطريقة الصحيحة في ذلك جزاكم الله خيرًا؟","title":"صفة الفتح على الإمام إن أخطأ أو نسي","answer":"الجواب:  عليك أن تفتح على من غلط، أن تفتح عليه وأنت في الصلاة، تقرأ الآية التي غلط فيها أو وقف عندها حتى يتنبه والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9461/صفة-الفتح-على-الامام-ان-اخطا-او-نسي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37512.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11290,"question":"إنسان شك في السجود هل سجد سجدة واحدة أم سجدتين هل يلزمه سجود السهو، والحال ما ذكر؟","title":"حكم الشك في عدد السجدات","answer":"الجواب:  إذا كان هذا الشك طرأ فيها بعد انتهاء الصلاة وهو يعلم على أنها تامة ثم طرأ عليه الشك هذا لا يؤثر صلاته صحيحة والحمد لله، أما إذا كان طرأ عليه الشك في السجود في أثناء السجود هل سجد واحدة أو ثنتين هذا يجعلها واحدة ويأتي بالسجود الثاني وإذا فرغ من التحيات والدعاء يسجد للسهو، أما إذا كان سلمًا على أنها تامة ثم حدث له الشك بعد ذلك فلا يلتفت إليه. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9488/حكم-الشك-في-عدد-السجدات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37620.mp3","categories":["سجود السهو"]},{"id":11332,"question":"هذه رسالة وصلت من مستمعة للبرنامج تقول: هل تجوز الصلاة في المكان الواسع، أي: أمام باب السلام في مكة، أي: خارج الحرم، علمًا بأنه يوجد أماكن واسعة داخل الحرم في صلاة الجماعة، وكذلك هل تصح الصلاة في بئر زمزم؟","title":"حكم الصلاة خارج المسجد الحرام مع وجود سعة بداخله","answer":"الجواب:  الواجب الدخول، الواجب على من يريد الجماعة الدخول إلى المسجد والصلاة مع الجماعة في المسجد، فإذا كان هناك صفوف في الخارج فلا حرج أن يصلي معهم، أما أنه يصلي وحده في الخارج لا، بل يدخل يصف مع الناس، ولو فرضنا أن هناك صفوفًا في الخارج وصفوفًا من الداخل وأمكنه الدخول فإن المشروع له والأفضل أن يدخل حتى يكمل الصفوف الأول، ولا حرج في الصلاة في زمزم على ظهر زمزم على ظهرها لا بأس. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9514/حكم-الصلاة-خارج-المسجد-الحرام-مع-وجود-سعة-بداخله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_292/29211.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11335,"question":"الفقرة الثانية يا سماحة الشيخ يقول هذا السائل: هل يأثم من صلى منفردًا في الوقت وهل يفوته أجر الجماعة؟","title":"إثم من يصلي منفردًا ويترك الجماعة","answer":"الجواب: نعم. يأثم من صلى مفردًا وهو يستطيع جماعة، ويفوته أجر الجماعة إذا صلى وهو يستطيع الجماعة يفوته أما إذا عاجز مريض معذور، أجر الجماعة حاصل، أو في السفر ما حصل له جماعة له أجر الجماعة، يقول النبي ﷺ: إن العبد إذا مرض أو سافر كتب الله له ما كان يعمله وهو صحيح مقيم خرجه البخاري في الصحيح. فالمريض الذي عجز عن الجماعة له أجر الجماعة، والمسافر الذي ليس عنده جماعة له أجر الجماعة، أما إنسان يتعمد التخلف وهو صحيح لا، ليس له أجر الجماعة بل يأثم، يجب أن يصلي في الجماعة، وإذا تخلف من غير عذر أثم. نعم.","link":"https://binbaz.org.sa/fatwas/9517/اثم-من-يصلي-منفردا-ويترك-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_292/29214.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11373,"question":"بعد هذا رسالة بعث بها المستمع محمد أمين ، الأخ محمد يقول: أعمل حارسًا في عمارة ولا أتمكن من الصلاة في المسجد سوى في يوم الجمعة وصلاة الفجر فقط، وذلك لظروف معينة، فهل يلزمني حينئذ شيء؟ وهل أكون آثمًا؟ جزاكم الله خيرًا.","title":"حكم صلاة الجماعة على من يعمل في الحراسة","answer":"الجواب:  إذا كنت حارسًا ولا يسمح لك بترك الحراسة وقت الصلاة فلا حرج عليك؛ لأنك معذور في طلب الرزق وفي حفظ المال لمن استأجرك، فكون الإنسان حارسًا على بيت أو دكان أو أشياء أخرى له العذر أن يصلي في مكانه، تسقط عنه الجماعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9573/حكم-صلاة-الجماعة-على-من-يعمل-في-الحراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37918.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11381,"question":"بعد هذا رسالة بعث بها المستمع محمد أمين ، الأخ محمد يقول: أعمل حارسًا في عمارة ولا أتمكن من الصلاة في المسجد سوى في يوم الجمعة وصلاة الفجر فقط، وذلك لظروف معينة، فهل يلزمني حينئذ شيء؟ وهل أكون آثمًا؟ جزاكم الله خيرًا.","title":"حكم صلاة الجماعة على من يعمل في الحراسة","answer":"الجواب:  إذا كنت حارسًا ولا يسمح لك بترك الحراسة وقت الصلاة فلا حرج عليك؛ لأنك معذور في طلب الرزق وفي حفظ المال لمن استأجرك، فكون الإنسان حارسًا على بيت أو دكان أو أشياء أخرى له العذر أن يصلي في مكانه، تسقط عنه الجماعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9573/حكم-صلاة-الجماعة-على-من-يعمل-في-الحراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37918.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11392,"question":"يسأل أخونا أيضًا ويقول: إذا لم يدرك المصلي مع الإمام صلاة الجماعة إلا التشهد الأخير، فهل تحسب له صلاة الجماعة؟","title":"الحال التي يدرك فيها المسبوق صلاة الجماعة","answer":"الجواب: الجماعة لا تدرك إلا بركعة، يقول النبي ﷺ: من أدرك ركعة من الصلاة فقد أدرك الصلاة لكن إذا كان معذورًا، حبسه مرض، حبسه عذر شرعي؛ فله أجر الجماعة، ولو لم يحضرها. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9560/الحال-التي-يدرك-فيها-المسبوق-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37909.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11426,"question":"ما حكم من سها في صلاته حيث جلس للتشهد الأول وهو في الركعة الثالثة، هل يقوم؟ أم يواصل؟","title":"حكم من جلس للتشهد الأول في الركعة الثالثة سهوًا","answer":"الجواب:  نعم يقوم، ويأتي بالرابعة، ويسجد للسهو، يقوم، ويأتي بالرابعة، ثم قبل السلام يسجد سجدتين للسهو. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9608/حكم-من-جلس-للتشهد-الاول-في-الركعة-الثالثة-سهوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38024.mp3","categories":["سجود السهو"]},{"id":11431,"question":"هل يجوز أن أصلي خلف إمام لا يقصر ثوبه، ولا يطلق لحيته، وكذلك تخرج زوجته وبناته كاشفات الوجوه والشعور والساقين والأيدي؟","title":"حكم الصلاة خلف من يحلق لحيته ويخرج نساؤه متبرجات","answer":"الجواب:  الصلاة صحيحة خلفه إذا كان مسلمًا، الصلاة خلفه صحيحة، لكن إذا تيسر الصلاة خلف غيره ممن هو خير منه وأفضل منه؛ فهو أولى وأكمل؛ لأن هذا عاصٍ، والصلاة خلف العاصي صحيحة في أصح قولي العلماء إذا كان مسلمًا، وينصح ويوجه؛ حتى يوفر لحيته، حتى يرفع ثيابه، على إخوانه وأحبابه أن ينصحوه ويوجهوه ويلحوا عليه حتى يستقيم، وكذلك من جهة أهل بيته ينصحونه من جهتهم، فالمسلم أخو المسلم، والله يقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ [التوبة:71]، فالواجب التناصح، والتواصي بالحق في كل شيء. والإمام الذي يؤم الناس ينبغي أن يكون قدوة في كل خير، وإذا قصر؛ فيجب على ولاة الأمور أن يختاروا خيرًا منه، وأن يبدلوه إذا لم يستجب للنصيحة، عليهم أن يلتمسوا من هو خير منه، حتى يكون قدوة في الخير، وحتى ينتفع به المسلمون المصلون خلفه، وإذا تناصح المسلمون، وتواصوا بالحق؛ كثر الخير، وقل الشر، وإذا تساكتوا؛ فبالعكس، يكثر الشر، ويقل الخير، نسأل الله السلامة، نعم.","link":"https://binbaz.org.sa/fatwas/9613/حكم-الصلاة-خلف-من-يحلق-لحيته-ويخرج-نساوه-متبرجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_294/29407.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11436,"question":"ما حكم الإسلام في الإمام الذي يطيل في الصلاة زيادة عن اللازم؟ نصحناه إلا أنه رفض النصح، وعندما نشير إلى إطالته يقول: بإمكانكم الصلاة في مساجد أخرى.","title":"حكم من يطيل الصلاة بالناس","answer":"الجواب:  هذا ينصح، يبين له ما جاءت به السنة، يعطى كتاب الصلاة لابن القيم، كذلك ما يوجد من الكتب التي تبين صفة صلاة النبي ﷺ حتى لعله يقنع، إن شاء الله. المقصود أنه ينصح ويوجه من أهل العلم من الأخيار الذين يقدرهم، ويعرف فضلهم، وعلمهم، يشار عليهم بأن ينصحوه إذا كان يطيل، وينفر الناس، أما النصيحة من العامة ما تفيده، لكن يشار على أهل العلم، ويطلب منهم أن ينصحوه إذا كان عمله منفرًا، وفيه طول كثير، حتى يستفيد -إن شاء الله- من إخوانه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9618/حكم-من-يطيل-الصلاة-بالناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_294/29412.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11443,"question":"إذا صلى الإمام ومن ثم طرأ عليه ما يبطل صلاته، كيف يعمل في هذه الحالة؟","title":"حكم الإمام الذي طرأ عليه ما يبطل صلاته","answer":"الجواب:  ينصرف، وينبه الناس، إذا طرأ عليه ريح خرجت منه، أو بول؛ يقطع الصلاة، ويقدم من يصلي بهم، يتم بقية الصلاة، يعني: يستخلف من يصلي بهم بقية الصلاة، فإن انصرف، ولم يستخلف؛ قدم ممن يرضوه بعضهم، من هو في مقدم الصف، يقدموا واحدًا منهم؛ حتى يصلي بالناس، حتى يكمل للناس، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9625/حكم-الامام-الذي-طرا-عليه-ما-يبطل-صلاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_294/29419.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11453,"question":"يقول: أمَّيت جماعة في رمضان، فهل يجوز أن آخذ منهم أجرة مقابل ذلك؟ إذ أنهم أصروا على أن آخذ تلك الأجرة، وقلت: هذا عمل أتقرب به إلى الله، لكنهم أصروا، فما هو رأي سماحتكم؟ جزاكم الله خيرًا.","title":"حكم أخذ الإمام أجرة على إمامته في رمضان","answer":"الجواب: إن أخذته؛ فلا بأس، وإن تركته؛ فلا بأس، الأمر واسع، وإن تركته؛ فهو أفضل ما دمت ما أردت شيئًا، إن تركته؛ فهو أفضل، وإن أخذته؛ فلا حرج، إن شاء الله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9634/حكم-اخذ-الامام-اجرة-على-امامته-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38108.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11473,"question":"المستمع يوسف آدم مقيم في المملكة يقول: ذات يوم أميت الناس للصلاة، وفي أثناء الصلاة تذكرت بأني لست على طهارة، ولم أدر ماذا أصنع، وارتبكت، فأكملت الصلاة بهم، وقد أعدت الصلاة بالنسبة لي، أما بالنسبة للمأمومين فلم أخبرهم بشيء، وذلك لأنني خجلت، أفتوني جزاكم الله خيرًا.","title":"حكم من أمَّ الناس وفي صلاته تذكر أنه على غير طهارة","answer":"الجواب: صلاتهم صحيحة؛ لأنهم لم يعلموا، فإذا صلى الإنسان، ثم تذكر أنه محدث، وأتم الصلاة؛ فصلاة المأمومين صحيحة، أما هو فعليه أن يعيد، والواجب عليه أن يتقي الله، وأن يقطع الصلاة، لا يكمل، إذا أحدث، أو ذكر أنه محدث؛ يقطع الصلاة، ويستخلف، يعني يقول: تقدم يا فلان، يخلي من خلفه واحدًا منهم يتقدم حتى يكمل بهم، وهذا هو الاستخلاف، يقول: تقدم يا فلان، فإن لم يستخلف؛ قدم واحد صلى بهم، كمل بهم؛ لأن عمر  لما طعن؛ قدم عبدالرحمن، وأتم بالناس الصلاة، فهذا هو الأفضل، وإن تركهم وقدموا إنسانًا، وصلى بهم؛ فلا بأس، وإن أعادوها من أولها ؛فلا بأس، الأمر واسع، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9663/حكم-من-ام-الناس-وفي-صلاته-تذكر-انه-على-غير-طهارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_382/38209.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11495,"question":"يقول أخونا: إذا شكيت في سجدة، وأنا في ذلك الشك بعد أن قمت إلى الركوع في الثانية، ومع قيامي؛ أيقنت أنني سجدت سجدة واحدة، فماذا أعمل؟ جزاكم الله خيرًا.","title":"حكم من تيقن أنه ترك سجدة بعد مضى الركعة","answer":"الجواب:  إذا تيقنت أنك تركت سجدة؛ تعود تأتي بالسجدة، إلا إذا كنت قد شرعت في القراءة؛ تستمر، وتعتبر تلك الركعة ذاهبة، يعني: ذهبت عليك، تأتي بعوض منها عند الركعة الأخرى، وتسجد للسهو، إذا كنت إمامًا، أو منفردًا، أما إن كنت مأمومًا؛ تأتي بها إذا سلم إمامك، والحمد لله. المقصود: أن هذه الركعة التي تركت سجدتها إذا انتبهت لذلك عند قيامك، أو بعد قيامك قبل أن تشرع في القراءة؛ تعود تأتي بها، سواءً كنت إمامًا، أو منفردًا، أو مأمومًا، أما إن كنت لم تعلم، ولم تشعر إلا بعد القراءة؛ تبطل الركعة التي ........ وتقوم الثانية مقامها، وتأتي بعوض منها ركعة أخرى، سواءً كنت إمامًا، أو مأمومًا، أو منفردًا، والإمام يسجد للسهو، والمنفرد يسجد للسهو، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9681/حكم-من-تيقن-انه-ترك-سجدة-بعد-مضى-الركعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_383/38314.mp3","categories":["سجود السهو"]},{"id":11543,"question":"رسالة من المستمع: (س. ص. ع) من مكة المكرمة يقول: يوجد لدينا إمام مسجد في القرية التي نسكنها، وهذا الإمام يقوم بمعالجة الناس مستخدمًا التعامل مع الجن، وأنه طبيب شعبي، ويقول هذا الإمام: إنه تاب من ذلك التعامل وبدأ ينهج نهجًا صحيحًا، .. رأيكم هل نستمر في الصلاة خلف هذا الإمام؟","title":"حكم الصلاة خلف رجل كان يستخدم الجن ثم تاب","answer":"الجواب:  هذا يحتاج إلى سؤال أهل الخبرة به من الصلحاء والأخيار والثقات، فإذا علمت توبته؛ فالحمد لله، لا مانع من بقائه في المسجد، والصلاة خلفه، أما إذا كان متهمًا بإبقائه على عمله السيئ، واستخدام الجن؛ فلا يصلى خلفه، بل يجب الإنكار عليه، ورفع أمره إلى الجهة المسؤولة إلى الهيئة، أو إلى المحكمة، حتى يمنع من هذا العمل السيئ، ويؤدب بما يستحق، لكن متى ثبتت توبته ورجوعه إلى الله، وتركه هذا العمل السيئ من طريق الثقات الأثبات، أو من طريق المحكمة؛ فلا بأس من الصلاة خلفه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9726/حكم-الصلاة-خلف-رجل-كان-يستخدم-الجن-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_295/29510.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11596,"question":"القضية الثالثة التي يسأل عنها أخونا في هذا اللقاء، يقول: ما الحكم فيمن يصلي منفردًا، ثم يأتي شخص آخر يصلي خلفه، فهل تحسب لهما صلاة الجماعة، أم لا؟ جزاكم الله خيرًا.","title":"حكم الائتمام بالمنفرد","answer":"الجواب:  الصواب: لا حرج في ذلك، لا حرج في ذلك، كونه يأتم بهذا المنفرد، لا بأس، ويحصل لهما فضل الجماعة؛ لأنه ثبت عن النبي ﷺ أنه كان يصلي وحده، فجاء ابن عباس فصف عن يساره في صلاة الليل، فأداره النبي ﷺ عن يمينه، وصلى به، والنبي ﷺ أحرم وحده، ثم جاء ابن عباس، فدخل معه، فأقره النبي ﷺ وصلى به، وجعله عن يمينه. وثبت عنه أيضًا -عليه الصلاة والسلام- أنه رأى رجلًا دخل بعد الصلاة قد فاتته الصلاة، فقال: من يتصدق على هذا فيصلي معه؟. فالمقصود: أن كون المنفرد الذي يقضي يكون إمامًا، أو جاء وقد فاتته الصلاة، فصار فكبر يصلي وحده، ثم جاء إنسان فصف عن يمينه، أو جاء جماعة، وقدموه لا حرج، الصواب: لا حرج .... ومن هذا أنه ﷺ كان يصلي وحده، فجاء جابر وجبار من الأنصار، فصفا عن يمينه وشماله، فجعلهما خلفه، وصلى بهما، وكان قد أحرم وحده -عليه الصلاة والسلام- فدل هذا على أنه إذا ... وحده، ثم جاء من صف عن يمينه؛ فلا بأس، وإن صف عن يساره، أداره عن يمينه، وإن كانوا جماعة اثنين فأكثر؛ يجعلهم خلفه، هذا هو السنة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9777/حكم-الاىتمام-بالمنفرد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_387/38703.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11598,"question":"يقول: لديهم إمام مسجد يعمل في أعمال الدجل والسحر، وفك الأعمال، فهل تجوز الصلاة خلفه؟","title":"حكم الصلاة خلف المشعوذ ومن يتعاطى السحر","answer":"الجواب:  هذا فيه تفصيل: إن كان يتعاطى أمورًا كفرية من السحر، أو دعاء الجن، والاستغاثة بهم؛ هذا كفر أكبر، لا يصلى خلفه، أما إن كانت أمور أخرى غير الشرك الأكبر؛ فالصلاة خلفه صحيحة، كما يتعاطى بعض الناس .... التمائم من القرآن يعلقها ... هذه فيها شبهة، وإن كان لا تجوز، لكن لا تمنع صحة الصلاة خلفه. وأما إذا كان يتهم بالشرك يتهم بكفر، الاستغاثة بالجن، بكتب التمائم الشركية التي فيها دعوة غير الله، فيها الشرك بالله، أو فيها التعلق بالسحرة، أو تصديق السحرة بأنهم يعلمون الغيب، أو خدمة السحرة بدعاء الجن، والاستغاثة بالجن، ونحو ذلك. فالمقصود: إذا كان يتعاطى السحر، أو الاستغاثة بالجن، ونحو ذلك، هذا يكون من الكفر الأكبر، نسأل الله العافية. المقدم: نسأل الله السلامة والعافية، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9783/حكم-الصلاة-خلف-المشعوذ-ومن-يتعاطى-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_387/38709.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11600,"question":"يقول: لديهم إمام مسجد يعمل في أعمال الدجل والسحر، وفك الأعمال، فهل تجوز الصلاة خلفه؟","title":"حكم الصلاة خلف المشعوذ ومن يتعاطى السحر","answer":"الجواب:  هذا فيه تفصيل: إن كان يتعاطى أمورًا كفرية من السحر، أو دعاء الجن، والاستغاثة بهم؛ هذا كفر أكبر، لا يصلى خلفه، أما إن كانت أمور أخرى غير الشرك الأكبر؛ فالصلاة خلفه صحيحة، كما يتعاطى بعض الناس .... التمائم من القرآن يعلقها ... هذه فيها شبهة، وإن كان لا تجوز، لكن لا تمنع صحة الصلاة خلفه. وأما إذا كان يتهم بالشرك يتهم بكفر، الاستغاثة بالجن، بكتب التمائم الشركية التي فيها دعوة غير الله، فيها الشرك بالله، أو فيها التعلق بالسحرة، أو تصديق السحرة بأنهم يعلمون الغيب، أو خدمة السحرة بدعاء الجن، والاستغاثة بالجن، ونحو ذلك. فالمقصود: إذا كان يتعاطى السحر، أو الاستغاثة بالجن، ونحو ذلك، هذا يكون من الكفر الأكبر، نسأل الله العافية. المقدم: نسأل الله السلامة والعافية، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9783/حكم-الصلاة-خلف-المشعوذ-ومن-يتعاطى-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_387/38709.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11631,"question":"إنني أكون آسفًا إذ أكثرت عليكم الأسئلة، هكذا يقول سماحة الشيخ، وحينئذٍ أسألكم لو تكرمتم إذا كنت إمامًا لمسجد، وتخلفت بعض الفروض في الشهر مرة، أو مرتين، لأعذار معينة، فهل علي من حرج؟","title":"حكم تخلف الإمام الصلاة والصلاتين في الشهر لظروف طارئة","answer":"الجواب:  ليس عليك حرج -إن شاء الله- ولكن توصيهم بأن لا يتعطلوا، أو تعين من يؤمهم، أو توصيهم بأنك إذا تأخرت عن الوقت المعتاد يقدموا من يصلي بهم حتى لا يتعطلوا ولا يتأذوا، وعليك أن تجتهد في الاستقامة والأشياء العارضة القليلة لا حرج فيها، إن شاء الله.  المقدم: الحمد لله، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9829/حكم-تخلف-الامام-الصلاة-والصلاتين-في-الشهر-لظروف-طارىة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38916.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11649,"question":"إنني أكون آسفًا إذ أكثرت عليكم الأسئلة، هكذا يقول سماحة الشيخ، وحينئذٍ أسألكم لو تكرمتم إذا كنت إمامًا لمسجد، وتخلفت بعض الفروض في الشهر مرة، أو مرتين، لأعذار معينة، فهل علي من حرج؟","title":"حكم تخلف الإمام الصلاة والصلاتين في الشهر لظروف طارئة","answer":"الجواب:  ليس عليك حرج -إن شاء الله- ولكن توصيهم بأن لا يتعطلوا، أو تعين من يؤمهم، أو توصيهم بأنك إذا تأخرت عن الوقت المعتاد يقدموا من يصلي بهم حتى لا يتعطلوا ولا يتأذوا، وعليك أن تجتهد في الاستقامة والأشياء العارضة القليلة لا حرج فيها، إن شاء الله.  المقدم: الحمد لله، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9829/حكم-تخلف-الامام-الصلاة-والصلاتين-في-الشهر-لظروف-طارىة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38916.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11678,"question":"مستمع يقول: بحكم طبيعة عملي في الصحراء، وبعدي عن المدينة، فإني أصلي دائمًا في مكان عملي طوال الأسبوع، وقراءتي للقرآن ليست بالتشكيل الصحيح المضبوط، أفيدوني وفقكم الله.","title":"حكم من يصلي في مكان عمله لبعده عن المسجد","answer":"الجواب:  ليس عليك حرج ما دمت بعيدًا عن المدن لا تسمع النداء؛ صل في مكانك، وعليك أن تجتهد في قراءة القرآن، وإقامة الحروف، ولو في المصحف، وأهم شيء الفاتحة، لا بد أن تقيمها؛ لأنها ركن في الصلاة، وما سواها مستحب، لكن عليك أن تجتهد حتى تقيم الفاتحة، وتقرأها على من هو أعرف منك، حتى تقيمها وتحفظها جيدًا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9861/حكم-من-يصلي-في-مكان-عمله-لبعده-عن-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_390/39010.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11724,"question":"رسالة بعث بها المستمع إبراهيم العبدالله الناصر يقول: إذا دخل الإنسان المسجد لأداء صلاة العشاء، ثم لاحظ في ثوبه شيئًا من البقع، قال في نفسه: أصلي العشاء قبل أن يجتمع الناس، ثم صلى وخرج، هل هذا عذر مقبول؟ جزاكم الله خيرًا.","title":"حكم من دخل المسجد فصلى قبل الناس وخرج لبقعة في ثوبه","answer":"الجواب:  لا يجوز هذا، بل يجب عليه أن يصبر، ويصلي مع الناس، ولو في ثوبه بقع، إلا إذا أمكن أن يذهب إلى الحمام الذي حول المسجد، أو بيته إن كان قريبًا، إذا أمكنه أن يذهب ويزيل البقعة؛ فلا حرج في ذلك، هذا إذا كانت البقعة غير نجسة. أما إذا كانت نجاسة؛ يلزمه أن يذهب، يلزمه أن يذهب، ويزيل النجاسة، وإلا يبدل الثوب، ولو فاتته الجماعة؛ يلزمه أن يذهب إلى بيته، وأن يزيل هذه النجاسة بالغسل، أو بإبدال الثوب، بإبدال الثوب بثوب آخر ليس فيه نجاسة، أما مجرد وسخ بقع، وسخ ليس فيها نجاسة ..... يصلي فيه، والحمد لله، ولا يضيع الجماعة، يلزمه أن يصلي مع الجماعة، وفي إمكانه بعد ذلك أن يزيل الثوب، أو يغسل الوسخ. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9907/حكم-من-دخل-المسجد-فصلى-قبل-الناس-وخرج-لبقعة-في-ثوبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_421/42105.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11739,"question":"ما حكم من صلى منفردًا خلف الصف؟","title":"صلاة المنفرد خلف الصف لا تصح","answer":"الجواب:  لا تصح صلاته، من صلى خلف الصف منفردًا لا صلاة له، يقول النبي ﷺ: لا صلاة لمنفرد خلف الصف ورأى رجل يصلي خلف الصف وحده، فأمره أن يعيد، عليه الصلاة والسلام. فالواجب على المؤمن أن يلتمس فرجة حتى يقف في الصف، فإن عجز؛ صلى مع الإمام عن يمين الإمام إذا تيسر ذلك، فإن لم يتيسر؛ انتظر حتى يأتي من يصف معه. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9917/صلاة-المنفرد-خلف-الصف-لا-تصح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_393/39303.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11741,"question":"أخيرًا يسأل أخونا ويقول: رجل صلى بالجماعة، لكنه نسي آية من سورة الفاتحة، ما حكم صلاته، وصلاة المأمومين خلفه؟","title":"حكم من نسي آية من سورة الفاتحة وهو إمام","answer":"الجواب:  حكمه أن يأتي بركعة، بدل الركعة التي ترك فيها آية من الفاتحة يأتي بركعة قبل أن يسلم، ويسجد للسهو، فإن طال الفصل يعيد هو، ويعيدون، أما إن ذكر بعد السلام في وقت قريب يأتي بركعة، ويسجد للسهو، ويسلم، وإن سجد للسهو بعد السلام؛ فهو أفضل يأتي بركعة، ثم يسلم، ثم يسجد للسهو بعد السلام، هذا هو الأفضل. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9923/حكم-من-نسي-اية-من-سورة-الفاتحة-وهو-امام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_393/39307.mp3","categories":["القراءة في الصلاة","سجود السهو"]},{"id":11751,"question":"ما الذي يجب علينا عمله بالضبط عندما نقابل سجدة في القرآن الكريم؟","title":"حكم سجود التلاوة وما يقال فيه من أدعية","answer":"الجواب:  السنة السجود إذا مررت على السجدة في القرآن، تكبر وتسجد، وتقول: (سبحان ربي الأعلى سبحان ربي الأعلى) مثل سجود الصلاة سواء، تقول فيها مثل السجود في الصلاة (سبحان ربي الأعلى، سبحان ربي الأعلى) تدعو فيها وإذا قلت: (اللهم لك سجدت، وبك آمنت، ولك أسلمت، سجد وجهي للذي خلقه وصوره، وشق سمعه وبصره بحوله وقوته، تبارك الله أحسن الخالقين)، فهذا أيضًا سنة، يقال في سجود الصلاة، وفي سجود التلاوة. وهكذا: اللهم اكتب لي بها عندك أجرًا، وامح عني بها وزرًا، واجعلها لي عندك ذخرًا، وتقبلها مني كما تقبلتها من عبدك داود عليه السلام هذا أيضًا لا بأس، ورد في بعض الأحاديث أن النبي ﷺ دعا بذلك، قال: اللهم اكتب لي بها عندك أجرًا، وامح عني بها وزرًا، واجعلها لي عندك ذخرًا، وتقبلها مني كما تقبلتها من عبدك داود -عليه الصلاة والسلام- فهذا لا بأس به. المقصود: أنه يقول في سجوده للتلاوة مثل سجود الصلاة، يقول: (سبحان ربي الأعلى، سبحان ربي الأعلى) (سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي)، (سبوح قدوس رب الملائكة والروح)، (اللهم لك سجدت وبك آمنت ولك أسلمت، سجد وجهي للذي خلقه وصوره، وشق سمعه وبصره بحوله وقوته، تبارك الله أحسن الخالقين) ثم يرفع مكبرًا، إذا كان في الصلاة يرفع مكبرًا، أما خارج الصلاة؛ فيكفي التكبير الأول، وليس فيها تكبير ثانٍ، ولا سلام في خارج الصلاة، أما في الصلاة فيكبر عند السجود، ويكبر عند الرفع، كما فعله النبي -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9933/حكم-سجود-التلاوة-وما-يقال-فيه-من-ادعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_393/39314.mp3","categories":["سجود التلاوة والشكر","سجود السهو","الأدعية والأذكار"]},{"id":11752,"question":"متى يجب سجود السهو، وكيف يكون؟","title":"موجبات سجود السهو وصفته","answer":"الجواب:  سجود السهو إذا ترك واجبًا، أو فعل محرمًا سهوًا؛ وجب السجود، أما إذا ترك مستحبًا؛ فلا يلزمه السجود، لو نسي الاستفتاح، أو نسي الدعاء في السجود، أو شبه ذلك، أو نسي رفع اليدين؛ فلا يلزمه السجود، إنما السجود إذا ترك واجبًا سهوًا، من ترك التشهد الأول، وقام، أو نسي سجدة، ثم أتى بالركعة التي تليها وكمل الصلاة، وزاد ركعة. المقصود: إذا ترك واجبًا سهوًا؛ وجب عليه السجود، مثل ترك سبحان ربي الأعلى في السجود، سبحان ربي العظيم في الركوع، ربنا ولك الحمد عند الرفع من الركوع، التكبيرات عند السجو،د والرفع منه، كل هذا إذا نسيه؛ سجد له في آخر الصلاة قبل أن يسلم أفضل، وهكذا لو ترك التشهد الأول. أما إذا ترك ركنًا مثل سجود الصلاة، أو مثل الركوع، ولم يذكره إلا بعد ذلك؛ قامت الركعة التي بعدها مقام الركعة التي تركه منها، وضاعت عليه الركعة التي ترك سجودها، وركوعها، وقامت الركعة التي بعدها مقامها، ثم يأتي بركعة زائدة، ثم إذا كملها؛ سجد للسهو، ثم سلم، وهذا واجب أيضًا؛ لأن الإنسان قد ينسى الركوع، أو ينسى السجود، ولا ينبه، ثم يتنبه، أو ينبه بعد ذلك، فيأتي بركعة كاملة بدلًا من الركعة التي ترك سجودها، أو ركوعها. أما إن نبه في الحال أنه لم يركع وهو هاوٍ للسجود؛ يعود، يقف ثم يركع، أو نبه أنه لم يسجد الثانية؛ يسجد في الحال، إذا نهض ونبه؛ يجلس ويقول: رب اغفر لي، رب اغفر لي، ثم يسجد السجدة الثانية، ويسجد للسهو في آخر الصلاة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9934/موجبات-سجود-السهو-وصفته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_393/39315.mp3","categories":["سجود السهو"]},{"id":11753,"question":"من شك في تأدية عمل من أعمال الصلاة هل أداه أو لم يؤده، هل يشرع له سجود السهو سماحة الشيخ؟","title":"حكم من شك في الصلاة","answer":"الجواب:  يبني على اليقين أولًا، إذا شك هل صلى ثنتين أو ثلاثًا؛ يجعلها ثنتين، إذا شك هل سجد الثانية؛ يسجد، إذا شك هل ركع، أو ما ركع؛ يركع، ثم يسجد للسهو بعده في آخر الصلاة. المقدم: إذاً يشرع سجود السهو حتى للشك. الشيخ: يجب السجود. المقدم: يجب؟ الشيخ: إيه، يجب أولًا إذا شك يعمل باليقين، ثم يسجد للسهو في آخر الصلاة. المقدم: بارك الله فيكم، وأحسن إليكم، وجزاكم خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9935/حكم-من-شك-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_393/39316.mp3","categories":["سجود السهو"]},{"id":11754,"question":"يسأل أخونا ويقول: ماذا يجب على الفرد إذا كان في صلاة جماعة، وأطال السجود، وقام الإمام، ونزل للأخرى وهو ما زال في سجدته؟","title":"التفصيل في تأخر المأموم لمتابعة إمامه","answer":"الجواب:  هذا لا يجوز، إذا تعمد ذلك؛ بطلت صلاته، أما إذا كان ينعس، أو ما سمع صوت الإمام، يقوم ويتبع الإمام، ولا يضره، أما إذا تعمد حتى فاته القيام؛ بطلت صلاته، نسأل الله العافية، لكن إذا كان ما سمع صوت الإمام، أو ينعس؛ فهذا يتابع الإمام، وصلاته صحيحة. المقدم: الذين لا يتابعون الإمام بدقة كافية سماحة الشيخ فهم يتأخرون عنه، أو قد يسبقونه، أو قد يوافقونه. الشيخ: الواجب متابعته، لا يسبقونه، ولا يوافقونه، الواجب بعده، مثلما قال ﷺ: إنما جعل الإمام ليؤتم به، فلا تختلفوا عليه، فإذا كبر؛ فكبروا، ولا تكبروا حتى يكبر، وإذا ركع فاركعوا، ولا تركعوا حتى يركع .. الحديث. فالواجب عليهم أن يكونوا بعده، لكن متصلين لا يتأخرون، لا يسابقونه، ولا يوافقونه، بل يكون بعده متصلًا به، هذا هو المشروع، وهذا هو الواجب. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9936/التفصيل-في-تاخر-الماموم-لمتابعة-امامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_393/39317.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11757,"question":"في حال سهو الإمام، وقيامه للركعة الخامسة، ماذا نقول؟ هل نقول: الحمد لله، أم سبحان الله؟ نرجو أن توجهونا حول هذا الموضوع جزاكم الله خيرًا.","title":"ما يقال للإمام إذا سها في الصلاة","answer":"الجواب:  السُّنة أن يقول المأموم عند سهو الإمام: سبحان الله، سبحان الله، حتى ينتبه الإمام، وإذا كان هناك حاجة إلى آية يتلوها، كأن يقول -إذا لم يسجد-: وَاسْجُدْ وَاقْتَرِبْ [العلق:19]، أو الركوع ينبهه يقول: يَا أَيُّهَا الَّذِينَ آمَنُوا ارْكَعُوا [الحج:77] فلا بأس. المقصود: أن الأصل التسبيح، سبحان الله، سبحان الله، وإذا تلا آية من الآيات ترشد الإمام؛ فلا بأس. المقدم: بارك الله فيكم، ... الآيات إذا قال: اركعوا، أو اسجدوا جائز هذا؟ الشيخ: وَاسْجُدْ وَاقْتَرِبْ [العلق:19] ينبه السجود، أو قوله سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا ارْكَعُوا وَاسْجُدُوا وَاعْبُدُوا رَبَّكُمُ وَافْعَلُوا الْخَيْرَ... [الحج:77] إلى آخره. نعم. المقدم: بمعنى أن يتلفّظ بآية من القرآن الكريم تتفق وحال الإمام... الشيخ: مثلًا انحط للسجود قبل أن يركع؛ فنبِّهه على الركوع تقول: اركعوا يَا أَيُّهَا الَّذِينَ آمَنُوا ارْكَعُوا وَاسْجُدُوا [الحج:77]. نعم. المقدم: طيب جزاكم الله خيرًا. الشيخ: والأصل هو التسبيح، إذا حصل به المطلوب الحمد لله، سبحان الله، سبحان الله، نعم. المقدم: جزاكم الله خيرًا، طيب.","link":"https://binbaz.org.sa/fatwas/9941/ما-يقال-للامام-اذا-سها-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_394/39403.mp3","categories":["سجود السهو"]},{"id":11791,"question":"بعد هذا ننتقل إلى جيزان، قرية ذربة عبر رسالة بعث بها مستمع من هناك، رمز إلى اسمه بالحروف (ع. ب. هـ) أخونا بدأ رسالته كالتالي: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على نبينا محمد، وعلى آله وصحبه وسلم، أبعث برسالتي هذه إلى سماحة الشيخ: عبدالعزيز بن عبدالله بن باز -حفظه الله- أما بعد: فإني أحبك في الله، وأسأل الله أن يحشرني وإياك ومن أحب في جنة النعيم، إنه على كل شيء قدير، سماحة الوالد ما هي الصفات التي يجب أن تتوفر فيمن أراد أن يصير إمامًا في مسجد يؤم المصلين؟ جزاكم الله خيرًا.","title":"صفات من يتولى إمامة المصلين","answer":"الجواب:  أولًا نقول: أحبك الله الذي أحببتنا له، فقد صح عن رسول الله ﷺ أنه قال: يقول الله : وجبت محبتي للمتحابين في، والمتزاورين في، والمتجالسين في، والمتباذلين في وثبت أيضًا عنه ﷺ أنه قال: يقول الله يوم القيامة: أين المتحابون بجلالي؟ اليوم أظلهم في ظلي، يوم لا ظل إلا ظلي نسأل الله أن يجعلنا وإخواننا المتحابين في الله من هؤلاء. أما الصفات التي ينبغي أن تكون في الإمام مثلما بين النبي ﷺ: يؤم القوم أقرؤهم لكتاب الله، فإن كانوا في القراءة سواء؛ فأعلمهم بالسنة، فإن كانوا في السنة سواء؛ فأقدمهم هجرة، فإن كانوا في الهجرة سواء؛ فأكبرهم سنًا وفي لفظ: فأقدمهم إسلامًا. فعليك -يا أخي- أن تجتهد في الإكثار من القرآن، والعناية به، وحفظ ما تيسر منه، والتفقه في الدين والتعلم؛ حتى تعرف أحكام صلاتك، وأحكام سجود السهو، ونحو ذلك مما يعرض للإمام، مع تقوى الله والاستقامة على دينه، والحذر من معصيته . فإذا اجتهدت في ذلك؛ فأنت صالح للإمامة، وأهم شيء العناية بالتفقه في الدين، والعناية بالقرآن الكريم، وحفظ ما تيسر منه، مع الاستقامة على طاعة الله، والحذر من معاصيه  نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9975/صفات-من-يتولى-امامة-المصلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_422/42208.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11797,"question":"المستمع بخيت بن مبارك الدوسري بمدينة الجبيل بعث برسالة يقول فيها: أولًا نحن في الأمن الصناعي دوامنا ورديات، وبالطبع تمر علينا الصلوات وأحيانًا.الشيخ: أعد أعد.المقدم: نحن في الأمن الصناعي دوامنا ورديات، وبالطبع تمر علينا الصلوات، وأحيانًا نضطر ليصلي كل واحد منا بمفرده، سؤالنا: هل تحسب لنا صلاة الجماعة وأجرها، علمًا بأنا نصلي أحيانًا فرادى؟ جزاكم الله خيرًا.","title":"ثواب صلاة الرجل منفردًا لظروف العمل","answer":"الجواب:  إذا اضطر الإنسان لصلاة الفرد، وهو معذور لمرض، أو حراسة؛ ترجى له، يرجى له فضل الجماعة؛ لأنه معذور، لقول النبي ﷺ: إذا مرض العبد، أو سافر؛ كتب الله له ما كان يعمله وهو صحيح مقيم ولقوله ﷺ في الذين تخلفوا عن غزوة تبوك في المدينة، قال -عليه الصلاة والسلام-: إن في المدينة أقوامًا ما سرتم مسيرًا، ولا قطعتم واديًا إلا وهم معكم قالوا: وهم في المدينة؟ قال: وهم في المدينة حبسهم العذر وفي اللفظ الآخر: حبسهم المرض، فالمعذور له أجر العاملين إذا كان تخلفه من أجل العذر الشرعي، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9981/ثواب-صلاة-الرجل-منفردا-لظروف-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_422/42214.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11798,"question":"يقول: إذا كان هناك إنسان أتى من مكان بعيد، ولم يستطع أن يصلي مثلًا صلاة المغرب، وعندما وصل إلى البيت، فإذا بصلاة العشاء تقام، هل يصلي العشاء أولًا، أم يصلي المغرب؟ جزاكم الله خيرًا.","title":"حكم من أدرك الجماعة ولم يكن صلى الفرض الذي قبله","answer":"الجواب:  يصلي معهم العشاء بنية المغرب، لا يضيع الجماعة، يصلي معهم العشاء بنية المغرب، ويجلس في الثالثة، ويسلم معهم بعد ذلك، ثم يصلي العشاء حتى يحصل له فضل الجماعة، هذا هو المختار، وهذا هو الأرجح، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9982/حكم-من-ادرك-الجماعة-ولم-يكن-صلى-الفرض-الذي-قبله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_422/42215.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11807,"question":"من جدة رسالة بعث بها أحد الإخوة رمز إلى اسمه بالحروف (ع. ع. ع) أخونا يسأل عن حكم من يؤذن ويصلي بالناس ورأسه مكشوف، وهو يحفظ من القرآن الكريم الشيء الكثير؟ أفيدونا أفادكم الله.","title":"حكم من يؤم الناس في الصلاة وهو حاسر الرأس","answer":"الجواب:  لا حرج في ذلك أن يصلي ورأسه مكشوفة، لا بأس بذلك؛ لأن الواجب ستر العورة، وأن يكون على عاتقه شيء، إذا ستر العاتقين؛ كان ذلك أكمل، أما الرأس فليس من الشرط ستره، والمحرم مدة إحرامه يصلي ورأسه مكشوفة، لكن إذا صلى في زينته المعتادة؛ كان هذا حسنًا، ولاسيما عند الناس لقول الله سبحانه: يَا بَنِي آدَمَ خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ [الأعراف:31] فإذا صلى على العادة المعروفة بملابسه المعتادة كان هذا حسنًا، وإلا فلا يضره كشف الرأس، نعم.","link":"https://binbaz.org.sa/fatwas/9991/حكم-من-يوم-الناس-في-الصلاة-وهو-حاسر-الراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_423/42309.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11819,"question":"ماذا نقول بين السجدتين في سجود السهو؟","title":"ما الذي يقال بين السجدتين في السهو؟","answer":"الجواب:  مثلما يقال في سجود الصلاة: رب اغفر لي، رب اغفر لي، اللهم اغفر لي وارحمني، اللهم اغفر لي ذنبي كله.. إلى آخره، مثل سجود الصلاة، مثل ما بين السجدتين في سجود الصلاة. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10003/ما-الذي-يقال-بين-السجدتين-في-السهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_423/42321.mp3","categories":["سجود السهو"]},{"id":11824,"question":"إذا سها المصلي في صلاته فصلى ركعتين، أو ثلاثًا، ثم سلم وقام، بعد مدة تذكر أنه ترك الصلاة ناقصة، فهل يعيد الصلاة؟","title":"حكم من سها في صلاته فأنقص منها ركعة أو أكثر","answer":"الجواب:  إن ذكر قريبًا؛ كمل، وسجد للسهو، إذا كان قريبًا يعني: سلم من ثنتين في الظهر، أو في العصر، ثم ذكر قريبًا؛ يتمم ويسجد للسهو بعد السلام، هذا هو الواجب، والسنة أن يكون سجوده بعد السلام أفضل، وإن سجد قبل السلام؛ فلا بأس، أما إن طال الفصل، ولم يتذكر إلا بعدما طال الفصل؛ فإنه يعيدها كلها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10007/حكم-من-سها-في-صلاته-فانقص-منها-ركعة-او-اكثر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39510.mp3","categories":["سجود السهو"]},{"id":11843,"question":"مستمع يقول أخوكم في الله كمال الدين عبدالحليم يسأل ويقول: هل يجوز أن أصلي وراء إنسان حالق اللحية والشارب، وإزاره طويل، وحافظ للقرآن الكريم، هل يجوز الصلاة وراءه، أم لا؟","title":"حكم الصلاة خلف حالق اللحية ومسبل الإزار","answer":"الجواب:  مثل هذا لا يصلى وراءه، ينبغي له أن يعزل إلا إذا دعت الحاجة، ولم يتيسر للإنسان يعزله يصلي وراءه، لا يصلي وحده، يصلي مع الجماعة، لكن إذا تيسر للمسؤولين أن يزيلوه، ويعينوا مكانه من أهل الخير، كان هذا هو الواجب، لما ذكرت عنه من حلق اللحية، والإسبال. المقصود: أن الواجب على المسؤولين عن المسجد أن يقدموا من هو مرضي لله، من هو الأقرأ المتصف بصفة الخير، والمظهر الإسلامي الذي قد عفا لحيته، ولم يسبل ملابسه. المقصود: يتحرون لهذا المسجد الإمام الصالح المستقيم على شريعة الله، ويزال هذا، لكن إذا بليتم أنتم وغيركم بإمام حليق، أو مسبل، ولم يتيسر عزله؛ فلا تصلوا وحدكم، صلوا مع الجماعة، وانصحوا له بالكلام الطيب، والتوجيه الحسن؛ لعل الله يهديه بأسبابكم. نعم. المقدم: الله المستعان سماحة الشيخ! هل تكون النصيحة خفية، أو معلنة؟  الشيخ: إذا كان قد أعلن هذا الأمر؛ تكون معلنة، وإذا نصحه بينه وبينه لعل ذلك ينفع طيب، وإذا نصحه جماعة في المسجد، قالوا: يا عبدالله! اتق الله، ارفع ثيابه، يصير منكرًا ظاهرًا، إذا نصحوه ظاهرًا؛ فلا بأس، وإن رأوا، أو بعضهم نصيحته سرًا يزورونه في البيت، أو يقوم له واحد في محل الإمامة بينه وبينه، وينصحه، كل هذا طيب، يفعلون ما هو الأصلح. نعم. المقدم: بارك الله فيكم، وأحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/10029/حكم-الصلاة-خلف-حالق-اللحية-ومسبل-الازار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_396/39609.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11845,"question":"بعد هذا ننتقل إلى ليبيا لنقرأ رسالة بعث بها أحد الإخوة، يقول -أخوكم في الله من ليبيا- يسأل ويقول: ما حكم من يصلي في حجرته وبجانبه عمارة فيها قاعة يصلي فيها الطلبة اتخذوا منها مسجدًا، وليس لهم إمام محدد، وعذرهم أن الإمام يؤمهم قد يكون حالقًا للحيته، كما أنهم يطولون الصلاة أكثر من اللازم؟","title":"وجوب صلاة الجماعة في المساجد","answer":"الجواب:  يلزم الجميع أن يصلوا في المساجد إذا كان قربهم مساجد يسمعون الأذان، أما إذا كان ما في قربهم مساجد، فإن هذا الرجل يصلي معهم، يصلي مع الجماعة، طلبة وغير الطلبة، ويقدمون أفضلهم، وأقرأهم، ولا يقدم حالق اللحية، لا يقدم ولو كان أستاذًا، ولو كان مدرسًا، يقدم من هو أقرؤهم ممن وفر اللحية، وعرف بالخير، من المدرسين أو غيرهم، ويلزم من كان حولهم أن يصلي معهم الجماعة؛ لأن الرسول ﷺ قال: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر والجماعة واجبة، قد هم أن يحرق على ناس بيوتهم لما تخلفوا عن الجماعة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10024/وجوب-صلاة-الجماعة-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_396/39604.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11878,"question":"يسأل سماحتكم فيقول: ما حكم الإمام الذي يدخن، ويسبل الثياب، ويحلق لحيته، أو يقص اللحية إلا قليلًا منها، كعلامة تدل على اللحية، ما حكم إمامته للناس، أرجو الإفادة له، ولنا ولكل أمثالنا؟ جزاكم الله خيرًا.","title":"حكم إمامة المدخن والمسبل والحالق لحيته","answer":"الجواب:  هذه المسائل معاصي، حلق اللحية معصية، وقصها كذلك؛ لأن الرسول ﷺ قال: قصوا الشوارب، وأعفوا اللحى قصوا الشوارب، ووفروا اللحى؛ خالفوا المشركين خالفوا المجوس. هكذا التدخين لا يجوز؛ لما فيه من المضار العظيمة، هكذا الإسبال تحت الكعب لا يجوز للرجل، كل هذه معاص يجب الحذر منها، ولا يجوز للإمام، ولا غير الإمام تعاطيها، وإذا كان يتعاطى هذا؛ كان حقًا على المسؤولين عن المسجد أن يلتمسوا غيره، إذا لم يتب، والصلاة صحيحة، الصلاة خلفه صحيحة، لكن ينبغي للمسؤولين عن المسجد أن يلتمسوا إمامًا أصلح منه، والواجب عليه التوبة إلى الله من شرب التدخين، من الدخان.. من حلق اللحية.. من الإسبال؛ النبي ﷺ يقول: ما أسفل الكعبين من الإزار؛ فهو في النار الإسبال خطر عظيم، ومنكر كبير. ويقول ﷺ: ثلاثة لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب رواه مسلم في صحيحه. ويقول ﷺ: من جر ثوبه خيلاء؛ لم ينظر الله إليه يوم القيامة إذا كان خيلاء؛ فهو أعظم في الإثم، وإن جره ما قصد خيلاء؛ كان محرمًا، ومن وسائل الكبر، ولكن يكون إثمه أخف من إثم المتكبر، وكله محرم، كله منكر، هذا هو الصواب، ولو ما قصد الخيلاء، ما يجوز له أن يسبل ثيابه، وهذا من وسائل الخيلاء، ومن الإسراف، ومن تعريض الثياب للنجاسات؛ فلا يجوز. والتدخين شره عظيم، فالواجب تركه، والحذر منه، وفق الله الجميع. نعم. المقدم: اللهم آمين! جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10062/حكم-امامة-المدخن-والمسبل-والحالق-لحيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_424/42407.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11880,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من مكة المكرمة، وباعثتها إحدى الأخوات المستمعات تقول: (هـ. أ. هـ) أختنا لها عدد من الأسئلة من بينها سؤال تقول فيه: أنا فتاة صليت صلاة الفجر في جماعة في المسجد، وأثناء قراءة الإمام السورة التي عقب الفاتحة كبر وسجد سجود التلاوة، وأنا لم أكن أعلم أنه سجد للتلاوة؛ فركعت، حتى النساء اللاتي بجواري ركعن، ثم كبر الإمام، وبدأ يكمل السورة، ثم ركع، فركعت معه مرة ثانية، وبعض النساء سجدن، فما حكم تلك الصلاة بالنسبة لي، وبالنسبة للنساء أمثالي، جزاكم الله خيرًا؟","title":"حكم عدم متابعة المؤتم للإمام في الركوع والسجود نسياناً","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالحكم في هذا أن النساء اللاتي ركعن معه بعدما ركع صلاتهن صحيحة، وركوعهن الأول صدر عن جهل؛ فلا يضر صلاتهن، صلاتهن صحيحة، وركوعهن الأول الذي ركعنه وهو ساجد للتلاوة لا يضر؛ من أجل الجهل، أما اللاتي لم يركعن معه، بل سجدن، ثم استمررن في الصلاة، ولم يركعن معه، ولم يأتين بركعة بعد السلام، فعليهن قضاء تلك الصلاة، عليهن قضاؤها الآن بالنية عن تلك الصلاة؛ لأنهن أخللن بركعة من الصلاة، فطال الفصل، فعليهن أن يأتين بالصلاة كاملة، يقضينها كاملة، والله ولي التوفيق. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10064/حكم-عدم-متابعة-الموتم-للامام-في-الركوع-والسجود-نسيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_425/42501.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11891,"question":"إذا كنت في صلاة المغرب، وأنا مسبوق بركعة وعندما سلم الإمام؛ سلمت معه ناسٍ، ماذا أفعل بعدما أكبر تكبيرة الإحرام؟ ماذا أفعل؟ وذلك أنه بعدما كبر تكبيرة الإحرام، وأتى بالركعة الثالثة، هل أسجد بعد السلام أم قبله؟ جزاكم الله خيرًا.","title":"حكم سلام المسبوق مع الإمام ناسيًا","answer":"الجواب:  إذا كان فاتك ركعة، إذا سلم إمامك تقوم تأتي بالركعة، لا تسلم معه، وإذا سلمت معه ناسيًا؛ فلا حرج، تقوم وتكمل صلاتك، ثم تسجد للسهو بعد السلام أفضل، تسجد السهو بعدما تسلم، تسجد سجدتين للسهو؛ لأن سلامك مع إمامك سهوًا لا يضر، ولا يجوز لك أن تعمد ذلك، إذا تعمدت ذلك وأنت تعلم الحكم الشرعي؛ بطلت الصلاة، لكن إذا كنت جاهلًا، أو ناسيًا، ثم تنبهت؛ تكمل الصلاة، ثم تسجد للسهو بعد السلام أفضل، سجدتين من أجل سلامك مع الإمام ناسيًا، وإن سجدت للسهو قبل السلام، قبل سلامك إذا قضيت ما عليك؛ فلا حرج في ذلك، لكن الأفضل في مثل هذا أن يكون السجود للسهو بعد السلام. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10075/حكم-سلام-المسبوق-مع-الامام-ناسيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_425/42512.mp3","categories":["سجود السهو"]},{"id":11903,"question":"المستمع من جمهورية مصر العربية طارق طه بعث يسأل ويقول: هل إذا أدركت الإمام في التشهد الأخير أكون قد أدركت الجماعة؟ جزاكم الله خيرًا.","title":"هل إذا أدركت التشهد الأخير أكون قد أدركت الجماعة؟","answer":"الجواب:  الجماعة لا تدرك إلا بركعة، يقول النبي ﷺ: من أدرك ركعة من الصلاة؛ فقد أدرك الصلاة، فإذا لم تدرك إلا التشهد الأخير؛ فقد فاتك فضل الجماعة، وعليك أن تبادر دائمًا -إن شاء الله- إلى المسجد في أول الوقت؛ حتى لا تفوتك جماعة. نعم.","link":"https://binbaz.org.sa/fatwas/10087/هل-اذا-ادركت-التشهد-الاخير-اكون-قد-ادركت-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42604.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11904,"question":"إذا صليت فريضة معينة في جماعتين هل يجوز ذلك، أو لا؟","title":"حكم تكرار الصلاة الواحدة جماعة","answer":"الجواب:  الأولى هي الفريضة والثانية نافلة، إذا صليت الفريضة مع قوم، ثم جاء آخرون وصليت معهم، الصلاة الثانية نافلة والأولى هي الفريضة. نعم.","link":"https://binbaz.org.sa/fatwas/10088/حكم-تكرار-الصلاة-الواحدة-جماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42605.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11910,"question":"إذا دخلت في صلاة الفرض، أو صلاة النفل، وبعد تكبيرة الإحرام دخل رجل بجواري، هل تكون صلاتي جماعة؟ وإذا كانت صلاتي نفلًا، وما هو الحكم أيضًا؟ جزاكم الله خيرًا.","title":"حكم الائتمام بصلاة من دخل فيها منفردًا","answer":"الجواب:  نعم، تكون جماعةً، سواءٌ نفلًا أو فرضًا، إذا دخل معك واحدٌ يكون عن يمينك، وأنت الإمام، ويكون لكما فضل الجماعة في الفرض والنفل. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10094/حكم-الاىتمام-بصلاة-من-دخل-فيها-منفردا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42611.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11929,"question":"من محافظة مطروح في جمهورية مصر العربية قرية النجيلة المستمع: محمد جبريل الملاح يسأل ويقول: إذا دخلت المسجد، ووجدت المصلين في التشهد الأخير، وجلست معهم حتى التسليم، فهل يلزمني حينئذ أن أعود لأقيم الصلاة؟ علمًا بأني لم أكبر تكبيرة الإحرام، جزاكم الله خيرًا.","title":"حكم الدخول مع الجماعة والإمام في التشهد الأخير","answer":"الجواب:  إذا كنت لم تكبر، جلست من دون تكبير؛ فلا صلاة لك، وعليك أن تكبر حين تبدأ الصلاة، لكن الأفضل لك إذا جئت وهم في التشهد الأخير أن تكبر وأنت واقف تكبيرة الإحرام، ثم تجلس معهم، وتأتي بالتشهد، متابعة الإمام أفضل، ثم إذا سلم الإمام؛ قمت تؤدي صلاتك كاملة؛ لقول النبي ﷺ: إذا أتى أحدكم الصلاة؛ فليمش، وعليه السكينة والوقار، فما أدرك؛ صلى، وما فاته؛ أتمه وفي اللفظ الآخر: فما أدركتم؛ فصلوا، وما فاتكم؛ فأتموا. فالسنة لمن جاء والإمام جالس في التشهد الأخير أن يدخل معه في الصلاة، وأن يكبر تكبيرة الإحرام وهو واقف، ثم يجلس، وإن كبر حين الجلوس؛ فهذا لا بأس به، فيتشهد، ثم إذا سلم الإمام؛ قام، وصلى بقية صلاته، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10113/حكم-الدخول-مع-الجماعة-والامام-في-التشهد-الاخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_427/42706.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11940,"question":"من مكة المكرمة رسالة بتوقيع أحد الإخوة المستمعين، يقول: (م. ع. ح. الرحيلي) له سؤال طويل يقول فيه: لقد أصبت بمرض منذ ثمان سنين, فجعلني حبيس المنزل، وهذا المرض اكتئاب شديد، ثم إني استقلت من العمل؛ نتيجة لذلك المرض، ولا أستطيع الخروج من المنزل، أو الذهاب إلى المسجد؛ لأن المسجد في مكان مرتفع، وكما تعلمون أن معظم منازل مكة مرتفعة، ولا أستطيع الصعود إليه؛ لأنه -كما سبق وذكرت- أنني مريض، رغم أني أصلي صلاة الجمعة في المسجد إياه، أما باقي الصلوات فإنني أصليها في المنزل، فهل علي إثم في هذا؟ رغم أنني -ولله الحمد- أصلي النوافل، وأسبح الله كثيرًا -ولله الحمد- وجهوني، جزاكم الله خيرًا.","title":"حكم ترك صلاة الجماعة والصلاة في البيت بسبب المرض","answer":"الجواب:  نسأل الله أن يمنحك الشفاء والعافية، وأن يثبتنا وإياك على الهدى، والله سبحانه يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ويقول النبي ﷺ: إذا أمرتكم بأمر؛ فأتوا منه ما استطعتم فإذا كنت لا تستطيع الوصول إلى المسجد في الصلوات الخمس، فإنه لا بأس عليك أن تصلي في البيت، أما إذا كنت تستطيع؛ فالواجب عليك أن تصلي في المسجد مع إخوانك، وأن تحذر الكسل وطاعة الشيطان، وأن تحذر -أيضًا- التشبه بالمنافقين المتخلفين عن الصلاة في الجماعة وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]: وَمَنْ يَتَّقِِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. فنوصيك بالجد والنشاط، والتعوذ بالله من الشيطان الرجيم، وسؤال الله العافية والشفاء وأنت في السجود، وفي آخر الصلاة، وفي صلاة الليل، وبين الأذان والإقامة، اسأل ربك، واضرع إليه بصدق أن يعافيك وأن يمنحك الشفاء، وأن يعينك على كل عمل يرضيه، وأبشر بالخير إذا صدقت، فالله -جل وعلا- سوف يعينك على أداء ما فرض عليك على الوجه الذي يرضيه  نعم.","link":"https://binbaz.org.sa/fatwas/10125/حكم-ترك-صلاة-الجماعة-والصلاة-في-البيت-بسبب-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42804.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":11996,"question":"بعد هذا رسالة بعث بها المستمع: محمد صالح الأحمر، يسأل جمعًا من الأسئلة، في أحدها يقول: هل يجوز للمسبوق أن يكون إمامًا؟","title":"حكم الائتمام بالمسبوق","answer":"الجواب:  إذا ائتم به بعض الناس؛ فلا حرج -إن شاء الله- على الصحيح، لو فاته مثلًا ركعة، أو أكثر، ودخل إنسان، وجعله إمامًا؛ فلا حرج، إن شاء الله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10181/حكم-الاىتمام-بالمسبوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43110.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12010,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: محمد ناجي مهيوب من مكة المكرمة، أخونا له جمع من القضايا من بينها قضية يقول فيها: قمنا بصلاة المغرب خلف إمام، وفي الركعة الثانية سجد، سهي سجدة واحدة، وقام بالركعة الثالثة، فقلنا له: سبحان الله، ولم يستجب لنا، وتابعنا معه الصلاة حتى سلم، فقلنا له بما حصل، وقام وأتى بركعة، وسجد سجود السهو قبل السلام، فهل ما قمنا به صحيح؟","title":"حكم عدم عمل الإمام بتنبيه المأمومين على سهوه","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: هذا الذي عمله الإمام لا حرج فيه، ولا بأس؛ لأنه بطلت الركعة التي ترك منها السجدة، وأتى بركعة عوضًا منها، والحمد لله ولا حرج في ذلك، وأنتم حين نبهتموه لعله لم يقتنع بتنبيهكم، ولم ينتبه لما أردتم، فلهذا لم يفعل شيئًا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10195/حكم-عدم-عمل-الامام-بتنبيه-المامومين-على-سهوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_432/43201.mp3","categories":["سجود السهو"]},{"id":12018,"question":"سؤال آخر تقول: هل يجوز أن أصلي أنا وأخي جماعة، علمًا بأنه غير متزوج، إذ أنه في بلدنا يقولون: يجب أن يكون الإمام متزوجًا، فهل هذا صحيح؟ جزاكم الله خيرًا.","title":"صفة صلاة المرأة مع أخيها","answer":"الجواب:  لا أصل لهذا الشرط، يجوز أن يكون الإمام متزوجًا، وغير متزوج، لا حرج في ذلك، هذا القول باطل، الإمام ليس من شرطه أن يكون متزوجًا، وإذا صليت مع أخيك؛ صلي خلفه، لا تصفي معه، المرأة ما تصف مع الرجال، فإذا صليت معه في الليل مثلًا في التهجد بالليل؛ تكوني خلفه، وهو لا يصلي في البيت الفرائض، يلزمه أن يصلي مع الناس الفريضة، ولا يصلي في البيت، وإذا صلى في البيت؛ لأنه فاتته الصلاة؛ بسبب نوم، أو نحوه، أو صلاة النافلة في الليل، وصليت معه؛ فلا بأس، لكن لا تقفي عن يمينه، ولكن خلفه، نعم؛ لأن الرسول ﷺ أمر النساء أن يكن خلف الرجال، وصلت معه أم سليم مع ابنها أنس، فصف أنس معه ﷺ وصفت خلفهم، وفي الحديث الآخر: \"صف أنس واليتيم خلف النبي ﷺ وهي من ورائهم\" نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10203/صفة-صلاة-المراة-مع-اخيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_432/43209.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12025,"question":"من دولة قطر المستمع موسى علي آدم بعث يسأل ويقول: حدثونا عن الوقوف منفردًا خلف الإمام أثناء الصلاة كيف يكون ذلك؟ وهل هو جائز؟ وهل تصح الصلاة جزاكم الله خيرًا؟","title":"حكم الوقوف منفرداً خلف الإمام أثناء الصلاة هل هو جائز؟","answer":"الجواب:  الوقوف خلف الإمام، وأنت وحدك ليس بجائز، ولا تصح معه الصلاة، يقول النبي ﷺ: لا صلاة لمنفرد خلف الصف ورأى رجلًا يصلي خلف الصف وحده -عليه الصلاة والسلام- فأمره أن يعيد الصلاة، فليس للفرد أن يصلي خلف الناس، ولكن ينتظر حتى يجد فرجة، أو يحصل من يصف معه، أو يتقدم فيصف مع الإمام عن يمينه، أما أن يصلي وحده لا، ولكن ينتظر، أو يلتمس فرجة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10210/حكم-الوقوف-منفردا-خلف-الامام-اثناء-الصلاة-هل-هو-جاىز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_432/43216.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12029,"question":"مستمع يقول: أسكن في منطقة تكاد تكون بعيدة عن أقرب المساجد، مما لا يمكنني من تأدية صلاة الفجر، وأقوم بتأديتها في وقتها في المنزل، فهل أنا آثم؟","title":"حكم الصلاة في البيت لبعد المسجد","answer":"الجواب:  إذا كان المسجد بعيدًا لا تسمع النداء؛ فأنت معذور، أما إذا كنت تسمع النداء لو كانت الأرض يعني متهيئة ما فيها أصوات تمنع، ولا فيها شيء يمنع، فإنك تسعى إلى المسجد.  والمقصود: صوت المؤذن من دون مكبر، إذا كنت تسمع الصوت المعتاد عند هدوء الأصوات تسمعه؛ فعليك السعي إلى المسجد؛ لقول النبي ﷺ: من سمع النداء، فلم يأت؛ فلا صلاة له إلا من عذر قيل لابن عباس الراوي: ما هو العذر؟ قال: خوف، أو مرض، وجاءه ﷺ رجل أعمى فقال: يا رسول الله! ليس لي قائد يقودني إلى المسجد، فهل ليي من رخصة أن أصلي في بيتي؟ فقال له ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب فهذا رجل أعمى أمره النبي ﷺ أن يجيب، وليس له قائد يقوده، فكيف بحال البصير والقادر؟!! المقصود: أن عليك الإجابة إذا كنت في محل تسمع فيه النداء، فأنت عليك الإجابة، أما إذا كنت بعيدًا لا تسمع النداء؛ فلا يلزمك، وإن تجشمت المشقة، وصبرت.. سيارة، أو على قدميك؛ فأنت على خير عظيم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10214/حكم-الصلاة-في-البيت-لبعد-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_432/43220.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12046,"question":"يقول: كثيرًا ما يحدث في رمضان أن تدخل جماعة أخرى وتصلي العشاء جماعة، ونحن في وقتها نصلي التراويح، فهل يجب عليهم أن يدخلوا معنا في التراويح، أم يصلوا منفردين؟ جزاكم الله خيرًا.","title":"حكم إقامة المتأخرين لصلاة العشاء أثناء التراويح","answer":"شالجواب: إذا صلوا منفردين؛ فلا بأس، ولعله أولى؛ خروجًا من الخلاف، وإن صلوا معكم التراويح، وإذا سلم الإمام قاموا وكملوا؛ فلا بأس على الصحيح، لكن إذا صلوا وحدهم؛ فهذا أصح عند الجميع، وإذا صلوا خلف من يتنفل، ثم قاموا وكملوا؛ أجزأ على الصحيح، وصح، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10231/حكم-اقامة-المتاخرين-لصلاة-العشاء-اثناء-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_433/43315.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12052,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من حائل، باعث الرسالة مستمع رمز إلى اسمه بالحروف (س. ك. س) أخونا يقول: هناك أمر قد أشكل علينا كثيرًا، وهو استواء الصف من جهة اليمين والشمال، فإذا كان في جهة اليمين أكثر مما هو في جهة الشمال، فهل للإمام نقل من كان أكثر إلى الجهة الأخرى حتى يعتدل الصف، أو يبقيه على ما هو عليه؟ جزاكم الله خيرًا.","title":"تساوي عدد المصلين في جهة اليمين واليسار في الصف","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فليس للإمام أن ينقل ما زاد في جهة اليمين إلى جهة اليسار، بل يترك الأمر على حاله؛ لأن اليمين أفضل، يمنة كل صف أفضل، فإذا زاد اليمين؛ فلا بأس، ولو كان اليسار أقل، ولا حرج في ذلك، والإمام في الوسط في محله، نعم. المقدم: وإذا كانت الزيادة في الجانب الأيسر والجانب الأيمن أقل؟ الجواب: لا حرج أيضًا، لكن لو نبههم كأن يقول: الأفضل لكم أن يكون الأكثر من جهة اليمين، يعني من باب الوعظ والتذكير والترغيب. المقدم: نعم نعم. جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10237/تساوي-عدد-المصلين-في-جهة-اليمين-واليسار-في-الصف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_434/43401.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12060,"question":"إذا كان لرجل بيت على رأس جبل، وليس بجانبه بيوت، فهل له أن يصلي بأسرته جماعة؟ وكيف يكون حالهم؟ جزاكم الله خيرًا.","title":"حكم الصلاة بأهل البيت لمن كان بعيداً عن المسجد","answer":"الجواب:  إذا كانت المساجد بعيدة لا يسمع النداء؛ صلى وحده، وإن صلى بأهله؛ فلا بأس، صلى بنسائه، يكونون خلفه؛ فلا بأس، أما إن كان عنده أولاد؛ فيصلي هو وإياهم، أو عنده إخوة، أو خدم؛ فيصلي كما يصلي الناس، يكون هو الإمام، ويكونون خلفه، وإذا صلى النساء معهم خلفهم؛ فكل هذا لا بأس به. أما إن كان بقربهم مساجد يسمعون النداء؛ فالواجب عليك السعي إلى المسجد؛ لقوله ﷺ: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر إذا كان المسجد قريبًا يسمع نداءه بدون مكبر لقربه؛ فإنه يلزمه الذهاب إليه، أما إذا كان بعيدًا ما يسمعه إلا بالمكبر؛ لبعده؛ فهذا لا يلزمه، وإن ذهب إليه يطلب الأجر؛ فهذا خير، وأفضل.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10245/حكم-الصلاة-باهل-البيت-لمن-كان-بعيدا-عن-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_434/43409.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12103,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يسأل فيها سماحتكم سؤالين: السؤال الأول هو: هناك مجموعة من الرجال يسكنون في منزل بعيد عن الناس، فهو بعيد قليلًا، وأقرب مسجد لهذا المنزل يبعد أكثر من الكيلو بقليل، وهم يسمعون النداء من مساجد تبعد أكثر من كيلوين بسبب عوامل منها قوة مكبرات الصوت، ومن هؤلاء الرجال من يجيد القراءة، وقد جعلوه إمامًا، وجعلوا لهم مكانًا مخصصًا للصلاة وهم يصلون الصلوات كلها جماعة، ويقيمون الصلاة، فهل يجوز لهؤلاء الصلاة في مسجدهم الخاص هنا حتى ولو كانوا ثلاثة أو أربعة، مع أن أدوات النقل موجودة، وهي تصعب في بعض الأوقات جزاكم الله خيرًا؟","title":"حكم صلاة البعيد عن المسجد في بيته","answer":"الجواب:  إذا كانوا يسمعون النداء بدون مكبر، إذا استمعوا له في الأوقات الهادئة يسمعون النداء؛ يلزمهم الذهاب إلى المسجد على أقدامهم، أو بواسطة وسائل النقل، أما إذا كانوا بعيدين حيث لا يسمعون النداء إلا بالمكبر؛ فإنه لا يلزمهم، إذا صلوا في مكانهم جماعة؛ كفى ذلك، وإذا صبروا، وذهبوا إلى المساجد ولو ما سمعوا النداء إلا بمكبر إذا صبروا، وذهبوا إلى المساجد على الأقدام، أو بواسطة وسائل النقل؛ فهذا خير لهم، وأفضل وأبعد عن الشبهة، وأبعد أيضًا عن التساهل بهذا الأمر العظيم. فنصيحتي لهؤلاء الصبر على بعض التعب، والذهاب إلى المساجد؛ لأن الشيطان قد يزين لهم التساهل، ويقول لهم: إنكم لا تسمعون، وهم يسمعون النداء لو استمعوا، لكن ينبغي للمؤمن أن يتحرى الخير، وأن يسارع إليه، وأن يبتعد عن الشبهة، وأن يتهم بالتساهل في أمر الله، والذهاب على الأقدام كل خطوة يرفعه الله بها درجة، ويحط عنه بها خطيئة، ويكتب الله له بها حسنة، هذا خير عظيم، وهكذا في السيارات. فنصيحتي للجميع العناية بصلاة الجماعة، والذهاب إلى المساجد ولو فيها بعض التعب اليسير، فالحمد لله، لكن الرخصة لهم رخصة إذا كانوا لا يسمعون النداء لولا المكبرات، لا يسمعون النداء لبعد المسجد عنهم؛ فلا حرج عليهم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10288/حكم-صلاة-البعيد-عن-المسجد-في-بيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_437/43706.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12108,"question":"كثر السؤال سماحة الشيخ عن الأئمة، فأخونا أيضًا يسأل عن الشروط التي يجب أن تتوفر في الإمام الذي يكون مصلٍ بالناس، جزاكم الله خيرًا.","title":"الشروط المطلوب توافرها في الأئمة","answer":"الجواب:  يجب على المسؤولين أن يتحروا في الإمام أن يكون أهلًا للإمامة لعدالته ودينه وعلمه وفضله، ويكون مجيدًا للقرآن ولقراءة القرآن حتى يختاروا الأفضل فالأفضل، يقول النبي ﷺ: يؤم القوم أقرؤهم لكتاب الله، فإن كانوا في القراءة سواء؛ فأعلمهم بالسنة، فإن كانوا في السنة سواء؛ فأقدمهم هجرة، فإن كانوا في الهجرة سواء؛ فأقدمهم سلمًا وفي رواية: فأكبرهم سنًا. فعلى المسؤولين أن يتحروا الأئمة، وأن يقدموا الأفضل فالأفضل من جهة الدين والعدالة والقراءة والعلم، الأفضل فالأفضل، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10293/الشروط-المطلوب-توافرها-في-الاىمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_437/43711.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12109,"question":"إذا دخل أحد المسجد للصلاة مع الجماعة والصف كامل، هل له الصلاة خلفهم في صف ثاني، أو يسحب من الصف الأول واحدًا؟ أفيدونا جزاكم الله خيرًا، وصاحب هذا السؤال هو المستمع (م. ن).","title":"حكم صلاة المنفرد خلف الصف إذا لم يجد فرجة","answer":"الجواب:  الواجب عليه أن يلتمس فرجة حتى يدخل فيها، لا يصلي وحده؛ يلتمس فرجة، أو يصف عن يمين الإمام، ولا يجذب أحدًا؛ لأنه إذا جذب أحدًا؛ فتح فرجة في الصف، والرسول ﷺ أمر بسد الخلل، وعدم الفرج في الصلاة، لكن ينتظر؛ لعله يأتي أحد يصف معه، فإن سلموا؛ صلى وحده، وهو معذور، والحمد لله، أما أنه يصلي وحده خلف الصف فلا، النبي  قال: لا صلاة لمنفرد خلف الصف ولما رأى رجلًا يصلي خلف الصف وحده، أمره أن يعيد الصلاة، ولم يسأله ويقول: هل أنت وجدت أو ما وجدت؟ بل أمره أن يعيد الصلاة لما رآه صلى خلف الصف وحده، أمره أن يعيد الصلاة، وقال: لا صلاة لمنفرد خلف الصف فليس لأحد أن يصلي خلف الصف وحده، ولكن ينتظر، أو يلتمس فرجة، أو يقف عن يمين الإمام، هذا هو الواجب عليه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10294/حكم-صلاة-المنفرد-خلف-الصف-اذا-لم-يجد-فرجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_437/43712.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12178,"question":"رجل صلى مع جماعة فريضة، وهذا الرجل فاتته ركعة واحدة من الفريضة، فسها الإمام، وصلى ركعة زيادة على المكتوبة، هل الرجل المتأخر يسلم مع الجماعة، أو يكمل الركعة التي فاتته؟","title":"حكم متابعة الإمام عند قيامه إلى ركعة زائدة","answer":"الجواب:  هذا الرجل لا يقوم في الزيادة، إذا كان يعلم أنها زيادة لا يقوم ويجلس مع الناس، وهكذا الجماعة لا يقومون، ينبهون: سبحان الله، سبحان الله، ولا يقومون معه، فإن رجع؛ فالحمد لله، وإن لم يرجع؛ صبروا حتى يسلم؛ لأنه قد يعتقد أنه مصيب، فإذا سلم؛ سلموا معه، إذا كانوا يعتقدون أنه مخطئ؛ لا يقومون معه. وهكذا الذي فاتته ركعة لا يقوم معه إذا كان يعلم أنها زائدة، فإذا سلم الإمام؛ قام، وقضى الركعة التي فاتته؛ لأن القضاء إنما يكون بعد السلام، بعد سلام الإمام، وإذا قام معه جاهلًا ما درى أنها زيادة، فإنها لا تجزئه على الصحيح، وإنما يقضي بعد ذلك، إذا سلم الإمام؛ قضى، هذا هو الصواب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10364/حكم-متابعة-الامام-عند-قيامه-الى-ركعة-زاىدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_443/44305.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12187,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين من جدة هو: محمد أحمد علي، أخونا محمد رسالته مطولة كثيرًا، ملخص ما فيها: أنه يشاهد بعض المصلين يتكلف في المباعدة بين القدمين أثناء الصلاة، ويرجو من سماحة الشيخ التوجيه؟","title":"حكم مباعدة القدمين أثناء صلاة الجماعة","answer":"الجواب:  السنة للمؤمن في هذا أن يقارب بين قدميه، ولا يؤذي جيرانه، وهكذا الآخر والآخر كلهم يتقاربون ويسدون الخلل بينهم والفرج، ولا يؤذي بعضهم بعضًا، فيكون قدماه في مكانهما المناسب، بحيث لا يؤذي من عن يمينه وشماله، وهكذا الآخر والآخر كل واحد يلصق قدمه بقدم صاحبه؛ حتى لا يكون بينهما فرج، ومن غير أذى، ولا محاكة، ولا أذى، هكذا. أما أن يفسح حتى يؤذي من حوله؛ فلا يجوز هذا، الواجب أنه يجر صاحبه إليه، والآخر يجر صاحبه إليه حتى يسدوا الفرج، ويتقاربوا من دون أن يؤذي بعضهم بعضًا، تكون مقاربة، يسد بها الخلل، ولكن ليس فيها إيذاء، ولا مضايقة للمصلي، كل واحد يلاحظ أخاه، ولا يضايقه، ولا يؤذيه، ولكن مع هذا يسدون الخلل، يتقاربون من غير حاجة إلى يفسح هذا ويفسح هذا، بل يتقاربون؛ حتى يسدوا الخلل بينهم، هذا هو المشروع، وهذا هو الواجب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10373/حكم-مباعدة-القدمين-اثناء-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_443/44314.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12210,"question":"ويسأل أيضًا ويقول: كذلك ألاحظ أنهم يقيمون الصلاة بعد الأذان مباشرة في صلاة المغرب، دون صلاة ركعتين، فهل هذا صحيح؟","title":"حكم التعجيل بصلاة المغرب وترك ركعتي المغرب القبلية","answer":"الجواب:  الأفضل عدم العجلة قليلًا، كان النبي ﷺ يبكر بالمغرب أكثر من غيرها -عليه الصلاة والسلام- وكان لا يجلس بعد الأذان إلا قليلاً بقدر ما يصلوا ركعتين، فالسنة أن يصلي ركعتين بعد الأذان، ثم يقيم الإمام بعد ذلك، لا يعجل، يتأنى شيئًا حتى يدرك الذي في الطريق الصلاة، والذي يتوضأ يدرك الصلاة، ولكن لا يكون مثل الظهر والعصر والمغرب والعشاء والفجر، لا، بل يتقدم بها أكثر، يعني يسرع بها أكثر؛ لأن الرسول ﷺ كان لا يتأخر فيها إلا قليلًا، وكان الناس يصلون ركعتين، ثم يقيم -عليه الصلاة والسلام-  نعم.","link":"https://binbaz.org.sa/fatwas/10396/حكم-التعجيل-بصلاة-المغرب-وترك-ركعتي-المغرب-القبلية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_445/44505.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12221,"question":"من اليمن الشمالي رسالة بعث بها المستمع (ح. م. مهدي) الرسالة تضمنت عددًا من الأسئلة من بينها سؤال يقول: هل يجوز للرجل أن يؤم الناس وهو مكشوف الرأس، أم ل؟ا نرجو الإفادة، جزاكم الله خيرًا.","title":"حكم إمامة الرجل حاسر الرأس","answer":"الجواب:  نعم لا حرج في ذلك، لا بأس أن يصلي وهو مكشوف الرأس؛ لأن الحديث إنما جاء في الرداء يقول النبي ﷺ: لا يصلي أحدكم في ثوب واحد ليس على عتقه من شيء. فالمقصود ستر العاتقين، أما الرأس فليس يجب ستره، ولهذا قال -عليه الصلاة والسلام-: لا يصلي أحدكم في الثوب الواحد ليس على عاتقه وفي اللفظ الآخر عاتقيه منه شيء . والعاتق الكتف، ولم يقل: على رأسه، وكان ﷺ في إحرامه يصلي بالناس في الرداء والإزار، وهكذا الصحابة يصلون في الرداء والأزر، وكانت عادة العرب يلبسون الأزر والأردية، والرأس ليس بشرط قد توضع عليه العمامة، وقد لا توضع عليه العمامة، فإن وضع العمامة عليه؛ كان أحسن؛ لأنها من الزينة، وإن لم يضعها؛ فلا حرج في ذلك، والحمد لله، نعم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10409/حكم-امامة-الرجل-حاسر-الراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_446/44609.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12240,"question":"إذا صليت ثلاث ركعات في صلاتي الرباعية، وبعد ثلاث ركعات سلمت، وبعد تسليمي تذكرت أني صليت ثلاثًا فقط، قمت وأتيت بركعة واحدة، فما حكم صلاتي؟","title":"حكم من نسي ركعة ولم يذكر إلا بعد السلام","answer":"الجواب:  صحيحة وعليك السجود للسهو، عليك أن تسجد سجدتين بعد السلام هذا السنة بعد السلام، صل ركعة تكمل صلاتك، ثم تسلم، ثم تسجد سجدتين للسهو؛ جبرًا لصلاتك؛ لأن النبي ﷺ ثبت عنه أنه صلى العصر في بعض الأيام ثلاثًا، وسلم، ثم نبه؛ فأتى بالركعة الرابعة، ثم سلم، ثم سجد سجدتين للسهو بعد السلام، كما وقع لك. وهكذا لو سلمت من ثنتين من الرباعية، أو من المغرب، ثم تذكرت بعد السلام؛ تقوم، وتكمل صلاتك، ثم تسلم، ثم تسجد للسهو، وإذا كنت إمامًا، ولم ينبهوك؛ فإنهم أيضًا يقومون معك للكمال، ثم يسجدوا معك للسهو بعد السلام، كما وقع للنبي -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10428/حكم-من-نسي-ركعة-ولم-يذكر-الا-بعد-السلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_448/44804.mp3","categories":["سجود السهو"]},{"id":12246,"question":"نعود في هذه الحلقة أيضًا إلى رسالة الأخت نالة العسيري الطائف، عرضنا بعض أسئلتها في حلقات مضت، وفي هذه الحلقة تسأل وتقول: ماذا يقول المصلي في سجود السهو؟","title":"ما الذكر المشروع في سجود التلاوة والسهو والشكر؟","answer":"الجواب:  يقول مثلما يقول في سجود الصلاة، المصلي في سجود السهو وسجود التلاوة مثلما يقول في سجود الصلاة، يقول: سبحان ربي الأعلى، سبحان ربي الأعلى، ويدعو ربه بما تيسر، ويقول أيضًا: اللهم لك سجدت، وبك آمنت، ولك أسلمت، سجد وجهي للذي خلقه، وصوره، وشق سمعه وبصره، بحوله وقوته، تبارك الله أحسن الخالقين، يقول هذا في سجود الصلاة، سجود السهو، سجود التلاوة، سجود الشكر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10435/ما-الذكر-المشروع-في-سجود-التلاوة-والسهو-والشكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_448/44810.mp3","categories":["الأدعية والأذكار","سجود السهو"]},{"id":12292,"question":"يقول: أحفظ معنى حديث عن الرسول ﷺ يقول: إن منكم منفرين، من أم الناس فليخفف وجهوا الأئمة حول معنى هذا الحديث، إذ أني ألاحظ أن بعض الأئمة يطيلون في الصلاة، فينفرون الناس عن المساجد؟","title":"حكم إطالة الإمام في الصلاة","answer":"الجواب:  هذا هو المشروع للأئمة ألا ينفروا الناس، لا بالإطالة، ولا بالتأخر عنهم عن الوقت الذي ينبغي أن تقام فيه الصلاة، بل ينبغي للإمام أن يتحرى الرفق بالجماعة من جهة المواظبة على إقامة الصلاة في وقتها، ومن جهة عدم الإطالة، تكون قراءته وركوعه وسجوده على وجه ليس فيه شدة، ليس فيه إطالة، يتحرى صلاة النبي ﷺ وما كان يفعله -عليه الصلاة والسلام- قال أنس : ما صليت خلف إمام أتم صلاة، ولا أخف صلاة من النبي، عليه الصلاة والسلام ويقول ﷺ: أيها الناس! أيكم أم الناس فليخفف؛ فإن فيهم الصغير والكبير والضعيف وذا الحاجة.  فوصيتي لجميع الأئمة أن يلاحظوا هذا الأمر، وأن يجتهدوا بالرفق برعيتهم، والحرص على تشجيعهم على الصلاة في الجماعة، وعدم تنفيرهم، وقد اشتكى بعض الناس معاذًا، وقالوا: إنه يطيل  فغضب النبي ﷺ في ذلك، وقال: أيها الناس! إن منكم منفرين وشد في ذلك، عليه الصلاة والسلام. فالسنة كون الإمام أن يتحرى الرفق بالمأمومين، وعدم الإطالة عليهم، لكن لا يكون تخفيفه مخلًا بالصلاة، يكون تخفيفه معه التمام، تخفيف معه تمام في قراءته وركوعه وسجوده بحيث يركد في القراءة، ويقرأ مثلما أوصى به النبي ﷺ كالغاشية و اقْرَأْ بِاسْمِ رَبِّكَ [العلق:1]: وَالسَّمَاءِ ذَاتِ الْبُرُوجِ [البروج:1] وأشباهها في الظهر والعصر والعشاء، وهكذا دون ذلك في المغرب كالزلزلة والعاديات والضحى، وأشباه ذلك. وإذا أطال بعض الأحيان في المغرب وهو سنة، كما فعله النبي ﷺ، فإنه صلى فيها في بعض الليالي بالمرسلات، وصلى فيها بعض الليالي بـ وَالطُّورِ ۝ وَكِتَابٍ مَسْطُورٍ [الطور:1-2] فهذا يدل على أنه لا بأس بالإطالة بعض الأحيان كما فعله النبي ﷺ في المغرب. والفجر يطيلها غالبًا؛ لأن النبي كان يطيلها -عليه الصلاة والسلام- يقرأ فيها بـ(ق) وأشباهها كالواقعة وأشباهها، وإذا خفف بعض الأحيان؛ فلا بأس، والمقصود أنه يتحرى صلاة النبي ﷺ ويتحرى فعله، عليه الصلاة والسلام. وهكذا في الركوع والسجود لا يطيل إطالةً تشق على الناس، بل يركد ويسبح خمس تسبيحات، أو سبع تسبيحات، أو عشر تسبيحات، وأدنى الكمال ثلاث، والواجب مرة، لكن يطمئن وهكذا في السجود، والركوع يقول: سبحان ربي العظيم، سبحان ربي العظيم، في السجود يقول: سبحان ربي الأعلى، سبحان ربي الأعلى، ويشرع له أن يقول مع ذلك: (سبحانك اللهم ربنا وبحمدك اللهم اغفر لي) في الركوع والسجود، وبين السجدتين يطمئن ولا يعجل يقول: رب اغفر لي رب اغفر لي، ربي اغفر لي اللهم اغفر لي وارحمني واهدني واجبرني وارزقني وعافني، وهكذا إذا وقف بعد الركوع يعتدل ولا يعجل ويقول: ربنا ولك الحمد حمدًا كثيرًا طيبًا مباركًا فيه، ملء السماوات، وملء الأرض، وملء ما بينهما، وملء ما شئت من شيء بعد وإذا زاد بعض الأحيان: أهل الثناء والمجد أحق ما قال العبد وكلنا لك عبد، لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد فهذا حسن؛ لأن الرسول ﷺ كان يفعل هذا وهذا، عليه الصلاة والسلام. فالمسلم يتأسى به ﷺ ويتحرى أفعاله وأقواله في جميع شؤونه العبادية، يعني: في جميع العبادات من صلاة وصوم وغير ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10492/حكم-اطالة-الامام-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_452/45212.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12306,"question":"أحد الإخوة المستمعين رمز إلى اسمه بالحروف (خ. س. العنزي) من عفيف، يقول في رسالة طويلة يصف إمام مسجدهم بأنه ضيق الصدر، ومصاب بكثير من الأمراض، ويؤخر إقامة الصلاة، وهم على خلاف دائم معه، مما اضطر بعض المصلين إلى أن يصلوا في مساجد أخرى غير ذلك المسجد، ويرجو نصحهم ونصح إمامهم، ونصح الأئمة حتى يكونوا على وفاق مع جماعتهم، جزاكم الله خيرًا.","title":"نصيحة إمام مسجد يؤخر وقت إقامة الصلاة","answer":"الجواب:  الواجب على الأئمة جميعًا أن يتقوا الله، وأن يتحروا سنة رسول الله ﷺ في صلاتهم، وفي كل شؤونهم، والواجب على الجماعة أن يتقوا الله أيضًا، وأن يكونوا عونًا للأئمة على فعل السنة، فالإمام يتحرى السنة في صلاته، في قراءته وركوعه وسجوده؛ حتى لا يشق على الناس، ويتحرى السنة أيضًا في ألا يتأخر عنهم، ويحبسهم في المسجد، يأتي في الأوقات المحددة، ويراعي الأوقات المحددة؛ حتى لا يشق على الناس، ويرفق بهم. والجماعة عليهم أن يراعوا ذلك أيضًا، فلا يشقوا عليه، ويلجئوه إلى أن يخالف السنة، أو يلجئوه إلى أن يبكر حتى تفوت الصلاة كثيرًا من الناس، بل كل منهما يتعاون مع أخيه الإمام، والجماعة يتعاونون على البر والتقوى، وعلى العناية بسنة النبي ﷺ في ذلك، حتى يكون أداؤهم للصلاة على وجه مرضي. وإذا كان الإمام يعاندهم، ولا يعتني بالسنة؛ يرفع أمره إلى المرجع، إلى الأوقاف، وإذا كانت الأوقاف لم تلب الدعوة، ولم تبال؛ يرفع إلى المحكمة، حتى تنظر المحكمة في الموضوع، أو إلى الهيئة من باب التعاون على البر والتقوى، وإن استقام الأمر؛ فالحمد لله.  والواجب على الإمام ألا يلجئهم إلى الرفع إلى المحكمة، أو إلى الأوقاف، بل يتحرى السنة هو ويقنعهم بالسنة، ويعلمهم السنة حتى يعلموها، وحتى يقتنعوا بأن عمله طيب، وإذا لم يقتنعوا؛ فالمحكمة أو الهيئة ترشد الجميع إذا كانت الأوقاف لم تقم بالواجب، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10506/نصيحة-امام-مسجد-يوخر-وقت-اقامة-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_453/45312.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12309,"question":"المستمع (م. ع. م. ع) من السودان بعث برسالة يقول فيها: بعض القرى عندنا تشترط شروطًا غاية في الغرابة في الإمامة، إذ في هذه القرى لا بد من معرفة أصل الإمام، وأنه من سكان القرية الأصليين، أي: غير وافد عليها، بصرف النظر عن حفظه للقرآن، وأهليته للإمامة، فهل هذان الشرطان لازمان للإمامة، أم أنهما بدعة؟ نرجو النصح والتوجيه، جزاكم الله خيرًا.","title":"حكم اشتراط كون الإمام غير وافد لصحة إمامته","answer":"الجواب:  هذان الشرطان لا أصل لهما، المهم أن يكون معروفًا بعدالته واستقامته وإجادته للقراءة، أما كونه من أهل البلد، أو من غير أهل البلد؛ ليس بلازم، ولو كان غريبًا. إذا عرف صلاحه واستقامته؛ فالحمد لله، فليس من الشرط أن يكون من أهل البلد، أو مولدًا في البلد، ولكن المهم أن يكون صالحًا للإمامة كما قال النبي ﷺ: يؤم القوم أقرؤهم لكتاب الله، فإن كانوا في القراءة سواء؛ فأعلمهم بالسنة الحديث، ويقول ﷺ: ليؤمكم قراؤكم. فالإمام يكون من خيرة الناس، سواء كان من أهل البلد الذين هم مستوطنون في البلد، مولدون فيها، أو ممن ورد إليها، ونزل بها، واستقر فيها، وإن كان ليس من أهلها إذا كان صالحًا للإمامة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10509/حكم-اشتراط-كون-الامام-غير-وافد-لصحة-امامته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_453/45315.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12314,"question":"إذا صلى أحد، ونسي التشهد الذي بين الركعتين، وقام وكبر، ثم تذكر بعد ذلك فهل يجلس للتشهد، أم يكمل الركعة؟ وكيف يتمها؟ جزاكم الله خيرًا.","title":"حكم من نسي التشهد الأوسط أو شك أنه نسيه","answer":"الجواب:  إذا ترك الإمام التشهد الأول، أو المنفرد، ولم يذكر إلا بعد أن استتم قائمًا؛ فالأفضل له أن يكمل الصلاة، ثم يسجد للسهو سجدتين قبل أن يسلم، كما فعله النبي، عليه الصلاة والسلام. أما إن ذكر حين القيام، أو ذكروه، نبهوه؛ يرجع، ويجلس يأتي بالتشهد، ثم يقوم، ويكمل صلاته، ويسجد للسهو أيضًا، ولو رجع جهلًا منه؛ فلا حرج عليه، صلاته صحيحة، ويسجد للسهو أيضًا، نعم. المقدم: جزاكم الله خيرًا، إذا تذكر أنه نسي التشهد، أو شك، فهل يسجد سجود السهو؟ الشيخ: إذا شك لا، أما إذا تذكر أنه تركه؛ فإنه يسجد للسهو، أما إذا تردد؛ فالأصل أنه لم يتركه، الأصل أنه .... نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10519/حكم-من-نسي-التشهد-الاوسط-او-شك-انه-نسيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_398/39807.mp3","categories":["سجود السهو"]},{"id":12329,"question":"كيف يمكن للنساء أن يصلين في البيت جماعة إذا جاز ذلك؟","title":"حكم صلاة الجماعة للنساء","answer":"الجواب:  إذا تيسر لهن ذلك؛ فهو أفضل، قد جاء عن أم سلمة، وعائشة أنهما كانتا تصليان بالنساء جماعة، فإذا تيسر لصاحبة البيت أن تصلي بأخواتها، أو بناتها، أو خادماتها فهذا طيب، تقوم وسطهن، يصففن عن يمينها، وعن شمالها، وهي وسطهن، ترفع صوتها بالقراءة والتكبير حتى يتعلم الجميع، يستفيد الجميع. المقدم: جزاكم الله خيرًا، وأحسن إليكم إذًا توصون أم البنات أن تفعل ذلك في بيتها سماحة الشيخ؟ الشيخ: نعم، .... نوصي إذا كانت عندها علم، وإن كان البنات أعلم منها، تتقدم العالمة منهن، أو أخوات .. فالمقصود يؤمهن أقرؤهن وأعلمهن. المقدم: طيب إذًا: لا يرى سماحتكم بأسًا في صلاة جماعة النساء؟ الشيخ: لا، مستحب، إذا تيسر ذلك فمستحب، لما فيه من الفائدة العظيمة، والأجر العظيم. المقدم: الله أكبر، جزاكم الله خيرًا، بعض إخوانكم لا يرون ذلك سماحة الشيخ، فما هو توجيهكم؟ الشيخ: لا، الصواب: أنه لا بأس به، لعموم الأدلة، ولفعل عائشة وأم سلمة.  المقدم: بارك الله فيكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10517/حكم-صلاة-الجماعة-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_398/39805.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12331,"question":"يقول: في أحد الأيام دخلت إلى المسجد في صلاة المغرب، فوجدت نفسي مسبوقًا بركعة، وحدث للإمام سهو بعد التشهد الأول، وبعد التشهد الثاني سجد الإمام للسهو، وسجدت معه، وبعد السلام قمت، وصليت الركعة التي قد سبقني الإمام فيها، وقرأت التشهد، وسلمت، وبعد أن خرجت من المسجد قال لي أحد المصلين: بأن صلاتي باطلة؛ لأنني بعد أن صليت الركعة التي سبقت فيها لم أسجد للسهو، فهل صلاتي باطلة حقًا؟ أرجو الإفادة، جزاكم الله خيرًا.","title":"حكم اكتفاء المسبوق بسجود السهو مع الإمام","answer":"الجواب:  صلاتك صحيحة، وهذه الفتوى لا أساس لها، وقد سجدت مع إمامك متابعة له، والحمد لله، أما أنت فليس عليك سجود، أما لو كان الإمام لم يسجد إلا بعد السلام، ولم تسجد معه؛ فإنه يشرع لك أن تسجد بعد قضاء ما عليك؛ لأنك لم تسجد مع الإمام، أما أنت فقد سجدت مع الإمام، وانتهى الموضوع، والحمد لله، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10524/حكم-اكتفاء-المسبوق-بسجود-السهو-مع-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_454/45404.mp3","categories":["سجود السهو"]},{"id":12332,"question":"يقول: في بعض الأحيان أبي يلعب الورقة، ويؤخر الصلاة، فهل في ذلك إثم؟","title":"حكم تأخير الصلاة بسبب لعب الورق","answer":"الجواب:  نعم، يجب عليه أن يصلي مع المسلمين، ويحذر التساهل في ذلك؛ فإن الجماعة واجبة على المسلم، فإذا سمع النداء؛ وجب عليه أن يجيب النداء، وأن يذهب ويصلي مع الناس، فإذا صلى وحده؛ أثم. فالواجب عليه أن يتقي الله، وأن يصلي مع المسلمين، وألا يتساهل في الجماعة، لا بلعب الورق، ولا غيره، ولعب الورق منكر، ومن آلات الملاهي، فالواجب ترك اللعب والقيام إلى الصلاة، هذا الواجب على أبيك، وعلى غيره، وعليك أن تنصحه كثيرًا، وتستمر في ذلك، وتصبر على النصيحة؛ لعل الله يهديه بأسبابك، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10527/حكم-تاخير-الصلاة-بسبب-لعب-الورق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_454/45405.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12344,"question":"إذا دخلت المسجد، أو أي محل، ووجدت شخصًا واحدًا يصلي، فهل يجوز لي الدخول معه ليكون الإمام وهو لم ينو أن يؤم أحدًا، بل نيته أن يصلي منفردًا؟  وجهوني جزاكم الله خيرًا.","title":"حكم الائتمام بمن يصلي منفرداً","answer":"الجواب:  لا حرج إذا دخلت وأنت لم تصل، ووجدت إنسانًا يصلي أن يكون إمامًا لك، وأن تصلي معه حتى يحصل لكما فضل الجماعة، لقول النبي ﷺ -لما رأى رجلًا دخل بعد انتهاء الصلاة-: من يتصدق على هذا؛ فيصل معه. والمقصود فضل الجماعة؛ ولأنه ﷺ كان يصلي في الليل، فقام ابن عباس وصف عن يساره، فأداره عن يمينه، وصلى به؛ فدل ذلك على أن التماس الجماعة في النافلة والفريضة أمر مطلوب، التهجد بالليل الفريضة التي جئت وقد فاتتك الجماعة، ووجدت إنسانًا يصلي، أو جماعة تصلي معه، وتكون عن يمين الإمام، فإذا كان واحدًا تكون عن يمينه، نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10547/حكم-الاىتمام-بمن-يصلي-منفردا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39906.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12350,"question":"المستمع حسن محمد علي البارقي بعث يقول: نحن جماعة في مزرعة، والمسجد يبعد عنا شيئًا بسيطًا، ونجتمع على فرش ونصلي، هل صلاتنا جائزة ونحن نسمع النداء من المسجد؟ جزاكم الله خيرًا.","title":"حكم صلاة الجماعة على من يسمع النداء","answer":"الجواب:  الواجب عليكم أن تصلوا مع الجماعة، إذا كنتم تسمعون النداء العادي بدون مكبرات النداء العادي، سماع النداء بالصوت المعتاد في وقت الهدوء؛ فعليكم أن تصلوا مع الناس، أما إذا كان بعيدًا، ما تسمعون إلا بالمكبر لبعده، فلا يلزمكم إلا إذا تيسر لكم الذهاب؛ فهو أفضل لكم، كونكم تؤدونها مع الجماعة أفضل لكم، لكن لا يلزمكم إلا إذا كان قريبًا منكم، تسمعون صوت النداء بغير مكبر، في الأوقات السليمة من الأشياء التي تمنع الصوت، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10558/حكم-صلاة-الجماعة-على-من-يسمع-النداء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39916.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12361,"question":"يسأل ما حكم صلاة من به سلس البول إمامًا؟","title":"حكم إمامة من به سلس البول","answer":"الجواب:  الأحوط له ألا يصلي بالناس؛ خروجًا من الخلاف إذا كان إمامًا، وهو صاحب سلس؛ فالأحوط له أن يعتذر، فإن صلى بهم؛ صحت صلاته -إن شاء الله- يتوضأ لكل صلاة، لكن الأحوط أنه يعتذر؛ لأن بعض أهل العلم يرى أنه لا تصح صلاته إمامًا يعني، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10579/حكم-امامة-من-به-سلس-البول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_400/40017.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12363,"question":"جزاكم الله خيرًا، وأحسن إليكم يقول: إذا جاء رجل في أثناء الصلاة متأخرًا عن بعضها، وبعدما سلم الإمام لانتهاء الصلاة؛ وقف المتأخر لإكمال الباقي عليه، ولكنه قام مستعجلًا، وقبل انتهاء الإمام من التسليمة الثانية، بل قام بعد التسليمة الأولى، وهذا يتكرر من بعض الناس -هداهم الله- فما الحكم في ذلك؟","title":"حكم قيام المؤتم لقضاء الصلاة قبل أن يسلم الإمام","answer":"الجواب:  إذا قام يقضي قبل التسليمة الثانية فقد أخطأ؛ لأن الصواب أن التسليمة الثانية لا بد منها، ذهب جمهور أهل العلم: إلى أن التسليمة الأولى تكفي، ولكن الأحاديث الصحيحة تدل على أنه لابد من التسليمة الثانية، فإذا قام قبل أن يسلم الإمام التسليمة الثانية؛ فقد ترك أمرًا مفترضًا، وهو الجلوس حتى يسلم إمامه، فالذي ينبغي أن يقضي الصلاة، أن يعيد الصلاة؛ خروجًا من الخلاف، واحتياطًا لدينه. المقدم: بارك الله فيكم، باعتباره ترك كمال ركن من الأركان؟ الشيخ: ترك واجبًا عليه، وهو الجلوس حتى يسلم إمامه، قام قبل أن يسلم إمامه من صلاته. المقدم: بارك الله فيكم، ومن ترك واجبًا، فما الحكم سماحة الشيخ؟ الشيخ: التعمد يبطل الصلاة، لكن هذا عنده جهل، أو نسيان، لعله يعفى عنه، لكن الأحوط له أن يعيد الصلاة من باب الخروج من الخلاف. المقدم: يعيد الصلاة كاملة؟  الشيخ: نعم، لأن هذا يكون إلا بعد ما طال الفصل، على كل حال يعيدها؛ لأنه لما قام؛ بطلت صلاته، لما قام -على الأرجح- قام بطلت صلاته؛ لأنه قام قبل أن يكمل الإمام الصلاة، والمسبوق ليس له أن يقوم حتى يسلم إمامه، مثلما فعل النبي ﷺ لما سلم عبدالرحمن بن عوف حين صلى معه في غزوة تبوك، لما سلم عبدالرحمن قام النبي يقضي -عليه الصلاة والسلام- فالقضاء يكون بعد سلام الإمام، فهذا من باب الاحتياط، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/10569/حكم-قيام-الموتم-لقضاء-الصلاة-قبل-ان-يسلم-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_400/40007.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12366,"question":"يسأل ما حكم صلاة من به سلس البول إمامًا؟","title":"حكم إمامة من به سلس البول","answer":"الجواب:  الأحوط له ألا يصلي بالناس؛ خروجًا من الخلاف إذا كان إمامًا، وهو صاحب سلس؛ فالأحوط له أن يعتذر، فإن صلى بهم؛ صحت صلاته -إن شاء الله- يتوضأ لكل صلاة، لكن الأحوط أنه يعتذر؛ لأن بعض أهل العلم يرى أنه لا تصح صلاته إمامًا يعني، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10579/حكم-امامة-من-به-سلس-البول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_400/40017.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12368,"question":"جزاكم الله خيرًا، وأحسن إليكم يقول: إذا جاء رجل في أثناء الصلاة متأخرًا عن بعضها، وبعدما سلم الإمام لانتهاء الصلاة؛ وقف المتأخر لإكمال الباقي عليه، ولكنه قام مستعجلًا، وقبل انتهاء الإمام من التسليمة الثانية، بل قام بعد التسليمة الأولى، وهذا يتكرر من بعض الناس -هداهم الله- فما الحكم في ذلك؟","title":"حكم قيام المؤتم لقضاء الصلاة قبل أن يسلم الإمام","answer":"الجواب:  إذا قام يقضي قبل التسليمة الثانية فقد أخطأ؛ لأن الصواب أن التسليمة الثانية لا بد منها، ذهب جمهور أهل العلم: إلى أن التسليمة الأولى تكفي، ولكن الأحاديث الصحيحة تدل على أنه لابد من التسليمة الثانية، فإذا قام قبل أن يسلم الإمام التسليمة الثانية؛ فقد ترك أمرًا مفترضًا، وهو الجلوس حتى يسلم إمامه، فالذي ينبغي أن يقضي الصلاة، أن يعيد الصلاة؛ خروجًا من الخلاف، واحتياطًا لدينه. المقدم: بارك الله فيكم، باعتباره ترك كمال ركن من الأركان؟ الشيخ: ترك واجبًا عليه، وهو الجلوس حتى يسلم إمامه، قام قبل أن يسلم إمامه من صلاته. المقدم: بارك الله فيكم، ومن ترك واجبًا، فما الحكم سماحة الشيخ؟ الشيخ: التعمد يبطل الصلاة، لكن هذا عنده جهل، أو نسيان، لعله يعفى عنه، لكن الأحوط له أن يعيد الصلاة من باب الخروج من الخلاف. المقدم: يعيد الصلاة كاملة؟  الشيخ: نعم، لأن هذا يكون إلا بعد ما طال الفصل، على كل حال يعيدها؛ لأنه لما قام؛ بطلت صلاته، لما قام -على الأرجح- قام بطلت صلاته؛ لأنه قام قبل أن يكمل الإمام الصلاة، والمسبوق ليس له أن يقوم حتى يسلم إمامه، مثلما فعل النبي ﷺ لما سلم عبدالرحمن بن عوف حين صلى معه في غزوة تبوك، لما سلم عبدالرحمن قام النبي يقضي -عليه الصلاة والسلام- فالقضاء يكون بعد سلام الإمام، فهذا من باب الاحتياط، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/10569/حكم-قيام-الموتم-لقضاء-الصلاة-قبل-ان-يسلم-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_400/40007.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12386,"question":"يقول: إنني أعمل مزارعًا، والمزرعة تبعد عن المسجد، ولا أستطيع صلاة الجماعة، فبماذا توجهونني؟ جزاكم الله خيرًا.","title":"المسافة التي تجب بها صلاة الجماعة","answer":"الجواب:  إذا كنت بعيدًا لا تسمع النداء؛ فصل في المزرعة، والحمد لله، أما إذا كنت قريبًا تسمع النداء العادي، إذا أذن؛ وجب عليك أن تصلي مع الجماعة، أما صوت المكبر؛ فهذا لا يتعلق به الحكم؛ لأنه يسمع من بعيد، لكن إذا كنت تسمع النداء بغير المكبر عند هدوء الأصوات، وعدم الموانع؛ فالواجب عليك البدار، وتصلي مع الناس إذا كنت لا تخشى على المحل الخطر .... وتصلي مع الجماعة، ولا حرج عليك في ترك الصلاة إذا كنت لا تسمع النداء، بل صل في محلك، وهكذا لو كنت في محل تخشى عليه إذا ذهبت، فإنك تصلي فيه، تصلي فيه؛ حفاظًا له، وحذرًا من الخطر إذا لم يكن فيه من يصونه. أما إذا كنت تستطيع إغلاق الأبواب، أو وجود من يحرسه، فالمقصود إذا كان لا خطر الواجب عليك أن تصلي مع الجماعة إذا سمعت النداء، إذا كنت تسمع النداء في الأوقات التي ليس فيها ما يمنع صوت النداء، أما صوت المكبر فهذا قد يسمع من بعيد، لا يتعلق به حكم، الحكم بالصوت العادي عند هدوء الأصوات، وعدم وجود الموانع، فالواجب عليك السعي، وأن تؤدي الصلاة مع المسلمين، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10587/المسافة-التي-تجب-بها-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_401/40106.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12411,"question":"يسأل عن الأذكار التي يقولها المسلم في سجود السهو؟","title":"ما الأذكار المشروعة في سجود السهو؟","answer":"الجواب:  سجود السهو مثل سجود الصلاة، يذكر فيه ما يقول في سجود الصلاة: (سبحان ربي الأعلى، سبحان ربي الأعلى، سبحانك اللهم، ربنا وبحمدك، اللهم اغفر لي، سبوح قدوس رب الملائكة والروح، اللهم لك سجدت، وبك آمنت، ولك أسلمت، سجد وجهي للذي خلقه، وصوره، وشق سمعه وبصره، بحوله وقوته، تبارك الله أحسن الخالقين) كل هذا يقال في سجود الصلاة، يقوله في سجود التلاوة، وفي سجود السهو، سواء سواء، سجود الصلاة، سجود التلاوة، سجود السهو، سجود الشكر، كلها يقال فيها هذا الذكر: (سبحان ربي الأعلى، سبحان ربي الأعلى، سبحان ربي الأعلى، سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، سبوح قدوس رب الملائكة والروح، سبحان ذي الجبروت والملكوت والكبريا والعظمة، اللهم لك سجدت، وبك آمنت، ولك أسلمت، سجد وجهي للذي خلقه وصوره، وشق سمعه وبصره، بحوله وقوته، تبارك الله أحسن الخالقين).  ويدعو في السجود أيضًا، يدعو بما تيسر من الدعاء؛ لقول النبي ﷺ: أقرب ما يكون العبد من ربه وهو ساجد؛ فأكثروا الدعاء. وقوله ﷺ: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء، فقمن أن يستجاب لكم يعني: حري أن يستجاب لكم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10618/ما-الاذكار-المشروعة-في-سجود-السهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40206.mp3","categories":["سجود التلاوة والشكر","سجود السهو","الأدعية والأذكار"]},{"id":12429,"question":"من مكة المكرمة رسالة بعث بها مستمع يقول: (س. ع) يقول: أنا أبلغ من العمر ثلاثين عامًا، ومتمتع بصحة جيدة، والحمد لله، توفي والدي منذ ست عشرة سنة، وبسبب وفاته أصابتني حالة نفسية سيئة، اعتزلت الناس على أثرها، ولم أعد أخرج من المنزل أبدًا، وأنا دائم المحافظة على الصلاة في أوقاتها، لكني أصلي في المنزل، وسؤالي: هل يجوز لي الصلاة في البيت، وحالتي الصحية ما ذكرت؟ وهل علي ذنب إذا صليت في البيت؟ جزاكم الله خيرًا.","title":"حكم من يصلي في بيته بسبب المرض النفسي","answer":"الجواب:  يلزمك الصلاة مع المسلمين في المساجد إلا بعذر شرعي، كالمرض الذي يمنعك من الصلاة، وإلا التذكر.. موت فلان، أو موت فلان، أبيك أو غيره لا يمنع، الواجب عليك أن تصلي مع المسلمين في المساجد، ويشرع لك الدعاء لوالدك بالمغفرة والرحمة، والحمد لله، وعليك التوبة مما فعلت، التوبة إلى الله، والندم، نعم.","link":"https://binbaz.org.sa/fatwas/10635/حكم-من-يصلي-في-بيته-بسبب-المرض-النفسي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_403/40304.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12430,"question":"من الخرج رسالة بعث بها المستمع جبريل أحمد حسن يقول: ما الحكم في شخص، أو أشخاص لا يسمعون الأذان إلا من خلال الإذاعة، أو يعرفون موعد الأذان من النتائج المدونة؟ فماذا يفعلون في صلاة القيام في شهر رمضان، علمًا بأن المسجد الموجود في المكان يبعد عن العمل حوالي ثلاثة كيلو؟","title":"حكم الصلاة في مكان العمل لبعده عن المسجد","answer":"الجواب:  يصلون في مكانهم، والحمد لله، بعد صلاة العشاء إذا صلوا العشاء، صلوا ما يسر الله لهم من القيام، ولا حاجة إلى أن يذهبوا المسجد البعيد، يصلون في مكانهم، والحمد لله، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/10636/حكم-الصلاة-في-مكان-العمل-لبعده-عن-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_403/40305.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12452,"question":"يسأل ويقول: ما رأي سماحتكم فيمن يتخذون من العمل وسيلة لترك صلاة الجماعة؟ أو من يتخذون من الاختبارات، والامتحانات المدرسية؛ وسيلة لإفطار شهر رمضان؟","title":"حكم ترك الجماعة بحجة العمل والإفطار بحجة الاختبارات","answer":"الجواب:  لا يجوز للمسلم أن يحتج بالعمل على ترك الجماعة، ولا بالاختبارات على ترك الجماعة، أو على الفطر في رمضان، بل الواجب على المسلمين أن يقوموا بالواجب، الصلاة في الجماعة، وصيام رمضان، وأن يعدوا للاختبار ما يلزم في الليل، أو ينقل الاختبار من رمضان إلى شوال، أو قبل رمضان في شعبان.  أما جعل الاختبارات في رمضان فهذا ليس بطيب، ولا ينبغي للمسؤولين أن يجعلوه في رمضان، بل ينبغي لهم أن يعينوا الطلبة على ما ينفعهم في دينهم ودنياهم. وهكذا الرئاسة العامة لتعليم البنات، كلهم الواجب عليهم أن يعينوا أبناءهم الطلبة، وبناتهم الطالبات على طاعة الله ورسوله، والصيام لاسيما في أيام القيظ، والأيام الطويلة يشق عليهم معه الاختبار.  فالواجب أن يقدم، أو يؤخر من باب الإعانة على الخير، ومن باب التعاون على البر والتقوى، وبكل حال فليس له أن يفطر من أجل الاختبار، بل يستعد في الليل ولا يفطر، وعلى المسؤولين أن يقدموا الاختبار، أو يؤخروه عن رمضان، لكن متى بلي الطالب بذلك ولم يؤخر الاختبار؛ فإنه لا يستبيح الفطر بذلك، بل يستعد في الليل بما يلزم من الاختبار، ويعينه الله وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. فالواجب عدم التساهل، وأن يعمل كل ما يستطيع حتى ينجح -إن شاء الله- ولا يقع فيما حرم الله، وسوف يعينه الله إذا صدق في ذلك، وسوف يسهل الله أمره في نجاحه وسلامته، وعلى المسؤولين -كما تقدم- أن يتقوا الله في الطلبة والطالبات، وأن يراعوا ظروفهم، وأن يعينوهم على الخير، وأن يقدموا الاختبار قبل رمضان، أو يؤخروه عن رمضان في جميع السنوات، هذا هو الواجب عليهم، نعم؛ لأن الله يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] والنبي ﷺ، يقول: والله في عون العبد ما كان العبد في عون أخيه نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10657/حكم-ترك-الجماعة-بحجة-العمل-والافطار-بحجة-الاختبارات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_456/45606.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12472,"question":"المستمع أحمد عبدالرحيم عمر من القاهرة في جمهورية مصر العربية، بعث رسالة وضمنها جمعًا من الأسئلة، في أحد أسئلته يقول: في صلاة العصر لم يجلس الإمام للتشهد الأوسط، فنبهه المصلون بسبحان الله، فبعد أن قام للركعة الثالثة؛ رجع وجلس للتشهد، وبعد التشهد الأخير سجد سجدتي سهو وسلم، فحصل بعض الخلافات في المسجد، البعض يقول: صلاته صحيحة، والآخر يقول: غير صحيحة؛لأنه رجع من فرض إلى سنة، وقام بعض المصلين لإعادة الصلاة، فما رأي سماحتكم، ونرجوا الإفادة عن حالات السهو، ومتى يكون سجود السهو قبل التسليم، ومتى يكون بعده؟ جزاكم الله خيرًا.","title":"حكم من ترك التشهد الأوسط ثم رجع وأتى به","answer":"الجواب:  إذا قام الإمام عن التشهد الأول ناسيًا، ثم نبه، وتنبه، ورجع؛ فلا حرج، وعلى المأمومين أن يرجعوا، ويجلسوا معه، ويأتوا بالتشهد، وعليه أن يصلي، وأن يسجد سجدتين للسهو قبل السلام، وقد فعل ذلك النبي ﷺ فإنه قام في التشهد الأول في بعض صلواته، ثم سجد سجدتين قبل أن يسلم -عليه الصلاة والسلام- لكن إذا كان هذا الإمام استوى قائمًا؛ فالأفضل له عدم الرجوع، لكن لو رجع؛ فلا حرج عليه، وعليهم أن يرجعوا معه، وصلاته صحيحة، وليس في هذا إعادة. أما إن شرع في القراءة؛ فإنه لا يرجع، يستمر، ويسجد للسهو بعد فراغه من التشهد والدعاء، يسجد للسهو قبل أن يسلم كما فعل النبي -عليه الصلاة والسلام- فلو رجع جاهلًا بالحكم، ولو قد شرع في القراءة جاهلًا بالحكم، ورجع؛ صلاته صحيحة، يعذر بالجهل، وعليهم أن يرجعوا معه، فيتشهدوا، ثم يقوموا معه إذا قام. والأصل في هذه المسائل أن الواجب على المأمومين التأسي بالإمام، والاقتداء به، وعدم المخالفة إلا بيقين، يعلمون أنه لا يجوز فيه المتابعة، كالذي قام لخامسة، وهم يعلمون أنها خامسة لا يقومون معه، أو قام لرابعة في المغرب، وهم يعلمون أنها رابعة لا يقومون معه، أو قام لثالثة في الفجر، أو في الجمعة، وهم يعلمون أنها ثالثة لا يقومون، أما الذي لا يعلم فإنه يتابع إمامه الذي لا يعلم، يتابع إمامه. أما سجود السهو فإنه يكون قبل السلام، هذا هو السنة قبل السلام؛ لأنه من الصلاة إلا في حالتين: إحداهما: إذا سلم عن نقص ركعة، أو أكثر؛ فإنه يسجد للسهو بعد السلام، هذا هو الأفضل، يسجد بعد السلام؛ لأن النبي ﷺ لما سلم عن نقص ركعتين في حديث ذي اليدين من حديث أبي هريرة؛ سجد بعد السلام، وهكذا في حديث عمران لما سلم عن نقص ركعة؛ كمل صلاته، وسجد بعد السلام، هذا هو الأفضل، وإن سجد قبل السلام؛ أجزأ، والحمد لله. الحال الثاني: إذا بنى على غالب ظنه، إذا تحرى الصواب، واجتهد، وبنى على غالب ظنه، فإنه يسجد بعد السلام، هذا هو الأفضل؛ لحديث ابن مسعود  في الصحيحين أن النبي ﷺ قال : إذا شك أحدكم في الصلاة؛ فليتحر الصواب، فليتم عليه، ثم ليسلم، ثم يسجد سجدتين فجعل السجود بعد السلام إذا كان الإمام بنى على غالب ظنه، تحرى الصواب، واجتهد وكمل، فإنه يسجد سجدتين بعد السلام، أما البقية فتكون قبل السلام، هذا هو الأفضل.  وفي أي حال لو سجد بعد السلام، أو قبل السلام أجزأ، الأمر في هذا واسع، فلو صلى بعد السلام في سجود محله قبل السلام؛ أجزأ، ولو سجد قبل السلام في سجود محله بعد السلام؛ أجزأ، إنما هي أفضلية، فلا ينبغي التشديد في هذا، بل ينبغي التسامح، كما بين ذلك أهل العلم -رحمة الله عليهم-حسب ما جاء في النصوص من سجوده -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10673/حكم-من-ترك-التشهد-الاوسط-ثم-رجع-واتى-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_404/40414.mp3","categories":["سجود السهو"]},{"id":12474,"question":"يقول: إذا دخلت مع أحد المصلين في جماعة، ودخل الآخر معنا، ثم دخل آخر، فنرجو من سماحة الشيخ الإفادة الصحيحة لما يفعله الإمام والمصلون في هذه الحالة؟","title":"واجب من اقتدى به شخص وشخصان في الصلاة","answer":"الجواب:  إذا كان المصلي يصلي وحده، ثم جاء إنسان وصف معه يجعله عن يمينه، كما فعل النبي ﷺ مع ابن عباس وغيره، فإن جاء ثانٍ يصير ثالثًا لهم، أخرهم خلفه صاروا خلفه، وهكذا لو جاء ثالث كلهم يصير خلفه، ولهذا لما جاء ابن عباس والنبي ﷺ يصلي في الليل، وصف عن يساره؛ جعله النبي ﷺ عن يمينه، وهكذا ثبت من حديث أنس أنه ﷺ زارهم، وصلى في البيت، وأقام أنسًا عن يمينه، وثبت عنه ﷺ أنه كان يصلي وحده، فجاء جابر -وجبار من الأنصار- فصفا معه، فجعلهما خلفه -عليه الصلاة والسلام- هذا هو السنة، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10675/واجب-من-اقتدى-به-شخص-وشخصان-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_404/40416.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12497,"question":"يقول: أنا تلميذ في الصف الثالث الإعدادي، وأبلغ من العمر الخامسة عشرة، وأحيانًا أصلي بوالدي، وبعض الأصدقاء إمامًا، فهل في هذا شيء، علمًا بأنهم غير متعلمين، ولا يعرفون القراءة؟","title":"حكم إمامة من بلغ الخامسة عشر","answer":"الجواب:  لا حرج في ذلك؛ لقول النبي ﷺ: يؤم القوم أقرؤهم لكتاب الله فإذا صليت بهم النافلة، أو بالليل، أو الفجر إذا فاتتك مع أهل المسجد؛ فلا حرج أن تؤمهم، وكان عمرو بن سلمة يؤم جماعته وهو ابن سبع سنين؛ لأنه كان أقرأهم. فالمقصود: أنك إذا كنت أقرأهم، فأنت أولى بالإمامة، لكن ليس لك أن تصلي في البيت، بل يجب عليك أن تصلي مع المسلمين في المسجد، وعلى أبيك، وعلى أهل البيت من الرجال، يجب أن يصلوا في المساجد، لكن في البيت النافلة التهجد من الليل صلاة الضحى إذا صليت بهم، إذا قدر أن الصلاة فاتتك في المسجد، وصليت بهم؛ فلا بأس، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10692/حكم-امامة-من-بلغ-الخامسة-عشر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_406/40603.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12539,"question":"رجل شك في عدد السجدات، وقد كان في ركعة أخرى بعدها، ماذا يفعل؟","title":"حكم الشك في عدد السجدات بعد مضي ركعة أخرى","answer":"الجواب:  إذا شك هل سجد سجدتين، أو ثلاثًا؛ فالأصل أنها سجدتان، ما عليه شيء، أما إذ شك هل سجد سجدة، أو سجدتين؛ فهذا يجعلها سجدة، ويأتي باليقين، يسجد سجدة ثانية، وإذا شك في ذلك بعدما مضت الركعة، وصار في ركعة ثانية؛ يعتبر الركعة الأولى لاغية .. تقوم الأخرى مقامها، ويأتي بركعة زائدة بدل الركعة التي ترك منها السجود، أو شك في السجود الذي تركه منها؛ لأن الواجب أن يأتي بالأركان كاملة عن يقين، فإذا صلى ركعة، ثم في الركعة الثانية بعد الركوع، أو في السجود، حصل عنده شك في الركعة الأولى، هل سجد سجدتين أو واحدة، فإنه يعتبرها واحدة يقينًا، وأن تكون الثانية بدلًا منها، ويأتي بأخرى، ويسجد للسهو، أما لو كان الشك بعد السلام؛ فليس عليه .... إذا كان الشك بعد السلام؛ فإنه لا يلتفت إلى ذلك، وصلاته صحيحة، وليس عليه سجود سهو، ولا غيره؛ لأن العبادة قد تمت وانتهت. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10745/حكم-الشك-في-عدد-السجدات-بعد-مضي-ركعة-اخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_409/40907.mp3","categories":["سجود السهو"]},{"id":12566,"question":"من باحة سلطنة عمان المستمع علي حمود سعيد البادي بعث برسالة ضمنها جمعًا من الأسئلة يقول في أحدها: إذا سهوت في صلاة ما فإنني أعلم أنه يجب علي أن أسجد سجود السهو، فمتى أسجده؟ أفتوني ولكم الأجر.","title":"سجود السهو قبل السلام وبعده","answer":"الجواب:  هذا فيه تفصيل: فإذا سهوت في العدد؛ وجب عليك البناء على اليقين، ويكون السجود قبل السلام، سجدتين قبل أن تسلم، وإذا شككت هل صليت ثنتين، أم ثلاثًا؛ جعلتها ثنتين، وكملت الصلاة، أو سهوت هل صليت ثلاثًا، أم أربعًا في العشاء أو الظهر، أو العصر جعلتها ثلاثًا، وبنيت على اليقين، ثم أتيت بالرابعة، فإذا كملت صلاتك؛ سجدت للسهو سجدتين قبل أن تسلم، أما إن كان السهو نوعًا آخر بأن نسيت التشهد الأول، وقمت إلى الثالثة، ما جلست للتشهد الأول، أو نسيت سبحان ربي الأعلى في السجود، أو نسيت أن تقول سبحان ربي العظيم في الركوع، أو نسيت بعض التكبيرات غير تكبيرة الإحرام، وأنت منفرد، أو إمام فإنك تسجد للسهو قبل السلام سجدتين؛ لأن الرسول ﷺ لما ترك التشهد الأول في بعض صلواته، سجد للسهو قبل أن يسلم سجدتين، عليه الصلاة والسلام.  وهناك أنواع أخرى من السهو لها أحكامها مثل: من زاد ركعة، فهذا يلزمه الرجوع إذا تنبه، أو نبه، فإن لم يرجع بطلت صلاته؛ لأنه زاد زيادة متعمدًا لها، إذا نبهوه، ولم يرجع؛ نبهه اثنان فأكثر، ولم يرجع؛ بطلت صلاته إلا إن يتيقن صواب نفسه، ويعتقد خطأهم، إذا تيقن صواب نفسه، وأن المنبه مخطئ؛ فلا حرج عليه، يكمل، والذين يعتقدون أنه زائد يجلسون، لا يتابعونه؛ فلهم اعتقادهم، وله اعتقاده، فإذا اعتقدوا أنه قام إلى خامسة في الظهر، أو العصر، أو العشاء يجلسون، أو إلى رابعة في المغرب، أو إلى ثالثة في الفجر، أو في الجمعة، يجلسون ولا يتابعونه، فإذا سلم؛ سلموا معه بعد ذلك. أما إذا كان ساهيًا، فلما نبهوه تنبه ورجع؛ فإنه يتشهد، وإذا فرغ من التشهد؛ سجد سجدتين للسهو قبل السلام، أو بعده، وقبله أفضل، وبذلك تتم صلاته في هذا السجود، وتنجبر الصلاة بهذا السجود؛ لأن الرسول ﷺ قال في بعض الأحاديث: إن كان صلى تمامًا؛ كان هذا ترغيمًا للشيطان، وإن كان صلى ناقصًا؛ جبر له صلاته. فالمقصود: أنه إن كان صلى صلاة تامة؛ فهو مأجور على سجود السهو، وفيه إرغام للشيطان، وإن كان النقص؛ كان جابرًا، نعم. وهناك نوع آخر وهو أن يسلم عن نقص، يسلم ثلاث في الظهر، أو العصر، أو العشاء، أو يسلم من ثنتين في المغرب، أو من واحدة في الفجر، ثم ينبه؛ فهذا يقوم، ويكمل، فإذا كمل؛ سلم، ثم سجد للسهو بعد ذلك، يكون سجود السهو بعد ذلك، إذا كان سلم عن نقص، ونبهوه، أو تنبه، ثم قام وكمل؛ فالأفضل أن يكون سجوده بعد السلام؛ لأن الرسول ﷺ لما سها في صلاته، وسلم عن نقص، ونبه؛ كمل صلاته، وسلم، ثم سجد سجدة السهو -عليه الصلاة والسلام- فهذا هو الأفضل في هذه الحال، أن يكون السجود بعد السلام، ولو سجد قبل السلام؛ أجزأ، يعني كونه يتحرى فعل النبي ﷺ ويسجد كما سجد بعد السلام، يكون هذا هو الأفضل. نعم.","link":"https://binbaz.org.sa/fatwas/10778/سجود-السهو-قبل-السلام-وبعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_411/41111.mp3","categories":["سجود السهو"]},{"id":12569,"question":"هل من السنة عندما يقول الإمام للمأمومين في تسوية الصفوف بالصلاة: استووا اعتدلوا يرحمني ويرحمكم الله؟","title":"حكم دعاء الإمام للمأمومين أثناء أمره بتسوية الصفوف","answer":"الجواب:  ما نعلم في هذا بأسًا إذا دعا لهم؛ لأن النبي ﷺ كان يأمرهم بالاستواء، يأمرهم بتعديل الصفوف، يأمرهم بسد الخلل، وإذا دعا ما أعلم في هذا بأسًا، لو قال: غفر الله لنا ولكم، أو رحمنا الله وإياكم، لا أعلم في هذا بأسًا -إن شاء الله- نعم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10769/حكم-دعاء-الامام-للمامومين-اثناء-امره-بتسوية-الصفوف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_411/41104.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12583,"question":"ما حكم الصلاة وراء من يبسمل قبل الفاتحة عند الصلوات الجهرية؟ هل تجوز الصلاة وراءه؟","title":"حكم الصلاة خلف من يجهر بالبسملة في الصلاة الجهرية","answer":"الجواب:  لا بأس بذلك؛ لأن بعض أهل العلم يرى شرعية الجهر بها، فلا حرج في ذلك، ولكن الأفضل الإسرار بها، كان النبي ﷺ يسر بها في الجهرية -عليه الصلاة والسلام- وروي عن بعض الصحابة الجهر بها، فإذا جهر بها بعض الناس؛ يصلى خلفه؛ لأنه قول معروف لبعض أهل العلم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10791/حكم-الصلاة-خلف-من-يجهر-بالبسملة-في-الصلاة-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_412/41207.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12611,"question":"إذا أخطأ الإمام في الصلاة في قراءة سورة ما، ولم يرد عليه أحد من المأمومين، فماذا يفعل؟","title":"حكم الإمام إذا أخطأ في الصلاة ولم يرد عليه","answer":"الجواب:  لا شيء عليه، إذا كانت الفاتحة سليمة، وقرأها سليمة؛ فالباقي لا يضر، نعم.","link":"https://binbaz.org.sa/fatwas/10827/حكم-الامام-اذا-اخطا-في-الصلاة-ولم-يرد-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41415.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12612,"question":"هل تجوز الصلاة خلف إمام مبتدع؟","title":"حكم الصلاة خلف المبتدع","answer":"الجواب:  هذا يختلف إن كانت البدعة مكفرة، مثل المبتدع الذي يدعو إلى الشرك، ويجيز الشرك بالله، هذا لا يصلى خلفه، أما إذا كان مبتدعًا يؤول بعض الصفات، أو يتعاطى الموالد، ولكن ما عنده شرك؛ فهذا يصلى خلفه، إذا دعت الحاجة إلى ذلك كالجمعة، وإذا تيسر غيره، فينبغي أن يصلى خلف غيره. أما إذا كانت بدعته مكفرة، كعبادة القبور، واستغاثة بالأموات هذا لا يصلى خلفه، نسأل الله العافية. المقدم: نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/10822/حكم-الصلاة-خلف-المبتدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41410.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12654,"question":"من مكة المكرمة وادي فاطمة رسالة بعث بها أحد الإخوة المستمعين رمز إلى اسمه بالحروف (م. ح. ح) يقول: رجل يدرك الركعة الثانية مع الإمام في المغرب، وربما الثانية في الفجر، وعلى هذا سوف يكون صلى ثلاث مرات للتشهد في المغرب، ومرتين في الفجر، فماذا يفعل في الجلسة الزائدة؟ وكيف يكون تفصيلها؟ وما حكم من قرأ التشهد فيها؟","title":"حكم جلوس المسبوق مع إمامه للتشهد","answer":"الجواب:  هذه الجلسة متابعة للإمام الجلسة التي يجلسها بعد الركعة الأولى التي أدركها وهي الركعة الثانية في حق الإمام، هذه جلسة تابعة، جلسة تابعة للإمام، يجلس تبعًا للإمام، وهكذا في المغرب في الفجر والمغرب هذه تابعة، وهكذا إذا أدرك ركعة من الظهر، أو العصر، أو العشاء فإنه يجلس بعد ما يصلي الركعة الأولى التي يقضيها، يجلس للتشهد، ثم يقوم فيصلي ثنتين التي فاتته. فالحاصل: أن هذه الركعة التي أدركها مع الإمام في الفجر، أو في المغرب، يجلس فيها جلسة مع الإمام تبعًا للإمام، وإذا قرأ فيها التحيات في التشهد الأول، والصلاة على النبي ﷺ تبعًا للإمام؛ فلا حرج في ذلك، ولو لم يقرأ لا حرج عليه؛ لأن هذه ما هي بجلسة في حقه، ليست في التشهد الأول، ولا في التشهد الأخير، لكن إذا قرأ تبعًا للإمام؛ فهذا حسن -إن شاء الله- ولا يضره، وإنما الواجب عليه الجلسة الأخيرة، التي بعد قضاء الركعة التي فاتته في الفجر، وبعد قضاء الركعتين في المغرب، عليه التشهد الأخير، التشهد الأخير والتشهد الأول بعدما يأتي بركعتين في المغرب في التشهد الأول في التشهد الأول وجلوسه مع الإمام، إنما هو متابعة. وإنما الجلسة التي تلزمه بعد ما يقضي ركعة من المغرب يجلس للتشهد الأول، ثم يصلي الثالثة، ويجلس التشهد الأخير، وفي الفجر يقضي الركعة التي عليه، ويجلس للتشهد الذي يجب عليه، وهو التشهد الذي فيه السلام، هذا واجب عليه. أما جلسته مع الإمام فإنها لا تلزمه إلا متابعة الإمام، يجلس متابعة للإمام، ولا يلزمه فيها قراءة التشهد، لكن إذا قرأه؛ فلا حرج، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10864/حكم-جلوس-المسبوق-مع-امامه-للتشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45806.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12655,"question":"يقول: أحيانًا يصلي الرجل نافلة، ولكنه قد يسهو فيها، فهل يلزمه سجود السهو؟","title":"حكم سجود السهو في صلاة النافلة","answer":"الجواب:  مثل الفريضة. المقدم: كالفريضة؟ الشيخ: كالفريضة نعم، إذا كان نوى ثنتين، ثم جلس بعد الأولى، أو سلم بعد الأولى يكمل يأتي بالثانية، ويسجد للسهو، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10865/حكم-سجود-السهو-في-صلاة-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45807.mp3","categories":["سجود السهو"]},{"id":12656,"question":"يقول: إذا زاد عدد الركعات في الصلاة، أو نقص شيء من ذلك، ولم يسجد سجود السهو، هل الصلاة تكون باطلة؟","title":"حكم صلاة من ترك سجود السهو","answer":"الجواب:  هذا فيه تفصيل: إذا كان عزم على ترك السجود وهو في الصلاة، هذا إذا تعمد ذلك، وهو من يعلم الحكم الشرعي؛ تبطل صلاته، أما إذا كان جاهلًا، أو ناسيًا؛ ما تبطل، صلاته صحيحة. أما إذا كان إنما كمل الصلاة على نية السجود للسهو، ثم نسيه، أو تعمد تركه بعد ذلك بعدما سلم؛ صلاته صحيحة، ويأثم بتركه سجود السهو الواجب عليه؛ لأنه مكمّل لصلاته، ولا تبطل به صلاته؛ لأنه كملها بالسلام، وهذا السجود واجب عليه لإكمال الصلاة، فإن سجد؛ فهو الواجب عليه، وإن لم يسجد؛ أثم، وصلاته صحيحة، وهو آثم. أما إن تركه ساهيًا، أو جاهلًا بالحكم الشرعي؛ فلا شيء عليه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10866/حكم-صلاة-من-ترك-سجود-السهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45808.mp3","categories":["سجود السهو"]},{"id":12667,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع: محمد صالح من جيزان أبو عريش، أخونا له جمع من القضايا من بينها قضية يقول فيها: ما هي موجبات سجود السهو في الصلاة؟ وأرجو التفصيل في هذا الموضوع، جزاكم الله خيرًا.","title":"أسباب سجود السهو","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإن سجود السهو له أسباب، تارة تكون زيادة في الصلاة، وتارة تكون نقصًا، وقد سجد النبي ﷺ للسهو في عدة ... مسائل وقعت له -عليه الصلاة والسلام- سجد للسهو لما ترك التشهد الأول ناسيًا، وقام إلى الثالثة سجد سجدتين قبل أن يسلم، وسجد لما سلم عن نقص، سلم من ثنتين، ثم نبه، وكمل الصلاة، ثم سجد للسهو بعد السلام سجدتين، وسلم من ثلاث، فنبه، ثم كمل صلاته، وسجد سجدتين للسهو بعد السلام، وزاد خامسة في بعض صلواته الرباعية، فنبه بعد السلام، فسجد سجدتين، وقال -عليه الصلاة والسلام-: إنما أنا بشر مثلكم، أنسى كما تنسون، فإذا نسيت؛ فذكروني. فالسجود للسهو يكون إما لنقص، وإما لزيادة -كما سمعت- فإذا زاد ركعة، أو ركوعًا، أو سجودًا ساهيًا؛ فإنه ينبه إذا كان إمامًا، ينبهه المأمومون على سهوه، ويرجع إلى تنبيههم إذا لم يكن عنده يقين فيما فعل، وعليه سجود السهو قبل السلام، أو بعده، والأفضل قبل السلام في جميع صور السهو إلا إذا كان سهوه عن نقص ركعة فأكثر، فإن سجوده يكون بعد السلام أفضل. وهكذا إذا بنى على غالب ظنه؛ فإنه يسجد للسهو بعد السلام أفضل؛ لحديث ابن مسعود  عن النبي ﷺ أنه قال : إذا شك أحدكم في صلاته؛ فليتحر الصواب، فليتم عليه، ثم ليسلم، ثم ليسجد سجدتين بعد السلام. وبهذا يعلم أنه يشرع له سجود السهو، بل يجب عليه إذا فعل ما يبطل عمده الصلاة من زيادة، أو نقص إذا فعله ساهيًا، فإذا ترك سجدة من السجدات، أو ركوعًا، أو ركعة، أو أكثر؛ فإنه ينبه كما تقدم، وعليه أن يرجع إلى الصواب، ويكمل صلاته، ويسجد للسهو قبل السلام في جميع صور السهو إلا في حالين: إحداهما: إذا سلم عن نقص ركعة فأكثر، فإنه يسجد للسهو بعد السلام. والحال الثاني: إذا بنى على غالب ظنه، وأتم الصلاة على غالب ظنه؛ فإنه يكمل، ويسلم، ثم يسجد للسهو سجدتين بعد السلام. أما إذا شك في صلاته، وليس عنده ظن غالب؛ فإنه يبني على اليقين، ثم يسجد للسهو سجدتين قبل أن يسلم، لقوله ﷺ في حديث أبي سعيد: إذا شك أحدكم في صلاته؛ فليبن على الأقل، ثم ليسجد سجدتين قبل أن يسلم فإذا شك هل صلى ثنتين، أو ثلاثًا يجعلهما ثنتين. وإذا شك هل هي ثلاث، أو أربع؛ يجعلها ثلاثًا ويكمل، لهذا الحديث، حديث أبي سعيد: إذا شك أحدكم في صلاته؛ فليبن على ما استيقن، ثم يسجد سجدتين قبل أن يسلم، فإن كان صلى خمسًا؛ شفعن له صلاته، وإن كان صلى تمامًا؛ كان ترغيمًا للشيطان خرجه مسلم في الصحيح. فهذا هو المشروع، بل الواجب على المؤمن والمؤمنة عند السهو، إذا شك في صلاته، ولم يكن له غلبة ظن؛ فإنه يبني على اليقين، يعني: الأقل، ويكمل صلاته على ذلك؛ احتياطًا للصلاة، فإذا شك هل سجد سجدة، أو سجدتين؛ يجعلها سجدة، ويأتي بالسجدة الثانية، ويتم صلاته، وإذا شكها؛ صلى ثنتين، أو ثلاثًا، يجعلهما ثنتين، ويكمل صلاته؛ لأن هذا هو اليقين، وهذا هو الاحتياط للصلاة، ثم إذا انتهى من الصلاة، ولم يبق إلا السلام؛ كبر، وسجد سجدتين للسهو مثل سجوده للصلاة، سجوده السهو مثل سجوده للصلاة سواء، يقول فيها: سبحان ربي الأعلى، سبحان ربي الأعلى، ويدعو فيها مثل سجود الصلاة، سواء بسواء، ثم يسلم. أما إذا كان عنده غلبة الظن، شك هل صلى ثنتين، أم ثلاثًا، لكن غالب ظنه أنها ثلاث، يجعلها ثلاثًا، ويكمل، ويسلم، ثم يسجد سجدتين بعد السلام، إلا إذا كان إمامًا، ونبهه المأموم؛ فإنه يرجح إلى تنبيههم، ويترك ظنه، يرجع إلى تنبيههم؛ لأن تنبيههم أوثق من ظنه. أما إذا سها عن شيء مستحب، ليس بواجب؛ فلا يلزمه سجود السهو، مثل: سها عن رفع اليدين عند الإحرام، أو عند الركوع، أو سها فتورك في التشهد الأول، أو سها فافترش في التشهد الأخير من الرباعية، أو الثلاثية، كل هذا لا يوجب سجود السهو؛ لأنه ليس بواجب، ولو سجد؛ فلا بأس للسهو، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10877/اسباب-سجود-السهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_416/41601.mp3","categories":["سجود السهو"]},{"id":12682,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: أخوكم في الله قاعود محمد سليمان مصري ويعمل في الرياض، طريق الخرج، أخونا يقول: أعمل حارسًا في مستودع لإحدى الشركات، وظروف العمل تضطرني للتواجد أربعة وعشرين ساعة، حيث لا يوجد بديل غيري، والمستودع الذي أعمل فيه لا يوجد أحد يعمل فيه غيري، وأضطر للصلاة بمفردي حيث لا يوجد مسجد قريب مني، فهل تعتبر صلاتي صحيحة، وحالي ما ذكرت جزاكم الله خيرًا؟","title":"حكم صلاة الجماعة لمن يعمل حارساً","answer":"الجواب:  نعم، لا بأس صلاتك صحيحة، والحمد لله، وأنت معذور، والحمد لله حتى ولو كان قربك مسجد، إذا كان ذهابك فيه خطر على المستودع؛ تصلي وحدك؛ لأنك معذور، أما إذا كان لا خطر، وبقربك المسجد، تسمع الأذان؛ وجب عليك أن تصليها في المسجد، أما إذا كان الذين جعلوك لا يرضون بذلك، ويخشون على مستودعهم؛ فالحارس معذور إذا صلى في محله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10892/حكم-صلاة-الجماعة-لمن-يعمل-حارسا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_417/41710.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12691,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجبيل، باعثها المستمع (ع. م أبو مصطفى)، أخونا يسأل ويقول: في الفقه المالكي وفي كتاب فتح الباري على صحيح البخاري يقول: لا تجوز صلاة الصبي إلا لمثله في الإمامة، وكذلك لا تجوز الصلاة خلف متنفل أو مسبوق، ما هو الحكم في ذلك، وما هو توجيهكم حيال ما ورد؟ جزاكم الله خيرًا.","title":"حكم صلاة المفترض خلف المتنفل وحكم إمامة الصبي","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فقد صحت الأحاديث عن رسول الله -عليه الصلاة والسلام- بأن الصبيان مأمورون بالصلاة إذا بلغوا سبعًا، ويضربون عليها إذا بلغوا عشرًا، وثبت عنه -عليه الصلاة والسلام- أنه صلى بالناس -عليه الصلاة والسلام- صلاة الخوف ركعتين، فرضه، وفرض الجميع، وفرض من خلفه، وصلى بالطائفة الأخرى ركعتين، نافلة له، وهي لهم فريضة فدل ذلك على أنه لا حرج أن يصلي المفترض خلف المتنفل، وثبت عن معاذ : أنه كان يصلي مع النبي ﷺ صلاة العشاء فرضه، ثم يرجع إلى قومه فيصلي بهم تلك الصلاة، فهي له نافلة، ولهم فرض وفي صحيح البخاري عن عمرو بن سلمة الجرمي : أنه كان يؤم جماعته وهو ابن سبع سنين؛ لأنه كان أكثرهم قرآنًا عملًا بقوله ﷺ: إذا حضرت الصلاة فليؤذن لكم أحدكم وليؤمكم أكثركم قرآنًا. وكان عمرو أكثرهم قرآنًا، فكان يصلي بهم، فدل ذلك على أنه لا حرج أن يؤم الصبي الكبار إذا كان ابن سبع فأكثر، وكان يعقل الصلاة، وكان أكثر ممن خلفه قرآنًا لقوله ﷺ: يؤم القوم أقرؤهم لكتاب الله، فإن كانوا في القراءة سواء فأعلمهم بالسنة، فإن كانوا في السنة سواء فأقدمهم هجرة، فإن كانوا في الهجرة سواء، فأقدمهم إسلامًا وفي لفظ: فأكبرهم سنًا وفي الحديث عن عمرو بن سلمة عن أبيه أن النبي -عليه الصلاة والسلام- قال: إذا حضرت الصلاة فليؤمكم أكثركم قرآنًا. فالمقصود: أن الصبي إذا كان أكثر من غيره قرآنًا، وكان يعقل الصلاة، ويؤديها كما ينبغي، فلا حرج أن يؤم الكبار لهذا الحديث الصحيح لقصة عمرو بن سلمة، ولعموم قوله ﷺ: يؤم القوم أقرؤهم لكتاب الله الحديث. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10901/حكم-صلاة-المفترض-خلف-المتنفل-وحكم-امامة-الصبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_418/41801.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12692,"question":"ما حكم صلاة الأطفال دون السابعة في الصفوف الأمامية، ويزاحمون المصلين، وهذا مما يجعل دائمًا أن يكون هناك فرجة في الصفوف، وأن يحدثوا بعض الحركات في الصلاة، جزاكم الله خيرًا؟","title":"حكم صلاة الصبي دون السبع في المسجد","answer":"الجواب:  الأطفال الذين هم دون السبع ليس لهم صلاة ولا يؤمرون بالصلاة، والمشروع لآبائهم إبقاؤهم في البيوت حتى لا يشوشوا على المصلين، هذا هو المشروع، لكن لو وجد أحدهم من بين الصفوف لم يضر الصف، وعلى من حوله أن يرشده إلى الهدوء حتى لا يؤذي أحدًا ولا يؤذى، أما آباؤهم فالمشروع لهم أن يحفظوهم في البيوت وأن لا يحضروهم المساجد حتى لا يشوشوا على الناس ويقطعوا الصفوف، ومتى وجد أحد منهم في الصف ودعت الحاجة إلى بقائه فإنه لا يضر الصف، ويكون بمثابة الكرسي أو العمود أو ما أشبه ذلك إذا دعت الحاجة إلى وجوده في الصف، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10902/حكم-صلاة-الصبي-دون-السبع-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_418/41802.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12740,"question":"أنا مقيم في مزرعة تبعد عن المسجد أكثر من ستة ونصف كيلو، هل يجوز لي أن أصلي في المزرعة؟","title":"حكم صلاة الجماعة لمن هو بعيد عن المسجد","answer":"الجواب:  نعم يجوز؛ لأنك بعيد، صل بمن معك، صل أنت ومن معك من العمال في المزرعة، والمشروع لك أن تهيأ مسجدًا في هذا، تصلون فيه أنت ومن يحضر معك، وإن تكلفت وذهبت إلى المسجد فأنت على خير عظيم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10954/حكم-صلاة-الجماعة-لمن-هو-بعيد-عن-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_418/41811.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12747,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع: عبدالله بابكر بشارة من بادية الجهراء، أخونا له سؤال يقول فيه: إنني أعمل بالبادية مع كفيلي، لكنه أمي، وحافظ عددًا من قصار السور، ولكنه لا يتقن قراءتها، وسؤالي أنه يصر على أن يكون إمامًا، بينما أشعر أنني في القراءة أحسن منه، فما هو توجيهكم جزاكم الله خيرًا؟","title":"حكم الصلاة خلف من لا يحسن القراءة","answer":"الجواب:  لا حرج، صل خلفه، والحمد لله، إذا كان يتقن الفاتحة، فإن كان لا يتقن الفاتحة؛ فانصحه حتى يقدم من يتقنها، أنت ومن معك من الإخوان تنصحونه، أما إذا كان يتقن الفاتحة، فالحمد لله، ولو حصل منه بعض الغلط في السور الأخرى، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10961/حكم-الصلاة-خلف-من-لا-يحسن-القراءة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_418/41818.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12771,"question":"أنا في جوار مسجد صغير يجتمع الناس فيه على فريضة العصر والمغرب، وبعد ذلك لا يجتمع فيه سوى اثنين أو ثلاثة، هل يجوز لي أن أذهب إلى مسجد آخر توجد به جماعات كبيرة، وترك الأذان، والإقامة في هذا المسجد الصغير؟","title":"حكم الصلاة في مسجد لا يصلى فيه إلا العصر والمغرب","answer":"الجواب:  الأقرب -والله أعلم- أنك تبقى في المسجد؛ لأن هذا من أسباب جمع الناس، والصلاة في المسجد، وعدم إهماله إذا كنت أنت المؤذن؛ فتؤذن فيه، وتقيم فيه بمن حضر مع الإمام، والحمد لله، إلا إذا كانت المساجد التي فيها الجم الغفير كثيرة، ولا حاجة إلى هذا المسجد، فلا مانع من إغلاقه، وأن تصلي في المساجد التي حوله التي فيها الجماعة كثيرة؛ لأن هذا المسجد حينئذ لا محل له، فعليك أن تراجع الأوقاف، وأهل العلم في بلدك؛ حتى ينظروا في الأمر، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10985/حكم-الصلاة-في-مسجد-لا-يصلى-فيه-الا-العصر-والمغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41920.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12773,"question":"دخلت المسجد، وقد انتهى الإمام من الصلاة، فهل يجوز لي أن أصلي خلف مأموم من الجماعة؟","title":"حكم الائتمام بالمسبوق","answer":"الجواب:  إن صليت خلفه وهو يقضي؛ صار إمامًا لك؛ فلا بأس، وإن صليت وحدك؛ فلا بأس، الأمر واسع والحمد لله، نعم. المقدم: الحمد لله، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10987/حكم-الاىتمام-بالمسبوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41922.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12810,"question":"يسأل ويقول: إذا حضر المصلي ووجد الصف الأول كاملًا، وليس معه أحد، ومن المعلوم أنه يأخذ معه واحدًا من الصف الذي أمامه، فهل يأخذ من خلف الإمام، أو من نهاية الصف؟ وكما أشاهد الكثير إذا كان الصف كاملًا، وحضر قليل أشاهدهم يصفون، إما على يمين الإمام، أو على يساره من بعد الصف، فما الحكم جزاكم الله خيرًا؟","title":"هل يجذب مصلٍ من الصف إذا لم يوجد من يصف معه؟","answer":"الجواب: إذا كان الصف كاملًا فليس لك أن تأخذ أحدًا، هذا هو الصواب، والحديث الوارد في ذلك ضعيف: ألا دخلت معهم، أو جررت رجلًا هذا ضعيف، لكن تنتظر لعله يأتي أحد يصف معك، أو تتقدم وتصلي مع الإمام عن يمينه، كل هذا لا حرج فيه، وليس لك أن تأخذ أحدًا من الصف؛ لأنك تفتح فرجة في الصف، والرسول ﷺ أمر بسد الخلل في الصفوف، فعليك أن تلتمس فرجة لعلك تجد ولا تعجل، فإن لم تجد فاصبر حتى يأتي أحد معك، ولو فاتت الركعة، أو تقدم وصف مع الإمام عن يمين الإمام. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11024/هل-يجذب-مصل-من-الصف-اذا-لم-يوجد-من-يصف-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_462/46215.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12860,"question":"من المستمع: صلاح محمد كرار بعث يسأل ويقول: في قريتنا لا يوجد مسجد لأداء الصلوات جماعة، ولكننا نقوم بأداء صلاة المغرب والعشاء في جماعة بالقرب من مساكننا، فهل يجوز ذلك؟","title":"حكم صلاة الجماعة إذا لم يكن هناك مسجد","answer":"الجواب: نعم، هذا الواجب عليكم أن تصلوا جماعة في منزل أحدكم، أو في قرب منازلكم؛ حتى يتيسر مكان لكم للصلاة، والواجب عليكم أن تتعاونوا في إيجاد مسجد، ولو بالشراء، شراء الأرض، والتعمير، بناء المساجد واجب على المسلمين، الواجب عليكم إذا كان ما عندكم مسجد قريب؛ أن تعمروا مسجدًا على حساب أنفسكم، أو بأيديكم، كما عندكم نقود بأيديكم تتعاونوا في بنائه بأيديكم في المكان المناسب المتوسط بينكم، وإذا استعنتم بالله، ثم ببعض إخوانكم الأثرياء؛ فلا حرج في ذلك. أما تساهلكم هذا لا يجوز، لكن ما دام المسجد لم يقم، صلوا جميعًا في أي بقعة من الأرض تناسبكم، تجتمعون فيها، أو في بيت أحدكم إذا لم يتيسر مكان مناسب، والحمد لله حتى يقام المسجد، ولا بد من إقامته، يجب عليكم أن تقيموه، وأن تتعاونوا في ذلك، أو تستعينوا بمن ترونه من أهل الخير في بلدكم، أو غيرها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11075/حكم-صلاة-الجماعة-اذا-لم-يكن-هناك-مسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_465/46510.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12870,"question":"مستمع هو عباس يوسف حكمي من قرية عقدة الأحكامية بمنطقة جيزان بعث يسأل ويقول: إذا جاء جماعة حوالي ثلاثة أو أربعة والإمام جالس في التشهد الأخير، ثم اشترك هؤلاء الثلاثة في هذه الفريضة، وعندما سلم الإمام قام هؤلاء الجماعة، وتقدم واحد منهم، وأم هؤلاء، وصلى بهم، نرجو منكم التوضيح هل ما فعلوه سليم؟","title":"حكم من فاتهم بعض الصلاة وقدموا أحدهم إمامًا لهم","answer":"الجواب:  صلاتهم صحيحة، ولا بأس بذلك، لكن الأولى ترك ذلك، وأن يقضي كل واحد على نفسه، هذا هو الذي ينبغي كل واحد يقضي لنفسه؛ لأن الرسول ﷺ لما جاءه عبدالرحمن بن عوف قد صلى بالناس ركعة في غزوة تبوك، صلى مع عبدالرحمن الركعة التي بقيت هو والمغيرة، فلما سلم عبدالرحمن؛ قام النبي ﷺ وقام المغيرة، وقضى كل واحد لنفسه الركعات التي فاتته، فهذا هو الأفضل أن كل واحد يقضي لنفسه، ولا يحتاج أن يتقدمهم واحد منهم فيصلي بهم، لكن صلاتهم صحيحة، لا نعلم مانعًا من صحتها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11085/حكم-من-فاتهم-بعض-الصلاة-وقدموا-احدهم-اماما-لهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_466/46602.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12884,"question":"تسأل أختنا وتقول: هل يجوز للمرأة أن تصلي في المسجد في شهر رمضان المبارك، وهل لها أن تتعطر وتتبخر؟","title":"حكم صلاة المرأة في المسجد","answer":"الجواب:  لها أن تصلي مع الناس في المسجد، مع العناية بالتستر والحجاب، والبعد عن أسباب الفتنة، وعدم التعطر والتبخر؛ لأنها تسير في الطرقات، فيحصل بها فتنة، والنبي ﷺ نهى عن حضور الصلاة لمن تعطرت، نهى قال: من مست طيبًا؛ فلا تحضر معنا الصلاة في اللفظ الآخر: أيما امرأة أصابت بخورًا؛ فلا تشهد معنا العشاء هكذا قال عليه الصلاة والسلام. فالمقصود: أنها إذا أرادت الخروج للصلاة مع الناس، ليس لها التعطر، ولا التبخر، وعليها مع ذلك أن تعتني بالستر والحجاب، وأن تخرج في زي لا يفتن الناس، كما في الحديث: وليخرجن تفلات يعني: غير متطيبات، وليس هناك زينة تفتن الناس، وإلا فبيتها خير لها، بيتها خير لها، وأفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11099/حكم-صلاة-المراة-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_466/46616.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12890,"question":"المستمع: أبو فلاح المطيري بعث يسأل ويقول: في صلاة العصر نسي الإمام أن يجلس للتشهد الأوسط، فذكره المأمومون غير أنه أصر على القيام للركعة الثالثة دون قراءة التشهد، فتبعه الناس عدا رجلين، جلسا وقرأ التشهد، وبقيا جالسين حتى سجد الإمام سجدتي الركعة الثالثة، وقام للرابعة، فقاما معه، وعليه: فأصبحت للإمام ومن تبعه الرابعة غير أنها بدون تشهد أوسط، وللرجلين الثالثة، وبعد التشهد الأخير سجد الإمام سجدتي السهو وسلم، وسجد جميع الناس للسهو مع الإمام بما فيهم الاثنان، غير أنهما لم يسلما معه، ولكن قاما فأتيا بالرابعة، فقال: من تبع الإمام كان عليكما يا الرجلان أن تتبعا الإمام، وتقتديا به، وقال الرجلان: بل نتبعه إذا كنا على يقين بأننا مخطئين، والإمام مصيب، أو إن كنا في شك، ولكن إن كنا على يقين بأننا المصيبون وهو المخطئ فلا يجب أن نتبعه؛ لأنه يجب البناء على اليقين ونحن على يقين بأنه مخطئ، والإمام نفسه كان على شك من نفسه، أو قد أيقن أنه مخطئ بدليل أنه سجد للسهو، فأي الفريقين مصيب، جزاكم الله خيرًا؟","title":"الواجب على المأمومين إذا ترك الإمام التشهد الأوسط سهوًا","answer":"الجواب: الذين قاموا مع الإمام هم المصيبون، والشخصان اللذان بقيا هما المخطئان، وقد ثبت عنه ﷺ أنه: قام عن التشهد الأول، فقام الناس معه، ولم يجلسوا، فلما فرغ من صلاته؛ سجد سجدتين للسهو قبل أن يسلم، ثم سلم، عليه الصلاة والسلام وهاتان السجدتان بدلًا من ترك التشهد الأول، والتشهد الأول واجب عند بعض أهل العلم، وسنة مؤكدة عند آخرين، فتركها ينجبر بسجدتي السهو. والصواب: أنه واجب، لكن ليس من جنس الأركان، فإذا قام الإمام ولم يجلس، فإن المأمومين يقومون معه، ينبهونه قبل أن يستتم، فإن نبهوه قبل أن يستتم؛ وجب عليه أن يرجع، فإن لم يرجع قاموا معه؛ لأنه قد يكون جهل الحكم الشرعي، قد يكون ما سمعهم. فالواجب على كل حال أن يقوموا معه، ويكملوا معه، ويسجدوا للسهو معه، ولا يجلس أحد منهم، هذا هو الواجب، كما فعل الصحابة مع النبي ﷺ ولم يقل لهم: من كان كذا، فليفعل كذا، بل أقرهم، فالشخصان اللذان جلسا قد أخطآن. أما في غير هذه المسألة لو قام إلى ثالثة في الفجر، وهناك من يعلم أنه أخطأ؛ لا يقومون معه؛ لأنه زيادة في الصلاة، أو قام إلى خامسة في الظهر؛ لا يقومون معه، الذي يعلم أنها زائدة لا يقوم معه، ينتظر حتى يسلم، ويسلم معه مع التنبيه. وهكذا لو جلس عن نقص، جلس في الثالثة في الظهر، أو في العصر، أو في العشاء ينبهونه، فإن تنبه وإلا قاموا وكملوا صلاتهم، هذا هو محل المخالفة لمن تيقن خطأ الإمام، أما من لم يتيقن خطأ الإمام، بل شك، أو يعلم صواب الإمام؛ فإنه يتابعه، أو يعلموا خطأ الإمام، لكن جهل الحكم الشرعي؛ فإنه يتابعه، ولا شيء عليه، فمن تابعه في الخطأ جاهلًا، أو شاكًا؛ فلا شيء عليه، أما من تابعه وهو يعلم الحكم الشرعي، ويعلم أنه مخطي، هذا ما تصح صلاته، أن يتابعه في الزيادة، ولا في النقص، والله المستعان، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11105/الواجب-على-المامومين-اذا-ترك-الامام-التشهد-الاوسط-سهوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_467/46705.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12896,"question":"يقول: إذا كنت أشاهد الناس يصلون في التلفزيون، أو أسمعهم في الراديو، فهل لي أن اقتدي بهم، وأصلي؟","title":"حكم الاقتداء بصوت الإمام في التلفاز أو الراديو","answer":"الجواب:  لا، ليس لك ذلك تصلي وحدك إذا لم تستطع الخروج إلى الجماعة، وإلا فعليك أن تصلي في المساجد، أما إذا كنت مريضًا تصلي وحدك، إن كان عندك في البيت أحد يصلي معك، يصلي معك كأهلك؛ وإلا صل وحدك الحمد لله. أما إذا كنت تستطيع؛ فالواجب عليك أن تصلي مع الجماعة في مساجد الله، وعليك أن تحذر مشابهة أهل النفاق، أما الصلاة من طريق الراديو، أو من طريق التلفاز تقتدي بالإمام بصوت المكبر في التلفاز، أو .... هذا لا يجوز، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11111/حكم-الاقتداء-بصوت-الامام-في-التلفاز-او-الراديو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_467/46711.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12904,"question":"رسالة وصلت إلى البرنامج من السودان العبيدية، وباعثها المستمع: أمير الدين عبدالله، أمير الدين له أكثر من سؤال، في إحدى أسئلته يقول: هل تصح الصلاة في المنزل إذا سمعت الأذان، ولم أذهب إلى المسجد، أم لا بد أن تكون الصلاة في المساجد؟","title":"حكم صلاة من صلى في البيت وترك الجماعة","answer":"الجواب:  الواجب أن تؤدى الصلاة في المساجد مع إخوانك المسلمين؛ لأن الرسول  قال: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر وجاءه رجل أعمى فقال: يا رسول الله! ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له -عليه الصلاة والسلام-: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب. فهذا أعمى ليس له قائد يلائمه، ومع هذا أمره النبي ﷺ بالإجابة، ولم يرخص له، فكيف بحال القادر البصير، فاتق الله أيها السائل! واحذر من التساهل، ومن مشابهة أهل النفاق. واختلف العلماء: هل تصح في البيت؟ على قولين: أحدهما: أنها تصح مع الإثم، وهذا هو الصواب، تصح مع الإثم. والثاني: أنها لا تصح، وأن عليه أن يصلي في الجماعة، ولا تصح صلاتهم دون الجماعة، ولكن القول الأول أصح أنها تصح، ولكن يأثم، وعليه التوبة إلى الله، وأن يستقيم على أدائها في الجماعة، الله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11119/حكم-صلاة-من-صلى-في-البيت-وترك-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_468/46806.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12912,"question":"من جمهورية مصر العربية محافظة المنيا، المستمع: (ع. س. م) بعث يسأل ويقول: أنا مصاب بمرض سلس البول، هل يجوز أن أؤم الناس في الصلاة؟","title":"حكم إمامة المصاب بسلس البول","answer":"الجواب:  ينبغي ألا تؤم الناس؛ لأن جملة من أهل العلم نبهوا على هذا؛ لأن حدثك دائم، فالأولى بك ألا تؤم الناس، وأن تصلي مأمومًا، وتتوضأ لكل وقت صلاة، كل وقت صلاة تتوضأ مثل المستحاضة، عليك أن تتوضأ لوقت كل صلاة، وتصلي في الوقت، وتقرأ في الوقت، وتلمس المصحف حتى ينتهي الوقت؛ لأن هذه الطهارة طهارة ضرورة. فأنت تصلي مع الإمام، ولا تصلي إمامًا، هذا هو الأحوط، وفيه الأخذ بما قاله أهل العلم، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11127/حكم-امامة-المصاب-بسلس-البول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_468/46814.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12916,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلينا من السودان باعثها مستمع رمز إلى اسمه بالحروف (أ. أ)، يقول في أحد أسئلته: أنا أقيم حاليًا في الرياض وأعمل في مزرعة جوار المسجد، وحصلت عندنا سرقة غنم نهارًا، وصاحب المزرعة منعني أن أصلي في المسجد وأمرني أن أصلي في المزرعة كل الأوقات الخمسة حتى أكون حارسًا على المزرعة، وما فيها، وحتى لا تتكرر السرقة، هل صلاتي والحال ما ذكر جائزة، أم لا؟ جزاكم الله خيرًا.","title":"حكم صلاة الجماعة لمن يشتغل بالحراسة","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإن الحراسة عذر شرعي في التخلف عن الجماعة، ولا حرج عليك في ذلك، فالحارس في المزرعة، أو على دكان، أو على بيت، أو نحو ذلك معذور عن حضور الجماعة لمسيس الحاجة إلى الحراسة، ولا حرج في ذلك -إن شاء الله- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11131/حكم-صلاة-الجماعة-لمن-يشتغل-بالحراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_469/46901.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12928,"question":"السائل (ع. م. ع) من السودان يقول في هذا  إذا أدرك المصلي الركعتين الأخيرتين لصلاة العشاء مثلًا، فهل يقرأ ما فاته سرًا، أم جهرًا؟ وهل يكمل ما فاته بسورة الفاتحة فقط، أفيدونا بذلك؟","title":"كيفية قضاء الركعتين الفائتتين في صلاة الجماعة الجهرية","answer":"الجواب:  الصواب أن ما أدركه المسبوق مع الإمام هو أول صلاته، وما يقضيه هو آخرها؛ لقول النبي ﷺ: ما أدركتم فصلوا، وما فاتكم فأتموا يقول ﷺ: إذا أتيتم الصلاة؛ فعليكم السكينة والوقار، فما أدركتم يعني مع الإمام فصلوا، وما فاتكم فأتموا وفي لفظ: فاقضوا يعني: أتموا، معنى القضاء التمام، وهذا يفيد أن ما أدركه الإنسان مع الإمام يكون هو أول صلاته، فإذا أدرك مع الإمام ركعتين من العشاء؛ فإنها تكون أول صلاته، فإذا سلم الإمام؛ يقوم يأتي بالركعتين الأخيرتين، يقرأ فيهما الفاتحة سرًا؛ لأنها آخر صلاته. وهكذا إذا أدرك واحدة من المغرب فإن الثنتين الأخيرتين هما آخر صلاته، فالأولى يقرأ فيها الفاتحة وسورة، أو آيات، ويجهر بعض الشيء جهرًا لا يشوش على من حوله، والأخيرة يقرأ فيها الفاتحة سرًا؛ لأنها هي المكملة لصلاته، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11144/كيفية-قضاء-الركعتين-الفاىتتين-في-صلاة-الجماعة-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_501/50103.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12957,"question":"السائل الذي رمز لاسمه بـ (م. م. ع. أ) من السودان يقول: هل يمكن أن أصلي في البيت، مع العلم بأنني صحيح وقادر، ومع العلم بأنني أسمع الأذان والإقامة، أفيدوني بذلك؟","title":"حكم ترك الصلاة في المسجد مع القدرة","answer":"الجواب:  لا يجوز لك أن تصلي في البيت، يجب أن تصلي مع الناس، من سمع النداء؛ وجب عليه أن يصلي مع الجماعة، يقول النبي ﷺ: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر قيل لابن عباس: «ما هو العذر؟ قال: خوف، أو مرض».  وجاءه ﷺ رجل أعمى فقال: «يا رسول الله، ليس لي قائد يقودني للمسجد، فهل لي من رخصة أن أصلي في بيت؟ -وهو أعمى- فقال له النبي ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب أعمى ليس له قائد يقال له: أجب. ويقول ابن مسعود : «لقد رأيتنا، وما يتخلف عنها -يعني: الصلاة في الجماعة- إلا منافق معلوم النفاق» فالواجب على المسلم القادر أن يصلي مع الجماعة ما دام يستطيع، يسمع النداء، في محل بحيث يسمع النداء؛ يلزمه. أما إذا كان بعيدًا يشق عليه، ما يسمع النداء وهو بعيد؛ فإنه يصلي في محله مع جماعته، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11174/حكم-ترك-الصلاة-في-المسجد-مع-القدرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50214.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":12958,"question":"السائل يقول: أرجو أن توجهوا لنا نصيحة من الكتاب والسنة بالنسبة للمصلين، الإمام يقول: تراصوا واعتدلوا إلى آخره، ولكن للأسف الشديد لا شيء يحصل من ذلك، فأرجو أن توجهونا جميعًا؟","title":"وجوب التراص وسدد الخلل في الصلاة","answer":"الجواب:  الواجب على المصلين أن يتقوا الله، وأن يرصوا الصفوف ويتقاربوا، ولو ما قال الإمام شيء، لكن الإمام يقول لهم يذكرهم يقول: استووا، تراصوا، تقاربوا، كملوا الأول فالأول، والواجب عليهم أن يفعلوا ذلك، حتى ولو سكت الإمام يجب عليهم أن يكملوا الصف الأول فالأول، وأن يتراصوا فيما بينهم، لا يكون فرج، النبي ﷺ قال: لا تذروا فرجات للشيطان، سدوا الخلل فيتقاربون حتى يكون قدم كل واحد يلي قدم الآخر، يلصق قدمه بقدمه من غير أذى، حتى يسد الخلل، ويكونوا مستويين، لا يتقدم أحد على أحد، يكون صدره مساوي صدر أخيه، لا يتقدم عليه. وهكذا كل ما تم صف؛ كملوا الصف الثاني والثالث، وهكذا، هذا هو الواجب على الجميع، كما أمر النبي بهذا -عليه الصلاة والسلام- قال: رصوا صفوفكم، وقاربوا بينها، وحاذوا بالأعناق وقال: من وصل صفًا وصله الله، ومن قطع صفًا قطعه الله وقال: سدوا الخلل، لا تذروا فرجات للشيطان. فالواجب على الجماعة في المسجد أن يتراصوا فيما بينهم، وأن يسدوا الخلل، وأن يكملوا الصف الأول فالأول، هكذا الواجب على الجميع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11176/وجوب-التراص-وسدد-الخلل-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50215.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13016,"question":"هناك كلمات يرددها بعض الناس بعد الصلاة مثل: حرمًا، تقبل الله، فهل هذه جائزة؟","title":"حكم قول بعد الصلاة: حرماً .. تقبل الله","answer":"الجواب:  أما حرمًا فلا أعرف لها أصلًا، حرمًا ما أعرف لها أصلًا، وأما إذا قال لأخيه: تقبل الله منك؛ فلا أعلم فيه بأسًا، لا في الصلاة، ولا في غيره، تقبل الله منك صيامك، تقبل الله منك صلاتك، لا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11233/حكم-قول-بعد-الصلاة-حرما-تقبل-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_471/47112.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13017,"question":"مصافحة المصلين بعضهم بعضًا بعد الصلاة هل هي جائزة؟","title":"حكم المصافحة عقب الانصراف من الصلاة","answer":"الجواب: إذا كان لم يصافحه أولًا؛ استحب له أن يصافحه، إذا فرغ من الأذكار الشرعية؛ صافح أخاه، أما إذا كان التصافح عند اللقاء في الصف قبل الصلاة؛ فهذا يكفي، والحمد لله؛ لأن المصافحة سنة عند اللقاء، والسلام سنة عند اللقاء، فإذا صافحه عندما لقيه في الصف، أو بعد صلاة النافلة قبل الصلاة كفى ذلك.  وإن صافحه بعد الفريضة بعدما يفرغ من الأذكار، هذا كله لا بأس به، من باب الإيناس، وأداء السنة، والتآلف، لكن لا يبادر من حين يسلم كما يفعل بعض الناس لا، بعد الأذكار، بعدما يفرغ من الأذكار الشرعية؛ يسلم على أخيه على يمينه وشماله، كيف حالك من باب التآلف والتعاون؛ لأنه ﷺ كان يصافح الصحابة، ولما جاء عنه ﷺ: إن المسلمين إذا تلاقيا وتصافحا؛ غفر لهما ما تقدم من ذنوبهما. فالسنة عند الالتقاء المصافحة. وثبت عن أنس  قال: كان أصحاب النبي ﷺ إذا تلاقوا تصافحوا، وإذا قدموا من سفر تعانقوا وكان ﷺ إذا دخلت عليه بنته فاطمة؛ قام إليها، وصافحها، وقبلها، وأجلسها مكانه، وإذا دخل عليها؛ هي قامت إليه، وصافحته، وقبلته، وأجلسته مكانها. فالمقصود: أن إفشاء السلام، والمصافحة عند اللقاء، والبشاشة في وجه أخيك كل هذا من أسباب الألفة والمحبة، لكن لا تجعل هذا من حين تسلم، بل بعد فراغك من السلام، والذكر الشرعي؛ تسلم، وتصافحه إذا كنت ما صافحته قبل ذلك، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11234/حكم-المصافحة-عقب-الانصراف-من-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_471/47113.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13019,"question":"يقول: إنني أشتغل في ورشة، وأسمع الأذان، وأنا في الورشة، وكنت في بعض الأيام أصلي في المسجد، ولكن خطب الخطيب في يوم الجمعة، وقال: لا يصح للعامل أن يأتي من عمله ليصلي في المسجد؛ لأنه يؤذي المصلين بالملابس المزيتة، وأصلي أنا وأخي زميل لي في الورشة جماعة، هل صلاتنا صحيحة في العمل القريب من المسجد.","title":"حكم صلاة الجماعة لمن في ثيابهم زيوت تؤذي المصلين","answer":"الجواب:  هذا الذي قاله الخطيب غلط وجهل، بل يجب على العمال أن يحضروا في الصلاة، وأن يعتنوا بالصلاة مع الجماعة، ولا يغتروا بخطبة الجاهلين، بل يجب على العمال أن يصلوا مع الناس، ويحضروا مع الناس، وإن كان في ثيابهم زيت، أو غيره، لكن عليهم أن يحرصوا على النظافة، وألا يكون عندهم روائح كريهة كالدخان..... يحرصون على أن يتوضؤوا، وأن يتنظفوا مما يؤذي إخوانهم المصلين، ولا يجوز لهم التساهل في هذا الأمر، فإذا حضرت الصلاة؛ ترك الشغل، وبادر إلى الصلاة، وتعاطى الأسباب التي تعينه على حضورها مع الجماعة، وعدم إيذائهم لا بدخانه، ولا بغيره من الأذى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11236/حكم-صلاة-الجماعة-لمن-في-ثيابهم-زيوت-توذي-المصلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_471/47115.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13108,"question":"إذا أقام المؤذن للصلاة، وأنا مازلت في صلاة السنة، فهل أسلم من الصلاة، أم أكمل الصلاة، ثم ألحق بهم؟","title":"المشروع لمن أقيمت الصلاة وهو يصلى النافلة","answer":"الجواب:  الأرجح من قولي العلماء أنك تقطعها، تنوي قطعها، وتلحق بالصلاة؛ لقول النبي ﷺ: إذا أقيمت الصلاة؛ فلا صلاة إلا المكتوبة رواه مسلم ، ولما رأى ﷺ رجلًا يصلي، وقد أقيمت الصلاة؛ أنكر عليه، عليه الصلاة والسلام. فالمقصود: أنه إذا أقيمت الصلاة، وأنت تصلي؛ فاقطعها، وادخل مع الإمام، ولا تكملها، فالفريضة أهم. وقال بعض أهل العلم: أنه يتمها خفيفة، ولكن الصواب أنه لا يتمها، بل يقطعها، ولا يحتاج إلى سلام، بل يقطعها بالنية، ويكفي، والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11326/المشروع-لمن-اقيمت-الصلاة-وهو-يصلى-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_473/47309.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13134,"question":"المستمع طارق يوسف يسأل ويقول: كنت أصلي الظهر بمفردي، وفي أثناء الركعة الثانية وجدت صلاة جماعة تصلى أمامي، هل أنوي مع صلاة الجماعة وأنا واقف مكاني، أو أكمل الصلاة بمفردي؟","title":"حكم من صلى منفردًا ثم أقيمت جماعة أثناء صلاته","answer":"الجواب:  تقطعها وتدخل معهم، تقطع صلاتك وتدخل معهم من أول الصلاة، تذهب معهم وتقضي بعد ذلك إذا سلموا، تقضي ما فاتك؛ لأن صلاة الجماعة مطلوبة، وإن كملت فلا حرج، إن كملت فلا حرج وإن قطعتها، وانتقلت إليهم؛ فإنك مأجور في هذا لأجل الجماعة، لأجل فضل الجماعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11378/حكم-من-صلى-منفردا-ثم-اقيمت-جماعة-اثناء-صلاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_474/47412.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13173,"question":"بعد ذلك ننتقل إلى رسالة بعث بها سائل للبرنامج رمز لاسمه أبو أحمد يقول: حدثونا عن سجود السهو، متى يكون قبل السلام، ومتى يكون بعده؟","title":"حالات سجود السهو ومتى يكون","answer":"الجواب:  سجود السهو السنة أن يكون قبل السلام؛ لأنه جزء من الصلاة، فالسنة أن يكون قبل السلام، هذا هو السنة، إلا في حالين: إحداهما: إذا سلم عن نقص ركعة، أو أكثر، ثم نبه، أو تنبه؛ فإنه يكمل صلاته، ويسلم، ثم يسجد للسهو، كما جرى للنبي ﷺ في قصة ذي اليدين، كمل الصلاة، ثم سلم، ثم سجد للسهو -عليه الصلاة والسلام- هذا هو الأفضل، وإن سجد قبل السلام؛ أجزأه، لكن هذا هو الأفضل، إذا سلم عن نقص ركعة، أو أكثر، ثم نبه، أو تنبه، وقضى ما عليه؛ فإنه يتمم الصلاة، ويسلم، ثم يسجد للسهو سجدتين، يكبر ويسجد، ويرفع ويكبر، هكذا يكبر عند السجود، وعند الرفع، وعند السجود الثاني، وعند الرفع، ثم يسلم. الحال الثاني: إذا بنى على غالب ظنه، إذا بنى على غالب ظنه فإنه يكون السجود بعد السلام، هذا هو الأفضل؛ لما ثبت في الصحيح من حديث ابن مسعود  أن النبي ﷺ قال: إذا شك أحدكم في صلاته؛ فليتحر الصواب؛ فليتم ما عليه، ثم ليسلم، ثم ليسجد سجدتين هكذا جاء في البخاري، إذا شك أحدكم في صلاته؛ فليتحر الصواب؛ فليتم ما عليه، ثم ليسلم، ثم يسجد سجدتين فإذا شك في ثلاث، أو أربع، أو غلب على ظنه أنها أربع، وتمم على أنها أربع؛ يكون سجوده بعد السلام أفضل. وهكذا في الفجر وفي المغرب إذا بنى على غالب ظنه، صلى واشتبه هل الركعة التي هو فيها هي الأولى، أو الثانية في الفجر، وغلب على ظنه أنها الثانية؛ فإنه يكمل، ويسجد للسهو بعد السلام. وهكذا في المغرب شك بعد الثانية، هل هي في الثالثة، أو الثانية، وغلب على ظنه أنها الثالثة؛ يكمل ويسجد للسهو بعد السلام. المقصود: أن السجود للسهو إذا كان قد بنى على غالب ظنه يكون بعد السلام في جميع الصلوات الخمس، أما إذا كان لا، عنده تردد، وبنى على اليقين؛ فإن السجود يكون قبل السلام، هذا هو الأفضل، يسجد سجدتين قبل أن يسلم إذا بنى على اليقين، أما إذا بنى على غالب ظنه؛ فإن الأفضل يكون سجوده بعد السلام، وإن سجد قبل السلام؛ فلا حرج، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11428/حالات-سجود-السهو-ومتى-يكون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_511/51109.mp3","categories":["سجود السهو"]},{"id":13175,"question":"ننتقل بعد ذلك -سماحة الشيخ- إلى رسالة بعث بها السائل: (م. م. س) الدمام يقول: أستيقظ لأداء صلاة الفجر، والحمد لله، يقول: ولكن ليس بجانبي مسجد قريب، فالمساجد بعيدة، ولكنني أسمع الأذان في المساجد، وأصلي في البيت في وقت صلاة الفجر، فهل صلاتي صحيحة؟","title":"حكم الصلاة في المنزل إذا كان المسجد بعيداً","answer":"الجواب:  إذا كانت المساجد بعيدة، إنما تسمع من أجل مكبرات الصوت فلا حرج عليك، وإن تجشمت مشقة في السيارة، أو على قدميك وذهبت إلى المسجد؛ فهذا أفضل لك. أما إذا كان تسمع الأذان بغير مكبر لقرب المسجد؛ يلزمك أن تذهب، وتصلي مع الناس، أما إذا كانت بعيدة لا تسمع إلا من أجل المكبر؛ فلا حرج عليك إذا صليت في البيت، وإن ذهبت وصبرت على المشقة؛ فهذا خير لك، وأفضل. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11430/حكم-الصلاة-في-المنزل-اذا-كان-المسجد-بعيدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_511/51111.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13190,"question":"رسالة من أحد الإخوة المستمعين يقول: أخوكم في الله (ت. ع. ع. ض) أخونا يسأل هل يجوز أن يصلي المسلم نافلة العصر، أو الصبح إذا جاء المسجد والإمام قد دخل في الصلاة، ولم يدرك النافلة قبل الصلاة؟","title":"حكم من دخل المسجد والإمام قد شرع في الصلاة","answer":"الجواب:  إذا جاء المسجد والإمام في الصلاة؛ يدخل مع الإمام، ليس لأحد أن يصلي والإمام يصلي، بل متى جاء؛ وجب عليه الدخول مع الإمام، وسقطت النافلة، سواء راتبة كالظهر، أو غير راتبة كالعصر، متى جاء المأموم والإمام قد شرع في الصلاة، وقد أقيمت؛ فإنه يدخل معه؛ لقول النبي ﷺ: إذا أقيمت الصلاة؛ فلا صلاة إلا المكتوبة. فالواجب على المؤمن متى وصل إلى المسجد أن يصلي مع الإمام، متى وجده في الصلاة، أو قد أقيمت الصلاة. نعم.","link":"https://binbaz.org.sa/fatwas/11445/حكم-من-دخل-المسجد-والامام-قد-شرع-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_475/47507.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13387,"question":"رجل يأتي متأخرًا في الصلاة، ويريد أن يدخل في الصف الأول، ويفرق بين الجالسين في الصف الأول؛ ليفسحوا له فرجة، هل يجوز له هذا؟","title":"حكم مزاحمة المصلين للصلاة في الصف الأول","answer":"الجواب: المشروع أن ينتهي حيث انتهت الصفوف، لا يزاحم الناس، إذا كان الصف الأول انتهى؛ يصف الثاني، الصف الثاني انتهى؛ يصف الثالث، وهكذا، إلا إذا وجد فرجة ما سدوها هم الذين أخلوا يذهب إليها، أما إذا كان ما في فرجة، إنما يزاحمهم، يقول تفحسوا، لا. لا يرح لهم، يصف في منتهى الصف الذي وجده اثنين.. ثلاثة.. أربعة، على حسب الحال، ولا يزاحم الناس، ولا يقطع الصفوف، ولا يتخطى رقاب الناس، إلا إذا كان الصف الأول ما تم، وصفوا في الثاني؛ يروح للصف الأول يكمله، أو تركوا فرجًا، وذهب إلى فرجة يسدها؛ لا بأس؛ لأنهم هم الذين قصروا. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11678/حكم-مزاحمة-المصلين-للصلاة-في-الصف-الاول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_515/51510.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13440,"question":"في آخر أسئلته يقول هذا السائل: هل يجوز للمقتدي أن يصلي بمن جاء من ورائه، مثلًا رجل لم يلحق بالمغرب إلا بركعة واحدة، ثم قام ليكمل ما بقي، وجاء رجل آخر، فهل يقتدي به، أم لا؟ وما صحة ذلك مأجورين؟","title":"حكم الاقتداء بالمسبوق","answer":"الجواب: إن اقتدى به؛ فلا بأس، وإن صلى وحده؛ فهو أفضل، إن صلى وحده فهو أفضل، وإن اقتدى بالمسبوق، جعله إمامًا له، فإذا سلم المسبوق، كمل ما عليه؛ فلا حرج -إن شاء الله- على الصحيح. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11737/حكم-الاقتداء-بالمسبوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52711.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13483,"question":"هنا رسالة وصلت إلى البرنامج من المستمع متعب الريفي من بلاد الريف جبال زهوان، أخونا يقول: إننا في بلاد الريف سكان في أودية، وفي جبال، وقد نسمع صوت المؤذن في المساجد التي في قرانا، ولكن لا نقدر نجيب الدعاء، إنا في رأس جبل، والمؤذن في الوادي، فإذا مشيت يومًا أسمع النداء لصلاة الظهر مثلًا قد لا أتمكن من اللحاق إلا بصلاة العصر، وأنا سمعت حديثًا عن الرسول ﷺ: أن رجلًا أعمى قال: هل تجد لي من رخصة، قال الرسول ﷺ: هل تسمع النداء؟ قال: نعم، قال: أجب هل كل من يسمع النداء ملزم بالإجابة، وإن كان كحالنا؟ وجهونا جزاكم الله خيرًا.","title":"نحن في رأس جبل والمؤذن في الوادي، فهل يلزمنا النزول للجماعة","answer":"الجواب: هذا النداء المعتاد الذي بدون المكبرات، بدون المكبر إذا سمعه الإنسان فهو قريب عند هدوء الأصوات، هو قريب يجب عليه الحضور، أما سماعه من طريق المكبرات، فهذا يسمع من بعيد، فلا يلزمه إذا كان بعيدًا عن المسجد، ويشق عليه، وربما لو توجه بعد الأذان ما أدرك المسجد، هذا لا يلزمه، وليس داخلًا في الحديث، إنما المراد في الحديث السماع للمؤذن بالطريقة المعتادة في عهده ﷺ بغير مكبرات، فهذا إذا سمع النداء يلزمه الحضور إذا قدر، أما إذا كان مريضًا، أو عاجزًا لا يلزمه. أما إذا سمع من طريق المكبرات؛ فهذا يسمع من بعيد لا يلزمه إذا كان بعيدًا يشق عليه الحضور، أو لو حضر ما أدرك، لو حضر بعد الأذان ما أدرك، هذا ليس داخلًا في الحديث، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11786/نحن-في-راس-جبل-والموذن-في-الوادي-فهل-يلزمنا-النزول-للجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_478/47812.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13484,"question":"يسأل سؤالًا آخر، ويقول: هل الرجل يؤم زوجته ومحارمه؟ وأين يكون وضع الإمام إذا كانت امرأة واحدة؟ هل هي بجانبه أو خلفه؟","title":"حكم إمامة الرجل لمحارمه وأين يقفن إذا أمهن؟","answer":"الجواب: يجوز له أن يؤمهم إذا فاتته الصلاة مثلًا، أو كان مريضًا، أو في النافلة يؤمهم، إن كان ثنتين أو ثلاث، أو أكثر صفين خلفه، وإن كانت واحدة كذلك تكون خلفه، ولا يصفون معه، ولا عن يمينه، ولا عن شماله، ولو أنها واحدة ولو أنها زوجته، الرسول ﷺ أمر أن يكون صفوفهن متأخرة عن الرجال، ولما صلى ذات يوم في بيت أنس بـأنس واليتيم، صلت المرأة خلفهم، أم سليم خلف الجميع، وهي واحدة، ولم تصف مع ابنها أنس، وابن ابنها اليتيم. فالمقصود: أن موقف المرأة خلف الرجال، ولو كانت واحدة، تقف خلف الرجل، ولو أنه زوجها أو أخوها تقف خلفه، لا عن يمينه، ولا عن شماله، أما الرجل فيقف عن يمينه إذا كان واحدًا، وإن كان الرجال اثنين فأكثر وقفوا خلف الإمام. أما النساء فيقفن خلفهم مطلقًا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11787/حكم-امامة-الرجل-لمحارمه-واين-يقفن-اذا-امهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_478/47813.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13534,"question":"يقول السائل: ما حكم إقامة جماعتين في مسجد واحد في وقت واحد، ولكنهم مختلفين الفريضة؟","title":"حكم إقامة جماعتين في مسجد واحد","answer":"الجواب: الواجب أن يصلوا جميعًا، إذا كانوا في وقت واحد عليهم أن يصلوا جميعًا، وليس لهم أن ينقسموا، عليهم أن يصلوا جميعًا، أما إذا صلت الجماعة الأولى، ثم جاءت جماعة أخرى صلوا وحدهم ولا حرج، لكن ما داموا جميعًا وقت الصلاة الأولى عليهم أن يصلوا جميعًا في الوقت الحاضر، وليس لهم أن يتفرقوا، بل يجب أن يصلوا جميعًا بإمام واحد. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11863/حكم-اقامة-جماعتين-في-مسجد-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53206.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13535,"question":"هذا سائل للبرنامج يقول في هذا  ما حكم من صلى المغرب بعد إمام يصلي العشاء قصرًا في نفس الوقت؟","title":"حكم صلاة المغرب خلف من يصلي العشاء قصرًا","answer":"الجواب: هذا سؤال مجمل: إذا قدم العشاء على المغرب ما يجوز، لا بد يقدم المغرب مع العشاء، فعليه أن يصلي المغرب أولًا، ثم يصلي العشاء بالترتيب، وليس له أن يصلي العشاء، ثم يصلي المغرب، لكن إذا صلى معهم العشاء بنية المغرب إن كانوا يقصرون ... المسافرين صلى معهم العشاء بنية المغرب، ثم قام بعد السلام، وأتى بالركعة الثالثة؛ أجزأ، أو كانوا مقيمين؛ صلى معهم العشاء بنية المغرب، وجلس في الثالثة حتى سلموا، ثم سلم، ثم صلى العشاء، لا بأس على الصحيح. نعم.","link":"https://binbaz.org.sa/fatwas/11856/حكم-صلاة-المغرب-خلف-من-يصلي-العشاء-قصرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53204.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13592,"question":"يقول هذا السائل من اليمن: هل الصلاة خلف من لا يحسن القراءة -أي: قراءة الفاتحة- هل هو مكروه؟","title":"هل تكره الصلاة خلف من لا يحسن قراءة الفاتحة؟","answer":"الجواب: إذا لم يتيسر غيره لا حرج؛ صل معه، إذا كان لحنه ما يحيل المعنى، إذا كان لحنًا خفيفًا لا يغير المعنى؛ فلا بأس أن تصلي معه، أما إذا كان يحيل المعنى؛ لابد يزال، لابد يعزل عن المسجد إذا لم يفهم، ولم يتعلم، يزال عن المسجد، يرفع أمره إلى الجهات المسؤولة؛ حتى يبدل بإنسان الذي يحسن القراءة. نعم.","link":"https://binbaz.org.sa/fatwas/11924/هل-تكره-الصلاة-خلف-من-لا-يحسن-قراءة-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_533/53309.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13676,"question":"السائل من الأردن له سؤال ثانٍ يقول: هل علي إثم إذا لم أصل الصلاة المكتوبة في المسجد، علمًا بأنني لا أسمع النداء إلا بمكبرات الصوت، أي: أن المسافة بيني وبين المسجد هي كيلو متر واحد تقريبًا، وأنا أجد مشقة في المحافظة على حضور الصلوات الخمس في المسجد، هذا السائل من الأردن، تفضل؟","title":"حكم صلاة الجماعة لمن كان المسجد بعيدًا عنهم","answer":"الجواب: الواجب على من سمع النداء أن يجيب المؤذن، وأن يصلي مع الجماعة؛ لقول النبي ﷺ: من سمع النداء، فلم يأت؛ فلا صلاة له إلا من عذر قيل لابن عباس: ما هو العذر؟ قال: خوف، أو مرض». وجاءه رجل أعمى، فقال: يا رسول الله! ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له: هل تسمع النداء بالصلاة؟ قال: نعم. قال: فأجب فهذا أعمى، ليس له قائد، ومع هذا أمره النبي ﷺ أن يجيب إذا كان يسمع النداء بالصوت العالي، دون المكبرات. أما إذا كان لا يسمع النداء إلا بمكبر؛ فهو معذور، إذا صلى في بيته، أو صلى مع جيرانه في بيت أحدهم حتى يوجد عندهم مسجد يكون صوت المؤذن يسمعونه بدون مكبر، أما إذا كان لا يسمع إلا بالمكبر فهو بعيد، إذا شق عليه الذهاب، لكن إن تجشم المشقة، وصبر، وذهب بالسيارة، أو على رجليه؛ هذا خير عظيم، وفضل كبير، لكن لا يلزمه إذا كان فيه مشقة، إذا كان بعيدًا لا يسمع صوت المؤذن إلا بمكبر؛ فهو لا يلزمه، لكن إذا تجشم المشقة، وصبر، وأحب المشاركة في الخير، هذا خير عظيم. في الصحيح: أن رجلًا كان بعيدًا عن المسجد، كان أبعد الناس عن المسجد، وكان يأتي إلى المسجد حافيًا، في مسجد النبي ﷺ في المدينة في حياة النبي ﷺ فقال له بعض الناس: لو اشتريت حمارًا تركبه في الرمضاء، أو في الليلة الظلماء، فقال الرجل: إني أحب أن يكتب الله لي أثر خطاي ذاهبًا وراجعًا، فأخبر النبي ﷺ بذلك، فقال: إن الله قد جمع له ذلك كله جمع له أثر خطاه ذاهبًا وراجعًا، وكان بعيدًا، لكن صبر على التعب؛ حرصًا على الأجر.  لكن من كان لا يتحمل، ويشق عليه ذلك؛ فلا بأس أن يصلي في بيته، أو مع جماعة له إن كان عنده جماعة يصلي هو وإياهم في بيت أحدهم. وإن استطاعوا أن يعمروا مسجدًا؛ وجب عليهم أن يعمروا مسجدًا، أن يعمروا مسجدًا، ويصلوا فيه فيما بينهم في حارتهم؛ لأن بناء المساجد أمر واجب على المسلمين مع القدرة، نعم. المقدم: جزاكم الله خيرًا. المقدم: يقول هذا السائل -يا سماحة الشيخ- من الأردن له فقرة أخرى تتبع الفقرة الأولى، يقول: نصلي في البيت أحيانًا الصلاة المكتوبة أنا وإخواني ووالدي وإخوتي، ولكننا نصليها كل واحد لوحده، ولا نصليها مع إمام واحد منا على شكل جماعة، هل علينا إثم في ذلك إذا تركنا الجماعة في نفس البيت؟ الشيخ: نعم. لا يجوز لكم ذلك، الواجب أن تصلوا جماعة، صلاة الجماعة واجبة، وأداؤها في المسجد واجب كل هذا، فالواجب عليكم أن تصلوا جماعة، إذا لم يتيسر الصلاة في المسجد؛ وجب أن تصلوا جماعة، يؤمكم أقرؤكم وأحسنكم، يؤمكم، وإن استطعتم أن تذهبوا للمسجد؛ وجب عليكم الذهاب إلى المسجد إذا كنتم تسمعون النداء، يجب الذهاب إلى المسجد والصلاة مع المسلمين لما تقدم من الحديث، لقوله ﷺ: من سمع النداء، فلم يأت؛ فلا صلاة له إلا من عذر وقال ابن مسعود : \"لقد رأيتنا وما يتخلف عنها -يعني: الصلاة في الجماعة- إلا منافق معلوم النفاق\". فالواجب على المؤمن أن يصلي مع الجماعة، وأن يحرص، ولا يصلي في البيت إلا إذا بعد فلا يسمع النداء؛ فلا بأس، ولكن يجتهد في أن يقيم هو وجيرانه مسجدًا حولهم حتى يصلوا فيه، يلزمهم إذا قدروا أن يقيموا مسجدًا حولهم، ويصلون فيه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12026/حكم-صلاة-الجماعة-لمن-كان-المسجد-بعيدا-عنهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_519/51908.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13692,"question":"يسأل سؤالًا آخر ويقول: كم تكبيرة يكبرها المأموم عندما يأتي والإمام في حال الركوع؟ أرجو التفصيل في هذه المسألة.","title":"كم يكبر المسبوق إذا أدرك الإمام وهو راكع؟","answer":"الجواب: يكبر تكبيرتين: إحداهما وهو واقف، وهذه هي التكبيرة الأولى، وهي تكبيرة الإحرام، وهي ركن لابد منه، ولا تنعقد الصلاة إلا بها، ثم ينحط مكبرًا للركوع، فإن خاف أن تفوته الركعة؛ اكتفى بالأولى، التكبيرة الأولى، وكفت عن تكبيرة الركوع في أصح قولي العلماء؛ لأنهما عبادتان اجتمعتا في محل واحد؛ فاجتزئ بالعظمى منهما، وهي تكبيرة الإحرام، لكن بشرط أن يؤديها وهو واقف قبل أن يركع، يؤديها وهو واقف بنية التكبيرة الأولى. وإذا أمكنه أن يأتي بالثانية وهو في هويه إلى الركوع؛ كان هذا هو الأكمل، فإن لم يتيسر ذلك لضيق الوقت؛ كفته التكبيرة الأولى، وهي تكبيرة الإحرام في أصح قولي العلماء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12063/كم-يكبر-المسبوق-اذا-ادرك-الامام-وهو-راكع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48102.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13734,"question":"يسأل ويقول: ما حكم إمامة المعذور للصحيح؟ مع العلم أن الصحيح لا يجيد قراءة القرآن؟","title":"حكم إمامة المعذور للصحيح","answer":"الجواب: هذا فيه تفصيل: إذا كان المعذور عذره لا يمنع شيئًا من واجبات الصلاة، ولا من أركانها؛ فلا بأس أن يؤم، مثل إنسان مقطوع اليد، أو مقطوع بعض الأصابع، أو نحو ذلك؛ لا بأس أن يؤم الناس، أما كون عذره يمنعه من القيام، يجلس فلا يؤمهم وهو جالس... يقدمون من يؤمهم غيره إلا إذا كان هو إمام الحي، هو الإمام الراتب، هو إمام المسجد؛ فلا بأس أن يؤمهم وهو جالس، كما أم النبي ﷺ أصحابه وهو جالس لما مرض -عليه الصلاة والسلام- أمهم وهو جالس، وقال: إنما جعل الإمام ليؤتم به، فإذا صلى قاعدًا؛ فصلوا قعودًا. فإذا كان إمامهم الراتب، وصلى قاعدًا؛ صلوا خلفه قعودًا، وإن صلوا قيامًا؛ فلا حرج، أجزأهم كما فعله النبي ﷺ في آخر حياته، فإنه صلى بهم قاعدًا، وصلوا خلفه قيامًا، ولم يأمرهم بالجلوس؛ فدل على الجواز. أما إذا كان ليس إمام الحي؛ فإنه لا يؤمهم وهو جالس، بل يلتمسون من يؤمهم من غير المعذورين الذين يستطيعون أن يؤموا وهم قيام. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12105/حكم-امامة-المعذور-للصحيح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48116.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13799,"question":"السائل أخوكم عبد الله من الرياض يقول في هذا  سؤالي: سمعت أنه في الصلاة يجب على المصلين في الصف الواحد أن تكون قدم كل واحد منهم ملامسة للآخر ومن يصلي بجانبه في الصف، فهل ورد في ذلك شيء سماحة الشيخ؟","title":"هل التراص في الصفوف يلزم منه ملامسة الأقدام؟","answer":"الجواب: ورد نعم عن النبي ﷺ أنه أمر برص الصفوف، أمر الصحابة أن يتراصوا في الصف وأن يسدوا الفرج، وكان بعض الصحابة يلزق قدمه من قدم صاحبه حتى لا تقع فرجة، لكن ما فيه المحاكة والإيذاء، يكون قريبًا منه حتى لا تكون فرجة، فالسنة أن يكون الصف متراصًا ليس فيه فرج هذا السنة.\nأما كونه يحاك قدم أخيه ما هو لازم المهم أن يسد الفرجة؛ لأن بعض الناس ما يتحمل هذا الحك ما يتحمل كونه يلمس رجله، فتكون حولها من دون محاكة من دون أذى لكن ما فيه فرجة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12170/هل-التراص-في-الصفوف-يلزم-منه-ملامسة-الاقدام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53619.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13806,"question":"ما حكم قراءة الفاتحة في صلاة الجماعة في الركعة الثالثة والرابعة بالنسبة للمأموم إذا لم يعط الإمام المجال للمأموم بتكملة الفاتحة؟","title":"حكم قراءة الفاتحة للمأموم في الركعتين الثالثة والرابعة","answer":"الجواب: الواجب على المأموم أن يبادر من حين يقف يقرأ الفاتحة في الثالثة والرابعة كما يقرؤها في الأولى والثانية ولا يتساهل يقرؤها قراءة متصلة حتى لا تفوته، عليه أن يبادر، فإذا كبر الإمام ولم يكملها كملها إذا كان باقي قليل، كالآية والآيتين يكملها ثم ركع، فإن خاف أن يفوته الركوع ركع وسقط عنه بقية الفاتحة؛ لأنه مأموم، مثلما لو جاء والإمام راكع ركع معه وسقطت عنه الفاتحة كما في حديث أبي بكرة الثقفي  أنه جاء والنبي ﷺ راكعًا فركع دون الصف ثم دخل في الصف وكمل الصلاة، فقال له النبي ﷺ: زادك الله حرصًا ولا تعد، ولم يأمره بقضاء الركعة، فالمأموم أسهل من الإمام والمنفرد، إذا أدرك الفاتحة قرأها وإن فاتته لكونه لم يأت إلا والإمام راكع أو عند الركوع أو كان الإمام سريع القراءة فركع قبل أن يتمها ولم يتيسر له تمامها أجزأه ذلك والحمد لله، هذا هو الصواب. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12187/حكم-قراءة-الفاتحة-للماموم-في-الركعتين-الثالثة-والرابعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_602/60206.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13813,"question":"بالنسبة لصلاة المنفرد - يا سماحة الشيخ - في الصف علمًا بأنه قد وجد في الصف الذي أمامه قد امتلأ تمامًا، ماذا يلزمه في مثل هذه الحالة؟","title":"هل يصلي وحده من وجد الصف ممتلأ؟","answer":"الجواب: نعم، لكن يكون اثنين فأكثر لا يصلي وحده، يلتمس فرجة أو يقف مع الإمام عن يمينه إلا إذا وجد معه آخر لا بأس، يصير اثنين أو أكثر خلف الصف؛ لقول النبي ﷺ: لا صلاة لمنفرد خلف الصف؛ ولأنه ﷺ رأى رجلًا يصلي خلف الصف وحده فأمره أن يعيد الصلاة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12175/هل-يصلي-وحده-من-وجد-الصف-ممتلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53621.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13855,"question":"إذا قام رجل في صلاته وصلى ركعتين مثلًا وهو في الركعة الثالثة دخله شك ولم يدر هل قرأ الفاتحة في الركعة الثانية أم لا، ولم يترجح عنده أحد الأمرين، علمًا بأن ذلك قد تكرر منه، ماذا يلزمه في ذلك؟","title":"ما يلزم من شك في عدد الركعات؟","answer":"الجواب: إذا كان الوسواس يتكرر فلا يلتفت إليه، ويحمل حاله على أنه قرأها إرغامًا للشيطان، أما إذا كان شيئًا عارضًا ليس بشيء متكرر فهذا يلغيها وتكون الثالثة بدلًا منها ويأتي بركعة زائدة ويسجد للسهو، أما إذا كان وسواس يتكرر فهذا من الشيطان ولا يلتفت إليه ويعتبرها ولا يعيد ولا يأتي بشيء بدلها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12225/ما-يلزم-من-شك-في-عدد-الركعات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53722.mp3","categories":["سجود السهو"," الوسواس بأنواعه"]},{"id":13875,"question":"يقول السائل: عندنا يسلمون على بعضهم عقب السلام مباشرة قائلين: تقبل الله منا ومنكم وغير ذلك من الأقاويل، فهل هذا جائز؟","title":"حكم المصافحة بعد الصلاة وقول تقبل الله","answer":"الجواب: هذا لا أصل له، بعد الفريضة لا أصل له، لا يصافحه ولا يقول: تقبل الله منك بعد الفريضة، أما إذا كان غير معتاد بعض الأحيان يقول: تقبل الله، هذا لا بأس، أما اعتياده كلما سلم يقول: تقبل الله، ويصافحه، لا. هذا خلاف ما شرعه الله، لم يفعله النبي ﷺ في الفرائض، كان إذا سلم قال: أستغفر الله ثلاثًا، اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام، ثم يقول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير ثلاث مرات، ثم يقول: لا حول ولا قوة إلا بالله، لا إله إلا الله ولا نعبد إلا إياه، له النعمة وله الفضل وله الثناء الحسن، لا إله إلا الله مخلصين له الدين ولو كره الكافرون، اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد.\nويذكر الله عشر مرات في الفجر والمغرب بعد هذا، عشر مرات في المغرب والفجر بعد هذا الذكر، يقول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، يحيي ويميت وهو على كل شيء قدير عشر مرات فعله النبي ﷺ، هذا هو السنة، ولا يرفع يديه بعد السلام في الفريضة، ولا يقول لأخيه: تقبل الله منك بصفة دائمة معتادة، لا. إذا قاله بعض الأحيان عند اللقاء أو إذا قاما من الصف، أو بعض الأحيان لا بأس، لكن اعتياده كأنه سنة لا. غير مشروع، لكن في النافلة لا بأس، لو رفع يديه بعد النافلة بعض الأحيان ودعا لا بأس.\nالمقدم: طيب، بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/12266/حكم-المصافحة-بعد-الصلاة-وقول-تقبل-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50604.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13889,"question":"يقول السائل: عندنا يسلمون على بعضهم عقب السلام مباشرة قائلين: تقبل الله منا ومنكم وغير ذلك من الأقاويل، فهل هذا جائز؟","title":"حكم المصافحة بعد الصلاة وقول تقبل الله","answer":"الجواب: هذا لا أصل له، بعد الفريضة لا أصل له، لا يصافحه ولا يقول: تقبل الله منك بعد الفريضة، أما إذا كان غير معتاد بعض الأحيان يقول: تقبل الله، هذا لا بأس، أما اعتياده كلما سلم يقول: تقبل الله، ويصافحه، لا. هذا خلاف ما شرعه الله، لم يفعله النبي ﷺ في الفرائض، كان إذا سلم قال: أستغفر الله ثلاثًا، اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام، ثم يقول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير ثلاث مرات، ثم يقول: لا حول ولا قوة إلا بالله، لا إله إلا الله ولا نعبد إلا إياه، له النعمة وله الفضل وله الثناء الحسن، لا إله إلا الله مخلصين له الدين ولو كره الكافرون، اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد.\nويذكر الله عشر مرات في الفجر والمغرب بعد هذا، عشر مرات في المغرب والفجر بعد هذا الذكر، يقول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، يحيي ويميت وهو على كل شيء قدير عشر مرات فعله النبي ﷺ، هذا هو السنة، ولا يرفع يديه بعد السلام في الفريضة، ولا يقول لأخيه: تقبل الله منك بصفة دائمة معتادة، لا. إذا قاله بعض الأحيان عند اللقاء أو إذا قاما من الصف، أو بعض الأحيان لا بأس، لكن اعتياده كأنه سنة لا. غير مشروع، لكن في النافلة لا بأس، لو رفع يديه بعد النافلة بعض الأحيان ودعا لا بأس.\nالمقدم: طيب، بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/12266/حكم-المصافحة-بعد-الصلاة-وقول-تقبل-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50604.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13897,"question":"يقول يا سماحة الشيخ عبدالعزيز: إذا دخلت المسجد ووجدت الإمام في جلوس التشهد الأخير، وبعد قيامي لإكمال الصلاة رأيت جماعة جديدة، فهل يمكنني قطع هذا القيام والانضمام إلى الجماعة الجديدة للصلاة؟","title":"حكم قطع المسبوق التشهد الأخير لأجل جماعة جديدة","answer":"الجواب: لا حرج في ذلك؛ لأن هذا قطع لما هو أفضل وهو الصلاة معهم، وإن أتممت فلا حرج، إن أتممت فلا حرج وإن قطعتها وذهبت مع الجماعة فذلك أفضل؛ لما في ذلك من أدائها جماعة. نعم.","link":"https://binbaz.org.sa/fatwas/12267/حكم-قطع-المسبوق-التشهد-الاخير-لاجل-جماعة-جديدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53808.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13902,"question":"ما حكم صلاة المنفرد خلف الصف؟","title":"حكم صلاة المنفرد خلف الصف","answer":"الجواب: لا تصح؛ لقول النبي ﷺ: لا صلاة لمنفرد خلف الصف، ولما رأى رجلًا يصلي خلف الصف وحده أمره أن يعيد الصلاة عليه الصلاة والسلام له: ولم يسأله ما قال وهل وجدت فرجة أو ما وجدت فرجة، أمره أن يعيد سدًا للباب، فليس لأحد أن يصف خلف الصف، بل ينتظر إن لم يجد فرجة ينتظر أو يتقدم مع الإمام إن تيسر يصلي عن يمين الإمام أو يصبر حتى يجد فرجة أو يجيء أحد يصلي معه، فإن انتهت الصلاة صلى وحده.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12288/حكم-صلاة-المنفرد-خلف-الصف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48202.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":13935,"question":"من جازان السائلة أم محمد تقول في هذا  صليت صلاة العصر وعند سجودي لا أدري هل سجدت سجدة أم سجدتين، وأكملت بسجود السهو دون أن أسجد سجدة أخرى رغم شكي، فهل صلاتي صحيحة؟","title":"حكم من شك أنه لم يسجد إحدى السجدات","answer":"الجواب: هذا فيه تفصيل، إن كان الشك ما فيه ترجيح فالواجب عليك أن تأتي بالسجدة الثانية وتكملي صلاتك ثم تسجدي السهو، وإن لم تفعلي فعليك أن تأتي بركعة زائدة تبطل الركعة التي تركت منها السجدة وتأتين بركعة زائدة بدلًا منها، وعليك سجود السهو، فإذا شكيت في إحدى الركعات هل سجدت سجدتين أو واحدة ولم تأت بالسجدة الثانية فعليك أن تأتي بركعة زائدة، ثم بعد كمال التحيات والدعاء تسجدين للسهو سجدتين.\nأما إن كان الشك مع الظن، يعني: ظننت وغلب على ظنك أنك سجدت سجدتين فلا شيء عليك وسجود السهو يكفي، سجود السهو يكفي والحمد لله، ولكن عليك دائمًا أن تحتاطي وأن تتعوذي بالله من الشيطان؛ لأن الشيطان قد يؤذي بالوساوس، فإذا حصل الشك فابني على اليقين، فإذا شكيت هل صليت ثنتين أو ثلاث اجعليها ثنتين ثم كملي الصلاة، وإذا شكيت هل سجدت واحدة أو ثنيتن اسجدي الثانية.\nأما إذا غلب على ظنك أنك ما سهيت وأنك فعلت الصواب فكملي الصلاة واسجدي للسهو سجدتين بعد السلام أفضل، إذا كنت فعلت ذلك عن ظن وعن غلبة ظن، أما مع الشك لا، مع الشك عليك باليقين، إذا شككت فلابد من اليقين، إذا شكيت هل سجدت أو ما سجدت الثانية اسجدي، وإذا شكيت صليت ثنتين أو ثلاث اجعليها ثنتين وكملي الصلاة ثم اسجدي للسهو قبل السلام، وإن سجدت بعد السلام فلا بأس.\nأما مع غلبة الظن فإنه يكفي سجود السهو، تبنين على غالب الظن وتسجدين للسهو، والأفضل في هذا المقام أن يكون سجود السهو بعد السلام إذا كان البناء على غالب الظن.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12331/حكم-من-شك-انه-لم-يسجد-احدى-السجدات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_544/54416.mp3","categories":["سجود السهو"]},{"id":14063,"question":"المستمع (ع. د. م) بعث برسالة يسأل فيها ويقول: إذا دخل رجل المسجد وسجد الإمام سجود السهو، فهل يجوز أن يسجد معه ثم يكمل صلاته؟ أم يكمل ولا يسجد معه وذلك قبل السلام؟","title":"هل يتابع المسبوق الإمام في سجود السهو؟","answer":"الجواب: يسجد معه أول ثم إذا سلم إمامه يقوم، يسجد معه للسهو، ثم إذا سلم إمامه يقوم ويقضي ما عليه، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12478/هل-يتابع-المسبوق-الامام-في-سجود-السهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48404.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14091,"question":"ما حكم السهو في الصلاة؟","title":"حكم حالات السهو في الصلاة","answer":"الجواب: السهو في الصلاة يقع من الناس، حتى من الأنبياء، ولكن النبي بين ﷺ حكم السهو، وهو أقسام وأنواع، فإذا سها المصلي عن التشهد الأول أو عن التكبيرات بعض التكبيرات التي غير التكبيرة الأولى غير تكبيرة الإحرام، تكبير الركوع أو السجود أو نحو ذلك، يسجد للسهو سجدتين قبل أن يسلم، والحمد لله إذا كان إمامًا أو منفردًا، أما المأموم فلا يسجد بل هو تابع لإمامه.\nأما إن كان السهو شك بأن شك الرجل أو المرأة وهو إمام أو منفرد، هل صلى ثنتين أو ثلاث من الظهر أو العصر أو المغرب أو العشاء؛ يجعلها ثنتين، يعمل باليقين، يعني: بالأقل، ثم يكبر ويسجد للسهو سجدتين قبل أن يسلم، فإذا شك في الظهر أو العصر أو العشاء هل صلى ثلاثًا أم أربعًا تردد؛ يجعلها ثلاثًا، يحتاط يبني على الأقل، ثم يأتي بالرابعة، فإذا فرغ سجد سجدتين قبل أن يسلم.\nهذا هو المشروع في حقه، وإذا نسي التشهد الأول قام إلى الثالثة ما تشهد الأول ناسيًا وهو إمام أو منفرد؛ سجد للسهو بعد الفراغ قبل أن يسلم، وإن كان مأمومًا؛ فليس عليه سجود، بل هو تابع لإمامه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12539/حكم-حالات-السهو-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_610/61009.mp3","categories":["سجود السهو"]},{"id":14134,"question":"رجل صلى بجماعة بنية صلاة غير الصلاة الحاضرة فهل تبطل صلاتهم؟","title":"حكم اختلاف نية الإمام والمأمومين في الصلاة","answer":"الجواب: لا، لا بأس بذلك، إذا صلى رجل بجماعة العصر وصلى معه أناس الظهر فلا حرج، صلاتهم صحيحة على الصحيح، وقد كان معاذ  يصلي مع النبي العشاء عليه الصلاة والسلام ثم يرجع فيصلي بجماعته العشاء نفلًا له وفرضًا لهم، فلا بأس أن يصلي من عليه الظهر خلف من يصلي العصر ثم يصلي العصر بعد ذلك. نعم.\nالمقدم: جزاكم الله خيرًا، سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12575/حكم-اختلاف-نية-الامام-والمامومين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_615/61511.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14139,"question":"في ثاني أسئلته يقول: إذا ترك الإنسان سجدة ولم يدر أي الركعات كانت مع العلم بأنني كنت في الركعة الأخيرة؟","title":"حكم من ترك سجدة ولم يذكر من أي ركعة","answer":"الجواب: إذا ترك سجدة ولم يدر من أي الركعات يأتي بركعة زائدة قبل أن يسلم، يقوم يأتي بركعة بدل الركعة التي ترك منها السجدة ثم يسجد للسهو ثم يسلم. نعم.\nيعني: يسجد للسهو بعد التشهد، بعدما يأتي بالتشهد التحيات والدعاء الشرعي يسجد للسهو ثم يسلم. نعم.","link":"https://binbaz.org.sa/fatwas/12580/حكم-من-ترك-سجدة-ولم-يذكر-من-اي-ركعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54604.mp3","categories":["سجود السهو"]},{"id":14205,"question":"يقول هذا السائل: عندما يكون الشخص يصلي وفجأة وسوس له الشيطان ونسي كم صلى ربما يزيد ركعة فكيف يتصرف في هذه الحالة يا سماحة الشيخ؟","title":"حكم من شك في عدد الركعات أثناء الصلاة","answer":"الجواب: إذا وسوس إليه الشيطان ونسي هل صلى ثلاثًا أم أربعًا يجعلها ثلاثًا ثم يأتي بالرابعة ويكملها ويسجد للسهو سجدتين قبل أن يسلم، وإذا كان في الثانية وشك في الثانية والثالثة يجعلها الثانية، يعني: يبني على الأقل، لما ثبت عنه أنه قال ﷺ: إذا شك أحدكم في صلاته فلم يدر كم صلى ثلاثًا أم أربعًا فليطرح الشك وليبن على ما استيقن ثم ليسجد سجدتين قبل أن يسلم، فإن كان صلى خمسًا شفعن له صلاته، وإن كان صلى تمامًا كانتا ترغيمًا للشيطان أخرجه مسلم في الصحيح من حديث أبي سعيد الخدري .\nالمقصود أنه يبني على اليقين، إذا شك يبني على الأقل يعني، إذا شك هل صلى ثلاث في الظهر أو في العصر أو العشاء أو أربع يجعلها ثلاث، شك هل صلى ثنتين أو ثلاث يجعلها ثنتين، وهكذا في المغرب لو شك هي ثنتين أو ثلاث يجعلها ثنتين، والفجر شك هل صلى واحدة أو ثنتين يجعلها واحدة، ثم يكمل ثم يسجد للسهو سجدتين قبل أن يسلم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12653/حكم-من-شك-في-عدد-الركعات-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54806.mp3","categories":["سجود السهو"]},{"id":14233,"question":"يقول هذا السائل: إذا دخلت المسجد وكان الإمام قد رفع من الركوع للركعة الأخيرة، فهل أدخل مع الجماعة؟ أم أنتظر حتى يأتي رجل فأصلي معه جماعة أخرى بعد تسليم الإمام الراتب؟","title":"ما يعمل من دخل المسجد والإمام في نهاية الصلاة؟","answer":"الجواب: إذا دخلت مع الإمام فكمل، إذا سلم الإمام تقضي الصلاة كلها إلا إذا كنت أدركته في الركوع قبل أن يرفع فقد أدركت الركعة الأخيرة، أما إذا رفع قبل أن تدركه في الركوع فإنك ما أدركت شيئًا فعليك أن تقضي الصلاة كلها بعد سلامه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12693/ما-يعمل-من-دخل-المسجد-والامام-في-نهاية-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_549/54905.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14257,"question":"المستمع شوقي قادر علي من اليمن له عدة أسئلة يسأل في سؤاله الأول ويقول: اعتاد بعض الناس عندما يدخل المسجد ويجد الإمام راكعًا أن يقولوا: إن الله مع الصابرين [البقرة:153]، يقصدون بذلك بقاء الإمام راكعًا حتى يدركوا الركعة معه، وبعض الأئمة ينتظرونهم مع أن هذا فيه مشقة على بعض المصلين، فما حكم قولهم هذا وما حكم انتظار الإمام لهم؟","title":"حكم قول \"إن الله مع الصابرين\" للإمام حتى يطيل الركوع","answer":"الجواب: لا أعلم أصلًا لقولهم: إن الله مع الصابرين [البقرة:153]، أو اصبر، أو ما أشبه ذلك لا نعلم لهذا أصلًا، ولا نعلم في ذلك منكرًا ولا محذورًا. وأما الإمام فيستحب له أن يتأنى قليلًا حتى يدرك من دخل على وجه لا يشق على المأمومين، فقد نص جمع من أهل العلم على ذلك وقالوا: يستحب له انتظار داخل ما لم يشق على المأموم، فإذا كان انتظاره يسيرًا لا يشق على الناس فلا حرج بذلك بل يستحب له ذلك مراعاة للداخلين حتى يدركوا الركعة، وهم يستحب لهم عدم العجلة والخشوع وعدم العجلة فإن أدركوا فالحمد لله وإلا قضوها ولا ينبغي لهم العجلة. أما كلمة: اصبر أو إِنَّ اللَّهَ مَعَ الصَّابِرِينَ [البقرة:153] فلا أعلم لها أصلًا في الشرع، ولا أعلم ما يمنعها من باب التنبيه للإمام ومن باب التذكير لا نعلم في هذا مانعًا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12746/حكم-قول-ان-الله-مع-الصابرين-للامام-حتى-يطيل-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_621/62106.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14262,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول المستمع أبو فهد، أبو فهد رسالته مطولة في الواقع ملخص ما فيها يسأل عن حكم اصطحاب الأطفال للمساجد، هل هو سنة كما يقول البعض؟ أم أنه غير جائز لما يسببه الأطفال من إزعاج للمصلين كما يقول البعض الآخر؟","title":"حكم اصطحاب الأطفال إلى المساجد","answer":"الجواب: استصحاب الأطفال فيه تفصيل: فإن كان الطفل قد أكمل السبع السنين فهو مأمور بالصلاة فيستصحبه أبوه أو أخوه حتى يتمرن على الصلاة ويعتادها ويحافظ عليها، أما إن كان أقل من السبع فلا حاجة إلى ذلك ولا يشرع استصحابه؛ لأنه قد يؤذي المصلين، قد يشوش عليهم في لعبه وكلامه الذي لا وجه له، فالأولى عدم استصحابهم لما في ذلك من الإيذاء للمصلين. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12729/حكم-اصطحاب-الاطفال-الى-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_621/62102.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14272,"question":"المستمع أحمد علي بعث يسأل ويقول: أرى كثيرًا من الناس يصلون في محل أشغالهم ويقولون: إن هذا الشغل معهم ويضطرون إلى العمل ثم يصلون فيه، فما حكم فعلهم هذا جزاكم الله خيرًا، إذ أني سمعت حديثًا معناه من سمع النداء ولم يجب فلا صلاة له؟","title":"حكم ترك صلاة الجماعة لأجل العمل","answer":"الجواب: الواجب على الرجال في كل مكان أن يصلوا في الجماعة؛ لقول النبي ﷺ: من سمع النداء فلا صلاة له إلا من عذر، وهو حديث صحيح قيل لـابن عباس: ما هو العذر؟ قال: مرض أو خوف، ولما ثبت عنه ﷺ أنه جاءه رجل أعمى فقال: يا رسول الله! ليس لي قائد يقودني للمسجد فهل لي من رخصة أن أصلي في بيتي؟ قال: هل تسمع النداء بالصلاة؟ قال: نعم، قال:  فأجب، ولما ثبت عنه ﷺ أنه قال: لقد هممت أن آمر بالصلاة فتقام ثم آمر رجلًا فيؤم الناس، ثم أنطلق برجال معهم حزم من حطب إلى رجال لا يشهدون الصلاة فأحرق عليهم بيوتهم، وهذا يدل على وجوب أداء الصلاة في الجماعة.\nفالواجب على جميع الرجال القادرين أن يصلوا في الجماعة في المساجد لا في موضع العمل، إذا كان المسجد قريبًا يسمعون النداء، أما إذا كان بعيدًا لا يسمعون النداء فإنه لا حرج أن يصلوا في مكانهم جماعة، يعني: سماع النداء بالصوت المعتاد لا بالمكبر، أما المكبر فيسمع من بعيد لكن إذا كانوا يسمعونه بالصوت المعتاد إذا كان على محل مرتفع وكان الجو مناسبًا ليس فيه ما يمنع الصوت إذا كانوا يسمعونه يعني: في محل يسمعون مثل هذا وجب عليهم السعي وبكل حال فكونهم يسعون إلى المساجد ولو بالسيارة فهذا هو الخير لهم وهذا هو الأفضل لهم وفيه امتثال أمر الله ورسوله.\nأما إن كانوا بعيدين يشق عليهم الذهاب إلى المسجد ولو كان الأذان بالصوت المعتاد ما سمعوه لبعده فلا حرج عليهم أن يصلوا جماعة في محلهم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12727/حكم-ترك-صلاة-الجماعة-لاجل-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_486/48610.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14278,"question":"هذا سائل للبرنامج يقول: ما حكم الشرع في نظركم في رجل لا يصلي في المسجد إلا يوم الجمعة؟ ما حكم أكلنا لذبيحته وجهونا بذلك؟","title":"حكم من لا يصلي في المسجد إلا الجمعة وحكم أكل ذبيحته","answer":"الجواب: يجب على المسلم أن يصلي جميع الصلوات في المسجد، والذي لا يصلي في المسجد ينكر عليه ويعلم ويوجه إلى الخير، ولا يتشبه بالمنافقين، وإذا عاند ولم يقبل يستحق أن يهجر ولا تقبل عزيمته ولا الأكل معه حتى يتوب، أما إذا أرشدتموه وقبل وصلى مع الناس فالحمد لله.","link":"https://binbaz.org.sa/fatwas/12738/حكم-من-لا-يصلي-في-المسجد-الا-الجمعة-وحكم-اكل-ذبيحته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_549/54916.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14308,"question":"يسأل أخونا ويقول: ما حكم إذا صليت وراء إمام مكروه عندي؟","title":"حكم صلاة الرجل خلف إمام يكرهه","answer":"الجواب: إذا كنت لا تعلم فيه مكفرًا فصلاتك صحيحة، ولو كرهته الصلاة صحيحة؛ لأنك قد تكرهه بغير حق، وقد تكرهه بشيء لا يوجب كراهته وإن كان عنده بعض المعاصي فلا يمنع ذلك صحة الصلاة، فقد صلى بعض الصحابة خلف الحجاج بن يوسف الثقفي وهو من أظلم الناس، فالمعصية لا تمنع صحة الصلاة خلف الإمام إذا كان مسلمًا وليس بكافر؛ لأن المعاصي قل من يسلم منها، ولا حول ولا قوة إلا بالله. فالمقصود: أن صلاتك خلف من تكره إذا كان مسلمًا صحيحة؛ لأنك أنت غير معصوم، قد تكرهه بغير حق، وقد تكرهه لشيء صحيح لكن لا يمنع صحة الصلاة، وفق الله الجميع.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/12800/حكم-صلاة-الرجل-خلف-امام-يكرهه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_622/62210.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14414,"question":"هذا سائل للبرنامج أرسل بهذا السؤال، لم يذكر الاسم في هذه الرسالة، يقول: هل الصبي يقطع صف الصلاة حيث إن بعض الأشخاص يحضرون معهم أبناءهم الصغار جدًا، ويقف الابن بجانبه، ثم يقف المصلي الآخر بجانب الطفل؟","title":"حكم إقامة الطفل وسط الصفوف","answer":"الجواب: الأولى لأولياء الأطفال أن لا يأتوا بهم إلى الصلاة إذا كانوا دون السبع، الأولى أن يبقوا في بيوتهم عند أهليهم، أما إذا كان ابن سبعة، عشرة فإنه لا يقطع الصف، بل يصف مع الرجال ويعتبر، لكن ذلك دون السبع تركه مع أهل البيت أولى وأفضل، حتى لا يتأذى به الناس، فلو وجد مع أبيه لا يقطع الصف لا حرج -إن شاء الله- كاللبنة بين الصفين أو العمود بين الصفين لا يضر. المقصود: أنه إذا كان وجد ودعت الحاجة إليه؛ لأن أباه قد يأتي به؛ لأنه يضر أهله لو بقى عند أهله، كما يروى أن الحسن قد يأتي والنبي ﷺ يصلي بالناس فيرتحله وهو ساجد، وكما صلى النبي ﷺ بـأمامة بنت زينب بنته للحاجة والتعليم يعلم الناس مثل هذا لا يضر، فإذا دعت الحاجة إلى مثل هذا، وكان أبوه لا يستطيع بقاءه عند أهل البيت، أو ما عنده في البيت أحد فيكون معذور، ويكون مثل حجر بين الصفين أو الكرسي بين الصفين، أو ما أشبه ذلك، قد تدعو الحاجة إلى هذا الشيء فلا يضر -إن شاء الله-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12896/حكم-اقامة-الطفل-وسط-الصفوف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55311.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14485,"question":"هل للمصلي أن يقتدي بالمصلين في المذياع أيضًا أو لا يجوز ذلك؟","title":"هل للمصلي أن يقتدي بالمصلين في المذياع؟","answer":"الجواب: لا، لا يقتدي به، لا يقتدي به، إلا إذا كان في المسجد يسمع صوت الإمام، أما في بيته، أو في المحلات الأخرى، لا يقتدي به، بل عليه أن يسعى إلى المسجد، ويصلي مع الناس، وأما إذا كان في بيته، أو في مكان آخر يصلي وحده، لا يصلي بالإمام، ولا يأتم بالإمام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12959/هل-للمصلي-ان-يقتدي-بالمصلين-في-المذياع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_488/48810.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14506,"question":"هذه رسالة من السائل (ع. م) من الرياض، له سؤالان في رسالته، في سؤاله الأول يقول: ما حكم ائتمام من يقصر بمن يتم صلاته أو العكس؟ وكيف يفعلان؟","title":"حكم ائتمام المقيم بالمسافر","answer":"الجواب: إذا ائتم من يقصر الصلاة، إذا أم من يقصر الصلاة بمن يتمها، فإنه إذا سلم من صلاته ثنتين يقوم المقيم فيتم أربعًا، إذا كان الإمام هو المسافر، فيصلي ثنتين، ثم إذا سلم يقوم من وراءه فيصلون أربعًا إذا كانوا مقيمين غير مسافرين والمسافرون يسلمون معه، هذا إذا كان الإمام هو المسافر. أما إذا كان الإمام هو المقيم، والمسافرون خلفه، فإنهم يتمون معه، وليس لهم القصر، بل يتمون معه أربعًا، وليس لهم القصر خلف من يتم أربعًا؛ لما ثبت في الصحيح من حديث ابن عباس -رضي الله تعالى عنهما- «أنه سئل عمن يصلي خلف الإمام، قالوا له: يا أبا العباس ما لنا إذا صلينا خلف الإمام صلينا أربعًا، وإذا صلينا في رحالنا صلينا اثنتين؟ فقال: «هكذا السنة» رواه الإمام أحمد في مسنده، بإسناد جيد، وأصله في صحيح مسلم.  وهذا يدل على أنّ صلاة المسافر خلف الإمام المقيم يجب أن تكمل أربعًا للحديث المذكور، والله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/12994/حكم-اىتمام-المقيم-بالمسافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_633/nour_63302.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14507,"question":"أرى بعض المصلين حينما يدخلون المسجد والجماعة في التشهد لا يشرعون في دخول الصلاة حتى يتأكدون من التشهد هل هو الأول أم الثاني؟ فإن كان الأول دخلوا مع الجماعة، وإن كان الثاني صلوا منفردين، أرجو منكم الإجابة الواضحة، وهل يجب على من دخل المسجد ووجد الناس في الصلاة أن يدخل معهم في أي حال؟ وكم تكبيرة يكبر لو وجدهم في الركوع أو السجود؟ وهل يقرأ دعاء الاستفتاح قبل الركوع أو السجود؟","title":"ما المشروع لمن دخل والإمام في الصلاة؟","answer":"الجواب: السنة لمن دخل والإمام في الصلاة أن يصلي لينضم إليهم، ويصلي معهم؛ لأنه جاءت أحاديث عن رسول الله ﷺ تدل على أن من جاء والإمام في حال فإنه يصنع ما يصنع الإمام، فإن وجده قائمًا صف معه، وجده راكعًا ركع، وجده ساجدًا سجد، وجده جالسًا جلس، وقال في هذا -عليه الصلاة والسلام-: ما أدركتم فصلوا، وما فاتكم فأتموا فيكبر تكبيرة الإحرام وهو واقف، ثم يقرأ الفاتحة إن أمكنه، ثم ينصت لقراءة الإمام إن كانت جهرية، حتى.... يركع ويركع معه، وإن كانت سرية كالظهر، والعصر قرأ معه الفاتحة، وقرأ ما تيسر معه في الأولى والثانية؛ لأنها سرية، وإن جاء وهو راكع ركع معه، كبر وركع، كما فعل أبو بكرة  فإنه جاء والنبي ﷺ راكع فركع دون الصف، ثم دخل في الصف، فلما سلّم النبي ﷺ قال له: زادك الله حرصًا، ولا تعد يعني: لا تعود إلى الركوع دون الصف، فدل ذلك على أن ركعته مجزئة، وأن صلاته صحيحة، ولكنه لا ينبغي له أن يدخل في الصلاة منفردًا، بل ينضم إلى الصف، فإن أمداه وأمكنه أن يركع معهم ركع، وإلا قضى ما فاته. والمشروع أن يكبر تكبيرتين: الأولى: تكبيرة الإحرام هذه فرض لا بد منها، والثانية للركوع إذا أراد أن ينحط للركوع وأمكنه يكبر الثانية؛ لأنها واجبة عند جمع من أهل العلم، ومستحبة عند الجمهور، فينبغي الإتيان بها إذا أمكنه، فإن خشي فوات الركوع كفته التكبيرة الأولى، وهي تكبيرة الإحرام تكفيه عند جمع من أهل العلم، والحمد لله؛ لأن العبادتين إذا اجتمعتا وإحداهما أكبر من الأخرى دخلت الصغرى في الكبرى كهذه الحالة، نعم. المقدم: جزاكم الله خيرًا، بالنسبة لدعاء الاستفتاح؟\nالجواب: مستحب دعاء الاستفتاح إذا جاء والإمام واقف وفيه سعة يستفتح بسبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك أو بأي نوع من أنواع الاستفتاحات الصحيحة، ثم يقرأ الفاتحة، أما إن كان الوقت ضيقًا، ويخشى أن يركع، يشتغل بالفاتحة، ويسقط الاستفتاح؛ لأنه سنة، والفرض أهم، الفاتحة أهم، فيبدأ بها حتى لا يركع الإمام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13018/ما-المشروع-لمن-دخل-والامام-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_626/nour_62608.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14509,"question":"هل يجوز لي أن أصلي مع المتنفل بنية الفرض إذا دخلت المسجد والصلاة قد انتهت، أم لا يجوز؟ وماذا أفعل إذا كنت أصلي النافلة ودخل المسجد أحد المصلين وصلى معي ظنًا منه أنني أصلي الفرض، هل يجوز أن أكون له إمامًا، أم أدفعه بعيدًا، أم أبتعد عنه؟أفيدوني، جزاكم الله خيرًا.","title":"هل يجوز صلاة الفريضة خلف المتنفل؟ والعكس؟","answer":"الجواب: لا حرج في أن تصلي مع المتنفل وأنت ناو الفرض؛ لأن الجماعة مطلوبة، ولا حرج أيضًا أن تصلي بمن دخل معك، وهو قد فاتته الفرض أن تصلي به، وتنوي الإمامة؛ لأن الجماعة مطلوبة، هذا هو الصواب. وذهب بعض أهل العلم إلى أن هذا لا يصلح إلا في النافلة. والصواب: أنه يجوز في الفرض والنفل، والدليل على هذا أن معاذًا  كان يصلي مع النبي العشاء -عليه الصلاة والسلام- فرضه، ثم يذهب إلى قومه فيصلي بهم فرضهم وهو متنفل، هو يصلي نفلًا؛ لأنه قد صلاها مع النبي ﷺ، ويصلي بهم فرضهم، فدل ذلك على أنه يجوز للمفترض أن يصلي خلف المتنفل، ومن ذلك ما صح عنه ﷺ في بعض أنواع صلاة الخوف أنه صلى بطائفة ركعتين ثم سلم، ثم صلى بآخرين ركعتين، فكانت الأولى له فرضًا، وكانت الثانية له نفلًا -عليه الصلاة والسلام-، فهذا هو الدليل على أنه لا حرج أن يكون المتنفل إمامًا للمفترض، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13016/هل-يجوز-صلاة-الفريضة-خلف-المتنفل-والعكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_626/nour_62607.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14513,"question":"هذه رسالة من السائل (ع. م) من الرياض، له سؤالان في رسالته، في سؤاله الأول يقول: ما حكم ائتمام من يقصر بمن يتم صلاته أو العكس؟ وكيف يفعلان؟","title":"حكم ائتمام المقيم بالمسافر","answer":"الجواب: إذا ائتم من يقصر الصلاة، إذا أم من يقصر الصلاة بمن يتمها، فإنه إذا سلم من صلاته ثنتين يقوم المقيم فيتم أربعًا، إذا كان الإمام هو المسافر، فيصلي ثنتين، ثم إذا سلم يقوم من وراءه فيصلون أربعًا إذا كانوا مقيمين غير مسافرين والمسافرون يسلمون معه، هذا إذا كان الإمام هو المسافر. أما إذا كان الإمام هو المقيم، والمسافرون خلفه، فإنهم يتمون معه، وليس لهم القصر، بل يتمون معه أربعًا، وليس لهم القصر خلف من يتم أربعًا؛ لما ثبت في الصحيح من حديث ابن عباس -رضي الله تعالى عنهما- «أنه سئل عمن يصلي خلف الإمام، قالوا له: يا أبا العباس ما لنا إذا صلينا خلف الإمام صلينا أربعًا، وإذا صلينا في رحالنا صلينا اثنتين؟ فقال: «هكذا السنة» رواه الإمام أحمد في مسنده، بإسناد جيد، وأصله في صحيح مسلم.  وهذا يدل على أنّ صلاة المسافر خلف الإمام المقيم يجب أن تكمل أربعًا للحديث المذكور، والله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/12994/حكم-اىتمام-المقيم-بالمسافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_633/nour_63302.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14514,"question":"أرى بعض المصلين حينما يدخلون المسجد والجماعة في التشهد لا يشرعون في دخول الصلاة حتى يتأكدون من التشهد هل هو الأول أم الثاني؟ فإن كان الأول دخلوا مع الجماعة، وإن كان الثاني صلوا منفردين، أرجو منكم الإجابة الواضحة، وهل يجب على من دخل المسجد ووجد الناس في الصلاة أن يدخل معهم في أي حال؟ وكم تكبيرة يكبر لو وجدهم في الركوع أو السجود؟ وهل يقرأ دعاء الاستفتاح قبل الركوع أو السجود؟","title":"ما المشروع لمن دخل والإمام في الصلاة؟","answer":"الجواب: السنة لمن دخل والإمام في الصلاة أن يصلي لينضم إليهم، ويصلي معهم؛ لأنه جاءت أحاديث عن رسول الله ﷺ تدل على أن من جاء والإمام في حال فإنه يصنع ما يصنع الإمام، فإن وجده قائمًا صف معه، وجده راكعًا ركع، وجده ساجدًا سجد، وجده جالسًا جلس، وقال في هذا -عليه الصلاة والسلام-: ما أدركتم فصلوا، وما فاتكم فأتموا فيكبر تكبيرة الإحرام وهو واقف، ثم يقرأ الفاتحة إن أمكنه، ثم ينصت لقراءة الإمام إن كانت جهرية، حتى.... يركع ويركع معه، وإن كانت سرية كالظهر، والعصر قرأ معه الفاتحة، وقرأ ما تيسر معه في الأولى والثانية؛ لأنها سرية، وإن جاء وهو راكع ركع معه، كبر وركع، كما فعل أبو بكرة  فإنه جاء والنبي ﷺ راكع فركع دون الصف، ثم دخل في الصف، فلما سلّم النبي ﷺ قال له: زادك الله حرصًا، ولا تعد يعني: لا تعود إلى الركوع دون الصف، فدل ذلك على أن ركعته مجزئة، وأن صلاته صحيحة، ولكنه لا ينبغي له أن يدخل في الصلاة منفردًا، بل ينضم إلى الصف، فإن أمداه وأمكنه أن يركع معهم ركع، وإلا قضى ما فاته. والمشروع أن يكبر تكبيرتين: الأولى: تكبيرة الإحرام هذه فرض لا بد منها، والثانية للركوع إذا أراد أن ينحط للركوع وأمكنه يكبر الثانية؛ لأنها واجبة عند جمع من أهل العلم، ومستحبة عند الجمهور، فينبغي الإتيان بها إذا أمكنه، فإن خشي فوات الركوع كفته التكبيرة الأولى، وهي تكبيرة الإحرام تكفيه عند جمع من أهل العلم، والحمد لله؛ لأن العبادتين إذا اجتمعتا وإحداهما أكبر من الأخرى دخلت الصغرى في الكبرى كهذه الحالة، نعم. المقدم: جزاكم الله خيرًا، بالنسبة لدعاء الاستفتاح؟\nالجواب: مستحب دعاء الاستفتاح إذا جاء والإمام واقف وفيه سعة يستفتح بسبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك أو بأي نوع من أنواع الاستفتاحات الصحيحة، ثم يقرأ الفاتحة، أما إن كان الوقت ضيقًا، ويخشى أن يركع، يشتغل بالفاتحة، ويسقط الاستفتاح؛ لأنه سنة، والفرض أهم، الفاتحة أهم، فيبدأ بها حتى لا يركع الإمام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13018/ما-المشروع-لمن-دخل-والامام-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_626/nour_62608.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14541,"question":"السائل من السودان استعرضنا بعضًا من أسئلته، بقي له هذا السؤال يقول: سماحة الشيخ، إذا كان الناس بقرية، ويغلب عليهم الجهل بالدين، هل يجوز لهم أن يتخذوا مصلى آخر خلاف مسجد القرية؟ وإذا كانت مداومة الصلاة فيه تؤدي إلى الفتنة عند مناصحتهم ما حكم ذلك؟","title":"حكم اتخاذ أكثر من مسجد في القرية","answer":"الجواب: الواجب على أهل القرية أن يصلوا جميعًا في مسجد واحد، وأن يتعاونوا على البر والتقوى؛ لأن الصلاة في داخل المسجد يعينهم على الخير والتعارف والتواصي بالحق والنصيحة، ولا يريد نصيحته من تيسر له أن ينصحهم جميعًا. أما إذا كانت القرية كبيرة تباعدت أطرافها، وجعلوا مسجدين للتباعد فلا بأس لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] إذا كان في مشقة، يجعل في جانبها الأيمن مسجد والآخر مسجد، أو في شرقها مسجد وغربها مسجد إذا كانت متباعدة يشق عليهم أن يجتمعوا في مسجد واحد، فلا حرج، والواجب عليهم التعاون على البر والتقوى والتواصي والتناصح، والحذر من أسباب الشحناء، والله المستعان، نعم.","link":"https://binbaz.org.sa/fatwas/13038/حكم-اتخاذ-اكثر-من-مسجد-في-القرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_555/55504.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14551,"question":"ما هو واجب إمام المسجد في حيه وتجاه جماعته في المسجد؟","title":"ما واجب الإمام تجاه جماعة مسجده؟","answer":"الجواب: الواجب عليه تفقدهم، وملاحظتهم، ونصيحتهم، وأن لا يشق عليهم بالتأخير، ولا بالتبكير، تكون صلاته وسط حسب التوجيهات التي إليه من المسؤولين عن الصلاة، يصلي حسب التوجيه، يحذر من التأخير الذي يضرهم، أو التقديم الذي يضرهم، يكون مراعيًا للأوقات التي حددت له، والتقدم اليسير أو التأخر خمس دقائق أو كذا لا يضر.  المهم أنه لا يتأخر شيئًا يضرهم، أو يتقدم شيئًا يخالف التعليم، بل يكون متحرزًا للتعليم، وإذا تأخر قليلًا بعد التعليمات خمس دقائق، أو نحوه كل هذا لا حرج فيه يراعي المصلحة في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13048/ما-واجب-الامام-تجاه-جماعة-مسجده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_555/55511.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14573,"question":"في ثاني أسئلة هذه السائلة تقول: ما حكم من يكثر من أكل الثوم لرغبته فيه وحبه له، هل يذهب إلى المسجد للصلاة فيه، أو يكفيه الصلاة في المنزل، ويتعذر بذلك؟","title":"حكم الذهاب إلى المسجد لمن أكل ثومًا أو بصلًا","answer":"الجواب: من يأكل الثوم أو البصل أو الكراث لا يجوز له الذهاب إلى المسجد؛ لأنه يؤذي الناس بذلك، والنبي نهى عن ذلك، وقال ﷺ: من أكل ثومًا أو بصلًا فليعتزلنا، وليعتزل مسجدنا، وليقعد في بيته وثبت عنه ﷺ أنه أمر بإخراج من تعاطى هذه الأمور عن المسجد، وقال: إن الملائكة تتأذى مما يتأذى منه بنو آدم. فلا يجوز للمسلم الذي يتعاطى الكراث أو الثوم أو البصل أن يصلي مع المسلمين؛ لأنه يؤذيهم بذلك، وإذا كان ليس هناك حاجة لهذا فليترك ذلك حتى لا يحرم الصلاة مع المسلمين.  أما إذا دعت الحاجة إلى ذلك لجوع أو مرض فلا حرج، أما إن اعتاد ذلك كشهوة فالذي ينبغي له ترك ذلك حتى لا يحرم صلاته مع المسلمين، نعم. وإذا قصد بذلك التخلف عن الجماعة يتحيل بهذا لترك الجماعة فهذا منكر، ولا يجوز، نسأل الله العافية، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13070/حكم-الذهاب-الى-المسجد-لمن-اكل-ثوما-او-بصلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_556/55611.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14581,"question":"السائلة الأخت أم أسامة من الدمام، تقول سماحة الشيخ: تذكر بأنها فتاة تصلي بأمها جماعة في المنزل، هل يجوز لها ذلك؟ وهل يجوز لي -تقول- بأن أرفع صوتي بالتلاوة حتى تسمع أمي القراءة؟ وهل رفع صوتي بالقراءة في جميع الركعات؟","title":"حكم صلاة المرأة بأمها وفي أي الركعات ترفع صوتها؟","answer":"الجواب: لا بأس أن تصلي بأمها أو ببناتها جماعة حتى يتعلمن ويستفدن، كل هذا طيب، إن كانت واحدة تكون عن يمينها، وإن كانوا جماعة يكونوا خلفها، تكون بينهن السنة أن تكون بينهن، ليس مثل الرجل تقف بينهن إذا كن جماعة، وإن كانت واحدة تقف عن يمينها، وتصلي بهن حتى يتعلمن ويستفدن ويرجى لهن فضل الجماعة، فلا بأس بهذا. وترفع صوتها بالقراءة في المغرب والعشاء والفجر، الفجر في الركعتين، في المغرب والعشاء في الركعة الأولى والثانية.  أما في الثالثة من المغرب والثالثة والرابعة من العشاء فالسنة السرية تقرأ سرًا، وأما في الفجر ترفع صوتها بالفاتحة وغيرها حتى تسمع أمها ومن معها وهكذا في الأولى والثانية من المغرب والعشاء، كما فعله النبي ﷺ، فإذا جهر يكون في الأولى والثانية من المغرب والأولى والثانية من العشاء وفي الفجر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13078/حكم-صلاة-المراة-بامها-وفي-اي-الركعات-ترفع-صوتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_557/55707.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14603,"question":"رسالة وصلت أيضًا من السودان، النيل الأزرق، وباعثها المستمع كمال حسن خضر، أخونا كمال يقول: في ذات يوم من الأيام، وفي صلاة المغرب، كنا نصلي في جماعة، وبعد انتهاء الصلاة سلم الإمام، وقام أحد المصلين، وقال: (سبحان الله) الصلاة ناقصة ركعة، البعض سلم خلف الإمام، والآخرين لم يسلموا، فنهض الإمام ليأتي بالركعة الناقصة، ونهض معه الذين لم يسلموا. أما الذين سلموا فظلوا جالسين، أيهما صلاته صحيحة؟","title":"حكم اختلاف المأمومين في حالة سهو الإمام بالصلاة","answer":"الجواب: كلهم صلاتهم صحيحة، الذي نهض معه، وكمل، والذي جلس وكمل لنفسه، أو نهض معه، وكمل، كلهم صلاتهم صحيحة، وعليهم سجود السهو، مع إمامهم، عليه سجود السهو، وعليهم أن يسجدوا معه للسهو جبرًا للصلاة، والأفضل أن يكون السجود بعد السلام، كما فعله النبي ﷺ لما سلم عن نقص ركعة في بعض المرات عن نقص ركعتين كمل الصلاة، ثم سلم، ثم سجد للسهو، ثم سلم بعد ذلك، هذا هو الأفضل في حق من سلم عن نقص ركعة أو أكثر أنه يكمل الصلاة، ويسلم منها، ثم يسجد للسهو، ثم يسلم بعد سجود السهو، والذين سلموا مع إمامهم يلزمهم أن يقوموا معه إذا قام، وهكذا الذين لم يسلموا لو سلموا كان أولى، ثم يقوموا يتابعون إمامهم، لكن إذا ما لم يسلموا لاعتقادهم نقص فلا شيء عليهم يتابعون، والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13101/حكم-اختلاف-المامومين-في-حالة-سهو-الامام-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_636/nour_63602.mp3","categories":["سجود السهو"]},{"id":14638,"question":"له سؤال آخر يقول فيه: دخلت إلى المسجد، ووجدت أحد المأمومين يقف منفردًا خلف الصفوف، ووقفت معه، ودخلت في الصلاة، ثم زاد الصف طولًا، وانتهت الصلاة، فقلت له: يا أخي، الوقوف منفردًا خلف الصف لا تصح صلاة من فعل ذلك على ما سمعت من هذا البرنامج، قال لي: بأنه حاول أن يسحب أحدًا من الصف الذي أمامه، لكن لم يستجب له أحد، الآن ما صحة صلاته هو وما صحة ما فعلت أنا؟جزاكم الله خيرًا.","title":"حكم صلاة المنفرد خلف الصف ومن صلى معه","answer":"الجواب: إذا كان الشخص الذي سبقك وقف في الصف، ثم جئت قبل الركوع، أو بعد الركوع صحت صلاتكما جميعًا، أما إذا كان مجيئك بعدما صلى ركعة أو أكثر، فإن صلاتك صحيحة؛ لأنك تعتقد سلامة صلاته، وصلاته غير صحيحة عليه أن يعيدها.  أما إن كنت تعلم أن صلاته باطلة حين وقفت معه، فعليك أن تعيد أيضًا، لكن إذا كنت لا تعتقد ذلك وتجهل الحكم الشرعي فصلاتك صحيحة، أو كان وقوفه قبل الركوع، أو بعد الركوع لكن جئت معه قبل أن يسجد في الركعة الأولى فإن صلاتكما صحيحة أيضًا، لقصة أبي بكرة؛ لأن أبا بكرة الثقفي  جاء والنبي راكعًا -عليه الصلاة والسلام- فركع دون الصف، ثم دخل في الصف، فقال له النبي -عليه الصلاة والسلام-: زادك الله حرصًا، ولا تعد ولم يأمره بالإعادة، فدل على أن من وقف دون الصف في الركوع، أو فيما بعد الركوع، لكنه أدرك السجود في الصف أو صف معه غيره، فإن صلاته صحيحة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13151/حكم-صلاة-المنفرد-خلف-الصف-ومن-صلى-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_627/nour_62707.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14644,"question":"هذا سائل للبرنامج السائل أبو عبدالله من القصيم بريدة، يقول: رجل دخل المسجد والإمام في الركعة الأخيرة من الصلاة، والصف قد اكتمل في الصلاة، هل أصلي خلف الصف منفردًا؟ وهل صلاتي صحيحة؟","title":"حكم صلاة المأموم منفردًا خلف الصف","answer":"الجواب: ليس لك ذلك، انتظر لعل الله يأتي بأحد يصلي معك، لا تصل وحدك خلف الصف، يقول النبي ﷺ: لا صلاة لمنفرد خلف الصف ولما رأى رجلًا يصلي خلف الصف وحده أمره أن يعيد الصلاة، فأنت تلتمس فرجة، أو تنتظر لعله يأتي أحد، فإن لم يتيسر صل وحدك، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/13130/حكم-صلاة-الماموم-منفردا-خلف-الصف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_559/55915.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14645,"question":"رسالة وصلت إلى البرنامج من اليمن الجنوبي، وباعثها المستمع إياد محمد سالم عبدالله، أحد أسئلته يقول: هل يجوز الصلاة جماعة بإمام بدون عمامة؟ وهل العمامة من السنة في الصلاة؟","title":"حكم صلاة الإمام بدون عمامة","answer":"الجواب: يجوز أن يصلي الإمام بدون عمامة، ليست شرطًا في الصلاة، ولا سنة في الصلاة، لكن الأفضل أن يصلي الإنسان بالزينة المعتادة؛ لأن الله قال: يَا بَنِي آدَمَ خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ[الأعراف:31] أي: عند كل صلاة، فإذا صلى بعادته المعتادة فهو أحسن وأولى، لأنه إذا تركها قد يستنكر ذلك، وقد يقدح في عقله، أو في اتزانه، أو في أخلاقه. فالحاصل: أنه إذا كان من عادة أهل بلده أنهم يصلون في العمامة، لا يدع العمامة يصلي في العمامة، حتى لا يظن به السوء، وحتى لا يقدح فيه أنه متساهل، أو أنه لا يبالي بزي أناس، أو ما أشبه ذلك، وإلا فليست شرطًا، فالنبي ﷺ قال: لا يصلي أحدكم في الثوب الواحد ليس على عاتقه منه شيء ولم يقل: ليس على رأسه، بل قال: ليس على عاتقه منه شيء. فالمشروع: أن يصلي في إزار ورداء، أما الرأس فلو صلى وهو مكشوف فلا بأس، فالسنة أن تصلي في قميص، أو في إزار ورداء، وإذا كان من عادة البلد أن الرأس عليه عمامة أو غترة أو شيء أو طاقية أو قلنسوة، فيصلي كما كانوا يصلون حتى لا يظن به خلاف ما ينبغي، ولو تركها لأنهم يتركونها، ولا يحصل بذلك بأس فلا حرج، ولو تركها عمدًا فصلاته صحيحة، لكنه ينصح بأن يفعلها حتى لا يظن به خلاف الأولى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13145/حكم-صلاة-الامام-بدون-عمامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_636/nour_63615.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14648,"question":"سمعت أنه حين سماع أذان العشاء وأنا أتعشى لا يصح لي ترك الطعام للذهاب إلى المسجد، فهل هذا ينطبق لو أني لم أبدأ عشائي بعد؟أرجو الإيضاح، جزاكم الله خيرًا.","title":"إذا قُدم العَشاء وحضرت الصلاة فما يقدم؟","answer":"الجواب: نعم إذا حضر العشاء عند صلاة المغرب أو العشاء أو العصر قدمت الأكل؛ لقوله ﷺ: إذا قدم العشاء وحضر العشاء فابدؤوا بالعشاء وفي اللفظ الآخر: إذا قدم العشاء فابدؤوا به قبل أن تصلوا المغرب وفي اللفظ الآخر: لا صلاة بحضرة الطعام، ولا وهو يدافعه الأخبثان. فالمؤمن إذا حضر طعامه يبدأ بالطعام؛ لأنه إذا ذهب إلى الصلاة والطعام قد حضر ذهب وقلبه مشغول، فلا يؤديها كما ينبغي، فيبدأ بالطعام، ثم يصلي الصلاة بقلب مقبل فارغ، يخشع في الصلاة، ويقبل عليها. لكن لا ينبغي له أن يجعل ذلك عادة له، ويأمرهم بإحضار الطعام وقت الصلاة لا، بل يجب عليه أن يبدأ بالصلاة، ويعتني بالصلاة، ولا يقوم بإحضار الطعام، لكن لو صادف أنه أحضر الطعام فإنه يبدأ به، لكن لا يجب أن يتخذه عادة، ويحتج به لإضاعة الصلاة في الجماعة، نعوذ بالله من ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13142/اذا-قدم-العشاء-وحضرت-الصلاة-فما-يقدم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_636/nour_63613.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14682,"question":"المستمع عماد آمين الددو، وصبحي عبدالكريم معلاج من سوريا بعثا يسألان عن صلاة المنفرد خلف الصف إذا دخل الإنسان ووجد الصف قد امتلأ، فهل يشرع في الصلاة، أم كيف يكون حاله؟جزاكم الله خيرًا.","title":"ما يفعل من دخل المسجد ووجد الصف ممتلأً؟","answer":"الجواب: المشروع له أنه يبقى حتى يجد فرجة، يعني: يلتمس فرجة في الصف حتى يدخل فيها، أو مع الإمام عن يمينه إذا تيسر ذلك، وإلا فليبق لا يصلي وحده، لعله يجد أحدًا من الجماعة الداخلين من جديد، يصلوا معه، ولا يصلي وحده، إن صلى وحده ما صحت صلاته، لا بد إما أن يجد فرجة يتأنى ويصبر حتى يجد فرجة لا يعجل، أو يقف مع الإمام عن يمينه، فإن لم يجد مع الاجتهاد انتظر لعله يأتي أحد فيصف معه، فإن صلوا ولا أتى أحد يصلي وحده، النبي  قال: لا صلاة لمنفرد خلف الصف ولما رأى رجلًا صلى وحده خلف الصف أمره أن يعيد، رأى رجلًا صلى خلف الصف وحده فأمره أن يعيد الصلاة، ولما ركع أبو بكرة دون الصف نهاه، وقال: زادك الله حرصًا، ولا تعد. فلا يركع دون الصف، ثم يمشي إلى الصف، ولا يصلي وحده خلف الصف، ولكن عن يمين الإمام، أو يلتمس فرجة لعله يجد حتى يدخل في الصف، فإن تعذر عليه ذلك بعد الاجتهاد انتظر، ولا يجذب أحدًا أيضًا، نعم.","link":"https://binbaz.org.sa/fatwas/13171/ما-يفعل-من-دخل-المسجد-ووجد-الصف-ممتلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48917.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14686,"question":"الواقع أن العمل لدى كثير من الناس هو هذا الجذب سماحة الشيخ؟","title":"حكم جذب شخص لمن أتى متأخرًا في الصلاة","answer":"الجواب: لا ما ينبغي؛ لأن الجذب تصرف فيه، وتعد عليه، وفتح فرجة في الصف أيضًا، يفتح فرجة في الصف لأجل مصلحته، والصف يجب سد خلله، والإنسان يفرح بالصف الذي قبله قبل مكانه، يعني: كل صاحب صف يحب أن يبقى في صفه. فالحاصل: أنه لا يجذب، أما حديث: أو اجتررت رجلًا فهو حديث ضعيف، في حديث: ألا دخلت معهم، أو اجتررت رجلًا هذا ضعيف. الصواب: أنه لا يجذب أحدًا، ولكن يلتمس فرجة، فإن وجد فرجة وإلا فيصف عن يمين الإمام، فإن لم يتيسر انتظر، ولا حرج عليه، والحمد لله.\nالمقدم: جزاكم الله خيرًا، أما أن يصلي وحده أو يجتذب أحدًا فهذا كله لا يجوز.\nالشيخ: ممنوع، نعم، لا يجوز. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13179/حكم-جذب-شخص-لمن-اتى-متاخرا-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48918.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14721,"question":"ما حكم الصلاة خلف من لا يحسن قراءة القرآن، ويلحن في سورة الفاتحة؟","title":"حكم الصلاة خلف من يلحن في الفاتحة","answer":"الجواب: إن كان لحنه يُحيل المعنى لم يصح الصلاة خلفه، إلا بمثله، إنسان مثله يعني: عامي يحيل المعنى أمي، أما إن كان لا يحيل المعنى مثل يقول: الحمدَ لله ينصب الدال، أو الحمدِ لله يجر الدال، أو يقول: الرحمنُ الرحيم، أو الرحمنَ الرحيم هذا ما يضر، أو إياك نعبدَ أو نِعْبدُ على لغة بعض البادية ما يضر هذا. لكن إذا قال: إياكِ هذا يضر، أو قال: أنعمتِ أو أنعمتُ هذا يضر يخل المعنى، ما يصلي، يُعلَّم، فإن ما نفع التعليم ما يصلى خلفه، إلا واحدًا مثله ما في حيله يعجز، عامي مثله أمي هذا يصح أن يصلي بمثله، أما أن يصلي بواحد يعرف لا ما يجوز وهو إنسان يستطيع الإصلاح ما يجوز يلزمه أن يغير لسانه، يلزمه أن يتعلم، حرام عليه أن يتكلم بما يحيل المعنى. والغالب أنه ما يمكن إنسان يقول: إياكِ نعبد، أو أنعمتُ إلا غلطة ثم إذا نبه تنبه؛ لأن معناها واضح ما يكلفه أن يقول: أنعمتَ عليهم يخاطب ربه، كونه يقول: أنعمتِ يخاطب المرأة، أو أنعمتُ هذا لحن فاحش، كل إنسان يستطيع يغير لسانه ويتعلم، أو إياكِ يخاطب المرأة ما يصلح كل إنسان يستطيع يغير أن يقول: إياكَ نعبد إذا عُلِّم يتعلم، أما كونه لحنًا لا يحيل المعنى، ولا يغير المعنى مثلما يقرأ بعض العامة: الحمدَ لله ربَ العالمين، الرحمنَ الرحيم، ما يضر هذا، هذا لحن ما يحيل المعنى، ما يخل بالمعنى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13205/حكم-الصلاة-خلف-من-يلحن-في-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_490/49002.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14722,"question":"لو أن الإمام أخطأ أثناء الصلاة في آية، هل يسجد سجود للسهو أم لا؟","title":"هل يسجد للسهو عند السهو في آية؟","answer":"الجواب: لا ما يلزمه سجود السهو إذا أسقط آية من غير الفاتحة، ما يلزمه سجود، الحمد لله؛ لأن هذا قراءة، زيادة على الفاتحة ليس بلازم، لكن إذا أسقط من الفاتحة، لا بد يأتي بالفاتحة كاملة، ينبهه الذي وراه، إذا أسقط آية من الفاتحة ينبهه الذي وراه على ما أسقط حتى يأتي به، ولو ما أتى به تبطل الركعة يأتي بركعة بدلها، لو أسقط آية من الفاتحة بطلت الركعة، وقامت الأخرى مقامها، إذا سها عن آية ولم يُنبه، أما إذا نُبه وأتى بها في الحال فلا بأس، الحمد لله. أما الذي غير الفاتحة لو أسقط شيئًا ناسيًا فلا يضره، الحمد لله، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13208/هل-يسجد-للسهو-عند-السهو-في-اية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56026.mp3","categories":["القراءة في الصلاة","سجود السهو"]},{"id":14724,"question":"هل تجوز الصلاة خلف من يحلق لحيته، ويضرب بالدف عند قبور الأولياء، ويطوف حولهم، ويدعو الناس لهذا العمل؟ وهل صلاة من صلى خلفه صحيحة أم لا؟أفيدونا، جزاكم الله خيرًا.","title":"حكم الصلاة خلف من يحلق لحيته ويطوف بالقبور","answer":"الجواب: هذا فيه تفصيل: العاصي لا بأس الصلاة صحيحة خلفه الذي يحلق لحيته، ولكنه مسلم ما يدعو القبور، ولا يستغيث بالقبور مسلم معروف، لكنه يحلق لحيته، أو يسبل ثيابه، أو يطول شواربه، هذا صلاته صحيحة؛ لأن هذه معصية. والصواب: أن الصلاة خلف العاصي تصح، وقد صلى بعض الصحابة خلف الأمراء المجرمين كـالحجاج كان يصلي ابن عمر خلفه، وهو من أشد الناس فسقًا قتال سفاكًا للدماء. المقصود: الصلاة خلف الفاسق صحيحة، والذي يحلق لحيته من جملة الفاسقين، إذا أصر على أنه يعلم أن الله حرم هذا عليه، وهو يعلم ذلك، ويتساهل يكون فسق، كذلك الذي يسبل ثيابه، وهو يعلم قد أخبره العلماء أن هذا ما يجوز، ثم أسبل ثيابه، ولم يبال يكون فاسقًا، ويصلي خلفه، الصلاة خلفه صحيحة. لكن ما ينبغي أن يتخذ إمامًا، ينبغي إنه يزال عن الإمامة إذا أصر على هذا ينبغي لولاة الأمور أن يزيلوه عن الإمامة، لكن الصلاة صحيحة. أما الذي يدف على القبور، يدعو القبور، يدعو الأموات، يطوف بالأموات هذا لا، هذا إذا كان يدعو الأموات، ويطوف بالقبور، هذا مشرك ما يصلى خلفه إذا كان يطوف، يتقرب إليهم بالطواف، أو يدعوهم من دون الله، أو يستغيث بهم، أو ينذر لهم، ويذبح لهم، هذا كافر، لا يصلى خلفه. أما الذي يضرب بالدف يحسب أنه جائز الدف، وإلا ما هو بيدعوهم، ولا يستغيث بهم فقط، مر على المقبرة ودف عند المقبرة، وإلا ما يدعوهم، ولا يستغيث بهم، ولكن مجرد الدف هذا معصية، الصلاة خلفه صحيحة، والذي يطوف حول القبور يحسب أنه مشروع، يحسب أنه مثل الكعبة يطاف حولها لله، يطوف لله، ما هو لهم، هذا بدعة منكر، أما الذي يطوف لهم يتقرب إليهم هذا شرك أكبر. نسأل الله العافية، نعم. المقدم: نسأل الله السلامة، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13212/حكم-الصلاة-خلف-من-يحلق-لحيته-ويطوف-بالقبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_490/49004.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14778,"question":"يسأل سؤالًا آخر ويقول: يوجد لدينا رجل عاجز، لا يستطيع القيام من الأرض، ويمشي على يديه ورجليه، ولكنه هو أفضل واحدٍ فينا قراءةً للقرآن الكريم؛ لأنه جلس في الحرم الشريف أكثر من عشر سنوات يحفظ القرآن الكريم، هل تجوز إمامته في الصلاة؟نرجو الإفادة، أفادكم الله.","title":"حكم تنصيب العاجز عن القيام إمامًا للمسجد","answer":"الجواب: مثل هذا لا يكون إمامًا؛ لأنه عاجز عن القيام، فالواجب أن يولى الإمامة من يستطيع القيام، لكن لو كان راتبًا إمامًا حيًا راتبًا، ثم أصابه علة وجلس، فلا بأس أن يصلوا خلفه قيامًا أو جلوسًا.  أما أن يعين وينصب وهو عاجز؛ فلا، لا ينصب وهو عاجز عن القيام، ولكن يلتمس من يستطيع القيام، نعم. السؤال: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13287/حكم-تنصيب-العاجز-عن-القيام-اماما-للمسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_641/nour_64105.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14780,"question":"يسأل سؤالًا آخر ويقول: يوجد لدينا رجل عاجز، لا يستطيع القيام من الأرض، ويمشي على يديه ورجليه، ولكنه هو أفضل واحدٍ فينا قراءةً للقرآن الكريم؛ لأنه جلس في الحرم الشريف أكثر من عشر سنوات يحفظ القرآن الكريم، هل تجوز إمامته في الصلاة؟نرجو الإفادة، أفادكم الله.","title":"حكم تنصيب العاجز عن القيام إمامًا للمسجد","answer":"الجواب: مثل هذا لا يكون إمامًا؛ لأنه عاجز عن القيام، فالواجب أن يولى الإمامة من يستطيع القيام، لكن لو كان راتبًا إمامًا حيًا راتبًا، ثم أصابه علة وجلس، فلا بأس أن يصلوا خلفه قيامًا أو جلوسًا.  أما أن يعين وينصب وهو عاجز؛ فلا، لا ينصب وهو عاجز عن القيام، ولكن يلتمس من يستطيع القيام، نعم. السؤال: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13287/حكم-تنصيب-العاجز-عن-القيام-اماما-للمسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_641/nour_64105.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14859,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع إياد محمد سالم عبدالله من اليمن الجنوبي، رسالته بدأها بقوله:بسم الله الرحمن الرحيم، أما بعد:الحمد الله الذي وعد فوفى، وأوعد فعفا، والصلاة والسلام على سيدنا محمد سيد الشرفاء، ومسود الخلفاء، وعلى آله وصحبه أهل الكرم والوفاء، وبعد:فإننا نرسل إليكم هذه الرسالة، حتى نستفيد منكم في الإجابة على أمور ديننا ودنيانا، ونريد منكم الإجابة بالصورة المطلوبة. السؤال الأول: إذا صلى اثنان جماعة فيكون المأموم من جهة يمين الإمام، جاء رجل آخر وهم في الركوع هل يحرم بجانب المأموم، فإذا أحرم فلا يستطيع أن يركع، لكن وجهونا ماذا يعمل؟جزاكم الله خيرًا.","title":"أين يصف من أدرك الإمام راكعًا وجواره مُصل؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد الله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فقد دلت سنة رسول الله -عليه الصلاة والسلام- أن الرجلين إذا صليا جميعًا، فإن الإمام يجعل المأموم عن يمينه، ويصلي به، فإذا جاء آخر فإنهما يتأخران، ويكونان خلفه، هذا هو السنة، ولا يقف لا عن يمين المأموم، ولا عن يسار الإمام، بل يتأخران.  وقد ثبت في صحيح مسلم عن النبي ﷺ أن «كان يصلي وحده فجاء جابر وجبار الأنصاريان فصفا عن يمينه وشماله، فأخذ بأيديهما، وجعلهما خلفه -عليه الصلاة والسلام-» وصلى ذات يوم بابن عباس في الليل فجعله عن يمينه، وصلى بأنس فجعله عن يمينه، هذا هو السنة، إذا جاء الرجل والإمام يصلي ومعه واحد عن يمينه، فإنه يجره خلفه بالرفق والحكمة، ويصفان خلف الإمام، فإن خشي أن تفوت صف عن يمين المأموم، أو عن يسار الإمام، وركعا معه، ثم تأخرا جميعًا خلف الإمام حتى يدرك الركعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13346/اين-يصف-من-ادرك-الامام-راكعا-وجواره-مصل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_639/nour_63901.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14886,"question":"هل تصح الصلاة جماعة مع إمام راتب، وهو لا يجيد القراءة، ومن المأمومين من يجيد القراءة أحسن منه؟","title":"حكم الصلاة خلف من لا يجيد قراءة القرآن","answer":"الجواب: لا مانع من أن يصلى معه، وإن كان لا يجيد القراءة إجادة كاملة، إذا كان يؤدي قراءة مجزئة في الفاتحة، وفي غير الفاتحة لا بأس، وإن كان غيره أجود منه، إذا كانت قراءته ليس فيها لحن يحيل المعنى، فلا بأس أن يصلى معه.  وإذا تيسر من هو خير منه، وتيسر أن يعين بدلًا منه، فهذا أحسن من دون تشويش، أما إذا كان بتشويش أو فتن فلا.  أما إذا كان لا يجيد القراءة يلحن لحنًا يحيل المعنى، فهذا لا يجوز نصبه، ولا الصلاة خلفه إلا بأجناسه وأمثاله من الأميين الذين لا يحسنون القراءة، بل يجب أن يعزل ويلتمس من يقوم مقامه. فالذي مثلًا يقول: (أَهْدِنا الصراط المستقيم) أَهْدِنا من الإهداء، هذا لحن يحيل المعنى أو يقول: (إياكِ نعبد وإياكِ نستعين) أو يقول: في أنعمتُ أو أنعمتِ هذه كلها لحن يحيل المعنى، نسأل الله السلامة فلا، مثل هذا ما يترك إمامًا، ويعلم حتى يعرف كيف يقرأ، ولو كان مأمومًا يعلم حتى يعرف القراءة الشرعية، لكن لا يجوز أن يكون إمامًا في مثل هذا، بل يجب أن يفصل ويلتمس من يؤم الناس من هو أصلح منه يعني، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13390/حكم-الصلاة-خلف-من-لا-يجيد-قراءة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_639/nour_63909.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14892,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول: علي الصديق علي، أخونا له سؤال واحد في رسالته، هو: ما حكم التبليغ وراء الإمام؟وهل هو يلزم في كل صلاة؟ أم يكون عندما لا يسمع الإمام جميع من يؤمهم؟ واطلب عدد المرات التي بلغ فيها في حياة الرسول ﷺ؟","title":"حكم التبليغ وراء الإمام","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فالتبليغ مشروع عند الحاجة إليه، حتى يتمكن المأمومون من الاقتداء بالإمام، أما إذا لم يحتج إليه لكون الإمام يسمعهم، فلا حاجة إلى التبليغ. وهكذا لما يسر الله مكبرات الصوت استغنى الناس عن التبليغ بسبب المكبرات، إلا إذا كان المسجد كبيرًا، وله نواحي كثيرة يخشى ألا يسمعوا الإمام، فلا مانع من التبليغ كما في المسجد الحرام، والمسجد النبوي؛ لأنهم قد يخفى عليهم صوت الإمام في بعض الجهات. فالحاصل: أن التبليغ مشروع عند الحاجة إليه، وإذا انتفت الحاجة لم يشرع، سواء كانت انتفت الحاجة بوجود المكبر، أو لأن الجماعة قليلون يسمعون فلا حاجة إلى التبليغ. وقد ثبت عنه ﷺ أنه صلى في مرضه الأخير قاعدًا، وصلى أبو بكر عن يمينه قائمًا وصلى الناس خلفهما قيامًا، وكان النبي ﷺ هو الذي يصلي بالناس وأبو بكر يبلغ عنه؛ لأن صوته بسبب المرض لا يسمعهم، فكان أبو بكر يبلغ عنه، فهذه هي الحادثة المحفوظة التي بلغ فيها عنه -عليه الصلاة والسلام- فيما نعلم، والحكم يعم كل حادثة بعده، متى وجدت الحاجة فإن التبليغ يشرع، ومتى انتفت الحاجة لم يشرع التبليغ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13389/حكم-التبليغ-وراء-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_492/49201.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14921,"question":"يقول أخونا من البحرين: إذا كان اثنان يصليان صلاة الجماعة، أحدهما على اليمين، ودخل عليهما الثالث يريد الصلاة جماعة، هل يجوز للإمام أن يتقدم أمام الصلاة وهو يقرأ؟","title":"حكم تقدم الإمام أثناء صلاته بجماعة","answer":"الجواب: لا حرج في ذلك، يتقدم، أو يؤخرهما خلفه، ويبقى في مكانه، ثبت عنه ﷺ أنه كان يصلي فجاء جابر فصف معه عن يمينه، ثم جاء جبار بن صخر فصف عن يساره، فأخذهما وجعلهما خلفه -عليه الصلاة والسلام-، وبقي في مكانه -عليه الصلاة والسلام-، فالإمام حينئذٍ ينظر ما هو الأنسب، فإن كان الأنسب أن يتقدم؛ لأن ما خلفه لا تسع لهما تقدم، وإن كان ما خلفه يتسع لهما أخرهما، وبقي في مكانه، وصلى بهما، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13416/حكم-تقدم-الامام-اثناء-صلاته-بجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_492/49205.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14924,"question":"يسأل أيضًا، ويقول: إذا صليت مع أخي أو أبي في المنزل فهل ندرك بهذا فضل صلاة الجماعة؟","title":"هل يدرك فضل الجماعة من يصلي في البيت جماعة؟","answer":"الجواب: لا يجوز للمسلم أن يصلي في البيت، لا مع أبيه ولا مع أخيه، بل يجب على الجميع أن يخرجوا إلى المساجد، وأن يصلوا مع المسلمين، كما قال النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر قيل لابن عباس: ما هو العذر؟ قال: المرض والخوف» وقال -عليه الصلاة والسلام- لرجل أعمى قال: «يا رسول الله، ليس لي قائد يلائمني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له النبي ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم قال: فأجب ولم يرخص له وهو أعمى ليس له قائد يلائمه، بعد أن يسمع النداء، فإذا كان في مكان يمكنه سماع النداء وجب عليه أن يتوجه إلى المسجد، ويصلي مع الناس. أما إذا كان بعيدًا، يشق عليه الحضور؛ لكونه بعيدًا لا يسمع النداء؛ فهذا لا يلزمه، يصلي مع من حوله في مكانه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13419/هل-يدرك-فضل-الجماعة-من-يصلي-في-البيت-جماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_640/nour_64006.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":14945,"question":"هذا سائل للبرنامج، السائلة (أ. ع) من حائل، لها مجموعة من الأسئلة، وكتبت هذه الأسئلة بأسلوبها الخاص تقول: سماحة الشيخ، إذا سهيت في صلاتي مرتين، فهل يكفي سجود سهو واحد، أم يجب علي إعادة الصلاة؟","title":"حكم من سها في صلاة واحدة عدة مرات","answer":"الجواب: إذا سها الإنسان في الصلاة سهوين أو أكثر، كفى سجود واحد، سجدتان للسهو، فلو سها وقام عن التشهد الأول في الرباعية أو الثلاثية وسها فجلس قبل التمام، أو زاد ركعة، يكفي سجود واحد سجدتان للسهو، ولا يتعدد السهو، سجدتان كافيتان، نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/13441/حكم-من-سها-في-صلاة-واحدة-عدة-مرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_562/56211.mp3","categories":["سجود السهو"]},{"id":15007,"question":"ما حكم الصلاة خلف إنسان يصلي بعض الفرائض، ويترك بعضها تهاونًا؟","title":"حكم الصلاة خلف من يتركها أحيانًا","answer":"الجواب: هذا لا يصلى خلفه؛ لأنه قد أتى منكرًا عظيمًا بإجماع المسلمين، وهو ترك الصلاة تهاونًا، وقد ذهب جمع من أهل العلم إلى أنه كافر بتركها تهاونًا، ولو بعضها، فإذا ترك الظهر تهاونًا، أو العصر تهاونًا، واستمر على ذلك، أو تارة يصلي، وتارة لا يصلي، يكون كافرًا، فلا يصلى خلفه، بل يستتاب من جهة ولاة الأمور، على ولي الأمر إذا ثبت لديه ذلك أن يستتيبه، فإن تاب وإلا قتل، ولا يصلى خلفه ولا كرامة؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر، نسأل الله العافية والسلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13502/حكم-الصلاة-خلف-من-يتركها-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_493/49304.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15014,"question":"سؤاله الآخر -سؤال سعيد بن محمد، من سلطنة عمان- يقول: فضلت الجماعة عن صلاة الفذ بسبعٍ وعشرين درجة، هل هذا الفضل يشمل صلاة الإمام والمأمومين، أم للمأمومين خاصة؟","title":"فضيلة الجماعة تشمل الإمام والمأموم","answer":"الجواب: هذا الفضل يشمل الجميع، هذا الفضل للإمام والمأمومين جميعًا، صلاة الجماعة أفضل من صلاة الفذ بسبعٍ وعشرين درجة، هذا للإمام والمأمومين جميعًا، من فضل الله ورحمته  نعم.","link":"https://binbaz.org.sa/fatwas/13508/فضيلة-الجماعة-تشمل-الامام-والماموم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_652/nour_65202.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15032,"question":"يقول هذا السائل: بالنسبة لصلاة الجماعة في المسجد إذا كان الشخص يسمع النداء، ولا يذهب للصلاة في المسجد؛ وذلك لأن أصحاب العمل لا يعطونه إذن بالذهاب؛ فهل عليه إثم؟ وهل يواصل معهم هذا العمل بالرغم من ذلك؟","title":"حكم الاستجابة لأصحاب العمل في ترك صلاة الجماعة","answer":"الجواب: ليس له أن يوافقهم، وعليه أن يشترط ذهابه إلى الصلاة في المسجد، ولا يجوز له طاعتهم؛ لأن الرسول ﷺ يقول: إنما الطاعة في المعروف هكذا يقول ﷺ: إنما الطاعة في المعروف فعليه أن يبين لهم أنه لا بد من الذهاب إلى المسجد، والصلاة مع الجماعة، سواء كان العمل حكوميًا، أو غير ذلك، يعلم أن الصلاة لا بد منها في الجماعة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13527/حكم-الاستجابة-لاصحاب-العمل-في-ترك-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_563/56307.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15035,"question":"يقول هذا السائل: بالنسبة لصلاة الجماعة في المسجد إذا كان الشخص يسمع النداء، ولا يذهب للصلاة في المسجد؛ وذلك لأن أصحاب العمل لا يعطونه إذن بالذهاب؛ فهل عليه إثم؟ وهل يواصل معهم هذا العمل بالرغم من ذلك؟","title":"حكم الاستجابة لأصحاب العمل في ترك صلاة الجماعة","answer":"الجواب: ليس له أن يوافقهم، وعليه أن يشترط ذهابه إلى الصلاة في المسجد، ولا يجوز له طاعتهم؛ لأن الرسول ﷺ يقول: إنما الطاعة في المعروف هكذا يقول ﷺ: إنما الطاعة في المعروف فعليه أن يبين لهم أنه لا بد من الذهاب إلى المسجد، والصلاة مع الجماعة، سواء كان العمل حكوميًا، أو غير ذلك، يعلم أن الصلاة لا بد منها في الجماعة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13527/حكم-الاستجابة-لاصحاب-العمل-في-ترك-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_563/56307.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15046,"question":"سؤاله الأخير يقول: إذا نسيت ركن، أو واجب مع الإمام، ماذا أفعل، أعيد الصلاة أم يلزمني سجود السهو؟","title":"ما يلزم المأموم إذا نسي ركنًا أو واجبًا؟","answer":"الجواب: إذا نسي المصلي وهو مأموم واجبًا من واجبات الصلاة؛ سقط عنه، مثل: نسي أن يقول: سبحان ربي الأعلى في السجود، أو نسي أن يقول: سبحان ربي العظيم في الركوع، أو نسي التكبير عند الهوي في الركوع، أو عند الهوي في السجود، أو عند الرفع من السجود، فإن هذا يسقط عنه، ولا شيء عليه؛ لكونه تابعًا للإمام، وهكذا لو نسي التشهد الأول، شغل ولم يأت به، وقام مع الإمام لما قام، ولم يأت بالتشهد الأول ناسيًا؛ فلا شيء عليه، يتحمله الإمام. أما الأركان -وهي الفرائض العظيمة- فلا بد منها، فإذا نسيها يأت بها، إذا نسيها يأتي بها، ثم يلحق إمامه، فلو سها عن الركوع، وكبر الإمام راكعًا، ثم رفع الإمام فانتبه، فإنه يركع ثم يرفع، ويتابع الإمام، وهكذا لو نسي السجدة الأولى، وسجد الإمام، ثم رفع، فانتبه المأموم، والإمام قد رفع من السجدة الأولى، فإنه يسجد، ثم يرفع، ثم يلحق الإمام في السجدة الثانية. المقصود: أن الأركان -وهي الفرائض المؤكدة- لا تسقط بالسهو عن المأموم، بل يأتي بها ويتابع إمامه، نعم.","link":"https://binbaz.org.sa/fatwas/13569/ما-يلزم-الماموم-اذا-نسي-ركنا-او-واجبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_654/nour_65405.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15049,"question":"سؤاله الأخير يقول: إذا نسيت ركن، أو واجب مع الإمام، ماذا أفعل، أعيد الصلاة أم يلزمني سجود السهو؟","title":"ما يلزم المأموم إذا نسي ركنًا أو واجبًا؟","answer":"الجواب: إذا نسي المصلي وهو مأموم واجبًا من واجبات الصلاة؛ سقط عنه، مثل: نسي أن يقول: سبحان ربي الأعلى في السجود، أو نسي أن يقول: سبحان ربي العظيم في الركوع، أو نسي التكبير عند الهوي في الركوع، أو عند الهوي في السجود، أو عند الرفع من السجود، فإن هذا يسقط عنه، ولا شيء عليه؛ لكونه تابعًا للإمام، وهكذا لو نسي التشهد الأول، شغل ولم يأت به، وقام مع الإمام لما قام، ولم يأت بالتشهد الأول ناسيًا؛ فلا شيء عليه، يتحمله الإمام. أما الأركان -وهي الفرائض العظيمة- فلا بد منها، فإذا نسيها يأت بها، إذا نسيها يأتي بها، ثم يلحق إمامه، فلو سها عن الركوع، وكبر الإمام راكعًا، ثم رفع الإمام فانتبه، فإنه يركع ثم يرفع، ويتابع الإمام، وهكذا لو نسي السجدة الأولى، وسجد الإمام، ثم رفع، فانتبه المأموم، والإمام قد رفع من السجدة الأولى، فإنه يسجد، ثم يرفع، ثم يلحق الإمام في السجدة الثانية. المقصود: أن الأركان -وهي الفرائض المؤكدة- لا تسقط بالسهو عن المأموم، بل يأتي بها ويتابع إمامه، نعم.","link":"https://binbaz.org.sa/fatwas/13569/ما-يلزم-الماموم-اذا-نسي-ركنا-او-واجبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_654/nour_65405.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15072,"question":"أختنا السائلة تسأل وتقول: سماحة الشيخ، من قال: (سبحان ربي الأعلى) في الركوع، وقال: (سبحان ربي العظيم) في السجود سهوًا منه، هل يسجد للسهو؟","title":"هل يسجد للسهو من أتى بأذكار السجود في الركوع والعكس؟","answer":"الجواب: نعم يسجد للسهو؛ لأن الواجب أن يقول: (سبحان ربي العظيم) في الركوع، والواجب أن يقول في السجود: (سبحان ربي الأعلى) فإذا سها يسجد للسهو، فإذا قال: (سبحان ربي العظيم) في السجود، (سبحان ربي الأعلى) في الركوع ساهيًا، فإنه يسجد للسهو قبل أن يسلم سجدتين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13565/هل-يسجد-للسهو-من-اتى-باذكار-السجود-في-الركوع-والعكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56404.mp3","categories":["سجود السهو"]},{"id":15110,"question":"إذا صلى الشخص الصلاة، ولنفرض مثلًا: أنه صلى صلاة المغرب، فأتم الركعتين الأوليين، ولكنه لم يجلس للتشهد الأول بسبب النسيان، فماذا عليه في هذه الحالة؟","title":"حكم من نسي التشهد الأول في الصلاة","answer":"الجواب: إذا لم يجلس في التشهد الأول سجد للسهو، سواء في المغرب، أو في الظهر، أو في العصر، أو في العشاء، المقصود: أنه إذا ترك التشهد الأول ناسيًا، يجب عليه سجود السهو، في الظهر، والعصر، والمغرب، والعشاء جميعًا، لكن لو نبه أو تنبه قبل أن يستتم قائمًا، رجع وجلس، وأتى بالتحيات، فإن استتم قائمًا، ولم ينتبه، ولم ينبه كمل صلاته، والحمد لله. وقد وقع هذا للنبي ﷺ فإنه ﷺ قام من التشهد الأول ناسيًا، فلما أنهى صلاته، وكملها سجد سجدتين قبل أن يسلم للسهو، قبل أن يسلم -عليه الصلاة والسلام-، فالأمة كذلك قال الله سبحانه: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ[الأحزاب:21] فالإمام أو المنفرد إذا ترك التشهد الأول، ولم ينتبه، ولم ينبه حتى استتم قائمًا، فإنه يكمل صلاته، ويسجد للسهو قبل أن يسلم، فإن رجع نبه ورجع قبل أن يشرع في القراءة فلا بأس، كفى، وعليه سجود السهو، لكن عدم رجوعه أولى إذا استتم قائمًا يستمر ويكمل صلاته.  أما إن شرع في القراءة حرم عليه الرجوع، لا يرجع يستمر حتى يكمل، ثم يسجد للسهو. أما المأموم فلا شيء عليه، لو قام المأموم ساهيًا ثم جلس تبعًا لإمامه ما عليه شيء، المأموم تابع لإمامه، إذا كان غير مسبوق، بل دخل معه من أول الصلاة، ولكن صار يهوجس وقام وإمامه جالس للتشهد الأول، وهو قام، يعود يجلس مع إمامه، ولا عليه شيء، ليس عليه سجود سهو. وهكذا لو زاد سجدة ناسيًا، أو ركوعًا ناسيًا لا تبطل صلاته، يتابع إمامه، وليس عليه سجود سهو؛ لأنه تابع لإمامه، وهكذا لو نسي سبحان ربي الأعلى في السجود، أو سبحان ربي العظيم في الركوع، وهو مأموم، ليس عليه سجود سهو تابع للإمام، يتحمله عنه الإمام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13610/حكم-من-نسي-التشهد-الاول-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_494/49407.mp3","categories":["سجود السهو"]},{"id":15111,"question":"يقول: حدثونا عن مستوجبات سجود السهو، وصفته؟","title":"صفة سجود السهو وموجباته","answer":"الجواب:\n\nسجود السهو مثل سجود الصلاة، سجدتان، مثل سجود الصلاة، يقول فيها: سبحان ربي الأعلى، سبحان ربي الأعلى، سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، يدعو فيها مثل سجود الصلاة سواء، يكبر عند الهوي، يكبر عند الرفع، يكبر عند السجود للسجدة الثانية، يكبر عند الرفع، مثل سجود الصلاة، سواء في التكبير، وفي الطمأنينة، وفي التسبيح، وفي الدعاء، الحكم واحد، نعم.\n\nالمقدم: مستوجباته، يقول؟\n\nالشيخ: يعني موجباته، هذا هو.\nالمقدم: هي هذه.\n\nالشيخ: هذه هي، نعم.\nالمقدم: جزاكم الله خيرًا، صفته؟\nالشيخ: هو هذا، مثل سجود الصلاة، يسجد سجدتين مثل سجوده للصلاة، يقول فيهما ما يقول في الصلاة، من تسبيح ودعاء، نعم.\nالمقدم: لعله يقصد دواعي سجود السهو سماحة الشيخ؟\n\nالشيخ: كان قال: موجبات.\n\nالمقدم: ربما أخطأ في التعبير.\n\nالشيخ: إذا زاد في الصلاة سهوًا، أو نقص سهوًا، هذا يوجب عليه سجود السهو، إذا ترك بعض الواجبات سهوًا، أو بعض الأركان سهوًا وأتى بها، أو زاد ركعة أو زاد ركوعًا، أو زاد سجودًا سهوًا، وهو إمام أو منفرد، يلزمه سجود السهو، بأن قام إلى خامسة في الظهر، والعصر، والعشاء، أو قام إلى رابعة في المغرب، أو قام إلى ثالثة في الفجر أو الجمعة، ثم نبهه الناس، أو تنبه ورجع يسجد للسهو.\n\nوهكذا لو زاد سجدة ثالثة ناسيًا يسجد للسهو، هكذا لو زاد ركوع ناسي سجد للسهو، وهكذا لو ترك التسبيح، سبحان ربي العظيم في الركوع، أو سبحان ربي الأعلى في السجود ناسيًا سجد للسهو مثل المنفرد.\n\nلكن للشيء المستحب لا يجب السجود، لو ترك يعني: ما سبح إلا مرة، أو مرتين ما عليه سجود سهو، أو كذلك لو مثلًا ما قرأ سورة بعد الفاتحة، ما يلزمه سجود للسهو؛ لأنها سنة ومستحبة، لا يلزمه سجود للسهو.\n\nوهكذا لو نسي رب اغفر لي بين السجدتين، أو نسي ربنا ولك الحمد، ما يلزمه شيء، يلزمه سجود السهو، لكن المأموم إذا كان مأمومًا ما عليه شيء، لكن إذا كان إمامًا ونسي واجبًا هذا مثلما تقدم، يسجد للسهو، لكن إذا كان نسي الزيادة، مثل ربنا ولك الحمد أتى بها، ولكن نسي أن يكمل وهو قائم، نسي أن يقول: حمدًا كثيرًا.. إلى آخره، أو نسي أن يكرر: رب اغفر لي، قالها مرة، ما يلزمه السجود للسهو، لأنه أتى بالواجب، والحمد لله.\n\nفالواجب أتى به، لكن لو نسي الزيادة المستحبة، هذا ليس عليه سجود للسهو، وهكذا المأموم لو نسي الواجب الذي عليه رب اغفر لي، أو سبحان ربي الأعلى، أو سبحان ربي العظيم، وهو مأموم، تبع لإمامه ليس عليه سجود للسهو، أما الجميع الإمام والمنفرد والمأموم لو تركوا شيئًا مستحبًا هذا ليس فيه شيء، المستحب مثل: قراءة سورة زائدة على الفاتحة هذه مستحبة، ليس فيها سجود سهو، لو ترك الجهر ما جهر في المغرب أو في العشاء في بعض الأحيان نسي الجهر، لا يلزمه سجود سهو، أو جهر في السرية، مثل: الظهر، والعصر جهر ناسي، لا يلزمه سجود للسهو؛ لأن هذا كله مستحب.\n\nفالحاصل: أن سجود السهو إنما يلزم إذا ترك واجبًا، إذا ترك واجبًا، أو ركنا سهوًا، فالواجب يسقط بالسهو، ولكن عليه سجود للسهو، والركن لا بد يأتي به، وعليه سجود للسهو، لو ترك السجود يأتي بالسجود، وعليه سجود السهو، يرجع يأتي بالسجود، أو نسي الركوع، هوى يعود يأتي بالركوع، وعليه سجود للسهو، فالركوع لا بد منه يأتي به، فإن نسيه بالكلية حتى شرع في الثانية، سقطت الركعة الأولى، وقامت الأخرى مقامها؛ لأنه أهمل ركنًا لا بد منه.\n\nأما لو واجب مثل: تسبيح الركوع والسجود، قول: رب اغفر لي بين السجدتين، وقول: ربنا ولك الحمد، سمع الله لمن حمده، كل هذه واجبات متى تركها سهوًا سقطت للإمام والمنفرد، وهكذا المأموم لو تركها سقطت عنه، لكن الإمام يسجد للسهو، والمنفرد يسجد للسهو، والمأموم لا يسجد للسهو؛ إذا كان ترك واجبًا سهوًا، لا يسجد؛ لأنه تابع لإمامه، لكن الإمام والمنفرد يسجدان للسهو، لو نسي رب اغفر لي، أو سبحان ربي الأعلى في السجود، أو سبحان ربي العظيم في الركوع، هذا يسجد للسهو الإمام والمنفرد كما تقدم، نعم.\n\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13611/صفة-سجود-السهو-وموجباته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_494/49408.mp3","categories":["سجود السهو"]},{"id":15162,"question":"سؤاله الثالث يقول: ما رأي فضيلتكم في صلاة الصبي المميز في الصف الأول؛ لأن الكثير من الناس -هداهم الله- يطردونهم إلى الصف الأخير مما يسبب اجتماعهم وعبثهم في المسجد؟","title":"حكم إبعاد الأطفال من الصفوف الأولى","answer":"الجواب: ينبغي أن يشجع الصبي على الصلاة، وألا ينفر منها، فإذا تقدم للصف الأول يبقى في الصف الأول، وهكذا إذا تقدم إلى الصف الثاني هكذا، ولا ينبغي تجميعهم في محل واحد؛ لأن هذا أولًا: ينفرهم من التقدم إلى الصلاة، وثانيًا: يسبب لعبهم وإشغالهم للمصلين، فلا ينبغي لأهل المسجد أن يفعلوا ذلك، بل ينبغي لأهل المسجد أن يلاحظوا تفريقهم، وأن يكونوا عن مواضع يبعد بعضهم عن بعض حتى لا يعبثوا، وحتى لا يؤذوا المصلين، ومن سابق منهم إلى الصف الأول فإنه يقر؛ لأنه سبق إلى شيء ما سبقه إليه غيره فهو أحق به، والله المستعان، نعم.","link":"https://binbaz.org.sa/fatwas/13661/حكم-ابعاد-الاطفال-من-الصفوف-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_665/nour_66508.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15180,"question":"المستمع: ناصر سعود شعيل الحربي، من القصيم الذيبية، بعث يسأل، ويقول: هل يقوم المأموم مع الإمام، إذا زاد الإمام ركعة بالصلاة سهوًا؟ إذا علم المأموم أن الصلاة تامة، وإذا قام المأموم مع الإمام في الركعة الزائدة، والمأموم يعلم أنها زائدة، هل تصح صلاته أم لا؟","title":"حكم متابعة الإمام إذا زاد ركعة","answer":"الجواب: إذا علم المأموم أن الإمام قد زاد ركعة لا يقوم معه، يجلس، ينبهه، يقول: سبحان الله، سبحان الله، وعلى الإمام أن يرجع إذا سبحوا به اثنان فأكثر، عليه أن يرجع، ويجلس ويقرأ التحيات ويسجد للسهو، ثم يسلم، فإن أبى ولم يرجع لا يتابعونه، يجلسون وينتظرونه، حتى المسبوق الذي سبق لا يتابعه، يجلس؛ لأنه خطأ، وهم يعلمون أنه خطأ، فلا يتابعونه فإن تابعوه جاهلًا بالحكم الشرعي صلاتهم صحيحة، ولو عرفوا أنها زائدة إذا جهلوا الحكم الشرعي يحسبون أنه يلزمهم المتابعة، فالصلاة صحيحة. أما إن كانوا يعرفون الحكم الشرعي، وأنه لا يجوز لهم، ثم تابعوه تبطل صلاتهم؛ لأنهم تعمدوا الزيادة في الصلاة، أما إذا كانوا جهالًا ولو علموا أنها زائدة، ما دام يظنون أنها تلزمهم المتابعة، فإن قيامهم معه لا يضرهم، صلاتهم صحيحة؛ لأنهم جهال. أما من عرف أنها زائدة، وعرف الحكم الشرعي، وأنه لا يجوز له متابعة الإمام في الزيادة، فإنه لا يقوم، لا يقوم ولا يتابعه، وإذا تابعه بطلت صلاته. وهكذا في النقص لو جلس في الثالثة، في الظهر، والعصر، والعشاء ونبهوه ولم يقم يقومون ويخلونه، يقومون يكملون لأنفسهم، وهو إن كان في اعتقاده مصيب صلاته صحيحة، وإن كان ما عنده اعتقاد، ولم يقم بطلت صلاته؛ لأن الواجب عليه المتابعة لمن نبهه إذا كانوا اثنين فأكثر، فإذا جلس ولم يكمل وقد بلغ النصاب، المنبهون بلغ النصاب فتكون صلاته باطلة حينئذٍ؛ لأنه تعمد النقص، إلا أن يكون يعتقد أنه أصاب لنفسه، إذا كان يعتقد أنه مصيب هو وأنهم مخطؤون فصلاته صحيحة، وهم لهم اعتقادهم، هو له اعتقاده، وهم لهم اعتقادهم، صلاتهم صحيحة إذا اعتقدوا أنهم مصيبون، وصلاته صحيحة هو الذي اعتقد أنه هو المصيب. وعليهم جميعًا في مثل هذه المسائل أن ينتبهوا حتى لا يقعوا في الباطل، فإذا دخل في الصلاة يقبل عليها بقلبه وينتبه يخشع فيها حتى لا يقع سهو، فإذا وقع السهو عمل بشرع الله، إن كان الإمام نبهوه: سبحان الله، سبحان الله، إن كان في زيادة لم يتابعوه في الزيادة، وإن كان في نقص لم يتابعوه في النقص، إذا علموا أنه زاد أو نقص، فإذا علموا بالزيادة، يجلسون ينتظرونه، وإذا علموا بالنقص يقومون إذا لم يتابعهم يقومون يكملون، وعليه هو سجود السهو إذا زاد أو نقص، عليه سجود سهو، ويتابعونه في السجود، إن كان زيادة، ورجع لتنبيههم، كمل الصلاة وسجد للسهو، وإن كان عن نقص قام وأتى بالنقص وسجد للسهو، وسجدوا معه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13673/حكم-متابعة-الامام-اذا-زاد-ركعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_496/49602.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15193,"question":"هذا سؤال بعث به المستمع (أ. ع) من مكة المكرمة، يقول: أتيت إلى المسجد لأصلي العشاء في رمضان، فوجدت المصلين يصلون التراويح، وقد انتهوا من صلاة العشاء، فهل يجوز أن أنضم إليهم بنية الفرض على أن أكمل ركعتين بعد سلامهم، ولي أجر الجماعة أو أصلي منفردًا العشاء؟","title":"حكم صلاة العشاء خلف من يصلي التراويح","answer":"الجواب: إن صليت وحدك فلا بأس، وإن صليت معهم من أجل الجماعة فهو أفضل، تصلي معهم، ثم إذا سلم الإمام تقوم وتأتي بالركعتين الباقيتين من العشاء، ولك أجر الجماعة -إن شاء الله-.  وقد ثبت في الصحيحين عن معاذ  أنه كان يصلي مع النبي -عليه الصلاة والسلام- العشاء فرضه، ثم يذهب معاذ فيصلي بجماعته صلاة العشاء نافلة له، وهي فرضهم، وقد أقره النبي على ذلك -عليه الصلاة والسلام-. والحاصل: أنه يجوز أن يصلي المفترض خلف المتنفل، كما أقره النبي ﷺ من فعل معاذ ، وثبت أيضًا أنه ﷺ في بعض صلاة الخوف صلى بجماعة ركعتين هي فرضه وفرضهم، ثم صلى بجماعة آخرين ركعتين، فصارت فرضًا لهم، وكانت نافلة له -عليه الصلاة والسلام-. فهذا كله يدل على أنه لا بأس أن يصلي المفترض خلف المتنفل، كالذي جاء في رمضان وقد صلى الناس العشاء فإنه يصلي معهم العشاء بنية العشاء، ثم إذا سلم الإمام من إحدى تسليمات التراويح يقوم فيصلي بقية العشاء، نعم.","link":"https://binbaz.org.sa/fatwas/13701/حكم-صلاة-العشاء-خلف-من-يصلي-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_671/nour_67106.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15195,"question":"له سؤال آخر يتعلق بالصلاة، يقول: لو أتيت والجماعة في الركوع أو السجود، فهل تكفي تكبيرة الركوع، أو السجود؟ أم لا بد من تكبيرة قبلها للإحرام، ثم تليها تكبيرة الركوع أو السجود؟","title":"كيفية تكبير المسبوق عندما يجد الإمام راكعًا أو ساجدًا","answer":"الجواب: إذا جاء والناس ركوع، فإن الواجب عليه أولًا أن يكبر تكبيرة الإحرام أولًا، ثم إن تيسر له أن يكبر عند انحنائه تكبيرة الركوع فإنه يكبرها، وإن لم يتيسر ذلك أجزأته التحريمة، تكبيرة الإحرام تجزئه على الصحيح، ولكن إن أتى بهما جميعًا، فهذا هو الأفضل والأكمل، خروجًا من خلاف العلماء، ثم يركع مع إمامه وتجزئه الركعة هذه، وليس عليه قضاء الركعة، بل تجزئه هذه الركعة التي أدرك الإمام فيها في حال الركوع.  وأما إذا جاء وهم سجود فإنه يكبر تكبيرة الإحرام فقط، وهو واقف، ثم ينحط ساجدًا بدون تكبير، ولا تجزئه هذه الركعة؛ لأنه فاته ركوعها وقيامها، نعم.","link":"https://binbaz.org.sa/fatwas/13702/كيفية-تكبير-المسبوق-عندما-يجد-الامام-راكعا-او-ساجدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_671/nour_67107.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15214,"question":"سؤاله الثامن والأخير، يقول: يوجد في أكثر من مسجد في قرى الباحة وغيرها أئمة مساجد، لا يجيدون القراءة، ويقعون في أخطاء كثيرة، وخاصة في التشكيل، وطريقة القراءة والإلقاء.مع العلم بأنه يوجد من هو أحسن منهم علمًا وفقهًا وإلقاء، وخاصة أن الإمام هو القدوة للمصلين في كل شيء وحركة. فنرجو إيضاح ذلك، وهل يجوز لمن هم أو لمن ذكرنا أنهم أحسن علمًا وفقهًا وإلقاء ترك هذه المساجد أم لا؟","title":"حكم إمامة من لا يجيد القراءة مع وجود الأفضل","answer":"الجواب: الرجل الذي يحصل منه بعض الأغلاط في القراءة له أحوال، تارة يكون غلطه لا يؤثر في المعنى، ولا يحيل المعنى، فهذا أمره أوسع، وتارة يكون غلطه يحيل المعنى، وتارة يكثر، وتارة يقل.  فالسنة في هذا أن يتولى الإمامة الأقرأ والأجود هذا هو السنة، كما قال النبي ﷺ: يؤم القوم أقرؤهم لكتاب الله، السنة أن يؤمهم أقرؤهم، وأجودهم قراءة، وأكثرهم قرآنًا، وهذا يرجع إلى ولاة الأمور الذين لهم الحل والعقد في أمر المساجد والأئمة، عليهم أن يولوا الأفضل، فالأفضل في قراءته وعلمه ودينه وعدالته. وإذا وجد أهل المسجد أن إمامهم يلحن كثيرًا، ففي إمكانهم أن ينصحوه، بأن يستقيل، أو يعلموه لعله يستفيد ويزول لحنه ويستقيم، أو يتكلم مع مسئولين في الأوقاف حتى يزيلوه ويعينوا غيره. وبكل حال، فالواجب على أهل المسجد أن يعنوا بالموضوع، وألا يتساهلوا، وإذا أمكن تفقيه الرجل وتعليمه وإرشاده من أهل العلم حتى يفقه القراءة الطيبة، وحتى يزول ما به من خطأ، فالحمد لله. وإذا أصر على لحنه وغلطه، فإن كان غلطه يحيل المعنى وجب عزله، ولا تصح صلاته، إذا كان في الفاتحة، مثل أن يقرأ: صراط الذين أنعمتُ عليهم هذا لحن فاحش، أو يقرأ: أنعمتِ عليهم هذا لحن فاحش، تبطل معه الصلاة إذا تعمده. لكن إذا كان يغلط جهلًا يُعلم ويوجه، ولو في الصلاة، فإذا اعتدل وقرأها: أَنْعَمْتَ عَلَيْهِمْ [الفاتحة:7] استقام صحت، أو قال: إياكِ وعلموه، وقال: إِيَّاكَ [الفاتحة:5] فقرأها كما قالوا واعتدل فلا بأس.  أما إذا كان ما يعرف إلا أنعمتُ أو أنعمتِ هذا يعزل، ولا تصح قراءته، ولا تصح صلاته بهم، أما هو في نفسه فإذا عجز صلاته تصح في نفسه، ولكن عليه أن يتعلم، عليه أن يجتهد، حتى يعدل لسانه، وحتى يستقيم في قراءته. أما اللحن الخفيف، مثل قال: الحمدَ لله رب العالمين أو قال: الحمدِ لله رب العالمين هذا ما يضر المعنى، أو قال: الحمد لله ربَّ العالمين أو: الرحمنَ الرحيمَ هذا ما يضر المعنى، لكن يعلم ويوجه، فإن استقام الحمد لله، وإلا أمكن أن يقولوا للمسؤولين يغيروه، أو يصطلح الجماعة إذا كان المسجد ما يتبع الأوقاف يصطلحون على إنسان أفضل منه، نعم.\nالمقدم: لكن هل على الإنسان الأفضل أن يأبى الإمامة؟ الشيخ: إذا احتيج إليه ما ينبغي أن يأبى، إذا احتيج إليه، ينبغي له الموافقة، وقد تجب عليه الموافقة إذا احتيج إليه، نعم.","link":"https://binbaz.org.sa/fatwas/13728/حكم-امامة-من-لا-يجيد-القراءة-مع-وجود-الافضل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_672/nour_67209.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15228,"question":"وردتنا رسالة من المرسل الطالب محمد نور موسى عرفة، من كسلا، بالسودان، يقول فيها: إذا ترك الإمام سجدة واحدة، والصلاة كانت العشاء، وكان في آخر الركعة، ثم سلم، وقال له بعض من المأمومين: يا شيخ، تركت السجدة، فتذكر، ثم جاء بالسجدة، وهو جالس في مصلاه، ثم سجد للسهو بعد السلام، هل بهذه الكيفية صحيحة أم لا؟ وإذا لم تصح ماذا يفعل مع الأدلة؟","title":"حكم الإمام إذا نسي سجدة ثم قضاها بعد الصلاة","answer":"الجواب:  هذه المسألة محتملة، فالمشهور عند بعض أهل العلم أنه يأتي بركعة، تبطل الركعة كلها، ويأتي بركعة كاملة، إذا كان ذكره لها، وتنبيهه عليها بعد السلام، ذهب بعض أهل العلم إلى أنه يأتي بركعة كاملة، ثم يسلم، ثم يسجد للسهو بعد ذلك؛ لكونه سلم عن نقص، وذهب بعضهم إلى أنه يكفيه أن يأتي بالسجدة، ثم يسلم، ثم يسجد للسهو، وإن سجد قبل السلام فلا بأس.  ونظرًا إلى أنها مهمة، وينبغي فيها التحقيق والعناية، فإني أرى تأجيلها إلى ليلة أخرى إلى حلقة أخرى نبين فيها الصواب بالأدلة -إن شاء الله-، نعم.","link":"https://binbaz.org.sa/fatwas/13718/حكم-الامام-اذا-نسي-سجدة-ثم-قضاها-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_678/nour_67802.mp3","categories":["سجود السهو"]},{"id":15253,"question":"هذا سؤال بعث به المستمع ذكري فرج مسعود، من السلوم، جمهورية مصر العربية، يقول: عندنا رجل يؤمنا في الصلاة، ويفرض نفسه علينا دون أن يشاور أحدًا في الأمر، رغم أن خلفه من هو أقرأ للقرآن منه، وأعلم بالسنة منه، فما حكم الصلاة خلف هذا الرجل؟","title":"حكم فرض الإمام نفسه للإمامة","answer":"الجواب: الواجب على هذا الرجل ألا يفرض نفسه على الناس، بل يشاورهم إن أرادوه تقدم بهم، وإن لم يريدوه ترك، والواجب عليه أيضًا أن يقدر من خلفه، فإذا كان من خلفه أقرأ منه وأعلم منه، فالواجب أن يكونوا مقدمين عليه؛ لأن الرسول  يقول: يؤم القوم أقرؤهم لكتاب الله، فإن كانوا في القراءة سواء، فأعلمهم بالسنة، فإن كانوا في السنة سواء، فأقدمهم هجرة، فإن كانوا في الهجرة سواء، فأقدمهم سلمًا وفي رواية: سنًا. فلا يجوز له أن يفرض نفسه عليهم، بل يجب عليه أن يدع هذا الأمر شورى بينهم، فإذا رأى أعيان الجماعة وخواصهم تقديمه تقدم، وإن رأوا تقديم غيره من هو أفقه منه، أو أقرأ منه، فذلك هو الأولى والأفضل، وليس له أن يفرض نفسه على الناس. وإذا كان للمسجد مسؤول من الأوقاف، أو غير الأوقاف، فالمسؤول هو الذي ينظر في الأمر، الأوقاف تنظر أو المسؤول على المسجد الذي هو الوكيل عليه، أو القائم عليه؛ لكونه هو الذي بناه وعمره. المقصود: إذا كان له مسؤول فالمسؤول ينظر في الأمر، وإذا كان ليس له مسؤول فالجماعة ينظرون في الأمر، ويختاروا من هو أفضل في دينه وتقواه، وأفضل في علمه وقراءته، ولا يقبلوا من أحد أن يفرض عليهم نفسه، نعم. المقدم: بارك الله فيكم.\nالشيخ: والصلاة صحيحة، الصلاة صحيحة إذا صلى بهم، لكنه على خطر؛ لأنه جاء الوعيد في حق من أم قومًا وهم له كارهون، فلا ينبغي له أن يؤم قومًا يكرهونه، فهو على خطر، فالصلاة صحيحة، لكنه قد خاطر بنفسه، فينبغي له الحذر والبعد عن مثل هذا الأمر إلا برضا الجماعة، وتقديمهم له، نعم.","link":"https://binbaz.org.sa/fatwas/13760/حكم-فرض-الامام-نفسه-للامامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_674/nour_67404.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15310,"question":"المستمعة والتي رمزت لاسمها بـ (ص. ي) من الجمهورية العربية السورية، دمشق، تقول: سماحة الشيخ، حدثونا عن سجود السهو وسجود التلاوة -جزاكم الله خيرًا- متى يجب؟","title":"متى يجب سجود السهو؟","answer":"الجواب: سجود السهو يجب إذا ترك الإمام واجبًا سهوًا، أو فعل محرمًا سهوًا، يسجد للسهو؛ لقوله ﷺ: من زاد في صلاته، أو نقص سهوًا فليسجد سجدتين فالسنة للإمام والمنفرد إذا أتى بشيء مما حرم الله في الصلاة ساهيًا أن يسجد للسهو، كأن يتكلم ساهيًا، أو يزيد ركعة ساهيًا، أو يزيد سجدة ساهيًا، يسجد للسهو قبل أن يسلم، بعد ما يفرغ من التحيات والدعاء يسجد سجدتي السهو، وإن سجداهما بعد السلام فلا بأس.  وهكذا لو ترك واجبًا ساهيًا ترك قول (سبحان ربي الأعلى) في السجود أو (سبحان ربي العظيم) في الركوع أو (رب اغفر لي) بين السجدتين، فإنه يسجد للسهو قبل أن يسلم، أو ترك التشهد الأول ناسيًا وقام إلى الثالثة يسجد السهو قبل أن يسلم، وإن سجد بعد السلام فلا حرج. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13807/متى-يجب-سجود-السهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56605.mp3","categories":["سجود السهو"]},{"id":15328,"question":"هذا سؤال من السائل: عبدالرزاق آدم محمود، مقيم بالمملكة العربية السعودية، الجموم، يقول: ذهبت إلى المسجد لصلاة العشاء، فوجدت الجماعة قد سبقوني بركعتين، وبعد أن كبرت للدخول في الصلاة، حصل للإمام عذر، جعله يقطع الصلاة، ويضعني إمامًا مكانه، فماذا أفعل في هذه الحالة، وأنا مسبوق بركعتين؟","title":"كيفية صلاة المسبوق إذا أنابه الإمام لإكمال الصلاة","answer":"الجواب: يصلي الركعتين التي أدرك مع الإمام، ويجلس للتشهد، فإذا تشهد التشهد الأول، والأفضل أن يصلي على النبي ﷺ ثم يقوم، ويشير لهم يجلسون؛ حتى يفرغ ويسلم بهم جميعًا، يشير لهم؛ حتى يجلسوا، ولا يتابعوه، فإذا قضى الركعتين اللتين عليه؛ سلم بهم جميعًا؛ لأنه معذور في هذه الحالة، وهم معذورون، فهو يقوم حتى يكمل صلاته، وهم ينتظرونه؛ لأنه قام لعذر، فيسلم بهم جميعًا، هذا هو المشروع. ولو أنه استخلف إنسانًا لم يفته شيء لكان أولى، لكن ما دام استخلفه، فإن الصلاة صحيحة، والحمد لله، فهو يصلي بهم ركعتين، ويتشهد بهم، ويصلي على النبي ﷺ على الأصح، الأفضل أن يصلي على النبي ﷺ بعد الشهادتين، ثم ينهض مكبرًا إلى الثالثة، حتى يكمل لنفسه، فإذا كمل لنفسه، سلم بهم جميعًا، أما هم لا ينهضون معه، ينتظرون حتى يسلم بهم جميعًا، نعم. المقدم: لكن لو كان هذا الشخص المستخلف أيضًا: استخلف آخر، أو قدم آخر من...؟\nالشيخ: يعني: حصل له عذر؟\nالمقدم: لا؛ بدون عذر، لكن يعني: هو نفسه يدفع أحد المكملين للصلاة مع الإمام الأول؟\nالشيخ: لا؛ الأحسن له أن يستمر، يمتثل لما استخلف، يمتثل هو، ولا يستخلف، أخشى أن يكون شبه الوكيل لا يوكل في مثل هذا، ما دام استخلفه، وارتضاه لهم، يمضي، ولا يستخلف هو، إلا إذا عرض له عارض، نعم.\nالمقدم: إنما إذا لم يكن هناك مانع، فيجب أن يمتثل. الشيخ: يكمل هو، ويشير لهم إذا أراد النهوض يشير لهم حتى يجلسوا، حتى يكمل، ولو قام معه أحد جاهل؛ صلاته صحيحة، لو قام معه الجاهل، وصلى معه الجاهل؛ صلاته صحيحة، لكن هو يشير لهم حتى يجلسوا، وينبههم بعد الصلاة أن هذا هو المشروع، إذا جاء مثل هذا؛ يجلسون، وينتظرون، نعم. المقدم: أحسن الله إليكم، وأثابكم.","link":"https://binbaz.org.sa/fatwas/13840/كيفية-صلاة-المسبوق-اذا-انابه-الامام-لاكمال-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_683/nour_68304.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15329,"question":"سؤاله الآخر يقول: كيف يقوم رجل وامرأة بتأدية صلاة الجماعة؟","title":"أين تصف المرأة في صلاة الجماعة؟","answer":"الجواب: هذا له أحوال: تارة يمكن أن يصليا جميعًا في النوافل، كأن يصلي هو وامرأته، أو أهل بيته في صلاة الضحى نافلة، وفي التهجد بالليل، أو صلاة الوتر، فيقوم هو وحده وتصف النساء خلفه، حتى ولو كانت زوجته خلفه، لا تصف معه، لا بأس بهذا، وهكذا في التراويح، لو صلوا مع الإمام صلين خلفه، أو صلى بهن صاحب البيت صلين خلفه، سواء واحدة، أو عدد يصلين خلفه، ويجوز في الفرائض لو جاء النساء إلى المساجد، وصلين مع الناس فإنهن يصلين خلف الأئمة، وخلف المأمومين، ولا تصف امرأة مع رجل، لا مع زوجها، ولا مع أبيها، ولا مع غيرهم موقفهن خلف الرجال، سواء في الفريضة أو في نافلة في الليل أو في النهار. المقصود: أن هذه الأنواع كلها طريقها واحد المرأة فيها تكون خلف الإمام، أو خلف المأمومين إذا كان هناك مأمومون، ولا تقف مع الإمام، ولا مع المأمومين، نعم. المقدم: وإن كن نساء فقط؟ الشيخ: تقف الإمامة وسطهن، الإمامة تقف وسطهن إذا كن نساء فقط، تكون إمامتهن في وسطهن. المقدم: لا تتقدمهن؟\nالشيخ: لا، لا تتشبه بالرجال، نعم.","link":"https://binbaz.org.sa/fatwas/13835/اين-تصف-المراة-في-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_677/nour_67707.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15330,"question":"له سؤال آخر يقول فيه: ما حكم التبليغ للإمام بالتكبير في الصلاة خلفه بصوت عالٍ؟مع العلم أن الجميع يسمعون صوت الإمام تكبيره وتحميده.","title":"التبليغ خلف الإمام","answer":"الجواب: إذا كان الجماعة يسمعون صوت الإمام، ولا يخفى عليهم، فلا حاجة إلى التبليغ.  أما إذا كان قد يخفى على بعضهم كالصفوف المؤخرة، فإنه يستحب التبليغ، وقد صلى النبي ﷺ ذات يوم في مرضه -عليه الصلاة والسلام-، وكان صوته ضعيفًا، وكان الصديق يبلغ عنه -عليه الصلاة والسلام-، فهذا لا بأس به، إذا احتيج إلى التبليغ لسعة المسجد، وكثرة الجماعة، أو بعد صوت الإمام لمرض أو غيره، فإنه يقوم بعض الجماعة بالتبليغ.  أما إذا كان الصوت واضحًا يسمعه الجميع، ولا يخفى على أحد في الأطراف، بل.....، أمر معلوم أنه يسمعه الجميع، فليس هناك حاجة إلى التبليغ، ولا يشرع التبليغ، نعم.","link":"https://binbaz.org.sa/fatwas/13830/التبليغ-خلف-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_677/nour_67705.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15345,"question":"هذه رسالة بعث بها المستمع علي معيض موسى الزهراني، من بلاد زهران، له سؤالان في رسالته، يقول في سؤاله الأول:صليت المغرب مع جدي، وقد سبقني بركعة واحدة، وبدلًا من أن يجلس للتشهد الأخير بعد الثالثة، نهض ليأتي بركعة زائدة، فأمسكته بيدي، وقلت: سبحان الله! ولكنه أصر على ذلك، وعندما جاء بهذه الركعة لم أسلم أنا ونهضت لأكمل صلاتي بركعة، هي في العدد رابعة، ولم أحتسب ركعته الرابعة له، والثالثة لي، وبعدما انتهت الصلاة، قلت له: لم زدت ركعة؟ فقال: لكي تكمل صلاتك معي، جهلًا منه، فما حكم هذه الزيادة في صلاته من غير سهو، وجهل منه بحكم ذلك، وماذا عليه فعله الآن؟ وما حكم صلاتي أنا حيث أنني زدت ركعة رابعة؛ إذ لم أحتسب زيادته، وأيضًا سجدت للسهو جبرًا للزيادة المعلومة؟","title":"حكم زيادة ركعة في الصلاة جهلًا من الإمام والمأموم","answer":"الجواب: أما عملك أنت فقد أصبت حين نبهته، وقلت: سبحان الله! وأمسكته ليجلس؛ لأن هذا هو الواجب عليه؛ أن يجلس إذا نبه، ولا يأتي بالزيادة، وأنت الواجب عليك أن تجلس وتنتظر، فإذا سلم قمت وأتيت بالركعة التي فاتتك، ولا تتابعه في الزيادة، هذا هو المشروع. إذا قام الإمام إلى رابعة في المغرب، أو إلى ثالثة في الفجر، أو إلى خامسة في الرباعية، كالظهر، فإن المأموم ينبهه، يقول: سبحان الله، سبحان الله، والمرأة تصفق، ويلزمه الرجوع، يلزم الإمام الرجوع، إلا إذا كان عنده يقين أنه لم يخطئ، وأنهم هم المخطؤون، وإلا فعليه الرجوع، والجلوس حتى يكمل صلاته، ثم يسلم، وعليه أن يسجد للسهو قبل ذلك؛ قبل أن يسلم سجدتين للسهو، فإن كان عنده يقين أنهم مخطؤون، وهو مصيب كمل صلاته وتممها.  أما المأمومون فهم يعملون بيقينهم، فإن كان عندهم يقين أنه زائد جلسوا، وانتظروه، حتى يسلموا معه، وإن كان ما عندهم يقين تابعوه، وكملوا معه؛ لأنه إمامهم، وعليهم متابعته، وليس لهم مخالفته، إلا إذا كان عندهم يقين، أنه مخطئ، فإنهم يجلسون، ولا يتابعونه في الزيادة. وهذا الذي قام لخامسة أتى بركعة زائدة جهلًا منه، من أجل أن تكمل معه الصلاة، هذا صلاته صحيحة؛ لأجل الجهل، مثل الذي قام لخامسة في الرباعية، أو ثالثة في الثنائية، أو رابعة في الثلاثية، جهلًا منه يحسب أنه لا يرجع إذا قام واستوى قائمًا، بعض الناس يظن أنه إذا استوى قائمًا، لا يرجع، بل يكمل، وهذا غلط من الجهل، فصلاته صحيحة لجهله، ولكن ينبغي له أن يتعلم صلاته، ويتفقه في صلاته، حتى لا يعود إلى مثل هذا الجهل. والمقصود: أنه إذا أتى بالخامسة أو بالرابعة في الثلاثية أو بالثالثة في الثنائية جهلًا أو نسيانًا، فصلاته صحيحة، ولكنه يسجد للسهو إذا كان في النسيان يسجد للسهو، أما لو تعمد الخامسة في الرباعية أو الثالثة في الثنائية أو الرابعة في الثلاثية مثل المغرب، وهو يعلم الحكم الشرعي، وتعمد القيام، هذا متلاعب، صلاته باطلة، ولكن غالبًا هذا لا يقع تعمدًا، إنما يقع من أجل الجهل أو النسيان، فتكون الصلاة صحيحة، وعليه سجود السهو في مسألة النسيان، والمأموم عليه ألا يتابعه في الخطأ، إذا عرف المأموم أنه مخطئ لا يتابعه، ولكن ينبهه، ولا يتابعه لا في الزياة، ولا في النقص، بل المأموم يعمل بيقينه، فإن كان الإمام زائدًا جلس، وإن كان الإمام ناقصًا قام المأموم يكمل ما عليه إذا لم يطاوعه الإمام، هذا هو الواجب على المأموم، وهذا هو الواجب على الإمام، كما سمعت، نعم.\nالمقدم: لكن هو هذا الشخص الذي لم يحتسب هذه الركعة التي زادها الإمام ليكمل صلاته بها ثلاثًا، وزاد عليها ركعة من عنده، هل فعله هذا صحيح؟ الشيخ: نعم، لا يتابعه في الزيادة. المقدم: هو تابعه، وزاد ركعة. الشيخ: المأموم لا يتابع في الزيادة، نعم. المقدم: تابعه في الزيادة، وزاد على ذلك ركعة. الشيخ: هذا غلط، جهلًا منه، القضاء يكون بعد السلام، بعد سلام الإمام، فالركعة التي زادها قبل السلام لا تجزئ، ولكن بسبب الجهل لا تبطل صلاته، وتكون التكملة بعد السلام؛ لأن القضاء استقرت الشريعة أن القضاء يكون بعد السلام، إلا في صلاة الخوف في بعض أنواع صلاة الخوف، وأما القضاء الشرعي المعتاد الذي بينه الرسول للأمة -عليه الصلاة والسلام- فيكون بعد السلام، نعم. المقدم: إنما ليس عليه إعادة الصلاة؟ الشيخ: نعم، ليس عليه إعادة الصلاة، نعم.","link":"https://binbaz.org.sa/fatwas/13846/حكم-زيادة-ركعة-في-الصلاة-جهلا-من-الامام-والماموم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_678/nour_67802.mp3","categories":["سجود السهو"]},{"id":15406,"question":"هذا أخوكم أبو معاذ يقول في هذا  بأنه يعمل في مزرعة، ومتزوج، ولا يوجد معه أولاد، ويبعد عن المسجد مسافة من اثنين إلى ثلاثة كيلو متر، يقول: فهل تجوز الصلاة في المزرعة؟ علمًا بأن المزرعة منعزلة عن القرية التي بها مسجد.","title":"حكم الصلاة في المزرعة لمن كان بعيدًا عن المسجد","answer":"الجواب: لا بأس، إذا كان لا يسمع النداء....، يصلي وحده، وإن صبر وذهب إلى المسجد فهذا خير عظيم، وفضل كبير، وإن صلى وحده فلا بأس؛ لأن الرسول ﷺ قال: من سمع النداء فإذا كان يسمع النداء لو هدأت الأصوات يسمع النداء بغير مكبر يسمعه يلزمه، أما إذا كان في محل بعيد لا يسمع النداء، فإنه لا يلزمه، لكن يصلي وحده، وإن تجشم المشقة وصبر وذهب إلى المسجد، فهذا خير عظيم، وفضل كبير. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13906/حكم-الصلاة-في-المزرعة-لمن-كان-بعيدا-عن-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56724.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15413,"question":"هذه رسالة من السائل (ي. س. م. ن) من العراق، الأنبار، يقول: سجود السهو هل يلزم عندما أنسى دعاء الوتر؟ وهل أقوم بسجود السهو عندما لا أجهر في صلاتي في وقت يجب الجهر فيه، وكان ذلك عن نسيان؟","title":"هل يسجد للسهو من نسي قنوت الوتر والجهر؟","answer":"الجواب: لا يجب إذا ترك الإنسان قنوت الوتر سهوًا، أو لم يجهر في الصلاة الجهرية سهوًا لا يجب، ولكن لو سجد لا بأس، السجود لترك السنة جائز، ولكن ليس بواجب.","link":"https://binbaz.org.sa/fatwas/13921/هل-يسجد-للسهو-من-نسي-قنوت-الوتر-والجهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_684/nour_68413.mp3","categories":["سجود السهو"]},{"id":15468,"question":"هذا السائل من عمان الأردن، يقول في هذا  سماحة الشيخ، ما حكم الصلاة في حالة نسيان الإمام الجلوس للتشهد الأول في الصلاة الرباعية، بعد أن اعتدل قائمًا للركعة الثالثة، ففتح المصلون على الإمام فنزل إلى التشهد بعد الاعتدال؟","title":"حكم صلاة من رجع للتشهد الأوسط بعد الاعتدال","answer":"الجواب: المشروع له بعد الاعتدال أن يمضي، وأن يتابعوه، ويسجد للسهو، ولكن لو رجع، لا يضره -إن شاء الله-، لو رجع جلسوا معه، ويسجدوا للسهو أيضًا، لكن الأفضل إذا استتم قائمًا يمضي ويسجد للسهو بعد ذلك سجدتين قبل أن يسلم، وهم يتابعونه، لكن لو تذكر بعدما قام ورجع، فإنهم يجلسون معه، وعليه سجود للسهو. أما لو تذكر عند القيام حال النهوض، يلزمه الجلوس، حتى يأتي بالتشهد الأول، وهم معه كذلك، لكن لو استتم قائمًا، فهذا هو محل الكراهة عند بعض أهل العلم، وجاء في حديث المغيرة في هذا المعنى ما يدل على أنه إذا استتم قائمًا لا يرجع، أما إن شرع في القراءة فليس له الرجوع، بل يستمر، وعليه السجود للسهو فقط، والحمد لله، نعم. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13992/حكم-صلاة-من-رجع-للتشهد-الاوسط-بعد-الاعتدال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_568/56816.mp3","categories":["سجود السهو"]},{"id":15565,"question":"سماحة الشيخ، من أسئلة هذا السائل يقول: ما رأي سماحتكم إذا قطع المصلي الركعة الأخيرة من السنة، وذلك إذا أقام المؤذن للصلاة؛ وذلك ليدرك تكبيرة الإحرام؟","title":"ما حكم قطع النافلة لإدراك تكبيرة الإحرام؟","answer":"الجواب: هذا الواجب، يقول النبي ﷺ: إذا أقيمت الصلاة فلا صلاة إلا المكتوبة إذا أقيمت وهو باقي عليه ركعة يقطعها ويصلي، يدخل مع الإمام، أما إذا أقيمت وقد انتهى ما بقي إلا السجود أو التحيات يكمل، نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/14107/ما-حكم-قطع-النافلة-لادراك-تكبيرة-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69135.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15688,"question":"يسأل ويقول: ما حكم قراءة القرآن من السور الطويلة والتطويل في السجود والركوع في الجمعة، أو في أي فرض آخر؟","title":"مشروعية التخفيف في صلاة الجماعة","answer":"الجواب: السنة أن تكون معتدلة الصلاة، كما كان النبي يفعل -عليه الصلاة والسلام-، يكون مطمئنًا في الركوع والسجود......، المراد في الحديث السماع للمؤذن بالطريقة المعتادة في عهده ﷺ بغير مكبرات، فهذا إذا سمع النداء يلزمه الحضور إذا قدم، أما إذا كان مريضًا أو عاجزًا لا يلزمه. أما إذا سمع من طريق المكبرات فهذا يسمع من بعيد، لا يلزمه إذا كان بعيدًا يشق عليه الحضور، أو لو حضر ما أدرك، لو حضر بعد الأذان ما أدرك هذا ليس داخلًا في الحديث، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14242/مشروعية-التخفيف-في-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_572/57209.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15714,"question":"السائل خالد سلمان، من مكة المكرمة، يقول: لي أخ شديد الخجل من الناس إلى درجة أنه لا يصلي في المسجد، حيث إنه يصلي في المنزل بسبب هذا الخجل، فما حكم صلاته في مثل هذه الحالة؟","title":"حكم التخلف عن الجماعة بسبب الخجل","answer":"الجواب: الواجب عليه أن يتقي الله، وأن يصلي مع الناس، علموه، ووجهوه للخير، هذا الخجل لا وجه له، هذا ضعف وعجز وكسل، لا يجوز، بل يجب عليه أن يبادر ويصلي مع الناس، ولا يجوز له أن يصلي في البيت، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14272/حكم-التخلف-عن-الجماعة-بسبب-الخجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_574/57404.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15728,"question":"هذا السائل يقول: رجل شك في صلاته -أي: في إحدى الركعات- فلا يدري هل سجد سجدتين أم سجدة واحدة؛ ماذا يلزمه هل يسجد للسهو؟ وأين يكون سجود السهو في هذه الحالة -قبل التسليم أم بعده-؟ وبماذا تنصحون من كان كثير الشكوك والوساوس في الصلاة؟مأجورين.","title":"حكم من شك في عدد السجدات","answer":"الجواب: إن كان شكه بعد الصلاة، بعدما سلم وانتهى، طرأ عليه الشك، لا عمل عليه، صلاته صحيحة، والحمد لله، ولا عليه سجود سهو إذا كان شكه بعد الصلاة -إنما حصل له بعد الصلاة-، هذا لا شيء عليه.\nأما إن كان الشك في الصلاة، فإنه يأتي بالسجدة، يبني على اليقين، إذا شك: هل سجد سجدة أو سجدتين، يأتي بالسجدة الثانية، سواء في الركعة الأولى، أو في الثانية، أو في الثالثة، أو الرابعة، ويسجد للسهو قبل السلام، وإن سجد بعد السلام فلا بأس، لكن في مثل هذا الأفضل قبل السلام. أما إن كان شكه بعد الصلاة، وبعدما فرغ منها، طرأ عليه الشك، هذا من الوساوس، لا يلتفت إليه، والشك بعد الصلاة لا يؤثر، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14292/حكم-من-شك-في-عدد-السجدات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_574/57414.mp3","categories":["سجود السهو"]},{"id":15739,"question":"بعد هذا ننتقل إلى تونس عبر رسالة، بعث بها المستمع الظاهر ربادي، أخونا يسأل جمعًا من الأسئلة، في أحدها يقول: يوجد جماعة يصلون في البيت والمسجد، قريب منهم، بمسافة مائة متر تقريبًا، فما حكم عملهم هذا؟جزاكم الله خيرًا.","title":"حكم الصلاة في البيت مع قرب المسجد","answer":"الجواب: الصلاة في البيت لا تجوز، بل الواجب الصلاة في الجماعة لمن قدر، وقد قال النبي ﷺ في الحديث الصحيح: من سمع النداء، فلم يأت فلا صلاة له إلا من عذر قيل لـابن عباس: ما هو العذر؟ قال: \"الخوف والمرض\". وجاءه ﷺ رجل أعمى، فقال: يا رسول الله ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال -عليه الصلاة والسلام-: هل تسمع النداء للصلاة؟ قال: نعم، قال: فأجب فهذا رجل أعمى، ليس له قائد، ومع هذا يقول له النبي ﷺ: أجب يعني: أجب الداعي المؤذن، لا تصل في البيت، صلِّ مع المسلمين.\nوهؤلاء الذين يصلون في البيت والمسجد منهم قريب، هؤلاء قد عصوا الله، وظلموا أنفسهم، فالواجب التوبة إلى الله، والبدار إلى صلاة الجماعة، نسأل الله لنا ولهم الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14322/حكم-الصلاة-في-البيت-مع-قرب-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_707/nour_70702.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15752,"question":"أحد الإخوة المستمعين يسأل ويقول: هل يجوز أن نصلي وراء إمام مبتدع، ويدعو إلى بدعته؟","title":"هل يجوز الصلاة وراء إمام مبتدع، يدعو إلى بدعته؟","answer":"الجواب: الإمام المبتدع يجب الرفع عنه للجهة المسؤولة، حتى يزال، حتى يُبعد عن الإمامة، وحتى لا ينشر بدعته.  أما الصلاة خلفه فيها تفصيل: إن كانت بدعته تكفره، يعني: يعتبر كافرًا بالأدلة الشرعية، فلا يصلى خلفه، ويجب عزله، وإن كانت بدعته مفسقة، ليست مكفرة، يعني: لا يكفر صاحبها، فالصلاة خلفه صحيحة، لكن ينبغي السعي في إبعاده، إبعاده من جهة ولاة الأمور، حتى يولى رجل صاحب سنة. والصلاة خلف الفاسق العاصي، وخلف المبتدع الذي لا يكفر صحيحة، لكنه ما ينبغي أن يولى الفاسق، ولا ينبغي أن يولى المبتدع، بل ينبغي إبعادهما عن الإمامة، أما إذا كان كافرًا فإنه لا تصح إمامته، ولا الصلاة خلفه، كالذي يعبد الأوثان، ويستغيث بالأولياء، يستغيث بـالحسين أو بالبدوي أو بالشيخ عبد القادر أو بغيرهم من الأموات، هذا كافر كفر أكبر، وهكذا الذي يعرف بسب الدين أو الاستهزاء بالدين الإسلامي كافر، لا يصلى خلفه، ولا يجوز أن يكون إمامًا. أما إذا كان بدعته أقل من ذلك، ما تكفره، مثل الذي يقول: نويت أن أصلي كذا وكذا، بدعة، لكن غير مكفرة، لا تمنع الصلاة خلفه، لكن ينصح ويعلم؛ لأن التلفظ بالنية بدعة، النية محلها القلب، كذلك الإنسان الذي يعرف بأنه يحضر الموالد؛ الاحتفالات بالموالد، ولكن ليس عنده شرك، بل يحضرها من دون أن يكون معروفًا بدعوة الأموات، أو الاستغاثة بالأولياء، حضور الموالد بدعة، لكن ليست مكفرة، إلا إذا كان يدعو الأموات، يستغيث بهم، ينذر لهم، ويذبح لهم، هذا يكون كافرًا بهذا العمل السيئ -نسأل الله العافية-، ولا يصلى خلفه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14341/هل-يجوز-الصلاة-وراء-امام-مبتدع-يدعو-الى-بدعته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74103.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15770,"question":"يقول: صليت المغرب مثلًا جماعة، وبعد الانتهاء جاء أخ للمسجد يريد الصلاة، فهل يمكن أن أصلي معه جماعة، ومن يكون الإمام؟","title":"جواز التنفل مع من تأخر عن صلاة الجماعة","answer":"الجواب: لا بأس أن تصلي معه جماعة، وإن كان أقرأ منك فهو الإمام، وإن كنت أقرأ منه فأنت الإمام؛ لقول النبي ﷺ لما رأى رجلًا دخل المسجد، بعدما فرغ الناس من الصلاة، يقول ﷺ: من يتصدق على هذا فيصلي معه؟ فقام بعض الصحابة وصلى معه، فإذا صلى هو إمام فأنت المأموم، وإن كنت أقرأ منه وقدمك إمامًا صلى معك مأمومًا، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14360/جواز-التنفل-مع-من-تاخر-عن-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74113.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15781,"question":"المستمع (ع. م. العتيبي) بعث رسالة يقول فيها: صليت بجماعة، واكتشفت بعد الصلاة أنني كنت على غير وضوء، فكيف أتصرف والحال ما ذكر؟جزاكم الله خيرًا.","title":"حكم من صلى بالناس على غير وضوء نسيانًا","answer":"الجواب: إذا لم تعلم، وتذكر إلا بعد الصلاة فلا شيء عليك، صلاتهم صحيحة، وأنت عليك الإعادة، عليك أن تتوضأ وتعيد، أما هم صلاتهم صحيحة، أما إن تذكرت وأنت في الصلاة فإنك تنفتل وتستنيب من يكمل بهم، تقول لمن وراءك لأحد من وراءك: تقدم، كمل بهم، وإن استأنفوا وصلوا من أول الصلاة، أو انتظروك حتى ترجع وصليت بهم من أول الصلاة، فلا بأس، لكن أسهل عليهم، وأرفق بهم، أن تقدم من يتم بهم الصلاة، وأنت تذهب وتوضأ وتعيد الصلاة، هذا هو الصواب في هذه المسألة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14370/حكم-من-صلى-بالناس-على-غير-وضوء-نسيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74207.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15823,"question":"يقول سماحة الشيخ: متى يكون سجود السهو بعد السلام؟ ومتى يكون قبله؟","title":"متى يكون سجود السهو بعد السلام؟ ومتى قبله؟","answer":"الجواب: السجود قبل السلام، هذا هو الأفضل، السجود قبل السلام إلا في حالتين: إحداهما: إذا بنى على غالب ظنه، الأفضل يكون بعد السلام.  والحالة الثانية: إذا سلم عن نقص ركعة أو ركعتين، ثم تنبه، يكمل، ثم يسلم، ثم يسجد للسهو، هذا هو الأفضل في هذه الحالتين، إحداهما: إذا بنى على غالب ظنه، يتحرى الصواب، ويبني على غالب ظنه، ثم يكمل صلاته، ثم يسلم، ثم يسجد للسهو، الحال الثاني إذا سلم عن ثنتين أو ثلاث، ثم تنبه، أو نُبه، يكمل صلاته، وإذا كملها وسلم يسجد للسهو، هذا هو الأفضل، وما سوى ذلك يكون قبل السلام. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/14412/متى-يكون-سجود-السهو-بعد-السلام-ومتى-قبله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57515.mp3","categories":["سجود السهو"]},{"id":15898,"question":"رسالة وصلت إلى البرنامج من المستمع (ج. ع) من محافظة الرقة يسأل ويقول: في صلاة السنة بعد الركعة الأولى إنني سجدت وسهوت عن الركوع فما الحكم؟جزاكم الله خيرًا.","title":"حكم من نسي الركوع في النافلة","answer":"الجواب: عليك أن ترجع وتقف ثم تركع ثم ترفع ثم تسجد ثم تسجد للسهو سجدتين قبل أن تسلم، كالفريضة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14491/حكم-من-نسي-الركوع-في-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74518.mp3","categories":["الركوع والسجود","سجود السهو"]},{"id":15991,"question":"يقول: عندي أولادي أعمارهم من إحدى عشرة سنة إلى سبع سنوات، هل الأفضل أن يصفوا خلفي في الصلاة أو إلى جانبي؟ أفيدوني، جزاكم الله خيرًا.","title":"كيفية صف الأولاد خلف الإمام","answer":"الجواب: السنة أن يصفوا خلفك، ولو كانوا صغارًا، إذا كانوا أبناء سبع فأكثر، وقد صلى النبي ﷺ في بيت بعض الصحابة لما زارهم الضحى صلى بهم صلاة الضحى وصف أنس واليتيم خلفه -عليه الصلاة والسلام-، فالسنة أن يصفوا خلفك ولو كانوا صغارًا، إذا كانوا أبناء سبع فأكثر، ولكن ليس لك أن تصلي في البيت صلاة الفريضة، بل يجب عليك أن تصلي في المسجد مع الناس، وعليهم أن يصلوا أيضًا تأمرهم أن يصلوا مع الناس إذا كانوا أبناء سبع أو ثمان يؤمرون، أما إذا بلغوا عشرًا فيؤمرون ويضربون إذا تخلفوا حتى يصلوا مع الناس يعتادوا الصلاة، لكن إذا صليتها في البيت في الليل تهجد بالليل أو صلاة الضحى، فلا بأس يصلوا خلفك، نعم.\nالمقدم: سماحة الشيخ، جزاكم الله خيرًا، ذكر أنه من أبناء البادية؟\nالشيخ: على كل حال يصلون معك في جماعة في مسجدكم في البادية أنت وجيرانك لا تصل في محلك صل مع إخوانك في محل الذي تصلون فيه مصلاكم أنت والجيران، نعم.\nالمقدم: جزاكم الله خيرًا، إذن إذا كان له جيران، فليصل معهم جماعة؟\nالشيخ: نعم، وأما إن كان وحده يصلي مع أولاده ويصلون خلفه. المقدم: بارك الله فيكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14605/كيفية-صف-الاولاد-خلف-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74703.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":15994,"question":"يقول: عندي أولادي أعمارهم من إحدى عشرة سنة إلى سبع سنوات، هل الأفضل أن يصفوا خلفي في الصلاة أو إلى جانبي؟ أفيدوني، جزاكم الله خيرًا.","title":"كيفية صف الأولاد خلف الإمام","answer":"الجواب: السنة أن يصفوا خلفك، ولو كانوا صغارًا، إذا كانوا أبناء سبع فأكثر، وقد صلى النبي ﷺ في بيت بعض الصحابة لما زارهم الضحى صلى بهم صلاة الضحى وصف أنس واليتيم خلفه -عليه الصلاة والسلام-، فالسنة أن يصفوا خلفك ولو كانوا صغارًا، إذا كانوا أبناء سبع فأكثر، ولكن ليس لك أن تصلي في البيت صلاة الفريضة، بل يجب عليك أن تصلي في المسجد مع الناس، وعليهم أن يصلوا أيضًا تأمرهم أن يصلوا مع الناس إذا كانوا أبناء سبع أو ثمان يؤمرون، أما إذا بلغوا عشرًا فيؤمرون ويضربون إذا تخلفوا حتى يصلوا مع الناس يعتادوا الصلاة، لكن إذا صليتها في البيت في الليل تهجد بالليل أو صلاة الضحى، فلا بأس يصلوا خلفك، نعم.\nالمقدم: سماحة الشيخ، جزاكم الله خيرًا، ذكر أنه من أبناء البادية؟\nالشيخ: على كل حال يصلون معك في جماعة في مسجدكم في البادية أنت وجيرانك لا تصل في محلك صل مع إخوانك في محل الذي تصلون فيه مصلاكم أنت والجيران، نعم.\nالمقدم: جزاكم الله خيرًا، إذن إذا كان له جيران، فليصل معهم جماعة؟\nالشيخ: نعم، وأما إن كان وحده يصلي مع أولاده ويصلون خلفه. المقدم: بارك الله فيكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14605/كيفية-صف-الاولاد-خلف-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74703.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16031,"question":"حدثوني عن سجود السهو في الصلاة بالنسبة للزيادة، وبالنسبة للنقصان في الصلاة.","title":"أحوال سجود السهو","answer":"الجواب: سجود السهو يجوز قبل السلام، وبعد السلام في جميع السهو إن سجد قبل السلام؛ كفى، وإذا سجد بعد السلام؛ كفى، لكن الأفضل أن يكون قبل السلام، هذا هو الأفضل إلا في حالتين:\nإحداهما: إذا بنى على غالب ظنه، إذا شك هي ثنتين أو ثلاث، هل صلى ثنتين أو ثلاثًا وبنى على غالب ظنه، يعني صار غالب ظنه أنه صلى ثنتين؛ يجب يكمل، أو كان غالب ظنه أنه صلى ثلاثًا؛ يكمل، فهذا الأفضل يكون سجوده بعد السلام إذا بنى على غالب ظنه. والحالة الثانية: إذا سلم عن نقص، سلم ثنتين، أو من ثلاث للرباعية ساهيًا، ثم تنبه وكمل، فهذا سجود السهو يكون بعد السلام أفضل، وما سوى ذلك فالسجود قبل السلام أفضل. وبكل حال سجوده قبل السلام، أو بعد السلام في جميع الصور كله صحيح، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14660/احوال-سجود-السهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74722.mp3","categories":["سجود السهو"]},{"id":16042,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول فيه: أنا رجل مسبوق في صلاة الجماعة بركعة، وحصل للإمام حدث، ثم خلفته لكي أكمل الصلاة، ماذا أفعل وأنا مسبوق، سألت أحد الناس فقال: أنت تشير للناس بأن يبقوا في هيأتهم لتأتي بما سبقت به، ثم تسلمون جميعًا، هل ما قاله صحيح؟","title":"حكم المسبوق إذا استنيب في الإمامة","answer":"الجواب: لا يتابعونك في الزيادة، وتشير إليهم إذا كنت تخشى أن يقوموا، تشير إليهم أن يبقوا حتى تكمل ما عليك، ثم تسلم ويسلمون معك، والحمد لله. المقدم: جزاكم الله خيرًا، نعيد الإجابة مرة أخرى أحسن الله إليكم. الشيخ: الواجب عليك إذا كنت صرت الخليفة بعده أن تكمل صلاتك، وهم ينتظرونك، فإذا كملت صلاتك؛ سلمت، وسلموا معك، وإذا خشيت أن يقوموا أشر لهم بيدك؛ حتى يبقوا، لا يقوموا معك، نعم. المقدم: أحسن الله إليكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14680/حكم-المسبوق-اذا-استنيب-في-الامامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74809.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16055,"question":"يقول: إذا كان هناك برنامج أحب الاستماع إليه، لكنه يأتي في وقت الصلاة، فهل أستمع إلى ذلك البرنامج؛ علمًا بأنه برنامج ديني؟ أم أبدأ بتأدية الصلاة؟ جزاكم الله خيرًا.","title":"حكم ترك صلاة الجماعة لأجل الاستماع لبرنامج ديني","answer":"الجوب: الواجب عليك أن تبدأ بالصلاة في الجماعة، أن تبدأ بالصلاة في الجماعة. أما إذا كنت مريضًا، أو مسافرًا يمكن أن تأخر قليلًا لتسمع الفائدة؛ فلا بأس، أما إذا كان هذا الاستماع يفوتك صلاة الجماعة؛ فلا يجوز لك، بل عليك أن تصلي مع الجماعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14686/حكم-ترك-صلاة-الجماعة-لاجل-الاستماع-لبرنامج-ديني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74815.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16090,"question":"هذا السائل أبو معاذ من الرياض يقول: سماحة الشيخ الوالد: عبدالعزيز بن باز -حفظكم الله- لي مجموعة من الأسئلة، في السؤال الأول: ما الصحيح في أقوال العلماء في صلاة المنفرد خلف الصف.. وهل صلاة من صلى ركعة واحدة خلف الصف منفردًا، ثم اكتمل الصف بعد ذلك هل صلاته صحيحة، أم يجب عليه الإعادة؟","title":"هل من صلى ركعة خلف الصف منفردًا، ثم اكتمل الصف عليه الإعادة؟","answer":"الجواب: من صلى خلف الصف؛ وجبت عليه الإعادة لقوله ﷺ: لا صلاة لمنفرد خلف الصف ولأنه ﷺ رأى رجلًا يصلي خلف الصف وحده؛ فأمره أن يعيد الصلاة، ولم يستفصله؛ فدل ذلك على أن من صلى خلف الصف وحده يؤمر بالإعادة، لكن إذا جاء والإمام راكعًا، فركع وحده، ثم دخل معه آخر قبل السجود؛ صحت الصلاة.  أما إن صلى ركعة وحده؛ فإن الصلاة لا تصح إلا إذا استأنفها بعد الركعة، استأنف التكبير بالنسبة إلى الباقي، يعني: استأنف دخوله مع إمامه بعد الركعة التي انفرد فيها، اعتقد بطلانها، وأتى بتكبيرة الإحرام في الركعات الباقية؛ صحت، ويقضي ما فاته. المقصود: أن صلاة المنفرد خلف الصف وحده لا تصح مطلقًا، سواء وجد من يصف معه، أو لم يجد، لا يصلي خلف الصف، بل ينتظر حتى يأتي من يصف معه، أو يلتمس فرجة، أو يصف مع الإمام عن يمينه إذا تيسر ذلك، هذا هو الواجب، لكن مجرد أنه كبر وحده، أو ركع وحده، ثم جاء من صف معه؛ هذا صحيح، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14730/هل-من-صلى-ركعة-خلف-الصف-منفردا-ثم-اكتمل-الصف-عليه-الاعادة ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57910.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16091,"question":"يقول السائل أبو معاذ: يقوم بعض الناس بالتسليم مع الإمام، والبعض الآخر يسلم بعد التسليمة الأولى للإمام؛ فهل صلاتهم صحيحة، وما الحكم في هذه الحالة؟","title":"ما حكم تسليم المأموم قبل إمامه؟","answer":"الجواب: الواجب التسليم بعد الإمام؛ النبي ﷺ أمر ألا يسلم إلا بعد سلام الإمام، فلا يجوز للمأموم أن يسلم إلا بعد سلام إمامه، وإذا سلم عامدًا قبل سلام إمامه، أو قبل التسليمة الثانية؛ بطلت صلاته، عليه أن يعيدها إذا كانت فريضة، أما إذا كان ساهيًا لا، إذا كان ساهيًا؛ يعود، ينوي الصلاة، ثم يسلم بعد إمامه، ولا يضر إذا كان ساهيًا.","link":"https://binbaz.org.sa/fatwas/14731/ما-حكم-تسليم-الماموم-قبل-امامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57911.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16105,"question":"أم محمد من منطقة جيزان محافظة صبيا أرسلت بسؤالين، سؤالها الأول تقول: صليت صلاة العصر، وعند سجودي لا أدري هل سجدت سجدة، أم سجدتين، وأكملت بسجود السهو، دون أن أسجد سجدة أخرى رغم شكي، فهل صلاتي صحيحة؟ أم باطلة؟","title":"شك هل سجد سجدة، أم سجدتين فما الحكم؟","answer":"الجواب: الواجب على من شك: هل سجد الثانية؟ أن يسجد الثانية، هذا الواجب: أن يسجد الثانية، ثم يسجد للسهو بعد ذلك، أما هذه التي شكت في السجدة الثانية، ولم تسجد عليها أن تعيد الصلاة، عليها أن تعيد الصلاة؛ لأنها تركت ركنًا متيقنًا مع الشك، فلابد من السجدتين، الواجب عليها إذا شكت أن تأتي بالسجدة الثانية، وتسجد للسهو قبل أن تسلم، تجمع بين الأمرين، تأتي بالسجدة حتى تتيقن أنها سجدت سجدتين، ثم مع ذلك تسجد للسهو من أجل الشك، هذا هو الواجب عليها، ولا يجوز لها التساهل في هذا. إلا إذا كانت عندها وساوس؛ فالأصل السلامة، إذا كان عندها وساوس؛ لا شيء عليها، أما إذا كان لا، سهو عارض؛ فالواجب عليها أن تسجد السجدة الثانية، ثم تسجد للسهو، أما من بلي بالوساوس الكثيرة؛ فعليه أن يطرحها، ويبني على ظنه، ولا يضر، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14752/شك-هل-سجد-سجدة-ام-سجدتين-فما-الحكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57924.mp3","categories":["سجود السهو","الركوع والسجود"]},{"id":16110,"question":"من طبرجل سليم سلامة الشراري بعث برسالة مطولة، ولها جمع من الأسئلة، يقول فيها: إنني -ولله الحمد- مستقيم، وأحفظ بعض سور القرآن الكريم، وأتقدم لأصلي بالناس في أكثر الأحيان، إلا أنني أخطئ، ولا أجد من يفتح علي، فما هو توجيهكم؟","title":"حكم من يؤم الناس ويخطئ ولا يجد من يفتح عليه","answer":"الجواب: لا حرج في ذلك، والحمد لله، إذا كانت الفاتحة قد أتقنتها، وأديتها فالغلط في بعض السور الأخرى، أو الآيات الأخرى لا يضر، ولا يضركم عدم وجود من يفتح عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14759/حكم-من-يوم-الناس-ويخطى-ولا-يجد-من-يفتح-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_749/nour_74912.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16112,"question":"يقول: إذا دخلت المسجد، ووجدت واحدًا يصلي، لكني لا أعلم هل هو يصلي السنة، أم الفرض، ماذا أفعل؟","title":"توجيه لمن دخل المسجد بعد الجماعة ووجد رجلًا يصلي","answer":"الجواب: إذا كان الجماعة، لم يحضروا؛ تنتظر، وتصلي سنة التحية، وإن كانت لها راتبة قبلها كالظهر؛ صليت الراتبة، وتنتظر الجماعة حتى يحضروا، وتصلي معهم. أما إذا كانوا قد صلوا، فتصلي معه حتى تكون جماعة، تكون مأمومًا، وهو إمام حتى يحصل لك فضل الجماعة، ولو كانت نافلة يحصل لك فضل الجماعة، أو تسأل، وتقول: هل صلى الناس؟ إذا كان المسألة فيها إشكال تقول: هل صلى الناس؟ إن كان ما صلوا؛ تنتظر، وإن كان قد صلى الناس تصلي معه؛ حتى يحصل لك فضل الجماعة، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14763/توجيه-لمن-دخل-المسجد-بعد-الجماعة-ووجد-رجلا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_749/nour_74913.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16114,"question":"يقول: إذا دخلت المسجد، ووجدت واحدًا يصلي، لكني لا أعلم هل هو يصلي السنة، أم الفرض، ماذا أفعل؟","title":"توجيه لمن دخل المسجد بعد الجماعة ووجد رجلًا يصلي","answer":"الجواب: إذا كان الجماعة، لم يحضروا؛ تنتظر، وتصلي سنة التحية، وإن كانت لها راتبة قبلها كالظهر؛ صليت الراتبة، وتنتظر الجماعة حتى يحضروا، وتصلي معهم. أما إذا كانوا قد صلوا، فتصلي معه حتى تكون جماعة، تكون مأمومًا، وهو إمام حتى يحصل لك فضل الجماعة، ولو كانت نافلة يحصل لك فضل الجماعة، أو تسأل، وتقول: هل صلى الناس؟ إذا كان المسألة فيها إشكال تقول: هل صلى الناس؟ إن كان ما صلوا؛ تنتظر، وإن كان قد صلى الناس تصلي معه؛ حتى يحصل لك فضل الجماعة، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14763/توجيه-لمن-دخل-المسجد-بعد-الجماعة-ووجد-رجلا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_749/nour_74913.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16116,"question":"من أم الناس سماحة الشيخ وهو على ذلكم المعتقد؟","title":"حكم إمامة من يعتقد أن الله في كل مكان","answer":"الجواب:  الذي يؤم الناس لا يصلى خلفه، من كان يعتقد أن الله في كل مكان هذا كافر ضال، لا يصلى خلفه، ولا يجوز أن يتخذ إمامًا، بل يجب أن يبعد، ويجب على المسؤولين أن يبعدوه، وأن يولوا غيره من أهل السنة والجماعة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14766/حكم-امامة-من-يعتقد-ان-الله-في-كل-مكان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_803/nour_80306.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16118,"question":"يقول: يحصل أحيانًا أن نبتعد عن المسجد لبعض المناسبات، فهل لنا أن نؤذن، ونقيم، ونصلي حيث نحن؟ أم لا بد من الصلاة في المسجد، حيث يقول الرسول ﷺ: لا صلاة لجار المسجد إلا في المسجد؟","title":"حكم صلاة الجماعة لمن هم بعيدون عن المسجد","answer":"الجواب: الحديث هذا ضعيف، ولكن يغني عنه أحاديث صحيحة، مثل قوله ﷺ: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر قيل لابن عباس: ما هو العذر؟ قال: \"خوف، أو مرض\" ومثل قوله ﷺ للأعمى لما سأله قال: ليس لي قائد يقودني إلى المسجد، فقال له ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم. قال: فأجب. فالصلاة في الجماعة في المساجد أمر واجب إلا من عذر شرعي، فإذا كنتم في محل تسمعون النداء؛ وجب عليكم أن تصلوا مع الناس، وإذا كنتم بعيدين لا تسمعون النداء العادي بالصوت العادي بغير مكبر؛ فلا حرج عليكم أن تصلوا جماعةً في محلكم لبعدكم؛ لأن صوت المكبر قد يسمع من بعيد، فإذا كان في الإمكان حضوركم، والصلاة مع الجماعة في قرب المسافة؛ وجب عليكم أن تحضروا المسجد. أما إن كانت المسافة بعيدة، وقد تذهبون؛ تفوتكم الصلاة لبعد المسافة بحيث لا تسمعون النداء لو كان النداء بغير مكبر لبعد المسافة؛ فلا حرج عليكم أن تصلوا جماعة، نعم.","link":"https://binbaz.org.sa/fatwas/14769/حكم-صلاة-الجماعة-لمن-هم-بعيدون-عن-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_749/nour_74914.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16143,"question":"من الأخت المستمعة (أ. أ) رسالة، وتسأل فيها وتقول: إذا كنت في صلاة جماعة في المسجد، وكنت من أحد المأمومين، ونسيت، وتركت واجبًا من واجبات الصلاة، فهل أجبره بسجود السهو؟ أم يكفيني الإمام في ذلك؛ لأني مع جماعة؟ جزاكم الله خيرًا.","title":"ما يتحمله الإمام على المأموم؟","answer":"الجواب: إذا كنت مع الإمام من أول الصلاة، ونسيت بعض الواجبات؛ فليس عليك سجود، سهو يتحمله الإمام، مثل إذا نسيت سبحان ربي الأعلى، أو سبحان ربي العظيم، أو ربنا ولك الحمد، هذا يتحمله الإمام. أما إذا نسيت ركنًا لا بد منه، ما سجدتي، لا بد من السجود، فإذا تركت سجدة من ركعة؛ تقومين إذا سلم تأتي بركعة كاملة، أو نسيت الركوع، ما ركعت مع الإمام نسيانًا، إذا سلم الإمام تأتي بركعة كاملة؛ لأن الركوع، والسجود ركنان لابد منهما. أما إذا نسيت شيئًا واجبًا، مثل الفاتحة نسيتيها، واجبة الفاتحة على المأموم وجوبًا، ليست ركنًا في حق المأموم، فإن نسيت الفاتحة، أو نسي المأموم الفاتحة، ليس عليه شيء، وليس عليه سجود سهو إذا كان مع الإمام من أول الصلاة، أما إذا كان مسبوقًا؛ فإنه يسجد السهو، إذا قضى ما عليه، إذا ترك واجبًا ساهيًا؛ فإنه يسجد للسهو بعد قضائه، ما عليه إذا كان مسبوقًا، أما إذا كان مع الإمام من أول الصلاة؛ فإنه يتحمله الإمام، إذا ترك واجبًا فقط كقراءة الفاتحة في حق المأموم، تسبيح الركوع والسجود قول: ربنا ولك الحمد، هذا واجب، فإذا سها عنه المأموم؛ تحمله الإمام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14819/ما-يتحمله-الامام-على-الماموم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_804/nour_80411.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16145,"question":"إذا كنت في صلاة الظهر، وبعد إتمام الصلاة، وأنا في الجلوس الأخير أي: في التشهد الأخير شككت هل جلست للتشهد الأول، أو لم أجلس، فماذا أفعل في مثل هذه الحال؟ جزاكم الله خيرًا.","title":"ما يعمل من شك في أداء التشهد الأوسط عند التسليم؟","answer":"الجواب: الأصل السلامة، تكمل التشهد، وتسلم والحمد لله، ما عليك شيء؛ لأن الأصل أنك أديته، فالشك لا أثر له في هذا؛ لأنه قد مضى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14799/ما-يعمل-من-شك-في-اداء-التشهد-الاوسط-عند-التسليم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_713/nour_71306.mp3","categories":["سجود السهو"]},{"id":16169,"question":"في سؤاله الأخير يقول: يوجد عندنا مسجدان في القرية أحدهما قريب للمنزل، والآخر بعيد بعض الشيء، علمًا بأن المسجد الأول لا يجتمع فيه الناس المجاورون له، ولا يخرجون للصلاة فيه جماعة، والمسجد الآخر يجتمع فيه عدد لا بأس به من الناس، وأنا أقوم بالصلاة في المسجد القريب أنا وأحد الإخوة وبصفة دائمة، فبماذا تنصحوننا، هل نصلي في هذا المسجد القريب أنا وأخي في الله القائم على هذا المسجد؟ أم أتركه وأذهب إلى المسجد البعيد حيث يجتمع عدد كبير من الناس، ويبقى المسجد الأول لا يصلي فيه إلا شخص واحد؟ أفيدونا مأجورين جزاكم الله خيرًا، وبماذا تنصحون إخواننا المجاورين للمسجد، والذين لا يؤدون الصلاة فيه جماعة؟","title":"أفضلية الصلاة في المسجد الذي به جماعة أكثر","answer":"الجواب: الصلاة في المسجد البعيد الذي فيه الجماعة الكثيرة أفضل، يقول النبي ﷺ في الحديث الصحيح: صلاة الرجل مع الرجل أزكى من صلاته وحده، وصلاته مع الرجلين أزكى من صلاته مع الرجل، وما كان أكثر فهو أحب إلى الله ويقول ﷺ: أعظم الناس في الصلاة أجرًا أبعدهم فأبعدهم ممشى. والمسجد القريب لابد له علة لم يتركوه إلا لعلة، فلابد أن يسألوا عن علة تركهم له، إما لأنه صغير، أو لأنه ليس فيه الخدمات المتوفرة، أو لأسباب أخرى لابد، فالعلة التي من أجلها ترك الجماعة الصلاة في الصغير لابد أن تعرف، وإذا كان المسجد القريب قد توافرت فيه الشروط، فلماذا يتركونه جيرانه؟ لابد من أسباب، لابد أن توضح الأسباب للعالم الذي عندكم، أو المحكمة، لابد لم يتركوه إلا لأسباب اقتضت ذلك. فالحاصل: أن المسجد البعيد، والأكثر جماعة هو الأفضل، أما المسجد القريب الذي تركه الناس؛ فلابد أن تعرف علته، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14852/افضلية-الصلاة-في-المسجد-الذي-به-جماعة-اكثر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_805/nour_80508.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16178,"question":"تقول: إذا صليت مع الجماعة، وأخطأت خطأ يستوجب مني سجود السهو، فما الحكم؟","title":"حكم سهو المأموم خلف إمامه","answer":"الجواب:  إذا صليت مع الجماعة من أول الصلاة، فنسيت مثل: سبحان ربي الأعلى، أو نسيت سبحان ربي العظيم في الركوع، أو رب اغفر لي، بين السجدتين، فإنه ليس عليك سجود سهو يتحمله الإمام -والحمد لله- أو نسيت الفاتحة يتحمله الإمام -والحمد لله- نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14832/حكم-سهو-الماموم-خلف-امامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_750/nour_75011.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16194,"question":"يقول: إذا وجبت الصلاة، ونحن جماعة ثلاثة، الثالث منا صبي عمره اثنتا عشرة سنة تقريبًا، ولم يبلغ الحلم، فهل نصلي بجنب الإمام، أو يصطف أحدنا والصبي خلف أحدنا لكون أحدنا إمامًا؟ جزاكم الله خيرًا.","title":"كيفية صلاة الجماعة لمن كانوا ثلاثة","answer":"الجواب: إن شاؤوا صفوا.. إن شاء صف، إذا كانوا ثلاثة؛ يصف الإمام أمامهم، ثم يصف الثاني مع الصبي الذي بلغ اثني عشر سنة، يصفان خلف الإمام، هذا هو السنة، حتى ولو كان أقل من اثني عشر سنة، حتى ولو كان ابن سبع، أو ثمان، يصف مع الكبير، النبي ﷺ صلى بأنس ومعه اليتيم، جعلهم خلفه صفًا. فالمقصود: أنه إذا كان مع الإمام رجلان، أو صبيان، أو رجل وصبي؛ فإنهم يصفون خلفه، يكون الرجلان خلفه، والصبيان خلفه، والرجل والصبي خلفه. أما المرأة إذا كان معهم نساء يكون خلف الرجال، ولو مرأة واحدة، تكون خلف الرجال وحدها، لا تصف مع الرجال، هذا هو المشروع، ولو صلوا عن يمينه وشماله صح، لكن السنة أن يكونوا خلفه، لما صف معه ﷺ جابر وجبار؛ جعلهما خلفه -عليه الصلاة والسلام- ولما صلى في بيت أنس بأنس وأخيه؛ جعلهما خلفه، وكان أخوه أصغر منه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14905/كيفية-صلاة-الجماعة-لمن-كانوا-ثلاثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_806/nour_80615.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16216,"question":"من نسي الركوع فماذا يفعل، ولا سيما إذا ذكر قبل أن يسجد؟","title":"حكم من نسي الركوع وذكر قبل أن يسجد","answer":"الجواب: إذا ذكر الركوع يقوم، إنْ كان قد سجد يقوم يقف، ويركع، وإن كان قد سجد كذلك يقوم، ويأتي بالركوع، ثم ينتصب، ثم يسجد بعد ذلك، وعليه سجود السهو قبل أن يسلم، وإن سجد بعد السلام؛ فلا بأس، لكن الأفضل في مثل هذا قبل السلام. فالمقصود: أنه إذا هوى للسجود، ثم تذكر أنه لم يركع؛ ينتصب ويركع، وإن كان ذكر في السجود، أو وهو جالس للتشهد؛ يقوم ويأتي بالركوع، ثم يرفع، ثم يسجد، ثم يكمل، ثم يسجد للسهو، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14887/حكم-من-نسي-الركوع-وذكر-قبل-ان-يسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_713/nour_71307.mp3","categories":["سجود السهو","الركوع والسجود"]},{"id":16219,"question":"المستمع (ذ. ر. ت) يقول: إذا سبق المأموم الإمام في الركوع، أو السجود، أو الرفع منهما من غير تعمد فهل تبطل الركعة، أم ماذا عليه؟","title":"حكم مسابقة الإمام في شيء من الصلاة دون تعمد","answer":"الجواب: إذا سبقه من غير تعمد لا تبطل الركعة، لكن يرجع فيركع بعده، إذا رفع قبله في الركوع، والسجود، ثم انتبه؛ يعود ويركع معه، أو بعده حتى يركع بعده، ولا شيء عليه من أجل الجهل، أما إذا تعمد هذا؛ فهو متلاعب، تبطل صلاته، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14891/حكم-مسابقة-الامام-في-شيء-من-الصلاة-دون-تعمد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_713/nour_71308.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16332,"question":"تقول: هل لي أن أصلي مقتدية بما أسمع في الراديو؟","title":"حكم الاقتداء بالإمام في الراديو","answer":"الجواب: ليس لك ذلك، صلي وحدك، ولا تقتدي بما في الراديو، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15022/حكم-الاقتداء-بالامام-في-الراديو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_753/nour_753018.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16407,"question":"نعود في بداية هذه الحلقة إلى رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين آثر فيها عدم ذكر اسمه، عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة له جمع من الأسئلة يقول: إذا كان الإنسان قد أتى المسجد وهو إمام، ولم يأت أحد ليصلي، ثم صلى، فحضر أناس بعدما صلى، هل يصلي معهم، أو بهم؟ أو تكفيه صلاته؟ جزاكم الله خيرًا.","title":"ما المشروع إذا جاء الناس بعدما صلى الإمام منفردًا؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالمشروع للإمام إذا جاء المسجد ألا يعجل، وأن ينتظر المأمومين، ولو تأخر عن العادة قليلًا؛ لأن الناس قد يشغلون بأشغال تمنعهم من التبكير، فإذا تأخروا تأخرًا خلاف العادة، وصلى، ثم جاؤوا؛ فإنه يشرع له أن يصلي بهم، وتكون له نافلة، كما كان معاذ يصلي مع النبي ﷺ العشاء، ثم يرجع، فيصلي بأصحابه، وهي له نافلة، ولهم فريضة، فإذا صلى بهم، فجزاه الله خيرًا، وإن أمهم غيره، ولم يصل بهم؛ فلا حرج عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15114/ما-المشروع-اذا-جاء-الناس-بعدما-صلى-الامام-منفردا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_755/nour_75501.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16408,"question":"هل يجوز لمن به عذر كسلس بول، أو غيره أن يصلي بالناس إمامًا، أي: هل تجوز إمامة ذلك في الصلاة؟","title":"هل يجوز لمن به سلس بول أن يصلي إمامًا؟","answer":"الجواب: فيه خلاف بين أهل العلم، والأولى ترك ذلك، الأولى ألا يؤم الناس ما دام معه سلس؛ لأن طهارته ناقصة، فالأولى، والأحوط ألا يؤمهم، يؤمهم غيره، وإن أمهم صحت الصلاة -إن شاء الله- لكن ترك ذلك أحوط؛ خروجًا من خلاف العلماء، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15109/هل-يجوز-لمن-به-سلس-بول-ان-يصلي-اماما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58122.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16448,"question":"هذا سائل للبرنامج يقول سماحة الشيخ: هل تبطل صلاة المأموم الذي يصلي خلف إمام وهو كاره له؟","title":"حكم صلاة المأموم خلف إمام يكرهه","answer":"الجواب: لا، لا تبطل صلاته، لكن إذا كان كارهًا له بحق، وأحب أن يصلي خلف غيره؛ لا بأس، وإلا فالأمر واسع، لا تبطل الصلاة إذا صلى خلف إمام، وإن كان بينه وبينه شيء؛ صلاته صحيحة، أو يكرهه؛ لأنه يتعاطى بعض المعاصي؛ صلاته صحيحة، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/15153/حكم-صلاة-الماموم-خلف-امام-يكرهه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58203.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16451,"question":"رسالة من أحد الإخوة المستمعين يسأل فيها سماحتكم، ويقول: ما حكم من يصلي الصلوات الخمس في بيته مع أولاده البنين والبنات بحجة أن النساء يتساهلن في أداء الصلوات في غيابه إذا ذهب إلى المسجد، مع أنه يسمع النداء؟ وما حكم الأولاد الذكور الذين يمنعهم من الذهاب إلى المسجد، مع رغبتهم في صلاة الجماعة، ولكن يخافون من أبيهم؟","title":"ما حكم الصلاة في البيت بحجة تساهل النساء والأولاد؟","answer":"الجواب: الواجب عليه أن يتقي الله، وأن يصلي في المسجد هو وأبناؤه، أما النساء فيعلمهن أن يصلوا قبله، أو بعده، قبل أن يذهب، أو بعد أن يذهب، الأمر واسع -بحمد الله- في إمكانهن أن يصلين بعد مجيئه من صلاة الجماعة الوقت واسع، أو في حال ذهابه إلى الجماعة. المقصود: أن هذا ليس بعذر، النساء يعلمن، ويؤكد عليهن في أداء الصلاة، وهذا واجبهن، والصلاة عمود الإسلام في حق الجميع، في حق الرجال والنساء، من تركها كفر؛ نسأل الله العافية. والواجب عليه هو أن يصلي في المسجد، وأولاده الذكور، هذا هو الواجب عليه؛ لقول النبي ﷺ: من سمع النداء، فلم يأت؛ فلا صلاة له إلا من عذر قيل لابن عباس ما هو العذر؟ قال: خوف، أو مرض، وفي الصحيح عن النبي ﷺ أنه جاءه رجل أعمى، فقال: يا رسول الله! ليس لي قائد إلى المسجد يقودني، فهل لي من رخصة أن أصلي في بيتي، فقال له ﷺ: هل تسمع النداء بالصلاة؟  قال: نعم. قال: فأجب وفي رواية: لا أجد لك رخصة فيقول ﷺ لهذا الأعمى: أنه ما يجد له رخصة، ويقول له: لا أجد، كيف البصير المعافى؟! وقد ثبت في الصحيحين أيضًا عن النبي ﷺ أنه قال: قد هممت أن آمر بالصلاة، فتقام، ثم آمر رجلًا، فيؤم الناس، ثم أنطلق برجال معهم حزم من حطب إلى رجال لا يشهدون الصلاة، فأحرق عليهم بيوتهم هذا يدل على عظم الأمر، وأن التاركين لصلاة الجماعة جديرون بالعقوبة. فوصيتي لهذا الرجل، وأبنائه أن يتقوا الله، وأن يصلوا مع الجماعة، وأن يحذروا عقاب الله وغضبه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15168/ما-حكم-الصلاة-في-البيت-بحجة-تساهل-النساء-والاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_716/nour_71601.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16453,"question":"إذا شك الإنسان في صلاته، فكيف يكون السجود؟ وهل يسمى حينئذ سجود الشك؟","title":"موجبات سجود السهو","answer":"الجواب:  إذا شك في صلاته؛ يسجد للسهو، بعدما يعمل ما شرع الله له، إذا شك هل هي ثلاث، أو أربع؛ يجعلها ثلاثًا، يبني على اليقين، إذا شك هل هي ثنتان، أو ثلاث؛ يجعلها ثنتين في الرباعية، أو في المغرب، إذا شك: هي ثنتان، أو واحدة في الثنائية، كالفجر، والجمعة؛ جعلها واحدة، وبنى على اليقين، ويسجد للسهو قبل أن يسلم، وإن سجد بعد السلام؛ فلا بأس. وهكذا لو ترك التشهد الأول ساهيًا، وقام عنه؛ فإنه يسجد للسهو قبل أن يسلم سجدتين، يقول فيهما مثل ما يقول في سجود الصلاة: سبحان ربي الأعلى، سبحان ربي الأعلى، سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، يدعو فيه مثل سجود الصلاة سواء. وهكذا لو ترك تسبيحة الركوع: سبحان ربي العظيم في الركوع، وسبحان ربي الأعلى في السجود؛ سهوًا يشرع له السجود أيضًا للسهو، مثل ما لو ترك التشهد الأول. وهكذا إذا سلم عن نقص ركعة، أو ركعتين، ثم تنبه ونبه؛ يكمل صلاته، ويسجد للسهو، لكن الأفضل يكون سجود السهو بعد السلام في هذه الحالة، إذا سلم عن نقص ركعة، أو ركعتين الأفضل يكون سجوده بعد السلام، وإن سجد قبل السلام؛ فلا بأس. وهكذا لو بنى على غالب ظنه بأن اشتبهت عليه الصلاة، هل صلى ثلاثًا، أم أربعًا، ولكن غلب على ظنه، وتحرى الصواب، وجعلها ثلاثًا، وكمل؛ فإنه يسجد للسهو، والأفضل أن يكون بعد السلام. وهكذا لو غلب على ظنه أنها أربع، واعتمدها أربعًا؛ فإنه إذا سلم؛ يسجد للسهو أفضل بعد السلام، وإن سجد للسهو قبل السلام؛ فلا بأس في هذه الحالة. والخلاصة: أنه يشرع سجود السهو قبل السلام في جميع السهو، يشرع سجود السهو قبل السلام في جميع السهو، هذا هو الأفضل، إلا في حالتين: إحداهما: إذا سلم عن نقص ركعة، أو أكثر، ثم نبه أو تنبه؛ فإنه يكمل الصلاة، ثم يسلم، ثم يسجد للسهو بعد السلام، هذا هو الأفضل؛ لفعله ﷺ. الحال الثاني: إذا بنى على غالب ظنه؛ تحرى الصواب، وبنى على غالب ظنه؛ فإنه يكمل على غالب ظنه، ويكون سجود السهو بعد السلام، هذا هو الأفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15169/موجبات-سجود-السهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_755/nour_75517.mp3","categories":["سجود السهو"]},{"id":16463,"question":"يقول في سؤاله الثاني: إذا كان مع الإمام واحد أول الصلاة، ثم جاء ثالث، وكان يريد إدراك الركعة والإمام راكع، هل يقف على يمين ذلك المأموم، أم يجذب المأموم الأول إليه، ويبقى في الصف الثاني؟ جزاكم الله خيرًا.","title":"ما يفعل من أدرك الإمام راكعًا وعن يمينه مُصل؟","answer":"الجواب: يركع مع الأول عن يمينه، أو عن يسار الإمام حتى لا تفوته الركعة، ثم يتأخران جميعًا خلف الإمام، إذا جاء والإمام راكع، ومعه واحد فهو مخير، إن شاء صف مع الذي عن يمينه، وإن شاء صف عن يسار الإمام؛ لأن يمينه مشغولة، ثم بعد الرفع يتأخرا، السنة أن يتأخرا خلف الإمام، هذا هو السنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15208/ما-يفعل-من-ادرك-الامام-راكعا-وعن-يمينه-مصل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_813/nour_81309.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16479,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من مكة المكرمة باعثتها إحدى الأخوات المستمعات من هناك رمزت إلى اسمها بالحروف (أ. م. ب) لها جمع من الأسئلة في أحدها تقول: سجود السهو هل هو سجدة واحدة، أم سجدتين؟","title":"كم عدد سجدات السهو؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فسجود السهو سجدتان، هكذا فعل النبي ﷺ وهما واجبتان في حق من سها عن واجب، أو فعل ما لا يجوز في الصلاة سهوًا، ومحلها قبل السلام وبعده، إن سجدهما قبل السلام؛ فلا بأس، وإن سجدهما بعد السلام؛ فلا بأس، وهما قبل السلام أفضل، إلا في حالين: إحداهما: إذا سلم عن نقص ركعة، فأكثر سهوًا؛ فإنه يكمل، ثم يسجد للسهو بعد السلام. والحال الثانية: إذا بنى على غالب ظنه، وتحرى الصواب، واجتهد، وكمل الصلاة، ثم سلم، فإنه يسجد للسهو بعد ذلك، يكون سجوده بعد السلام في هاتين الحالتين، هذا هو الأفضل، وإن سجد قبل السلام؛ فلا حرج في ذلك، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15181/كم-عدد-سجدات-السهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_756/nour_75601.mp3","categories":["سجود السهو"]},{"id":16499,"question":"سماحة الشيخ: إذا كان المسجد من دورين، فهل يشترط على من كان في الدور الثاني أن يرى الإمام، أو بعض المأمومين؟","title":"حكم الصلاة في الدور الثاني من المسجد","answer":"الجواب: هذا الظاهر أنه لا يشترط؛ لأنه تابع المسجد، مثل الخلوة في المسجد، تابع للمسجد إذا سمع الصوت. المقدم: إذا سمع الصوت فهو كاف. الشيخ: كفى إن شاء الله. المقدم: وإن لم ير الإمام، أو بعض المأمومين؟ الشيخ: إذا كان تابع المسجد، صَرْح تابع له، أو خلوة تابعة له. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15257/حكم-الصلاة-في-الدور-الثاني-من-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_814/nour_81406.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16538,"question":"يسأل عن سجود السهو لو سمحتوا يقول: هل على من زاد في الصلاة، فقرأ سورة قصيرة، أو آيات بعد الفاتحة في الركعة الثالثة، أو الرابعة مثلًا؟","title":"حكم الزيادة على الفاتحة في الركعتين الثالثة والرابعة","answer":"الجواب: ليس عليه سجود سهو؛ لأن هذه الزيادة إما أن تكون مشروعة، أو غير مشروعة، فإن كانت مشروعة كما في الركعة الأولى والثانية هذا أمر معلوم، لو نسيها ما عليه شيء، وإن كانت غير مشروعة في الثالثة والرابعة في العصر، وفي المغرب والعشاء؛ فالإتيان بها لا يضر، ولا يبطل الصلاة، ولا يؤثر فيها، الأمر فيها واسع، ولهذا ذهب بعض أهل العلم إلى شرعية الزيادة في الثالثة والرابعة في الظهر في بعض الأحيان، لحديث أبي سعيد -رضي الله تعالى عنه- أنه قال: \"حزرنا قراءة النبي ﷺ في الظهر قدر الم تنزيل السجدة، وفي الأخريين على النصف من ذلك\".  فقوله: \"على النصف من ذلك\" يدل على أنه يقرأ مع الفاتحة زيادة، فإذا فعلها بعض الأحيان؛ فلا حرج. وجاء عن الصديق  في الموطأ بسند جيد: أنه قرأ في الثالثة في المغرب: رَبَّنَا لا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ [آل عمران:8] وجاء في بعض الأحاديث أن بعض أئمة الأنصار كان يقرأ في كل ركعة زيادة قل هو الله أحد مع الفاتحة، وأقره النبي ﷺ قال: \"إنها صفة الرحمن، وأنا أحب أن أقرأها\" كان يقرأها في كل ركعة، فأقره النبي ﷺ. فالأمر في هذا واسع، فلو زاد الإنسان سواء كان في الثالثة، أو الرابعة في العصر، والعشاء، أو في الثالثة في المغرب؛ فلا حرج في ذلك، وليس عليه سجود سهو، لكن ترك ذلك أفضل، أما في الظهر فالأمر فيها واسع، في الظهر في الثالثة والرابعة إن زادها بعض الأحيان عملًا بحديث أبي سعيد، فذلك حسن، ويكون في الأغلب لا يزيد، عملًا بحديث أبي قتادة  في الصحيحين أنه ﷺ كان يقرأ في الأخريين من الظهر والعصر بفاتحة الكتاب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15269/حكم-الزيادة-على-الفاتحة-في-الركعتين-الثالثة-والرابعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_815/nour_81503.mp3","categories":["سجود السهو","القراءة في الصلاة"]},{"id":16549,"question":"إذا كان الإمام يكرر السور في الصلاة، فهل لي الصلاة في مسجد آخر في نفس الحي أحيانًا؛ لأنني أحب تدبر ما يقوله الإمام من القرآن؟","title":"حكم الصلاة في المسجد البعيد لأجل الخشوع","answer":"الجواب: لا حرج في تكرار السور... لا حرج أن يكرر في بعض الصلوات، السور يقرأ مثلًا في المغرب سورة، ويعيدها في العشاء، أو يعيدها في الفجر؛ لا حرج في ذلك، الحمد لله، وأنت مخير صليت في هذا المسجد، أو في هذا المسجد، انظر ما هو أصلح لقلبك، وما هو أنفع لك فافعله، إلا إذا كان ذهابك عن هذا المسجد الذي حولك قد يسبب تهمتك، وأنك لا تحضر الجماعة؛ فينبغي لك ألا تذهب؛ حماية لعرضك، وظن السوء بك، تصلي مع الناس الذين حولك؛ حتى يعرفوا أنك تصلي في الجماعة، وحتى تصون عرضك عن هتك الناس له، وتهمتك، وعن تهمتك بالسوء. أما إذا كان لا يترتب على صلاتك في المسجد الآخر محذور، وأنت ترى أن صلاتك مع الإمام الثاني أنفع لك، وأخشع لقلبك؛ فلا حرج في ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15279/حكم-الصلاة-في-المسجد-البعيد-لاجل-الخشوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_757/nour_75711.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16560,"question":"يقول: ما رأي سماحتكم في الإمام الذي يهمل عمله، ويضع حمل العمل على الحارس من أذان، وإقامة وصلاة بالناس، والقيام بشؤون المسجد، وهل المرتب الذي يتقاضاه حلال؟","title":"حكم إهمال إمام المسجد عمله وإنابة غيره","answer":"الجواب: هذا من الخيانة، لا يجوز له أن يعمل هذا العمل، والواجب رفع أمره إلى الجهة المسؤولة حتى يستقيم، أو يبدل بخير منه، هذا على الجماعة المسؤولين أن يرفعوا أمره، نسأل الله لنا وله الهداية.","link":"https://binbaz.org.sa/fatwas/15307/حكم-اهمال-امام-المسجد-عمله-وانابة-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_816/nour_81616.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16563,"question":"يقول: أحفظ كثيرًا من كتاب الله، وأجيد قراءته قراءة جيدة، وأؤم المصلين في كثيرٍ من الأحيان، إلا أنني لا أعرف كثيرًا من معاني الآيات، فهل تجوز الإمامة، والحال ما ذكر؟","title":"حكم إمامة من لا يعرف معاني الآيات","answer":"الجواب: نعم لا حرج في ذلك، وإن كنت تجهل بعض المعاني مادمت بحمد الله تجيد القراءة، فالحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15297/حكم-امامة-من-لا-يعرف-معاني-الايات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_816/nour_81611.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16587,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول في نهايتها: (أبو عبد العزيز . خ. ب. ر) أخونا يقول: رجل تأخر، ولم يصل المغرب حتى دخل وقت العشاء، فلما أتى إلى المسجد؛ رأى الإمام يصلي بالجماعة صلاة العشاء، وهو في الركعة الثانية، فدخل معهم، وصلى العشاء، ثم قام بعدها، وصلى المغرب، فقلت: كان الأولى بك أن تدخل مع الإمام، ونيتك صلاة المغرب، ثم تقوم بعدها، وتصلي العشاء منفردًا، أو مع جماعة أخرى، فقال: كيف أصلي معه بنية المغرب، وهو في الركعة الثانية، هل أسلم مع الإمام، أم أقوم، وآتي بالركعة التي فاتت؛ خوفًا من إنكار الذي يصلي بجواري، فسوف يقول لي: قم وائت بركعة، فاحترت، ثم بعثت بالسؤال إليكم، أفتونا بارك الله في أعماركم، وفي أعمالكم، وعلمكم، وزادكم خيرًا.","title":"حكم من لم يدرك صلاة المغرب ودخل وهم يصلون العشاء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالمشروع لك، وأمثالك إذا جئت والإمام في الصلاة -صلاة العشاء- وأنت لم تصل المغرب أن تدخل معهم بنية المغرب، ولا حرج في ذلك في أصح قولي العلماء. فإذا كان قد صلى واحدة نويت المغرب، وصليت معهم الثلاث، وتكفيك عن المغرب، وتسلم معهم، وإن كنت في أول الصلاة، جئتهم وهم في أول الصلاة، دخلت معهم، وإذا فرغت من الركعة الثالثة؛ جلست تنتظر الإمام حتى يسلم، ثم تسلم معه، وتكفيك عن المغرب، ثم تصلي العشاء بعد ذلك وحدك إن لم يتيسر جماعة أخرى، هذا هو المشروع لك ولأمثالك. ولا حرج في اختلاف النية، أنت نويت المغرب، وهم ينوون العشاء، لا حرج في ذلك، لأن الترتيب واجب، الترتيب بين الصلوات واجب، فالمغرب تؤدى قبل العشاء، وهكذا الظهر قبل العصر. وهكذا لو جاء إنسان وهم يصلون العصر، وعليه الظهر؛ يصلي معهم العصر بنية الظهر، فإذا فرغ من العصر من صلاته معهم الظهر؛ صلى العصر بعد ذلك وحده، أو مع جماعة إن تيسرت، هذا هو الصواب في هذه المسألة، والله ولي التوفيق، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15316/حكم-من-لم-يدرك-صلاة-المغرب-ودخل-وهم-يصلون-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_716/nour_71604.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16606,"question":"أسمع في نهاية الصلاة من بعض الناس قوله عندما يسلم من الصلاة يقول أحدهم لأخيه: تقبل الله العظيم، فيرد عليه الآخر: منا ومنكم صالح الأعمال فهل هذا من السنة؟","title":"حكم المداومة على قول المصلين لبعضهم بعد الصلاة: تقبل الله","answer":"الجواب: لا أصل لهذا، ليس من السنة، ولا أصل له، نعم. المقدم: جزاكم الله خيرًا، تنصحون سماحة الشيخ بالابتعاد عن مثل هذه الألفاظ، أو لا حرج في قولها؟ الشيخ: لا، لا، ينبغي ترك ذلك؛ لأنه غير مشروع. المقدم: غير مشروع. جزاكم الله خيرًا، ما الفرق بينها وبين الدعاء بالقبول في الأعمال؟سماحة الشيخ. الشيخ: إذا كان عارض ما يعتاده، في بعض الأحيان يفعله لا بأس، مثلما يقول له في الطريق... غفر الله لنا ولك، تقبل الله منا ومنك، أو عند السلام عليه في البيت، أو لا بأس، لكن كونه يعتاد إذا سلم من الصلاة يقول هذا الكلام عادة هذا ما هو مشروع، هذا بدعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15337/حكم-المداومة-على-قول-المصلين-لبعضهم-بعد-الصلاة-تقبل-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81717.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16621,"question":"تسأل أختنا هذا السؤال فتقول: إذا نسي المصلي، وسلم بعد ركعتين في الصلاة الرباعية، أو المغرب، وتذكر بعد ما سلم، هل يأتي بالركعة، أو الاثنتين الباقيتين، أو يعيد الصلاة؟","title":"ما يفعل من نسي فسلم من ركعتين؟","answer":"الجواب: إذا سلم الرجل، أو المرأة من ثنتين في الظهر، أو العصر، أو العشاء، أو المغرب ناسيًا، ثم تذكر؛ يتم الصلاة فقط، يقوم، ويأتي بما بقي، ويسجد للسهو بعد السلام، يسلم بعد التحيات، وبعد الدعاء، ثم يسجد للسهو سجدتين بعد السلام، هذا هو الأفضل، كما فعله النبي ﷺ فإنه في بعض الصلوات سلم من ثنتين في الظهر، أو العصر، ثم نبه؛ فقام، وكمل -عليه الصلاة والسلام- فلما كمل وسلم؛ سجد للسهو بعد السلام سجدتين، وإن سجد قبل السلام؛ أجزأ ذلك، ولا حرج، لكن الأفضل بعد السلام لفعله، عليه الصلاة والسلام. وسجوده للسهو مثل سجود للصلاة سواء، يقول فيه: سبحان ربي الأعلى، سبحان ربي الأعلى، يدعو فيه مثل سجود الصلاة سواء. وهكذا لو سلم من واحدة في الفجر، أو في الجمعة، أو في العيد، ثم تنبه، أو نبه؛ يقوم يكمل، يأتي بالثانية بعد قراءة التحيات، والصلاة على النبي ﷺ وبعد الدعاء، يسلم، ثم يسجد للسهو سجدتين بعد ذلك، هذا هو الأفضل، وإن سجدهما قبل السلام؛ أجزأ ذلك، والحمد لله. وهكذا لو بنى على غالب ظنه، لو بنى المصلي على غالب ظنه يعني: شك هو في الثالثة، أو الرابعة، وغلب على ظنه أنه في الثالثة، وأتمها أربعًا؛ الأفضل يكون سجوده بعد السلام؛ لأن النبي ﷺ قال فيمن شك في صلاته، وتحرى الصواب، وأتم ما عليه، ذكر أنه يسجد بعد السلام.  ففي هاتين الحالتين الأفضل أن يكون السجود بعد السلام في الحالة الأولى: إذا سلم عن نقص ركعة، أو أكثر يأتي بالباقي، ثم يسلم، ثم يسجد للسهو، هذا هو الأفضل. والحالة الثانية: إذا بنى على غالب ظنه كملها، أو .. المقصود: كملها على غالب ظنه؛ فإنه يكمل، ويسلم، ثم يسجد للسهو سجدتين، هذا هو الأفضل، وإن سجد سجدتين قبل السلام؛ فلا حرج. أما فيما سوى ذلك يكون السجود قبل السلام أفضل فيما سوى هاتين الحالتين يكون السجود للسهو قبل السلام، هذا هو الأفضل. مثلًا لو شك: هي ثنتين، أو ثلاث؛ جعلها ثنتين، بنى على اليقين، شك هي ثلاث، أو أربع، الظهر مثلًا يجعلها ثلاثًا، يبني على اليقين، ثم يكمل، ثم إذا فرغ من التحيات، والدعاء، يسجد سجدتين للسهو قبل أن يسلم. مثلًا: لو قام عن التشهد الأول في الظهر، أو العصر، أو المغرب، أو العشاء، قام عن التشهد الأول ساهيًا؛ فإنه إذا كمل يسجد للسهو قبل السلام، كما فعله النبي ﷺ هذا هو الأفضل، أو نسي: (سبحان ربي العظيم) في الركوع، ما قالها، وهو إمام، أو منفرد، أو نسيها، وهو .. أو نسيها في السجود: (سبحان ربي الأعلى) يسجد للسهو قبل السلام، أو نسي قول: (ربنا ولك الحمد) بعد الركوع، الإمام، أو المنفرد، أو نسي الإمام (سمع الله لمن حمده) أو المنفرد؛ عليه سجود السهو، الأفضل قبل السلام. وإن سجد بعد السلام؛ فلا بأس، وهكذا لو نسي (رب اغفر لي) بين السجدتين؛ يسجد للسهو سجدتين قبل السلام أفضل، وإن سجدهما بعد السلام؛ فلا حرج في ذلك. وسجود السهو يقول فيه مثل ما يقول في سجود الصلاة: سبحان ربي الأعلى، سبحان ربي الأعلى، ويدعو فيه: اللهم اغفر لي ذنبي كله، دقه وجله... إلى آخره، مثل سجود الصلاة سواء. أما المأموم إذا سها عن تسبيح الركوع، والسجود، أو (رب اغفر لي) أو (ربنا ولك الحمد) إذا سها عن هذا؛ ما عليه شيء، يتبع إمامه، ليس عليه سجود السهو، هو تبع الإمام في هذا، ولا حرج عليه، أو نسي التشهد الأول، ما أتى به، شغل بالوساوس ،ولا أتى به؛ فليس عليه شيء، يتحمله الإمام. أما الفاتحة فالصواب أنها تلزم المأموم على الصحيح، لكن لو سها عنها المأموم، أو جاء والإمام راكع؛ سقطت عنه، أو كان يعتقد أنها لا تجب على المأموم كما يقول الأكثر، ولم يقرأها لأنها عنده لا تجب على المأموم، أو يقلد من قال ذلك؛ فلا شيء عليه. لكن الصواب أنه يقرؤها مع إمامه في السرية والجهرية، هذا هو الصواب، في السرية: هذا أمر ظاهر، ويقرأ معها ما تيسر في الأولى والثانية: مثل الظهر والعصر والمغرب والعشاء، وفي الجهرية: يقرؤها فقط، ولا يزيد، الأولى والثانية من المغرب والعشاء، وفي الفجر، وفي الجمعة، يقرؤها فقط، ولا يزيد شيئًا، ولو كان الإمام يقرأ إذا كمل السكتة، يقرؤها ثم ينصت، لقول النبي ﷺ: لعلكم تقرؤون خلف إمامكم يقول ﷺ: لعلكم تقرءون خلف إمامكم؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب؛ فإنه لا صلاة لمن لم يقرأ بها وهذا يعم الجهرية، والسرية، والفرض، والنفل، كالتراويح. لكن إذا نسيها مثل: (رب اغفر لي) إذا نسيها، مثل (سبحان ربي الأعلى) إذا نسيها؛ سقطت عنه؛ لأنها واجبة في حقه، ليست ركنًا في حق المأموم، بل واجبة؛ بدليل أنه ﷺ لم يأمر أبا بكرة لما جاء والإمام راكع لم يأمره بقضاء الركعة، أجزأته الركعة التي فاته فيها القيام؛ فدل ذلك على أن القراءة في حق المأموم واجبة، تسقط بالجهل، والنسيان، وتسقط إذا فاته القيام، وأتى والإمام راكع؛ أجزأته الركعة، كما في حديث أبي بكرة أنه جاء والنبي راكع -عليه الصلاة والسلام- فركع وهو دون الصف، ثم دخل في الصف، فلما سلم النبي ﷺ قال له ﷺ: زادك الله حرصًا ولا تعد يقول له النبي ﷺ: زادك الله حرصًا ولا تعد يعني: لا تركع دون الصف، اصبر حتى تصل الصف، ولم يأمره أن يقضي الركعة؛ فدل على سقوط الفاتحة عنه؛ لأنه لم يدرك ... وعلى ذلك تسقط عن الناسي من المأموين، والجاهل؛ لأنه في حكم من لم يأت إلا والإمام راكع في المعنى، هذا هو الصواب. وذهب الأكثر من العلماء إلى أنها لا تجب على المأموم، وأنها سنة في حق المأموم في السكتات، وفي السرية. ولكن الصواب قول من قال: إنها واجبة على المأموم؛ لعموم الأحاديث، لكنها تسقط عنه إذا كان جاهلًا، أو ناسيًا، أو جاء والإمام راكع؛ لأنه فاته محل قراءتها وهو القيام. وهذه مسألة عظيمة، نوصي من سمع هذا الحديث أن يعتني بهذا الأمر، وأن يرشد من حوله لهذا الأمر؛ حتى يكون الجميع على بصيرة، وعلى بينة في هذا الأمر الذي تعم به البلوى كثيرًا، بالنسبة إلى من يأتي والإمام في الصلاة، وبالنسبة لمن قد يسهو في الصلاة وهو مع الإمام فلا يقرأ الفاتحة، هذا بحمد الله فيه فرج، وتيسير من الله  نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15358/ما-يفعل-من-نسي-فسلم-من-ركعتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_759/nour_75902.mp3","categories":["سجود السهو"]},{"id":16636,"question":"يقول إمامنا في المسجد يقرأ سورة بعد الفاتحة، ولكن إذا نسي آية؛ يكبر راكعًا، حيث لا يعطي المأمومين فرصة لتذكيره، وكذلك يقف أحيانًا في وسط الآية، ويكبر، وفي إحدى المرات قرأ آية طويلة، ولم يكملها، فهل عمله هذا صحيح؟","title":"حكم استعجال الإمام بالركوع إذا أخطأ في القراءة","answer":"الجواب:  لا حرج في ذلك، والحمد لله، لا حرج فيه، وإن وقف حتى يذكر؛ فلا بأس، لا حرج في ذلك، ولاسيما إذا كان الارتاج عليه في أول القراءة، فإن السنة أن يأتي بقراءة مناسبة بعد الفاتحة، كل صلاة على حسب ما يناسبها في الشرع، الظهر والعصر والمغرب والعشاء والفجر إذا لم يركع، واستفاد من المأمومين أن يذكروه، فهذا حسن، أما إذا كان قد قرأ قراءة كافية فالحمد لله. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15368/حكم-استعجال-الامام-بالركوع-اذا-اخطا-في-القراءة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_716/nour_71613.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16717,"question":"يسأل أخونا عن إمامة الصبي الذي عمره ثلاث عشرة سنة، وهل يجوز أن يخطب يوم الجمعة؟ جزاكم الله خيرًا.","title":"حكم إمامة من عمره ثلاث عشرة سنة","answer":"الجواب: لا حرج في إمامة الصبي إذا كان جيدًا، جيد القراءة، يقول النبي ﷺ: يؤم القوم أقرؤهم لكتاب الله وهذا يعم الصبي، ويعم غيره، وقد ثبت في الصحيح من حديث عمرو بن سلمة أنه قال: \"جاء أبي من عند النبي ﷺ فقال: إنه سمع النبي يقول: إذا حضرت الصلاة؛ فليؤمكم أكثركم قرآنًا قال: فقدموني وأنا ابن سبع سنين؛ لأني كنت أكثرهم قرآنًا\".  هذا من الأدلة على أن الصبي إذا كان يقرأ القرآن، ويجيد القرآن؛ فإنه يقدم لعموم قوله ﷺ: يؤم القوم أقرؤهم لكتاب الله إذا كان يعقل الصلاة، نعم، ابن سبع فما فوق. المقدم: ابن سبع فما فوق. الشيخ: نعم. المقدم: إذا كان يرتبك بعض الشيء سماحة الشيخ؟ الشيخ: ينبه إذا غلط مثل غيره، ما دام يعقل الصلاة ويفهمها، الحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15462/حكم-امامة-من-عمره-ثلاث-عشرة-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_761/nour_76106.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16746,"question":"بعد هذا رسالة من مكة المكرمة، مستشفى الملك عبدالعزيز بالزاهر، وباعثها المستمع أخوكم في الله بدر موسى عبدالكريم، الأخ بدر يسأل جمعًا من الأسئلة من بينها سؤال يقول: مصلٍ دخل مع الإمام في صلاة العشاء، في الركعة الرابعة، كيف يتم هذا المصلي صلاته؟ هل يقرأ سورة مع الفاتحة؟ وهل يقرؤها سرًا؟ أم جهرًا؟ جزاكم الله خيرًا.","title":"ما أول صلاة المسبوق؟","answer":"الجواب: المسبوق ما أدرك مع الإمام، هو أول صلاته في أصح قولي العلماء، المسبوق ما أدركه مع الإمام، هو أول صلاته، وما يقضيه هو آخرها، فإذا أدرك ركعة واحدة من الظهر، أو العصر، أو المغرب، أو العشاء، أو الفجر يقرأ الفاتحة، وما تيسر معها، ثم إذا قام يقضي، يقرأ الفاتحة، وما تيسر معها؛ لأن الثانية في أول صلاته، ثم في الثالثة، والرابعة يقتصر على الفاتحة، تكفيه الفاتحة. وإذا أدرك مع الإمام ثنتين، قرأ فيهما ما تيسر إن أمكنه، ويركع، إذا ركع؛ تكفيه الفاتحة، وإذا قام يقضي؛ يقضي بالفاتحة فقط في الثنتين، لأن السنة في الثالثة، والرابعة الاقتصار على الفاتحة، كما في حديث أبي قتادة الأنصاري  عن النبي ﷺ أنه كان يقرأ في الثالثة والرابعة بفاتحة الكتاب -عليه الصلاة والسلام- وإن قرأ في الثالثة والرابعة في الظهر بعض الأحيان بزيادة على الفاتحة؛ فحسن؛ لأنه جاء ما يدل على هذا من حديث أبي سعيد الخدري  عند مسلم، لكن الأغلب يكون بالفاتحة فقط، في الثالثة، والرابعة في الظهر وغيرها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15490/ما-اول-صلاة-المسبوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_718/nour_71811.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16753,"question":"يقول: دخلنا المسجد مسبوقين، وبعد سلام الإمام قمنا لتكملة صلاتنا ائتم بنا الشخص الذي دخل معي، هل فعله هذا صحيح؟","title":"حكم ائتمام المسبوق بمثله","answer":"الجواب: لا حرج، صحيح -إن شاء الله- لكن لو أن كل واحد قضى بنفسه يكون أحسن، لا حاجة إلى إمامة، لو أن كل واحد قضى لنفسه؛ كفى؛ لأن الرسول ﷺ لما صلى الصحابة بإمامة عبدالرحمن بن عوف في غزوة تبوك، لما تأخر النبي ﷺ في بعض الأيام عن صلاة الفجر؛ قدم الصحابة عبدالرحمن بن عوف  فصلى بهم صلاة الفجر، فجاء النبي ﷺ وعبدالرحمن في الثانية، فأراد أن يتأخر، فأشار إليه النبي ﷺ أن يبقى، فكمل عبدالرحمن بهم، وصلى النبي ﷺ معهم الركعة الثانية هو والمغيرة بن شعبة  فلما سلم عبدالرحمن؛ قام النبي، وقضى والمغيرة، قضى كل واحد قضى لنفسه ما ائتم المغيرة بالنبي ﷺ بل كل واحد قضى لنفسه، فهذا هو الأفضل؛ تأسيًا به -عليه الصلاة والسلام- لكن لو أن أحد المسبوقين ائتم بصاحبه، أو جماعة ائتموا بواحد منهم؛ لا حرج، إن شاء الله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15497/حكم-اىتمام-المسبوق-بمثله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_718/nour_71813.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16754,"question":"يقول: كنت أصلي السنة، فدخل أحد الأشخاص، ورآني أصلي، فظن أني أصلي الفرض، فائتم بي، هل ما فعله ذلك الشخص صحيحًا؟","title":"حكم صلاة الفرض خلف المتنفل","answer":"الجواب: لا حرج في ذلك، لا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15500/حكم-صلاة-الفرض-خلف-المتنفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_718/nour_71814.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16772,"question":"رسالة وصلت إلى البرنامج من المستمع (ع. ع. أ) وهو مقيم بمدينة الرياض يقول: إذا كنت أبعد عن المسجد مسافة ربع ساعة، إلا أني أسمع النداء بواسطة مكبرات الصوت، فهل علي إثم إن صليت في البيت جماعة مع إخوتي؟","title":"حكم الصلاة في البيت لبعد المسجد","answer":"الجواب: ينبغي لك أن تسارع إلى الصلاة في المسجد، وأن تستعين بالله بالأقدام، أو بالسيارة، وأبشر بالخير العظيم؛ لأن الربع الساعة ليست بالكثير بالنسبة إلى أصحاب السيارات، وأصحاب القوة، أما إذا كنت يشق عليك ذلك؛ لكبر السن، ونحو ذلك؛ فلا بأس. والاعتبار ليس بصوت المكبر، ولكن بصوت المؤذن العادي، فإذا كان صوت المؤذن العادي يسمع في مكانكم عند هدوء الأصوات، وعدم وجود المشوشات، وجب عليكم السعي؛ لقول النبي ﷺ: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر قيل لابن عباس: ما هو العذر؟ قال: خوف، أو مرض. وجاءه ﷺ رجل أعمى يقول: يا رسول الله، هل لي من رخصة أن أصلي في بيتي؛ لأنه ليس لي قائد يقودني إلى المسجد، فقال له ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال:  فأجب فالواجب عليكم أن تجيبوا، وأن تحضروا في المساجد إذا استطعتم ذلك، أما إذا لم تستطيعوا ذلك؛ لبعد المكان -كما ذكرتم- أو لمرض، أو لخوف، فأنتم معذورون في الصلاة في البيت، نسأل الله للجميع التوفيق، والإعانة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، إذا لم يكن صاحب سيارة، هل تنصحونه بالاستئجار، أو أنه لا يلزمه؟ الشيخ: ما دام لا يسمع صوت المؤذن لو كان بدون مكبر؛ ما يلزمه، إذا كان الصوت العادي للمؤذن العادي المعروف، لو أذن ما سمعوه في محلهم لبعدهم؛ فلا حرج عليهم من الصلاة في البيت، لكن إذا تجشموا المشقة، وصبروا، وتحملوا؛ هذا خير لهم وأفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15524/حكم-الصلاة-في-البيت-لبعد-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_822/nour_82205.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16832,"question":"ما حكم صلاة المنفرد خلف الصف؟","title":"حكم صلاة المنفرد خلف الصف","answer":"الجواب: حكمها عدم الصحة، البطلان، لقول النبي ﷺ: لا صلاة لمنفرد خلف الصف ولأن رسول الله ﷺ رأى رجلًا يصلي خلف الصف وحده؛ فأمره أن يعيد الصلاة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15610/حكم-صلاة-المنفرد-خلف-الصف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82408.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16833,"question":"المستمع هويدي هديان الوريكاني السلمي من منطقة الكامل بعث برسالة مطولة بعض الشيء، ملخصها: أنه يؤم أناسًا دون أن يستأذن منهم، فهل عمله هذا صحيح؟","title":"حكم من أم قومًا دون أن يستأذنهم","answer":"الجواب: إذا قدموه وصلى بهم، فليس من اللازم أن يستأذن الجميع، إذا قدمه أعيانهم، أو قدمه ولاة الأمر في هذا المسجد؛ فلا حرج، لكن إذا كانوا يكرهونه من أجل خصومة بينه وبينهم، وشحناء؛ أو من أجل بدعته، أو من أجل أنه عنده معاصٍ ظاهرة، فلا ينبغي له أن يؤمهم، وقد جاء في بعض الأحاديث الصحيحة، أن النبي ﷺ قال: ثلاثة لا يقبل الله لهم صلاة، ولا تصعد لهم حسنة ذكر منهم: من أم قومًا وهم له كارهون.  قال العلماء: يعني: إذا كرهوه بحق، يكرهونه بحق فإنه لا يؤمهم، إذا كرهوه لبدعته، أو لشحناء بينه وبينهم؛ لا يؤمهم، أما إذا كان لا، هو مستقيم، ومن أهل السنة، وليس به بأس، ولكن كرهوه؛ لأنه يدعوهم إلى الله؛ لأنه يعلمهم، لأنه يأمرهم بالمعروف، وينهاهم عن المنكر، لا، هذا لا عبرة بكراهتهم، يؤمهم، ولا عبرة بكراهتهم، لكن إن كرهوه بحق؛ لأنه صاحب خصومة بينه وبينهم، شحناء، أو لأنه صاحب بدعة، أو يرونه بالمعاصي الظاهرة كالإسبال، وحلق اللحية، فلا يؤمهم؛ لأنه عليه مؤاخذة في هذا، هذا الذي يحلق لحيته، أو يقصها، أو يسبل ثيابه، لهم الاعتراض عليه إما أن يستقيم، وإما أن يعتزلهم. وهكذا لو كان معروفًا ببدعة، ممن يدعو إلى الموالد، والاحتفال بالموالد، أو يدعو إلى الاحتفال بليلة سبع وعشرين، ليلة الإسراء والمعراج، أو ممن يتهم بأشياء أخرى يعرف منه أماراتها، ودلائلها مما هو بدعة، أو معصية ظاهرة. فالحاصل: أنه إذا كان عليه أمر واضح يكرهونه بحق، لبدعته، أو دعوته إلى الباطل، أو إظهاره للمنكر، أو ما أشبه ذلك مما هو عذر لهم في كراهتهم له، فإنه لا يؤمهم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15588/حكم-من-ام-قوما-دون-ان-يستاذنهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82401.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16849,"question":"هل يجوز أن يصلي المفترض وراء المتنفل؟","title":"جواز صلاة الفريضة خلف المتنفل","answer":"الجواب: نعم لا حرج في ذلك، لو أن إنسانًا لم يصل فريضته، وجاء إلى إنسان يصلي نافلة، وصلى معه؛ صحت، كان معاذ  يصلي بأصحابه العشاء نفلًا؛ لأنه قد صلاها مع النبي ﷺ وهم مفترضون؛ ولأنه ﷺ في بعض أنواع صلاة الخوف صلى بطائفة ركعتين فرضهم، ثم صلى بطائفة أخرى ركعتين نفلًا له، ولهم فرض، فلا حرج، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15611/جواز-صلاة-الفريضة-خلف-المتنفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82409.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16866,"question":"رسالة وصلت إلى البرنامج من السودان، وباعثها مستمع من هناك، يقول كامل هارون ريفي، يسأل جمعًا من الأسئلة في أحدها يقول: أرجو تفصيل هذه المسائل الهامة في نظري، جزاكم الله خيرًا: كيف يفعل المسبوق بركعة، أو ركعتين في العشاء أو المغرب، هل يقرأ سرًا؟ أم كيف يعمل؟ جزاكم الله خيرًا.","title":"كيفية صلاة المسبوق","answer":"الجواب: إذا سبق بركعة إذا سلم الإمام يقوم يأتي بالركعة التي سبق فيها، ويقرأ فيها الفاتحة فقط، هذا هو الأفضل؛ لأن ما يقضيه هو آخر صلاته، وما أدركه مع الإمام هو أول صلاته، هذا هو الصحيح، ما أدركه المسبوق هو أول صلاته، وما يقضيه هو آخر صلاته. فإذا كان فاته ركعة من العشاء، أو المغرب، أو الفجر؛ فإنه إذا سلم الإمام يقوم، ويأتي بالركعة التي بقيت عليه، والسنة أن يجهر بالقراءة في المغرب، والعشاء يقرأ الفاتحة فقط، وإن قرأ زيادة؛ فلا حرج سرًا، أما في الفجر فيجهر.. فهي جهرية، يقرأ جهرًا في الركعة التي يقضيها الفاتحة، وزيادة معها كما يقرؤها لو كان مع... كما كان الإمام يقرؤها، لكنه في حال قضائه ليس مع الإمام، فيقضيها، ويقرأ مع الفاتحة ما تيسر جهرًا، جهرًا لا يؤذي من حوله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15633/كيفية-صلاة-المسبوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_764/nour_76415.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16941,"question":"من الأحساء السائل (خ. ع. د) يقول: سماحة الشيخ أسأل عن حكم الصلاة خلف إمام عليه أخطاء كثيرة في قراءته لسورة الفاتحة، وسور أخرى من القرآن الكريم، مع أن هناك أناس يحفظون أكثر منه، وجهونا في ضوء ذلك؟","title":"حكم الصلاة خلف إمام غير متقن","answer":"الجواب: الأفضل أن يتقدم بالناس أقرؤهم، يقول النبي ﷺ: يؤم القوم أقرؤهم لكتاب الله يعني: أجودهم قراءة، هذا هو السنة، هذا هو المشروع، لكن إذا كان لحنه خفيفًا؛ صحت صلاته، إذا كان لحنه لا يغير المعنى؛ صحت صلاته بهم، مثلًا: إذا قرأ الحمدَ لله رب العالمين، أو الحمدِ لله رب العالمين، أو الرحمنُ الرحيم، أو مالكُ يوم الدين، ما يضر هذا، ما يغير المعنى.  أما إذا كان يغير المعنى مثل: إياكِ نعبد، أو صراط الذين أنعمتِ، أو أنعمتُ عليهم هذا ما يجوز، لا يؤم الناس. أما إذا كان لحنه خفيفًا ما يغير المعنى مثل: الحمدِ لله أو الحمدَ لله رب العالمين، أو الرحمنَ الرحيم، أو الرحمنُ الرحيم، هذا لا يضر، لكن الأفضل أن يختاروا من هو أجود، أهل المسجد يقدمون من هو أجود للقراءة، لقوله ﷺ: يؤم القوم أقرؤهم لكتاب الله وهكذا المسؤول عن الإمامة يقدم في الإمامة من هو أقرأ، نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15718/حكم-الصلاة-خلف-امام-غير-متقن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58614.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16969,"question":"بعض الناس يأكل الثوم في رمضان، وقد تجد له رائحة قوية تنبعث منه، فهل يؤثر ذلك على الصيام؟ وجهونا مأجورين.","title":"حكم الصلاة في المسجد لمن أكل ثومًا أو بصلًا","answer":"الجواب: لا يجوز لمن يصلي مع الناس أن يأكل الثوم والبصل، أو الكراث، يجب أن يمتنع من ذلك، وإذا فعل وجب إخراجه من المسجد حتى لا يؤذي الناس، كان النبي ﷺ يأمر بإخراجهم إذا أكلوا الثوم والبصل؛ لئلا يؤذوا الناس، فالذي يأكل ثومًا لحاجة، أو بصلًا لحاجة يصلي في بيته، لا يصلي مع الناس، وعلى الهيئة، أو المسؤولين إخراجه من المسجد حتى لا يؤذي الناس.  المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15739/حكم-الصلاة-في-المسجد-لمن-اكل-ثوما-او-بصلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58619.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":16986,"question":"يقول: منزلي يبعد عن المسجد، ولكني أسمع الأذان من مكبر الصوت، إنما نحن مع ذلك نصلي في البيت، هل نكون آثمين حينئذ، وهل صلاتنا صحيحة؟ جزاكم الله خيرًا.","title":"ما حكم الصلاة في البيت لمن كان المسجد بعيدًا عنه؟","answer":"الجواب: إذا كان المسجد بعيدًا عنكم لا تسمعون الأذان بالصوت المعتاد عند هدوء الأصوات؛ فإنه لا تلزمكم الجماعة في المسجد، لكن لو ذهبتم إليه، ولو بالركوب، أو تحمل بعض المشقة يكون أفضل؛ لما فيه من الفضل العظيم، ومضاعفة الأجر، والاجتماع بالمصلين، والتعارف، والتعاون على الخير. أما صوت المكبر فلا يكفي، فلا يلزم به الحضور؛ لأنه يسمع من بعيد. لكن من أجاب على صوت المكبر، وذهب للجماعة، وصبر على المشقة؛ فله أجر عظيم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15771/ما-حكم-الصلاة-في-البيت-لمن-كان-المسجد-بعيدا-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_829/nour_82902.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17002,"question":"أولى أسئلة هذه الحلقة سؤال وصل إلى البرنامج من المواطن (ع. ف. غ) يقول: حدثونا عن حكم الصلاة التالية: إمامنا صلى بنا الظهر ثلاثًا، ثم سجد للسهو، ثم سلم، ثم قام فأتى بالرابعة، وسجد للسهو، ثم سلم؟ جزاكم الله خيرًا.","title":"حكم من سجد للسهو ثم أتم وسجد للسهو مجددًا","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإذا كان الإمام المذكور قد ظن أنه قد كمل الصلاة، وسلم من ثلاث، وسجد للسهو؛ بناءً على أنه بنى على اليقين، أو على غالب ظنه، ثم تنبه أنه مخطئ، وأنه قد بقي عليه ركعة؛ فالواجب هو ما صنع؛ يقوم، ويأتي بالرابعة، ثم بعد قراءة التحيات، وإكمالها يسلم، ثم يسجد للسهو، هذا هو الأفضل، يكون سجوده بعد السلام، وإن سجد قبل السلام؛ فلا حرج في ذلك، وبكل حال فعمله -بحمد الله- صحيح، إذا كان كما ذكرنا سلم من ثلاث يعتقد أنه مصيب، ثم تبين له خطؤه، فقام، وكمل، وسجد للسهو، والحمد لله، وهذا هو الواجب عليه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15801/حكم-من-سجد-للسهو-ثم-اتم-وسجد-للسهو-مجددا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_767/nour_76705.mp3","categories":["سجود السهو"]},{"id":17030,"question":"يقول: هل وجب علي إذا سمعت أذان صلاة الفجر عندما أستيقظ من النوم لم ألحق بالصلاة إلا نادرًا، فهل يجب علي عندما أعلم أنني لم ألحق بالجماعة أن أصلي في البيت؟ أم ألحق بالمسجد كيفما كان الحال؟","title":"وجوب المبادرة إلى صلاة الجماعة","answer":"الجواب: الواجب عليك السعي إلى المسجد، والبدار بذلك؛ لقول النبي ﷺ: من سمع النداء، ولم يأت؛ فلا صلاة له إلا من عذر قيل لابن عباس: ما هو العذر؟ قال: مرض، أو خوف. وجاءه ﷺ رجل أعمى، فقال: يا رسول الله! ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال -عليه الصلاة والسلام-: هل تسمع النداء بالصلاة؟ قال: نعم، قال:  فأجب. فأنت عليك أن تجيب، وتبادر، وإذا كانوا يبكرون بادر تأهب للصلاة قبل الأذان، تأهب لها حتى تدرك إخوانك، ما دمت تسمع النداء، والمسجد قريب عليك أن تبادر، وأن تصلي مع إخوانك، وأن تحذر الكسل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15806/وجوب-المبادرة-الى-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_830/nour_83001.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17042,"question":"هل يشرع في سجود السهو قراءة التشهد؟","title":"حكم قراءة التشهد في السهو","answer":"الجواب: ليس فيه تشهد، سجدتان فقط بدون تشهد، إذا سها يسجد سجدتين ليس فيهما تشهد، إن سجدهما قبل السلام فلا بأس، أو بعد السلام فلا بأس، لكن الأفضل أن يكون سجودهما قبل السلام، إلا في حالتين: إحداهما: إذا سلم عن نقص ثم تنبه، أو نبه يكمل، ويكون سجوده بعد السلام أفضل. والحال الثاني: إذا بنى على غالب ظنه؛ لأن الرسول ﷺ أمر من سها أن يتحرى الصواب، فيتم عليه، ثم ليسلم، ثم ليسجد السجدتين، فإذا بنى على غالب ظنه، وأتم يسلم، ثم يسجد سجدتي السهو، وليس فيهما تشهد، والبقية كلها قبل السلام، سجدتان قبل أن يسلم في غير ذلك من السهو. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15830/حكم-قراءة-التشهد-في-السهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58719.mp3","categories":["سجود السهو"]},{"id":17065,"question":"يقول يا سماحة الشيخ: بأنه يبعد عن المسجد حوالي ثلث ساعة، ولا يسمع الأذان إلا في أوقات الهدوء، وذلك عبر مكبرات الصوت، يقول: هل صلاتي في البيت غير مقبولة، علمًا بأنه لا يوجد ما يخيفني؟","title":"المسافة التي يعذر فيها بترك الجماعة","answer":"الجواب: إذا بعد الإنسان عن المسجد حيث لا يسمع النداء المعتاد، بحيث لا يسمع النداء المعتاد فإنه لا يلزمه، النبي  قال: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر وقال للأعمى: هل تسمع النداء بالصلاة قال: نعم. قال: فأجب فإذا كان في محلٍ بعيد لا يسمع النداء المعتاد إلا بمكبرات الصوت؛ فإنه لا يلزمه، لكن إذا احتسب الأجر، وصبر، وذهب للمسجد؛ فهذا خير له، فيه فضل عظيم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15867/المسافة-التي-يعذر-فيها-بترك-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58805.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17074,"question":"تقول هذه السائلة سماحة الشيخ: متى يكون السجود للسهو قبل السلام؟ ومتى يكون بعده؟ أفتونا مأجورين.","title":"حالات سجود السهو بعد السلام","answer":"الجواب: السجود للسهو قبل السلام، السجود للسهو يكون قبل السلام إلا في حالتين:  إحداهما: إذا سلم المصلي عن نقص ركعة، أو أكثر ناسيًا فإنه يكمل، ثم يسجد للسهو بعد السلام، هذه الحالة الأولى؛ إذا سلم عن نقص ركعة، أو أكثر، ثم تنبه، أو نبه فإنه يكمل صلاته، ثم يقرأ التحيات، ويكمل التشهد، ثم يسلم، ثم يسجد للسهو سجدتين بعد السلام، هذا هو الأفضل، كما فعله النبي ﷺ لما سلم عن نقص. الحال الثاني: إذا أشكل عليه، وبنى على غالب ظنه في الصلاة، يعني: أشكل هل صلى ثلاثًا، أو أربعًا، وغلب على ظنه أنه صلى أربعًا، فإنه يسلم بعد الفراغ، ثم يسجد للسهو، أو غلب على ظنه أنه صلى ثلاثًا، يبني على ثلاث، ثم يكمل الصلاة، ثم يسجد للسهو بعد السلام إذا بنى على غالب ظنه، أما إذا بنى عن اليقين، عمل باليقين فإن السجود يكون قبل السلام. فالحاصل أنه في حالتين يسجد بعد السلام: إحداهما إذا سلم عن نقص، ركعة، أو أكثر؛ فإن السجود يكون بعد السلام أفضل، كما فعله النبي ﷺ. الحال الثاني: إذا بنى على غالب ظنه، ما هو بعلى اليقين، بنى على غالب ظنه؛ فإنه يؤجل سجود السهو حتى يسلم، ثم يسجد للسهو بعد ذلك. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15879/حالات-سجود-السهو-بعد-السلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58814.mp3","categories":["سجود السهو"]},{"id":17106,"question":"من أسئلته يقول يا سماحة الشيخ: إذا كان الإمام في الصلاة في حالة الركوع، أو السجود، وخرج منه شيء أبطل صلاته، فماذا عليه؟ هل يتم الصلاة، أو يقدم أحدًا من الذين خلفه؟","title":"ماذا يفعل الإمام إذا أحدث في الصلاة؟","answer":"الجواب: إذا أحدث الإمام في الصلاة في ركوعه، أو سجوده، أو في غيرهما لا يستمر، ينفتل، ويقدم من يصلي بالناس، لما طعن عمر  قدم عبدالرحمن بن عوف، فصلى بالناس، فإذا خرج منه ريح، أو بول فإنه ينفتل من الصلاة، ينصرف، ويستخلف من يصلي بالناس ممن وراءه، يقدمه حتى يكمل بالناس. نعم. المقدم: حزاكم الله خيرًا، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/15901/ماذا-يفعل-الامام-اذا-احدث-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58905.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17107,"question":"هذا سائل للبرنامج، يقول السائل من كينيا سعد أحمد يقول أخوكم في الله، يقول يا سماحة الشيخ: هل تصح الصلاة خلف إمامٍ مبتدع، ويشتغل بأعمال الشعوذة، والسحر، وما حكم الصلاة خلف هذا إذا كنا صلينا خلف هذا الإمام عدة صلوات؟","title":"هل تصح الصلاة خلف الإمام المبتدع؟","answer":"الجواب: إن كانت بدعته تخرجه من الدين لم تصح الصلاة، أما إن كان بدعته ما تخرجه من الدين، بدعة منكرة، لكن لا يكون بها كافرًا مثل: بدعة المولد، ومثل: بدعة النطق بالنية في الصلاة، فهذا لا حرج في الصلاة خلفه، لكن ينبغي استخلاف غيره، ينبغي العمل في إيجاد غيره من أهل السنة، ولكن الصلاة خلفه صحيحة إذا كان لم يحكم بكفره. أما إذا كانت بدعة تكفره كبدعة، دعاء غير الله، والاستغاثة بغير الله، والنذر لغير الله، والذبح لغير الله، هذا لا يصلى خلفه؛ لأنه مشرك، لا يصلى خلفه، ولكن العاصي الذي بدعته معصية ما تجعله كافرًا، هذا إذا صلى خلفه؛ صحت، لكن ينبغي إبداله بغيره، التماس غيره من أهل السنة.","link":"https://binbaz.org.sa/fatwas/15902/هل-تصح-الصلاة-خلف-الامام-المبتدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58906.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17117,"question":"هذا سائل يقول: سماحة الشيخ! هل صلاة الصبح تحل مكان صلاة الفجر لظروف عملي، وعدم المقدرة على الاستيقاظ لصلاة الفجر؟ وما هو آخر وقت لصلاة الصبح مأجورين؟","title":"وجوب الصلاة مع جماعة المسلمين","answer":"الجواب: الواجب عليك أن تصلي مع المسلمين، إذا أذن تذهب إلى المسجد، وتصلي مع المسلمين، وآخر وقت لصلاة الفجر طلوع الشمس، إذا طلعت ذهب الوقت، ولا يجوز التأخير إلى طلوع الشمس، ولا يجوز ترك الجماعة مع المسلمين، يجب أن تصلي مع المسلمين في المساجد، الله -جل وعلا- يقول: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43].  ويقول النبي ﷺ: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر قيل لابن عباس: «ما هو العذر؟ قال: خوف، أو مرض» وجاءه رجل أعمى، قال: «يا رسول الله! ليس لي قائد يقودني للمسجد، فهل لي من رخصة أن أصلي في بيتي؟ قال: هل تسمع النداء بالصلاة؟ قال: نعم. قال: فأجب ولا يجوز أن يؤخر الصلاة إلى بعد طلوع الشمس، هذا كفر وضلال -نسأل الله العافية- تعمد هذا كفرٌ وضلال، يقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/15926/وجوب-الصلاة-مع-جماعة-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58914.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17118,"question":"ما الأسباب المعينة يا سماحة الشيخ على أداء صلاة الفجر؟","title":"الأسباب المعينة على أداء صلاة الفجر جماعة","answer":"الجواب: الأسباب المعينة: التبكير، كونه يسري مبكرًا لا يسهر، كونه يحط الساعة، يركب الساعة قبل الأذان.. مع الأذان حتى يقوم، أو يعمد أهله الطيبين يوقظونه، يعني: يفعل الأسباب، أما إذا كان يسهر، ولا يسري إلا عند الفجر، هذا يبي ينام، هذا كالمتعمد -نسأل الله العافية- فعليه أن يبكر، يسري مبكرًا، لا يسهر، وعليه أن يعتني بالساعة، يوقتها على قرب الأذان، أو يعمد أهله الجيدين يوقظوه، لا يتساهل، يفعل الأسباب. المقدم: حزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15927/الاسباب-المعينة-على-اداء-صلاة-الفجر-جماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58915.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17128,"question":"رسالة وصلت إلى البرنامج من المملكة الأردنية الهاشمية باعثها مستمع يقول أخوكم في الله: فواز الخرشة، الأخ فواز يسأل سماحتكم فيقول: أنا شاب من الأردن، أصلي بمجموعة من الناس إمامًا في أحد المساجد، لكني أعترف أنني لا أجيد قراءة القرآن بشكل جيد، فهل أكون آثمًا؛ علمًا بأنه لا يوجد غيري إمامًا لهؤلاء الناس؟ وجهوني جزاكم الله خيرًا.","title":"حكم إمامة من لا يجيد قراءة القرآن","answer":"الجواب: إذا كنت تقيم القراءة، ولو كنت غير مجود؛ لأن التجويد ليس بواجب، مستحب، إذا كنت تقيم القراءة، تقيم الحروف، تخرجها؛ فلا بأس بذلك، ولو كنت لم تقرأ التجويد، ما دمت تقرأ الآيات باللغة العربية واضحة، والحروف واضحة، فلا بأس عليك، والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15947/حكم-امامة-من-لا-يجيد-قراءة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72207.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17179,"question":"يقول هذا السائل: ما هي كيفية وضع القدمين في الصلاة بالنسبة للمأمومين؟ هل يقوم بإلزاق رجله اليمنى برجل من على يمينه، ورجله اليسرى برجل من على يساره في حالة السجود؟","title":"كيفية وضع القدمين في الصلاة","answer":"الجواب: يسد الخلل، ولا حاجة إلى المحارشة، المعنى سد الخلل، مثلما أمر ﷺ بسد الخلل، ما يكون بينهما فرج، وكان الصحابة يلصق أحدهم قدمه بقدم صاحبه لسد الخلة، فالسنة أن يسد الخلل بإلصاق قدمه بقدم أخيه من دون إيذاء لأخيه. نعم.","link":"https://binbaz.org.sa/fatwas/15997/كيفية-وضع-القدمين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59008.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17185,"question":"هذه سائلة تقول: سماحة الشيخ! قمت بقراءة الفاتحة بدلًا من التشهد الأخير في صلاة الظهر مع الجماعة، ولكنني أدركت بأنني أخطأت، وقرأت التشهد مرةً أخرى، فهل أسجد سجدتين، سجدة للسهو بعد أن ينتهي الإمام من صلاة الجماعة؟ أم ماذا أفعل؟","title":"ما حكم سهو المأموم خلف الإمام؟","answer":"الجواب: يكفي إذا قرأت التشهد، والحمد لله، وليس عليك سجود السهو؛ المأموم تبع لإمامه، ليس عليه سجود سهو، والحمد لله. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16004/ما-حكم-سهو-الماموم-خلف-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59013.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17186,"question":"من الأفلاج السائل: (س. ر) يقول: سماحة الشيخ! متى يكون سجود السهو قبل السلام، ومتى يكون بعده؟ جزاكم الله خيرًا.","title":"حالات سجود السهو بعد السلام وقبله","answer":"الجواب: السجود قبل السلام، هذا هو الأفضل، إلا في حالتين، السنة أن يكون السجود قبل السلام إلا في حالتين: إحداهما: إذا سلم عن نقص ركعة، أو أكثر، ثم نبه، أو تنبه يكمل الصلاة، ثم يسلم، ثم يسجد سجدتين، كما فعل النبي ﷺ في حديث ذي اليدين، وفي حديث عمران. الحال الثاني: إذا بنى على غالب ظنه، إذا شك في صلاته، وبنى على غالب ظنه فإنه يسجد للسهو بعد السلام، أما إن بنى على اليقين فإن السجود يكون قبل السلام، لحديث ابن مسعود لما أمر النبي ﷺ قال: إذا شك أحد في صلاته؛ فليتحر الصواب، فليتم عليه، ثم ليسلم، ثم ليسجد سجدتين بعد السلام. أما إذا بنى على اليقين فإنه يسجد قبل السلام، لقوله ﷺ في حديث أبي سعيد: إذا شك أحدكم في صلاته؛ فليطرح الشك، وليبن على ما استيقن، ثم ليسجد سجدتين قبل أن يسلم فإذا بنى على اليقين، وطرح الشك فإنه يسجد للسهو قبل السلام. أما إذا بنى على غالب ظنه، شك في ثنيتن، أو ثلاث، وغلب على ظنه أنها ثلاث، يجعلها ثلاثًا، ويكمل، ويقرأ التحيات، ثم يسلم، ثم يسجد للسهو؛ لأنه بنى على غالب ظنه. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16005/حالات-سجود-السهو-بعد-السلام-وقبله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59014.mp3","categories":["سجود السهو"]},{"id":17194,"question":"بالنسبة للرواتب هل يشرع سجود السهو في الرواتب يا شيخ؟","title":"حكم سجود السهو في صلاة الراتبة","answer":"الجواب: نعم. إذا سها في الرواتب، أو في صلاة الضحى يسجد للسهو، أو في وتره يسجد للسهو. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16013/حكم-سجود-السهو-في-صلاة-الراتبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59022.mp3","categories":["سجود السهو"]},{"id":17243,"question":"من اليمن أبو الفضل، يقول: سماحة الشيخ، هل من أدرك الإمام راكعًا، فقد أدرك الركعة، وإن لم يقرأ بفاتحة الكتاب؟","title":"حكم من أدرك الإمام راكعًا","answer":"الجواب: نعم إذا أدرك الإمام راكعًا؛ أدرك الركعة، لأن النبي ﷺ لما ذكر له أبو بكرة أنه أدركه راكعًا، أمره ألا يعود، وركع دون الصف، أمره ألا يعود إلى الركوع دون الصف، ولم يأمره بقضاء الركعة، فدل على إجزائه، قال: زادك الله حرصًا، ولا تعد لما ركع دون الصف، خاف أن تفوته الركعة. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16074/حكم-من-ادرك-الامام-راكعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59120.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17284,"question":"يلحظ بعض الإخوة المستمعين على بعض الأئمة سماحة الشيخ، جزاكم الله خيرًا، أنهم يتأخرون عن صلاتي الفجر والعصر، وإذا ما نصح بعضهم قال: إن هذا من الابتلاء، والامتحان، فما هو توجيه سماحتكم لكلٍ من الأئمة، والمأمومين؟ جزاكم الله خيرًا.","title":"توجيه لمن يتأخر من الأئمة عن الصلاة","answer":"الجواب: الواجب على الجميع العناية بالصلاة كلها الخمس كلها، يجب العناية بها، وأن تؤدى في أوقاتها، وفي الجماعة، وعلى الإمام أن يحافظ، وعلى كل مسلم أن يحافظ على الصلاة في وقتها، وعلى الإمام أن يحافظ حتى لا يعطل الناس، لا يعجل، ولا يتأخر، يتحرى صلاة النبي ﷺ ويتحرى ما عين من جهة الأوقاف في الأوقات، وما يقاربها، حتى لا يؤذي المصلين لا بالعجلة، ولا بالتأخر، يتحرى الأوقات التي عينت له، ووضحت له، يتحرى فيها سنة النبي، عليه الصلاة والسلام. وهكذا المأموم يسابق إلى الصلاة كلها، الظهر، والعصر، والمغرب، والعشاء والفجر كلها، لا يتأخر، والفجر والعصر كذلك، يجب أن يعتني بهما كبقية الأوقات، ولا يجوز التساهل في ذلك لا للإمام، ولا للمأموم، و لا للنساء، ولا للرجال، يجب على الجميع العناية بالأوقات، وعلى الرجل أن يصليها في الجماعة جميعها، عليه أن يصليها جميعًا في الجماعة، نسأل الله للجميع الهداية.  المقدم: اللهم آمين، جزاكم الله خيرًا، و أحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16130/توجيه-لمن-يتاخر-من-الاىمة-عن-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72320.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17288,"question":"مستمع رمز إلى اسمه بالحروف (م. ع. ب. ي) يسأل سماحتكم يقول: قرأت قولًا لرسول الله ﷺ: ألا صلوا في رحالكم متى يصلي الإنسان في رحاله، وهل هذا القول منسوب إلى النبي ﷺ؟","title":"الحالات التي يشرع فيها الصلاة في الرحال","answer":"الجواب: نعم، هذا صحيح عن النبي ﷺ في أوقات المطر والدحض، يقول المؤذن: صلوا في رحالكم عند قوله: حي على الصلاة ... يقول: صلوا في رحالكم، صلوا في بيوتكم، أو بعد الأذان: صلوا في بيوتكم، إذا كان في مشقة على الناس من جهة المطر، أو الزلق في الأسواق، هكذا فعله ابن عباس في الطائف، أمر المنادي أن ينادي، وأخبر أن النبي قال ذلك، وفعله -عليه الصلاة والسلام- وهذا من باب رحمة المسلمين، والشفقة عليهم، والرفق بهم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16132/الحالات-التي-يشرع-فيها-الصلاة-في-الرحال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72321.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17300,"question":"هل النوم يعد عذرًا للتخلف عن صلاة الجماعة، أو تأخيرها، بحيث لا يخرج وقتها، خاصةً إذا كان الإنسان مجهدًا في عملٍ معين، وذلك لحديث: من نام عن صلاة، أو نسيها وحديث: رفع القلم عن ثلاثة -وذكر منها- النائم؟ أم يجب إيقاظ النائم في أول وقت الصلاة؟ أم يجوز تأخيره، بحيث لا يخرج الوقت؟ جزاكم الله خيرًا.","title":"حكم التخلف عن صلاة الجماعة بسبب النوم","answer":"الجواب: إذا كان معذورًا يعني: فعل الأسباب، واجتهد، ولكن غلبه النوم، فلا بأس، مثل ما قال ﷺ: من نام عن الصلاة، أو نسيها فليصلها إذا ذكرها وقد وقع للنبي ﷺ مرات في السفر، ناموا عن الصلاة، فلما استيقظوا قضوا، ولكن مع الحيطة، بحيث يجعل ساعة يوكدها على وقت الصلاة، أو بعض أهله يوقظونه، ولا يسهر، بل يبكر بالنوم، يعني عليه أن يتعاطى الأسباب التي تعينه على القيام، فإذا غلب، ولم تنفع الأسباب فهو معذور.  أما أن يتساهل، ويسهر الليل، ثم يقول: أقوم، هذا هو المفرط.. هو الذي تعاطى أسباب عدم القيام، فهو آثم، حتى يفعل الأسباب الشرعية من عدم السهر، ومن جميع الأشياء التي تعينه على ذلك، أو بعض أهله الذين يوقظونه. المقصود: لابد من تعاطي الأسباب، فإذا تعاطى الأسباب الشرعية، واجتهد، ثم غلبه النوم فهو معذور. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16143/حكم-التخلف-عن-صلاة-الجماعة-بسبب-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_724/nour_72401.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17309,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين ضمنها جمعًا من الأسئلة في أحدها يسأل عن حكم الصلاة في البيت، ولا سيما إذا كان المسجد بعيدًا، وليس له وسيلة مواصلات؟ جزاكم الله خيرًا.","title":"حكم الصلاة في البيت لمن المسجد بعيدًا عنه","answer":"الجواب: الصلاة في البيت صلاة الفريضة لا تجوز، إذا كان يقدر على الصلاة في المسجد، يجب عليه أن يصلي مع الناس؛ لقول النبي ﷺ: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر،  قيل لابن عباس: ما هو العذر؟ قال: خوف، أو مرض. ولقوله ﷺ للأعمى لما سأله، هل يصلي في بيته، قال ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب ولأنه ﷺ توعد بالنار من تخلف عن الصلاة في الجماعة.  فالواجب على المكلف أن يحضر صلاة الجماعة مع المسلمين في المساجد إلا إذا كان بعيدًا عن المسجد لا يسمع النداء فلا حرج عليه، إذا كان بعيدًا عنك المسجد لا تسمع النداء فلا حرج أن تصلي في البيت، وإن صليت في المسجد، ولو مع المشقة كان أفضل، وأكثر ثوابًا، ولكن لا يلزمك إذا كان بعيدًا، لا تسمع النداء .. النداء بالصوت المعتاد لا بالمكبر، أما المكبر فقد يسمع من بعيد، وليس كل أحد يستطيع المشي إلى ما يسمع.  فالحاصل: أنه لا يلزمك السعي إلى المسجد إذا كان بعيدًا، لا تسمع النداء بالصوت المعتاد عند خلو الأصوات، ولكن إن سعيت، وصبرت على المشقة كان أفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16184/حكم-الصلاة-في-البيت-لمن-المسجد-بعيدا-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_833/nour_83315.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17319,"question":"نرجو أن توضحوا لنا كيفية النهوض من سجود السهو، هل يعتمد على ركبتيه؟ أم على يديه؟","title":"كيفية النهوض من سجود السهو","answer":"الجواب: مثل نهوضه من سجود الصلاة سواء بسواء، فالأفضل على ركبتيه إذا كان قادرًا، وإن كان عاجزًا، أو مريضًا نهض على يديه لا بأس، وأما إذا كان صحيحًا فالأفضل على ركبتيه، كسجود الصلاة سواء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16183/كيفية-النهوض-من-سجود-السهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_833/nour_83314.mp3","categories":["سجود السهو"]},{"id":17322,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين ضمنها جمعًا من الأسئلة في أحدها يسأل عن حكم الصلاة في البيت، ولا سيما إذا كان المسجد بعيدًا، وليس له وسيلة مواصلات؟ جزاكم الله خيرًا.","title":"حكم الصلاة في البيت لمن المسجد بعيدًا عنه","answer":"الجواب: الصلاة في البيت صلاة الفريضة لا تجوز، إذا كان يقدر على الصلاة في المسجد، يجب عليه أن يصلي مع الناس؛ لقول النبي ﷺ: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر،  قيل لابن عباس: ما هو العذر؟ قال: خوف، أو مرض. ولقوله ﷺ للأعمى لما سأله، هل يصلي في بيته، قال ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب ولأنه ﷺ توعد بالنار من تخلف عن الصلاة في الجماعة.  فالواجب على المكلف أن يحضر صلاة الجماعة مع المسلمين في المساجد إلا إذا كان بعيدًا عن المسجد لا يسمع النداء فلا حرج عليه، إذا كان بعيدًا عنك المسجد لا تسمع النداء فلا حرج أن تصلي في البيت، وإن صليت في المسجد، ولو مع المشقة كان أفضل، وأكثر ثوابًا، ولكن لا يلزمك إذا كان بعيدًا، لا تسمع النداء .. النداء بالصوت المعتاد لا بالمكبر، أما المكبر فقد يسمع من بعيد، وليس كل أحد يستطيع المشي إلى ما يسمع.  فالحاصل: أنه لا يلزمك السعي إلى المسجد إذا كان بعيدًا، لا تسمع النداء بالصوت المعتاد عند خلو الأصوات، ولكن إن سعيت، وصبرت على المشقة كان أفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16184/حكم-الصلاة-في-البيت-لمن-المسجد-بعيدا-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_833/nour_83315.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17391,"question":"يقول: حصل خلاف بيني وبين صديق لي في العمل، صلى ذات مرة خلفي، ويقول: إنك أطلت الصلاة، علمًا بأن صحته جيدة، ولا يشكو من أي شيء، فما هو توجيهكم لي، ولأمثالي؟ جزاكم الله خيرًا.","title":"المشروع للإمام مراعاة المأمومين","answer":"الجواب: عليك أن تراعي المأمومين.. السنة للمؤمن إذا كان إمامًا أن يراعي المأمومين، فلا يشق عليهم، يصلي صلاة متوسطة، ليس فيها طول يشق على الناس، لقول النبي ﷺ: أيكم أم الناس فليخفف؛ فإن فيهم الصغير، والكبير، والضعيف، وذا الحاجة.  فالمشروع للإمام أن يراعي المأمومين؛ لأنه يكون فيهم المريض، وكبير السن، وصاحب الحاجة، فلا يعجل؛ فيخل بالصلاة، ولا يطول؛ فيشق عليهم، ولكن بين ذلك، صلاة معتدلة، يقرأ الفاتحة، وما تيسر معها في الأولى والثانية، ويقرأ في الأخيرتين الفاتحة، ويركد في الركوع، والسجود، وبين السجدتين، أيضًا يركد ولا يعجل، وهكذا عند قيامه من الركوع، ووقوفه بعد الركوع، لا يعجل، يطمئن، ويعتدل هكذا، لكن لا يطيل إطالة تشق على الناس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16274/المشروع-للامام-مراعاة-المامومين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83509.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17394,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول: أنا سكني بجوار المسجد، والحمد لله، وأواظب أوقاتي الخمسة في المسجد، ولكن في بعض الأوقات يحصل لي بعض الأزمات، من الصعب جدًا الذهاب إلى المسجد لأصلي صلاة الجماعة، فهل صلاتي مقبولة إذا صليتها في البيت؟ جزاكم الله خيرًا.","title":"حكم التخلف عن الصلاة في المسجد لعذر","answer":"الجواب: إذا كانت الأزمة عذرًا شرعيًا كالمرض المفاجئ فأنت معذور، إذا كان أمرًا واضحًا يشق عليك معه الحضور في الجماعة، كالمرض المفاجئ فأنت معذور، أما أمور أخرى كالتساهل من أجل الأولاد، أو الزوجة هذا ليس بعذر، الواجب عليك أن تتقي الله، وأن تبادر إلى صلاة الجماعة لما سمعت من الحديث السابق، يقول ﷺ: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر قال ابن عباس -رضي الله عنهما-: \"العذر الخوف والمرض\". هكذا السجن مسجون الممنوع معذور، وهكذا المقعد؛ لأنه كالمريض الذي يشق عليه الذهاب إلى المسجد، وقد سمعت حديث الأعمى، الرسول ﷺ قال للأعمى: أجب ولم يرخص له في الصلاة في البيت، وهو أعمى ليس له قائد، وقال: أجب وفي رواية: لا أجد لك رخصة. فالواجب عليك يا عبدالله أن تصلي في الجماعة، وأن تحذر التساهل بالأسباب التي لا وجه لها، بل بادر، وسارع إلى الصلاة في الجماعة، واتق الله، وراقب الله، واحذر التشبه بالمنافقين المتخلفين، قال تعالى في حق المنافقين: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى يُرَاءُونَ النَّاسَ وَلا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلً[النساء:142].  فاحذر يا أخي التشبه بأعداء الله، وكن نشيطًا في الصلاة.. حريصًا عليها.. مؤديًا لها في الجماعة في جميع الأوقات، وفق الله الجميع. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16270/حكم-التخلف-عن-الصلاة-في-المسجد-لعذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83506.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17431,"question":"نعلم أنه من السنة، أن يلتفت الإمام بعد السلام، ولكن هناك بعض الناس يكمل صلاته، ويكون وجه الإمام مقابلًا له، فماذا يفعل الإمام؟","title":"يلتفت الإمام بعد السلام ويكون وجهه في مقابل من يكمل صلاته، فما الحكم؟","answer":"الجواب: لا يضره، .. يصلي ويقضي ما عليه، ولو كان أمامه الإمام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16312/يلتفت-الامام-بعد-السلام-ويكون-وجهه-في-مقابل-من-يكمل-صلاته-فما-الحكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83614.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17455,"question":"هذا السائل أخوكم في الله (ع. ب. ت) يقول هذا السائل في سؤاله الأول: هل يجوز إمامة المعذور كمن به سلس البول للقوم الجهال؟ مع العلم بأنه لا يوجد في القوم من يقوم بأداء الواجب للصلاة أحسن من المعذور، حيث أنه أقرأهم لكتاب الله، ولسنة نبيه ﷺ وأعلمهم أيضًا بالأمور الشرعية.","title":"هل يجوز إمامة من به سلس البول للقوم الجهال؟","answer":"الجواب: الأحوط ألا يصلي بهم، ما دام معه سلس دائم الأحوط ألا يصلي بهم؛ لأن جمعًا من أهل العلم يرون أنه لا تصح إمامته، فالأحوط ألا يصلي بهم، يصلي بهم غيره، ولو كان أقل منه قراءة، نعم، يصلي بهم من هو صالح للإمامة، وإن كان أقل منه علمًا، وأقل قراءة، نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ من به سلس بول هل يجوز أن يصلي العشاء، ثم يصلي التراويح بدون إعادة للوضوء؟ الشيخ: نعم، إذا توضأ للوقت؛ كفى، لوقت العشاء؛ كفى، يصلي به التراويح والقيام -قيام الليل- لأنه وقت واحد. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16324/هل-يجوز-امامة-من-به-سلس-البول-للقوم-الجهال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77212.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17503,"question":"هذا سائل من الأردن يقول في هذا  سماحة الشيخ! أنا أعمل في بقالة طول النهار ويؤذن للصلاة ولا أتمكن من الذهاب إلى المسجد؛ لأنني أعمل وحدي وأجد صعوبة في إغلاق البقالة والمسجد يبعد عنا ما يقارب من نصف كيلو أي أن الرجل لو نادى بأعلى صوته لا يسمع، فما حكم صلاتي في المحل أو في بقالتي مأجورين؟","title":"وجوب صلاة الجماعة","answer":"الجواب: الواجب عليك الصلاة مع الجماعة وإغلاق البقالة كل ما جاء الوقت، ولا ينبغي التساهل في هذا الأمر؛ لأن الله أوجب عليك الصلاة في الجماعة، فالواجب عليك البدار بذلك طاعة لله ولرسوله عليه الصلاة والسلام، والله يقول: حَافِظُوا عَلَى الصَّلَوَاتِ[البقرة:238]، ويقول: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ[البقرة:43]، ويقول ﷺ لما جاءه رجل أعمى قال: «يا رسول الله! ليس لي قائد يلائمني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ قال: هل تسمع النداء بالصلاة؟ قال: نعم. قال: فأجب. فالواجب عليكم وعلى أمثالكم البدار بالصلاة في الجماعة، وإغلاق المحل التجاري سواء دكان أو بقالة أو غير ذلك حتى تصلوا مع إخوانكم، وتؤدوا ما أوجب الله عليكم من أدائها في الجماعة، ولا يجوز التساهل في هذا الأمر.","link":"https://binbaz.org.sa/fatwas/16418/وجوب-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_774/nour_77408.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17504,"question":"سماحة الشيخ! يقول في سؤاله الثاني السائل سالم من جمهورية مصر العربية: إذا صلى الإنسان وشك في صلاته ولم يكن عنده غالب ظن فهل يكفي أن يسجد للسهو فقط؟ أم يبني على ما تيقن ثم يسجد للسهو؟","title":"حكم من شك في صلاته دون غلبة ظن","answer":"الجواب: هذا فيه تفصيل: إن كان صلى وليس عنده شك ثم جاء الشك بعد الصلاة ليس عليه عمل صلاته صحيحة، والحمد لله، أما إن كان الشك في الصلاة في أثنائها فإنه يبني على اليقين، إذا شك هل صلى ثنتين أو ثلاثًا يجعلها ثنتين ثم يأتي بالبقية، شك هل هي ثلاث أو أربع يجعلها ثلاثًا ويكمل ويسجد للسهو قبل أن يسلم، وهكذا إذا شك هل سجد واحدة أو سجدتين؟ يسجد الثانية يأتي بالثانية ويبني على اليقين، يسجد الثانية، هذا إذا كان الوسواس عارضًا. أما إذا كان يغلب عليه الوساوس، يكثر عليه الوساوس؛ هذا يطّرحها ويبني على ظنه ويعمل بظنه والحمد لله ولا عليه شيء، ولا عليه سجود للسهو ولا، بل يعمل بظنه والحمد لله؛ لأن هذا من غلبة العدو عليه ... أكثر عليه عدو الله الوساوس، وأضاع عليه بصيرته، فلا يلتفت إليه، ويخالفه، ويعاكسه. أما إذا كانت الوسوسة عادية فإنه يبني على اليقين والحمد لله، أو يبني على غالب ظنه إذا غلب على ظنه شيء فلا بأس، إذا شك صلى ثنتين أو ثلاثًا وغالب ظنه أنها ثلاث يجعلها ثلاثًا، ويسجد للسهو بعد السلام. أما إن كان عنده تردد ما عنده غلبة ظن يبني على اليقين، إذا شك هي ثلاث أو ثنتين يجعلها ثنتين، شك هي ثلاث أو أربع يجعلها ثلاث ويكمل ثم يسجد للسهو قبل أن يسلم.\nالمقدم: شكر الله لكم يا سماحة الشيخ وبارك الله فيكم وفي علمكم ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/16433/حكم-من-شك-في-صلاته-دون-غلبة-ظن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_774/nour_77415.mp3","categories":["سجود السهو"," الوسواس بأنواعه"]},{"id":17509,"question":"مع مطلع هذه الحلقة نعود إلى رسالة وصلت إلينا من أحد الإخوة المستمعين ضمنها ما يقرب من خمسة عشر سؤالًا، أخونا هو عثمان محمد، عرضنا بعضًا من أسئلته في حلقة مضت، وفي هذه الحلقة لا زال له جمع من الأسئلة يقول في أحدها: هل يجوز للمتيمم أن يؤم الجماعة المتوضئين؟","title":"حكم إمامة المتيمم للمتوضئين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\nفنعم لا بأس أن يؤم المتيمم الناس المتوضئين، إذا كان له عذر شرعي أجاز له التيمم فإنه يصلي بالناس المتوضئين ولا حرج في ذلك والحمد لله؛ لأن التيمم طهارة شرعية، فإذا كان مريضًا لا يستطيع استعمال الماء وتيمم فإنه يصلي بهم وإن كانوا متوضئين، أو في السفر خرجوا متوضئين ثم قدر أنه أحدث وليس عندهم ماء وتيمم فإنه يصلي بهم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16430/حكم-امامة-المتيمم-للمتوضىين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_837/nour_83701.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17510,"question":"إذا دخل المصلي المسجد ووجد الصف الأول قد امتلأ ويريد أن يدرك الركعة فماذا يفعل: هل يقف وحده أم يجذب أحد المصلين من الصف الأول؟ جزاكم الله خيرًا.","title":"التصرف الصحيح لمن دخل المسجد والصفوف مكتملة","answer":"الجواب: عليه أن يلتمس فرجة، فإن لم يجد لا يجذب أحدًا بل ينتظر حتى يأتي أحد ولو فاتته الركعة، وإن تيسر له أن يتقدم مع الإمام ويصف عن يمينه فهذا طيب وإلا فلينتظر حتى يأتي أحد، ولا يصلي وحده ولا يجذب الناس، أما الحديث \"ألا دخلت معهم أو اجتررت رجلاً\" فهو ضعيف؛ ولأن جذب الرجل يفتح فرجة في الصف وهو تصرف فيه بغير حق. فالحاصل لا يجر رجلًا، ولا يصلي وحده؛ لقوله ﷺ: لا صلاة لمنفرد خلف الصف، ولكن ينتظر حتى يأتي من يصف معه، فإن لم يأت أحد صلى بعد ذلك، إذا سلم الإمام صلى وحده ... معذور.\nالمقدم: وحينئذ له أجر الجماعة سماحة الشيخ؟\nالشيخ: نرجو له أجر الجماعة؛ لأنه معذور شرعًا.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16458/التصرف-الصحيح-لمن-دخل-المسجد-والصفوف-مكتملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_837/nour_83712.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17522,"question":"من المستمع صالح عبد الله أحمد الإمام رسالة ضمنها جمعًا من الأسئلة، في أحدها يقول: كنت مأمومًا في صلاة العصر في مسجد قريتنا، وفي الركعة الأخيرة سجد الإمام وسجدنا معه آخر سجود في الركعة، ولما رفع من السجود لم نسمع تكبيرته، وظللنا ساجدين حتى قرأ الإمام التشهد ثم سلم فرفعنا من السجود، ماذا علينا والحال ما ذكر؟","title":"حكم صلاة من سلم إمامه وما زال ساجدًا","answer":"الجواب: إذا كنتم بقيتم في السجود لم تسمعوا فلا حرج عليكم، تكملون الصلاة والحمد لله، إذا رفعتم رءوسكم، تأتون بالتشهد ثم تسلمون بعده، ولا شيء عليكم والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا، أما إذا سلموا مع الإمام فالصلاة ...؟\nالشيخ: لا ما تصح صلاتهم، إذا سلموا عمدًا؛ لأنهم ما قرءوا التشهد، لا بد يقرءون التشهد، فإن صار نسيانًا يرجعون ويأتون بالتشهد ثم يسجدون للسهو ثم يسلمون، إذا كان فعلوه سهوًا، يعني: سلموا معه سهوًا .. يعني: اندهشوا سلموا معه سهوًا، يرجعون إلى الصلاة إذا كان العهد قريبًا ما طال الفصل ويقرءون التحيات، وبعد التكميل يسجدون للسهو ويسلمون، وإن سلموا ثم سجدوا للسهو كان هذا أفضل، يسلمون ثم يسجدون للسهو سجدتين بعد السلام.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16456/حكم-صلاة-من-سلم-امامه-وما-زال-ساجدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_837/nour_83711.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17539,"question":"بم تدرك صلاة الجماعة؟","title":"كيفية إدراك صلاة الجماعة","answer":"الجواب: بركعة، كما قاله النبي ﷺ: من أدرك ركعة من الصلاة فقد أدرك الصلاة، ومن فاتته الركعة الأخيرة فاته فضل الجماعة إلا أن يكون معذورًا بأن حرص على أن يحضر ولكن منعه مانع من مرض أو حدث به حادث في الطريق منعه أو حدث به حادث البول أو الغائط حتى احتاج إلى قضاء حاجته فإن له فضل الجماعة لأنه معذور، له فضل الجماعة وإن فاتته الجماعة، كما في الحديث الصحيح يقول ﷺ: إن العبد إذا مرض أو سافر كتب الله له ما كان يعمله وهو صحيح مقيم، رواه البخاري في الصحيح، يعني: بنيته العمل الصالح لولا السفر ولولا المرض، كذلك الحديث الصحيح يقول ﷺ في غزوة تبوك: إن في المدينة أقوامًا ما سرتم واديًا ولا قطعتم شعبًا إلا وهم معكم، -وفي اللفظ الآخر: إلا شركوكم في الأجر- قالوا: يا رسول الله! وهم في المدينة؟ قال: وهم في المدينة، حبسهم العذر. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16491/كيفية-ادراك-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_838/nour_83814.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17545,"question":"ماذا يفعل المسبوق إذا وجد المصلين في الركوع وقد أدرك الركوع لكنه لم يقرأ الفاتحة؟","title":"ما يفعله المسبوق إذا أدرك الإمام راكعًا؟","answer":"الجواب: إذا أدرك الركوع أجزأته الركعة على الصحيح، وهو قول جمهور أهل العلم؛ لأنه ثبت من حديث أبي بكرة الثقفي  أنه أتى ذات يوم والنبي راكع عليه الصلاة والسلام، فركع معه وركع دون الصف ثم دخل في الصف، فلما سلم قال له النبي ﷺ: زادك الله حرصًا ولا تعد، ولم يأمره بقضاء الركعة، أخرجه البخاري رحمه الله في الصحيح، وهذا يدل على أن الإنسان إذا فاته القيام أجزأته الركعة بإدراك ركوعها، وسقطت عنه الفاتحة؛ لأنه معذور لكونه لم يحضر في القيام، هذا هو الصواب وعليه الأئمة الأربعة رحمهم الله لحديث أبي بكرة هذا. وقال جماعة من أهل العلم: إن القراءة على المأموم ليست واجبة، قراءة الفاتحة، ونقل هذا عن الجمهور أن القراءة ليست واجبة على المأموم، قراءة الفاتحة، ولكن الأرجح أنها واجبة عليه لعموم الأحاديث، ومنها قوله ﷺ: لعلكم تقرءون خلف إمامكم؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب، فإنه لا صلاة لمن لم يقرأ بها، وهو حديث جيد. لكن إذا فاته القيام وأدرك الركوع أجزأه الركوع لحديث أبي بكرة المتقدم، وهكذا لو نسي الفاتحة أو جهل الحكم يحسب أنه لا حرج عليه فإن ركعته تجزئه، فالقراءة في حق المأموم واجبة تسقط بالنسيان والجهل وبعدم إدراك القيام، بخلاف قراءة الفاتحة في حق الإمام فإنها ركن لا بد منه، وهكذا في حق المنفرد ركن، لا تصح الصلاة بدونها؛ لقوله ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب، متفق على صحته. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16485/ما-يفعله-المسبوق-اذا-ادرك-الامام-راكعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_838/nour_83812.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17546,"question":"في حالة إدراك المأموم ركعة واحدة من صلاة المغرب، فكيف يتم صلاته؟","title":"كيفية إتمام الصلاة لمن فاتته ركعتان من المغرب","answer":"الجواب: إذا سلم الإمام يقوم يأتي وبركعة ثم يجلس التشهد الأول ويصلي على النبي ﷺ ثم يقوم ويأتي بالركعة الثالثة يقرأ فيها الفاتحة، هذا هو المشروع؛ لأن المغرب فيها تشهد أول بعد الثنتين والتشهد الأخير بعد الثالثة، وتشهده اللي مع الإمام ليس هو التشهد المطلوب منه بل هو تابع، إنما جلس متابعة لإمامه بعد الأولى، وإلا فالجلوس الذي في حقه هو بعد الثانية، ولهذا إذا أتى بالثانية يجلس ويأتي بالتشهد الأول. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16497/كيفية-اتمام-الصلاة-لمن-فاتته-ركعتان-من-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_838/nour_83816.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17550,"question":"من المستمع عماد الدين من السودان رسالة يقول فيها: أريد أن أعرف: ما حكم الإسلام في إنسان أتى إلى المسجد لكي يصلي مع الجماعة، ولكنه حينما أتى وجد الجماعة قد انقضت فما الحكم في ذلك؟ هل يصلي مفردًا؟ أم يكون هو ومن يجده في المسجد جماعة أخرى؟ أفتونا بارك الله فيكم.","title":"حكم من أتى المسجد وقد انتهت صلاة الجماعة","answer":"الجواب: إذا حضر الإنسان المسجد والناس قد صلوا وتيسر له وجود ناس يصلي معهم فإنه يصلي جماعة ثانية، هذا هو المشروع، يصلي جماعة ثانية، وقد ثبت عنه ﷺ أنه دخل رجل بعد ما صلى الناس فقال ﷺ: من يتصدق على هذا فيصلي معه؟، وفي الحديث الآخر: صلاة الرجل مع الرجل أزكى من صلاته وحده، فالمشروع لمن دخل وقد صلى الناس أن يلتمس من يصلي معه، فإن وجد وإلا شرع لمن حضر أن يقوم بعضهم فيصلي معه حتى تحصل له الجماعة للحديث السابق. أما قول بعض العلماء أنه يصلي وحده أو يرجع إلى بيته هذا قول ضعيف مرجوح، الصواب أنه يصلي جماعة مع من تيسر، ولو قام بعض الجماعة الذين قد صلوا وصلوا معه نافلة فهذا أفضل كما أمر به النبي ﷺ وأرشد إليه، قال: من يتصدق على هذا فيصلي معه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16481/حكم-من-اتى-المسجد-وقد-انتهت-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_838/nour_83810.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17551,"question":"إذا أدرك ثلاث ركعات في صلاة الظهر أو العصر، فكيف يتم صلاته قولًا وعملًا؟","title":"كيفية إتمام الصلاة لمن فاتته ركعة من الرباعية","answer":"الجواب: يكبر مع الإمام .. يكبر ويصلي ركعة التي ....... أعد أعد.\nالمقدم: يقول: إذا أدرك ثلاث ركعات من صلاة الظهر أو العصر، فكيف يتم صلاته قولًا وعملًا؟\nالشيخ: عليه إذا سلم الإمام أن يقوم فيأتي بالركعة التي بقيت عليه، يقرأ فيها الفاتحة فقط، هذا هو الأفضل، أما جلوسه مع الإمام ولم يتم صلاته فهو متابعة يقرأ فيه التحيات والصلاة على النبي ﷺ مع الإمام متابعة له أفضل، ثم يقوم ويأتي بالركعة الرابعة التي بقيت عليه، يقرأ فيها الفاتحة؛ لأنها الرابعة في حقه، ولو قرأ زيادة لا يضر لكن الأفضل أن يقرأ الفاتحة، هذا هو الأفضل لأنه ثبت عن النبي ﷺ أنه كان يقرأ في الثالثة والرابعة من صلاة الظهر والعصر بفاتحة الكتاب، وصلاة المغرب والعشاء مثل ذلك، يقرأ في الثالثة من المغرب الفاتحة، وفي الثالثة والرابعة من العشاء الفاتحة، ثم يجلس بعد ما يصلي الركعة، ويسجد سجدتين ..... ويأتي بالتشهد كاملاً مع الصلاة على النبي صلى الله عليه وسلم ومع الدعاء ثم يسلم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16498/كيفية-اتمام-الصلاة-لمن-فاتته-ركعة-من-الرباعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_838/nour_83817.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17555,"question":"من المستمع عماد الدين من السودان رسالة يقول فيها: أريد أن أعرف: ما حكم الإسلام في إنسان أتى إلى المسجد لكي يصلي مع الجماعة، ولكنه حينما أتى وجد الجماعة قد انقضت فما الحكم في ذلك؟ هل يصلي مفردًا؟ أم يكون هو ومن يجده في المسجد جماعة أخرى؟ أفتونا بارك الله فيكم.","title":"حكم من أتى المسجد وقد انتهت صلاة الجماعة","answer":"الجواب: إذا حضر الإنسان المسجد والناس قد صلوا وتيسر له وجود ناس يصلي معهم فإنه يصلي جماعة ثانية، هذا هو المشروع، يصلي جماعة ثانية، وقد ثبت عنه ﷺ أنه دخل رجل بعد ما صلى الناس فقال ﷺ: من يتصدق على هذا فيصلي معه؟، وفي الحديث الآخر: صلاة الرجل مع الرجل أزكى من صلاته وحده، فالمشروع لمن دخل وقد صلى الناس أن يلتمس من يصلي معه، فإن وجد وإلا شرع لمن حضر أن يقوم بعضهم فيصلي معه حتى تحصل له الجماعة للحديث السابق. أما قول بعض العلماء أنه يصلي وحده أو يرجع إلى بيته هذا قول ضعيف مرجوح، الصواب أنه يصلي جماعة مع من تيسر، ولو قام بعض الجماعة الذين قد صلوا وصلوا معه نافلة فهذا أفضل كما أمر به النبي ﷺ وأرشد إليه، قال: من يتصدق على هذا فيصلي معه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16481/حكم-من-اتى-المسجد-وقد-انتهت-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_838/nour_83810.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17556,"question":"إذا أدرك ثلاث ركعات في صلاة الظهر أو العصر، فكيف يتم صلاته قولًا وعملًا؟","title":"كيفية إتمام الصلاة لمن فاتته ركعة من الرباعية","answer":"الجواب: يكبر مع الإمام .. يكبر ويصلي ركعة التي ....... أعد أعد.\nالمقدم: يقول: إذا أدرك ثلاث ركعات من صلاة الظهر أو العصر، فكيف يتم صلاته قولًا وعملًا؟\nالشيخ: عليه إذا سلم الإمام أن يقوم فيأتي بالركعة التي بقيت عليه، يقرأ فيها الفاتحة فقط، هذا هو الأفضل، أما جلوسه مع الإمام ولم يتم صلاته فهو متابعة يقرأ فيه التحيات والصلاة على النبي ﷺ مع الإمام متابعة له أفضل، ثم يقوم ويأتي بالركعة الرابعة التي بقيت عليه، يقرأ فيها الفاتحة؛ لأنها الرابعة في حقه، ولو قرأ زيادة لا يضر لكن الأفضل أن يقرأ الفاتحة، هذا هو الأفضل لأنه ثبت عن النبي ﷺ أنه كان يقرأ في الثالثة والرابعة من صلاة الظهر والعصر بفاتحة الكتاب، وصلاة المغرب والعشاء مثل ذلك، يقرأ في الثالثة من المغرب الفاتحة، وفي الثالثة والرابعة من العشاء الفاتحة، ثم يجلس بعد ما يصلي الركعة، ويسجد سجدتين ..... ويأتي بالتشهد كاملاً مع الصلاة على النبي صلى الله عليه وسلم ومع الدعاء ثم يسلم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16498/كيفية-اتمام-الصلاة-لمن-فاتته-ركعة-من-الرباعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_838/nour_83817.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17587,"question":"الرسالة التالية وصلت إلى البرنامج من الأمارات العربية المتحدة- أبو ظبي وباعثها المستمع أحمد سالم الحامد، الأخ أحمد له جمع من الأسئلة في أحدها يقول: إذا دخلت المسجد والجماعة يصلون العصر وأنا لم أصل الظهر بعد، فهل أدخل مع الجماعة بنية الظهر؟ أم أصلي منفردًا الظهر ثم ألحق بالجماعة؟ جزاكم الله خيرًا.","title":"حكم من وجد الناس يصلون العصر ولم يصل الظهر","answer":"الجواب: الأرجح أن تصلي معهم بنية الظهر، هذا هو الصواب، ثم تصلي العصر بعد ذلك، ولا يضر اختلاف النية، فتدخل معهم وتصلي معهم الظهر بنية الظهر وإذا فرغت تصلي العصر وحدك أو مع من تيسر من الجماعة الأخرى، هذا هو الصواب. نعم.\nالمقدم: جزاكم الله خيرًا. كذلك في رمضان إذا دخلت المسجد والجماعة يصلون التراويح وأنا لم أصل العشاء، هل أنضم معهم أو أصلي منفردًا؟\nالشيخ: إن صليت منفردًا فلا بأس، وإن صليت معهم بنية الفريضة وإذا سلم تممت صلاتك فلا بأس، كله طيب. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16532/حكم-من-وجد-الناس-يصلون-العصر-ولم-يصل-الظهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_841/nour_84116.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17596,"question":"ننتقل بعد هذا إلى رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تسأل فيها جمعًا من الأسئلة، تقول في أحدها: هل سجود السهو قبل التسليم أم بعده، وإن كان قبله كما أعلم فهل يقرأ بعده شيئًا من التشهد أو يسلم مباشرة؟","title":"حالات سجود السهو قبل السلام وبعده","answer":"الجواب: السجود يختلف؛ سجود السهو تارة كذا وتارة كذا، الأفضل أن يكون قبل السلام ولا يقرأ بعده شيئًا، ينهي التشهد والدعاء وإذا كمله سجد للسهو سجدتين قبل أن يسلم، هذا في أغلب السهو، ويشرع أن يكون السجود بعد السلام في حالين:\nإحداهما: إذا سلم عن نقص، سلم عن نقص ركعة أو ركعتين ثم نبهوه يكمل ثم يسلم ثم يكون سجوده بعد السلام، هذا أفضل، وإن سجد قبل السلام فلا بأس.\nوالحال الثاني: إذا بنى على غالب ظنه، يعني: كمل الصلاة على غالب ظنه، فإنه يسجد للسهو بعد السلام، حصل عنده بعض شك هل صلاته ناقصة أو كاملة وغلب على ظنه أنها كاملة ما نقص منها شيئًا فإن هذه الغلبة توجب عليه سجود السهو لكن يكون بعد السلام أفضل؛ لأنه ورد في حديث ابن مسعود فيمن سها قال النبي ﷺ: فليتحر الصواب، فليتم ما عليه ثم ليسلم، ثم يسجد سجدتين، ولما سها وسلم من ركعتين ﷺ ونبهه الناس كمل صلاته ثم سلم ثم سجد للسهو بعد ذلك، وفي واقعة أخرى سلم من ثلاث فنبه فكمل صلاته ثم سجد للسهو بعد ذلك عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/16519/حالات-سجود-السهو-قبل-السلام-وبعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_841/nour_84106.mp3","categories":["سجود السهو"]},{"id":17601,"question":"هذا أخوكم في الله خالد حسين من فلسطين غزة ويقول بأني من متابعي هذا البرنامج أرجو عرض رسالتي على سماحة الشيخ، يقول يا سماحة الشيخ: إذا دخل مجموعة من المصلين والإمام في التشهد الأخير ما هو التصرف الصحيح في ذلك؟","title":"ما التصرف الصحيح إذا دخل والإمام في التشهد الأخير؟","answer":"الجواب: الأمر في هذا واسع، إن صلوا وحدهم فلا بأس، وإن صلوا مع الإمام فلا بأس، لعموم قوله ﷺ: فما أدركتم فصلوا هذا يعم إدراك التشهد، وإن صلوا وحدهم جماعةً فلا حرج إن شاء الله، الأمر في هذا واسع إن شاء الله.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16513/ما-التصرف-الصحيح-اذا-دخل-والامام-في-التشهد-الاخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59409.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17604,"question":"يقول: يا سماحة الشيخ حفظكم الله بالنسبة للمصلي المسبوق في تشهده الأخير، هل يذكر النصف الأول من التشهد أم كله؟ وإذا كان نصف التشهد فماذا عن الوقت الذي يسكت فيه حتى يسلم الإمام؟","title":"كيفية تشهد المسبوق مع الإمام التشهد الأخير","answer":"الجواب: يأتي بالتشهد وما معه تبعًا للإمام، ثم إذا سلم قام وقضى ما عليه، يأتي بالتشهد والصلاة على النبي والدعاء، ثم يقوم بعدما يسلم الإمام: صلوا كما رأيتموني أصلي إنما جعل الإمام ليؤتم به فهو يقرؤه تبعًا للإمام، وإن كان لا يجزئه لكن يقرؤه تبع الإمام مثل ما لو جاء وقد صلى ركعة، فيجلس معه في الركعة الثانية في التشهد الأول، وهو ليس في محل تشهد هو، ما صلى إلا ركعة، لكن يتابع الإمام، فالمقصود أن هذا متابعة الإمام والحمد لله. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16531/كيفية-تشهد-المسبوق-مع-الامام-التشهد-الاخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59412.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17645,"question":"لها سؤال مطول بعض الشيء -سماحة الشيخ- ملخص ما في هذا السؤال، أن والدها لا يصلي إلا في البيت، إلا في يوم الجمعة، فما هو توجيه سماحتكم؟","title":"حكم من لا يصلي في المسجد إلا يوم الجمعة","answer":"الجواب: هذا لا يجوز، الواجب على المكلف أن يصلي في المسجد، مع المسلمين، ولا يجوز للرجل المكلف أن يصلي في البيت، ولا على من بلغ العشر، بل يصلي مع الناس ويضرب إذا تأخر، لقوله عليه الصلاة والسلام في الحديث الصحيح: من سمع النداء فلم يأت فلا صلاة له إلا من عذر، قيل لـابن عباس: ما هو العذر؟ قال: خوف أو مرض. ولما ثبت في صحيح مسلم عن النبي ﷺ أنه سأله رجلٌ أعمى، فقال: يا رسول الله! ليس لي قائدٌ يقودني للمسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له النبي ﷺ: هل تسمع النداء بالصلاة؟،  قال: نعم، قال: فأجب هذا أعمى ليس له قائد، ومع هذا يقول له النبي ﷺ: أجب وفي الرواية الأخرى يقول: لا أجد لك رخصة.\nفالواجب على كل مسلم مكلف أن يتقي الله، وأن يصلي مع الجماعة في المساجد، ولا يجوز له أن يصلي في بيته؛ لأن هذا مخالف للأمر، وتشبه بالمنافقين، فالواجب الحذر من ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/16572/حكم-من-لا-يصلي-في-المسجد-الا-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_726/nour_72610.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17679,"question":"هذا سائل للبرنامج يقول: السجود بعد السلام هل يكون له سلام غير السلام الأول، أقصد سجود السهو؟","title":"هل يسلم لسجود السهو بعد التسليم الأول؟","answer":"الجواب: نعم إذا سجد للسهو بعد السلام يسلم تسليمتين مثل تسليمته الأولى، إذا سجد للسهو بعد السلام يسلم تسليمتين عن يمينه وشماله. نعم.","link":"https://binbaz.org.sa/fatwas/16612/هل-يسلم-لسجود-السهو-بعد-التسليم-الاول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59508.mp3","categories":["سجود السهو"]},{"id":17717,"question":"هذا السائل يقول في سؤاله: إذا أقيمت الصلاة وأنا في نافلة ثم صار هناك فراغ بيني وبين الصف هل علي حرج أن أمشي حتى أصل إلى نهاية الصف؟","title":"حكم من كان في نافلة وأقيمت الصلاة","answer":"الجواب: عليك أن تقطع الصلاة؛ أن تقطع النافلة إذا أقيمت الصلاة يقول ﷺ: إذا أقيمت الصلاة فلا صلاة إلا المكتوبة فعليك أن تقطعها وتدخل في الفريضة تقدم إلى الفرجة وتسدها إلا إذا كنت في آخرها قد ركعت الركوع الثاني في السجود في التحيات تكملها، ثم تقوم، وتدخل في الصف مع الإمام، أما إذا كان بقي عليك ركعة أو أكثر تقطعها لقوله ﷺ: إذا أقيمت الصلاة فلا صلاة إلا المكتوبة أخرجه مسلم في الصحيح. نعم.\nالمقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16678/حكم-من-كان-في-نافلة-واقيمت-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77622.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17719,"question":"نختم هذا اللقاء سماحة الشيخ بهذا السؤال وهو: إذا دخل شخص والإمام في التحيات الأخيرة هل يجلس أو ينتظر جماعة أخرى؟","title":"ماذا يفعل من دخل والإمام في التشهد الأخير؟","answer":"الجواب: الأفضل يدخل معهم ولا ينتظر لقوله ﷺ: إذا أتيتم الصلاة فعليكم السكينة والوقار، فما أدركتم فصلوا وما فاتكم فأتموا هذا عام يعم من أدركها في الركعة الأخيرة أو في التشهد يدخل معه والحمد لله. نعم.\nالمقدم: شكر الله لكم يا سماحة الشيخ وبارك الله فيكم وفي علمكم ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/16683/ماذا-يفعل-من-دخل-والامام-في-التشهد-الاخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77625.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17721,"question":"إذا دخل شخص والإمام قد ركع ثم ركع على رفع الإمام؟","title":"حكم ركوع المسبوق أثناء رفع الإمام","answer":"الجواب: إذا أدرك الركوع قبل أن يرفع اعتد بها، وإن رفع الإمام قبل أن يستوي راكعًا لا يعتد بها يقضيها، أما إذا استوى راكعًا قبل أن يرفع الإمام فإنه يعتد بها ولا يضره رفع الإمام، أما إذا هذا أقبل على الهوي والإمام رافع لا يعتد بها، يقضيها.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16681/حكم-ركوع-المسبوق-اثناء-رفع-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77624.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17895,"question":"أيضًا يقول في سؤال آخر: صليت إمامًا برجلين سمعت أحدهما كبر للإحرام أثناء تكبيري للإحرام، وقد مضيت في الصلاة مع اعتقادي بطلان صلاة الرجل المذكور فما الحكم؟ حفظكم الله.","title":"صلى إمامًا وسمع مأموما كبر للإحرام أثناء تكبيره","answer":"الجواب: الأظهر أن صلاتك صحيحة وصلاة الرجل الثاني صحيحة أما هو فيؤمر بالإعادة؛ لأنه كبر مع الإمام، والواجب أن يكبر بعد الإمام، كما قال ﷺ: إذا كبر فكبروا فتأمره بعد السلام بأن يعيد الصلاة، أما أنت فأنت معذور؛ لأنك سمعته وأنت في الصلاة، والمأموم معذور حين تأخر مع صاحبه يظنه مستقيمًا، يظن صلاته صحيحة وله شبهة، وأنت لك الشبهة في عدم الإنكار عليه وقد كبرت.\nفالأصل في هذا الصحة إن شاء الله لشبهة صحة صلاته بسبب أنه وقف مع المأموم الثاني وأنت لا تستطيع الإنكار عليه في الصلاة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16915/صلى-اماما-وسمع-ماموما-كبر-للاحرام-اثناء-تكبيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_846/nour_84603.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17902,"question":"من الرياض المستمع (ع. س) أبو بندر سؤال مطول بعض الشيء يقول فيه: مشكلتي هي أنني أعاني من ثقل نوعًا ما في القراءة حيث يركع الإمام في الركعتين الأخيرتين أو الثالثة في المغرب قبل أن أتمكن من إتمام الفاتحة، فإذا أتممت الفاتحة رفع أو ربما يرفع الإمام من الركوع قبل أن أركع لاسيما إذا صليت خلف إمام يخفف الصلاة، والسؤال هنا: هل أمضي وأتمم الفاتحة حتى ولو رفع الإمام من الركوع؟ أم يتعين علي متابعة الإمام حتى ولو لم أتمكن من إتمام الفاتحة في الصلاة كلها، حيث أنني سمعت بعض طلبة العلم يقولون: إن متابعة الإمام أهم وأوجب من إتمام الفاتحة في كل الركعات، فهل هذا هو الصحيح؟ أم هناك قول آخر أصح منه؟ وجهوني جزاكم الله خيرًا؟","title":"من لم يتمكن من إتمام الفاتحة هل يتابع الإمام أم يتمها","answer":"الجواب: الواجب عليك متابعة الإمام وإن لم تكمل الفاتحة؛ لقول النبي ﷺ وإذا ركع فاركعوا، فعليك أن تركع معه إذا ركع تركع بعده وإن لم تكمل الفاتحة، لكن عليك أن تعتني بقراءة الفاتحة من حين التكبير ومن حين ينهض من السجود وتستقيم واقفًا، فعليك أن تعتني بالقراءة ولا تتباطأ، تقرأ قراءة خفيفة حتى تدرك إكمال الفاتحة قبل الركوع، وعليك بالحذر من الوساوس، اقرأ قراءة جيدة والحمد لله، ولو كنت أسرعت فيها بعض الإسراع. بعض الناس يقرأ قراءة مقطعة يتأخر، لا. عليك أن تقرأ قراءة متصلة واضحة من حين تكبر تكبيرة الإحرام بعد الاستفتاح أفضل، وهكذا في الركعات الأخرى من حين تقف تبادر بالقراءة وأنت بهمة عالية لا بتباطؤ وتكاسل.\nلكن لو فرضنا أنه ركع وأنت .... بعض الآيات فاركع معه إلا أن كانت بقيت آية أو آيتان تكملها؛ لأنه يمديك أن تكملها وتركع. أما إذا خشيت أن يرفع فاركع ولا حرج عليك والحمد لله، كما لو جئت والإمام راكع ركعت معه وسقطت عنك الفاتحة، لو جاء المسبوق والإمام راكع وركع معه أجزأ وسقط عنه الفاتحة كما صح ذلك من حديث أبي بكرة  أنه أتى النبي ﷺ وهو راكع فركع دون الصف، ثم دخل في الصف، فقال له النبي ﷺ: زادك الله حرصًا ولا تعد. وهكذا لو كان المأموم يجهل الحكم الشرعي ما قرأ الفاتحة أو نسيها أجزأه؛ لأن القراءة في حق المأموم واجبة تسقط بالسهو والجهل وبعدم إدراك الإمام وهو واقف، كل هذا يكون من أسباب سقوطها إذا جهل الحكم أو سها عنها أو نسيها، أو جاء والإمام راكع، أو قرب الركوع ما أمكنه أن يقرأها سقطت عنه والحمد لله، هذا هو الصواب.\nوقال الجمهور: إنها غير واجبة على المأموم، قال أكثر أهل العلم: إنها غير واجبة على المأموم، والصواب أنها واجبة على المأموم لكنه إذا سها عنها أو جهل الحكم أو جاء متأخرًا والإمام راكع أو عند الركوع سقطت عنه كالواجبات الأخرى كما لو سها عن سبحان ربي العظيم أو سبحان ربي الأعلى أو ربنا ولك الحمد أو نحو ذلك أجزأه سقطت عنه، لقول النبي ﷺ: لعلكم تقرءون خلف إمامكم؟ قلنا: نعم. قال: لا تفعلوا إلا بفاتحة الكتاب فإنه لا صلاة لمن لم يقرأ بها فهذا يدل على أن المأموم يقرأ خلف إمامه، وأن هذا هو الواجب عليه، لكن متى سها عن ذلك أو جهل الحكم الشرعي سقط عنه ذلك فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].\nوالأصل في هذا حديث أبي بكرة لما جاء والنبي راكع عليه الصلاة والسلام ركع معه ولم يأمره بإعادة الركعة، مع أنه لم يقرأ الفاتحة؛ لأنه معذور بسبب عدم حضوره حال قيام الإمام. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16913/من-لم-يتمكن-من-اتمام-الفاتحة-هل-يتابع-الامام-ام-يتمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_846/nour_84602.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17905,"question":"آخر سؤال له يقول: هل وجود المأموم بين مجموعة من الأطفال دون سن التمييز عن يمينه وشماله في الصف هل يؤثر أو يخل بصلاته؟","title":"ما حكم صلاة المأموم بين الأطفال؟","answer":"الجواب: نعم. إذا كان فردًا إذا كان دون السبع يعتبر فردًا إذا كان ما فيه غيرهم ما صف معهم غيرهم يعتبر فردًا فلا يصح، نعم. عليه أن يعيد، عليه أن يعيد الصلاة، لقول النبي ﷺ: لا صلاة لمنفرد خلف الصف وهو حكمه حكم المنفرد، نعم. إذا كانوا دون التمييز دون السبع يعني.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16920/ما-حكم-صلاة-الماموم-بين-الاطفال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_846/nour_84604.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17916,"question":"إذا انسحب الإمام من الصلاة في ظروف ما واستخلف غيره هل يكمل الآية من حيث كان الإمام يقرأ؟ أم يكمل بآية أخرى، وبالنسبة للفاتحة هل يكملها أم يعيدها؟","title":"كيفية إكمال الصلاة لمن استخلفه الإمام","answer":"الجواب: إذا كان استخلفه يبدأ الفاتحة من أولها، يبدأ الفاتحة من أولها، وأما السورة فلا مانع أن يقرأ السورة التي قرأها الإمام أو غيرها أو يتم من آيات.\nالمقصود الفاتحة يأتي بها من أولها، وبقية الآيات إذا أتى بآيات أخرى غير ما قرأ الإمام أو سورة أخرى فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/16952/كيفية-اكمال-الصلاة-لمن-استخلفه-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78013.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17927,"question":"مستمع من السودان من بور سودان بعث يسأل جمعًا من الأسئلة في أحدها يقول: عندما أصلي في المسجد يقرأ الإمام سورة التين، وعندما يصل إلى قوله تعالى: أَلَيْسَ اللَّهُ بِأَحْكَمِ الْحَاكِمِينَ [التين:8]، أسمع الناس: يرددون من خلفه: بلى ونحن على ذلك من الشاهدين، فهل هذا مشروع؟","title":"حكم قول المأمومين: بلى ونحن على ذلك من الشاهدين، في آخر سورة التين","answer":"الجواب: جاء في حديث ضعيف \"أنه كان ﷺ إذا قرأ: أَلَيْسَ اللَّهُ بِأَحْكَمِ الْحَاكِمِينَ [التين:8]، قال: بلى ونحن على ذلك من الشاهدين، وإذا قرأ: فَبِأَيِّ حَدِيثٍ بَعْدَهُ يُؤْمِنُونَ [المرسلات:50] من آخر المرسلات قال: آمنت بالله ورسله، آمنت بالله وبما أنزل، وإذا قرأ آخر القيامة: أَلَيْسَ ذَلِكَ بِقَادِرٍ عَلَى أَنْ يُحْيِيَ الْمَوْتَى [القيامة:40]، قال: سبحانك فبلى\"، ولكنه ضعيف إلا ما ورد في القيامة فهو ثابت عند قوله تعالى: أَلَيْسَ ذَلِكَ بِقَادِرٍ عَلَى أَنْ يُحْيِيَ الْمَوْتَى [القيامة:40]، يقال: بلى، سبحانك فبلى، هذا مشروع، وأما عند آخر سورة التين والمرسلات فهو ليس بمحفوظ. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16967/حكم-قول-المامومين-بلى-ونحن-على-ذلك-من-الشاهدين-في-اخر-سورة-التين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_847/nour_84711.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17935,"question":"مستمع من السودان من بور سودان بعث يسأل جمعًا من الأسئلة في أحدها يقول: عندما أصلي في المسجد يقرأ الإمام سورة التين، وعندما يصل إلى قوله تعالى: أَلَيْسَ اللَّهُ بِأَحْكَمِ الْحَاكِمِينَ [التين:8]، أسمع الناس: يرددون من خلفه: بلى ونحن على ذلك من الشاهدين، فهل هذا مشروع؟","title":"حكم قول المأمومين: بلى ونحن على ذلك من الشاهدين، في آخر سورة التين","answer":"الجواب: جاء في حديث ضعيف \"أنه كان ﷺ إذا قرأ: أَلَيْسَ اللَّهُ بِأَحْكَمِ الْحَاكِمِينَ [التين:8]، قال: بلى ونحن على ذلك من الشاهدين، وإذا قرأ: فَبِأَيِّ حَدِيثٍ بَعْدَهُ يُؤْمِنُونَ [المرسلات:50] من آخر المرسلات قال: آمنت بالله ورسله، آمنت بالله وبما أنزل، وإذا قرأ آخر القيامة: أَلَيْسَ ذَلِكَ بِقَادِرٍ عَلَى أَنْ يُحْيِيَ الْمَوْتَى [القيامة:40]، قال: سبحانك فبلى\"، ولكنه ضعيف إلا ما ورد في القيامة فهو ثابت عند قوله تعالى: أَلَيْسَ ذَلِكَ بِقَادِرٍ عَلَى أَنْ يُحْيِيَ الْمَوْتَى [القيامة:40]، يقال: بلى، سبحانك فبلى، هذا مشروع، وأما عند آخر سورة التين والمرسلات فهو ليس بمحفوظ. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16967/حكم-قول-المامومين-بلى-ونحن-على-ذلك-من-الشاهدين-في-اخر-سورة-التين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_847/nour_84711.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17970,"question":"من المستمع علي سعيد الغامدي من الباحة قرية الأجادي الحوزة بعث برسالة وضمنها جمعًا من الأسئلة يقول في أحدها: إذا تذكر الإمام في أثناء الصلاة أنه محدث فماذا يفعل؟","title":"ما يفعل الإمام إذا علم أنه محدث أثناء الصلاة؟","answer":"الجواب: يستنيب من يكمل بهم، يقدم واحدًا ممن حوله الذي يكمل بهم الصلاة والحمد لله هذا هو الصواب، يستنيب من يكمل بهم الصلاة ممن حوله من الطيبين مثلما فعل عمر  لما طعن قدم عبد الرحمن بن عوف وصلى بهم.. كمل بهم الصلاة، وإن استأنفوها من أولها قدموا غيره واستأنفوها من أولها فلا حرج، وإن انتظروه جلسوا ينتظرونه حتى يتوضأ ثم يعود ويصلي بهم من أول الصلاة فلا بأس ولكن الأفضل أن يستنيب حتى لا يشق عليهم، أن يستنيب من يكمل بهم والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.\nالمقدم: أما هو فيعيد الصلاة من أولها؟\nالشيخ: أما هو فيعيد، يعيد .... يتوضأ ويعيد. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17003/ما-يفعل-الامام-اذا-علم-انه-محدث-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_848/nour_84811.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17976,"question":"من المستمع علي سعيد الغامدي من الباحة قرية الأجادي الحوزة بعث برسالة وضمنها جمعًا من الأسئلة يقول في أحدها: إذا تذكر الإمام في أثناء الصلاة أنه محدث فماذا يفعل؟","title":"ما يفعل الإمام إذا علم أنه محدث أثناء الصلاة؟","answer":"الجواب: يستنيب من يكمل بهم، يقدم واحدًا ممن حوله الذي يكمل بهم الصلاة والحمد لله هذا هو الصواب، يستنيب من يكمل بهم الصلاة ممن حوله من الطيبين مثلما فعل عمر  لما طعن قدم عبد الرحمن بن عوف وصلى بهم.. كمل بهم الصلاة، وإن استأنفوها من أولها قدموا غيره واستأنفوها من أولها فلا حرج، وإن انتظروه جلسوا ينتظرونه حتى يتوضأ ثم يعود ويصلي بهم من أول الصلاة فلا بأس ولكن الأفضل أن يستنيب حتى لا يشق عليهم، أن يستنيب من يكمل بهم والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.\nالمقدم: أما هو فيعيد الصلاة من أولها؟\nالشيخ: أما هو فيعيد، يعيد .... يتوضأ ويعيد. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17003/ما-يفعل-الامام-اذا-علم-انه-محدث-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_848/nour_84811.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":17981,"question":"إذا قدم المسلم يريد الدخول في الصلاة ولكنه وجد الصف مكتملًا هل يسحب أحد المصلين ويصلي معه؟ أم أنه يصلي منفردًا متابعًا للإمام؟","title":"من جاء للجماعة والصف مكتمل هل يسحب أحد المصلين أم يصلي خلف الصف","answer":"الجواب: المشروع له أن يلتمس فرجة لعله يجد، فإن لم يجد وقف مع الإمام عن يمينه، فإن لم يتيسر ذلك انتظر ولا يسحب أحدًا؛ لأن سحبه ظلم وتعدٍ عليه وفتح فرجة في الصف، ولكن ينتظر فإن قضيت الصلاة ولم يأت أحد صلى وحده والحمد لله، معذور. نعم.\nالمقدم: جزاكم الله خيرًا. إذا صلى الركعة الأولى منفردًا مع الإمام ثم دخل معه مصل آخر في الركعة الثانية وبعد الانتهاء من الفرض هل يسلم مع الإمام أم أنه يقوم فيأتي بالركعة الأخيرة؟\nالشيخ: إذا صلى ركعة واحدة بطلت صلاته فعليه أن يستأنف مع الجديد مع الشخص الذي جاء ويستأنف معه من أول الصلاة، فإذا استمر ولم يستأنف يعيدها؛ لأن صلاته باطلة، يعني: صلى ركعة وحده خلف الصف، والنبي عليه السلام يقول: لا صلاة لمنفرد خلف الصف هكذا صح عنه ﷺ، وصح عنه أنه أمر من صلى وحده خلف الصف أن يعيد الصلاة، لكن لو ركع وحده ثم دخل في الصف أو وقف معه آخر قبل السجود صحت وأجزأت والحمد لله كما فعل أبو بكرة . نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17004/من-جاء-للجماعة-والصف-مكتمل-هل-يسحب-احد-المصلين-ام-يصلي-خلف-الصف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_848/nour_84812.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18024,"question":"يسأل سؤال آخر ويقول: نحن في قرية في مصر وقريب من بيتنا مسجد صغير، لكن إمام المسجد لا يقرأ القرآن على الطريقة الصحيحة كثيرًا ما نبهناه إلى ذلك، ولكن لا فائدة، هل يجوز أن نصلي في منازلنا طالما أنه يخطئ في قراءة القرآن الكريم؟","title":"حكم الصلاة خلف إمام لا يجيد قراءة القرآن","answer":"الجواب: هذا فيه تفصيل: إذا كان اللحن لا يغير المعنى فالواجب عليكم أن تصلوا معه تؤدوا الجماعة، وأما إن كان يغير المعنى فالواجب تنبيهه حتى يستقيم أو يعزل، يجتمع الجماعة على عزله والتماس من هو خير منه، فإذا كان لحنه في مثل الحمد لله رب العالمين أو الحمد لله رب العالمين ما يضر المعنى صحيح وله وجه من العربية، الحمد لله رب العالمين رب العالمين له وجه من العربية، أو الرحمن الرحيم أو الرحمن الرحيم أو ما أشبه ذلك من اللحن الذي لا يغير المعنى فلا بأس لا يضر هذا، أو قال: اهدنا الصراط المستقيم، أو الصراط المستقيم ما يضر ما يغير المعنى، لكن لو غير المعنى وجب تنبيهه حتى يستقيم مثل: إياك هذا يغير المعنى، أو صراط الذين أنعمت عليهم هذا للمتكلم ما يصلح، أو أنعمت لخطاب المرأة ما يصلح يغير المعنى، هذا يجب أن ينبه عليه حتى يغير العبارة، حتى يستقيم لسانه؛ لأن هذا اللحن يغير المعنى لا تستقيم معه القراءة. لابد أن يعيد القراءة بالوجه الشرعي فيعيد أنعمت ويعيد إياك بالفتح حتى تستقيم القراءة، وإذا لم يستطع يبدل يعزل، وهكذا في الآيات الأخرى خارج الفاتحة يراعى فيها المعنى، فإن كان اللحن لا يغير المعنى فالأمر في هذا واسع وغيره أفضل منه ممن يقيم الألفاظ، أما إذا كان يحيل المعنى فإن الواجب عزله وإبداله بمن يصلح للإمامة. ولا يجوز لكم الجلوس في البيت والصلاة في البيت بل يجب أن تصلوا في المسجد وأن تعملوا ما يلزم من إصلاح وضعه أو إبداله بغيره. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17057/حكم-الصلاة-خلف-امام-لا-يجيد-قراءة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_850/nour_85009.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18027,"question":"المستمع سعد خميس الدوسري بعث يقول: إذا صليت خلف إمام، وأثناء الصلاة لاحظت أن بإحدى رجليه بقعة لم يصلها الماء، فنبهته بعد الصلاة فلم يبال، فأعدت الصلاة، فما حكم ما فعلت؟","title":"حكم من صلى خلف إمام طهارته غير صحيحة","answer":"الجواب: إذا صلى الإمام بالناس، ثم بان أنه محدث، أو أن طهارته غير صحيحة؛ فصلاة المأمومين صحيحة، هذا هو الصواب، صلاتهم صحيحة، وعليه هو الإعادة إذا علم أنه محدث أو أن طهارته فيها خلل يبطلها؛ عليه أن يعيد هو وليس على الجماعة إعادة، صلاتهم صحيحة، والواجب عليه هو أن يعيد، نعم. المقدم: جزاكم الله خيرًا، وإذا أعاد المأموم اعتقادًا منه أن فعله صحيح؟ الشيخ: لا حرج عليه، إذا أعاد اجتهادًا منه؛ لا حرج عليه، لكن ينبغي أن يعلم الحكم الشرعي، وأنه لا إعادة عليه، فمن عاد يظن أن عليه إعادة فهو مأجور إن شاء الله . المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17048/حكم-من-صلى-خلف-امام-طهارته-غير-صحيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_599/59903.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18057,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع: يوسف عثمان يوسف ، الأخ يوسف يقول: إذا أدرك الإنسان عددًا من الركعات في أي صلاة مع الجماعة وهو مسبوق، هل الركعات التي يأتي بها تكون هي التي لم يدركها؟ أم الذي أدركها، ويكمل صلاته؟ جزاكم الله خيرًا.","title":"ما أدركه المسبوق مع الإمام هو بداية صلاته","answer":"الجواب: تقدم في بعض الأجوبة أن ما أدركه هو أول صلاته، وما يقضيه هو آخرها؛ لأن الرسول عليه الصلاة والسلام قال: ما أدركتم فصلوا، وما فاتكم فأتموا وفي روايةٍ: فاقضوا ومعناه فأتم، معنى القضاء: الإتمام، فالذي يقضيه هو آخر صلاته، والذي يدركه مع الإمام هو أول صلاته، فإذا أدرك مع الإمام ركعتين، يقرأ الفاتحة، وإن تيسر يقرأ معها زيادة، يقرأ الزيادة مع الفاتحة، ثم إذا قام يقضي يقرأ الفاتحة بالذات فقط؛ لأنها آخر صلاته. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17090/ما-ادركه-المسبوق-مع-الامام-هو-بداية-صلاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_729/nour_72914.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18079,"question":"يسأل أخونا عن صلاة المسافر الذي يقصر ويجمع بالمقيمين، هل تجوز أو لا؟","title":"حكم صلاة المقيم خلف المسافر","answer":"الجواب: نعم، صلاة المسافر بالمقيمين صحيحة، فإذا سلم؛ يتمون، إذا كان مسافرًا، وهم مقيمون، صلى معهم الظهر ثنتين، والعصر ثنتين، والعشاء ثنتين، ثم يتمون، أما هو -المسافر- إذا صلى خلف المقيم، فإنه يتم، يصلي أربع، إذا كان المسافر مأمومًا، والإمام مقيم؛ فإن المسافر يتم، يصلي أربعًا، هكذا السنة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17114/حكم-صلاة-المقيم-خلف-المسافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_730/nour_73003.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18083,"question":"أنا أصلي في المسجد، وأحيانًا لا أدرك الصلاة كاملة، فإذا أدركت التشهد الأخير فقط، هل يعتبر قد أدركت صلاة الجماعة؟","title":"عدم إدراك الجماعة لمن أدرك التشهد الأخير","answer":"الجواب: الجماعة لا تدرك إلا بركعة؛ يقول النبي ﷺ: من أدرك ركعةً من الصلاة، فقد أدرك الصلاة ، فالواجب المسارعة إلى الصلاة في الجماعة، والحرص على المبادرة بعد سماع الأذان، حتى لا يفوتك شيءٌ من الصلاة، فإن قدر أنه فاتك شيء، فإنك تقضي ما فاتك، ولا تكون مدركًا للجماعة إلا إذا أدركت ركعةً، أو أكثر. أما من جاء والإمام في التشهد الأخير، فإنه يصلي معه، لكن فاتته الجماعة، لكن يصلي معه، يجلس يصلي معه، لقوله ﷺ: ما أدركتم فصلوا، وما فاتكم فأتموا، فعمم عليه الصلاة والسلام، ما أدركتم فهذا يعم الركعة الأخيرة، والسجود الأخير، والتشهد، يعمه. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17118/عدم-ادراك-الجماعة-لمن-ادرك-التشهد-الاخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_730/nour_73007.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18087,"question":"عندما أكون مسبوقًا، وأدرك الجماعة في أي صلاة، هل الركعات التي أصليها بعد تسليم الإمام أعتبرها هي التي سبقتني؟ أم هي التي أدركتها مع الإمام؟ جزاكم الله خيرًا.","title":"ما أول صلاة المسبوق؟","answer":"الجواب: الصواب أن ما أدركه المسبوق هو أول صلاته، ما أدركه مع الإمام هو أولها، يقرأ فيه مع الفاتحة ما تيسر، وما يقضيه هو آخرها، هذا هو الصواب؛ لقوله ﷺ: ما أدركتم فصلوا، وما فاتكم فأتموا فهو إتمامٌ للصلاة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17122/ما-اول-صلاة-المسبوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_730/nour_73011.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18088,"question":"أحد الإخوة المستمعين بعث برسالة آثر فيها عدم ذكر اسمه، يسأل ويقول: هنالك رجلٌ يصلي بأبنائه في بيته، ونحن ننصحه كثيرًا بأن يصلي في المسجد هو وأبناؤه، وهو يصلي في بيته ويقول: للاطمئنان على أنهم قد صلوا، فهل عمل هذا الرجل صحيح؟ أم لابد من صلاته في المسجد بعد ذلك؟ يأتي ويصلي بأولاده، وجهونا جزاكم الله خيرًا.","title":"حكم صلاة الأب مع أولاده في البيت","answer":"الجواب: الواجب عليه وعلى أولاده الصلاة في المسجد، عليهم جميعًا أن يصلوا في المسجد، وعليه أن يحاسبهم، وأن يستعين بالله عليهم، حتى يصلوا معه في المسجد، لقول الرسول ﷺ: مروا أبناءكم بالصلاة لسبع، واضربوهم عليها لعشر، فهو يجتهد في هذا، ويحرص حتى يذهبوا معه إلى المسجد، ولا يجوز له أن يصلي في البيت، ومن تخلف منهم، إن كان ابن عشر فأكثر، أدبه، وإن كان ابن سبع فأكثر إلى العشر، فلا تأديب عليه، لكن بالكلام الطيب، والنصيحة، والتوجيه، لكن إذا بلغ العشر استحق أن يضرب، حتى يستقيم. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17123/حكم-صلاة-الاب-مع-اولاده-في-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_730/nour_73012.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18127,"question":"أخونا أيضًا يسأل سماحة الشيخ ويقول: هل تصح الصلاة خلف مستور الحال في المجتمع الذي أعيش فيه أم لا؟","title":"حكم الصلاة خلف مجهول الحال","answer":"الجواب: نعم إذا كان مستور الحال، ولا تعرف عنه شيئًا من الشرك وهو مسلم يتظاهر بالإسلام تصح الصلاة خلفه، والحمد لله، حتى تعلم ما يوجب منع ذلك من ظهور الكفر والشرك. أما ما دام مستورًا مع المسلمين، لا يظهر منه ما يوجب ردته؛ فإنك تصلي خلفه والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/17173/حكم-الصلاة-خلف-مجهول-الحال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_852/nour_85203.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18269,"question":"لمن صلى العصر وبعد أن انتهى ثم خرج ولما عاد بعد قليل ذكر بأنه غير متأكد، هل صلى ثلاثًا أو أربعًا، ماذا يفعل؟","title":"حكم من شك في عدد الركعات بعد خروجه من المسجد","answer":"الجواب: ما دام الشك طرأ بعد ذلك، وهو حين انصرف من الصلاة حين انصرف من الصلاة ليس عنده شك، فالشك الطارئ لا يضر ولا يعبأ به، ولا يلتفت إليه، أما إذا شك في أثناء الصلاة قبل أن يسلم، هل صلى ثلاثًا أم ثنتين؟ يبني على اليقين، يجعلها ثنتين ويأتي بالثالثة، أو شك هل صلى ثلاثًا أم أربعًا يبني على اليقين وهو الأقل، فيجعلها ثلاثًا ويأتي بالرابعة، ثم يسجد للسهو إن كان إمامًا أو منفردًا. أما إن كان مأمومًا فهو تبع إمامه، ليس له نظر في الشك بل يتابع إمامه ولا عبرة بشكه، أما بعد السلام، كونه يطرأ عليه شك جديد، هذا لا يعتبر ولا يلتفت إليه. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17318/حكم-من-شك-في-عدد-الركعات-بعد-خروجه-من-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_910/nour_91005.mp3","categories":["سجود السهو"]},{"id":18357,"question":"سماحة الشيخ هل مقتضى قول النبي ﷺ: صلاة الجماعة تفضل صلاة الفذ بسبع وعشرين درجة جواز الصلاة في غير المسجد؟","title":"هل مقتضى: «صلاة الجماعة تفضل صلاة الفذ» جواز الصلاة في غير المسجد؟","answer":"الجواب: .......: ثم آمر رجلًا فيؤم الناس ثم أنطلق برجال معهم حزم من حطب إلى قوم لا يشهدون الصلاة فأحرق عليهم بيوتهم ويقول ابن مسعود : «لقد رأيتنا وما يتخلف عنها -يعني: صلاة الجماعة- إلا منافق معلوم النفاق أو مريض». فكون الصلاة في الجماعة أفضل من صلاة الفذ بسبع وعشرين درجة ما يقتضي جواز الصلاة في البيت هي أفضل ومع ذلك واجبة، واجبة في الجماعة ولا يجوز فعلها في البيت إلا من عذر كالمرض. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17410/هل-مقتضى-صلاة-الجماعة-تفضل-صلاة-الفذ-جواز-الصلاة-في-غير-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91324.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18361,"question":"يقول هذا السائل في سؤاله الثاني: رجل صلى ركعة منفردًا خلف الصف، فلما سلم الإمام أتى بخامسة؟","title":"حكم من صلى خلف الصف","answer":"الجواب: الذي يظهر أنها لا تصح الصلاة؛ لأن الرسول ﷺ قال: لا صلاة لمنفرد خلف الصف فإذا صلى ركعة فأكثر فلا صلاة له، أما لو صلى بعض الشيء مثل قام خلف الصف، ثم جاء معه آخر أو دخل في الصف، أو ركع، ثم دخل في الصف، أو جاء معه آخر؛ لا بأس. أما إذا كمل الركعة فإنها لا تصح لقوله ﷺ: لا صلاة لمنفرد خلف الصف وأقر أبا بكرة لما ركع دون الصف ثم دخل في الصف، ولم يأمره بالقضاء، فدل على أنه إذا كان الانفراد في الركوع أو في القيام قبل الركوع هذا يجزئ، ثم دخل في الصف أو صف معه آخر، أما إذا سجد وليس معه أحد، أو أتى بأكثر من ذلك؛ فإن الصلاة غير صحيحة. وقد رأى النبي ﷺ رجلًا يصلي خلف الصف وحده فأمره أن يعيد الصلاة وقال: لا صلاة لمنفرد خلف الصف اللهم صل عليه وسلم. المقدم: اللهم صل وسلم وزد وبارك على نبينا وحبيبنا محمد، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17430/حكم-من-صلى-خلف-الصف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78324.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18416,"question":"رجل بلغ من العمر ستين عامًا وهو لا يصلي الصلوات الخمس إلا في بيته ما عدا الجمعة، يصليها في المسجد فهل تقبل صلاته؟ علمًا أن المسجد بجوار البيت؟","title":"حكم الصلاة في البيت بدون عذر","answer":"الجواب: هذا قد فعل منكرًا عظيمًا وخالف الشرع، فإن الشرع يلزمه بالحضور في جماعة المساجد جماعة المسلمين، لكن الصلاة صحيحة في أصح قولي العلماء الصلاة صحيحة ليس عليه إعادة، ولكن عليه التوبة إلى الله، عليه التوبة إلى الله من تأخره عن المسجد وعن الجماعة، والصلاة في البيت من غير عذر هذا لا يجوز، فعليه أن يتقي الله وأن يصلي مع الناس، وأن يتوب إلى الله مما سلف. يقول النبي ﷺ: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر،  ، قيل لابن عباس: ما هو العذر؟ قال: \"خوف أو مرض\". وسأله ﷺ رجل أعمى قال: يا رسول الله! ليس لي قائد يقودني إلى المسجد؛ فهل لي من رخصة أن أصلي في بيتي؟ فقال عليه الصلاة والسلام: هل تسمع النداء بالصلاة؟ قال: نعم. قال: فأجب، فهذا أعمى ليس له قائد، ومع هذا يقول له النبي ﷺ: أجب ليس لك رخصة. فالواجب على المؤمن الذي يستطيع الحضور في المسجد أن يحضر المسجد ويصلي مع الناس، وليس له التخلف والصلاة في بيته. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17492/حكم-الصلاة-في-البيت-بدون-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_733/nour_73305.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18434,"question":"يوجد كثير من الناس يسمعون النداء للصلاة فلا يصلون في المسجد ويصلون في بيوتهم، وليس لهم أي عذر شرعي، فهل صلاتهم صحيحة؟","title":"حكم التخلف عن الصلاة جماعة لغير عذر","answer":"الجواب: هذا الذي يفعله بعض الناس من الصلاة في البيت، مع سماعهم النداء، هذا منكر، في أصح قولي العلماء لا يجوز لهم الصلاة في البيت مع سماع النداء، وقرب المسجد، بل الواجب على كل مسلم ذكر أن يصلي في المسجد إذا استطاع ذلك، ولم يمنعه مرض ولا خوف؛ لأن الرسول ﷺ كان هو وأصحابه  يصلون في المسجد ويقول: صلوا كما رأيتموني أصلي عليه الصلاة والسلام، ويقول: من سمع النداء فلم يأت فلا صلاة له إلا من عذر قيل لابن عباس: ما هو العذر؟ قال: مرض أو خوف». فإذا كان مريضًا لا يستطيع فهو معذور أو يخاف لأن البلد غير آمنة، أو لأنه يراقب لقتله أو ضربه؛ فهو معذور، ويقول ﷺ لـعبد الله بن أم مكتوم لما استأذنه في الصلاة، وكان رجلاً أعمى، قال: «يا رسول الله! ليس لي قائد يلائمني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال عليه الصلاة والسلام: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب خرجه مسلم في صحيحه. فإذا كان الرجل الأعمى الذي ليس له قائد يلائمه، ليس له عذر، فكيف بالمعافى البصير غير المعذور؟ والمقصود أن الواجب على الرجال أن يصلوا في المساجد مع الجماعة، وأن يحذروا طاعة الشيطان في الصلاة في البيت، وقد دلت السنة على أن هذا بل دل القرآن العظيم .......................","link":"https://binbaz.org.sa/fatwas/17515/حكم-التخلف-عن-الصلاة-جماعة-لغير-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_914/nour_91409.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18453,"question":"أصلي إمام بالناس، وأسمع بعض القادمين للصلاة، فأطيل الركوع حتى يلحق المتأخر بالجماعة، هل هذا يصح أم لا؟","title":"حكم إطالة الإمام للركوع لأجل المتأخرين","answer":"الجواب: هذا هو السنة، إذا سمعت أثرًا للقادم أن لا تعجل في الركوع، لكن بشرط أن لا تطيل إطالة تشق على من معك، بل تكون إطالة خفيفة لا تشق على المأمومين. نعم.","link":"https://binbaz.org.sa/fatwas/17553/حكم-اطالة-الامام-للركوع-لاجل-المتاخرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_865/nour_86512.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18473,"question":"أخ لنا من جمهورية اليمن يقول السائل صالح سالم حسين، محافظة صعدة، ناحية الحشوة-العقيق- أخونا يقول: إنه رأى شخصًا كان يعتقد أن له منزلة أكبر من المنزلة التي رآه عليها وهي بيعه للقات، وذلكم الرجل إمام لمسجد، ويسأل عن الحكم وعن الصلاة خلف ذلكم الرجل؟","title":"جواز الصلاة خلف بائع القات","answer":"الجواب: ينبغي تنبيهه ونصيحته؛ لأن القات كثير من علماء اليمن يبيحونه ويتعاطونه، فهذا الإمام قد يكون له شبهة، قد يكون ممن يرى إباحته، أو يقلد من يرى إباحته من علماء اليمن. فالذي نرى نصيحته والمشورة عليه بتركه وأن لا يبيعه وأن لا يشربه، والصلاة خلفه صحيحة والحمد لله؛ لأن الصحيح من أقوال العلماء أن الصلاة خلف الفاسق صحيحة، وإنما تبطل إذا كانت خلف الكافر، أما العاصي فالصلاة خلفه صحيحة، لكن يشرع لك يا أخي نصيحة هذا أو التماس من ينصحه ممن هو فوقك حتى يقدره وحتى يقبل منه، وأنت في هذا على أجر، وصلاتك صحيحة والحمد لله.","link":"https://binbaz.org.sa/fatwas/17569/جواز-الصلاة-خلف-باىع-القات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_866/nour_86607.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18576,"question":"سماحة الشيخ! هذا سوداني مقيم بالمملكة بحائل أحمد محمد يقول: كنت أنا وزوجتي نصلي في جماعة، أي: في صف واحد، تصلي معي في صف واحد، وعندما سمعت من أحد الإخوة بأنه يقول: لا يجوز للمرأة أن تصلي مع الرجل في صف واحد أصبحت أفكر كثيرًا في الأيام التي كانت تصليها معي زوجتي في صف واحد، هل أعيد الصلاة؟","title":"أين تقف المرأة في الصلاة مع الرجال؟","answer":"الجواب: ليس عليك إعادة، لكن في المستقبل تكون خلفك؛ النبي ﷺ أمرهن أن يكونوا خلف الرجال، وصلى مرة في بيت أم أنس، فأقام أنس عن يمينه، والمرأة خلفه جدة أنس . فالمقصود: أن موقف النساء يكون خلف الرجال، حتى ولو هو وزوجته، تكون خلفه لا تصف معه، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17693/اين-تقف-المراة-في-الصلاة-مع-الرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78620.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18601,"question":"يمتلئ الصف الأول في المسجد، فنريد أن نكون الصف الثاني، فهل نبدأ به من خلف الإمام مباشرة بموازاته؟ أم على يمين الصف أو يساره؟ وجوهنا جزاكم الله خيرًا.","title":"من أين يبدأ ترتيب الصفوف في الصلاة؟","answer":"الجواب: الواجب البداءة من وسط الصف مما يلي الإمام، يعني: مما يقابل الإمام يبدأ من هذا، ثم يصفون عن يمين وشمال، البداءة من وسط الصف كالأول، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17709/من-اين-يبدا-ترتيب-الصفوف-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_734/nour_73408.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18603,"question":"هذا سائل يقول في سؤاله الأول: مسجد موجود عندنا بالعمل يمتلئ دائمًا -والحمد لله- بالمصلين، وعند انقضاء الصلاة تتكون في الحال جماعة أخرى فتصلي، ولكن يتفق أحيانًا -وإن كان ذلك قليلًا- أن يكون هناك وفي مكان آخر جماعة أخرى تصلي لم يشاهدوها، فيصبح بالمسجد جماعتان أو أكثر في نفس الوقت، فما العمل في هذه الحالة؟ وما على من جاء متأخرًا ليصلي فوجد جماعتين في المسجد تؤديان الصلاة، فإلى أيهما ينضم؟أفيدونا بذلك مأجورين.","title":"حكم وجود جماعتين في المسجد بعد الجماعة الأولى","answer":"الجواب: لا حرج في إقامة جماعة ثانية إذا صلى الإمام الراتب، وجاء قوم لم يصلوا يصلون جماعة، والحمد لله، كان أنس  إذا جاء والناس قد صلوا صلى مع أهل بيته جماعة، المقصود: أنه صلى مع إخوانه، ومن معه جماعة. فالحاصل: أنه إذا جاء جماعة وقد صلى الإمام يصلون جماعة، فإذا جاء جماعة أخرى يصلون مع الجماعة الأولى لا ينفردون، يصلون مع الجماعة الأخرى، لكن لو لم يعلموا عنهم؛ لأن المسجد كبير، وصلوا جماعة، ثم جاء آخر يصلي مع من شاء منهما، والأحسن مع الأكثر، يصلي مع الأكثر، كلما كثرت الجماعة صار الأجر أكثر، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17715/حكم-وجود-جماعتين-في-المسجد-بعد-الجماعة-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78702.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18605,"question":"هذا سائل يقول في سؤاله الأول: مسجد موجود عندنا بالعمل يمتلئ دائمًا -والحمد لله- بالمصلين، وعند انقضاء الصلاة تتكون في الحال جماعة أخرى فتصلي، ولكن يتفق أحيانًا -وإن كان ذلك قليلًا- أن يكون هناك وفي مكان آخر جماعة أخرى تصلي لم يشاهدوها، فيصبح بالمسجد جماعتان أو أكثر في نفس الوقت، فما العمل في هذه الحالة؟ وما على من جاء متأخرًا ليصلي فوجد جماعتين في المسجد تؤديان الصلاة، فإلى أيهما ينضم؟أفيدونا بذلك مأجورين.","title":"حكم وجود جماعتين في المسجد بعد الجماعة الأولى","answer":"الجواب: لا حرج في إقامة جماعة ثانية إذا صلى الإمام الراتب، وجاء قوم لم يصلوا يصلون جماعة، والحمد لله، كان أنس  إذا جاء والناس قد صلوا صلى مع أهل بيته جماعة، المقصود: أنه صلى مع إخوانه، ومن معه جماعة. فالحاصل: أنه إذا جاء جماعة وقد صلى الإمام يصلون جماعة، فإذا جاء جماعة أخرى يصلون مع الجماعة الأولى لا ينفردون، يصلون مع الجماعة الأخرى، لكن لو لم يعلموا عنهم؛ لأن المسجد كبير، وصلوا جماعة، ثم جاء آخر يصلي مع من شاء منهما، والأحسن مع الأكثر، يصلي مع الأكثر، كلما كثرت الجماعة صار الأجر أكثر، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17715/حكم-وجود-جماعتين-في-المسجد-بعد-الجماعة-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78702.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18614,"question":"إذا جلس المصلي في صلاة الجماعة للتشهد، هل يجب عليه أن يصف نفسه ويقدمه بحيث يجعل ركبتيه بجانب ركبتي اللذين بجانبه، أم المهم أن يكون الظهر موازيًا لزميله الذي يصلي بجانبه؟جزاكم الله خيرًا.","title":"حكم المحاذاة في الصلاة وكيفيتها","answer":"الجواب: على كل حال.....، يصلي المأموم عن يمين الإمام لا حرج أن يكون محاذيًا لقدميه العبرة بالقدمين تكون الأكعب متحاذية، ويكفي، ولو كان ظهره أطول. فالمقصود: أنه إذا تحاذى صار قدمه حذاء قدمه كفى، هذا هو السنة، أن يكونا متحاذيين بالأقدام، بالأكعب، والحمد لله، ولو كان مأمومًا مع الإمام وحده، لا يتأخر ولا يتقدم يكون محاذيًا له، نعم.\nالمقدم: إذًا المهم بداية الصف سماحة الشيخ؟ الشيخ: نعم. المقدم: جزاكم الله خيرًا. الشيخ: وسط الصف...، من وسط الصف، والمحاذاة تكون بالأقدام...، مع الإمام.....، واحد ولا بين المأمومين......، يتحاذون بالأقدام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17724/حكم-المحاذاة-في-الصلاة-وكيفيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_734/nour_73412.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18632,"question":"ثالث أسئلة هذا السائل نور الدين يقول: إذا كنتُ أصلي في المسجد، أو مع الجماعة، وأنا في آخر الصف، ولا أسمع تكبيرات الإمام ولا القراءة، فقط أركع مثل الذي أمامي، يركع فأركع، ويسجد فأسجد، هل تصح صلاتي؟","title":"حكم صلاة من لا يسمع قراءة الإمام وتكبيراته","answer":"الجواب: نعم، ولو ما سمعت، تتبعهم ولو ما سمعت، تقتدي بمن حولك من المأمومين، والحمد لله، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17746/حكم-صلاة-من-لا-يسمع-قراءة-الامام-وتكبيراته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78714.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18686,"question":"هل يجوز للإمام أن يستأجر شخصًا آخر ليقوم بالإمامة نيابة عنه؟","title":"حكم استئجار إمام المسجد من ينوب عنه في الإمامة","answer":"الجواب: فلا حرج في ذلك في أصح قولي العلماء إذا كان المستأجر صالحًا لذلك، ووافقت عليه الجهة المسئولة -كالأوقاف مثلًا- أو صاحب المسجد الذي عينه فيه إمامًا، لكن إذا ترك الاستئجار وقال له: تنوب عني، أنا -إن شاء الله- أساعدك يكون أحسن من لفظ الاستئجار؛ لأن كثيرًا من أهل العلم يكرهوا هذا اللفظ، ويكرهوا هذا الاستعمال، لحديث: اتخذ مؤذنًا لا يأخذ على أذانه أجرًا وسُئل أحمد -رحمه الله- عن رجل يقول: أصلي بكم رمضان بكذا وكذا، فقال: أعوذ بالله! ومن يصلي خلف هذا؟! أو كما قال -رحمه الله-. فالحاصل: مثل هذه العبارات فيها شيء من النقص، أو كونه يقول له: أنت تنوب عني وأنا -إن شاء الله- لا أقصر في مساعدتك، أو -إن شاء الله- أعطيك ما يعينك على حاجتك، أو ما أشبه ذلك، أحسن من كونه يتعاقد معه إجارة، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17795/حكم-استىجار-امام-المسجد-من-ينوب-عنه-في-الامامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_873/nour_87302.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18699,"question":"مستمع فاروق حسين إبراهيم من السودان يقول: دخلت المسجد لأداء صلاة العصر، فوجدت ثلاثة أشخاص يصلون، فصليت معهم بنية صلاة العصر، ولكن بعدما تفرقنا وفرغنا من صلاتنا أخبروني بأنهم صلوا صلاة الظهر؛ لأنها كانت فائتة بالنسبة لهم، ولما قاموا لصلاة العصر، قمت وصليت معهم أيضًا، فهل صلاتي الأولى هي الصحيحة أم الثانية؟جزاكم الله خيرًا.","title":"صحة صلاة العصر خلف من يصلي الظهر قضاءً","answer":"الجواب: الأولى صحيحة، والثانية نافلة، والحمد لله، الأولى صحيحة ما دامت في الوقت، الحمد لله، يجوز أن يصلي الإنسان العصر خلف من يصلي الظهر، إذا كان عليه العصر، وهم يصلون الظهر في وقت العصر؛ لأنها فاتتهم أو لأنهم قد جمعوا بينها وبين العصر جمع تأخير؛ فصلاته معهم بنية العصر -إذا كان قد صلى الظهر- صحيحة، هذا هو الصواب من قولي العلماء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17794/صحة-صلاة-العصر-خلف-من-يصلي-الظهر-قضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_735/nour_73511.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18746,"question":"أخونا السائل سماحة الشيخ يقول: في بعض المساجد توجد أعمدة بين الصفوف تؤدي إلى قطعها وتجزئتها إلى أكثر من صف، فهل الأفضل في مثل هذه الحالة أن يصلي الإنسان بجانب العمود، ومن ثم يكون الصف متقطع، أم الأفضل أن يكمل الصف بأن يجعل العمود من خلفه؟ مع العلم بأن الصف في هذه الحالة يكون مكتمل، ولكن مائلًا لخروج المصلي قليلًا عن الصف، أفتونا في ذلك مأجورين.","title":"حكم الصلاة بين الأعمدة والسواري","answer":"الجواب: السنة أن تستقيم الصفوف متصلة والأعمدة خلفهم، تكون الأعمدة خلفهم، والصف يكون مستقيمًا أمام الأعمدة، ولا تقطع الصفوف إلا عند الضرورة، إذا ازدحم المسجد، وضاق المسجد، وصف الناس بين السواري؛ فلا حرج للحاجة؛ ولهذا قال أنس: إنهم كانوا يتقون ذلك يتقون الوقوف بين السواري، يعني: عند عدم الحاجة إلى ذلك. فالسنة: أن يتقدم المأمومون، وتكون الأعمدة خلفهم، ولا يضر لو تقدم قليل من جهة العمود؛ ليجعل خلفه العمود، لكن ينبغي للذين بين العمودين أن يتقدموا قليلًا، حتى يستقيم الصف، حتى يكون الذي خلفه العمود وغيره، سواء سواء مستقيمين في الصف لا يتقدم أحد على أحد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17874/حكم-الصلاة-بين-الاعمدة-والسواري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79005.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18773,"question":"وهذا سائل آخر يستفسر عن مجموعة من الأسئلة في سؤاله الأول يقول: رجل دخل المسجد والإمام في الركعة الثانية من الظهر، ولم يجد فرجة في الصف، فصلى منفردًا، وفي الركعة التالية جاء البعض من الناس، وأتموا الصف، فهل الركعة التي صلاها هذا الرجل منفردًا صحيحة أم عليه أن يعيد هذه الركعة فقط؟ مأجورين.","title":"صلى منفردا خلف الصف في أول ركعة فهل تصح صلاته؟","answer":"الجواب: صلاته غير صحيحة؛ لقول النبي ﷺ: فلا صلاة لمنفرد خلف الصف فهو صلى ركعة أو أكثر صلاته غير صحيحة، إلا إذا كان أبطلها وابتدأ كبر تكبيرة الإحرام لما جاء معه أحد فهو صحيح، ما أدرك بعد ذلك، يعني: إذا جاء معه في الركعة الأخيرة، وقطع الصلاة، وابتدأ كبر تكبيرة الإحرام ناويًا الصلاة مع الإمام لما جاء معه شخص آخر يكون أدرك ركعة، حسب ما وقع له، أما إذا كان بنى على صلاته التي هي فيها منفرد فصلاته غير صحيحة؛ لقوله ﷺ: لا صلاة لمنفرد خلف الصف ورأى رجلًا يصلي خلف الصف وحده، فأمره أن يعيد -عليه الصلاة والسلام-. المقصود: أن الصلاة خلف الصف باطلة، وعلى صاحبها الإعادة إذا كانت فريضة. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17903/صلى-منفردا-خلف-الصف-في-اول-ركعة-فهل-تصح-صلاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79109.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18778,"question":"يقول هذا السائل: إذا قام الإمام إلى ركعة خامسة في العشاء، وعندما قام قال له المصلون: سبحان الله، ولكنه لم يقعد، وأكمل الركعة، وقام المصلون من خلفه، فما حكم هذه الركعة؟ما حكم عمل هذا الإمام؟","title":"حكم متابعة الإمام في زيادة ركعة","answer":"الجواب: الواجب تنبيهه بالتسبيح، فإذا لم يرجع انتظروا حتى يسلم؛ لأنه قد يعتقد صواب نفسه، فينتظرونه حتى يسلم، ويسلموا معه، والذي لا يعلم أنه مخطئ يقوم معه، الذي لا يعلم الحال يقوم معه يتابع إمامه، والذي يعلم أن الإمام مخطئ يجلس حتى يسلم مع الإمام بعدما يسلم الإمام. ومن اعتقد أنه قد أخطأ فليس له القيام بل يصبر، وأما الإنسان الذي ما عنده خبر هل الإمام مصيب أو ما هو مصيب فإنه يتابعه؛ لأن الأصل متابعة الإمام حتى يسلم معه، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17905/حكم-متابعة-الامام-في-زيادة-ركعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79111.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18791,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع أبو مؤمن خلف الله علي، مصري يعمل في اليمن، أخونا عرضنا جزءًا من أسئلته في حلقة مضت، وبقي له مجموعة من الأسئلة في هذه الحلقة فيسأل مثلًا ويقول:أصلي يا سماحة الشيخ العشاء جماعة في المسجد، ثم أعود إلى البيت فأصلي بزوجتي العشاء، محتسبًا إياها نافلة لي، وهي بالنسبة للزوجة فريضة، هل في ذلك شيء؟","title":"جواز صلاة المفترض خلف المتنفل","answer":"الجواب: بسم الله الرحمن الرحيم  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فليس في ذلك حرج إذا كان المقصود تعليمها وتوجيهها إلى الصلاة الشرعية، فقد كان معاذ بن جبل -رضي الله تعالى عنه- يصلي مع النبي ﷺ صلاة العشاء، ثم يرجع إلى قومه فيصلي بهم تلك الصلاة، فتكون له نافلة ولجماعته فريضة، فلا حرج في ذلك، وفي هذا فائدة من جهة التعليم والتوجيه، ولا أعلم بهذا بأسًا -إن شاء الله-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17918/جواز-صلاة-المفترض-خلف-المتنفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_876/nour_87601.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18795,"question":"من ليبيا هذه رسالة بعث بها أخونا فضل الله عبد ربه منصور، يسأل مجموعة من الأسئلة من بينها سؤال يقول: إذا تذكرت أن الصلاة ناقصة بعد السلام، هل أعود وأكملها، وكيف هي الصفة؟","title":"حكم من تذكر بعد السلام أن الصلاة ناقصة","answer":"الجواب: هذا فيه تفصيل: إن تذكرت أنها ناقصة نقصًا يتعلق بأركانها؛ فعليك أن تكملها، أما إن كان النقص يتعلق بالسنن والمستحبات؛ فلا يضرك ذلك، والنوافل تجبر ما نقص من صلاتك، أما لو تذكرت أنك ما صليت إلا ثلاث في الظهر أو العصر أو العشاء؛ فإنك تقوم تأتي برابعة وتسجد للسهو سجدتين قبل أن تسلم أو بعد السلام، وهو الأفضل إذا كنت سلمت ثم تذكرت أنك لم تصل إلا ثلاث..، في الظهر والعصر والعشاء، أو ثنتين في المغرب أو واحدة في الفجر، بعدما سلمت تذكرت أنها ناقصة؛ فإنك تقوم وتكمل، وبعد الفراغ من التشهد والدعاء تسلم ثم تسجد سجدتي السهو بعد السلام؛ لأن النبي فعل هذا -عليه الصلاة والسلام- لما سلم عن نقص ركعة، وفي بعض الروايات: نقص ركعتين وذكروه قام فكمل صلاته، ثم كمل التحيات والدعاء، ثم سلم ثم سجد للسهو سجدتين -عليه الصلاة والسلام- ثم سلم، ولو سجدت السجدتين قبل السلام أجزأ ذلك. أما إن كان النقص في مثل سجدة من السجدات، أو ركوع من الركوعات، ذكرت أنك نسيت ركوعًا، أو سجدة بعدما سلمت؛ فإنك تقوم وتأتي بركعة كاملة، تأتي بركعة كاملة، ثم بعد التحيات وبعد الصلاة على النبي ﷺ وبعد الدعاء تسلم، ثم تسجد سجدتي السهو، ثم تسلم ثانيًا، هذا هو المشروع لك. أما إن كان النقص غير هذا، بأن تذكرت أنك مثلًا لم تجلس التشهد الأول، قمت إلى الثالثة ما جلست ناسيًا، أو نسيت (سبحان ربي الأعلى) في السجود، أو نسيت (سبحان ربي العظيم) في الركوع، أو نسيت (رب اغفر لي) بين السجدتين، هذا يكفيك سجود السهو، تسجد للسهو ويكفي، وكما لو نسيت (ربنا ولك الحمد) بعد الركوع يكفيك أن تسجد سجدتين للسهو والحمد لله؛ لأن الرسول ﷺ لما قام عن التشهد الأول ناسيًا سجد سجدتي السهو قبل أن يسلم ثم سلم -عليه الصلاة والسلام-. أما إن كان النقص شيئًا مستحبًا مثلما تقدم، مثل ذكرت أنك نسيت الاستفتاح، ما قلت: سبحانك اللهم ربي وبحمدك، في أول الصلاة، وهو الاستفتاح: (سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك)، لم تقله ولا غيره من الاستفتاحات، بل كبرت وابتدأت التعوذ والتسمية والقراءة، ما قرأت الاستفتاح هذا سنة ليس عليك شيء، كذلك لو تذكرت أنك مثلًا ما دعوت في السجود، قلت: سبحان ربي الأعلى، ولا دعوت في السجود فليس عليك؛ لأن الدعاء في السجود مستحب وليس بلازم، أو تذكرت أنك ما كررت (سبحان ربي العظيم) كثير ما قلتها إلا مرة أو مرتين؛ فإنه ليس عليك شيء. أو تذكرت أنك بعدما صليت على النبي ﷺ في التشهد الأخير، سلمت ولا أتيت بالدعاء -التعوذ من الأربع- فلا شيء عليك، وهكذا لو تذكرت أنك قلت بين السجدتين: (رب اغفر لي) مرة واحدة، ما كثرت، ما كررتها ثلاث، قلتها مرة فقط ثم سجدت الثانية، ليس عليك شيء؛ لأن هذه سنن ونوافل وليست بواجبة، فإذا تركها الإنسان ناسيًا أو عامدًا فهذا نقص ليس عليه فيه شيء وصلاته صحيحة، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17926/حكم-من-تذكر-بعد-السلام-ان-الصلاة-ناقصة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_876/nour_87606.mp3","categories":["سجود السهو"]},{"id":18881,"question":"يقول: كثير من الناس حينما يحضر إلى الصلاة في المسجد وهي مقامة؛ يجدون أطفالًا يصلون بعضهم أقل من السابعة، وبعضهم أكثر من السابعة، فيقومون بإزاحتهم إلى طرف الصف ويصفون في مكانهم، وإذا كانوا في طرف الصف، يؤخرونهم إلى الصف الذي يليه؛ مما يؤدي إلى قطع صلاتهم، فهل في عملهم هذا شيء؟وماذا يجب علينا حين نشاهد مثل ذلك؟ وهل يجوز تأخير الذين أعمارهم أقل من السابعة من صفهم إلى الصف الذي يليه؟وجهونا، جزاكم الله خيرًا.","title":"حكم إخراج الأطفال من الصفوف في الصلاة","answer":"الجواب: أما من كان بلغ السابعة فالمشروع تركه، ولا يجوز تأخيره؛ لأنه سبق إذا ما لم يسبق إليه مسلم فهو أولى بمكانه، وفيه تشجيع له على المحافظة والمسارعة إلى الخير فلا يؤخر. أما من كان دون السبع فهذا محل نظر، إن ترك فلا بأس؛ لئلا يحصل عليه مضرة إذا أخر، ولئلا يعبث أو يذهب إلى محل آخر يضره، فتركه في مكانه أولى وأحوط، حتى لا يحصل أي ضرر، أو يحصل منه عبث يضر أحدًا من الناس في تأخيره، بالتشويش عليه، نعم. المقدم: جزاكم الله خيرًا، إذًا هناك مراعاة خاصة للأطفال في المساجد سماحة الشيخ. الشيخ: نعم نعم مراعاة لئلا يقع شر عليهم إذا أخروا في الصلاة، قد يذهبون إلى جهات تضرهم، وقد يعبثون عبثًا يضرهم ويضر غيرهم، ثم أيضًا في تركهم في الصف تمرين لهم على المجيء والحرص على الصلاة؛ حتى إذا كملوا السابعة إذا هم قد تمرنوا، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا، لو التفت الطفل وهو في الصف، أو تحرك حركة ربما تكون زائدة، ما هو توجيه سماحة الشيخ؟ الشيخ: يشيروا له. المقدم: بالهدوء. الشيخ: حتى يهدأ، نعم بالإشارة، ما دام في الصلاة بالإشارة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، إذًا سماحة الشيخ: ممن يدعو إلى اصطحاب الأطفال بعد تأديبهم إلى المساجد. الشيخ: يوجهون. المقدم: بارك الله فيكم. الشيخ: حتى يعتادوا الخير، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18017/حكم-اخراج-الاطفال-من-الصفوف-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73613.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18937,"question":"هذا سائل يقول: شخص جاء قبل تسليم الإمام في صلاة رباعية، وبعد التسليم نهض وصلى ركعتين ناسيًا، هل يصلي ركعتين بعدها ويسجد للسهو، أم يعيد الصلاة أربع ركعات؟","title":"حكم من سلم من ركعتين ناسيًا في صلاة رباعية","answer":"الجواب: يكمل، يصلي أربعًا، ويسجد للسهو إذا ذكر قريبًا، يأتي بركعتين يكمل صلاته، ثم يسجد للسهو، يسجد للسهو بعد السلام أفضل. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18063/حكم-من-سلم-من-ركعتين-ناسيا-في-صلاة-رباعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88203.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18944,"question":"يقول: إذا تأخر الرجل عن صلاة الفجر إلى ما بعد الجماعة، فهل يصلي في البيت مع زوجته جماعة؟","title":"حكم صلاة الفجر جماعة في البيت لمن تأخر","answer":"الجواب: إذا فاتته الجماعة في المسجد يصلي في بيته وحده، وإلا هو وزوجته، لكن زوجته تكون وراءه ما تصف معه، تكون خلفه، وإن صلى وحده فلا بأس إذا فاتته الجماعة في المسجد.","link":"https://binbaz.org.sa/fatwas/18142/حكم-صلاة-الفجر-جماعة-في-البيت-لمن-تاخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88241.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":18951,"question":"أدركت الإمام في آخر ركعة، وكان الصف قد اكتمل، ولم يتسع لي، ولم أتمكن من سحب شخص من الصف الأول، فهل يجوز أن أقف منفردًا في الصف الثاني؟","title":"حكم الصلاة منفردًا خلف الصف","answer":"الجواب: ليس لك ذلك، صل عن يمين الإمام، تلتمس فرجة وإلا تصلي عن يمين الإمام، ولا تصلي وحدك، فإن لم تجد أحدًا فاصبر، فإذا سلم الإمام صل وحدك إن لم يأت أحد. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18119/حكم-الصلاة-منفردا-خلف-الصف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88234.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19003,"question":"رسالة وصلت إلى البرنامج من المملكة الأردنية الهاشمية وباعثها مستمع من هناك رمز إلى اسمه بالحروف: (ر. هـ. م. خ) يسأل جمعًا من الأسئلة في أحدها يقول: هل تكون سجدة السهو قبل التسليم في الركعة الأخيرة أم بعده؟ جزاكم الله خيرًا.","title":"هل سجدة السهو قبل التسليم أم بعده؟","answer":"الجواب: سجود السهو السنة فيه أن يكون قبل التسليم قبل أن يسلم إلا في حالين: إحداهما: إذا سلم عن نقص كأن يسلم من ثلاث في الظهر، أو العصر، أو العشاء، أو يسلم من ثنتين في المغرب، أو من واحدة في الفجر، أو الجمعة، هذا الأفضل أن يكون بعد التسليم كما فعله النبي عليه الصلاة والسلام. والحال الثاني: إذا بنى على غالب ظنه واجتهد فإن الأفضل أن يكون سجوده بعد السلام؛ لحديث ابن مسعود  عن النبي ﷺ أنه قال: إذا شك أحدكم في صلاته فليتحر الصواب، فليتم ما عليه، ثم ليسلم، ثم يسجد سجدتين بعد السلام فإذا بنى على غالب ظنه؛ فإنه يسجد سجدتين بعد السلام؛ لهذا الحديث، ومعنى ذلك أنه إذا شك هل هو في الثالثة أو في الرابعة، في الظهر، أو العصر، أو العشاء، ويغلب على ظنه أنه في الرابعة؛ فإنه يكمل ويسجد للسهو بعد السلام، وهكذا في المغرب لو شك هل هو في الثانية أو في الثالثة، وبنى على غالب ظنه، ولم ينبه؛ فإنه يسجد للسهو بعد السلام. أما إذا كان عنده تردد وليس عنده غلبة الظن فإنه يبني على اليقين، فإذا شك هل هو في الثانية أو في الثالثة، يكون في الثانية، يبني على أنه في الثانية. وإذا شك هل هو في الثالثة أو الرابعة، وليس عنده غلبة ظن؛ فإنه يبني على اليقين، ويجعلها الثالثة، ثم يكمل صلاته ويسجد للسهو قبل السلام. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18161/هل-سجدة-السهو-قبل-التسليم-ام-بعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_795/nour_79502.mp3","categories":["سجود السهو"]},{"id":19020,"question":"أخونا يسأل سؤال فيه شيء من الغرابة يقول: إذا كان إمام المسجد ينتظر في بيته، ولا يحضر للمسجد إلا عند الإقامة، ولا يشتغل في البيت بصلاة نافلة أو قراءة قرآن، فهل الأفضل له التبكير إلى المسجد قبل الإقامة؟","title":"المشروع للإمام بين الأذان والإقامة","answer":"الجواب: هذا لا نعلم فيه حدًا محدودًا ولا سنة واضحة، بل الأمر يرجع إلى الإمام؛ فإن رأى أن حضوره المسجد أصلح لقلبه وأنفع للناس ليقرأ ليصلي ما تيسر ويقرأ، وربما كان عالمًا فيفتي الناس بما يسألونه عنه ونحو ذلك كان هذا أفضل، وإن رأى أن بقاءه في البيت أصلح له يقرأ في بيته ويصلي الرواتب في بيته، ثم يأتي عند إقامة الصلاة كما هو الغالب من فعل النبي عليه الصلاة والسلام. المعروف من فعله ﷺ أنه كان يبقى في البيت فإذا جاء وقت الإقامة خرج إلى الناس عليه الصلاة والسلام، هذا هو الأصل في الإمام يبقى في بيته، ويشتغل بما يسر الله له من قراءة أو علم أو صلاة نافلة ونحو ذلك، ويحرص على الرواتب التي شرعها الله من أربع قبل الظهر وثنتين بعدها، وثنتين بعد المغرب، وثنتين بعد العشاء، وثنتين قبل صلاة الصبح، هذه رواتب حافظ عليها النبي عليه الصلاة والسلام، فإذا فعلها الإمام في البيت، وفعل ما يسر الله له من الخير من دراسة قرآن أو قراءة علم أو تحفظ شيء ينفعه من العلم أو القرآن فكل هذا طيب. فالأصل أن الإمام يبقى في البيت اقتداءً بالنبي عليه الصلاة والسلام، ثم يأتي وقت الإقامة فيقيم الصلاة، فإذا رأى في حالة من الحالات، أو في قرية من القرى، أو في بلد من البلدان أن مجيئه إلى المسجد قبل الصلاة ينتظرها مع الناس في المسجد يصلي ما كتب الله له مما شرع الله ويقرأ القرآن، أو يسبح ويهلل في محل من المسجد حتى يحضر وقت الإقامة، كل هذا لا بأس به. والخلاصة: أن الأصل والأفضل أن يكون في البيت حتى يأتي وقت الإقامة اقتداءً بالنبي عليه الصلاة والسلام، فإذا حصل له أمر آخر يقتضي أنه يحضر في المسجد وأن في ذلك مصلحة راجحة على بقائه في البيت فلا أعلم في هذا بأسًا بل ينبغي له أن يتحرى ما هو أقرب إلى المصلحة والنفع للمسلمين. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18191/المشروع-للامام-بين-الاذان-والاقامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_927/nour_92707.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19058,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من حائل باعثها أحد الإخوة المستمعين ونص رسالته كما يلي: بسم الله الرحمن الرحيم، وبه نستعين، إلى سماحة الشيخ: عبد العزيز بن باز المحترم.السلام عليكم ورحمة الله وبركاته، بعد التحية ومزيد الاحترام.الحمد لله، والصلاة والسلام على أفضل أنبياء الله، سيدنا محمد ﷺ.أما بعد، فأنا علي حمود الرشيد المقيم بمنطقة حائل أرسل هذه الأسئلة راجيًا الرد منك عليها شخصيًا.السؤال الأول: أنا مصاب بكسر في أسفل الظهر، وعن هذا نتج العجز الكلي؛ لأنه مضى على الإصابة حتى الآن ثلاثون عامًا، ومع كل سنة يزيد العجز، ومع هذا فأنا مصاب بأمراض نفسية، فإذا جلست مدة لا تتجاوز ربع ساعة يخدر الجزء الأسفل ككل من ضمنها الأرجل فلا أستطيع السير إلا بعكازين، وينتج مع هذا توتر في الأعصاب ونزول العرق بغزارة من الأرجل، مما يزيد حالتي النفسية تعبًا.ومع هذا فأنا لا أستطيع الصلاة أداءً مع الجماعة في المسجد، فأصلي في البيت مع العلم بأنني ساكن في قرية لا يوجد في البيت المقيم به سخان كهربائي للماء، فهل يجوز لي أن أتيمم والحال كما ذكرت لكم؟ أرجو أن تتفضلوا بتوجيهي وإرشادي، جزاكم الله خيرًا.","title":"حكم العاجز عن صلاة الجماعة وعن تسخين الماء للوضوء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فنسأل الله للسائل الشفاء والعافية من كل سوء، وأن يكفر عنا وعنه السيئات، والحمد لله على كل حال، الله يقول: وَبَشِّرِ الصَّابِرِينَ  ۝ الَّذِينَ إِذَا أَصَابَتْهُمْ مُصِيبَةٌ قَالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ  ۝  أُوْلَئِكَ عَلَيْهِمْ صَلَوَاتٌ مِنْ رَبِّهِمْ وَرَحْمَةٌ وَأُوْلَئِكَ هُمُ الْمُهْتَدُونَ [البقرة:155-157]، وأنت يا أخي! عليك أن تتقي الله ما استطعت كما قال الله : فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. عليك أن تصلي بالماء، وأن تصلي حسب طاقتك قائمًا أو قاعدًا إن استطعت القيام ولو بعكازة صليت قائمًا، وإن لم تستطع ذلك صليت جالسًا، وليس عليك الذهاب إلى المسجد إذا كنت تعجز عن ذلك كما ذكرت في سؤالك. أما ما يتعلق بالماء فالواجب الوضوء بالماء، فإذا عجزت عن ذلك لشدة البرد وعدم وجود ما تسخن به فهذا عذر شرعي في استعمال التيمم، لكن من كان في القرية فهو لا يعجز في الحقيقة عن التسخين ولو بغير الكهرباء، يسخن بالحطب بالفحم بغير ذلك، فأنت ما دمت في القرية الواجب عليك أن تسخن الماء إذا شق عليك من جهة البرودة يسخن بالطرق الأخرى، بالنار التي تستعمل بالحطب والفحم وغير ذلك مما يوقد به النار، وليس لك عذر في التيمم مع وجود ما تسخن به الماء. أما لو كنت في صحراء في السفر ولم تستطع تسخين الماء فهذا عذر، فمن عجز عن الماء لبرودته وشدة الشتاء فإنه يتيمم، لكن أهل القرى والمدن في استطاعتهم تسخين الماء بأي وجه من الوجوه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18234/حكم-العاجز-عن-صلاة-الجماعة-وعن-تسخين-الماء-للوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_929/nour_92901.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19060,"question":"تقول: وأنا أصلي نسيت كم صليت في الركعتين الأولى من الصلاة، هل أقرأ التشهد، وأصلي سجود السهو، ثم أكمل الصلاة، أو لا أكمل، وبعدها أصلي سجود السهو؟ جزاكم الله خيرًا.","title":"حكم من شك في عدد الركعات التي صلاها","answer":"الجواب: إذا شك المصلي سواء كان رجلًا أو امرأة إذا شك هل هو في الثانية أو في الأولى من المغرب، أو الظهر، أو العصر، أو العشاء، أو الفجر؛ يجعلها الأولى، يبني على اليقين إذا شك المصلي رجلًا كان أو امرأة في الركعة التي هو فيها، هل هي الأولى أو الثانية؟ فإنه يبني على اليقين، ويجعلها الأولى، ثم يأتي بالثانية، ويجلس للتشهد الأول في المغرب، والعشاء، والظهر، والعصر، وفي الفجر يأتي بالثانية، ويجلس للتشهد حتى يكمل، ويسجد للسهو بعد ذلك في الفجر إذا انتهى من التشهد والدعاء سجد سجدتين للسهو، وسلم، وفي الظهر، والعصر، والمغرب، والعشاء؛ إذا كمل الصلاة سجد للسهو سجدتين قبل أن يسلم، وهكذا لو شك في الثانية، والثالثة، هل هي الثانية، أو الثالثة؛ يجعلها الثانية يجلس في التشهد الأول، ثم يكمل صلاته، وهكذا في الثالثة، والرابعة، لو شك هل هي الثالثة أو الرابعة؟ يجعلها الثالثة، ثم يأتي بالرابعة، وإذا فرغ من التشهد والدعاء سجد سجدة للسهو، ثم سلم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18237/حكم-من-شك-في-عدد-الركعات-التي-صلاها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_796/nour_79612.mp3","categories":["سجود السهو"]},{"id":19070,"question":"يقول: رجل مسافر لم يصل صلاة المغرب وعندما وصل إلى المدينة وجد الناس يصلون صلاة العشاء في المسجد، هل يصلي المغرب ثم يصلي معهم العشاء؟ أو ينوي بصلاته المغرب ويصلي معهم ثلاث ركعات ويسلم، أم ماذا يفعل؟","title":"حكم من وجد الناس يصلون العشاء ولم يصل المغرب","answer":"الجواب: يصلي المغرب ثم يصلي معهم العشاء، يصلي المغرب ثم يصلي معهم العشاء. نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/18260/حكم-من-وجد-الناس-يصلون-العشاء-ولم-يصل-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88325.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19091,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات من الرياض تقول: أختكم في الله (خ. أ. ع) أختنا لها عدد كبير من الأسئلة في سؤالها الأول تقول: سماحة الشيخ هل يجوز لمن يمنعه عمله من الصلاة مع الجماعة أن يصلي وحده إذا كان ليس معه أحد يصلي في العمل؟ أم يجب عليه ترك العمل؟","title":"حكم ترك صلاة الجماعة بسبب العمل","answer":"الجواب: هذا فيه تفصيل: إن كان عمله يمنعه من الجماعة؛ لأنه عمل خطير لو ذهب عنه لوقع الخطر كالحارس هذا له العذر يصلي في محل حراسته. أما إذا كان يستطيع أن يذهب ويرجع؛ لأنه لا خطر في ذلك، فإنه يذهب ويرجع لعمله كسائر الموظفين، إذا أذن الظهر خرجوا للصلاة ثم رجعوا لعملهم ليس في هذا شيء، ولا يجوز أن يصلي وحده، بل يجب أن يصلي مع المسلمين في مساجدهم ثم يرجع إلى عمله. أما من كان عمله يقتضي أن يلازم المحل وأن لا يتعدى المحل كالحارس مثلًا ونحوه الذين أعمالهم توجب لزومهم المكان الذي عينوا فيه؛ لأن فراقه يحصل به خلل من حراسة ونحوها، هؤلاء يصلون في محلهم، ويكون عذرًا لهم هذا العمل الذي وكل إليهم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18256/حكم-ترك-صلاة-الجماعة-بسبب-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_930/nour_93005.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19093,"question":"تسأل أختنا وتقول: ما حكم السهو في هذه المواضع قراءة الفاتحة في موضع التحيات أو العكس؟","title":"حكم من أتى بذكر في الصلاة في غير محله","answer":"الجواب: لا شيء في ذلك، الصلاة صحيحة. ولا حرج في ذلك، وإذا سجد للسهو يكون أفضل. إذا سجد للسهو إذا كان إمامًا أو منفردًا وسجد للسهو يكون أفضل، وإلا ما يلزمه. المقدم: وإلا لا يلزمه. الشيخ: لأنه قول مشروع في غير محله، قول مشروع في الصلاة لكن أتى به في غير محله، فإذا سجد للسهو كان ذلك أفضل، وإلا فلا حرج. نعم. المقدم: جزاكم الله خيرًا. قول: الله أكبر بدلًا من سمع الله لمن حمده؟ الشيخ: هذا سهو والصلاة صحيحة، وعلى الإمام إذا كان فعله الإمام سجود السهو أو المنفرد. أما إذا كان فعله المأموم قال: الله أكبر بدل ربنا ولك الحمد فلا عليه شيء؛ لأن المأموم تابع لإمامه، إذا كان دخل معه من أول الصلاة ليس عليه شيء، يتحمل عنه الإمام هذا السهو. لكن إذا كان المأموم سها في ما انفرد به إذا كان قد فاته بعض الصلاة أي: المسبوق، فهذا إذا سها في شيء وهو مسبوق مع إمامه، أو سلم مع إمامه ساهيًا ثم انتبه أو سها فيما انفرد به، هذا يسجد للسهو. وأما سهوه مع إمامه من أول الصلاة وهو معه من أول الصلاة، هذا يتحمله عنه الإمام. إذا سهو سهوًا لا يخل بالفعل مثل سها عن سبحان ربي الأعلى أو سبحان ربي العظيم، أو قال بدل ربنا ولك الحمد: سمع الله لمن حمده، أو الله أكبر، هذا لا يضر ولا سجود عليه لأنه تابع. أما إذا سها في الركوع أو في السجود لابد أن يأتي به، إذا سها كان يهوجس وركع إمامه وهو لم يركع ثم انتبه يركع ويلحق إمامه وهكذا في السجود هذه أركان لابد منها. لكن إذا سها في الأشياء التي هي تعتبر واجبات لكنها قولية، سها فيها المأموم فلا شيء عليه أو سها في التشهد الأول مثلاً ما أتى به فلا شيء عليه؛ لأنه تابع لإمامه. أما في الأركان لابد منها، التشهد الأخير ركن لابد يأتي به لو سها ولم يأت به مع الإمام ثم انتبه يأتي به قبل أن يسلم ثم يسلم بعد ذلك، أو انتبه بعد السلام يعود بنية الصلاة ويأتي بالتشهد ثم يسلم. نعم. المقدم: وبالنسبة للمنفرد أو المرأة في بيتها؟ الشيخ: عليهم سجود السهو إذا كان في مثل: (سبحان ربي الأعلى) في الواجبات يعني، إذا كان منفردًا رجل أو امرأة في صلاة منفردة إذا سها في الواجبات مثل ترك (سبحان ربي الأعلى) أو (سبحان ربي العظيم) في الركوع أو (ربنا ولك الحمد) سها عنها، يسجد للسهو قبل أن يسلم سجدتين أو ترك التشهد الأول قام إلى الثالثة ناسي التشهد الأول، هذا يسجد للسهو سجدتين قبل أن يسلم، كما فعله النبي عليه الصلاة والسلام. المقدم: وإذا قال ألفاظًا مكان ألفاظ أخرى. الشيخ: لا يضر. المقدم: لا يضر. الشيخ: لكن إن سجد وهي مشروعة فلا بأس مثل قرأ التحيات وهو جالس أو قرأ الحمد وهو جالس ناسي، إذا سجد للسهو يكون أفضل لا تبطل الصلاة ولا يجب، لأنه قول مشروع أتى به في غير موضعه. ليس بمنكر في الصلاة. نعم. المقدم: الحمد لله.","link":"https://binbaz.org.sa/fatwas/18262/حكم-من-اتى-بذكر-في-الصلاة-في-غير-محله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_930/nour_93007.mp3","categories":["سجود التلاوة والشكر","سجود السهو","الأدعية والأذكار"]},{"id":19110,"question":"يسأل أخونا سؤالًا آخر ويقول: في بعض الإخوة المؤمنين بعد فرض كل صلاة يقوم بعضهم بتقبيل أيادي البعض الآخر، فهل هذا صحيح أم لا؟","title":"حكم تقبيل الأيدي بعد الصلاة","answer":"الجواب: الأفضل عدم ذلك؛ لأنه ليس من عادة الصحابة  مع النبي ﷺ تقبيل يده، وإنما يفعله بعضهم نادرًا، فالأفضل في مثل هذا التأسي بالصحابة مع نبيهم عليه الصلاة والسلام، وهو المصافحة فقط، لكن لو فعل ذلك نادرًا وقليلًا مع أبيه، أو مع العالم السني صاحب السنة فلا بأس بذلك. لكن لا ينبغي أن يتخذ عادة؛ لأنه ليس من عادة الصحابة مع نبيهم عليه الصلاة والسلام، فالأفضل ترك التقبيل للأيدي والاكتفاء بالمصافحة، وإذا قدم من سفر عانق أخاه معانقة أو قبل ما بين عينيه لا بأس، أما اتخاذ تقبيل اليد عادة فلا ينبغي بل هو مكروه. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18279/حكم-تقبيل-الايدي-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_884/nour_88402.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19135,"question":"من المستمع محمد الطيب من السودان رسالة وضمنها سؤالين، في سؤاله الأول يقول: ما حكم الصلاة التي رفعت فيها رأسي من السجود قبل الإمام؟ وضحوا لي جزاكم الله خيرًا.","title":"حكم صلاة من رفع رأسه من السجود قبل الإمام","answer":"الجواب: إذا كنت رفعت رأسك قبل الإمام فعليك أن ترجع فتسجد، ثم ترفع بعده؛ فإن لم تفعل جاهلًا فلا شيء عليك، والصلاة صحيحة، أما إن كنت تعلم بحكم الشرع، وتعمدت هذا، ولم ترجع للسجود؛ فصلاتك باطلة تعيدها. أما إن كنت جاهلاً فالصلاة صحيحة، ولا تعد إلى ذلك، فإذا رفعت رأسك تحسب أن الإمام رفع ثم علمت أنه لم يرفع ارجع واسجد، ثم ارفع بعده. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18335/حكم-صلاة-من-رفع-راسه-من-السجود-قبل-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_798/nour_79803.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19247,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين المقيمين في المدينة المنورة يقول: إبراهيم عمر نصير سوداني، أخونا يسأل ويقول: أسألكم سماحة الشيخ عن شخص أدرك مع الإمام الركعتين الأخيرتين في صلاة العصر بعد انتهاء التشهد الأوسط وقيام الإمام للركعتين الأخيرتين كيف يكمل صلاته؟ أفيدونا جزاكم الله خيرًا.","title":"صلاة المسبوق","answer":"الجواب: إذا سلم الإمام فيقوم يأتي بركعتين، وتكون الركعتان الأخيرتان اللتان يقضيهما هما آخر صلاته، وأولها ما أدرك مع الإمام الركعتان اللتان أدركهما مع الإمام هما أول صلاته، فإذا تيسر أن يقرأ مع الفاتحة زيادة إذا كان الإمام أطال الوقوف فهو مشروع؛ لأنهما أول صلاته، والقاعدة أن ما أدرك مع الإمام هو أول صلاته، وما يقضيه هو آخر صلاته، لقول النبي ﷺ: ما أدركتم فصلوا وما فاتكم فأتموا، فالإتمام يكون هو القضاء، فالركعتان اللتان يقضيهما من فاتته الركعتان الأوليان تكونان هما آخر صلاته. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18440/صلاة-المسبوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_738/nour_73810.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19283,"question":"إنني أكثر من سجود السهو، هل في هذا شيء؟","title":"حكم الإكثار من سجود السهو","answer":"الجواب: لا ينبغي ذلك، السنة سجدتان فقط، ولو سها مائة مرة، لو سها الإنسان في صلاته مائة مرة، السنة له سجدتان فقط، لا يزيد على ذلك، ولا يجوز الزيادة على ذلك، فلو مثلًا قام عن التشهد الأول في الظهر أو العصر أو المغرب أو العشاء، قام عن التشهد ناسيًا، ثم مثلًا نسي التسبيح في الركوع: (سبحان ربي العظيم)، أو نسي التسبيح في السجود: (سبحان ربي الأعلى)، أو نسي (رب اغفر لي) بين السجدتين، أو نسي بعض التكبيرات عند قيامه أو قعوده، فإنه يكفيه سجدتان فقط عن الجميع كلها، وليس له أن يكرر سجدتين أخريين، لا، سجدتان كافيتان عن جميع السهو، هكذا فعل النبي ﷺ فإنه في بعض الأحيان عليه الصلاة والسلام سلم من ثنتين، وقام واستقبل الناس يظن أنه أكمل الصلاة، فنبه عليه الصلاة والسلام، فقام وكمل صلاته، ولم يسجد سوى سجدتين مع أنه سلم تسليمتين، وقام وذهب ورجع، فأتى بأشياء من الأعمال ساهيًا، ولكن سجد سجدتين فقط عليه الصلاة والسلام. نعم. المقدم: جزاكم الله خيرًا ! كأني فهمت سماحة الشيخ جانبًا آخر للسؤال. الشيخ: نعم. المقدم: وهو أنها تصلي الظهر مثلاً ثم تصلي سجود السهو، ولو لم تلاحظ أنها سهت، وتصلي العصر ثم تصلي سجود السهو، وهكذا؟ الشيخ: لا، هذا غلط، هذا ما يجوز، ما دام ما عندها سهو لا تسجد سجدتي السهو، الأوهام ما تصلح، الأوهام والوساوس ما تجوز، هذا من عمل الشيطان، إنما تسجد للسهو إذا علمت أنها سهت سهوًا يوجب سجود السهو، علمت أنها مثلًا تركت التشهد الأول وقامت ناسية، علمت أنها مثلًا نسيت (سبحان ربي الأعلى) في السجود، نسيت (سبحان ربي العظيم) في الركوع، فالأصح في هذا أنها تسجد للسهو في مثل هذا، وإن كان بعض أهل العلم لا يرى ذلك واجبًا، لكن الصحيح أن التشهد الأول واجب، وأن (سبحان ربي الأعلى) في السجود واجب، و(سبحان ربي العظيم) في الركوع واجب، ولو مرة واحدة، (رب اغفر لي) بين السجدتين واجب على الأصح، فمن تركه ساهيًا، سجد له، فلو اجتمعت هذه الأمور، سها في التشهد الأول، وسها في ترك التسبيح في الركوع أو في السجود يكفي سجدتان، والحمد لله. وهكذا لو مثلًا شك هل سجد سجدة أو سجدتين، فأتى بسجدة ثانية ليتيقن أنه سجد سجدتين فإنه يكفي سجدتان للسهو عن هذا وعن السهو الآخر. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18494/حكم-الاكثار-من-سجود-السهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_893/nour_89309.mp3","categories":["سجود السهو"]},{"id":19323,"question":"إمام سلم بعد أربع ركعات من صلاة رباعية، وظاهره أنه لم يخطئ في شيء، وتأخر المأموم في السلام بعد الإمام، فوجد الإمام سجد للسهو فسجد معه من غير السلام الأول؛ فأصبح سجود سهو الإمام بعد السلام وسجود سهو المأموم قبل السلام، فهل يعيد المأموم صلاته؟","title":"حكم عدم متابعة الإمام في التسليم إذا سجد للسهو","answer":"الجواب: لا يضر ذلك -الحمد لله- إذا سجد الإمام بعد السلام والمأموم بعد ما سلم وسجد معه لا يضر، لكن الأفضل أن يسلم المأموم، ثم يسجد هذا الأفضل. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18525/حكم-عدم-متابعة-الامام-في-التسليم-اذا-سجد-للسهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73919.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19342,"question":"بسم الله الرحمن الرحيم، سماحة الوالد البار عبد العزيز بن عبد الله بن باز ! أطال الله عمره وجعله ذخرًا للإسلام والمسلمين.السلام عليكم ورحمة الله وبركاته، وبعد:أطرح على سماحتكم هذه الأسئلة راجيًا من الله ثم منكم الإجابة عليها، صاحب هذه الرسالة هو أخونا من عسير عجب خلف الغنامي الروبي، في سؤاله الأول يقول: إذا أدركت الإمام راكعًا وركعت، فهل تكتب لي ركعة؟ أم أعيدها؟ علمًا بأن الرسول ﷺ يقول: لا صلاة لمن لم يقرأ بفاتحة الكتاب؟","title":"إدراك الركعة بإدراك الركوع","answer":"الجواب: هذه المسألة تنازع فيها أهل العلم، فمنهم من قال: تجزئه الركعة وهذا قول الأكثرين، وهو قول الأئمة الأربعة وغيرهم من أهل العلم، قالوا: لأن الرسول ﷺ سأله أبو بكرة الثقفي عن هذه القضية، فإن أبا بكرة جاء والإمام راكع فركع مع الصف ثم دخل في الصف، فلما سلم النبي ﷺ قال: من الذي فعل هذا؟ قال أبو بكرة: أنا يا رسول الله! فقال: زادك الله حرصًا ولا تعد، ولم يأمره بقضاء الركعة بل نهاه أن يعود إلى الركوع دون الصف، فالداخل ليس له أن يركع دون الصف بل يصبر حتى يتصل بالصف ويصف في الصف وليس له أن يركع دونه، ولم يأمره بقضاء الركعة؛ ولأنه معذور ما أدرك القراءة فكان معذورًا فيكون هذا الحديث مخصصًا للحديث الذي ذكره السائل، وهو قوله ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب، فهذا عام يستثنى منه الذي دخل والإمام راكع أو دخل مع الإمام ونسي قراءتها أو يعتقد أنها لا تجب عليه كما يقوله الجمهور: أنها لا تجب على المأموم، فهو مستثنى عند الجمهور. والصواب: أنها تجب على المأموم لكن إذا تركها ناسيًا أو تقليدًا لغيره لم يعرف الحكم الشرعي أو لم يدرك إلا الركوع كأن جاء عند الركوع أو وهو راكع فهذا معذور والصواب أنها تجزئه، هذا هو الصواب الذي عليه عامة أهل العلم وأكثر أهل العلم. وذهب بعضهم إلى أنها لا تجزئه، وبه قال البخاري رحمه الله وجماعة لهذا الحديث حديث: لا صلاة لمن لم يقرأ بفاتحة الكتاب، ولكنهم محجوجون بحديث أبي بكرة فهو معذور لعدم أمر النبي ﷺ له بالقضاء، فلو كان من فاتته القراءة يقضي وتجزئه الركعة لأمره عليه الصلاة والسلام بذلك، فإنه لا يجوز تأخير البيان عن وقت الحاجة وهذا وقت البيان، فلما سكت النبي ﷺ ولم يأمره بقضاء الركعة دل على أنه لا قضاء عليه وأن هذا مستثنى. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18559/ادراك-الركعة-بادراك-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_899/nour_89905.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19351,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: المحب في الله عبد الله عبد الرحمن سليمان رهفة، أخونا بدأ رسالته كما يلي: سماحة الشيخ عبد العزيز بن عبد الله بن باز حفظه الله.. آمين، السلام عليكم ورحمة الله وبركاته، وبعد:سؤالي هو: إنني جئت لأداء الصلاة المكتوبة وقت صلاة العصر فوجدت الإمام في التشهد الأخير على نهايته، وقدم معي بعض الرفاق يريدون ما أريد وطلبت منهم أن نقيم جماعة جديدة حيث الإمام يوشك أن يسلم من الصلاة فوافقوني، وأقمنا الصلاة جماعة أكثر من ثلاثة أو أربعة، ولكن الإمام وبعض الإخوة المصلين الرفاق بعد أداء الصلاة احتجوا علينا وطلبوا منا أداء الصلاة معهم حتى ولو كان الإمام في التشهد الأخير وفي نهايته؛ محتجين بالحديث الذي معناه: ما أدركتم فصلوا وما فاتكم فأتموا، فأخبرتهم أن معلوماتي في هذا الحديث هو أنه إذا جاء الرجل إلى المسجد فعليه بالسير بسكينة ووقار والاقتداء بالإمام فيما أدرك وقضاء ما لم يدرك.ومن جهتي أخبرتهم أن الذي لا يدرك الركعة الأخيرة من الفرض المكتوب فإنه يكون حاصلًا على ثواب الجماعة، وأما الصلاة فإنه لا يدركها، وأنه إذا أتمها فإنه يتمها منفردًا، أما نحن فقد -والحمد لله- أدركنا فضل الفريضة جماعة وفضل جماعة الصلاة، أرجو أن تبينوا لنا الأمر حسب أمر الله فيه ورسوله، والله نسأل لكم التوفيق وأن يرزقكم السداد وأن يجنبكم الخطأ والزلل، والسلام عليكم ورحمة الله وبركاته.","title":"حكم الدخول مع الجماعة لمن أتى في التشهد الأخير","answer":"الجواب: لا شك أن الرسول ﷺ قال هذا الكلام، يقول عليه الصلاة والسلام: إذا أتيتم الصلاة فأتوها وعليكم السكينة والوقار فما أدركتم فصلوا وما فاتكم فأتموا فمقتضى هذا الحديث: أن من جاء والإمام في التحيات أنه يدخل معه؛ لأنه أدركه في الصلاة لكنه لا يدرك فضل الجماعة إلا بركعة؛ لأن في الحديث الآخر: من أدرك ركعة من الصلاة فقد أدرك الصلاة. أما كونه يدخل معه حيثما وجده فهو ظاهر الحديث ولو في التحيات، فدخول الداخل مع الإمام في الصلاة قبل أن يسلم هذا هو الأفضل والأقرب لظاهر العموم، لكن لو صلوا جماعة ولم يدخلوا معه فلا أعلم في هذا حرجًا؛ لأن فضل الجماعة قد فاتهم، ولم يبق إلا جزء يسير من الصلاة، لكن تأدبا مع السنة، ومع ظاهر السنة احتياطًا للدين الذي أراه وأفتي به أن الأولى بالمؤمن إذا جاء في مثل هذه الحال، والإمام في التشهد أنه يدخل معه ولو كانوا عددًا، يدخلون معه ويجلسون ويقرؤون ما تيسر من التحيات التي تمكنهم، ثم ينهضون بعد السلام ويقضون ما عليهم، هذا هو الأحوط والأظهر؛ للعمل بعموم الحديث، لكن من صلى جماعة ولم يدخل مع الإمام لا أرى التشديد عليه؛ لأن له شبهة؛ لأن الصلاة قد انتهت، ولم يبق منها إلا اليسير، فلا وجه للتشديد في هذا. والله المستعان. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18550/حكم-الدخول-مع-الجماعة-لمن-اتى-في-التشهد-الاخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_899/nour_89901.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19365,"question":"من جيزان، المدرسة المتوسطة والثانوية المستمع أخونا حمود محمد علي هزازي يسأل ويقول: لقد سمعنا من أناس كثيرين قالوا: إذا جاء المسلم إلى المسجد للصلاة، ووجد بأن الصف مزدحم من جميع الجهات؛ فعليه أن يسحب أحد المصلين ليصلي معه، وسمعنا أناسًا آخرين قالوا: لا يجوز ذلك، بل يصلي وحده من غير أن يسحب أحدًا، نرجو من سماحتكم البيان في ذلك؟ جزاكم الله خيرًا.","title":"التصرف الصحيح لمن أتى المسجد والصفوف مكتملة","answer":"الجواب: هذه المسألة كما ذكر السائل بعض أهل العلم يرى أنه إذا كان الصف قد كمل، وليس فيه فرجة؛ فلا مانع من أن يسحب أحدهم، ويصف معه في الصف الذي بعده، وجاء في حديث ضعيف: ألا دخلت معهم أو اجتررت رجلًا ولكنه حديث ضعيف لا يعول عليه. والصواب القول الثاني: وأنه لا يسحب أحدًا؛ لأن ذلك يفتح فرجة في الصف، والرسول ﷺ أمر بسد الخلل، وسد الفرج، وتراص الصفوف؛ ولأنه تصرف في إنسان قد سبقه إلى هذا الفضل فلا ينبغي له، ولا يجوز له أن يتصرف فيه، ولكن يلتمس فرجة، أو يقف مع الإمام إذا تيسر عن يمين الإمام، فإن لم يتيسر ذلك انتظر حتى يأتي من يصف معه، فإن انتهت الصلاة، ولم يأت أحد صلى وحده لقول النبي ﷺ: لا صلاة لمنفرد خلف الصف ولأنه ﷺ رأى رجلاً يصلي خلف الصف وحده فأمره أن يعيد الصلاة. ولما صف أبو بكرة  خلف الصف حين الركوع أخبره النبي ﷺ بعد ذلك أن لا يعود إلى ذلك قال: زادك الله حرصًا ولا تعد فلا يجوز أن يصف وحده بل يصبر حتى يأتي من يصف معه، أو يجد فرجة في الصف، أو يقف عن يمين الإمام إذا تيسر ذلك، فإن فاتت الصلاة، ولم يتيسر له أحد فإنه يصلي وحده، وهو معذور، وله أجر الجماعة؛ لأنه ترك الدخول معه لعذر شرعي، فيكون له أجر الجماعة كالمريض ونحوه الذي لم يتيسر له الصلاة في الجماعة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18586/التصرف-الصحيح-لمن-اتى-المسجد-والصفوف-مكتملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_942/nour_94208.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19414,"question":"بقربي المسجد، ولكنه بدون إمام، فهل يجب علي أن أصلي فيه، وإذا كان لهذا المسجد إمام، فهل علي إثم إن صليت في بيتي؟","title":"هل يأثم من صلى في بيته؟","answer":"الجواب: الواجب الصلاة في الجماعة، وليس لك أن تصلي في بيتك، وإن كان المسجد ليس فيه إمام، يقدمون أحدهم يقدمون أقرأهم وأفضلهم يصلي بهم، وليس لك أن تصلي في البيت، وإذا قدموك لأنك أقرؤهم وأفضلهم؛ فصل بهم، ولا يجوز لك ولا لغيرك الصلاة في البيت وترك الجماعة؛ لقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر، والعذر: هو المرض والخوف ونحوهما مما يمنع الإنسان من الذهاب إلى المسجد. وقد ثبت عنه ﷺ أنه جاءه رجل أعمى جاء إلى النبي ﷺ رجل أعمى يستأذن أن يصلي في بيته، وذكر أنه ليس له قائد يقوده فقال له النبي ﷺ: هل تسمع النداء بالصلاة؟ سأله النبي ﷺ: هل تسمع النداء يعني الأذان؟ قال: نعم، قال: فأجب فإذا كان الأعمى الذي ليس له قائد يؤمر بالإجابة فكيف بغيره ممن عافاهم الله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18643/هل-ياثم-من-صلى-في-بيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_740/nour_74010.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19432,"question":"إذا أصيب الإمام برعاف وكان باب المسجد خلف المصلين، فهل يقطع صفوفهم لكي يخرج من المصلى، أو ينتظر حتى يتموا صلاتهم؟","title":"ما يفعله الإمام إذا أصابه رعاف","answer":"الجواب: إذا أصابه رعاف، أو انتقض وضوؤه؛ فإنه يستنيب على الراجح، يستخلف من يكمل بالناس الصلاة، ويخرج إذا استطاع الخروج؛ ولو بشق الصفوف معذور، فإن لم يستطع جلس حتى يتيسر له الخروج، ويتحفظ حتى لا يقطر الدم في المسجد، ولا بأس عليه، فليجلس إذا لم يتيسر له الخروج، وإن خرج بشق الصفوف فلا بأس عليه والحمد لله، لكن الصواب أنه يستخلف حتى لا يعطلهم، يستخلف من يصلي بهم كما فعل عمر  فإنه لما طعن استخلف عبد الرحمن بن عوف وصلى بهم، كمل بالناس الصلاة، فهذا هو الصواب أنه يستخلف ولو سبقه الحدث، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18676/ما-يفعله-الامام-اذا-اصابه-رعاف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_944/nour_94402.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19434,"question":"إذا كان الراديو مفتوح وهم يصلون المغرب أو العشاء جماعة، هل يجوز أن أصلي بعدهم؟الشيخ: كيف؟المقدم: يقول: إذا كان الراديو مفتوح لصلاة المغرب أو العشاء هل يجوز أن أصلي بعدهم، يأتم بهم؟","title":"حكم الائتمام بصوت الإمام في الراديو","answer":"الجواب: ما نعلم في هذا شيء، ولو كان الراديو مفتوح يعني: قصده مسجل يسجل صلاته وإلا يسمع الصوت فيه؟\nالمقدم: يسمع الصوت ، يسمع صوت المصلي هل يقتدي بالإمام وهو في الراديو مثلاً؟\nالشيخ: هذا فيه تفصيل: إن كان مقصوده أنه يصلي بموجب الراديو الذي ينقل صوت الإمام من مسجد آخر هذا لا يصلي.\nأما إذا كان قصده إنه يشوش قد يشوش عليهم الراديو يتحدث الراديو بكلام أو مفتوح هذا ينبغي إغلاقه حتى لا يشوش عليهم وهم يصلون.\nأما إذا كان المقصود أن يأتم بالراديو ويصلي خلف الراديو الذي ينقل منه صلاة الحرم أو صلاة المدينة أو صلاة أي مسجد، هذا لا؛ لأنه قد ينقطع فتختل العبادة، ولأنه ليس مع الصفوف في المسجد، بل هو بعيد عنهم، فليس له أن يقتدي بالراديو، بل يصلون صلاة مستقلة ليس لها تعلق بالراديو، هذا هو الواجب.","link":"https://binbaz.org.sa/fatwas/18666/حكم-الاىتمام-بصوت-الامام-في-الراديو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_937/nour_93709.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19473,"question":"من ضواحي الباحة هذه رسالة بعث بها الأخ عائض محسن حاضر الغامدي، أخونا عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة يسأل ويقول: هل من كبر تكبيرة الإحرام قبل أن يسلم الإمام يدرك الجماعة أم لا؟ جزاكم الله خيرًا.","title":"بم تدرك صلاة الجماعة","answer":"الجواب: قد دلت السنة سنة النبي عليه الصلاة والسلام أن الصلاة في الجماعة إنما تدرك بالركعة، قال عليه الصلاة والسلام: من أدرك ركعة من الصلاة؛ فقد أدرك الصلاة ففضل الجماعة يدرك بإدراك الركعة فأكثر، لكن إذا كان له عذر بسبب ذلك فاتته الصلاة؛ فإن أجر الجماعة يحصل له، وإن لم يصل في الجماعة كالمريض الذي حبسه المرض ثم وجد نشاطًا فرَجَا أن يدرك الجماعة فلم يدركها، وكإنسان توجه إلى الجماعة فحدث به حادث يمنعه من ذلك كالغائط أو البول، فذهب يتوضأ أو ما أشبهه من الأعذار الشرعية فهذا يُرجى له فضل الجماعة إذا لم يفرط، لكن من جاء والإمام في التشهد فإنه يدخل معه، وله الفضل في ذلك لقوله ﷺ: ما أدركتم فصلوا، وما فاتكم فأتموا، فهذا عام يعم ما أدركه المؤمن من صلاة الإمام ولو التشهد، فإنه يدخل معه فإذا سلم قام وقضى ما فاته، ولكنه لا يدرك فضل الجماعة إلا بإدراك الركعة كما تقدم. والواجب على المؤمن أن يسارع إلى الصلاة، وأن يبادر بعد سماع الأذان حتى يدرك الصلاة كاملة، وحتى يؤدي ما شرع الله قبلها من الراتبة كراتبة الظهر، أو ما يسر الله من الركعات قبل العصر، أو المغرب، أو العشاء. هكذا ينبغي للمؤمن أن يبادر ويسارع إلى هذه الفريضة العظيمة عند سماع الأذان، أو قبل الأذان عند قرب الأذان، حتى يتمكن من الوصول إلى المسجد بهدوء، وحتى يصلي ما يسر الله له قبل الصلاة، هذا هو الذي ينبغي للمؤمن، بل هو واجب عليه حتى لا تفوته الجماعة، وهكذا صلاة الفجر.\nالمقصود أنه يجب عليه أن يبادر ويسارع في الوقت الذي يضمن إدراكه الصلاة من أولها، وإذا تيسر له فضل وقت حتى يصلي قبل الصلاة ما يسر الله من تحية المسجد، أو الراتبة فهذا خير عظيم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18724/بم-تدرك-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_945/nour_94503.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19474,"question":"المستمعة (أ. م. أ) من الخرطوم تسأل أيضًا وتقول: هل تصح الصلاة خلف من لم نعرف حاله؟","title":"حكم الصلاة خلف من لم تعرف حاله","answer":"الجواب: نعم، من كان ظاهره الإسلام، ويؤم المسلمين؛ فإنها تصح الصلاة خلفه حتى يتبين منه ما يدل على أنه كافر لا تصح الصلاة خلفه، ولو بان أنه فاسق فإن الصلاة خلف الفاسق صحيحة في أصح قولي العلماء، لكن متى بان أنه كافر عند ذلك لا يصلى خلفه، ويمنع من الإمامة، ولا تصح الصلاة خلفه، كالذي يظهر أنه منافق يسب الدين، ويستهزئ بالدين، أو يسب الرسول عليه الصلاة والسلام، أو ما أشبه ذلك؛ مما يوجب ردته عن الإسلام، أو يظهر منه أنه أيضًا يعبد أصحاب القبور، ويستغيث بهم، وينذر لهم، وما أشبه ذلك مما يدل على ردته وكفره نسأل الله السلامة. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18722/حكم-الصلاة-خلف-من-لم-تعرف-حاله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_945/nour_94502.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19494,"question":"أخونا يسأل ويقول: رجل دخل المسجد ليصلي المغرب فوجد رجلًا يصلي فالتحق به فإذا به يصلي العصر، فماذا يفعل الرجل الذي يصلي المغرب، هل يكمل معه أم ينفصل عنه في الركعة الثالثة؟","title":"حكم اختلاف الإمام والمأموم في النية وعدد ركعات الصلاة","answer":"الجواب: إذا دخل المسلم مع إنسان يصلي صلاة رباعية وهو قصده المغرب بأن دخل معه يظنه يصلي المغرب فصار يصلي العشاء كما قد يقع ذلك في الأسفار، وفي هطلة الأمطار، فإنه إذا قام الإمام إلى الرابعة يجلس الثالثة، ويقرأ التشهد، ويدعو حتى يسلم إمامه، ثم يسلم معه وتجزئه؛ لقوله عليه الصلاة والسلام: إنما الأعمال بالنيات هذا له نيته، وهذا له نيته، إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى هكذا قال المصطفى عليه الصلاة والسلام. وهكذا لو صلى معه العشاء وهو ناوي المغرب، وهو مسافر الذي يصلي العشاء فسلم من ثنتين فإنه يقوم ويصلي الثالثة، وصلاته صحيحة له نيته وذاك له نيته، هذا نوى المغرب وهي ثلاث، وهذا نوى العشاء مقصورة لأنه مسافر، وسلم من ثنتين، فإذا سلم قام وأتى بالثالثة الذي يصلي المغرب. وهكذا لو صلى الظهر خلف من يصلي العصر جاء وهم يصلون في وقت الجمع في السفر - مثلًا - فظن أنهم يصلون الظهر فصاروا يصلون العصر وهو يصلي الظهر؛ فإن صلاته صحيحة، وله نيته، ولهم نيتهم، هذا هو الصواب، الأعمال بالنيات. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18746/حكم-اختلاف-الامام-والماموم-في-النية-وعدد-ركعات-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_945/nour_94512.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19506,"question":"إذا جاء الرجل إلى المسجد والإمام يقرأ هل يكبر ويستمع؟ أم يقرأ دعاء الاستفتاح ثم الفاتحة ثم يستمع؟","title":"المشروع لمن أدرك الإمام حال القراءة","answer":"الجواب: إذا كبر يستمع، لكن يقرأ الفاتحة، أما الاستفتاح مستحب يسقط، لكن يقرأ الفاتحة، ثم ينصت إذا كان الإمام ما يسكت. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18750/المشروع-لمن-ادرك-الامام-حال-القراءة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93929.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19522,"question":"يقول هذا السائل: ما حكم الشرع في نظركم - سماحة الشيخ - في الشخص وهو في الصلاة، وحصل عليه سجود سهو قبل السلام، ولكنه نسي أن يأتي بهذا، ولم يتذكر إلا بعد أن خرج من الصلاة؟","title":"حكم من نسي سجود السهو","answer":"الجواب: يسجد للسهو ولو في بيته، يسجد للسهو ولو في بيته، وإن كان إمامًا رجع وسجد بالحاضرين. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18783/حكم-من-نسي-سجود-السهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94620.mp3","categories":["سجود السهو"]},{"id":19563,"question":"يقول -يا سماحة الشيخ-: دخلت المسجد فلم أجد لي مكانًا في الصف، وانتظرت مدة فلم يحضر أحد هل أصلي منفردًا خلف الصف؟","title":"حكم من أتى المسجد ولم يجد فرجة له في الصف","answer":"الجواب: لا تصل منفردًا، بل تقدم وصل مع الإمام عن يمينه، وإلا قارب بين الصف حتى تجد الفرجة، فإن لم تجد فاصبر حتى يسلم الإمام ثم صل وحدك. نعم.","link":"https://binbaz.org.sa/fatwas/18821/حكم-من-اتى-المسجد-ولم-يجد-فرجة-له-في-الصف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94713.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19564,"question":"يقول هذا السائل: دخلت المسجد، فوجدت المصلين في التشهد الأخير، هل أجلس معهم؟ أم أنتظر جماعة أخرى؟","title":"دخل المسجد، فوجد المصلين في التشهد الأخير، هل يجلس معهم؟","answer":"الجواب: إذا دخلت فاجلس معهم، النبي ﷺ قال: ما أدركتم فصلوا، وما فاتكم فأتموا فإذا جئت وهم جالسون للتشهد فاجلس معهم، وبعد السلام تقوم وتقضي الصلاة. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18824/دخل-المسجد-فوجد-المصلين-في-التشهد-الاخير-هل-يجلس-معهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94715.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19578,"question":"تقول السائلة: ما كيفية سجود السهو؟","title":"كيفية سجود السهو","answer":"الجواب: سجود السهو مثل سجود الصلاة، سجدتين مثل سجود الصلاة سواء. نعم.","link":"https://binbaz.org.sa/fatwas/18839/كيفية-سجود-السهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94903.mp3","categories":["سجود السهو"]},{"id":19609,"question":"هل من تسوية الصفوف في الصلاة أن يلصق المصلي قدمه بقدم من بجواره؟","title":"حكم إلصاق القدم بالقدم عند المصافة في الصلاة","answer":"الجواب: نعم، لا بد أن يسدوا الخلل، قال الصحابة: كان أحدنا يلصق قدمه بقدم صاحبه فالسنة إلصاق القدم بالقدم حتى لا تبقى فرجة، لكن من دون أذى لا يؤذي جاره، لكن يلصق قدمه بقدمه حتى لا يكون بينهم فرج. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18879/حكم-الصاق-القدم-بالقدم-عند-المصافة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94813.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19629,"question":"يقول يا سماحة الشيخ! هل تعتبر الصلاة بعد صلاة الجماعة الأولى مع عدة أشخاص يزيدون عن الثلاثة، هل تعتبر صلاة جماعة إذا صلينا بعد الجماعة الأولى؟","title":"الجماعة الثانية وحصول الأجر فيها","answer":"الجواب: إذا حصلت جماعة أخرى بعد الجماعة الأولى، وصليت معهم فأنت مأجور، وإذا كان الواحد وصليت معه حتى يحصل له الجماعة فأنت مأجور، والحمد لله.","link":"https://binbaz.org.sa/fatwas/18896/الجماعة-الثانية-وحصول-الاجر-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94827.mp3","categories":["صلاة الجماعة","سجود السهو"]},{"id":19645,"question":"أخيرًا يقول هذا السائل: إبراهيم من اليمن، ما هو حكم الصلاة خلف الصف منفردًا؟ نرجو من سماحتكم القول الراجح في ذلك مأجورين.","title":"ما هو حكم الصلاة خلف الصف منفردًا؟","answer":"الجواب: الصلاة خلف الصف منفردًا لا تصح، يقول النبي ﷺ: لا صلاة لمنفرد خلف الصف فالذي يصلي وحده خلف الصف صلاته باطلة، بل عليه أن يجتهد حتى يجد فرجة أو يقف عن يمين الإمام، أو ينتظر حتى يأتي أحد. نعم. المقدم: شكر الله لكم يا سماحة الشيخ وبارك الله فيكم وفي علمكم ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/18929/ما-هو-حكم-الصلاة-خلف-الصف-منفردا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94934.mp3","categories":["صلاة الجماعة","سجود السهو"]}]
